(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]=m["moe"]||{};d["appendix"]=[{"id":"ap-moe-router-terms","title":"MoE 路由术语速查","summary":"覆盖 top-k 门控、路由分数归一化、专家容量因子、token 丢弃与溢出重路由、负载均衡辅助损失在推理侧的残留影响，以及 Blackwell 上路由 kernel 的 warp 级归约与 SM100 张量核流水线衔接方式。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-1\">一 · 条目的定义边界：什么算“路由术语”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-2\">二 · 分类维度一：选择机制与归一化位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-3\">三 · 分类维度二：容量约束与溢出策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-4\">四 · 分类维度三：均衡手段与其推理侧残留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-5\">五 · 分类维度四：kernel 实现层与 Blackwell 衔接点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-6\">六 · 速查表结构与相邻概念的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-7\">七 · 路由条目的边界条件与失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-8\">八 · 速查表的字段口径与读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-9\">九 · 阈值：k、容量因子与单 warp 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-10\">十 · 归一化位置：一个二选一的口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-11\">十一 · 溢出策略：丢弃与重路由的正确性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-12\">十二 · Blackwell 实现要点：归约与流水衔接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-13\">十三 · 三个高频踩坑的对照口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-14\">十四 · 阈值不是常数，是随 batch 形状漂移的区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-15\">十五 · 容量因子 1.0–1.25 的边界与低于 1.0 的系统性丢弃</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-16\">十六 · k≤4 的单 warp 归约窗口与流水衔接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-17\">十七 · 归一化位置的重复执行是幅值级故障</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-18\">十八 · 同分 logits 与不稳定排序引发的不可复现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-19\">十九 · 把阈值变成可观测量的工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-20\">二十 · 容量因子、丢弃率与路由归约的工程边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-21\">二十一 · 踩坑清单：三类高频故障的机制定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-22\">二十二 · 检查顺序：从路由表到 GEMM 流水</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-23\">二十三 · 容量与丢弃的判定：用实测丢弃率而非训练损失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-24\">二十四 · 回滚方案：把路由配置做成可切换的版本化对象</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-25\">二十五 · 踩坑清单、检查顺序与回滚方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-26\">二十六 · 上游依赖：路由术语如何被量化与并行条目反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-27\">二十七 · 下游影响：从路由表到分组 GEMM 与 combine 的连锁代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-28\">二十八 · 横向关系：与框架选型、剖析工具链的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-29\">二十九 · 在全书中的位置：路由作为容量规划的第一变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-30\">三十 · 接口契约：术语表如何变成可执行的检查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-router-terms-sec-31\">三十一 · 路由参数的上下游耦合与失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-moe-router-terms\"><svg style=\"max-width:510px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 509.6 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"427.6\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：MoE 路由术语速查</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">覆盖 top-k 门控、路由分数归一化、专家容量因子、token 丢弃与</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">溢出重…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-moe-router-terms-sec-1\">一 · 条目的定义边界：什么算“路由术语”</h3>\n<p>《MoE 路由术语速查》收录的不是 MoE 的全部概念，而是“一个 token 从进入路由器到被派发到专家 GEMM 之前”这一段的可配置项与可观测项。判定一个词是否入表，用三条边界：它必须改变 token 到专家的映射结果（选择机制、归一化、溢出策略）；或改变每个专家实际接收的 token 数量上界（容量因子）；或改变这段映射在硬件上的执行方式与延迟（warp 级归约、排序网络、与 MMA 流水衔接）。三条都不满足的，归入相邻条目——例如专家并行与 All-to-All 讲的是映射确定之后的通信拓扑，分组 GEMM 与 tcgen05 讲的是映射确定之后的矩阵流水，二者都以“路由结果已定”为前提，因此不在本表展开。</p>\n<p>按此边界，本表的核心条目是：top-k 门控、路由分数归一化、专家容量因子、token 丢弃、溢出重路由、负载均衡辅助损失的推理侧残留、warp 级归约。它们共同构成一个五元组：<em>(选择, 归一化, 容量, 溢出, 实现)</em>。任何一次推理服务的路由行为，都可以用这五个坐标唯一描述；反过来，任何一个路由故障，也必然落在其中一个坐标上。</p>\n<p>代价视角先立一个基线：k 是容量规划的第一变量。k 从 1 增至 2 或 4，每 token 的专家 GEMM 工作量与 All-to-All 通信量近似线性抬升，而路由 kernel 自身的归约开销增长远小于此——这意味着路由段的算力占比随 k 增大而下降，但 dispatch 段的带宽占比随 k 增大而上升。工程判断因此不是“路由快不快”，而是“路由结果表产出得够不够早，能否赶在分组 GEMM 流水启动窗口之前”。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-2\">二 · 分类维度一：选择机制与归一化位置</h3>\n<p>选择机制区分 top-k 与 expert-choice。top-k 是 token 主动挑专家：对每个 token 的路由 logits 取前 k 个，仅这些专家参与该 token 的前向计算，k 通常取 1、2 或 4。expert-choice 反向行之，由专家挑 token，天然带容量约束，但推理侧因 batch 组合变化会导致同一 token 在不同请求中被不同专家选中，可复现性差。本表以 top-k 为主轴，expert-choice 作为对照条目列出其容量语义差异。</p>\n<p>归一化位置是第二个维度，也是最容易被误配的一维。定义上，路由分数归一化指对选中专家的 gate 值做 softmax 或除以求和，使权重和为 1。关键在于“位置”而非“是否”：归一化可以放在专家 GEMM 之前（把权重预先乘进激活），也可以放在 combine 阶段（对专家输出加权求和时归一）。二者只应择一。若两处各做一次，权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非明显报错——这是本表标注为“静默数值错误”的典型条目。</p>\n<div class=\"formula\">$$ w_i = \\frac{\\exp(z_i)}{\\sum_{j \\in \\mathcal{S}(x)} \\exp(z_j)},\\quad \\sum_{i \\in \\mathcal{S}(x)} w_i = 1 $$</div>\n<p>其中 $\\mathcal{S}(x)$ 为 token $x$ 选中的专家集合，$z_i$ 为路由 logits。该式成立的前提是求和只在选中集合内进行；若实现里对全专家做 softmax 再取 top-k，权重和小于 1，等价于对未选中专家做了隐式零填充，数值上并非错误但会系统性压低激活幅值。速查表为此单列一列“归一化域”，取值为“选中集内 / 全集”。</p>\n<p>具体例子：某服务把归一化放在 GEMM 前，又在 combine kernel 里复用了同一段 softmax 代码，两处叠加后 k=2 时权重和被平方，热专家输出被放大，冷专家被压缩，端到端表现为生成文本的 logits 整体偏移。定位手段不是看路由分布，而是直接比对 combine 前后的权重和是否为 1。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-3\">三 · 分类维度二：容量约束与溢出策略</h3>\n<p>专家容量因子定义为每专家 token 上限与平均负载之比：</p>\n<div class=\"formula\">$$ C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E} $$</div>\n<p>其中 $T$ 为 batch 内 token 数、$E$ 为专家数。它直接决定分组 GEMM 的 M 维上界与激活缓冲区大小，因此不是一个“调度参数”而是“显存与算力形状参数”。推理常用容量因子 1.0–1.25；低于 1.0 会系统性丢弃，因为平均负载本身已等于 $Tk/E$，容量因子小于 1 意味着上限低于均值，必然有 token 无处可去。</p>\n<p>溢出策略分两支。token 丢弃指 token 被路由到的专家已满容量时被跳过，其输出按零或残差直通处理；溢出重路由则把溢出 token 改派到次优专家并重算权重。二者在推理侧的代价结构完全不同：丢弃是零额外 kernel 分支但引入数值正确性代价（该 token 的专家贡献缺失）；重路由需要一次额外的路由查表与权重重算，增加 dispatch 段的分支与不规则访存，但保住了 k 个专家的有效贡献。速查表为此设“溢出策略”列，取值为“丢弃 / 重路由 / 无容量约束”，并单列“数值正确性代价”说明丢弃是否可接受取决于该 token 是否处于残差直通路径。</p>\n<p>工程判断：容量因子与溢出策略必须成对配置。容量因子 1.0 配丢弃，等于把“平均负载”当作硬上限，长序列或领域偏移输入下热专家必然打满；容量因子 1.25 配重路由，则把溢出成本转移到 dispatch 段的分支延迟上。具体例子：某长序列请求 batch 内 $T$ 较大，$Tk/E$ 抬高，容量因子仍取 1.0，热专家在序列后半段持续溢出，丢弃率上升而训练损失无任何变化——这正是本表要求“以实测丢弃率而非训练损失判断是否调容量因子”的原因。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-4\">四 · 分类维度三：均衡手段与其推理侧残留</h3>\n<p>均衡手段在表中分两类：辅助损失与路由器 z-loss。负载均衡辅助损失在训练时把 token 分配推向均匀，但它不是推理期的运行时保证。推理侧残留影响体现为路由分布仍带训练期偏置：热专家在长序列或特定领域输入上更易打满容量。因此速查表把“辅助损失”条目的“推理侧是否可关闭”标为“可关闭但不建议单独关闭”，并把它的影响阶段标为“路由（间接）”，而非“dispatch”。</p>\n<p>这里必须区分“训练期均匀”与“推理期均匀”。辅助损失优化的是训练分布上的期望分配，推理请求的分布是另一个分布；两者之间的偏移量无法从训练损失读出。可观测的替代指标是单专家打满率与实测丢弃率。失败模式很具体：训练时辅助损失把路由压均匀，推理直接沿用同一路由器却不监控单专家打满率，长序列输入下热专家溢出丢弃，输出质量在无告警情况下劣化。表中为此设“监控项”一列，值为“单专家打满率、丢弃率、权重和偏差”。</p>\n<p>z-loss 作用于 logits 尺度而非分配均匀性，其推理侧残留是 logits 幅值被约束，间接影响归一化后的权重尖锐度。它与辅助损失不是替代关系：前者控幅值，后者控分配。速查表将二者分列，避免工程上把“加了 z-loss”误当作“负载已均衡”。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-5\">五 · 分类维度四：kernel 实现层与 Blackwell 衔接点</h3>\n<p>实现层维度收录三项：warp 级归约、排序网络、与 MMA 流水衔接。Blackwell 上路由 kernel 的 warp 级归约指在单个 warp 内用 shuffle 完成 top-k 比较与分数求和，避免跨 warp 的 shared memory 往返。工程阈值明确：k≤4 时通常单 warp 可完成；k 更大需多轮 shuffle 或跨 warp 合并。k 取 1、2、4 正好落在单 warp 区间内，这也是 k 的常见取值在实现层的一个约束来源。</p>\n<p>衔接点是本维度最关键的工程事实：归约结果需写入供 SM100 张量核流水线消费的 token 排序/偏移表，归约延迟必须短于分组 GEMM 的流水启动窗口。也就是说，路由 kernel 的绝对延迟不是指标，它与 GEMM 启动窗口的相对关系才是。若归约延迟超过该窗口，张量核流水线出现气泡，此时即使路由 kernel 本身“很快”，端到端吞吐仍下降。速查表为此设“Blackwell 实现要点”列，取值为“warp 归约 / TMEM 衔接 / 排序网络”，并要求标注该条目是否位于流水启动的关键路径上。</p>\n<p>排序网络条目对应 top-k 比较的稳定性问题。top-k 排序用不稳定比较会使同分 token 路由抖动，引发 batch 间输出不一致；相同输入在不同 batch 组合下路由到不同专家，造成服务端输出不可复现、难以定位。这是实现层维度里唯一直接影响可复现性的条目，其代价不是延迟而是可观测性。具体例子：两个 logits 完全相等的 token 在同一 batch 内被不稳定排序分到不同专家，单请求测试通过，混合 batch 压测时输出漂移，排查方向被误导到数值精度而非排序稳定性。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-6\">六 · 速查表结构与相邻概念的分界</h3>\n<p>表结构固定为八列：术语名、数学定义、推理侧是否可关闭、影响的 kernel 阶段（路由/dispatch/GEMM/combine）、关键参数（k、capacity_factor）、数值正确性代价、Blackwell 实现要点、监控项。前七列保证一个条目可被工程侧直接配置，第八列保证它可被运维侧观测。缺任一列，条目就退化为“名词解释”而非“速查项”。</p>\n<table class=\"mini\"><thead><tr><th>条目</th><th>影响阶段</th><th>可关闭</th><th>关键参数</th><th>正确性代价</th></tr></thead><tbody><tr><td>top-k 门控</td><td>路由</td><td>否</td><td>k=1/2/4</td><td>k 减小降低覆盖</td></tr><tr><td>分数归一化</td><td>GEMM 前或 combine</td><td>否（择一）</td><td>归一化域</td><td>重复归一化致幅值偏移</td></tr><tr><td>容量因子</td><td>dispatch/GEMM</td><td>否</td><td>1.0–1.25</td><td>&lt;1.0 系统性丢弃</td></tr><tr><td>token 丢弃</td><td>dispatch</td><td>是（改重路由）</td><td>—</td><td>专家贡献缺失</td></tr><tr><td>溢出重路由</td><td>路由/dispatch</td><td>是（改丢弃）</td><td>次优专家数</td><td>权重重算偏差</td></tr><tr><td>辅助损失残留</td><td>路由（间接）</td><td>不建议</td><td>—</td><td>热专家打满</td></tr><tr><td>warp 级归约</td><td>路由</td><td>否</td><td>k≤4</td><td>超窗口致流水气泡</td></tr></tbody></table>\n<p>与相邻条目的分界用一句话各自指路：容量因子与丢弃代价条目讲的是本表“容量约束”维度的代价量化；专家并行与 All-to-All 讲映射确定后的通信；分组 GEMM 与 tcgen05 讲映射确定后的矩阵形状消费；量化后路由漂移讲的是 logits 数值变化如何反馈到本表的选择机制。本表只负责“映射本身”的定义与分类，不重复上述任何一条的展开。</p>\n<p>最后一个工程判断落在实现层：路由 kernel 的正确性验收不应只看单请求输出，而应同时检查三项——combine 前后权重和是否为 1、同分 logits 在混合 batch 下是否路由一致、归约延迟是否落在分组 GEMM 流水启动窗口内。三项中任一不满足，条目配置即视为未闭环，无论其吞吐数字多好看。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-7\">七 · 路由条目的边界条件与失效面</h3>\n<p>速查表里每个条目都必须带一列“推理侧是否可关闭”，因为可关闭性直接决定它是不是容量规划的变量。top-k 与容量因子不可关闭：k 取 1、2 或 4 时，每 token 的专家 GEMM 工作量与 All-to-All 通信量随 k 线性抬升，容量因子则通过 <span class=\"formula\">$$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$$</span> 直接钉死分组 GEMM 的 M 维上界与激活缓冲区大小，二者共同构成显存与带宽预算的硬边界。归一化位置、溢出策略、均衡手段则属于“可配置但不可省略”的一类——省略归一化会让专家加权和随 k 与 logits 尺度漂移，把溢出策略从丢弃换成重路由会引入额外 kernel 分支与次优专家重算，这些都不是性能开关而是数值契约。</p>\n<p>失效条件集中在三处，且都不报错。其一，训练期辅助损失把路由压均匀，推理沿用同一路由器却不监控单专家打满率，长序列或特定领域输入下热专家溢出丢弃，输出质量静默劣化；判断依据应是实测丢弃率而非训练损失。其二，归一化在 GEMM 前与 combine 阶段各做一次，权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非异常。其三，top-k 用不稳定比较或未处理同分 logits，相同输入在不同 batch 组合下路由到不同专家，服务端输出不可复现。三者的共同点是：错误发生在 dispatch 与 combine 之间，被下游采样掩盖。</p>\n<p>系统代价要按 kernel 阶段拆开看。路由阶段，k≤4 时单 warp 用 shuffle 完成 top-k 比较与分数求和即可，避免 shared memory 往返；k 更大需多轮 shuffle 或跨 warp 合并，归约延迟一旦超过分组 GEMM 的流水启动窗口，SM100 张量核就出现空转，这段代价不计入 GEMM 利用率却真实吃掉吞吐。dispatch 阶段，容量因子低于 1.0 会系统性丢弃，1.0–1.25 是推理常用区间，因子越大激活缓冲区越大、显存越紧。combine 阶段重复归一化不增加算力，却让整条链路的数值正确性失去可验证性。工程上应把“影响的 kernel 阶段”与“数值正确性代价”作为速查表的两列并排，让读者一眼看出哪个条目关掉只是慢、哪个条目关掉是错。</p>\n<table class=\"mini\"><thead><tr><th>条目</th><th>推理侧可关闭</th><th>失效表现</th><th>代价落点</th></tr></thead><tbody><tr><td>top-k 门控</td><td>否</td><td>k 抬升线性增通信</td><td>GEMM/All-to-All</td></tr><tr><td>分数归一化</td><td>否（位置可定）</td><td>logits 整体偏移</td><td>combine</td></tr><tr><td>容量因子</td><td>否</td><td>&lt;1.0 系统性丢弃</td><td>激活缓冲区</td></tr><tr><td>溢出重路由</td><td>可切换</td><td>额外分支与重算</td><td>dispatch</td></tr></tbody></table>\n<h3 id=\"ap-moe-router-terms-sec-8\">八 · 速查表的字段口径与读法</h3>\n<p>这张表不是术语词典，而是给推理工程师在代码评审、容量评估和线上排障时直接对照的检查清单。每一行对应一个路由术语，六列分别是：术语名、数学定义（写成可落到 kernel 里的形式）、推理侧是否可关闭、影响的 kernel 阶段、关键参数与取值口径、数值正确性代价与 Blackwell 实现要点。读法上要抓住一点：路由术语的“可关闭性”不是布尔值，而是“关闭后哪一层语义会漂移”。例如归一化可以关闭，但关闭后 combine 阶段的加权和幅值会随 k 与 logits 尺度变化，这不是精度问题而是分布偏移问题。表里的“影响阶段”用路由/dispatch/GEMM/combine 四段标注，是因为这四个阶段在 Blackwell 上是流水衔接的：路由 kernel 的 warp 归约结果写入 token 排序/偏移表，dispatch 按该表搬运，分组 GEMM 消费偏移表决定 M 维，combine 按权重回写。任何一列的取值改动，都会沿这条流水线传导到至少一个下游阶段。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>术语</th><th>数学定义</th><th>推理侧可关闭</th><th>影响阶段</th><th>关键参数与口径</th><th>正确性代价 / Blackwell 要点</th></tr>\n</thead>\n<tbody>\n<tr><td>top-k 门控</td><td>对每 token 的 logits 取前 k 个专家，仅这些专家参与前向</td><td>否（结构决定）</td><td>路由 / GEMM / combine</td><td>k ∈ {1,2,4}；k 增大线性抬升专家 GEMM 工作量与 All-to-All 通信量</td><td>k 是容量规划第一变量；k≤4 时单 warp shuffle 可完成比较</td></tr>\n<tr><td>路由分数归一化</td><td>选中 gate 值做 softmax 或除以求和，权重和为 1</td><td>可，但需固定位置</td><td>路由 / combine</td><td>归一化位置：GEMM 前或 combine 阶段，二选一</td><td>两处都做则权重和被平方缩放，logits 整体偏移；warp 内求和后写回</td></tr>\n<tr><td>专家容量因子</td><td>C = capacity_factor × T·k / E</td><td>否（决定缓冲区）</td><td>GEMM（M 维上界）/ dispatch</td><td>推理常用 1.0–1.25；低于 1.0 系统性丢弃</td><td>直接决定激活缓冲区大小；偏移表需按 C 截断</td></tr>\n<tr><td>token 丢弃</td><td>专家满容量时跳过，输出置零或残差直通</td><td>否（溢出策略之一）</td><td>dispatch / combine</td><td>与容量因子绑定；丢弃率需实测</td><td>输出质量静默劣化；分支在 dispatch kernel 内</td></tr>\n<tr><td>溢出重路由</td><td>溢出 token 改派次优专家并重算权重</td><td>否（溢出策略之一）</td><td>路由 / dispatch</td><td>需保留次优候选，额外分支</td><td>数值更正确但路由 kernel 多一轮；归约延迟需仍短于 GEMM 启动窗口</td></tr>\n<tr><td>负载均衡辅助损失</td><td>训练期把 token 分配推向均匀</td><td>推理侧不参与计算</td><td>无（仅残留偏置）</td><td>以实测单专家打满率判断，不看训练损失</td><td>热专家在长序列/特定领域更易打满；需监控而非调参</td></tr>\n<tr><td>warp 级归约</td><td>单 warp 内 shuffle 完成 top-k 比较与分数求和</td><td>否（实现层）</td><td>路由</td><td>k≤4 单 warp；更大需多轮 shuffle 或跨 warp 合并</td><td>避免 shared memory 往返；归约延迟须短于分组 GEMM 流水启动窗口</td></tr>\n</tbody>\n</table>\n<p>这张表的用法是“按列排查”：排障时先看“影响阶段”定位到哪一段流水线，再看“关键参数与口径”确认取值是否落在工程阈值内，最后看“正确性代价”判断是硬报错还是静默漂移。表中没有给出具体延迟数字，因为路由 kernel 的绝对延迟取决于 batch 内 token 数与专家数，工程上应把它与分组 GEMM 的启动窗口做相对比较，而不是记一个绝对值。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-9\">九 · 阈值：k、容量因子与单 warp 边界</h3>\n<p>三个阈值构成速查表的骨架。第一是 k：常见取值为 1、2、4。k 增大线性抬升每 token 的专家 GEMM 工作量与 All-to-All 通信量，因此它是推理容量规划的第一变量——容量评估时先定 k，再算每 token 的专家计算量与通信量，最后才谈容量因子。第二是容量因子：推理常用 1.0–1.25，低于 1.0 会系统性丢弃。这里的口径是“每专家 token 上限与平均负载之比”，公式为：</p>\n<div class=\"formula\">$$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$$</div>\n<p>其中 T 为 batch 内 token 数、E 为专家数。C 直接决定分组 GEMM 的 M 维上界与激活缓冲区大小，因此容量因子不是“调优旋钮”而是“缓冲区尺寸参数”：调低它省显存但引入丢弃，调高它增显存且可能让 GEMM 的 M 维出现大量填充行。第三是单 warp 边界：warp 级 top-k 归约在 k≤4 时通常单 warp 可完成，k 更大需多轮 shuffle 或跨 warp 合并。这条边界的工程含义是：k≤4 时路由 kernel 可以保持在一个 warp 内完成比较与分数求和，避免跨 warp 的 shared memory 往返；一旦 k 超过 4，归约延迟上升，可能吃掉分组 GEMM 的流水启动窗口，表现为 GEMM 等待偏移表而空转。</p>\n<p>具体例子：一个 batch 内 T 个 token、E 个专家、k=2，若容量因子取 1.0，则每专家上限恰为平均负载，任何路由倾斜都会立即触发丢弃；取 1.25 则给热专家留出 25% 的余量。工程判断是：先以 1.0–1.25 为搜索区间，用实测丢弃率而非训练损失决定落点，因为训练期辅助损失把分配推向均匀，推理侧残留的路由偏置会让热专家在长序列或特定领域输入上更易打满容量。丢弃率是唯一可信的口径，训练损失不能替代。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-10\">十 · 归一化位置：一个二选一的口径</h3>\n<p>归一化在速查表里必须写成“位置”而不是“是否”。推理侧若省略归一化，专家输出加权和会随 k 与 logits 尺度漂移；若在 GEMM 前与 combine 阶段各做一次，权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非明显报错。因此口径是二选一：要么在路由 kernel 内、GEMM 之前把选中 gate 值归一化并写进权重表，要么把原始 gate 值传到 combine 阶段再归一化。前者让 dispatch 与 GEMM 拿到的是已归一权重，后者让 combine 承担求和除法。两种做法都要求“只做一次”，速查表里应把归一化位置作为必填字段，而不是可选优化。</p>\n<p>机制上，归一化在 warp 级归约里就是一次 shuffle 求和：选中专家的 gate 值在单 warp 内求和，再逐 lane 除以该和。k≤4 时这一步与 top-k 比较共用同一轮 shuffle，不额外增加跨 warp 往返。代价在 combine 阶段：若归一化放在 combine，combine kernel 需要读原始 gate 值并做除法，增加了 combine 的算术密度但避免了路由 kernel 写两套权重表；若放在 GEMM 前，路由 kernel 的输出表就是最终权重，combine 只做乘加。工程判断取决于 combine 是否已经是带宽瓶颈：combine 读的是专家输出，若其带宽占用已高，把除法前移更划算。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-11\">十一 · 溢出策略：丢弃与重路由的正确性代价</h3>\n<p>速查表把丢弃与重路由并列为“溢出策略”，因为二者对应不同的数值正确性代价与额外 kernel 分支。token 丢弃指 token 被路由到的专家已满容量时被跳过，其输出按零或残差直通处理；溢出重路由则把溢出 token 改派到次优专家并重算权重。丢弃的代价是静默的：输出质量在无告警情况下劣化，且劣化程度与丢弃率、被丢 token 在序列中的位置相关，难以从单条日志定位。重路由的代价是路由 kernel 多一轮分支：需要保留次优候选、在容量检查失败时改派、并重算归一化权重，归约延迟因此上升，必须仍短于分组 GEMM 的流水启动窗口，否则 GEMM 空等。</p>\n<p>口径上，速查表要求把“溢出策略”与“容量因子”绑定填写：容量因子低于 1.0 时丢弃是系统性行为而非偶发，此时选丢弃等于接受固定比例的 token 不参与专家计算；选重路由则要把次优候选的保留成本算进路由 kernel 的延迟预算。具体例子：长序列输入下热专家打满容量，若策略是丢弃，被丢 token 的残差直通会让该 token 的输出退化为注意力层的直通结果，表现为局部生成质量下降而无报错；若策略是重路由，溢出 token 改派次优专家，权重按新专家重算，输出更接近训练分布，但路由 kernel 的分支让偏移表生成变慢，需要确认它没有超出 GEMM 启动窗口。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-12\">十二 · Blackwell 实现要点：归约与流水衔接</h3>\n<p>速查表最后一列是 Blackwell 实现要点，核心是两件事：warp 级归约和与 SM100 张量核流水线的衔接。warp 级归约指在单个 warp 内用 shuffle 完成 top-k 比较与分数求和，避免跨 warp 的 shared memory 往返；其结果需写入供 SM100 张量核流水线消费的 token 排序/偏移表。衔接点在于归约延迟必须短于分组 GEMM 的流水启动窗口——分组 GEMM 按偏移表决定 M 维并启动 MMA，若偏移表迟到，GEMM 的流水线启动被推迟，张量核空转。k≤4 时单 warp 归约可以满足这一约束；k 更大时多轮 shuffle 或跨 warp 合并会拉长归约，工程上应把 k 的选择与这条延迟约束一起考虑，而不是只看计算量。</p>\n<p>另一个实现要点是排序稳定性。top-k 排序若用不稳定比较，同分 token 的路由会抖动，相同输入在不同 batch 组合下路由到不同专家，造成服务端输出不可复现、难以定位。速查表应把“比较稳定性”作为路由 kernel 的检查项：同分 logits 需有确定的 tie-break 规则（如按专家索引），使偏移表在 batch 组合变化时保持可复现。这一项不影响吞吐，但直接影响可运维性——不可复现的输出让丢弃率、归一化漂移等问题的定位失去基准。</p>\n<p>代价层面，warp 归约省掉的是 shared memory 往返的延迟与带宽，换来的是对 k 的上界约束；与 TMEM 的衔接体现在偏移表被分组 GEMM 消费的时机，归约结果写表越早，GEMM 流水启动越早。工程判断是：把路由 kernel 的归约延迟当作分组 GEMM 的前置延迟预算来管理，k 与容量因子的取值都要在这个预算内选定，而不是先定 k 再补延迟。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-13\">十三 · 三个高频踩坑的对照口径</h3>\n<p>速查表的价值在排障时体现为三条对照口径。第一，把训练期辅助损失当作推理负载均衡保证：辅助损失在训练时把 token 分配推向均匀，但推理侧残留影响体现为路由分布仍带训练期偏置，热专家在长序列或特定领域输入上更易打满容量。口径是“以实测丢弃率而非训练损失判断是否调容量因子”，速查表里辅助损失一行应标注“推理侧不参与计算，仅残留偏置”。第二，在 combine 阶段重复归一化：归一化在 GEMM 前与 combine 阶段各做一次，权重和被平方缩放，专家加权和幅值偏离训练分布。口径是“归一化位置二选一”，速查表把位置作为必填字段而非优化项。第三，top-k 排序用不稳定比较：同分 token 路由抖动，batch 间输出不一致。口径是“tie-break 规则必须确定”，速查表把比较稳定性列为路由 kernel 检查项。</p>\n<p>这三条的共同点是都不产生明显报错，而是静默改变数值或可复现性。因此速查表的使用方式不是“查定义”，而是“在评审路由 kernel 与容量配置时逐行核对口径”：k 是否落在 1–4、容量因子是否在 1.0–1.25 且与丢弃率实测匹配、归一化位置是否唯一、溢出策略是否与容量因子绑定、warp 归约是否满足 k≤4 的单 warp 边界、比较是否稳定。任何一行口径缺失，都会在长序列或高倾斜输入下以丢弃率上升或输出漂移的形式暴露，而那时已无训练损失可参照。</p>\n<h3 id=\"ap-moe-router-terms-sec-14\">十四 · 阈值不是常数，是随 batch 形状漂移的区间</h3>\n<p>工程上谈 MoE 路由阈值，最容易犯的错是把 k 与容量因子当成一组固定超参写进配置就完事。实际在 Blackwell 推理栈里，这两个量的有效取值随 batch 内 token 数 T、专家数 E、序列长度分布一起漂移，因为它们进入的是同一个容量公式：</p>\n<div class=\"formula\">$$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$$</div>\n<p>这个式子给出的不是“每专家能放多少 token”的静态上界，而是分组 GEMM 的 M 维上界与激活缓冲区尺寸的直接来源。T 在连续批处理下是逐 iteration 变化的，k 固定时 C 随 T 线性变化；这意味着同一组 capacity_factor 在小 batch 下宽松、在大 batch 下骤然收紧。工程判断因此不是“选一个容量因子”，而是“选定一个容量因子并声明它适用的 T 区间”。k 的常见取值为 1、2 或 4，每加一档，每 token 的专家 GEMM 工作量与 All-to-All 通信量线性抬升，这是容量规划的第一变量，也是本片段所有阈值的锚点。</p>\n<p>测量方法上，不要用训练侧的辅助损失曲线推断推理侧负载。辅助损失把分配推向均匀，但推理侧残留的训练期偏置会让热专家在长序列或特定领域输入上更易打满容量。正确做法是在服务路径上采样单专家打满率：对每个 iteration 记录被容量截断的 token 数占该专家应接收 token 数的比例，按专家维度聚合出打满率分布，而不是只看全局平均丢弃率——全局平均会把少数热专家的系统性溢出稀释掉。代价上，这个采样本身要读回路由 kernel 写出的偏移表，属于 host 侧同步点，若每个 iteration 都做会打断流水；工程上按固定间隔抽样若干 iteration，把打满率作为容量因子的反馈信号。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-15\">十五 · 容量因子 1.0–1.25 的边界与低于 1.0 的系统性丢弃</h3>\n<p>推理常用容量因子落在 1.0–1.25。1.0 意味着每专家上限恰好等于平均负载，任何路由倾斜都会立即产生丢弃；1.25 给热专家留出四分之一余量，代价是激活缓冲区按 1.25 倍平均负载分配，分组 GEMM 的 M 维上界同步放大，显存占用与 GEMM 的有效利用率之间形成对冲。低于 1.0 不是“更省”，而是系统性丢弃：容量上限低于平均负载，即使路由完全均匀也必然有 token 被跳过，其输出按零或残差直通处理，数值正确性代价从“偶发”变成“结构性”。</p>\n<p>判断是否该调容量因子，依据是实测丢弃率而非训练损失。一个可操作的判定链是：先在目标 T 区间内以 1.0 跑，采集单专家打满率；若热专家打满率显著高于冷专家，说明路由倾斜是结构性的，抬容量因子只能缓解不能消除，应同时检查归一化位置与路由分数尺度；若打满率在各专家间接近但整体偏高，则是 T 相对 E 过大，抬容量因子或调整 batch 切分更直接。丢弃与溢出重路由是两条不同的分支：丢弃走零或残差直通，kernel 分支短但输出质量受损；溢出重路由把 token 改派到次优专家并重算权重，数值上更接近完整计算，代价是额外 kernel 分支与一次权重重算，dispatch 阶段的 token 排序表需要支持二次写入。选哪条取决于 SLO 对输出一致性的容忍度，而不是默认丢弃更便宜。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-16\">十六 · k≤4 的单 warp 归约窗口与流水衔接</h3>\n<p>Blackwell 路由 kernel 的 warp 级归约指在单个 warp 内用 shuffle 完成 top-k 比较与分数求和，避免跨 warp 的 shared memory 往返。工程阈值在这里很具体：k≤4 时通常单 warp 可完成，k 更大需多轮 shuffle 或跨 warp 合并。这个阈值不是性能偏好，而是衔接约束——归约结果要写入供 SM100 张量核流水线消费的 token 排序/偏移表，衔接点在于归约延迟必须短于分组 GEMM 的流水启动窗口。一旦 top-k 归约跨 warp 合并，多出的 shared memory 往返与同步会把归约延迟推过这个窗口，分组 GEMM 的流水启动被拖后，表现为路由阶段与 GEMM 阶段之间出现气泡，吞吐下降而单看路由 kernel 的耗时并不夸张。</p>\n<p>伪代码层面的思路是：warp 内先做 logits 的局部比较得到候选，再用 shuffle 在 lane 间交换候选完成 top-k 定序，随后对选中分数做求和以支持归一化，最后把 (token, expert, 权重) 三元组按专家维度写出偏移表。k≤4 时这整段在单 warp 内闭合，无 shared memory 中转。测量方法上，要测的不是路由 kernel 的绝对延迟，而是它与分组 GEMM 启动之间的间隔：在 profiler 里看路由 kernel 结束到 GEMM kernel 首个 MMA 指令之间的空窗，若空窗随 k 增大而扩张，说明归约已越过衔接窗口，此时应限制 k 或改归约实现，而不是继续加容量因子。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-17\">十七 · 归一化位置的重复执行是幅值级故障</h3>\n<p>路由分数归一化使选中专家的 gate 权重和为 1，推理侧若省略归一化，专家输出加权和会随 k 与 logits 尺度漂移，因此必须在 kernel 内固定归一化位置：GEMM 前或 combine 阶段，二选一。最常见的踩坑是在两处各做一次，权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非明显报错。这类故障没有异常抛出，只有输出分布漂移，定位成本极高。</p>\n<p>测量方法要针对幅值而非针对路由：在固定输入下对比 combine 阶段输出的加权和与参考实现的逐元素偏差，若偏差呈整体缩放而非随机噪声，即为重复归一化。工程上更稳的做法是把归一化位置写进 kernel 契约并在 profiler 里断言只执行一次，而不是靠代码评审。代价层面，归一化本身是 warp 内求和的延伸，单 warp 归约下几乎不增加延迟；真正的代价是错误位置带来的数值返工——一旦发现幅值偏移，需要回退整条量化校准数据管线，因为校准数据是在错误幅值下采集的。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-18\">十八 · 同分 logits 与不稳定排序引发的不可复现</h3>\n<p>top-k 比较使用不稳定排序或未处理同分 logits，会让相同输入在不同 batch 组合下路由到不同专家，造成服务端输出不可复现、难以定位。这不是精度问题，是一致性问题：同一 token 在 batch A 里路由到专家 i，在 batch B 里路由到专家 j，两者输出都“正确”，但服务端无法给出稳定结果，A/B 对比与故障复现全部失效。工程阈值在这里是“同分必须定序”：在 warp 级归约的比较逻辑里加入以专家索引为次级键的稳定比较，使同分 logits 的定序与 batch 组合无关。</p>\n<p>测量方法直接且廉价：构造一组人为同分 logits 的输入，以不同 batch 切分方式重复推理，比对路由结果表是否逐位一致。这一步应纳入回归测试而非线上监控，因为线上流量里同分概率低、偶发不一致难以被统计捕获。代价上，稳定比较在 warp 内多一次索引比较，k≤4 时仍在单 warp 窗口内闭合，不破坏与分组 GEMM 的流水衔接；但若把定序逻辑放到跨 warp 合并里，就会同时引入第三节所述的衔接窗口问题。因此稳定定序应实现在单 warp 归约内部，与 top-k 比较共用同一轮 shuffle。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-19\">十九 · 把阈值变成可观测量的工程落点</h3>\n<p>把上述阈值串起来，工程落点是三个可观测量：单专家打满率、路由 kernel 结束到 GEMM 首个 MMA 的空窗、combine 输出加权和与参考的幅值偏差。三者分别对应容量因子、k 与归约实现、归一化位置。它们都不需要训练侧信号，全部在推理服务路径上可采。容量因子的反馈来自打满率分布而非全局丢弃率；k 的上限由空窗是否随 k 扩张决定，而不是由单 kernel 延迟决定；归一化的正确性由幅值偏差断言，而不是由路由分布断言。</p>\n<p>具体例子：一条长序列请求混入连续批处理，T 骤增使 C 收紧，热专家打满率跳升，若只看全局丢弃率会被冷专家稀释而漏判；此时若贸然抬容量因子，激活缓冲区按更高倍数分配，显存压力转移到 KV cache 侧，反而压缩了可并发序列数。正确顺序是先确认打满率是否集中在少数专家——集中则查归一化与分数尺度，分散则调 batch 切分或容量因子。这个判断链的每一步都落在具体机制上：容量公式给出上界，warp 归约给出衔接窗口，归一化位置给出幅值契约，三者共同约束 k 与 capacity_factor 的可选区间。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-20\">二十 · 容量因子、丢弃率与路由归约的工程边界</h3>\n<p>容量因子是推理侧唯一能同时约束显存与分组 GEMM 形状的旋钮，其定义已在前文给出：$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$。工程上真正要盯的不是这个上界本身，而是它与实测丢弃率的耦合。容量因子取 1.0–1.25 是推理常用区间，低于 1.0 意味着每个专家的 token 上限低于平均负载，系统性丢弃不可避免——这不是概率事件，而是由负载分布方差直接决定的确定性损失。判断是否需要上调，唯一可靠依据是逐专家的打满率与丢弃率采样：在路由 kernel 输出排序/偏移表时顺带累加每个专家的实际接收 token 数与溢出计数，按 batch 或按时间窗口聚合。训练期辅助损失把分配推向均匀，但推理输入的长序列与领域偏置会让热专家重新聚集，训练损失下降不能作为容量充足的证据。代价方面，容量因子上调线性放大激活缓冲区与分组 GEMM 的 M 维上界，即使实际填充率不高，预留的显存与调度槽位也已被占用；因此这是一个用显存换丢弃率的单调权衡，而非可以随手调大的安全余量。</p>\n<p>丢弃与溢出重路由在系统代价上分属两类。丢弃路径只需在 combine 阶段把被跳过 token 的输出置零或走残差直通，kernel 分支最浅，但数值正确性代价是无声的：输出质量劣化不产生任何告警。溢出重路由要把 token 改派到次优专家并重算权重，等于在 dispatch 之后插入一次额外的路由判定与可能的第二轮 All-to-All，延迟与通信量都随溢出比例上升，且次优专家的权重未经归一化校正时会破坏权重和为 1 的前提。工程判断是：容量因子接近 1.0 且丢弃率非零时，优先上调容量因子而非开启重路由，因为前者只花显存，后者花的是流水线启动窗口与链路带宽。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>采样位置</th><th>失效信号</th></tr></thead><tbody><tr><td>单专家打满率</td><td>路由排序/偏移表写出时</td><td>热专家持续满载而容量因子未上调</td></tr><tr><td>丢弃/溢出计数</td><td>dispatch 分支</td><td>丢弃率非零却无监控告警</td></tr><tr><td>权重和偏差</td><td>combine 阶段</td><td>归一化在 GEMM 前与 combine 各做一次，权重和被平方缩放</td></tr><tr><td>路由一致性</td><td>top-k 比较</td><td>同分 logits 用不稳定排序，跨 batch 路由抖动</td></tr></tbody></table>\n<p>归一化的重复执行是最隐蔽的一类错误：在 GEMM 前归一化一次、combine 阶段再归一化一次，权重和不再为 1 而是被平方缩放，专家加权和的幅值偏离训练分布，表现为 logits 整体偏移而非报错，排查时极易误判为精度问题。正确做法是在 kernel 内固定归一化位置，只做一次，并在 combine 输出处校验权重和。路由侧的另一处边界在 warp 级归约：k≤4 时单 warp 用 shuffle 即可完成 top-k 比较与分数求和，k 更大则需多轮 shuffle 或跨 warp 合并，归约延迟随之拉长。这个延迟必须短于分组 GEMM 的流水启动窗口，否则 SM100 张量核在等待排序/偏移表时被迫空转，路由成为整条流水线的实际瓶颈。同分 logits 的处理同样落在这一层：不稳定比较会让相同输入在不同 batch 组合下路由到不同专家，服务端输出不可复现，定位成本远高于修复成本，因此比较必须带确定性的 tie-break。</p>\n<h3 id=\"ap-moe-router-terms-sec-21\">二十一 · 踩坑清单：三类高频故障的机制定位</h3>\n<p>推理侧 MoE 的故障很少来自算子本身写错，而是来自「训练期语义」与「推理期执行」之间的缝隙。第一类坑是把训练期辅助损失当成推理负载均衡的保证。辅助损失在训练时把 token 分配推向均匀，但推理侧残留影响体现为路由分布仍带训练期偏置：热专家在长序列或特定领域输入上更易打满容量。工程上必须区分两个量——训练损失是优化目标，单专家打满率才是推理健康指标。监控对象应是每个专家的 <code>token_count / capacity</code> 比值随 batch 的分布，而不是 loss 曲线。长序列输入下热专家溢出丢弃，输出质量在无告警情况下劣化，这类故障没有异常日志，只有下游评测分数缓慢下滑，因此必须把打满率做成常驻指标而非事后排查项。</p>\n<p>第二类坑是归一化位置重复。归一化指对选中专家的 gate 值做 softmax 或除以求和，使权重和为 1。若在 GEMM 前做一次、在 combine 阶段又做一次，权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非明显报错。这类错误的隐蔽性在于它不触发任何断言：张量形状正确、数值有限、kernel 不报错，只是输出分布被整体压缩或放大。定位手段是在 combine 输出上挂一个轻量探针，统计 <code>sum(gate_weight)</code> 的均值，偏离 1 即报警。归一化位置必须在 kernel 内固定为单一位置，写进路由 kernel 的契约而非由上层框架参数决定。</p>\n<p>第三类坑是 top-k 比较使用不稳定排序或未处理同分 logits。相同输入在不同 batch 组合下路由到不同专家，造成服务端输出不可复现。机制上，warp 级归约用 shuffle 完成 top-k 比较时，若比较函数对相等 logits 返回非确定顺序，则同一 token 在不同 warp 布局下选中不同专家。修复方式是在比较器中引入专家索引作为次级键，使排序全序化；代价是每次比较多一次整数比较，在 k≤4 的单 warp 归约中可忽略，但对 k 更大的多轮 shuffle 会累积成可测的归约延迟。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-22\">二十二 · 检查顺序：从路由表到 GEMM 流水</h3>\n<p>排查应按数据流方向推进，而不是按模块清单平铺。第一步检查路由 kernel 产出的 token 排序/偏移表：这张表是 dispatch 与分组 GEMM 的唯一输入契约，表错则后续全错。检查项包括每个专家的 token 计数是否与容量公式一致，以及偏移表是否单调。容量上界由</p>\n<div class=\"formula\">$$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$$</div>\n<p>给出，其中 T 为 batch 内 token 数、E 为专家数。它直接决定分组 GEMM 的 M 维上界与激活缓冲区大小。若实测 token 计数超过 C，说明容量因子设置与真实路由分布不匹配，此时应看丢弃率而非改 k。</p>\n<p>第二步检查归一化与权重写入。归一化发生在 GEMM 前还是 combine 阶段，必须与 kernel 契约一致；检查方式是取一个 batch，手工重算选中专家的权重和，与 kernel 输出比对。第三步检查 dispatch 的 All-to-All 与分组 GEMM 的衔接：Blackwell 上路由 kernel 的 warp 级归约结果需写入供 SM100 张量核流水线消费的偏移表，衔接点在于归约延迟必须短于分组 GEMM 的流水启动窗口。若归约拖长，GEMM 流水启动被推迟，表现为端到端延迟中一段无法归因的空转。第四步才是数值精度与量化路径，因为前两步的错误会伪装成精度问题。</p>\n<p>检查顺序的工程理由是代价不对称：路由表错误导致的是全 batch 语义错误，修复成本低但发现晚；而归约延迟属于性能问题，可用时间线工具直接定位。把语义正确性检查放在性能检查之前，能避免在错误的表上做性能调优。一个具体例子：某服务在长序列压测中吞吐正常但输出漂移，按此顺序第一步即发现热专家 token 计数持续等于容量上界，说明溢出丢弃已系统性发生，容量因子需上调而非调精度。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-23\">二十三 · 容量与丢弃的判定：用实测丢弃率而非训练损失</h3>\n<p>容量因子推理常用 1.0–1.25，低于 1.0 会系统性丢弃。判定是否需要上调，唯一可靠依据是实测丢弃率：统计被跳过或被重路由的 token 占该 batch 总 token 的比例，并按专家维度分解。训练期辅助损失不能作为判据，因为它优化的是全局均匀性，而推理故障往往集中在少数热专家上——全局分布看起来均匀，单专家打满率却已饱和。</p>\n<p>token 丢弃指 token 被路由到的专家已满容量时被跳过、其输出按零或残差直通处理；溢出重路由则把溢出 token 改派到次优专家并重算权重。二者在推理侧对应不同的数值正确性代价与额外 kernel 分支。丢弃的代价是语义损失且无分支开销；重路由的代价是额外一次权重计算与可能的第二次 dispatch，延迟上升但语义更接近训练分布。选择哪一种取决于 SLO：延迟敏感场景倾向丢弃加残差直通，质量敏感场景倾向重路由。无论哪种，都必须把丢弃率与重路由率作为独立指标暴露，而不是合并成一个「溢出率」。</p>\n<p>容量因子上调的代价是显存：C 直接决定激活缓冲区大小，容量因子从 1.0 提到 1.25 意味着分组 GEMM 的 M 维上界与中间激活同步扩大，在专家并行下每个 rank 的缓冲区都要按此放大。因此上调容量因子不是免费的数值调整，而是一次显存预算重分配，需与 KV cache 的占用一起核算。工程判断是：先测丢弃率随序列长度的曲线，若在目标序列长度上丢弃率超过可接受阈值，再评估上调容量因子与增大 k 之外的第三条路——按领域输入做路由预热统计，识别热专家并针对性扩容。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-24\">二十四 · 回滚方案：把路由配置做成可切换的版本化对象</h3>\n<p>路由相关参数（k、capacity_factor、归一化位置、溢出策略、排序比较器）应打包为版本化配置对象，与模型权重解耦。理由是三处坑的修复都只动配置不动权重：归一化位置、比较器全序化、容量因子调整都不改变专家参数。把配置做成可热切换对象，使得线上异常时能在不重载权重的前提下回滚到上一版路由语义，回滚窗口从分钟级降到秒级。</p>\n<p>回滚的判定条件要预先定义，不能靠人工判断。建议三条触发线：单专家打满率持续超过阈值、combine 输出权重和探针偏离 1、相同输入在不同 batch 组合下路由结果不一致（可用固定种子的小批量探针周期性比对）。第三条尤其重要，因为不稳定排序造成的不可复现是最难定位的一类，周期性探针比对能在扩散前捕获。</p>\n<p>回滚方案还需覆盖 kernel 层：warp 级 top-k 归约在 k≤4 时通常单 warp 可完成，k 更大需多轮 shuffle 或跨 warp 合并。若线上把 k 从 2 调到 4，归约路径可能从单 warp 变为多轮，延迟特性改变，此时回滚不仅是参数回退，还要确认 kernel 分支与参数匹配。工程上应把 k 的取值与 kernel 实现路径绑定在同一个配置对象里，避免出现参数已回滚而 kernel 仍走多轮归约路径的不一致状态。最后一段落在具体机制上：路由 kernel 的契约应显式声明「归一化位置、比较器全序性、容量上界来源」三项，任何一项变更都触发配置版本号递增，使回滚成为一次版本指针切换而非一次重新推理验证。</p>\n\n\n<h3 id=\"ap-moe-router-terms-sec-25\">二十五 · 踩坑清单、检查顺序与回滚方案</h3>\n<p>本方案真正的边界不在术语表本身，而在“术语—kernel 阶段—可观测指标”这条链是否闭合。速查表若只列定义而不标注“推理侧是否可关闭、影响哪个 kernel 阶段”，工程上就无法定位故障。检查顺序应按代价从低到高排：先看单专家打满率与实测丢弃率，再看归一化次数，最后看路由可复现性。原因是三者失效表现截然不同——容量溢出表现为输出质量在无告警下劣化，重复归一化表现为 logits 整体幅值偏移而非报错，不稳定排序表现为同一输入在不同 batch 组合下路由抖动。前两者可用指标直接判定，后者只能靠固定 batch 组合的比对实验暴露，排查成本最高，故放在末位。速查表建议至少含“影响的 kernel 阶段（路由/dispatch/GEMM/combine）”与“数值正确性代价”两列，否则术语无法与故障现象对齐。</p>\n<p>容量侧的第一个坑是把训练期辅助损失当作推理负载均衡的保证。辅助损失只把训练分布推向均匀，推理侧残留的是训练期偏置：热专家在长序列或特定领域输入上更易打满容量。判断依据必须是实测丢弃率，而不是训练损失曲线。容量上界由 <span class=\"formula\">$$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$$</span> 给出，它同时决定分组 GEMM 的 M 维上界与激活缓冲区大小；容量因子低于 1.0 会系统性丢弃，推理常用 1.0–1.25。这里的系统代价是双向的：调高容量因子抬高激活缓冲区显存占用与分组 GEMM 的 M 维浪费（填充 token 参与无效计算），调低则触发丢弃或溢出重路由的额外 kernel 分支。k 取 1、2 或 4，k 增大线性抬升每 token 的专家 GEMM 工作量与 All-to-All 通信量，因此容量因子与 k 必须联合标定，单独调其中一个都会把代价推到另一侧。</p>\n<p>归一化侧的坑是“GEMM 前与 combine 阶段各做一次”。权重和被平方缩放，专家加权和幅值偏离训练分布，症状是 logits 整体偏移而非明显报错，极易被误判为精度问题。规避手段是在 kernel 内固定归一化位置，只允许一处生效，并在 combine 阶段加一条断言：选中专家权重和与 1 的偏差超过阈值即上报。路由侧还有一个隐蔽坑：top-k 比较用不稳定排序或未处理同分 logits，相同输入在不同 batch 组合下路由到不同专家，服务端输出不可复现。修复方式是排序网络对同分 token 附加确定性 tie-break（如按 token 索引），代价是排序网络多一级比较，但换来可复现性——这是排障的前提，不能省。</p>\n<p>Blackwell 实现层的坑集中在衔接点：warp 级归约用 shuffle 完成 top-k 比较与分数求和，避免跨 warp 的 shared memory 往返，其结果需写入供 SM100 张量核流水线消费的 token 排序/偏移表。约束是归约延迟必须短于分组 GEMM 的流水启动窗口；k≤4 时单 warp 通常可完成，k 更大需多轮 shuffle 或跨 warp 合并，归约延迟随之拉长，可能吃掉流水启动窗口，表现为 GEMM 空转而非报错。回滚方案按粒度分三级：第一级只回滚容量因子至上一稳定值并保留 k，用于丢弃率突升；第二级回滚归一化位置开关，用于幅值偏移；第三级回滚整个路由 kernel 至上一版本排序实现，用于不可复现故障。每级回滚都必须同时冻结 batch 组合配置，否则回滚后指标不可比，无法确认故障是否真的消除。</p>\n<h3 id=\"ap-moe-router-terms-sec-26\">二十六 · 上游依赖：路由术语如何被量化与并行条目反向约束</h3>\n<p>路由条目在全书里不是孤立的一张表，它同时是多个条目的输入契约。最直接的上游是 NVFP4/FP8 权重激活条目：一旦专家权重被压到 FP4 或 FP8，路由 logits 的数值尺度、gate 分数的比较精度都会改变，top-k 的“谁进前 k”在低精度下可能出现同分或近同分抖动。因此路由 kernel 的 warp 级归约必须明确它消费的 logits 是何种精度、是否在归约前做一次尺度对齐；否则下游 combine 阶段的加权和会继承一个未被记录的偏差。第二个上游是量化后路由漂移条目——它讨论的是量化本身如何改变路由分布，而本条目提供的是“漂移之后用什么术语描述后果”：容量因子是否仍按 1.0–1.25 取、丢弃率是否从训练期偏置中放大，都是漂移条目的输出被路由术语接住的点。</p>\n<p>第三个上游是专家并行与 All-to-All：路由结果决定 dispatch 的目标 rank，token 排序/偏移表的结构直接决定 All-to-All 的消息切分粒度。路由 kernel 写出的偏移表若按专家连续排列，All-to-All 就能按专家块打包；若按 token 原始顺序排列，通信侧需要额外的重排。这里的代价是显存与带宽：偏移表本身很小，但它决定的打包方式会影响 All-to-All 的有效载荷利用率，进而影响每 token 的通信字节数。一个具体例子是 k=2、容量因子 1.25 的配置下，热专家被打满时溢出 token 需要改派，改派后的目标专家可能落在另一个 rank，路由表必须同时携带“原专家、次优专家、是否溢出”三个字段，否则 dispatch 阶段无法区分正常 token 与重路由 token。</p>\n<p>上游依赖的工程判断是：路由术语的每一个字段都要能回答“谁在消费它”。k 被容量规划消费，归一化位置被 combine kernel 消费，容量因子被分组 GEMM 的 M 维上界消费，溢出策略被 dispatch 分支消费。缺一个字段，下游条目就得自己补假设，而补出来的假设往往与训练期分布不一致。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-27\">二十七 · 下游影响：从路由表到分组 GEMM 与 combine 的连锁代价</h3>\n<p>路由条目最重的下游是分组 GEMM 与 tcgen05 条目。容量因子给出的每专家 token 上限 $$C = \\mathrm{capacity\\_factor} \\times \\frac{T \\cdot k}{E}$$ 直接变成分组 GEMM 的 M 维上界与激活缓冲区大小；路由 kernel 产出的按专家分组的 token 计数，则是分组 GEMM 切分 grid 的依据。Blackwell 上的衔接点很具体：warp 级归约完成的 top-k 与分数求和必须短于分组 GEMM 的流水启动窗口，否则 SM100 张量核在等待路由结果时流水空转。这里的系统代价是延迟而非吞吐——路由归约本身在 k≤4 时单 warp 可完成，但它处在关键路径上，归约延迟直接叠加到每个 micro-batch 的首个 GEMM 之前。</p>\n<p>第二个下游是 combine 阶段。归一化位置一旦在路由条目里定死（GEMM 前或 combine 阶段），combine kernel 就不能再做一次；重复归一化会让权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非报错。这个失败模式的代价是数值正确性，不是性能：它不会让服务变慢，但会让输出质量在无告警的情况下劣化。工程上对应的检查是 combine 前后各采样一次权重和，确认其为 1。</p>\n<p>第三个下游是 MoE 场景 KV 压缩与分离式预填/解码。路由倾斜尾延迟条目讲的是热专家打满导致的尾延迟，而本条目提供的是“倾斜如何在术语层被度量”：单专家打满率、丢弃率、溢出重路由比例。分离式预填/解码场景下，预填阶段的长序列更容易把热专家打满，解码阶段则以小 batch 反复触发同一批热专家；两个阶段的容量因子是否需要分开设定，取决于路由条目里“容量约束是否可关闭”这一列。可关闭容量因子意味着不丢弃但激活缓冲区按最坏情况分配，显存代价上升；不可关闭则意味着必须接受丢弃或重路由的数值代价。</p>\n<p>下游影响的工程判断是：路由表的字段设计要预留下游分支所需的判别位。溢出标记、归一化标记、排序稳定性标记三者缺一，dispatch 与 combine 就得靠推断，而推断在 batch 组合变化时会失效。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-28\">二十八 · 横向关系：与框架选型、剖析工具链的接口</h3>\n<p>路由术语与 MoE 推理框架选型条目的接口是“哪些术语可由框架配置、哪些被写死在 kernel 里”。TensorRT-LLM、vLLM、SGLang、Dynamo 对 top-k、容量因子、归一化位置的暴露程度不同：有的把容量因子作为插件参数，有的把归一化固定在 combine 内。选型条目关心的是功能覆盖，本条目关心的是术语到配置项的映射——如果某个框架不暴露归一化位置，那么“在 GEMM 前归一化”这一术语在该框架下不可实现，只能退到 combine 阶段，此时必须确认没有第二次归一化。</p>\n<p>与 MoE 剖析工具链条目的接口是度量口径。剖析工具链采集的是单专家 token 数、打满率、丢弃率、All-to-All 字节数；这些指标的定义必须与路由术语一致，否则“丢弃率”在工具里按容量因子归一化、在容量规划里按实际 token 数归一化，两边对不上。一个具体例子是：工具报告某专家打满率为 1.0，容量规划侧却按平均负载算出容量因子 1.25 仍有余量——差异来自分母定义，前者是“达到上限的 step 占比”，后者是“上限与平均负载之比”。术语速查表的价值就在这里：它把每个指标的分母写死。</p>\n<p>横向关系还包括通信计算死锁条目。溢出重路由会引入额外的 dispatch 分支，分支内的 All-to-All 若与主路径共享同一组 NCCL 通道，可能出现等待顺序不一致。路由条目能提供的是“重路由 token 的数量上界”，这个上界由容量因子与 k 决定，通信侧据此预留缓冲区，避免动态分配导致的通道争用。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-29\">二十九 · 在全书中的位置：路由作为容量规划的第一变量</h3>\n<p>把路由条目放回全书结构，它的位置是“容量规划的第一变量”。SLO 与容量规划条目需要三个输入：每 token 的专家 GEMM 工作量、每 token 的 All-to-All 通信量、激活缓冲区大小。这三个输入全部由 k 与容量因子决定——k 增大线性抬升前两者，容量因子决定第三者。因此路由术语不是背景知识，而是容量公式里的系数来源。工程上的做法是先把 k 与容量因子定死，再算单卡可承载的 token 数，最后反推 batch 与并行度；反过来先定 batch 再调容量因子，会让丢弃率成为不可控的因变量。</p>\n<p>在七个领域的推理形态里，路由术语的权重不同。长序列与文档理解类负载更容易触发热专家打满，容量因子需要留余量；低延迟对话类负载 batch 小、k 常取 1 或 2，路由归约延迟占比更高，warp 级归约的启动窗口成为关键；批量离线推理可以用更大的容量因子换取不丢弃，显存代价可接受。这些差异不改变术语定义，只改变术语的取值区间。</p>\n<p>与显存与 KV cache 条目的关系是间接的：路由本身不占 KV cache，但容量因子决定的激活缓冲区与溢出 token 的残差直通路径会占用额外显存。当容量因子取 1.25 时，激活缓冲区按上限分配，实际使用率取决于路由倾斜程度；倾斜越重，缓冲区越接近满，而 KV cache 可用的显存余量越少。这是一个需要在容量规划里显式列出的耦合项。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-30\">三十 · 接口契约：术语表如何变成可执行的检查</h3>\n<p>路由术语速查表的最后一层用途是生成检查项，而不是供人查阅。每个术语对应一条可在服务启动前执行的断言：k 是否在 1–4 内、容量因子是否不低于 1.0、归一化是否只在一个位置发生、top-k 比较是否稳定、溢出策略是否有对应的 dispatch 分支、warp 归约结果是否写入了分组 GEMM 消费的偏移表。这些断言的成本很低，但它们拦住的是三类失败模式：训练期辅助损失被当作推理负载均衡保证、归一化重复、同分 logits 路由抖动。</p>\n<p>接口契约的关键在于“谁负责断言”。路由 kernel 负责 k 范围、归约延迟、排序稳定性；dispatch 负责溢出标记与目标 rank；combine 负责权重和为 1；容量规划负责容量因子与丢弃率的上界。把断言分配到具体组件，才能避免每个组件都假设别人已经检查过。一个具体机制是：在路由 kernel 输出偏移表时附带一个单调递增的序号，combine 阶段校验序号连续且无重复，即可发现重路由 token 被重复计入或遗漏。</p>\n<p>系统代价方面，这些断言的运行时开销可以忽略，但它们约束了 kernel 的实现方式：排序稳定性要求比较函数带 token 序号作为次级键，warp 级归约需要在 shuffle 中携带该序号；这会让单 warp 归约在 k≤4 时仍可完成，但寄存器压力略增。工程判断是：稳定性不是可选项，因为服务端输出不可复现的定位成本远高于寄存器压力带来的占用率损失。</p>\n<p>最终落在具体机制上：路由条目的价值是把“路由”从一个黑盒步骤拆成一组带分母、带消费方、带断言的字段；当这些字段与上游量化、下游 GEMM/combine、横向框架配置对齐后，MoE 推理的容量规划才有可复算的起点，而不是靠实测丢弃率反复试错。</p>\n\n<h3 id=\"ap-moe-router-terms-sec-31\">三十一 · 路由参数的上下游耦合与失效边界</h3>\n<p>路由不是孤立的一层，它向上承接 batch 调度给出的 token 数 T，向下决定分组 GEMM 的 M 维上界与 All-to-All 的通信量。容量因子 C 一旦写死，就把这条链路锁死了：<div class=\"formula\">$$M_{\\text{GEMM}} \\le C \\cdot E,\\quad \\text{通信量} \\propto T \\cdot k$$</div>调度侧把连续批处理的 batch 拉大，T 上升，C 不变则单专家上限按比例放大，激活缓冲区与 TMEM 占用同步膨胀；反之若为省显存压低 C，丢弃率上升。工程上应把 C 作为调度器的输出而非静态配置，让 batch 规模与容量因子联动，而不是各自独立调参。</p>\n<p>归一化位置是另一处跨条目耦合点。若在 GEMM 前归一化，combine 阶段必须只做加权求和；若在 combine 阶段归一化，则 GEMM 前保持原始 gate 值。两处各做一次会使权重和被平方缩放，专家加权和幅值偏离训练分布，表现为 logits 整体偏移而非报错——这类错误在 SLO 监控上只体现为质量指标缓慢下滑。判断依据是实测丢弃率与单专家打满率，而不是训练期辅助损失：辅助损失把路由推向均匀，但推理输入分布与训练不同，热专家在长序列或特定领域输入上仍会打满，训练损失对此无告警能力。</p>\n<p>kernel 实现层与张量核流水线的衔接决定了路由能否被隐藏。k≤4 时 warp 级 shuffle 归约可在单 warp 内完成 top-k 比较与分数求和，结果写入 token 排序/偏移表供分组 GEMM 消费；衔接条件是归约延迟必须短于流水启动窗口，否则 GEMM 空等，路由从“免费”变成串行瓶颈。k 增大到需多轮 shuffle 或跨 warp 合并时，这段延迟直接进入关键路径，此时应把路由与 dispatch 重叠，而非继续加宽单次归约。同分 logits 的处理同样落在这一层：不稳定比较使相同输入在不同 batch 组合下路由到不同专家，服务端输出不可复现，定位成本极高，排序网络必须显式定义 tie-break。</p>\n<table class=\"mini\"><thead><tr><th>上游变化</th><th>路由侧响应</th><th>系统代价</th></tr></thead><tbody><tr><td>batch 增大（T 上升）</td><td>C 联动放大或接受丢弃</td><td>激活缓冲与 TMEM 占用上升</td></tr><tr><td>k 由 2 升至 4</td><td>归约轮次增加</td><td>专家 GEMM 与 All-to-All 线性抬升</td></tr><tr><td>长序列/领域偏移</td><td>热专家打满</td><td>丢弃或重路由分支，质量无告警劣化</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"app-t-ap-moe-router-terms\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>覆盖 top-k 门控、路由分数归一化、专家容量因子、token 丢弃与溢出重路由、负载均衡辅助损失在推理侧的…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-moe-router-terms · 共 5 个片段</p>\n"},{"id":"ap-capacity-factor","title":"容量因子与丢弃代价","summary":"容量因子决定每专家 token 上限，直接换算为分组 GEMM 的 M 维分块与显存占用；需说明丢弃率随 batch 与序列分布漂移的实测方法，以及在 NVL72 上因 All-to-All 不均衡导致的尾延迟放大机制。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-1\">一 · 条目定义：容量因子约束的是什么量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-2\">二 · 分类维度一：取值区间与溢出策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-3\">三 · 分类维度二：统计口径与流量分档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-4\">四 · 与 M 对齐的耦合：cf 不是线性扩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-5\">五 · NVL72 拓扑下的尾延迟放大：cf 的第三重身份</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-6\">六 · 速查表结构与分类落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-7\">七 · 容量因子的边界：从名义上限到对齐后的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-8\">八 · 速查表总览：七列字段与三档口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-9\">九 · 容量列与 M 对齐列：名义值与实际占用的换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-10\">十 · 丢弃率分桶列：按 batch 与序列长度双维记录</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-11\">十一 · 显存增量列与尾延迟放大列：两个必须联算的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-12\">十二 · 推荐流量档位列与填表检查清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-13\">十三 · 字段间的耦合关系与不可填组合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-14\">十四 · 速查表的字段口径与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-15\">十五 · 阈值不是常数：把 cf 拆成三个可测维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-16\">十六 · 丢弃率告警阈值：0.5%–1% 只是起点，口径才是关键</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-17\">十七 · NVL72 上的尾延迟放大：按最慢 rank 反推 cf</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-18\">十八 · 测量流程：从分桶统计到 cf 反推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-19\">十九 · 三个高频踩坑的量化识别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-20\">二十 · 阈值不是拍脑袋：把 cf 钉在可复现的测量链上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-21\">二十一 · 踩坑一：用平均负载选 cf，丢弃只在 P99 上现形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-22\">二十二 · 踩坑二：把 cf 当线性扩容，忽略 M 对齐 padding</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-23\">二十三 · 踩坑三：单卡视角调 cf，NVL72 上最慢 rank 决定整批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-24\">二十四 · 检查顺序：从统计口径到拓扑，逐层收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-25\">二十五 · 回滚方案：cf 变更必须可逆且带观测锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-26\">二十六 · 容量因子调参的失效边界与上线检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-27\">二十七 · 踩坑清单：三个失效点、检查顺序与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-28\">二十八 · 上游依赖：容量因子挂在哪些条目上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-29\">二十九 · 下游影响：cf 决定谁的分块、谁的尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-30\">三十 · 与量化条目的耦合：cf 影响的是数值路径的选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-31\">三十一 · 与调度、分离式架构的接口：cf 是批调度的一个约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-32\">三十二 · 在全书中的位置：cf 是容量规划的一个乘子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-capacity-factor-sec-33\">三十三 · 容量因子在全书中的位置：上游约束、下游放大与失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-capacity-factor\"><svg style=\"max-width:504px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 504.4 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"422.4\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：容量因子与丢弃代价</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">容量因子决定每专家 token 上限，直接换算为分组 GEMM 的 M 维</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">分块…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"422.4\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">需说明丢弃率随 batch 与序列分布漂移的实测方法，以及在 </text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">NVL72 上因…</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-capacity-factor-sec-1\">一 · 条目定义：容量因子约束的是什么量</h3>\n<p>容量因子（capacity factor，cf）在 MoE 推理里不是“专家并行度”也不是“负载均衡系数”，它只回答一个可被内核直接消费的问题：<strong>每个专家在一次前向中最多接收多少 token</strong>。给定批内 token 总数 T、每 token 选中的专家数 k、专家总数 E，每专家容量上限写成</p>\n<div class=\"formula\">$$C = \\mathrm{cf} \\times \\frac{T \\cdot k}{E}$$</div>\n<p>括号内那项是“均匀路由假设下的期望负载”，cf 是对这个期望值的放大倍数。注意 C 是<em>硬上限</em>而非软目标：路由 kernel 在写出 dispatch 索引时就要按 C 截断，超出部分走溢出策略。因此 cf 一旦确定，它同时锁死了三件事——分组 GEMM 的 M 维上界、专家激活缓冲区的预留尺寸、以及 All-to-All dispatch 阶段每个目的地的接收队列深度。这三者耦合在一起，是 cf 区别于其他调度旋钮的根本特征。</p>\n<p>把它与相邻概念切开：cf 不是 <em>token 丢弃阈值</em>（后者是 cf 的后果，由溢出策略决定）；不是 <em>专家并行度</em>（EP 决定专家放在哪张卡，cf 决定每张卡上每个专家处理多少 token）；也不是 <em>分组 GEMM 的分块大小</em>（M 对齐粒度是硬件约束，cf 是上层业务参数，二者通过 padding 相互作用）。工程上最常见的混淆是把 cf 当作“吞吐旋钮”来调——调大 cf 并不增加算力，只增加可接纳的 token 数上限与随之而来的显存占用；真正决定吞吐的是分组 GEMM 的有效 M 与 All-to-All 的实际流量。</p>\n\n<h3 id=\"ap-capacity-factor-sec-2\">二 · 分类维度一：取值区间与溢出策略</h3>\n<p>推理场景常用 cf 落在 1.0–1.25。这个区间的含义很具体：cf=1.0 表示严格按期望负载截断，任何路由倾斜都会立即产生丢弃；cf=1.25 给出 25% 的倾斜余量，代价是激活缓冲区按 1.25 倍预留。分类上先看<strong>是否允许丢弃</strong>：允许丢弃时 cf 是纯容量参数，超出即丢；不允许丢弃时 cf 必须配合溢出策略，此时 cf 更像“快速路径容量”，溢出 token 走慢速路径。</p>\n<p>溢出策略本身构成第二层分类，三种典型做法代价完全不同：</p>\n<ul>\n<li><strong>丢弃</strong>：超出容量的 token 不进入该专家 GEMM，输出按零或残差直通。实现最简，dispatch 队列有界，显存可精确预留；代价是数值上损失了这部分专家的贡献，丢弃率直接映射为质量损失。</li>\n<li><strong>重路由</strong>：把溢出 token 改派到次优专家。避免了零输出，但破坏了路由决策的一致性，且次优专家可能同样打满，形成级联溢出；dispatch 阶段需要二次寻址，All-to-All 消息数上升。</li>\n<li><strong>残差直通</strong>：溢出 token 跳过 MoE 层、以残差形式穿过。数值上等价于该层退化为恒等映射，对深层网络比置零温和，但会让不同 token 的有效深度不一致。</li>\n</ul>\n<p>举例：一个 T=8192、k=2、E=64 的批，期望负载为 256 token/专家；cf=1.0 时 C=256，若某热专家收到 400 个 token，则 144 个 token 触发溢出。若选丢弃且这些 token 恰好集中在长序列请求上，损失会沿序列位置累积，而平均指标几乎看不出来——这正是丢弃代价必须按分桶统计而非按全局均值评估的原因。</p>\n\n<h3 id=\"ap-capacity-factor-sec-3\">三 · 分类维度二：统计口径与流量分档</h3>\n<p>cf 的选值必须绑定统计口径，否则同一个 cf 在不同流量下表现差异巨大。丢弃率随 batch 大小与序列长度分布漂移：短 batch 下路由结果的方差大，单批内专家负载可能极端倾斜；长序列下热专家集中效应更强，因为序列内 token 的路由相关性高。同一 cf 在不同流量档位下丢弃率可相差数倍，这不是噪声而是分布特性。</p>\n<p>因此分类上要区分<strong>按 batch 分桶</strong>与<strong>按序列长度分桶</strong>两种口径，并在路由 kernel 输出处直接统计：每专家实际接收 token 数与容量上限之比，按桶记录溢出计数。伪代码思路是——</p>\n<ul>\n<li>路由 kernel 写出 dispatch 索引时，对每个专家维护一个原子计数器 <em>recv[e]</em>；</li>\n<li>截断逻辑执行后，<em>overflow[e] = max(0, recv[e] − C)</em>，按当前 batch 尺寸与序列长度桶累加；</li>\n<li>离线聚合得到每个桶的丢弃率分布，取 P99 尾延迟对应流量档位的丢弃率反推所需 cf，而不是用平均负载估算。</li>\n</ul>\n<p>系统代价在这里体现为：统计本身要在路由 kernel 里加原子操作与桶标记，属于热路径开销；但相比用平均负载选 cf 导致的线上溢出，这点开销可忽略。工程阈值上，丢弃率告警常设在 0.5%–1%，超过即说明当前 cf 与流量档位不匹配。分类维度里还应记录<strong>部署拓扑</strong>：单机 NVLink 域内与跨域 IB 的 All-to-All 行为不同，同一 cf 在两种拓扑下的尾延迟表现不可互推。</p>\n\n<h3 id=\"ap-capacity-factor-sec-4\">四 · 与 M 对齐的耦合：cf 不是线性扩容</h3>\n<p>cf 最容易被误读的一点是它与分组 GEMM 的 M 维对齐耦合。每专家的实际 M 会被 padding 到 MMA 的 M 对齐粒度（常见 64 或 128），因此 cf 略大于 1 时，显存占用不是按 cf 比例线性增长，而是被对齐向上取整放大。设对齐粒度为 a，则每专家实际占用的 M 为</p>\n<div class=\"formula\">$$M_{\\text{pad}} = a \\cdot \\left\\lceil \\frac{C}{a} \\right\\rceil$$</div>\n<p>当 C 从 256 提到 320（cf 1.0→1.25，E=64 场景），若 a=128，则 M_pad 从 256 变为 384，实际增幅 50%，远高于 cf 名义上的 25%。E 越大、C 越接近对齐边界，这种 padding 浪费越显著。激活缓冲区按 E×C×hidden 预留，cf 从 1.0 提到 1.25 在 E 较大时增加约 25% 的专家激活显存；若同时增大 M 对齐 padding，实际增幅高于 cf 比例，必须与 KV cache 预算联合核算——在很多部署里显存会先于算力耗尽。</p>\n<p>分类上因此要增加一列“是否与 M 对齐耦合”：耦合时 cf 的显存代价要用 M_pad 而非 C 计算；解耦时（例如用变长分组 GEMM 不做统一 padding）cf 的显存代价接近线性，但内核实现复杂度上升。这一维度直接决定容量规划时该用哪条公式，是 cf 分类里最容易被工程团队忽略的一项。</p>\n\n<h3 id=\"ap-capacity-factor-sec-5\">五 · NVL72 拓扑下的尾延迟放大：cf 的第三重身份</h3>\n<p>在 GB200/GB300 NVL72 这类机架级部署上，cf 还有第三重身份：它决定 All-to-All 的不均衡程度，进而决定整批完成时间。机制是明确的——某专家打满后，其所在 GPU 的 dispatch 流量骤降，而其他 GPU 仍在等待；combine 阶段又需等最慢专家完成。机架内 NVLink 域带宽虽高于跨域 IB，但集合通信按最慢 rank 同步，单专家热点即拖慢整批，而非只影响该卡。</p>\n<p>这意味着 cf 的分类必须包含<strong>部署拓扑</strong>维度：单机 NVLink 域内，热点专家的放大效应主要来自集合通信同步；跨域 IB 场景下，带宽下降与同步开销叠加，同一 cf 的尾延迟放大更严重。工程判断上，NVL72 上不能按单 GPU 视角调 cf——单卡吞吐评估会低估热点专家的全局影响，因为最慢 rank 决定整批完成时间。量化数字未给出，但机制上可以确定：cf 越接近 1.0，热点专家越容易打满，dispatch 流量骤降的 rank 越多，尾延迟放大系数越高。</p>\n<p>具体例子：一个跨 8 卡的批，某专家在 rank 3 上打满，rank 3 的 dispatch 队列提前清空进入等待，其余 7 卡继续发送；combine 阶段所有卡等 rank 3 的专家 GEMM 完成。若该专家 M_pad 因对齐被拉到 384 而实际只需 200，rank 3 的计算时间被 padding 拉长，整批尾延迟随之上升——cf、对齐、拓扑三者在同一条链上。</p>\n\n<h3 id=\"ap-capacity-factor-sec-6\">六 · 速查表结构与分类落地</h3>\n<p>把上述维度落成一张可查的表，列应包括：cf 取值、对应每专家容量公式、M 维对齐粒度与 padding 浪费、实测丢弃率分桶、激活显存增量、NVL72 尾延迟放大系数、推荐流量档位。这张表的作用不是给出一组“最优 cf”，而是让工程团队在给定流量档位与拓扑时能反查出该 cf 的丢弃代价与显存代价，避免用平均负载选值。</p>\n<table class=\"mini\"><thead><tr><th>分类维度</th><th>取值/口径</th><th>对 cf 选择的约束</th></tr></thead><tbody>\n<tr><td>cf 取值区间</td><td>1.0–1.25</td><td>越接近 1.0 丢弃风险越高，越接近 1.25 显存代价越高</td></tr>\n<tr><td>是否允许丢弃</td><td>允许 / 不允许</td><td>不允许时必须配溢出策略，cf 退化为快速路径容量</td></tr>\n<tr><td>溢出策略</td><td>丢弃 / 重路由 / 残差直通</td><td>重路由增加 All-to-All 消息数，丢弃最省显存</td></tr>\n<tr><td>统计口径</td><td>按 batch / 按序列长度分桶</td><td>必须用 P99 流量档位反推，禁用平均负载</td></tr>\n<tr><td>部署拓扑</td><td>单机 NVLink 域 / 跨域 IB</td><td>NVL72 上按最慢 rank 评估，不按单卡</td></tr>\n<tr><td>M 对齐耦合</td><td>耦合 / 解耦</td><td>耦合时显存按 M_pad 算，增幅高于 cf 比例</td></tr>\n</tbody></table>\n<p>分类落地的关键判断是：cf 的三个代价——丢弃率、激活显存、尾延迟放大——分别由统计口径、M 对齐、拓扑三个维度主导，任何一个维度缺失都会让容量规划失真。最常见的踩坑正是只填了 cf 取值一列就下结论：按训练平均 token 分布设定 cf，线上长序列集中命中少数专家，溢出丢弃率远超预期且只在尾延迟指标上可见；或只算 cf 对激活缓冲区的比例增长，忽略 M 向对齐粒度的向上取整，E 大时 padding 浪费使显存显著高于名义增幅。分类表的价值就在于强制这三个维度同时被记录，使 cf 从“一个数字”变成“一组带口径的约束”。</p>\n\n<h3 id=\"ap-capacity-factor-sec-7\">七 · 容量因子的边界：从名义上限到对齐后的真实代价</h3>\n<p>容量因子（cf）在条目中不是一个抽象旋钮，而是把路由统计直接翻译成硬件资源约束的换算系数：$$C = \\mathrm{cf} \\times \\frac{T \\cdot k}{E}$$，其中 T 为本批 token 数、k 为每 token 选中的专家数、E 为专家总数。这个上限一旦落到分组 GEMM 上，就不再是连续的实数——每专家的 M 维必须向上取整到 MMA 的 M 对齐粒度（常见 64 或 128），于是 cf 略大于 1 时，激活缓冲区的增长不是线性的 cf 比例，而是被 padding 放大的阶梯函数。E 较大时，每个专家即使只溢出几个 token，也会整块占用一个对齐单元，cf 从 1.0 提到 1.25 的名义 25% 增幅在显存账本上会被显著抬高。因此本条目把 cf 的“边界”定义为三重耦合：取值区间（推理常用 1.0–1.25）、M 对齐粒度、以及激活缓冲区按 E×C×hidden 预留的显存预算。任何把 cf 当作线性扩容手段的做法，都会先在显存上撞墙，而不是在算力上。</p>\n<p>分类维度决定了这个边界在不同部署形态下的失效方式。按是否允许丢弃可分为零丢弃（cf 取足够大、以显存换确定性）与允许丢弃（溢出 token 不进入该专家 GEMM，输出按零或残差直通）；按溢出策略可分为丢弃、重路由、残差直通，三者的尾延迟特征完全不同——重路由会把热点从专家搬到通信层，残差直通则把精度损失藏进输出分布而非时延指标。按统计口径分为按 batch 分桶与按序列长度分桶，这一维度直接决定 cf 是否可信：丢弃率随 batch 大小与序列长度分布漂移，短 batch 下方差大，长序列下热专家集中，同一 cf 在不同流量下丢弃率可相差数倍。按部署拓扑分为单机 NVLink 域与跨域 IB，前者受 All-to-All 最慢 rank 同步约束，后者还叠加 IB 带宽与拥塞。与相邻概念的区别在于：cf 不是批调度参数（它不改变 token 的到达顺序），也不是 KV cache 的分配粒度，而是路由层与 GEMM 层之间的容量契约；丢弃代价则是这份契约被违反时的账单，且只在 P99 尾延迟上可见。</p>\n<p>失效条件集中在三类工程误判。其一是用平均负载而非 P99 流量选 cf：线上长序列请求集中命中少数专家，溢出丢弃率远超按均值估算的结果，而平均延迟几乎不动，告警阈值（常设 0.5%–1%）只在尾部分桶里才被触发。其二是只算 cf 对激活缓冲区的比例增长，忽略每专家 M 向对齐粒度的向上取整，E 大时 padding 浪费使显存占用显著高于 cf 名义增幅，KV cache 预算被挤压后并发下降，吞吐反而倒退。其三是在 NVL72 多机部署中按单卡视角调 cf：某专家打满后其所在 GPU 的 dispatch 流量骤降，其他 GPU 仍在等待，combine 阶段又需等最慢专家完成，机架内 NVLink 域虽带宽高，但集合通信按最慢 rank 同步，单专家热点把整批尾延迟放大而非仅影响该卡。对应的系统代价可写成一句判断：cf 的每一次上调都在用激活显存与对齐 padding 换取丢弃率的下降，而在 NVLink 域内，收益还被最慢 rank 的同步开销折价。</p>\n<table class=\"mini\"><thead><tr><th>cf 取值</th><th>每专家容量</th><th>M 对齐与 padding</th><th>激活显存</th><th>NVL72 尾延迟</th></tr></thead><tbody><tr><td>1.0</td><td>基准上限</td><td>对齐后仍有阶梯浪费</td><td>基准</td><td>热点专家直接放大</td></tr><tr><td>1.25</td><td>上限提高 25%</td><td>padding 使实际增幅高于 25%</td><td>约增 25% 起</td><td>缓解溢出但同步开销仍在</td></tr></tbody></table>\n<p>实测方法因此必须落在路由 kernel 输出处：统计每专家实际接收 token 数与容量上限之比，按 batch 与序列长度分桶记录溢出计数，再以 P99 尾延迟对应的流量档位反推所需 cf，而不是用平均负载估算。这条路径的边界在于它只观测“已发生”的溢出，对突发长序列的预测依赖分桶粒度；粒度太粗会把热点平滑掉，太细则样本不足。工程判断是：cf 的选型应以 P99 档位的溢出计数为约束、以 M 对齐后的激活显存为预算上限，两者同时满足才允许上调，否则优先改路由或重路由策略而非继续加 cf。</p>\n<h3 id=\"ap-capacity-factor-sec-8\">八 · 速查表总览：七列字段与三档口径</h3>\n<p>本表面向“拿到一个 MoE 推理配置，能否直接照着填参数”的场景。七列依次为：cf 取值、每专家容量、M 维对齐与 padding 浪费、实测丢弃率分桶、激活显存增量、NVL72 尾延迟放大系数、推荐流量档位。前四列是配置输入，后三列是代价输出，必须成对填写——只填 cf 不填后三列，等于把容量因子当成一个孤立旋钮，这正是失败模式的起点。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>字段</th><th>取值/口径</th><th>判定阈值</th><th>工程含义</th></tr>\n</thead>\n<tbody>\n<tr><td>cf 取值</td><td>1.0 / 1.05 / 1.125 / 1.25</td><td>区间 1.0–1.25</td><td>超过 1.25 需先证明 P99 流量确实需要</td></tr>\n<tr><td>每专家容量</td><td>$$C=\\mathrm{cf}\\cdot T k/E$$</td><td>按 batch 实际 T 计算，不用均值</td><td>容量是分组 GEMM 的 M 上界</td></tr>\n<tr><td>M 对齐粒度</td><td>64 或 128</td><td>padding 浪费率 = 对齐后 M / 实际 M − 1</td><td>cf 名义增幅与显存实际增幅脱钩</td></tr>\n<tr><td>实测丢弃率</td><td>按 batch 桶 × 序列长度桶</td><td>告警 0.5%–1%</td><td>用 P99 流量档位反推 cf</td></tr>\n<tr><td>激活显存增量</td><td>$$E\\cdot C\\cdot \\text{hidden}$$</td><td>与 KV cache 预算联合核算</td><td>cf 1.0→1.25 在 E 大时约增 25%，叠加 padding 更高</td></tr>\n<tr><td>尾延迟放大系数</td><td>定性：单专家热点拖慢整批</td><td>按最慢 rank 同步判定</td><td>NVL72 内 NVLink 域带宽高不救同步开销</td></tr>\n<tr><td>推荐流量档位</td><td>短 batch / 长序列 / 混合突发</td><td>按 P99 而非均值选档</td><td>同一 cf 在不同档位丢弃率相差数倍</td></tr>\n</tbody>\n</table>\n<p>口径上有一条硬规则：容量与丢弃率必须来自同一批线上流量样本，且样本要覆盖至少一个完整的突发周期。若容量按离线平均 token 分布算、丢弃率按线上 P99 算，两列数字不可比，表就失去意义。</p>\n\n<h3 id=\"ap-capacity-factor-sec-9\">九 · 容量列与 M 对齐列：名义值与实际占用的换算</h3>\n<p>容量列填的是 cf 乘出的 token 上限，但对齐列才是显存与算力的真实入口。分组 GEMM 把每专家 M 向上取整到 MMA 的 M 对齐粒度（常见 64 或 128），因此实际参与计算的 M 为：</p>\n<div class=\"formula\">$$M_{\\text{padded}} = \\left\\lceil \\frac{C}{a} \\right\\rceil a,\\quad a \\in \\{64,128\\}$$</div>\n<p>浪费率为 $M_{\\text{padded}}/M_{\\text{actual}}-1$。当 E 很大、单专家实际 token 数落在对齐粒度之下时，cf 从 1.0 提到 1.125 可能只让名义容量涨 12.5%，却因为跨过一个对齐边界而使 padding 后 M 跳一整档，显存增幅显著高于名义比例。速查表填写时，对齐列必须写出“当前 batch 下每专家实际 M 落在哪个对齐区间”，而不是只写粒度数字。</p>\n<p>代价落在两处：激活缓冲区按 $E\\cdot C\\cdot \\text{hidden}$ 预留，cf 提高直接抬升这块显存；同时 padding 后的 M 决定分组 GEMM 的 tile 数与 Tensor Core 占用时长，padding 浪费即算力浪费。工程判断是：先算 padding 浪费率，若已高于丢弃率带来的收益，提 cf 就是亏的——显存先于算力耗尽，这是最常见的踩坑路径。</p>\n<p>具体例子：某层 E 较大、单专家实际接收 token 数略低于 64 时，cf 从 1.0 提到 1.125 使容量跨过 64 边界，M 被 padding 到 128，激活显存接近翻倍而非增 12.5%；此时若丢弃率仅 0.3%，提 cf 明显不划算，应改为溢出重路由或残差直通。</p>\n\n<h3 id=\"ap-capacity-factor-sec-10\">十 · 丢弃率分桶列：按 batch 与序列长度双维记录</h3>\n<p>丢弃率列不能填一个标量。口径是：在路由 kernel 输出处统计每专家实际接收 token 数与容量上限之比，按 batch 大小分桶、按序列长度分桶，交叉记录溢出计数。原因在事实里写得很清楚——短 batch 下方差大，长序列下热专家集中，同一 cf 在不同流量下丢弃率可相差数倍。单桶平均值会把突发档位的溢出抹平。</p>\n<p>伪代码思路：</p>\n<ul>\n<li>路由 kernel 末尾对每个专家累加 <code>recv[e]</code>，与 <code>cap[e]</code> 比较得 <code>overflow[e] = max(0, recv[e]-cap[e])</code>；</li>\n<li>按 <code>(batch_bucket, seqlen_bucket)</code> 二维键聚合 <code>sum(overflow)/sum(recv)</code>；</li>\n<li>取 P99 尾延迟对应的流量档位，读该档位的丢弃率，反推满足告警阈值所需 cf。</li>\n</ul>\n<p>告警阈值常设在 0.5%–1%，但这是工程惯例而非统一标准，填表时应注明本部署的实际阈值来源。代价侧：丢弃率本身不直接产生延迟，但它通过“被丢弃 token 走零或残差直通”改变输出质量，同时溢出计数是判断 cf 是否够用的唯一线上信号。若只看平均负载，长序列请求集中命中少数专家时溢出丢弃率远超预期，且只在尾延迟指标上可见——这正是失败模式的第一条。</p>\n<p>具体例子：混合突发档位下，平均丢弃率 0.2% 看似安全，但按序列长度分桶后长序列桶丢弃率达 1.4%，已越过告警线；此时应针对长序列桶单独提 cf 或启用重路由，而不是全局抬 cf 让短 batch 桶白白多占显存。</p>\n\n<h3 id=\"ap-capacity-factor-sec-11\">十一 · 显存增量列与尾延迟放大列：两个必须联算的代价</h3>\n<p>显存增量列填 $E\\cdot C\\cdot \\text{hidden}$ 的相对变化，并注明是否已含 padding。事实给出：cf 从 1.0 提到 1.25 在 E 较大时增加约 25% 的专家激活显存；若同时增大 M 对齐 padding，实际增幅高于 cf 比例。这一列必须与 KV cache 预算联合核算——MoE 层的激活缓冲与注意力层的 KV cache 争同一块 HBM，cf 抬升挤压的是可服务的并发序列数。</p>\n<p>尾延迟放大列在单机 NVLink 域与跨域 IB 两种拓扑下口径不同。NVL72 上的机制是：某专家打满后其所在 GPU 的 dispatch 流量骤降，其他 GPU 仍在等待；combine 阶段又需等最慢专家完成；机架内 NVLink 域带宽虽高，但集合通信按最慢 rank 同步，单专家热点即拖慢整批。因此这一列不能填“该卡变慢”，而要填“整批完成时间由最慢 rank 决定”。量化数字事实未给出，填表时写定性判定并注明依据的 rank 同步路径。</p>\n<p>代价判断：显存增量是可预算的，尾延迟放大是不可预算的——前者能提前算，后者只能在线上按 P99 观测。所以速查表的填写顺序应是先定流量档位与丢弃率阈值，再回填 cf，最后核显存；反过来先定 cf 再找理由，必然踩“按单 GPU 视角调 cf”的坑。</p>\n<p>具体例子：NVL72 多机部署中按单卡吞吐评估容量，单卡看似余量充足，但某专家热点使该 rank 的 combine 迟迟不完，整批尾延迟被放大；此时正确动作是降 cf 减少热点专家的排队深度，或对该专家做重路由分流，而非给热点卡加资源。</p>\n\n<h3 id=\"ap-capacity-factor-sec-12\">十二 · 推荐流量档位列与填表检查清单</h3>\n<p>流量档位列把前三列的口径锚定到具体场景：短 batch 档看方差，长序列档看热专家集中度，混合突发档看 P99。同一 cf 在这三档下的丢弃率可相差数倍，因此档位列必须与丢弃率分桶列一一对应，不能跨档引用数字。</p>\n<p>填表后的检查清单，按顺序执行：</p>\n<ul>\n<li>容量是否用该档位实际 T 计算，而非训练平均 token 分布；</li>\n<li>对齐列是否给出 padding 浪费率，而非只写 64/128；</li>\n<li>丢弃率是否按 batch × 序列长度双维分桶，且取自 P99 流量档位；</li>\n<li>显存增量是否含 padding 并已与 KV cache 预算对账；</li>\n<li>尾延迟列是否按最慢 rank 同步口径填写，拓扑标明单机 NVLink 域或跨域 IB；</li>\n<li>cf 是否落在 1.0–1.25，超出部分是否有 P99 流量证据支撑。</li>\n</ul>\n<p>任何一项缺失，该行配置不可直接上线。检查清单本身就是速查表的“口径”部分——字段名相同但口径不同的两张表，数字不可互相引用。</p>\n<p>具体例子：某配置表 cf 填 1.25、丢弃率填 0.3%、显存增量填 +25%，看似自洽；但核对后发现丢弃率取自短 batch 档、显存增量未含 padding、尾延迟按单卡口径填。三项口径错位，实际长序列档丢弃率与整批尾延迟均未覆盖，该行应作废重填。</p>\n\n<h3 id=\"ap-capacity-factor-sec-13\">十三 · 字段间的耦合关系与不可填组合</h3>\n<p>速查表的七列不是独立旋钮，存在硬耦合：cf 与容量是定义关系，容量与对齐列是取整关系，对齐列与显存增量是乘性关系，丢弃率与流量档位是条件关系，尾延迟放大与拓扑是判定关系。填表时若某一列改动，必须回溯检查与之耦合的列是否仍成立。</p>\n<p>不可填组合有三类，直接判为配置错误：</p>\n<ul>\n<li>cf 提高但对齐列 padding 浪费率未重算——名义扩容掩盖实际显存跳档；</li>\n<li>丢弃率填全局均值而流量档位填 P99——两列口径不一致，反推的 cf 无意义；</li>\n<li>NVL72 部署下尾延迟列填单卡增量——忽略 All-to-All 最慢 rank 同步，容量评估系统性偏乐观。</li>\n</ul>\n<p>耦合的工程含义是：容量因子从来不是单层参数，它同时决定分组 GEMM 的 M 分块、激活显存预留、以及集合通信的同步等待长度。把 cf 当线性扩容旋钮，等于假设这三者都线性——而事实是 padding 取整与 rank 同步都非线性。</p>\n<p>具体例子：E 较大时把 cf 从 1.0 提到 1.25，容量列涨 25%、显存列因 padding 实际涨更多、尾延迟列因热点专家排队变长而恶化；三列同时变差而丢弃率仅从 0.8% 降到 0.5%，收益不足以抵消代价，正确判断是维持 cf 并对溢出 token 走残差直通，把容量压力从显存转移到输出质量的可控损失上。</p>\n\n<h3 id=\"ap-capacity-factor-sec-14\">十四 · 速查表的字段口径与失效边界</h3>\n<p>这张表不是配置推荐，而是把容量因子从“一个标量”拆成七个必须同时填的字段，任何一格留空都意味着某个代价没被核算。列定义如下：cf 取值（推理常用 1.0–1.25）；每专家容量 $$C = \\mathrm{cf} \\times \\frac{T \\cdot k}{E}$$；M 维对齐粒度（常见 64 或 128）与由此产生的 padding 浪费；实测丢弃率按 batch 与序列长度分桶；激活显存增量；NVL72 尾延迟放大系数；推荐流量档位。口径上有一条硬约束：丢弃率一栏必须填 P99 流量档位下的溢出计数比，而不是均值——均值口径会把突发长序列命中的热专家溢出抹平，使 cf 选小一档，问题只在尾延迟指标上现形。表里每一行对应一种溢出策略（丢弃、重路由、残差直通），策略不同则丢弃代价的语义不同：丢弃是输出置零，残差直通是把该 token 的输出退回残差路径，两者对下游精度的影响不可混算。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径</th><th>失效条件</th></tr></thead><tbody><tr><td>cf</td><td>1.0–1.25，按 P99 档位反推</td><td>按训练平均分布设定</td></tr><tr><td>C</td><td>T·k/E 乘 cf</td><td>T 取均值而非峰值</td></tr><tr><td>M 对齐</td><td>64 或 128，向上取整</td><td>把 cf 增幅当线性扩容</td></tr><tr><td>丢弃率</td><td>分桶溢出计数，告警 0.5%–1%</td><td>只统计全局平均</td></tr><tr><td>激活显存</td><td>E×C×hidden 预留</td><td>不与 KV cache 联合核算</td></tr><tr><td>尾延迟放大</td><td>按最慢 rank 同步估算</td><td>按单卡视角调 cf</td></tr></tbody></table>\n<p>对齐粒度是本表最容易被跳过的一格。cf 从 1.0 提到 1.25，在 E 较大时专家激活缓冲区名义上增加约 25%，但每专家 M 会被 padding 到 64 或 128 的整数倍，实际占用是向上取整后的值，增幅高于 cf 比例；E 越大、单专家实际 token 越少，padding 浪费占比越高。因此这一格必须写成“对齐后 M 与对齐前 M 的比值”，而不是写 cf 本身。显存核算的次序也要固定：先算对齐后的激活缓冲区，再与 KV cache 预算相加，否则会出现算力尚有余额而显存先耗尽的局面——这是把 cf 当线性扩容的直接后果。</p>\n<p>尾延迟放大系数一栏只在部署拓扑为 NVL72 多机时填写，单机 NVLink 域内可留空。其机制是 All-to-All 的集合通信按最慢 rank 同步：某专家打满后，其所在 GPU 的 dispatch 流量骤降，其余 GPU 仍在等待，combine 阶段又要等最慢专家完成，于是单专家热点拖慢整批，而非只影响那一张卡。这一格的取值应写成“整批完成时间相对无热点时的比值”，用最慢 rank 的等待时间估算，不能按单卡吞吐折算。跨域 IB 拓扑下该系数另计，因为域内 NVLink 带宽高于跨域 IB，热点在域内被吸收的速度与跨域不同。表填完后做一次交叉校验：若丢弃率落在告警区间而尾延迟放大系数明显大于 1，说明 cf 应按 P99 档位上调而非按均值下调；若激活显存增量已逼近预算而丢弃率仍低，则应改溢出策略为重路由或残差直通，而不是继续抬 cf。</p>\n<h3 id=\"ap-capacity-factor-sec-15\">十五 · 阈值不是常数：把 cf 拆成三个可测维度</h3>\n<p>工程上把容量因子当成一个旋钮（1.0 到 1.25 之间拧一下）是常见误用。真正决定行为的不是 cf 这个标量，而是它同时约束的三件事：每专家 token 上限 <span class=\"formula\">$$C = \\mathrm{cf}\\cdot\\frac{T\\cdot k}{E}$$</span>、分组 GEMM 的 M 维分块、以及激活缓冲区预留量 <span class=\"formula\">$$B_{\\text{act}} \\approx E \\cdot \\lceil C \\rceil_{\\text{align}} \\cdot h \\cdot b$$</span>（h 为 hidden，b 为每 token 字节数）。三者对 cf 的敏感度不同：C 线性，M 分块因对齐呈阶梯，显存则被对齐向上取整放大。因此调 cf 时必须分别记录“名义 cf”“有效 M 对齐后容量”“实际预留显存”三个数，否则会把阶梯误读成线性。</p>\n<p>具体机制上，每专家 M 被 padding 到 MMA 的 M 对齐粒度（常见 64 或 128）。若某专家实际收到 130 个 token、对齐粒度为 128，则 M 被抬到 256，浪费接近一倍。E 越大，这种向上取整在总激活显存中的占比越高——cf 从 1.0 提到 1.25 名义上增加 25%，叠加对齐后实际增幅高于该比例，需与 KV cache 预算联合核算，而不是单独看激活缓冲。</p>\n<p>代价侧要分清：cf 抬高直接吃显存与 HBM 带宽（更多 token 进入 GEMM、更多中间激活写回），但不改变 All-to-All 的通信量下限；cf 压低则把代价转移到丢弃率与输出质量。一个具体例子：E=64、hidden 较大、对齐 128 时，把 cf 从 1.0 调到 1.1，名义容量只涨 10%，但若热专家恰好跨过对齐边界，该专家 M 翻倍，单卡激活占用跳变远大于 10%，此时显存先于算力成为瓶颈。</p>\n\n<h3 id=\"ap-capacity-factor-sec-16\">十六 · 丢弃率告警阈值：0.5%–1% 只是起点，口径才是关键</h3>\n<p>业界常把丢弃率告警设在 0.5%–1%，但该区间没有统一标准，直接套用会误导。原因是丢弃率的统计口径决定数值大小：按整批平均、按序列分桶、按专家分桶、按 P99 流量档位统计，同一 cf 下可相差数倍。短 batch 方差大，长序列下热专家集中，因此“平均丢弃率 0.3%”完全可能掩盖某流量档位下 3% 的瞬时溢出。</p>\n<p>正确的测量方法是在路由 kernel 输出处直接统计每专家实际接收 token 数与容量上限之比，按 batch 大小与序列长度分桶记录溢出计数，形成二维直方图，再以 P99 尾延迟对应的流量档位反推所需 cf，而不是用平均负载估算。伪代码思路：</p>\n<div class=\"formula\">$$\\text{for each (batch\\_bucket, seq\\_bucket): } \\rho = \\frac{\\#\\{\\text{overflow tokens}\\}}{\\#\\{\\text{routed tokens}\\}};\\ \\text{alert if } \\rho_{P99} &gt; \\tau$$</div>\n<p>告警阈值 τ 应绑定 SLO 而非固定值：若丢弃 token 走残差直通、对质量影响可接受，τ 可放宽；若丢弃直接置零且落在关键层，τ 需收紧到 0.5% 以下。代价上，统计本身几乎免费（路由 kernel 里加计数器），但分桶记录会引入少量原子操作与日志带宽；若在 NVL72 上跨 rank 聚合，需注意聚合频率不要与 All-to-All 争抢 NVLink 域带宽。</p>\n<p>具体例子：同一 cf=1.1，短 batch（T 小）下每专家容量小、方差主导，丢弃率可能在个别 batch 冲到 2%；长序列集中命中少数专家时，热专家溢出率持续偏高。两者平均后看似 0.6%，但 P99 档位已越过 1% 告警线——这正是“只在尾延迟指标上可见”的失败模式。</p>\n\n<h3 id=\"ap-capacity-factor-sec-17\">十七 · NVL72 上的尾延迟放大：按最慢 rank 反推 cf</h3>\n<p>在 NVL72 机架内，NVLink 域带宽高于跨域 IB，但集合通信按最慢 rank 同步。某专家打满后，其所在 GPU 的 dispatch 流量骤降，而其他 GPU 仍在等待；combine 阶段又必须等最慢专家完成。结果是单专家热点拖慢整批，而非仅影响该卡。量化放大系数未给出统一数字，但机制上可写成 <span class=\"formula\">$$L_{\\text{batch}} \\approx \\max_{r}\\left(L_r^{\\text{dispatch}} + L_r^{\\text{GEMM}} + L_r^{\\text{combine}}\\right)$$</span>，即整批完成时间由最慢 rank 决定，容量不足的专家通过这一 max 把局部溢出放大为全局尾延迟。</p>\n<p>因此 NVL72 上选 cf 的正确姿势是：以“最慢 rank 的专家溢出”为约束，而不是以单卡平均吞吐为约束。测量方法是按 rank 记录每专家溢出计数与 dispatch/combine 等待时间，找出 P99 尾延迟对应的热点专家，再反推该专家所需容量与 cf。代价上，cf 抬高会同步抬高所有 rank 的激活预留（E×C×hidden），在机架级显存核算中相当于整域扩容；而 cf 不足时，尾延迟放大让吞吐下降的幅度远超单卡视角的估算。</p>\n<p>具体例子：某专家在 decode 阶段被长序列请求集中命中，容量打满后该 rank 的 dispatch 流量塌陷，其余 rank 在 combine 处空等；此时即便平均丢弃率低于 0.5%，整批尾延迟仍被拉长。工程判断是：在 NVLink 域内优先用重路由或残差直通吸收溢出，把 cf 留给真正无法重路由的热点，而不是全局抬高 cf 让所有专家一起占显存。</p>\n\n<h3 id=\"ap-capacity-factor-sec-18\">十八 · 测量流程：从分桶统计到 cf 反推</h3>\n<p>没有现成数字时，测量流程应固定为四步，避免用平均负载拍脑袋。第一步，在路由 kernel 出口埋计数器，记录每专家接收 token 数、容量上限、溢出数，按 batch 与序列长度分桶。第二步，把分桶数据与端到端延迟对齐，取 P99 延迟对应的流量档位作为设计点。第三步，在该档位上计算各专家溢出率，找出超过告警阈值（0.5%–1%）的专家集合。第四步，对这些专家反推所需 cf：<span class=\"formula\">$$\\mathrm{cf}_{\\text{req}} = \\max_{e}\\frac{\\text{tokens}_e^{P99}}{T\\cdot k/E}$$</span>，再叠加 M 对齐粒度向上取整，得到实际显存增量。</p>\n<p>测量中要区分两种代价：统计开销（计数器、分桶、跨 rank 聚合）与实验开销（改 cf 重跑流量）。前者应常驻低开销，后者只在容量规划阶段做。一个具体做法是固定 batch 与序列长度分布，扫 cf ∈ {1.0, 1.1, 1.25}，记录每档的丢弃率分桶、激活显存、P99 尾延迟，形成速查表所需的列（cf 取值、容量公式、M 对齐 padding 浪费、实测丢弃率分桶、激活显存增量、尾延迟放大系数、推荐流量档位）。</p>\n<p>注意测量口径必须与部署拓扑一致：单机 NVLink 域与跨域 IB 的 All-to-All 不均衡表现不同，跨域 IB 下最慢 rank 的同步代价更高，同一 cf 的尾延迟放大更明显。若在单机上测得的 cf 直接搬到 NVL72 多机，会低估热点专家的全局影响。</p>\n\n<h3 id=\"ap-capacity-factor-sec-19\">十九 · 三个高频踩坑的量化识别</h3>\n<p>踩坑一：按训练平均 token 分布设定 cf。识别方法是比较训练分布与线上 P99 流量档位的专家命中直方图；若长序列请求集中命中少数专家，线上溢出丢弃率远超预期，且只在尾延迟指标上可见。对策是把 cf 的设计点从“平均”移到“P99 档位”，并用重路由兜底。</p>\n<p>踩坑二：只算 cf 对激活缓冲区的比例增长，忽略 M 向对齐粒度的向上取整。识别方法是同时打印名义容量与对齐后容量，计算 padding 浪费率 <span class=\"formula\">$$\\eta = 1 - \\frac{C}{\\lceil C\\rceil_{\\text{align}}}$$</span>；E 大时 η 显著，显存占用高于 cf 名义增幅。对策是把对齐粒度纳入容量规划，必要时调整每专家分块策略而非一味抬 cf。</p>\n<p>踩坑三：在 NVL72 多机部署中按单卡吞吐评估容量。识别方法是比较单卡视角的吞吐与整批尾延迟；若单专家热点把整批拖慢，说明集合通信以最慢 rank 同步。对策是以最慢 rank 的溢出为约束选 cf，并在 combine 前做溢出吸收，避免热点专家成为全局瓶颈。</p>\n<p>三个坑的共同点是“用平均值替代尾部分布”。工程上可操作的判断是：只要丢弃率告警按 P99 档位统计、显存核算按对齐后容量、cf 选择按最慢 rank 约束，容量因子就从经验数字变成可复现的工程阈值；反之，任何一项退回平均值口径，cf 的调整都会在尾延迟或显存上以非线性方式反噬。</p>\n\n\n<h3 id=\"ap-capacity-factor-sec-20\">二十 · 阈值不是拍脑袋：把 cf 钉在可复现的测量链上</h3>\n<p>工程上把 cf 落到 1.0–1.25 这个窄区间，靠的不是经验直觉，而是一条从路由 kernel 到 P99 尾延迟的闭环测量链。做法是在路由 kernel 输出处直接埋点：对每个专家统计实际接收 token 数 <em>n<sub>e</sub></em> 与容量上限 <em>C</em> 的比值，溢出计数按 batch 大小与序列长度两个维度分桶落盘，形成二维直方图而非单一均值。分桶的必要性来自方差结构：短 batch 下路由分布抖动大，同一 cf 在 batch 从几十跳到几百时丢弃率可相差数倍；长序列场景则相反，热专家集中度上升，均值掩盖了尖峰。因此选 cf 的正确输入是“目标流量档位下 P99 尾延迟所对应的溢出率”，而不是平均负载下的溢出率。告警线常设在 0.5%–1%，但这个数字必须绑定分桶口径才有意义——全局 0.8% 的丢弃率若全部来自长序列桶，说明该桶已越界，而短 batch 桶可能仍有余量。测量频率上，路由埋点本身开销极低（每专家一次原子累加），可以常开；真正昂贵的是把溢出率映射回尾延迟，需要按流量档位做阶梯压测，每档记录 P99 与溢出计数，反推出满足 SLO 的最小 cf。</p>\n<p>第二个边界在显存侧，且失效方式比多数人预期的更早。激活缓冲区按 <em>E</em>×<em>C</em>×hidden 预留，cf 从 1.0 提到 1.25 在专家数较大时名义上增加约 25% 专家激活显存；但每专家 M 维还要 padding 到 MMA 对齐粒度（常见 64 或 128），实际占用是 <em>E</em>×⌈<em>C</em>/<em>a</em>⌉×<em>a</em>×hidden，其中 <em>a</em> 为对齐粒度。当 <em>C</em> 落在对齐边界附近时，向上取整带来的浪费可以超过 cf 的名义增幅，<em>E</em> 越大绝对浪费越显著。这就是“把 cf 提高当作线性扩容”的典型翻车：算力预算尚有余量，显存却先耗尽，且耗尽点出现在 KV cache 与激活缓冲争抢同一预算的时刻。工程判断是：调 cf 前先算 padding 后的实际字节数，与 KV cache 预算联合核算，把 cf 的搜索空间限制在“padding 后增量可接受”的区间内，而不是先定 cf 再看显存。</p>\n<p>第三个边界在拓扑侧，也是 NVL72 上最容易被单卡视角掩盖的失效条件。某专家打满后，其所在 GPU 的 dispatch 流量骤降，而其他 GPU 仍在等待；combine 阶段又必须等最慢专家完成。机架内 NVLink 域带宽虽高于跨域 IB，但集合通信按最慢 rank 同步，单专家热点因此把整批尾延迟放大，而非只影响那一张卡。放大系数的量级取决于热点专家在 All-to-All 中的占比与该 rank 的等待时长，量化数字需按实际拓扑压测获得，不能从单卡吞吐外推。由此得出一个部署判据：单机 NVLink 域内调 cf 可以相对激进，因为同步惩罚被高带宽部分吸收；跨域 IB 部署则必须按最慢 rank 的完成时间选 cf，并优先考虑溢出策略从“丢弃”切到“重路由或残差直通”以削平热点。下表给出把上述三条边界收进同一张核算表的列结构，供压测时逐档填写。</p>\n<table class=\"mini\"><thead><tr><th>核算列</th><th>填写口径</th><th>失效信号</th></tr></thead><tbody><tr><td>cf 取值</td><td>1.0–1.25 内逐档扫描</td><td>名义增幅与实测显存增量背离</td></tr><tr><td>每专家容量</td><td><em>C</em>=cf·<em>T</em>·<em>k</em>/<em>E</em></td><td>—</td></tr><tr><td>M 对齐 padding</td><td>⌈<em>C</em>/<em>a</em>⌉·<em>a</em>，<em>a</em>∈{64,128}</td><td>padding 浪费超过 cf 增幅</td></tr><tr><td>分桶丢弃率</td><td>按 batch×序列长度统计溢出比</td><td>长序列桶越过 0.5%–1%</td></tr><tr><td>尾延迟放大</td><td>按最慢 rank 完成时间折算</td><td>单卡吞吐正常但整批 P99 恶化</td></tr></tbody></table>\n<p>把这三条边界合起来看，cf 的可行域是一个由“P99 溢出率上限”“padding 后显存增量上限”“最慢 rank 同步惩罚上限”共同切出的多面体，任一约束收紧都会把可行域压到 1.0 附近甚至要求改溢出策略。最隐蔽的失败模式是按训练期平均 token 分布设定 cf：线上长序列请求集中命中少数专家，溢出丢弃率远超预期，而这一恶化只在中位延迟之外的 P99 指标上可见，常规吞吐监控完全无感。对应的工程动作是把分桶丢弃率与 P99 尾延迟做成同一条告警链，任一桶越界即触发 cf 重估，而不是等平均指标漂移后再排查。</p>\n<h3 id=\"ap-capacity-factor-sec-21\">二十一 · 踩坑一：用平均负载选 cf，丢弃只在 P99 上现形</h3>\n<p>容量因子选型的第一个系统性错误，是把离线统计的平均 token 分布当作线上流量。路由 kernel 的输入分布由 batch 组成与序列长度共同决定，短 batch 下每专家接收数的方差大，长序列下注意力与 FFN 的 token 集中度更高、热专家更突出，同一 cf 在不同流量档位下的丢弃率可相差数倍。平均负载估算会把溢出概率压到看似安全的区间，实际却在尾请求上集中爆发：被丢弃的 token 不进入该专家 GEMM，输出按零或残差直通，单请求质量下降不会立刻体现在均值指标上，只会把 P99 延迟与 P99 质量同时推高。</p>\n<p>正确的实测口径是在路由 kernel 输出处直接统计，而不是从端到端指标反推。伪代码思路：对每个 batch 记录 <code>recv[e]</code>（专家 e 实际接收 token 数）与 <code>C</code>（容量上限），溢出计数 <code>ovf[e] = max(0, recv[e] - C)</code>，按 batch 大小与序列长度两个维度分桶落盘，再对每个桶计算 <code>drop_rate = Σovf / Σrecv</code>。关键在于分桶而非全局平均——全局丢弃率 0.3% 完全可能对应某个长序列桶的 3%，而后者才是告警阈值（0.5%–1%）要盯的对象。选 cf 时应以 P99 尾延迟对应流量档位的分桶丢弃率为准，把该桶压到阈值以下，而不是让全局均值好看。</p>\n<p>代价体现在两个方向：cf 偏小则丢弃率超标，尾请求质量与延迟双输；cf 偏大则激活缓冲区按 <code>E×C×hidden</code> 预留，直接吃掉 KV cache 预算。工程判断是先把分桶统计管线建起来，再谈 cf 取值——没有分桶数据的 cf 调整都是盲调。</p>\n\n<h3 id=\"ap-capacity-factor-sec-22\">二十二 · 踩坑二：把 cf 当线性扩容，忽略 M 对齐 padding</h3>\n<p>容量上限 <code>C = cf × T·k/E</code> 换算到分组 GEMM 时并不是连续可用的 M 维：每专家的 M 会被 padding 到 MMA 的 M 对齐粒度（常见 64 或 128）。这意味着 cf 从 1.0 提到 1.25，名义容量涨 25%，但若某专家的实际接收数落在对齐边界之下，padding 浪费会把有效利用率拉低；E 较大时，每个专家都带一份向上取整的浪费，累加后的激活显存增幅高于 cf 的名义比例。只按比例核算显存的人，会在算力尚未打满时先撞上显存墙。</p>\n<p>核算公式应写成对齐后的形式：单专家激活占用约为 <code>ceil(C / A) × A × hidden × dtype_bytes</code>，其中 A 为对齐粒度；总激活缓冲为 <code>E</code> 份之和。把 cf 与 A 解耦看：A=128 时，C 从 100 提到 125 不会改变对齐块数，显存不涨；C 从 128 提到 129 则块数翻倍，显存跳变。这就是“cf 略大于 1 因对齐放大显存而非线性增长”的机制来源。</p>\n<p>具体例子：E 较大、hidden 固定的配置下，cf 由 1.0 升至 1.25，名义激活显存增约 25%，但对齐 padding 使实际增幅更高；若同时把 A 从 64 提到 128 以换取更好的 MMA 效率，padding 浪费进一步扩大。代价是 KV cache 可用容量被压缩，长上下文场景的并发数下降。工程判断：调 cf 前先算清 <code>ceil(C/A)</code> 的跳变点，把 cf 取值卡在块数不变或只增一档的位置，再与 KV cache 预算联合核算，而不是先定 cf 再看显存够不够。</p>\n\n<h3 id=\"ap-capacity-factor-sec-23\">二十三 · 踩坑三：单卡视角调 cf，NVL72 上最慢 rank 决定整批</h3>\n<p>在 NVL72 这类多机 NVLink 域部署中，按单 GPU 吞吐评估容量是第三个高频错误。All-to-All dispatch 阶段，某专家打满后其所在 GPU 的 dispatch 流量骤降，而其他 GPU 仍在等待；combine 阶段又必须等最慢专家完成。机架内 NVLink 域带宽虽高于跨域 IB，但集合通信按最慢 rank 同步，单专家热点即拖慢整批——尾延迟放大不是只影响那张卡，而是整批请求一起等。</p>\n<p>机制上可以把整批完成时间写成 <code>T_batch = max_r (T_dispatch,r + T_gemm,r + T_combine,r)</code>，热点 rank 的 GEMM 因 M 打满而最慢，其 combine 等待又叠加 All-to-All 同步开销。单卡视角看到的“这张卡利用率 95%”掩盖了它正是 max 项的事实。量化放大系数未给出统一数字，但方向明确：cf 偏小导致热点专家溢出，溢出后该专家 GEMM 变快、combine 反而更不均衡；cf 偏大则热点专家 M 维膨胀，GEMM 时间线性上升，两者都让 max 项恶化。</p>\n<p>工程判断是把 cf 选型与拓扑绑定：单机 NVLink 域内可容忍更激进的 cf，跨域 IB 部署则要为最慢 rank 留余量，并把分桶丢弃率统计按 rank 维度再切一刀，观察是否存在固定热点 rank。代价是跨域场景下 cf 的有效上限被通信同步压低，吞吐让位于尾延迟稳定性。</p>\n\n<h3 id=\"ap-capacity-factor-sec-24\">二十四 · 检查顺序：从统计口径到拓扑，逐层收敛</h3>\n<p>排查容量因子问题时，顺序错了会把时间浪费在下游。推荐的自外向内检查链：</p>\n<ul>\n<li><b>统计口径</b>：确认丢弃率是否按 batch 与序列长度分桶、是否以 P99 流量档位反推 cf，而非全局均值。口径不对，后面所有数字都不可信。</li>\n<li><b>对齐核算</b>：用 <code>ceil(C/A)×A</code> 复算每专家 M 维与激活显存，检查 cf 是否卡在块数跳变点上，并与 KV cache 预算对账。</li>\n<li><b>溢出策略</b>：确认溢出走丢弃、重路由还是残差直通，三者对尾延迟与质量的影响不同；丢弃率告警阈值 0.5%–1% 要按策略分别设。</li>\n<li><b>拓扑与同步</b>：在 NVL72 上按 rank 切分丢弃与 GEMM 耗时，定位是否存在固定热点 rank，验证 max 项是否由单专家主导。</li>\n<li><b>流量档位复核</b>：用当前线上真实流量重跑分桶统计，确认 cf 仍落在推荐区间 1.0–1.25 内且未越过分桶阈值。</li>\n</ul>\n<p>这个顺序的代价含义是：前两步只花统计与核算的工程时间，却能排除大部分误判；后两步涉及多机 profiling，成本高但只在拓扑嫌疑成立时才做。把顺序倒过来，常见结果是先在多机上折腾一轮，回头发现根因是平均负载选 cf。</p>\n\n<h3 id=\"ap-capacity-factor-sec-25\">二十五 · 回滚方案：cf 变更必须可逆且带观测锚点</h3>\n<p>cf 是运行时配置，但它的影响面横跨显存预留、GEMM 分块与集合通信同步，变更必须设计成可回滚。回滚方案的三要素：</p>\n<ul>\n<li><b>双档并行</b>：新 cf 先在部分副本或部分流量档位灰度，保留旧 cf 的配置快照，回滚时一键切回，避免重新编译或重排激活缓冲区布局。</li>\n<li><b>观测锚点</b>：回滚判据不是均值指标，而是分桶丢弃率是否越过 0.5%–1% 告警线、P99 尾延迟是否恶化、以及热点 rank 的 GEMM 耗时是否成为 max 项。三个锚点任一触发即回滚。</li>\n<li><b>显存对账</b>：cf 回滚会改变 <code>E×C×hidden</code> 预留，需确认 KV cache 能同步回收，否则回滚后显存仍被旧布局占住，等于没回滚。</li>\n</ul>\n<p>具体机制上，把 cf 与 M 对齐粒度 A 作为一组配置项绑定发布，回滚时整组还原，避免只回滚 cf 而 A 留在新值导致 padding 浪费残留。代价是灰度期间两套激活缓冲区并存，显存峰值上升，需在容量规划里预留这段过渡余量。</p>\n<p>最后一个工程判断落在溢出策略与 cf 的耦合上：若溢出走残差直通，丢弃对质量的伤害被掩盖，告警阈值应更严；若走丢弃，则 cf 回滚必须与丢弃率告警联动，不能等尾延迟爆了才动手。把 cf、A、溢出策略、分桶统计口径四者作为不可分割的发布单元，是这套检查清单真正要固化的机制。</p>\n\n<h3 id=\"ap-capacity-factor-sec-26\">二十六 · 容量因子调参的失效边界与上线检查顺序</h3>\n<p>这套容量因子方案最脆弱的边界不在公式本身，而在“用什么流量去标定 cf”。凡是拿训练期平均 token 分布或离线平均吞吐来选 cf 的部署，都会在线上长序列请求集中命中少数专家时失效：溢出丢弃率远超预期，且只在 P99 尾延迟指标上可见，平均延迟与平均吞吐几乎不动。原因是丢弃代价按“超出容量的 token 不进该专家 GEMM、输出按零或残差直通”结算，被丢弃的 token 在平均口径下占比极小，但它们的下游层要重算或退化，尾部的少数请求承担了全部损失。因此检查顺序必须是先固定统计口径再谈取值：在路由 kernel 输出处统计每专家实际接收 token 数与容量上限之比，按 batch 与序列长度分桶记录溢出计数，用 P99 尾延迟对应流量档位反推 cf，而不是用平均负载估算。分桶粒度不足是第一个坑——只按 batch 分桶会掩盖长序列下的热专家集中，必须 batch × 序列长度二维分桶，否则同一 cf 在不同流量下相差数倍的丢弃率会被平均掉。</p>\n<p>第二个失效条件是显存核算口径错误。激活缓冲区按 E×C×hidden 预留，而每专家 M 被 padding 到 MMA 的 M 对齐粒度（64 或 128），所以 cf 从 1.0 提到 1.25 在 E 较大时名义增加约 25% 专家激活显存，但叠加对齐向上取整后实际增幅高于 cf 比例。可用的保守估算式为</p>\n<div class=\"formula\">$$M_{\\text{pad}} = \\left\\lceil \\frac{C}{A} \\right\\rceil \\cdot A,\\qquad \\text{显存增量} \\approx \\frac{M_{\\text{pad}}(cf) - M_{\\text{pad}}(1.0)}{M_{\\text{pad}}(1.0)}$$</div>\n<p>其中 A 为对齐粒度。当 C 落在对齐边界下方时，cf 提高一档可能只增加 padding 浪费而不增加有效容量，此时扩容收益为零、显存却已付出。检查时必须把该增量与 KV cache 预算联合核算，否则会出现“显存先于算力耗尽”的典型故障：算力侧还有余量，激活缓冲区却已挤掉 KV cache 块，连续批处理被迫降低并发，吞吐反而下降。工程上应把 cf 取值、对应每专家容量、对齐粒度与 padding 浪费、分桶实测丢弃率、激活显存增量并列成一张核对表，任一行超预算即回退。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失效表现</th><th>回退动作</th></tr></thead><tbody><tr><td>cf 标定流量档位</td><td>平均延迟正常、P99 恶化</td><td>改用 P99 档位重标，cf 上调一档</td></tr><tr><td>M 对齐 padding</td><td>显存增幅高于 cf 名义比例</td><td>回退 cf 或改对齐粒度</td></tr><tr><td>NVL72 尾延迟放大</td><td>单卡吞吐达标、整批完成时间拉长</td><td>按最慢 rank 重估容量</td></tr><tr><td>丢弃率告警</td><td>分桶溢出计数越过 0.5%–1%</td><td>切残差直通或重路由策略</td></tr></tbody></table>\n<p>第三个坑是拓扑视角错误。在 NVL72 多机部署中按单卡吞吐评估容量，会忽略 All-to-All 以最慢 rank 同步这一事实：某专家打满后其所在 GPU 的 dispatch 流量骤降而其他 GPU 仍在等待，combine 阶段又需等最慢专家完成，机架内 NVLink 域带宽虽高于跨域 IB，但集合通信按最慢 rank 同步，单专家热点即拖慢整批，尾延迟被放大而非仅影响该卡。回滚方案因此要分层：先回退溢出策略（丢弃切残差直通或重路由），再回退 cf 取值，最后才动对齐粒度与并行拓扑；每次回滚只动一层，并用分桶丢弃率与 P99 尾延迟两个指标确认恢复，避免把容量问题误判为通信问题而反复调参。</p>\n\n<h3 id=\"ap-capacity-factor-sec-27\">二十七 · 踩坑清单：三个失效点、检查顺序与回滚闸门</h3>\n<p>容量因子调参最常见的失效不是参数本身错，而是<strong>选参口径错</strong>。用训练期平均 token 分布或平均负载反推 cf，线上长序列请求集中命中少数专家时，溢出丢弃率会远超预期，且这一偏差只在 P99 尾延迟上可见——均值吞吐与平均丢弃率都正常。检查顺序应固定为：先在路由 kernel 输出处按 batch 与序列长度分桶统计每专家实际接收 token 数与容量上限之比，得到分桶溢出计数；再取 P99 尾延迟对应流量档位反推所需 cf，而非用均值估算。工程阈值上，丢弃率告警常设在 0.5%–1%，一旦分桶口径下某桶越线，说明该流量形态的 cf 已失效，需按桶而非按全局回滚。</p>\n<p>第二个坑是<strong>把 cf 当线性扩容</strong>。容量上限 $C = \\mathrm{cf}\\times T\\cdot k/E$ 换算到分组 GEMM 时，每专家 M 维要向上取整到 MMA 对齐粒度（常见 64 或 128），实际占用是 $\\lceil \\mathrm{cf}\\cdot T k/E\\rceil_{\\text{align}}$ 而非名义值。cf 从 1.0 提到 1.25，E 较大时专家激活显存名义增约 25%，叠加 padding 后实际增幅更高，激活缓冲区按 E×C×hidden 预留，会先于算力耗尽挤掉 KV cache 预算。检查项：把对齐浪费单列一栏，与 KV cache 预算联合核算，而不是只看 cf 比例。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失效信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>分桶丢弃率</td><td>某序列长度桶越 0.5%–1%</td><td>该桶降 cf 或改溢出策略</td></tr><tr><td>M 对齐 padding</td><td>激活显存增幅 &gt; cf 名义增幅</td><td>回调 cf，重算 KV 预算</td></tr><tr><td>NVL72 尾延迟</td><td>单专家热点拖慢整批</td><td>按最慢 rank 重估容量</td></tr></tbody></table>\n<p>第三个坑在<strong>部署拓扑视角</strong>：NVL72 上按单卡吞吐评估容量，忽略 All-to-All 以最慢 rank 同步。某专家打满后其所在 GPU 的 dispatch 流量骤降，其他 GPU 仍在等待，combine 阶段又要等最慢专家完成，单专家热点把整批尾延迟放大，而非只影响该卡。回滚方案必须按机架域整体执行：cf 变更先在单 NVLink 域灰度，以最慢 rank 的 P99 为闸门，跨域 IB 部署另设一档更保守的 cf，因为跨域带宽更低、同步开销更贵。溢出策略（丢弃/重路由/残差直通）也应随 cf 一同回滚，否则丢弃率降了、重路由又把流量打回热点专家。</p>\n<h3 id=\"ap-capacity-factor-sec-28\">二十八 · 上游依赖：容量因子挂在哪些条目上</h3>\n<p>容量因子不是孤立旋钮，它在本卷的依赖图上至少有三个上游输入，缺一个就无法给出可用的 cf。第一个上游是<b>MoE 路由术语速查</b>——cf 的定义式 $$C = \\mathrm{cf} \\times \\frac{T \\cdot k}{E}$$ 里，T、k、E 三个量的口径必须与路由 kernel 一致：T 是当前批的有效 token 数（含 padding 与否直接改变 C），k 是每 token 选中的专家数，E 是全局专家数。口径错位会让 cf 名义值 1.25 实际等效于 1.0 或 1.5，这是容量因子条目最隐蔽的上游风险。第二个上游是<b>专家并行与 All-to-All</b>：cf 只在“每专家 token 上限”这一层有意义，而 token 到专家的物理落点由 EP 的 dispatch 决定；EP 度数与专家到 rank 的映射决定某专家打满时是哪张 GPU 的 dispatch 流量塌陷。第三个上游是<b>分组 GEMM 与 tcgen05</b>：C 必须换算成每专家 GEMM 的 M 维，而 M 要被 padding 到 MMA 对齐粒度（64 或 128），这一步把 cf 的连续取值离散化。</p>\n<p>这三个上游共同决定一个事实：cf 的“名义值”与“实际生效值”之间存在两层折算——一层是口径折算（T、k、E 的定义），一层是对齐折算（M 向 64/128 向上取整）。工程上把 cf 当单一标量调，等于同时忽略两层折算。上游依赖的正确用法是：先固定路由口径与 EP 映射，再在分组 GEMM 的 M 对齐约束下反解 cf，而不是先定 cf 再倒推。</p>\n<div class=\"formula\">$$M_e = \\left\\lceil \\frac{C}{a} \\right\\rceil \\cdot a,\\quad a \\in \\{64, 128\\}$$</div>\n<p>这里 $M_e$ 是专家 e 的分组 GEMM M 维，a 是对齐粒度。代价直接落在激活缓冲区：按 E×C×hidden 预留的缓冲，在 E 较大时 cf 从 1.0 提到 1.25 约增加 25% 专家激活显存，而对齐 padding 会把实际增幅推到 cf 比例之上。例子：E 较大、hidden 固定的配置下，某专家 C 恰好略超 64 的整数倍，向上取整到 128 使该专家 M 翻倍——单专家显存翻倍在 E 大时叠加成可观总量，且这部分显存与 KV cache 预算争抢同一块 HBM。</p>\n\n<h3 id=\"ap-capacity-factor-sec-29\">二十九 · 下游影响：cf 决定谁的分块、谁的尾延迟</h3>\n<p>容量因子向下游输出两个量：分组 GEMM 的 M 维分块形状，以及丢弃率的分桶统计口径。前者影响<b>分组 GEMM 与 tcgen05</b>条目里的 tile 选择与 TMEM 占用——M 被 padding 后，小专家 GEMM 的 M 可能远小于对齐粒度，算力利用率被 padding 稀释；后者影响<b>路由倾斜尾延迟</b>条目里的告警判据。cf 调大是“用显存换丢弃率”，cf 调小是“用丢弃率换算力与显存”，这条权衡线的斜率由 M 对齐粒度决定，而非由 cf 本身决定。</p>\n<p>更关键的下游是 NVL72 上的尾延迟放大。某专家打满后，其所在 GPU 的 dispatch 流量骤降，而其他 GPU 仍在等待；combine 阶段又需等最慢专家完成。机架内 NVLink 域带宽虽高，但集合通信按最慢 rank 同步，单专家热点即拖慢整批。于是 cf 的下游影响不是“该卡慢一点”，而是“整批慢一截”——尾延迟放大系数是 cf 与流量分布的函数，且只在 P99 上可见。这与<b>通信计算死锁</b>条目共享同一拓扑前提：EP 组内所有 rank 必须走完同一轮 dispatch/combine，任何 rank 的专家溢出都会把同步点后移。</p>\n<table class=\"mini\"><thead><tr><th>cf 取值</th><th>M 维对齐后果</th><th>下游条目受影响面</th></tr></thead><tbody><tr><td>1.0</td><td>padding 浪费最小，溢出概率最高</td><td>丢弃率告警、尾延迟放大</td></tr><tr><td>1.25</td><td>对齐 padding 使实际显存增幅高于 25%</td><td>KV cache 预算、激活缓冲</td></tr><tr><td>按 P99 反推</td><td>M 分块随流量档位漂移</td><td>分组 GEMM tile、TMEM 占用</td></tr></tbody></table>\n<p>代价的量化方向：cf 提高带来的显存增量是确定性的（E×C×hidden 加 padding），而它换来的丢弃率下降是分布相关的——短 batch 下方差大、长序列下热专家集中，同一 cf 在不同流量下丢弃率可相差数倍。这意味着下游收益不可线性外推，只能用分桶实测反推。</p>\n\n<h3 id=\"ap-capacity-factor-sec-30\">三十 · 与量化条目的耦合：cf 影响的是数值路径的选择</h3>\n<p>容量因子与<b>NVFP4/FP8 权重激活</b>、<b>量化后路由漂移</b>两条目的关系是间接但真实的。第一，cf 决定每专家 GEMM 的 M 维，而 M 维大小影响量化 kernel 的选择：M 很小时低精度 GEMM 的收益被 padding 与启动开销吃掉，此时把 cf 调大以抬高 M 反而让 NVFP4/FP8 路径更划算——这是一条“cf 换量化效率”的隐性链路。第二，<b>量化后路由漂移</b>改变的是专家命中分布，从而改变同一 cf 下的溢出概率：量化使路由分数偏移，热专家更热，cf 名义不变而实际丢弃率上升。因此容量因子的标定必须与量化校准在同一条流量档位上做，否则 cf 是按旧分布选的。</p>\n<p>与<b>量化校准数据管线</b>的接口在于统计口径：校准管线产出的 token 分布若只覆盖平均负载，cf 就会按平均而非 P99 选，这正是失败模式“按训练平均 token 分布设定容量因子”的根源。工程判断是：cf 的输入分布必须来自线上分桶统计（按 batch 与序列长度分桶记录溢出计数），而不是校准集的聚合分布。代价上，量化把权重与激活压小后，激活缓冲区占比相对上升，cf 引起的显存增幅在总预算中的权重变大——低精度并不自动缓解 cf 的显存压力。</p>\n\n<h3 id=\"ap-capacity-factor-sec-31\">三十一 · 与调度、分离式架构的接口：cf 是批调度的一个约束</h3>\n<p>在<b>批调度与连续批处理</b>这条线上，cf 是一个硬约束而非软参数：连续批处理不断把新请求拼进在飞批次，T 随批次组成变化，C 随之漂移；若 cf 固定，则批次里长序列请求一多，热专家立刻溢出。调度器的准入逻辑需要把 cf 与当前批的序列长度分布联合判断，而不是按固定 token 预算放行。与<b>分离式预填解码</b>的接口更明确：预填阶段 T 大、分布宽，解码阶段 T 小、方差大，两个阶段的 cf 不应共用同一取值——短 batch 下方差大，解码侧需要更保守的 cf 或更严格的溢出策略。</p>\n<p>与<b>MoE 场景 KV 压缩</b>的耦合是预算层面的：cf 抬高激活缓冲，KV cache 预算被挤压，KV 压缩率被迫提高，进而改变可承载的 batch 与序列长度，反过来又改变 cf 所需值——这是一个闭环。工程上必须联合核算，单独优化任一项都会在另一项上付出代价。例子：某部署把 cf 从 1.0 提到 1.25 以压丢弃率，激活显存增加约 25%（E 大时叠加 padding 更高），KV cache 可用空间下降，可并发序列数减少，长序列请求更集中，热专家溢出概率回升——cf 的收益被闭环吃掉一部分。</p>\n\n<h3 id=\"ap-capacity-factor-sec-32\">三十二 · 在全书中的位置：cf 是容量规划的一个乘子</h3>\n<p>把容量因子放回全书结构，它的位置是<b>SLO 与容量规划</b>模块里的一个乘子，而不是一个独立主题。容量规划的主线是“给定 SLO 反推可承载流量”，cf 在这条主线里以两种方式进入：作为显存预算的乘子（激活缓冲 = E×C×hidden，C 含 cf 与对齐 padding），以及作为丢弃率与尾延迟的调节器（cf 决定溢出概率，溢出经 All-to-All 最慢 rank 放大成整批尾延迟）。因此 cf 的标定输出应当是一张按流量档位分档的表，而不是一个全局常数——这正是速查表条目里“推荐流量档位”一列的来源。</p>\n<p>与<b>MoE 推理框架选型</b>的关系是：不同框架对 cf 的暴露方式不同——有的把它作为每层静态参数，有的允许按 batch 动态调整，有的把溢出策略（丢弃/重路由/残差直通）做成可选项。选型时 cf 的可调粒度与溢出策略的可选性，比框架的峰值吞吐更能决定线上尾延迟表现。与<b>MoE 剖析工具链</b>的接口是观测点：cf 的实测丢弃率必须在路由 kernel 输出处统计每专家实际接收 token 数与容量上限之比，按 batch 与序列长度分桶，再以 P99 尾延迟对应的流量档位反推所需 cf——这条链路把剖析工具的输出直接变成 cf 的输入，缺了它 cf 只能靠猜。</p>\n<p>最后落在工程判断上：cf 的取值应由“P99 流量档位下的分桶溢出计数 + M 对齐后的激活显存增量 + NVL72 最慢 rank 的尾延迟放大”三者联合反解，而不是由平均负载或单卡视角给出。当三者冲突时，优先保证 P99 档位不触发丢弃率告警（0.5%–1% 量级），再在对齐 padding 与 KV cache 预算之间做显存腾挪；在 NVL72 上尤其不能用单 GPU 吞吐评估容量，因为集合通信以最慢 rank 同步，单专家热点把整批尾延迟放大而非仅影响该卡——这条判断决定了 cf 是“每卡参数”还是“每 EP 组参数”，而后者才是 NVL72 上的正确粒度。</p>\n\n<h3 id=\"ap-capacity-factor-sec-33\">三十三 · 容量因子在全书中的位置：上游约束、下游放大与失效边界</h3>\n<p>容量因子不是孤立旋钮，它在全书里处于“路由策略—分组 GEMM—显存预算—集合通信”这条链的中间位置。上游依赖 MoE 路由与 token 分布统计：cf 的取值必须由路由 kernel 输出处的实测溢出计数反推，而不是由平均负载估算；下游直接决定分组 GEMM 的 M 维分块形态与激活缓冲区预留，并进一步通过 NVL72 的 All-to-All 同步把单专家热点转化为整批尾延迟。换言之，cf 是少数同时触及算力、显存与通信三个代价维度的参数，调它等于同时改三张预算表。其边界条件也很清楚：当流量分布稳定、序列长度方差小、E 较小且 M 对齐浪费可忽略时，cf 接近 1.0 即可；一旦长序列集中命中少数热专家，cf 的名义余量会被对齐 padding 与最慢 rank 同步双重侵蚀。</p>\n<p>失效条件可归为三类。第一类是统计口径失效：按训练平均 token 分布设定 cf，线上长序列请求集中命中热专家，溢出丢弃率远超预期，且该现象只在 P99 尾延迟指标上可见，平均吞吐看不出异常。第二类是显存核算失效：只按 cf 比例估算激活缓冲区增长，忽略每专家 M 向 MMA 对齐粒度（64 或 128）的向上取整，E 大时 padding 浪费使实际占用显著高于名义增幅，结果显存先于算力耗尽。第三类是拓扑视角失效：在 NVL72 多机部署中按单卡吞吐评估容量，未意识到 All-to-All 以最慢 rank 同步，单专家打满后其所在 GPU 的 dispatch 流量骤降而其余 GPU 仍在等待，combine 阶段又等最慢专家完成，整批完成时间被单个热点拖长。三者的共同点是：cf 的代价从来不是局部的。</p>\n<p>把丢弃代价写成可核算的形式，需要把“溢出比例”与“对齐浪费”分开计。设每专家实际接收 token 数为 \\(n_e\\)，容量上限 \\(C=\\mathrm{cf}\\cdot Tk/E\\)，则丢弃率 \\(d_e=\\max(0,1-C/n_e)\\)，而分组 GEMM 的实际 M 维为 \\(\\lceil C/A\\rceil\\cdot A\\)（A 为对齐粒度），padding 浪费率为 \\((\\lceil C/A\\rceil A-C)/C\\)。两者叠加后，激活显存增量为 \\(E\\cdot\\lceil C/A\\rceil A\\cdot \\text{hidden}\\)，与 cf 不成线性。工程上应把这两个量分别记录在按 batch 与序列长度分桶的表中，再以 P99 尾延迟对应流量档位反推 cf，而不是用平均丢弃率做决策。</p>\n<table class=\"mini\"><thead><tr><th>cf 取值</th><th>主要风险</th><th>代价落点</th><th>适用判断</th></tr></thead><tbody><tr><td>1.0</td><td>热专家溢出，丢弃率抬升</td><td>尾延迟、输出质量</td><td>分布稳定、短序列为主</td></tr><tr><td>1.0–1.25</td><td>对齐 padding 放大显存</td><td>激活缓冲区、KV cache 预算</td><td>需与 M 对齐联合核算</td></tr><tr><td>&gt;1.25</td><td>显存先耗尽、通信等待变长</td><td>整批同步时间</td><td>仅在有分桶实测支撑时采用</td></tr></tbody></table>\n<p>与全书其他条目的关系应当这样读：讲路由与负载均衡的条目给出 token 分布的上游事实，讲分组 GEMM 与 tcgen05 的条目给出 M 对齐与 TMEM 占用的下游约束，讲 KV cache 与显存预算的条目要求 cf 的激活增量必须与之联合核算，讲 NVL72 通信与尾延迟的条目则把 cf 的局部决策放大为机架级同步代价。因此本条目在全书中的位置是“约束转换器”：它把路由层的统计分布翻译成 GEMM 的分块与显存数字，再把显存数字翻译成集合通信的等待时间。判断 cf 是否合理的最终标准不是丢弃率本身，而是丢弃率告警阈值（常设在 0.5%–1%）与 P99 尾延迟是否在同一流量档位下同时可控；若只满足其一，说明 cf 的选取口径与部署拓扑中至少有一个未被纳入核算。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-capacity-factor\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>容量因子决定每专家 token 上限，直接换算为分组 GEMM 的 M 维分块与显存占用</td></tr><tr><td>关键点</td><td>需说明丢弃率随 batch 与序列分布漂移的实测方法，以及在 NVL72 上因 All-to-All 不均衡导…</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-capacity-factor · 共 5 个片段</p>\n"},{"id":"ap-expert-parallel","title":"专家并行与All-to-All","summary":"区分专家并行、张量并行与数据并行的组合方式，说明 All-to-All 的 dispatch/combine 两段通信、NVLink 域内与跨域 IB 的带宽差，以及 SM100 上通信与分组 GEMM 重叠所需的 SM 资源预留与同步原语。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-1\">一 · 条目边界：EP 是切分对象，All-to-All 是它的通信契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-2\">二 · 分类维度一：并行网格配置与 EP 组边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-3\">三 · 分类维度二：All-to-All 拓扑与两段通信的分别计量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-4\">四 · 分类维度三：重叠策略——SM 预留比例与同步原语</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-5\">五 · 分类维度四：通信量口径与容量因子耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-6\">六 · EP 网格的边界条件：All-to-All 何时从加速器变成瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-7\">七 · 并行网格与 EP 组边界的速查口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-8\">八 · dispatch/combine 通信量公式与计费口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-9\">九 · 带宽档位与 SM 预留比例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-10\">十 · 典型误配的查表识别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-11\">十一 · 速查表：EP 组边界、SM 预留与通信量口径的失效判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-12\">十二 · 速查表：EP 组边界、SM 预留与通信量口径的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-13\">十三 · 阈值不是常数：三个可测的边界量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-14\">十四 · 测域边界：用 dispatch 带宽拐点定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-15\">十五 · 测 SM 预留：以流水气泡为判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-16\">十六 · 测 k 与 combine 的通信量下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-17\">十七 · 跨域分层后的重测清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-18\">十八 · 测量纪律：固定口径再谈阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-19\">十九 · EP 组边界与 SM 预留的工程判据：先量什么、卡在哪、怎么定阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-20\">二十 · 把“经验值”变成可测的边界：EP 组、SM 预留与 k 的三条阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-21\">二十一 · 踩坑清单：先按“域边界”排雷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-22\">二十二 · 重叠失效：SM 预留不足的隐性气泡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-23\">二十三 · 检查顺序：从静态配置到动态剖面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-24\">二十四 · 回滚方案：三条退路与各自的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-25\">二十五 · 死锁与顺序：检查清单里最容易被跳过的一格</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-26\">二十六 · 清单落地：把判据写成可执行的检查项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-27\">二十七 · 踩坑清单：EP 组边界、SM 争抢与 combine 聚合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-28\">二十八 · 坑位边界：EP 组跨域、SM 抢占与 combine 聚合错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-29\">二十九 · 上游依赖：并行网格与通信域分层是 EP 的前置约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-30\">三十 · 上游依赖：数值精度与分组 GEMM 决定重叠的可行性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-31\">三十一 · 下游影响：尾延迟、KV 压缩与分离式预填解码都吃 EP 的通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-32\">三十二 · 下游影响：框架选型与剖析工具链以 EP 拓扑为坐标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-33\">三十三 · 在全书中的位置：EP 是并行与通信卷的收口环节</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-34\">三十四 · 边界条件：EP 组何时失效、代价落在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-expert-parallel-sec-35\">三十五 · 边界条件与全书坐标：EP 方案何时失效、向何处传导</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-expert-parallel\"><svg style=\"max-width:504px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 504.4 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"422.4\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：专家并行与All-to-All</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">区分专家并行、张量并行与数据并行的组合方式，说明 </text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">All-to-All 的 d…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-expert-parallel-sec-1\">一 · 条目边界：EP 是切分对象，All-to-All 是它的通信契约</h3>\n<p>本条目讨论的对象必须先把两个词分开：<strong>专家并行（EP）是一种切分方式</strong>，它规定 E 个专家如何分布到设备上；<strong>All-to-All 是这种切分在推理时必然产生的通信模式</strong>，它规定 token 如何跨设备流动。二者不是同义词，也不是可互相替代的优化手段。EP 回答“专家放在哪”，All-to-All 回答“token 怎么去找专家”。把 EP 组扩大而不改变 All-to-All 的拓扑，等于只改了切分维度却不动通信契约，这正是本条目要防的第一类误判。</p>\n<p>准确定义：EP 将 MoE 层的 E 个专家划分为若干组，每组驻留在一个设备（或一个 rank）上，每设备持有 E/DP 个专家——这里的 DP 指专家维度的切分组数，与数据并行的 batch 复制不是同一件事，读者需按上下文区分。推理时每个 token 经路由选中 k 个专家，这 k 个专家可能分布在 k 个不同设备上，于是 token 必须被发送过去、算完再送回。这一来一回就是 dispatch 与 combine 两段全交换。</p>\n<p>与相邻概念的区别要一句话讲清：张量并行切的是<strong>层内矩阵</strong>，通信发生在层内的 all-reduce 或 reduce-scatter，粒度是激活张量；数据并行切的是<strong>batch</strong>，推理时通常不产生每层通信（权重复制、请求分派）；EP 切的是<strong>专家子集</strong>，通信是 token 级的稀疏全交换。三者可以叠加，典型推理布局是注意力层用 TP、MoE 层用 EP，形成 TP×EP×DP 的混合网格，通信域随之分层：TP 组内是高频小消息，EP 组内是低频大消息，跨 DP 组则多是请求级调度。</p>\n<div class=\"formula\">$$\\text{comm}_{\\text{dispatch}} \\approx T \\cdot k \\cdot h \\cdot \\mathrm{bytes},\\qquad \\text{comm}_{\\text{combine}} \\approx T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</div>\n<p>其中 T 为本 microbatch 内被路由的 token 数，k 为每 token 选中的专家数，h 为隐藏维宽度。两段各一次全交换，故 EP 推理的 All-to-All 总通信量是上式两倍量级。工程代价直接落在这里：k=2 相对 k=1 通信量翻倍，这是线性关系，不随拓扑优化而改变；因此调 k 是调带宽预算，不是调精度参数。一个具体例子：NVL72 机架域内，EP 组设为 72 以内时 dispatch/combine 走 NVLink，带宽足以让 All-to-All 藏在分组 GEMM 之后；一旦 EP 组跨出机架边界，同样的 T·k·h 字节要过 IB，带宽下降、延迟上升，dispatch 立刻从“可重叠”变成“主瓶颈”，分组 GEMM 的 tcgen05 算力闲置。</p>\n\n<h3 id=\"ap-expert-parallel-sec-2\">二 · 分类维度一：并行网格配置与 EP 组边界</h3>\n<p>第一个分类维度是并行维度的组合比例，即 TP:EP:DP 的取值。这不是审美选择，而是由模型结构与部署形态倒推出来的约束：注意力层头数决定 TP 上限，专家总数 E 与每设备显存决定 EP 组大小，请求并发与 SLO 决定 DP 宽度。分类时要把“EP 组大小”与“EP 组边界”分开记录——组大小是数字，边界是它落在哪个通信域里。二者共同决定 All-to-All 走 NVLink 还是 IB。</p>\n<p>工程阈值很硬：EP 组常限制在单 NVLink 域内，NVL72 机架域是典型边界。跨域扩展需改用分层 All-to-All（域内先聚合、域间再转发）或降低 k，二者都是拿通信量换规模。分类表里必须有一列明确写出“EP 组大小与域边界”，否则同一套配置在不同机架上会给出完全不同的尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>分类维度</th><th>取值/档位</th><th>对 All-to-All 的影响</th><th>代价落点</th></tr></thead><tbody><tr><td>并行网格</td><td>TP×EP×DP 比例</td><td>决定通信域分层与消息粒度</td><td>TP 组内高频小消息挤占 SM</td></tr><tr><td>EP 组边界</td><td>单 NVLink 域 / 跨域 IB / 分层</td><td>决定带宽档位与延迟量级</td><td>跨域时 dispatch 成瓶颈</td></tr><tr><td>重叠策略</td><td>SM 预留比例、同步原语</td><td>决定 dispatch 能否藏进 GEMM</td><td>预留不足产生流水气泡</td></tr><tr><td>通信量口径</td><td>dispatch/combine 分计</td><td>决定容量规划的上界</td><td>漏计 combine 导致带宽超卖</td></tr><tr><td>容量因子耦合</td><td>EP 越大每专家容量越小</td><td>影响丢弃率与有效 T</td><td>丢弃改变实际通信量</td></tr></tbody></tbody></table>\n<p>注意最后一行：EP 组越大，每设备持有的专家越少（E/DP 变小），单个专家分到的容量因子随之收紧，丢弃与重排会改变实际参与 All-to-All 的 token 数 T。分类时若把 T 当作固定值，容量规划会系统性偏乐观。容量因子与丢弃代价本身是另一条目的主题，此处只作为分类维度的一个耦合项记录。</p>\n\n<h3 id=\"ap-expert-parallel-sec-3\">三 · 分类维度二：All-to-All 拓扑与两段通信的分别计量</h3>\n<p>第二个维度是拓扑：单机 NVLink、多机 IB、分层三种。分类的关键不是背下档位名，而是坚持<strong>dispatch 与 combine 分别计量</strong>。dispatch 把 token 按其路由专家发送到持有该专家的设备；combine 把专家输出送回 token 原设备并加权求和。两段的通信量同阶，但失败模式不同：dispatch 的瓶颈是“到达数据块能否及时进入 GEMM 流水”，combine 的瓶颈是“是否按 token 原设备聚合”。</p>\n<p>combine 阶段最常见的错误是按专家而非按 token 原设备聚合输出，导致 token 被多次跨设备转发，通信量超出 T·k·h 的理论下界。这不是拓扑问题，是聚合键选错，任何带宽档位都救不回来。分类表因此要单列“combine 聚合键”这一项，把它与拓扑档位并列，而不是塞进实现细节。</p>\n<p>分层 All-to-All 的伪代码思路可写成：域内先做一次全交换把 token 归并到目标域，域间只传归并后的块，域内再做第二次全交换分发到具体设备。收益是把跨域字节数从 T·k·h 压到按域聚合后的量级；代价是两次域内交换的延迟叠加，且归并缓冲占用显存。对 NVL72 机架域而言，域内 NVLink 带宽足以承载高带宽 All-to-All，分层的主要价值在跨机架扩展时保住 dispatch 不被 IB 拖死。</p>\n<div class=\"formula\">$$\\text{bytes}_{\\text{layered}} \\approx \\text{bytes}_{\\text{intra}} \\times 2 + \\text{bytes}_{\\text{inter}},\\qquad \\text{bytes}_{\\text{inter}} \\ll T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</div>\n<p>代价判断：分层并不减少域内总字节，反而增加一次域内往返；它只在跨域带宽显著低于 NVLink 时才划算。若 EP 组本就落在单 NVLink 域内，引入分层是纯增延迟。这是分类维度与工程判断的直接接口。</p>\n\n<h3 id=\"ap-expert-parallel-sec-4\">四 · 分类维度三：重叠策略——SM 预留比例与同步原语</h3>\n<p>第三个维度是通信与分组 GEMM 的重叠策略。SM100 上这不是“开个开关”，而是资源分配问题：部分 SM 专职驱动 NVLink 拷贝与同步，其余 SM 执行 tcgen05 MMA。分类时要记录两个量：SM 预留比例，以及同步原语类型（mbarrier、cluster 内 barrier 等）。重叠依赖细粒度同步，使 dispatch 的到达数据块可在 GEMM 流水未排空前进入 TMEM 暂存。</p>\n<p>SM 预留比例常见个位数到十几个百分点（具体数值随 kernel 与拓扑而定，本条目不给定量结论）。预留不足的后果是可复现的：NVLink 拷贝 kernel 与 tcgen05 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，且难以通过调 batch 消除——因为气泡的周期由拷贝与 MMA 的相对节奏决定，改 batch 只改变气泡数量不改变其存在。这类失败在分类表里应标为“重叠策略=无专用 SM”，与“重叠策略=预留+细粒度同步”明确区分。</p>\n<p>同步原语的分类意义在于：mbarrier 适合块级到达通知，cluster 内 barrier 适合跨 SM 的流水对齐；选错原语会让同步开销吃掉重叠收益。工程代价落在延迟上：一次不必要的全局同步会把 dispatch 的尾块推迟到 GEMM 排空之后，重叠收益归零。具体例子：dispatch 的数据块按专家分块到达，若用块级 mbarrier 逐块唤醒 GEMM 消费者，则 TMEM 暂存区可被流水式填满；若退化为整段 barrier，则必须等全部 token 到齐才能启动 MMA，重叠窗口消失。</p>\n\n<h3 id=\"ap-expert-parallel-sec-5\">五 · 分类维度四：通信量口径与容量因子耦合</h3>\n<p>第四个维度是通信量口径。分类表必须把 dispatch 与 combine 分列，并注明是否计入容量因子导致的丢弃。口径不统一是容量规划失准的主因：只算 dispatch 会把带宽预算低估一半；把 T 当作路由前的 token 数会忽略丢弃后的实际流量；把 combine 的聚合键默认成专家会引入额外转发。这三项在分类表里各占一行，比任何性能数字都重要。</p>\n<p>容量因子耦合的机制是：EP 组越大，每设备专家数 E/DP 越少，单专家容量越小，超出容量的 token 被丢弃或重排，实际参与 All-to-All 的 T 下降。表面上通信量变小，但被丢弃 token 的输出质量损失与重排带来的额外路由抖动是另一笔账。分类时若把“EP 组大小”与“容量因子”绑在同一行，就能避免把“EP 扩大→通信量线性上升”当成无条件成立的结论——它只在无丢弃时成立。</p>\n<p>速查表应包含的列在此收束为：并行网格配置、EP 组大小与域边界、dispatch/combine 通信量公式、NVLink 与 IB 带宽档位、SM 预留比例、同步原语、重叠收益与尾延迟风险。这七列覆盖了上述四个维度，且每一列都对应一个可观测的工程代价：延迟（同步原语与域边界）、吞吐（SM 预留与重叠）、显存（分层归并缓冲与 TMEM 暂存）、带宽（通信量口径）、功耗（拷贝 SM 与 MMA SM 的并行占用）。</p>\n<p>最后落在一条工程判断上：分类的目的不是给配置贴标签，而是让“EP 组跨出 NVLink 域”与“未预留专用 SM”这两种失败模式在表里各自可见。前者表现为 dispatch 带宽骤降、分组 GEMM 算力闲置；后者表现为周期性流水气泡、调 batch 无效。二者都不需要新硬件解决，只需要在分类阶段把域边界与 SM 预留写成显式列，而不是留给部署时临场决定。</p>\n\n<h3 id=\"ap-expert-parallel-sec-6\">六 · EP 网格的边界条件：All-to-All 何时从加速器变成瓶颈</h3>\n<p>专家并行的分类不能停在“把 E 个专家切到不同设备”这一句上，真正决定推理形态的是它与 TP、DP 的嵌套次序。典型布局是注意力层走 TP、MoE 层走 EP，形成 TP×EP×DP 的混合网格；通信域随之分层：TP 组内是高频的激活切分与归约，EP 组内是 dispatch/combine 两次全交换，DP 组只在 batch 复制维度上对齐。三者的失效条件完全不同——TP 组受限于层内矩阵切分的粒度，EP 组受限于 All-to-All 的带宽域边界，DP 组受限于副本间的负载偏斜。把 EP 组当作可无限扩大的维度是分类上最常见的误判：EP 组大小一旦越过 NVLink 域边界，dispatch 就从机架内高带宽交换退化为跨域 IB 传输，带宽下降、延迟上升，此时即便专家数增加使每设备容量 E/DP 变小、显存压力缓解，分组 GEMM 的算力也会因等待 token 到达而闲置。</p>\n<p>通信量口径必须把 dispatch 与 combine 分开计。dispatch 把 token 按其路由专家发送到持有该专家的设备，combine 把专家输出送回 token 原设备并加权求和，两段各一次全交换，单段通信量为</p>\n<div class=\"formula\">$$C_{\\text{seg}} \\approx T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</div>\n<p>其中 T 为 token 数、k 为每 token 激活专家数、h 为隐藏维。k 是最直接的杠杆：k=2 相对 k=1 通信量翻倍，且这一增长是线性的，不随 EP 组扩大而摊薄。工程上因此出现一个明确的边界判断——EP 组常限制在单 NVLink 域内（如 NVL72 机架域），跨域扩展必须改用分层 All-to-All（域内先聚合再跨域转发）或直接降低 k。分层方案把一次全局交换拆成域内与域间两跳，代价是额外的中间缓冲与一次域内重排，收益是把跨域流量从 T·k·h 压到按专家所在域聚合后的量级；若不做分层而硬扩，dispatch 成为主瓶颈，combine 又因回程同样跨域而叠加尾延迟。</p>\n<p>重叠策略是另一个分类维度，也是失效高发区。SM100 上要让通信与分组 GEMM 重叠，必须预留 SM 资源：部分 SM 专职驱动 NVLink 拷贝与同步，其余 SM 执行 tcgen05 MMA，重叠依赖 mbarrier 与 cluster 内 barrier 这类细粒度同步原语，使 dispatch 到达的数据块能在 GEMM 流水未排空前进入 TMEM 暂存。预留比例常见个位数到十几个百分点，低于这个区间，拷贝 kernel 会与 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，且这种气泡无法靠调 batch 消除——它是资源争用的结构性结果。反向的坑在 combine：若按专家而非 token 原设备聚合输出，token 会被多次跨设备转发，实际通信量超出 T·k·h 的理论下界，等于把两段全交换做成了多段。</p>\n<table class=\"mini\"><thead><tr><th>分类维度</th><th>取值与边界</th><th>系统代价</th></tr></thead><tbody><tr><td>并行网格</td><td>TP×EP×DP 嵌套，注意力 TP、MoE EP</td><td>通信域分层，TP 归约与 EP 全交换争用链路</td></tr><tr><td>All-to-All 拓扑</td><td>单机 NVLink / 多机 IB / 分层</td><td>跨域带宽下降，dispatch 延迟主导</td></tr><tr><td>重叠策略</td><td>SM 预留比例、同步原语类型</td><td>预留不足产生流水气泡，尾延迟抬升</td></tr><tr><td>容量耦合</td><td>EP 越大每专家容量越小</td><td>专家负载偏斜放大，combine 聚合成本上升</td></tr></tbody></table>\n<h3 id=\"ap-expert-parallel-sec-7\">七 · 并行网格与 EP 组边界的速查口径</h3>\n<p>速查表的第一列不是“用了多少卡”，而是并行网格的分解方式。推理侧典型布局是注意力层走 TP、MoE 层走 EP，两者再与 DP 叠成 TP×EP×DP 的网格，通信域随之分层：TP 组内是高频小消息（每层都要 all-reduce），EP 组内是低频大消息（每 token 一次 dispatch/combine），DP 组基本不通信。填表时要把三个数字分开写清楚——TP 度、EP 组大小、DP 度，并显式标注 EP 组的域边界落在哪一层网络上。工程判断只有一条：EP 组大小必须 ≤ 单 NVLink 域可容纳的设备数，NVL72 机架域是当前可用的最大整块高带宽域，一旦 EP 组跨越该边界，dispatch 就落到 IB 上，带宽档位整体下移一档，此时增加专家数带来的容量收益会被通信开销吃掉。表里应有一列“域内/跨域”布尔标记，任何跨域配置都要在备注栏写明改用分层 All-to-All 或下调 k。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>取值口径</th><th>阈值/判据</th><th>代价落点</th></tr></thead><tbody>\n<tr><td>并行网格</td><td>TP 度 × EP 组大小 × DP 度，按层分别标注</td><td>EP 组 ≤ 单 NVLink 域设备数</td><td>TP 增通信频次，EP 增单次消息体积</td></tr>\n<tr><td>EP 组边界</td><td>域内 NVLink / 跨域 IB / 分层</td><td>跨域即触发带宽降档</td><td>dispatch 延迟上升，成为主瓶颈</td></tr>\n<tr><td>每设备专家数</td><td>E / EP 组大小</td><td>与容量因子耦合，EP 越大每专家容量越小</td><td>显存占用与丢弃率联动</td></tr>\n<tr><td>k（每 token 激活专家数）</td><td>路由 top-k</td><td>k 翻倍则通信量翻倍</td><td>dispatch/combine 带宽线性上升</td></tr>\n</tbody></table>\n<p>这张子表的作用是让配置在写下来的一刻就暴露矛盾：若 EP 组大小已经顶到 NVL72 边界而 E 还想继续增大，唯一不跨域的办法是提高每设备专家数，代价是单卡显存里权重占比上升、留给 KV cache 的空间被压缩。此时应把决策点前移到“是否值得为更多专家付跨域带宽”，而不是先扩组再测性能。</p>\n\n<h3 id=\"ap-expert-parallel-sec-8\">八 · dispatch/combine 通信量公式与计费口径</h3>\n<p>第二块是通信量口径，必须分两段计，不能合并成一个数。dispatch 把 token 按其路由专家发送到持有该专家的设备，combine 把专家输出送回 token 原设备并加权求和，两段各一次全交换，单段通信量为</p>\n<div class=\"formula\">$$V_{\\text{dispatch}} = T \\cdot k \\cdot h \\cdot b,\\qquad V_{\\text{combine}} = T \\cdot k \\cdot h \\cdot b$$</div>\n<p>其中 T 为本批 token 数、k 为激活专家数、h 为隐维、b 为每元素字节数。整轮 EP 通信量是两段之和，即 2Tkhb 量级，这是理论下界，任何超出都来自聚合方式不当。速查表要单列“dispatch 计费”和“combine 计费”两行，并在 combine 行注明聚合键必须是 token 原设备而非专家：若按专家聚合，同一 token 的输出会被多次跨设备转发，实际通信量突破 2Tkhb 下界，这是最常见的隐性浪费。另一个口径细节是 b 的取值要与数值精度一致，NVFP4/FP8 下 b 显著小于 BF16，公式里换一个字节数，带宽预算就整体改写，因此表里应把精度档位与 b 绑定成一行，避免用旧口径估算新精度下的 All-to-All 开销。</p>\n<p>计费口径还要区分“每层”与“每 token”：MoE 层数越多，EP 通信在总时延里的占比越高，而注意力层的 TP all-reduce 是另一条独立账。速查表应给出一个合成判据——把单层 dispatch+combine 时间与单层分组 GEMM 时间并列，若前者超过后者，则该配置下 EP 规模已到瓶颈，继续扩组无收益。这个比值不需要精确测量，用带宽档位和公式量级即可定性判断。</p>\n\n<h3 id=\"ap-expert-parallel-sec-9\">九 · 带宽档位与 SM 预留比例</h3>\n<p>第三块是资源档位表，分网络与 SM 两类。网络侧只列两档：NVLink 域内与跨域 IB，后者带宽低于前者且延迟更高，量化数字不作承诺，但档位关系是确定的，因此表里用“高/低”两档加“是否满足 dispatch 实时性”判据即可。SM 侧的核心字段是通信专用 SM 预留比例，工程上常见个位数到十几个百分点：一部分 SM 专职驱动 NVLink 拷贝与同步，其余 SM 执行 tcgen05 MMA。预留不足时拷贝 kernel 会抢占计算 SM 的 warp slot，tcgen05 流水出现周期性气泡，且这种气泡无法靠调 batch 消除，因为它来自资源争抢而非排队。</p>\n<table class=\"mini\"><thead><tr><th>档位字段</th><th>取值</th><th>判据</th><th>失效表现</th></tr></thead><tbody>\n<tr><td>网络档位</td><td>NVLink 域内 / 跨域 IB</td><td>EP 组是否越界</td><td>dispatch 成主瓶颈，GEMM 算力闲置</td></tr>\n<tr><td>SM 预留比例</td><td>个位数到十几个百分点</td><td>拷贝 kernel 不与 MMA 争 slot</td><td>流水周期性气泡，调 batch 无效</td></tr>\n<tr><td>同步原语</td><td>mbarrier、cluster 内 barrier</td><td>到达数据块可进 TMEM 暂存</td><td>GEMM 排空后才启动拷贝，重叠归零</td></tr>\n<tr><td>重叠收益</td><td>dispatch 与分组 GEMM 并行</td><td>流水未排空前数据已就位</td><td>尾延迟随路由倾斜放大</td></tr>\n</tbody></table>\n<p>同步原语一栏不能只写“有 barrier”，要写清粒度：细粒度 mbarrier 让 dispatch 的到达数据块在 GEMM 流水未排空前进入 TMEM 暂存，这是重叠成立的前提；若同步粒度粗到整层，重叠窗口消失，SM 预留也失去意义。表里应把“同步原语类型”与“SM 预留比例”放在同一行组，因为二者是配套的：预留了 SM 但同步太粗，拷贝仍要等 GEMM 排空；同步够细但没预留 SM，拷贝没有执行资源。重叠收益一栏同时要挂尾延迟风险，路由倾斜时到达数据块分布不均，细粒度同步会把这种不均直接传导为流水抖动。</p>\n\n<h3 id=\"ap-expert-parallel-sec-10\">十 · 典型误配的查表识别</h3>\n<p>速查表的价值在于把失败模式变成可勾选的检查项，而不是事后归因。第一类误配：EP 组扩到跨机架 IB 域以容纳更多专家，表里“EP 组边界”一栏勾到跨域、“网络档位”落到低档，此时 dispatch/combine 带宽下降，All-to-All 成为主瓶颈，分组 GEMM 算力闲置——三个字段同时报警即可判定，无需跑 profiling。第二类误配：为追求重叠而不预留专用 SM，“SM 预留比例”填零或极低，“失效表现”列直接对应流水气泡，且该气泡对 batch 调整不敏感，这是与排队型气泡的区分点。第三类误配：combine 按专家聚合，“combine 计费”一栏的实际值突破 2Tkhb 下界，token 被多次跨设备转发，表里用“聚合键=token 原设备”作为强制校验项。</p>\n<p>查表时还要交叉验证 k 与容量因子：k 增大使通信量线性上升，k=2 相对 k=1 通信量翻倍，而 EP 组越大每专家容量越小，两者叠加会让“扩组+提 k”的组合同时推高带宽与丢弃代价。速查表因此把 k 与每设备专家数放在相邻行，任何一行变动都要求重算另一行的预算。最后一段落在具体机制上：把“聚合键”和“SM 预留比例”设为配置提交前的两个必填项，前者决定通信量是否触及理论下界，后者决定重叠是否真实发生；这两项填错，其余字段再精确也无法挽回流水效率。</p>\n\n<h3 id=\"ap-expert-parallel-sec-11\">十一 · 速查表：EP 组边界、SM 预留与通信量口径的失效判据</h3>\n<p>这张表不是配置模板，而是判断“当前 EP 布局是否已经越界”的检查清单。四个字段必须一起读：EP 组大小与域边界决定 All-to-All 走 NVLink 还是 IB；dispatch/combine 通信量口径决定带宽预算；SM 预留比例决定重叠能否成立；同步原语类型决定重叠的粒度下限。任何一行单独看都会给出错误结论——例如 EP 组仍在 NVL72 机架域内，但 SM 预留为零，此时带宽档位再高也换不来重叠收益，dispatch 的到达数据块只能等 GEMM 流水排空后才进 TMEM，尾延迟按层累加。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>取值/阈值</th><th>口径</th><th>越界信号</th></tr></thead><tbody><tr><td>EP 组大小与域边界</td><td>≤ 单 NVLink 域（NVL72 机架域）</td><td>按 All-to-All 实际经过的链路计，不按逻辑 rank 数计</td><td>组内出现跨机架 IB 跳数，dispatch 带宽骤降</td></tr><tr><td>dispatch/combine 通信量</td><td>各计一次，量级 $$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</td><td>两段分别记账，不可合并成“一次全交换”</td><td>combine 实际量超出 $$T \\cdot k \\cdot h$$ 下界</td></tr><tr><td>SM 预留比例</td><td>个位数到十几个百分点</td><td>按每 SM 的 warp slot 占用计，非按 kernel 数计</td><td>拷贝 kernel 与 tcgen05 MMA 争抢同一 SM</td></tr><tr><td>同步原语</td><td>mbarrier、cluster 内 barrier</td><td>按数据块粒度，非按层粒度</td><td>只能整层同步，重叠退化为串行</td></tr></tbody></table>\n<p>第一类失效是域边界误判。把 EP 组扩到跨机架 IB 域以容纳更多专家，看似提升了每设备专家数的余量，但 dispatch 与 combine 两段全交换的带宽档位从 NVLink 掉到 IB，延迟同时上升。此时通信量公式不变，$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$ 的分子没变而分母变小，All-to-All 直接成为主瓶颈，分组 GEMM 的 tcgen05 算力闲置。判断口径是看 All-to-All 的实际链路而非逻辑拓扑：只要有一次交换跨出 NVL72 机架域，就应按 IB 档位重算带宽预算，并考虑改用分层 All-to-All 或下调 k。k 的口径也要盯住——k=2 相对 k=1 通信量翻倍，这是线性关系，扩容专家数不能靠抬 k 来换。</p>\n<p>第二类失效是 SM 预留不足。SM100 上通信与分组 GEMM 重叠依赖部分 SM 专职驱动 NVLink 拷贝与同步，其余 SM 执行 tcgen05 MMA；预留比例落在个位数到十几个百分点区间，低于此区间时拷贝 kernel 会抢占计算 SM 的 warp slot，流水出现周期性气泡，且这种气泡无法通过调 batch 消除，因为它是资源争抢而非排队问题。同步原语的选择同样设定了重叠粒度：只有 mbarrier 与 cluster 内 barrier 这类细粒度原语，才能让 dispatch 的到达数据块在 GEMM 流水未排空前进入 TMEM 暂存；若同步只能做到层粒度，重叠就退化为两段串行，SM 预留反而变成纯开销。</p>\n<p>第三类失效是 combine 的聚合口径错误。combine 必须按 token 原设备聚合后再加权求和，若按专家聚合输出，token 会被多次跨设备转发，实际通信量超出 $$T \\cdot k \\cdot h$$ 的理论下界，且超出部分不随 k 线性、难以预估。速查时把 combine 的记账单位固定为“token 原设备”，与 dispatch 的“路由专家所在设备”区分开；两段各一次全交换，但聚合键不同，这是同一张表里最容易被合并掉的一行。容量因子与 EP 组大小耦合也要在同一张表里核对：EP 越大每专家容量越小，若同时跨域扩容，带宽与容量的双重恶化会叠加在同一层上。</p>\n\n<h3 id=\"ap-expert-parallel-sec-12\">十二 · 速查表：EP 组边界、SM 预留与通信量口径的工程判据</h3>\n<p>这张表不是配置模板，而是判断“当前 EP 方案是否已经越界”的检查清单。每一行都对应一个可观测的失效信号：EP 组跨越 NVLink 域边界后，dispatch 的带宽档位从机架内全带宽掉到 IB 档，All-to-All 立刻取代分组 GEMM 成为主瓶颈，此时扩容专家数换来的是算力闲置而非吞吐提升。SM 预留比例落在个位数到十几个百分点区间内是重叠能成立的前提；低于这个区间，NVLink 拷贝 kernel 会与 tcgen05 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，调 batch 也消不掉。通信量必须按 dispatch 与 combine 分别记账，合并成一个总数会掩盖 combine 阶段按专家而非 token 原设备聚合所引入的重复往返——那种实现的实际通信量已超出 $$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$ 的理论下界。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>取值/阈值</th><th>口径与失效判据</th></tr></thead><tbody><tr><td>并行网格</td><td>TP×EP×DP，注意力 TP、MoE EP</td><td>通信域随维度分层，EP 组不得跨层混用</td></tr><tr><td>EP 组边界</td><td>限制在单 NVLink 域（NVL72 机架域）</td><td>越界即走 IB，带宽下降、延迟上升</td></tr><tr><td>dispatch 通信量</td><td>$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</td><td>单独计，k=2 相对 k=1 翻倍</td></tr><tr><td>combine 通信量</td><td>同量级，按 token 原设备聚合</td><td>按专家聚合则超出下界</td></tr><tr><td>SM 预留</td><td>个位数至十几个百分点</td><td>不足则拷贝抢占计算 SM，出气泡</td></tr><tr><td>同步原语</td><td>mbarrier、cluster 内 barrier</td><td>缺细粒度同步则无法块级流水</td></tr></tbody></table>\n<p>容量因子与 EP 规模是耦合的：EP 越大，每设备持有的专家数为 E/DP，单专家分到的 token 越少，分组 GEMM 的 M 维变小、tcgen05 MMA 的利用率下降，而 All-to-All 通信量却随 k 线性上升。这条曲线意味着 EP 存在一个由带宽与算力共同夹出的最优点，越过它继续加专家只会把瓶颈从 GEMM 搬到 dispatch。判断方法是分别测量 dispatch、combine 与分组 GEMM 三段的耗时占比：若前两段之和已接近或超过第三段，扩容即失效。</p>\n<p>重叠策略的代价必须写进容量规划。预留 SM 驱动 NVLink 拷贝与同步，等于从计算预算中永久扣除这部分算力，收益是 dispatch 到达的数据块能在 GEMM 流水未排空前进入 TMEM 暂存；若同步原语粒度不够细，块级流水退化为段级流水，重叠收益被尾延迟吃掉。跨域扩展时唯一可用的替代是分层 All-to-All——域内走 NVLink、域间走 IB——并同步降低 k，否则 IB 档带宽无法支撑两段全交换。</p>\n<h3 id=\"ap-expert-parallel-sec-13\">十三 · 阈值不是常数：三个可测的边界量</h3>\n<p>工程上真正需要盯住的阈值只有三个，而且它们都不是从文档里抄来的常数，必须在本机、本拓扑、本模型上测出来。第一个是<strong>EP 组域边界</strong>：当 EP 组恰好落在单个 NVLink 域内（如 NVL72 机架域）时，dispatch/combine 走的是高带宽链路；一旦组内任一 rank 越出该域，这两段全交换就落到 IB 上，带宽档位下降、延迟抬升，dispatch 立刻从“可与 GEMM 重叠的旁路”变成“流水前端的硬阻塞”。第二个是<strong>SM 预留比例</strong>：通信与分组 GEMM 重叠时，必须有一批 SM 专职驱动 NVLink 拷贝与同步，常见区间是个位数到十几个百分点；低于这个区间，拷贝 kernel 会去抢计算 SM 的 warp slot。第三个是<strong>k 的取值</strong>：k=2 相对 k=1 使 All-to-All 通信量翻倍，这条线性关系是判断“还能不能加 k”的唯一硬约束。</p>\n<p>这三个量之所以必须实测，是因为它们互相耦合：EP 组越大，每专家容量越小（容量因子与丢弃代价见另篇），而组一旦跨域，前两个量的最优值全部失效。测量方法应当固定为“单变量扫描 + 端到端指标回读”，而不是分别调参后拼在一起看。</p>\n\n<h3 id=\"ap-expert-parallel-sec-14\">十四 · 测域边界：用 dispatch 带宽拐点定位</h3>\n<p>测域边界的正确做法不是查拓扑表，而是构造一个纯通信微基准：固定 token 数 T、top-k 的 k、隐维 h 与字节宽度，令路由分布均匀（人为打散专家归属，避免倾斜干扰），只跑 dispatch 一段，扫 EP 组大小从域内到跨域。通信量口径按 $$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$ 计，把实测耗时换算成有效带宽，画“EP 组大小—有效带宽”曲线。域内段应呈平台，跨域那一刻出现台阶式下跌，台阶位置就是该集群的 EP 组上限。这条曲线同时给出第二个信息：延迟随组大小的增长斜率，用于判断尾延迟风险（路由倾斜导致的尾延迟见另篇，此处只取均匀分布基线）。</p>\n<p>代价判断很直接：若台阶后的有效带宽已低于分组 GEMM 的单步计算时间所对应的可容忍通信时间，则 dispatch 成为主瓶颈，分组 GEMM 算力闲置——这正是把 EP 组扩到跨机架 IB 域以容纳更多专家的典型失败模式。工程上应把 EP 组大小钉在台阶左侧，宁可减少每设备专家数、提高容量因子，也不越界。</p>\n\n<h3 id=\"ap-expert-parallel-sec-15\">十五 · 测 SM 预留：以流水气泡为判据</h3>\n<p>SM 预留比例的测量不能只看通信 kernel 的独立吞吐，必须放在重叠流水里测。做法是：固定 EP 组与 k，扫预留 SM 数（从 0 到十几个百分点），同时采集两个指标——分组 GEMM 的有效 MMA 占用率，以及 dispatch 数据块进入 TMEM 暂存的到达间隔抖动。判据是<strong>周期性气泡</strong>：预留不足时，NVLink 拷贝 kernel 与 tcgen05 MMA 争抢同一 SM 的 warp slot，GEMM 流水出现规律性空档，且这种空档不会因调 batch 而消失；预留足够时，mbarrier 与 cluster 内 barrier 的细粒度同步能让到达的数据块在 GEMM 流水未排空前进入 TMEM 暂存，气泡收敛。</p>\n<p>伪代码思路如下：对每个候选预留比例 r，跑 N 步稳态迭代，记录每步的 GEMM 起止时间戳与 dispatch 完成时间戳，计算重叠窗口占比与窗口内空档长度的方差；取方差首次落入平台区的 r 作为下界，再向上取一档留余量。代价面：预留比例过高会直接削减可用 MMA 算力，等效于吞吐线性下降，因此这个比例是“气泡损失”与“算力损失”的交叉点，不是越大越好。</p>\n\n<h3 id=\"ap-expert-parallel-sec-16\">十六 · 测 k 与 combine 的通信量下界</h3>\n<p>k 的扫描必须与 combine 的聚合方式一起测，否则测出的数字没有意义。理论下界是 $$T \\cdot k \\cdot h$$ 量级，前提是 combine 阶段按 token 原设备聚合：同一 token 的 k 个专家输出应先汇聚到其原设备再加权求和。若实现按专家而非 token 原设备聚合，token 会被多次跨设备转发，实测通信量将系统性超出该下界——这是可测的：在 combine 微基准里统计每 token 的实际跨设备跳数，与 k 比较，跳数大于 k 即说明聚合点选错。</p>\n<p>测量口径要把 dispatch 与 combine 分开计，不能合并成一个“All-to-All 总时间”，否则 k 翻倍带来的线性上升会被重叠收益掩盖。工程判断：当 k=2 的实测 combine 时间已接近分组 GEMM 单步时间，继续加 k 的收益必须用端到端吞吐而非单算子延迟来验证；若 dispatch/combine 已占稳态步时间的主导份额，说明瓶颈在通信侧，此时提高 SM 预留比例只对重叠有效，对总量无效。</p>\n\n<h3 id=\"ap-expert-parallel-sec-17\">十七 · 跨域分层后的重测清单</h3>\n<p>一旦决定跨域扩展并改用分层 All-to-All，前述三个阈值全部需要在新的通信域分层下重测，因为域内段与跨域段的带宽档位不同，SM 预留的最优值也随之漂移。重测清单应包含：分层后域内段与跨域段各自的 dispatch 有效带宽、两段之间的同步点数量与由此引入的额外延迟、以及 combine 在分层聚合下是否仍满足按 token 原设备聚合的下界。表格化的记录方式便于横向比较不同 EP 组配置：</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>判据</th><th>失效信号</th></tr></thead><tbody><tr><td>EP 组域边界</td><td>均匀路由 dispatch 有效带宽 vs 组大小</td><td>曲线台阶位置</td><td>台阶后带宽低于可容忍通信时间</td></tr><tr><td>SM 预留比例</td><td>重叠流水内 GEMM 空档长度方差</td><td>方差进入平台区</td><td>气泡周期性出现且不随 batch 消失</td></tr><tr><td>k 的边际</td><td>dispatch/combine 分开计时</td><td>k=2 相对 k=1 翻倍</td><td>combine 跳数大于 k</td></tr><tr><td>分层同步开销</td><td>域内段与跨域段衔接处延迟</td><td>相对单域基线增量</td><td>同步点数量随组大小线性增长</td></tr></tbody></table>\n<p>这张表的价值在于把“经验数字”变成可复现的判据：任何一项失效信号出现，都指向具体机制而非笼统的“通信慢”。跨域分层后若同步点数量随组大小线性增长，说明分层切分过细，应回到减少 EP 组规模或降低 k 的路径上。</p>\n\n<h3 id=\"ap-expert-parallel-sec-18\">十八 · 测量纪律：固定口径再谈阈值</h3>\n<p>最后一条工程判断落在测量纪律上。所有阈值必须在同一口径下取得：token 数、路由分布、字节宽度、是否与容量因子耦合、dispatch 与 combine 是否分开计，任一项变动都会让数字失去可比性。特别是路由分布——均匀分布给出的是带宽基线，真实推理中的倾斜分布会把尾延迟推高（见路由倾斜尾延迟一篇），因此阈值应以均匀分布基线加倾斜分布压力测试两条曲线共同确定，取更保守者。测量时还应记录 SM 预留比例与同步原语类型，因为同一 EP 组在不同重叠策略下的有效带宽不同，把这两项写进记录才能让阈值在换框架、换拓扑后仍可追溯。没有实测数字时，唯一正确的写法是写清测量步骤与判据，而不是填一个看似合理的经验值。</p>\n\n<h3 id=\"ap-expert-parallel-sec-19\">十九 · EP 组边界与 SM 预留的工程判据：先量什么、卡在哪、怎么定阈值</h3>\n<p>把 EP 组画到哪条线上，是这一节要回答的唯一问题。判据不是“专家数够不够放”，而是 dispatch 段的有效带宽能否在分组 GEMM 的单个流水周期内把 T·k 个 token 送达。设单卡 NVLink 域内单向有效带宽为 B<sub>nv</sub>，跨域 IB 为 B<sub>ib</sub>，则 dispatch 时延可写成 <span class=\"formula\">$$t_{disp} \\approx \\frac{T \\cdot k \\cdot h \\cdot \\mathrm{bytes}}{B_{\\mathrm{eff}} \\cdot N_{\\mathrm{ep}}} + t_{sync}$$</span> 其中 B<sub>eff</sub> 取 B<sub>nv</sub> 或 B<sub>ib</sub> 取决于 EP 组是否跨出 NVL72 机架域，t<sub>sync</sub> 是 mbarrier 与 cluster barrier 的到达等待。工程上先测 B<sub>eff</sub>：固定 T、k、h，只跑 dispatch 的纯拷贝 kernel，用 CUDA event 卡两端时间戳，得实际单向吞吐；再在同一配置下跑完整 forward，两者之差即 GEMM 与 combine 的叠加代价。跨域时 B<sub>ib</sub> 明显低于 B<sub>nv</sub>，同一 T·k 下 t<sub>disp</sub> 被拉长到与分组 GEMM 同量级甚至更长，此时算力开始闲置——这就是“EP 组跨机架”踩坑的定量形态，而非定性感受。</p>\n<p>第二个要测的量是 SM 预留比例。SM100 上重叠依赖专用 SM 驱动 NVLink 拷贝与同步，其余 SM 跑 tcgen05 MMA。预留太少，拷贝 kernel 与 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡；预留太多，MMA 可用 SM 减少，分组 GEMM 本身变慢。测法：扫预留比例 r（个位数到十几个百分点区间），对每个 r 记录 (a) 单层 MoE 的端到端时延，(b) 用 Nsight 类工具看 MMA 流水空转周期占比，(c) dispatch 数据块进入 TMEM 暂存的平均等待。取时延曲线的拐点作为阈值，而不是取最小值——拐点右侧通常尾延迟更稳。注意气泡一旦由争抢引起，调 batch 无法消除，因为瓶颈在 SM 资源分配而非队列深度，这一点必须在测量中单独标记。</p>\n<p>第三个量是 k 的线性代价与 combine 的聚合口径。k 从 1 增到 2，All-to-All 通信量翻倍，这是硬性线性关系，没有压缩空间；因此 k 的取值必须与 EP 组大小一起做二维扫描，而不是单独调。combine 段要按 token 原设备聚合再回送，若按专家聚合，token 会被多次跨设备转发，实际通信量超出 T·k·h 的理论下界，测量上表现为 combine 时延显著高于 dispatch 时延（对称拓扑下两者应接近）。判别方法：分别计时 dispatch 与 combine，若 combine/dispatch 比值明显偏离 1，先查聚合口径再查带宽。</p>\n<p>把上述量组织成一张判据表，便于在容量规划时逐项打勾。<table class=\"mini\"><thead><tr><th>观测量</th><th>测量手段</th><th>阈值判据</th><th>越界后果</th></tr></thead><tbody><tr><td>B<sub>eff</sub>（dispatch 单向）</td><td>纯拷贝 kernel + event 计时</td><td>EP 组不跨 NVL72 域</td><td>dispatch 成主瓶颈，GEMM 闲置</td></tr><tr><td>SM 预留比例 r</td><td>扫 r，看 MMA 空转占比</td><td>取时延拐点，个位数到十几个百分点</td><td>流水气泡，调 batch 无效</td></tr><tr><td>combine/dispatch 时延比</td><td>两段分别计时</td><td>接近 1</td><td>聚合口径错，通信超下界</td></tr><tr><td>k 与 EP 组大小</td><td>二维扫描</td><td>k=2 通信量翻倍需预算</td><td>带宽预算击穿</td></tr></tbody></table> 这张表的价值在于把“EP 能扩多大”从架构直觉变成可复现的测量序列：先定域边界，再定 SM 预留，最后校聚合口径，三步都过才允许把 EP 组写进部署配置。</p>\n\n<h3 id=\"ap-expert-parallel-sec-20\">二十 · 把“经验值”变成可测的边界：EP 组、SM 预留与 k 的三条阈值</h3>\n<p>EP 组规模的硬边界不是专家数，而是<b>通信域边界</b>。把 EP 组压在单个 NVLink 域（NVL72 机架域）内时，dispatch/combine 走的是高带宽链路；一旦组跨出机架落到 IB，同一份 <span class=\"formula\">$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</span> 的通信量就要在更低的带宽档位上搬运，dispatch 段立刻从“可被 GEMM 掩盖”变成“决定 step 时间”。测量方法很直接：固定 T、k、h 与专家数，只改 EP 组大小做阶梯扫描，记录每档的 dispatch 耗时、combine 耗时与分组 GEMM 耗时三者之比；当 dispatch+combine 开始超过 GEMM 且随组增大单调恶化，该点就是本集群的 EP 组上限。判断依据是比值而非绝对毫秒，因为绝对值和 batch、序列长度强耦合。</p>\n<p>重叠不是免费的，它要用 SM 换。SM100 上让 NVLink 拷贝与 tcgen05 MMA 并行，必须划出专职驱动拷贝与同步的 SM，剩余 SM 才跑 MMA，靠 mbarrier 与 cluster 内 barrier 让到达的数据块在 GEMM 流水排空前进入 TMEM。预留比例的经验区间是个位数到十几个百分点，取值由“拷贝带宽需求 / 单 SM 可驱动的搬运速率”反推：预留不足时拷贝 kernel 与 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，且调 batch 消不掉——因为瓶颈是 SM 占用而非队列深度。测法：扫预留比例，画“GEMM 有效利用率 vs 预留 SM 数”曲线，拐点前利用率随预留上升，拐点后因计算 SM 不足而回落，取拐点偏左一档作为稳态配置，并单独记录尾延迟（长序列或热点专家倾斜时的 P99）。</p>\n<p>k 是最容易被低估的线性因子：k=2 相对 k=1 通信量翻倍，而专家容量随 EP 增大反而变小，两者叠加使“加大 EP 换容量”的收益被通信吃掉。工程上应把 k 与 EP 组大小放在同一张表里联合标定，而不是分别调优。combine 段还有一条隐性下界：必须按 token 原设备聚合后再回送，若按专家聚合，token 会被多次跨设备转发，实际通信量突破 <span class=\"formula\">$$T \\cdot k \\cdot h$$</span> 的理论下界，这类超额只能靠逐跳计数器（每 token 跨设备次数）暴露，常规带宽监控看不出来。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>测法</th><th>失效信号</th></tr></thead><tbody><tr><td>EP 组上限</td><td>固定 T/k/h 阶梯扩组，看 dispatch+combine 与 GEMM 耗时比</td><td>跨 IB 后比值单调恶化</td></tr><tr><td>SM 预留比例</td><td>扫预留 SM 数，画 GEMM 有效利用率曲线</td><td>拐点后回落、气泡调 batch 不消</td></tr><tr><td>combine 超额</td><td>逐 token 计跨设备跳数</td><td>跳数 &gt; 理论下界对应次数</td></tr></tbody></table>\n<h3 id=\"ap-expert-parallel-sec-21\">二十一 · 踩坑清单：先按“域边界”排雷</h3>\n<p>EP 推理的绝大多数事故不是算错，而是拓扑错。检查第一顺位永远是：EP 组是否严格落在单个 NVLink 域内。把 E 个专家摊到跨机架 IB 域上，表面上每设备专家数下降、单卡显存压力缓解，实际是把 dispatch/combine 从高带宽域内交换推到 IB 链路上——带宽档位下降、延迟抬升，All-to-All 立刻取代分组 GEMM 成为主瓶颈，而 tcgen05 MMA 的算力被闲置。判断方法很直接：取并行网格配置，标出每个 EP rank 的物理位置，若 EP 组跨越 NVL72 机架域边界，即为高危配置。此时要么把 EP 组收缩回单域、把多出的专家容量交给 TP 或 DP 承担，要么改用分层 All-to-All（域内 NVLink 先聚合、域间只走压缩后的流量），要么下调 k。三条路里，收缩 EP 组通常是代价最小的一条，因为它不改变数值路径。</p>\n<p>第二顺位是 k 与容量因子的耦合。k 从 1 增到 2，dispatch 与 combine 各一次全交换的通信量按 <span class=\"formula\">$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</span> 线性翻倍，而每专家分到的 token 数不变、容量因子不变，于是“通信翻倍、计算不变”的失衡直接体现在尾延迟上。检查时不要只看平均吞吐，要看 dispatch 段在时间轴上的占比：若 dispatch 已接近单次前向的关键路径长度，说明 k 或 EP 组大小至少有一个该退。</p>\n<p>第三顺位是 combine 的聚合口径。combine 必须按 token 原设备聚合，把同一 token 在各专家上的输出加权求和后一次送回；若实现成按专家逐个回传，token 会被多次跨设备转发，通信量突破 <span class=\"formula\">$$T \\cdot k \\cdot h$$</span> 的理论下界，且每次转发都带一次同步开销。这是一个纯软件坑，但在自研 kernel 与部分框架的早期实现里反复出现。</p>\n\n<h3 id=\"ap-expert-parallel-sec-22\">二十二 · 重叠失效：SM 预留不足的隐性气泡</h3>\n<p>SM100 上让通信与分组 GEMM 重叠，前提是资源隔离而非时间片抢占。机制上需要一部分 SM 专职驱动 NVLink 拷贝与同步，其余 SM 执行 tcgen05 MMA，两侧通过 mbarrier 与 cluster 内 barrier 做细粒度握手，使 dispatch 到达的数据块在 GEMM 流水未排空前就进入 TMEM 暂存。若没有预留专用 SM，拷贝 kernel 会与 MMA 争抢同一 SM 的 warp slot：表面上两个 kernel 都在跑，实际是周期性互相打断，流水出现规律性气泡，且这种气泡无法靠调 batch 消除——因为它是资源竞争的结构性结果，不是排队问题。</p>\n<p>检查顺序是：先看 SM 预留比例是否落在个位数到十几个百分点的常见区间，再看同步原语是否真的细到数据块粒度。若同步只在整段 dispatch 结束时做一次 barrier，那么即便预留了 SM，重叠也只是“先通信后计算”的伪装，收益为零而复杂度照付。代价口径上，预留比例偏小则气泡重现，偏大则分组 GEMM 的有效算力被削，二者之间的窗口不宽，需要用实际 profile 定位而非拍脑袋。一个可操作的判据：把预留比例从当前值上下各调一档，若吞吐对比例高度敏感，说明正处在气泡与算力损失的夹缝里，应优先改同步粒度而不是继续调比例。</p>\n\n<h3 id=\"ap-expert-parallel-sec-23\">二十三 · 检查顺序：从静态配置到动态剖面</h3>\n<p>把排查排成固定次序，能避免在错误层面反复打转。建议的顺序是：配置层 → 通信量层 → 重叠层 → 数值层。</p>\n<ul>\n<li><strong>配置层</strong>：并行网格（TP×EP×DP 比例）、EP 组大小与域边界、每设备专家数 E/DP、k 值、容量因子。这一层只读配置就能排除掉跨域与 k 失衡两类大坑。</li>\n<li><strong>通信量层</strong>：dispatch 与 combine 分别计量，不要合并成一个“通信开销”。两段各一次全交换，量级同为 <span class=\"formula\">$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</span>，但瓶颈可能只落在其中一段——dispatch 受路由倾斜影响，combine 受聚合口径影响。</li>\n<li><strong>重叠层</strong>：SM 预留比例、同步原语类型、气泡周期。用时间轴看拷贝与 MMA 的交替形态，而不是只看总利用率。</li>\n<li><strong>数值层</strong>：量化后路由漂移、容量因子导致的丢弃。这一层放在最后，是因为它常被误判为通信问题——尾延迟升高时先怀疑 All-to-All，实际可能是路由漂移把 token 挤到了少数专家上，放大了倾斜。</li>\n</ul>\n<p>每一层都配一个可回退的判据：配置层看域边界是否越界；通信量层看实测是否显著高于 <span class=\"formula\">$$T \\cdot k \\cdot h$$</span> 下界；重叠层看气泡是否随 batch 变化（随 batch 变化的是排队，不随的是资源竞争）；数值层看专家负载分布的偏斜度。</p>\n\n<h3 id=\"ap-expert-parallel-sec-24\">二十四 · 回滚方案：三条退路与各自的代价</h3>\n<p>改动 EP 配置必须预设退路，否则一次跨域扩缩容会把整条推理链路拖进不可用状态。三条退路按代价从低到高排列：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>退路</th><th>动作</th><th>恢复的指标</th><th>代价</th></tr>\n</thead>\n<tbody>\n<tr><td>降 k</td><td>k=2 回退到 k=1</td><td>dispatch/combine 通信量减半</td><td>路由质量下降，需重评精度</td></tr>\n<tr><td>收缩 EP 组</td><td>把 EP 组拉回单 NVLink 域</td><td>All-to-All 回到高带宽档位</td><td>每设备专家数上升，显存压力回升</td></tr>\n<tr><td>改分层 All-to-All</td><td>域内聚合后再跨域</td><td>跨域流量被压缩</td><td>实现复杂度与同步开销上升</td></tr>\n</tbody>\n</table>\n<p>回滚的触发条件要写死，不能靠人盯：dispatch 段占关键路径比例超过设定阈值、或 combine 实测通信量显著高于理论下界、或 SM 预留调整后吞吐仍对比例敏感，三者任一命中即触发。降 k 是最快的一条，因为它只改路由参数不动拓扑；收缩 EP 组需要重排专家放置，通常要停一次流量；分层 All-to-All 是结构性改造，只在跨域扩展确有必要时才动。</p>\n<p>还有一条不写在表里的退路：把重叠关掉，退回串行通信-计算。它的吞吐必然下降，但能把“气泡”这个不可解释的抖动变成可预测的串行时间，从而让容量规划重新可算。在 SLO 紧张、又来不及定位资源竞争根因时，这是唯一能立刻止损的工程判断。</p>\n\n<h3 id=\"ap-expert-parallel-sec-25\">二十五 · 死锁与顺序：检查清单里最容易被跳过的一格</h3>\n<p>通信计算死锁在 EP 里不是理论风险。All-to-All 是集合通信，所有 rank 必须按同一顺序进入 dispatch 与 combine；一旦某些 rank 因容量因子丢弃而提前退出、或分组 GEMM 的完成顺序在不同 rank 上不一致，就会出现部分 rank 在等 barrier、另一部分已在发下一轮 dispatch 的局面。检查清单里要单独列一格：dispatch 与 combine 的进入条件是否对所有 rank 对称，丢弃逻辑是否在集合通信之外完成。代价是整条流水停摆，表现为吞吐骤降到零而非缓慢劣化——这与带宽瓶颈的形态完全不同，可据此快速区分。</p>\n<p>顺序问题的另一面是 combine 与下一层 dispatch 的交叠。若把 combine 的尾部与下一轮 dispatch 的头部重叠，必须保证 token 原设备的聚合已完成，否则下一轮路由读到的是未加权求和的部分结果。这一条在分层 All-to-All 下尤其危险，因为域间压缩会改变到达顺序。工程上的稳妥做法是给 combine 的完成加一个显式的 cluster 内 barrier，再放行下一轮 dispatch，用一次同步换掉一类静默错误。</p>\n\n<h3 id=\"ap-expert-parallel-sec-26\">二十六 · 清单落地：把判据写成可执行的检查项</h3>\n<p>最后把上述内容压成一张可执行的清单，每项都带判据而非描述：EP 组是否越出 NVLink 域边界（是则高危）；k 与容量因子是否同向调整（否则通信与计算失衡）；dispatch 与 combine 是否分别计量（合并计量则无法定位瓶颈段）；SM 预留比例是否在个位数到十几个百分点区间且同步粒度到数据块（否则重叠为伪）；combine 是否按 token 原设备聚合（否则通信量越界）；集合通信进入条件是否对所有 rank 对称（否则死锁）；回滚触发条件是否写死并绑定降 k、收缩 EP 组、分层三条退路。这张清单的价值不在于长，而在于每一项都能在配置或 profile 里一眼判定，不需要二次推理。</p>\n<p>真正决定这套清单是否有效的，是它能否在改动前被执行而不是在故障后被想起。EP 配置的每一次扩缩容，都应当先在配置层过一遍域边界与 k 的耦合，再决定是否值得动重叠策略——因为跨域与 k 失衡这两个坑，一旦踩进去，后面所有的 SM 预留调优都是在错误的地基上做装修。</p>\n\n<h3 id=\"ap-expert-parallel-sec-27\">二十七 · 踩坑清单：EP 组边界、SM 争抢与 combine 聚合</h3>\n<p>EP 推理最贵的错误发生在拓扑层，而且往往在容量规划阶段就被埋下：为了容纳更多专家，把 EP 组从单 NVLink 域扩到跨机架 IB 域。此时 dispatch/combine 的通信量口径不变，仍是 <span class=\"formula\">$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</span> 量级（T 为 token 数、k 为每 token 路由专家数、h 为隐维），但承载它的链路从 NVLink 换成 IB，带宽下降、延迟上升，All-to-All 立刻成为主瓶颈，而分组 GEMM 的算力大量闲置。检查顺序应固定为：先确认 EP 组大小与域边界严格对齐（如 NVL72 机架域），再核对 k 取值——k=2 相对 k=1 通信量直接翻倍，扩容前先问 k 能否降；最后才看重叠策略。回滚方案是把 EP 组收回单域、以分层 All-to-All 跨域，或降低 k 换取带宽余量，代价是每专家容量因子变小、路由质量下降。</p>\n<p>第二个坑是重叠期的 SM 争抢。SM100 上要让 dispatch 的数据块在分组 GEMM 流水排空前进入 TMEM 暂存，必须预留个位数到十几个百分点的 SM 专职驱动 NVLink 拷贝与 mbarrier/cluster barrier 同步，其余 SM 跑 tcgen05 MMA。若不预留，拷贝 kernel 与 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，且调 batch 无法消除——因为气泡源于资源竞争而非队列深度。判定方法是看气泡是否随 batch 变化而漂移：不漂移即为 SM 预留不足。回滚即调高预留比例，代价是 GEMM 可用算力下降、单卡吞吐略降，属于用吞吐换尾延迟稳定性的确定性交易。</p>\n<p>第三个坑在 combine：按专家而非 token 原设备聚合输出，token 被多次跨设备转发，实际通信量超出 <span class=\"formula\">$$T \\cdot k \\cdot h$$</span> 的理论下界。正确做法是以 token 原设备为聚合目标，一次回送并加权求和。检查清单可压缩为一张表：</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判据</th><th>失效代价</th></tr></thead><tbody><tr><td>EP 组域边界</td><td>组大小 ≤ 单 NVLink 域</td><td>dispatch 走 IB，带宽骤降</td></tr><tr><td>k 与通信量</td><td>k=2 即翻倍，扩容前先降 k</td><td>All-to-All 成主瓶颈</td></tr><tr><td>SM 预留</td><td>个位数至十几个百分点</td><td>流水周期性气泡</td></tr><tr><td>combine 聚合目标</td><td>按 token 原设备</td><td>通信量超理论下界</td></tr></tbody></table>\n<p>这张表的检查顺序不可颠倒：域边界与 k 决定通信量下界，SM 预留决定重叠收益能否兑现，combine 聚合决定实际通信量是否贴着下界走。三者任一失守，容量因子与 batch 调度都救不回来。</p>\n\n<h3 id=\"ap-expert-parallel-sec-28\">二十八 · 坑位边界：EP 组跨域、SM 抢占与 combine 聚合错位</h3>\n<p>三类失效在工程上最贵。第一类是 EP 组越过 NVLink 域边界：为容纳更多专家把组扩到跨机架 IB，dispatch 段带宽骤降，All-to-All 成为主瓶颈，而分组 GEMM 算力闲置——此时加 batch 只会加深排队，不会提升吞吐。第二类是重叠未预留专用 SM：NVLink 拷贝 kernel 与 tcgen05 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，调 batch 无法消除，因为瓶颈是 SM 资源而非队列深度。第三类是 combine 聚合错位：按专家而非 token 原设备聚合，token 被多次跨设备转发，通信量突破 \\(T \\cdot k \\cdot h \\cdot \\mathrm{bytes}\\) 的理论下界。判定边界可用一条粗算：设单 token 单跳代价为 \\(c_{\\text{NV}}\\)（域内）与 \\(c_{\\text{IB}}\\)（跨域），则 dispatch+combine 总代价约为 \\(2Tk h \\cdot \\mathrm{bytes} \\cdot c\\)，当 \\(c_{\\text{IB}}/c_{\\text{NV}}\\) 的比值使该项超过分组 GEMM 时间，跨域即不成立。</p>\n<p>检查顺序按“拓扑→资源→聚合→尾延迟”推进，不要反过来从调参入手。</p>\n<table class=\"mini\"><thead><tr><th>顺序</th><th>检查项</th><th>判据</th><th>失效代价</th></tr></thead><tbody>\n<tr><td>1</td><td>EP 组是否落在单 NVLink 域（如 NVL72 机架域）</td><td>组内任一对设备跨 IB 即告警</td><td>dispatch 带宽骤降，GEMM 闲置</td></tr>\n<tr><td>2</td><td>SM 预留比例是否落实</td><td>个位数到十几个百分点，且拷贝 kernel 不落计算 SM</td><td>流水周期性气泡</td></tr>\n<tr><td>3</td><td>combine 是否按 token 原设备聚合</td><td>每 token 只回原设备一次</td><td>通信量超理论下界</td></tr>\n<tr><td>4</td><td>k 与容量因子耦合</td><td>k=2 时通信量翻倍，每专家容量减半</td><td>尾延迟抬升、丢弃率上升</td></tr>\n</tbody></table>\n<p>回滚方案要按“可逆粒度”设计，而非整体回退到 TP-only。第一档：把 EP 组收缩回单 NVLink 域，多余专家改由 DP 复制承载，代价是每设备专家数上升、显存吃紧，但 All-to-All 回到域内带宽档位。第二档：降低 k（k=2→1）直接砍掉一半通信量，代价是路由质量下降、专家负载更不均。第三档：关闭重叠、退回串行 dispatch-GEMM-combine，SM 全部给 MMA，代价是暴露全部通信延迟但消除气泡。三档应做成配置开关而非代码分支，回滚时只改并行网格描述与 SM 预留参数，不动 kernel；同时保留 dispatch/combine 分段计时，否则回滚后无法判断是带宽恢复还是聚合修正起了作用。</p>\n<h3 id=\"ap-expert-parallel-sec-29\">二十九 · 上游依赖：并行网格与通信域分层是 EP 的前置约束</h3>\n<p>EP 条目不是孤立存在的，它的每一个工程决策都建立在并行网格的划分结果之上。注意力层用 TP、MoE 层用 EP、batch 复制用 DP，三者组合成 TP×EP×DP 的混合网格后，通信域随之分层：TP 组内是高频小消息（每层都要 all-reduce），EP 组内是低频大消息（每 token 一次 dispatch/combine），DP 组通常只做梯度或参数同步之外的推理侧复制。这个分层直接决定了 All-to-All 的物理路径——EP 组边界若与 NVLink 域边界重合，dispatch/combine 走机架内高带宽链路；若 EP 组跨越域边界，消息被迫落到 IB 上。因此 EP 规模的上限不是由专家数量决定的，而是由并行网格划分时通信域与物理拓扑的对齐关系决定的。上游一旦把 EP 组切到跨域，下游任何重叠策略、SM 预留比例都无法把带宽缺口补回来。这里的代价是结构性的：dispatch 通信量为 <span class=\"formula\">$$T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</span> 量级，k 从 1 增到 2 就翻倍，跨域带宽下降后这条式子里的带宽项成为主约束，分组 GEMM 的算力被闲置。具体例子：NVL72 机架域内做 EP=64 的 dispatch 是可行配置，但把同一 EP 组扩到两个机架、让部分专家落在 IB 域外，dispatch 阶段立刻从 NVLink 档位跌到 IB 档位，尾延迟由通信而非 MMA 决定。</p>\n<p>上游依赖还有一层：容量因子与 EP 大小的耦合。EP 越大，每设备持有的专家数 E/DP 越少，单专家承载的 token 容量越紧，路由倾斜时丢弃风险上升。这个耦合关系在上游的容量规划里已经定死，EP 条目只能在其约束下选择 k 与重叠策略，不能反过来放宽容量因子来换通信量。换句话说，EP 的拓扑选择是被上游并行网格与容量因子共同夹住的可行域，而不是自由参数。</p>\n\n<h3 id=\"ap-expert-parallel-sec-30\">三十 · 上游依赖：数值精度与分组 GEMM 决定重叠的可行性</h3>\n<p>通信与分组 GEMM 重叠不是无条件的。SM100 上要让 dispatch 到达的数据块在 GEMM 流水未排空前进入 TMEM 暂存，前提是分组 GEMM 的 tile 粒度与 dispatch 的消息粒度匹配。tcgen05 MMA 的 tile 形状、NVFP4/FP8 权重激活的打包格式，决定了专家侧一次能消费多大的 token 块；dispatch 若按更细的粒度到达，重叠收益被同步开销吃掉，若按更粗的粒度到达，TMEM 暂存区装不下。上游的量化格式还影响路由漂移——量化后专家打分变化会让 dispatch 的目标设备分布偏移，重叠流水里预设的 SM 预留比例可能不再匹配实际到达模式。因此 EP 条目的重叠策略必须读取上游的 tile 配置与量化方案，而不是独立设定一个 SM 预留比例。代价体现在流水气泡上：预留个位数到十几个百分点的 SM 专职驱动 NVLink 拷贝与同步，其余 SM 跑 tcgen05 MMA，同步原语用 mbarrier 与 cluster 内 barrier 做细粒度握手；一旦 tile 粒度错配，mbarrier 等待时间拉长，预留的 SM 空转，等效于把算力按预留比例白白扣掉。具体例子：FP8 打包下专家侧消费 128 token 一块，dispatch 却以 64 token 为粒度到达，两次到达才能填满一个 MMA tile，同步次数翻倍，重叠窗口被切碎。</p>\n\n<h3 id=\"ap-expert-parallel-sec-31\">三十一 · 下游影响：尾延迟、KV 压缩与分离式预填解码都吃 EP 的通信账</h3>\n<p>EP 的 dispatch/combine 通信量是下游多个条目的输入参数。路由倾斜尾延迟条目关心的是：combine 阶段若未按 token 原设备聚合，token 被多次跨设备转发，实际通信量超出 <span class=\"formula\">$$T \\cdot k \\cdot h$$</span> 的理论下界，尾延迟由最慢的那条多跳路径决定。EP 条目给出的聚合顺序与域边界，直接决定了下游尾延迟分析的分母。MoE 场景 KV 压缩条目则依赖 EP 的容量耦合：EP 组越大每专家容量越小，KV 压缩的收益被专家侧丢弃风险抵消，压缩策略必须知道 EP 规模才能定压缩比。分离式预填/解码条目把预填与解码拆到不同资源池后，EP 的 All-to-All 变成跨池通信——预填池产出的 token 要 dispatch 到解码池的专家，若两池不在同一 NVLink 域，dispatch 走 IB，分离式架构的收益被通信吃掉。这里的代价是延迟预算的重新分配：分离式把预填的算力密集段与解码的带宽密集段分开，但 EP 的 All-to-All 恰好横跨两者，成为连接处的固定开销。具体例子：预填池与解码池各占半个 NVL72 机架，EP 组横跨两池时 dispatch 必须跨域，分离式带来的预填吞吐提升被 dispatch 延迟部分抵消；若把 EP 组限制在解码池内的 NVLink 域、预填池只做注意力与路由计算，则 dispatch 留在域内，代价转为预填池到解码池的 KV/激活传输。</p>\n\n<h3 id=\"ap-expert-parallel-sec-32\">三十二 · 下游影响：框架选型与剖析工具链以 EP 拓扑为坐标</h3>\n<p>MoE 推理框架选型条目的判断依据之一是框架对分层 All-to-All 的支持程度：单机 NVLink、多机 IB、分层三种拓扑对应不同的通信原语与 SM 预留接口。EP 条目定义的拓扑分类（并行维度组合、All-to-All 拓扑、重叠策略、通信量口径、容量耦合）就是框架选型的坐标轴——框架若只支持单层 All-to-All，跨域扩展就只能靠降低 k 硬扛；支持分层 All-to-All 的框架可以把域内与域间拆成两段，域内走 NVLink、域间走 IB 并做聚合压缩。剖析工具链条目同样以 EP 为观测对象：dispatch/combine 分别计的通信量口径、SM 预留比例、同步原语类型，都是工具链要采样的字段。没有这些字段，工具链只能看到总通信时间，无法区分是带宽不足还是同步气泡。代价在可观测性上：EP 拓扑不透明时，调 batch 无法消除周期性气泡，因为气泡根源是 SM 争抢而非 batch 不足。具体例子：框架若不暴露 SM 预留比例参数，NVLink 拷贝 kernel 与 tcgen05 MMA 争抢同一 SM 的 warp slot，剖析工具只能看到利用率抖动，定位不到预留不足这一层。</p>\n\n<h3 id=\"ap-expert-parallel-sec-33\">三十三 · 在全书中的位置：EP 是并行与通信卷的收口环节</h3>\n<p>把全书结构摊开看，EP 条目处在“并行与通信”这一卷的收口位置：上游是算子与数值精度卷给出的 tile 与量化格式、显存与 KV cache 卷给出的容量约束、批调度卷给出的 token 到达分布；下游是 SLO 与容量规划卷需要的通信账、七个领域推理形态各自对 EP 规模的偏好。它不生产新的数值格式，也不定义调度策略，而是把上游的这些参数翻译成一张通信拓扑与重叠方案，再把通信代价交给下游做容量规划。这个位置决定了它的写法：不能重复上游的基础定义（量化格式、KV 压缩原理在各自条目已讲），也不能替下游做 SLO 决策，只能给出机制、公式与代价的接口。工程判断落在这里：EP 组边界与 NVLink 域边界对齐是硬约束，SM 预留比例是软约束但必须与 tile 粒度联动；前者错了无法用调参补救，后者错了表现为周期性气泡。容量规划卷拿到 EP 的 dispatch/combine 通信量公式与域边界后，才能把 All-to-All 时间算进 SLO 预算；七个领域条目拿到 EP 规模上限后，才能判断自己的专家数量是否落在单域内。EP 条目因此是并行网格、数值精度、调度、容量规划四者交汇的那一个节点，它的输出是一组可被下游直接引用的拓扑参数与代价口径，而不是一套独立的优化配方。</p>\n\n<h3 id=\"ap-expert-parallel-sec-34\">三十四 · 边界条件：EP 组何时失效、代价落在哪一层</h3>\n<p>EP 组规模不是可随意放大的旋钮，它的上限由 NVLink 域边界硬性钉住。当专家数 E 增长到需要跨机架时，dispatch/combine 从 NVLink 落到 IB，带宽档位下降、延迟抬升，All-to-All 立刻取代分组 GEMM 成为主瓶颈——此时算力并未减少，只是闲置。判断失效的判据不是“专家放不下”，而是通信时间与计算时间的比值：设单层分组 GEMM 时间为 <span class=\"inline\">T_c</span>，两段 All-to-All 时间为 <span class=\"inline\">T_a</span>，重叠后单层实际耗时为 <span class=\"inline\">max(T_c, T_a)</span> 加同步开销；一旦 <span class=\"inline\">T_a &gt; T_c</span>，重叠失去意义，扩 EP 只换来更长的 dispatch 尾巴。工程上把 EP 组限制在单 NVLink 域（NVL72 机架域）内，跨域扩展改用分层 All-to-All 或降低 k，是唯一不破坏流水的前提。这条边界同时向上游传导：容量因子随 EP 增大而每专家容量变小，批调度条目里的 token 分布假设必须跟着改；向下游则决定了分离式预填/解码的部署形态——预填节点与解码节点若不在同一 NVLink 域，KV 与 token 的搬运会把 EP 的收益吃掉。</p>\n<p>第二个失效条件是 SM 资源预留不足。重叠依赖“部分 SM 专职驱动 NVLink 拷贝与同步、其余 SM 跑 tcgen05 MMA”这一分工，若拷贝 kernel 与 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，且这种气泡无法靠调 batch 消除——它不是排队问题，是资源争用问题。预留比例常见个位数到十几个百分点，低于该区间则 dispatch 到达的数据块无法在 GEMM 流水排空前进入 TMEM 暂存，mbarrier 与 cluster 内 barrier 的细粒度同步退化为粗粒度等待。代价表现为尾延迟：平均吞吐看似正常，P99 却被周期性气泡拉高，SLO 条目里的容量规划必须按尾延迟而非均值留余量。</p>\n<p>第三个失效条件在 combine 阶段。若按专家而非 token 原设备聚合输出，token 被多次跨设备转发，通信量超出理论下界。两段全交换的下界是</p>\n<div class=\"formula\">$$C_{\\min} = 2 \\cdot T \\cdot k \\cdot h \\cdot \\mathrm{bytes}$$</div>\n<p>其中系数 2 对应 dispatch 与 combine 各一次，k 为每 token 路由专家数；k=2 相对 k=1 通信量翻倍，这是线性关系而非可摊销的成本。按 token 原设备聚合意味着 combine 前先在专家侧完成加权求和、再单次回送，任何“边算边转发”的实现都会把系数推高到 2 以上。这条约束与拓扑选择耦合：单机 NVLink、多机 IB、分层三种拓扑的通信量口径必须 dispatch/combine 分别计，混算会低估 IB 段的占比。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发点</th><th>系统代价落点</th></tr></thead><tbody><tr><td>EP 组跨 NVLink 域</td><td>专家数超出机架域容量</td><td>dispatch 带宽骤降，GEMM 算力闲置</td></tr><tr><td>SM 预留不足</td><td>拷贝 kernel 抢占计算 SM</td><td>周期性气泡，P99 尾延迟抬升</td></tr><tr><td>combine 未按原设备聚合</td><td>按专家聚合输出</td><td>通信量超 <span class=\"inline\">T·k·h</span> 下界，重复往返</td></tr></tbody></table>\n<p>把这三条放回全书位置看：本条目上游承接并行维度组合（TP×EP×DP 网格决定通信域分层）与显存/KV cache 条目（每专家容量随 EP 缩小），下游向批调度输出“EP 组内 token 分布不均会放大 All-to-All 尾延迟”的约束，向分离式部署输出“预填与解码必须同域”的拓扑前提，向 SLO 与容量规划输出以 <span class=\"inline\">max(T_c, T_a)</span> 为分母的容量公式。速查表因此必须同时含并行网格配置、EP 组大小与域边界、dispatch/combine 分列通信量、NVLink 与 IB 带宽档位、SM 预留比例、同步原语类型、重叠收益与尾延迟风险七列——缺任一项，读者就无法判断自己的配置是否已越过失效边界。</p>\n\n<h3 id=\"ap-expert-parallel-sec-35\">三十五 · 边界条件与全书坐标：EP 方案何时失效、向何处传导</h3>\n<p>本条目描述的 EP 方案有一条硬边界：<strong>EP 组不得跨越 NVLink 域</strong>。NVL72 机架域内 All-to-All 走 NVLink，跨域即退化为 IB，带宽下降、延迟上升，dispatch 立刻取代分组 GEMM 成为主瓶颈——算力闲置而链路饱和。失效判据可写成域内/域外通信时间之比：<div class=\"formula\">$$\\frac{t_{\\text{IB}}}{t_{\\text{NVLink}}}=\\frac{B_{\\text{NVLink}}}{B_{\\text{IB}}}\\cdot\\frac{1}{\\eta_{\\text{IB}}}$$</div>其中 $\\eta_{\\text{IB}}$ 为协议与拥塞效率损失。当该比值超过分组 GEMM 单波时间占比，重叠设计即告失效。第二个失效条件是 SM 预留不足：拷贝 kernel 与 tcgen05 MMA 争抢同一 SM 的 warp slot，流水出现周期性气泡，调 batch 无法消除。第三个是 combine 未按 token 原设备聚合，token 被多次转发，通信量突破 $T\\cdot k\\cdot h$ 下界。</p>\n<p>上游依赖集中在三处：并行网格定义（TP×EP×DP 比例决定通信域分层与 EP 组大小）、拓扑与带宽档位（NVLink 域边界即 EP 组上限）、以及 SM100 的同步原语（mbarrier 与 cluster barrier 决定 dispatch 数据块能否在 GEMM 流水未排空前进入 TMEM）。下游影响则传导至容量规划与 SLO：EP 越大每专家容量越小，k 增大使通信量线性上升（k=2 相对 k=1 翻倍），尾延迟由最慢那一段 All-to-All 决定。下表给出边界判定口径。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>正常态</th><th>失效态</th></tr></thead><tbody><tr><td>EP 组边界</td><td>单 NVLink 域内</td><td>跨机架走 IB，dispatch 成瓶颈</td></tr><tr><td>SM 预留</td><td>个位数至十几个百分点专职拷贝</td><td>无预留，气泡不可调</td></tr><tr><td>combine 聚合</td><td>按 token 原设备</td><td>按专家聚合，重复往返</td></tr></tbody></table>\n<p>在全书中的位置：本条目是“并行与通信”模块的收口件，向上承接精度与算子条目（tcgen05 MMA 的 SM 占用是重叠前提），向下为批调度与分离式预填/解码提供约束——连续批处理的 batch 上限受 EP 组容量因子制约，PD 分离的 decode 池若跨域部署则直接触发上述失效。工程判断落在一条：先按 NVLink 域切 EP 组，再谈重叠比例与 k 值。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-expert-parallel\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>区分专家并行、张量并行与数据并行的组合方式，说明 All-to-All 的 dispatch/combine …</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-expert-parallel · 共 5 个片段</p>\n"},{"id":"ap-grouped-gemm-tcgen05","title":"分组GEMM与tcgen05","summary":"解释按专家分组的变长 GEMM 如何映射到 tcgen05 MMA 与 TMEM，说明 M 维对齐、padding 浪费、累加器复用与 warp specialization 的调度约束，并给出分组数增大时 kernel 启动与尾块效率的量化权衡。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-1\">一 · 条目的准确定义：什么算一次分组 GEMM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-2\">二 · 分类维度一：分组依据与 M 对齐粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-3\">三 · 分类维度二：累加器复用策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-4\">四 · 分类维度三：warp specialization 角色划分与同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-5\">五 · 分类维度四：尾块处理与通信重叠的 SM 预留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-6\">六 · 边界条件：分组 GEMM 在什么情况下反而变慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-7\">七 · 速查表的字段口径：先定义“量的是什么”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-8\">八 · 速查表主体：字段、典型取值与判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-9\">九 · 阈值怎么用：三个联合判据而非单点门限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-10\">十 · 一个照表执行的例子：短专家占比高的分组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-11\">十一 · 表外但必须同表检查的两个耦合项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-12\">十二 · 速查表：分组 GEMM 落到 tcgen05 时的边界与代价口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-13\">十三 · 对齐粒度的实测标定：从名义 M 到有效 M</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-14\">十四 · 累加器驻留的容量阈值：TMEM 决定分波数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-15\">十五 · 尾块效率：拐点只能测不能猜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-16\">十六 · 启动与 barrier 开销的摊销判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-17\">十七 · 测量协议：把三个阈值串成一条流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-18\">十八 · 阈值不是拍脑袋：对齐粒度、padding 率与尾块拐点的实测口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-19\">十九 · 踩坑清单：三类高频失效的机理拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-20\">二十 · 检查顺序：从路由分布到 kernel 计数的自底向上排查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-21\">二十一 · 调参联合空间：分组数、对齐粒度与组大小分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-22\">二十二 · 回滚方案：分级降级与可逆开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-23\">二十三 · 上线前检查清单与判定落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-24\">二十四 · 分组 GEMM 上机前的失效模式与回滚路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-25\">二十五 · 踩坑清单与回滚判据：从 padding 率反推对齐粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-26\">二十六 · 上游依赖：路由分布是分组 GEMM 的输入契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-27\">二十七 · 上游依赖：量化精度与权重布局决定 MMA 形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-28\">二十八 · 下游影响：与 All-to-All 重叠时的 SM 资源分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-29\">二十九 · 下游影响：分离式预填/解码与 KV 压缩改变分组形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-30\">三十 · 下游影响：框架与剖析工具链的观测口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-31\">三十一 · 在全书中的位置：算子精度层与调度层的接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-grouped-gemm-tcgen05-sec-32\">三十二 · 边界条件：分组 GEMM 在什么情况下反而变慢</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-grouped-gemm-tcgen05\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：分组GEMM与tcgen05</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">解释按专家分组的变长 GEMM 如何映射到 tcgen05 MMA 与 </text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">TME…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-1\">一 · 条目的准确定义：什么算一次分组 GEMM</h3>\n<p>分组 GEMM 在推理系统里的准确定义是：把一次前向中按路由结果切出的若干变长 token 段，按目标权重矩阵的归属重新拼接成多个 M 维互不相等的 GEMM，每组恰好对应一个专家的权重矩阵。它的“分组”不是数据并行意义上的分组，也不是把一个大 GEMM 沿 K 或 N 切块的分块，而是沿 M 维按语义归属做的不等长切分。判断一个算子是否属于本条目，看三条同时成立：其一，组数与权重矩阵数量绑定（典型是专家数 E）；其二，各组的 M 由运行时数据决定，编译期不可知；其三，各组共享同一套 kernel 骨架，只在组描述符上不同。</p>\n<p>在 Blackwell 上，每组映射为若干条 tcgen05 MMA 指令，累加器驻留 TMEM，因此“一组”在硬件上的最小闭合单元不是一次 MMA，而是一串 MMA 加上它们共享的那块 TMEM 累加器。这个定义直接决定了后面所有分类维度：M 维必须对齐到 MMA 指令粒度（64 或 128），未对齐部分靠 padding 补齐；组与组之间是否复用同一块累加器，决定了 TMEM 读写次数随组数如何增长。</p>\n<p>与相邻概念的分界要划清楚。分组 GEMM 不等于 batched GEMM：后者各组形状一致、可静态排布，而分组 GEMM 的组形状是数据相关的，且组间存在对齐与尾块问题。它也不等于稀疏 GEMM：稀疏性来自权重结构，分组来自激活侧的 token 归属，两者的 padding 语义完全不同。它更不等于 All-to-All 通信本身——通信只负责把 token 送到持有专家的设备，分组 GEMM 是通信落地之后在本地做的计算形态，两者可以重叠但不可互相替代。</p>\n<div class=\"formula\">$$\\text{有效算力利用率} \\;=\\; \\frac{\\sum_{e} M_e^{\\text{real}}}{\\sum_{e}\\lceil M_e^{\\text{real}}/A\\rceil \\cdot A}$$</div>\n<p>其中 $A$ 为对齐粒度，$M_e^{\\text{real}}$ 为第 $e$ 组真实 token 数。这个比值是分组 GEMM 的第一性能指标，它把“名义 token 数”和“实际被 MMA 消化的 token 数”分开。工程代价直接体现在这里：当短专家占比高时，分母被零填充撑大，MMA 吞吐被稀释，而 kernel 的启动与 barrier 开销却按组数照付。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-2\">二 · 分类维度一：分组依据与 M 对齐粒度</h3>\n<p>第一个分类维度是分组依据。按专家分组是最常见的形态，组数等于被激活的专家数；按容量上限分组则出现在容量因子约束下，路由侧先把 token 截断或丢弃到每组容量上限，再按上限切组，此时组形状更规整但语义上已不是纯粹的专家归属。两者的区别不在 kernel 内部，而在组描述符的生成侧：按专家分组时组大小分布由路由倾斜决定，按容量上限分组时分布被人工压平，padding 率与尾块形态随之改变。</p>\n<p>第二个维度是 M 对齐粒度，常见取 64 或 128。粒度越小，短专家的零填充越少，但每条 MMA 指令覆盖的 M 越窄，指令发射密度上升、单指令效率下降；粒度越大，长组更饱满，短组浪费更严重。选粒度本质是在“短组 padding 浪费”和“指令发射开销”之间取平衡，而这个平衡点随每专家 M 分布移动，不能用一个固定值覆盖所有负载。</p>\n<table class=\"mini\"><thead><tr><th>分类维度</th><th>取值</th><th>直接影响的代价</th></tr></thead><tbody><tr><td>分组依据</td><td>按专家 / 按容量上限</td><td>组大小分布形态、padding 率</td></tr><tr><td>M 对齐粒度</td><td>64 / 128</td><td>零填充比例、MMA 指令密度</td></tr><tr><td>累加器复用</td><td>跨组合并 / 逐组重置</td><td>TMEM 读写与同步开销</td></tr><tr><td>warp 角色划分</td><td>加载 / 发射 / epilogue 分离</td><td>同步点数量、尾块并行度</td></tr><tr><td>尾块处理</td><td>padding / 拆分</td><td>SM 占用率、kernel 启动开销</td></tr><tr><td>通信重叠</td><td>预留 SM / 不预留</td><td>计算与 All-to-All 的资源争用</td></tr></tbody></table>\n<p>具体例子：某层路由后 8 个专家中 3 个只分到远少于对齐粒度的 token，若对齐粒度取 128，这 3 组各自被补到 128 行，实际有效行数可能只有个位数，padding 率在这一层可超过 50%。此时若按名义 token 总数估算 GEMM 算力，会高估有效 MMA 吞吐，容量规划随之失准。正确做法是在路由侧按对齐粒度合并或拆分专家批次，把碎组拼到同一累加器流水上，而不是让每个碎组独立走一遍完整 kernel 骨架。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-3\">三 · 分类维度二：累加器复用策略</h3>\n<p>累加器复用指 TMEM 中的累加器在连续 MMA 之间保持，避免每组 GEMM 结束后写回全局内存再读入。它把“组”从独立的计算单元降级为同一流水上的一个片段：多个小组共享一块累加器，组间只切换描述符与权重指针，不重置累加器状态。与之相对的是逐组重置策略，每组结束即写回，逻辑清晰但 TMEM 读写与同步开销随分组数线性上升。</p>\n<p>这个维度之所以是分类维度而非实现细节，是因为它改变了 kernel 的拓扑：复用策略下，组数增大只增加描述符切换次数；重置策略下，组数增大同时增加 TMEM 写回次数、全局内存流量和 barrier 数量。当分组数很大时，后者的瓶颈会从 MMA 转移到 TMEM 与内存带宽上，此时再调对齐粒度也无济于事。</p>\n<div class=\"formula\">$$C_{\\text{TMEM}} \\;\\propto\\; N_{\\text{reset}} \\cdot \\big(S_{\\text{write}} + S_{\\text{read}}\\big)$$</div>\n<p>其中 $N_{\\text{reset}}$ 为累加器重置次数，$S$ 为单次写回/读入的同步代价。代价的量级不在单次，而在它与组数的乘积：分组数翻倍，重置策略的 TMEM 开销近似翻倍，而复用策略只增加切换开销。工程判断因此很直接——只要 TMEM 容量允许同时驻留的累加器数量，就应优先跨组合并；容量不足时按波次分执行，而不是退回逐组重置。</p>\n<p>具体例子：一个专家并行度较高的层，若每个小组独立重置累加器，尾部的若干碎组会各自触发一次写回与一次 barrier，这些碎组的真实计算量极小，开销却与正常组同量级，端到端表现为“组数调大反而变慢”。把碎组并入同一累加器流水后，同样的组数下 TMEM 写回次数显著下降，代价是组间描述符切换更频繁，需要 warp specialization 的角色划分来吸收这部分切换。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-4\">四 · 分类维度三：warp specialization 角色划分与同步点</h3>\n<p>分组 GEMM kernel 把 warp 分为加载、MMA 发射、epilogue 等角色，tcgen05 MMA 由专用 warp 发射并等待 TMEM 就绪。这个划分本身是一个分类维度：角色越细，单角色内的流水越深，但角色间的同步点越多；角色越粗，同步点少，但加载与 MMA 发射互相阻塞的概率上升。分组数增大时，同步点数量随组数增长，这是尾块效率下降的直接来源之一。</p>\n<p>同步点的代价不在单次 barrier 的延迟，而在尾块阶段并行度不足时无法被其他组掩盖。正常组可以靠组间重叠把 barrier 延迟藏起来，最后几个小组没有后续组可重叠，barrier 与 TMEM 就绪等待直接暴露在关键路径上。因此尾块处理方式（padding 还是拆分）与角色划分必须联合设计：拆分尾块可以把一个小组拆成多个可并行的片段，padding 则把小组合并进相邻组以减少同步点。</p>\n<p>具体例子：当每 SM 处理组数较多时，加载 warp 与 MMA 发射 warp 之间的同步点密集，尾块阶段加载 warp 已无新组可载，MMA 发射 warp 却在等待 TMEM 就绪，两者形成空转。此时把尾块拆分为更细的 M 片段、让多个 SM 分担同一组的剩余行，比继续 padding 更能填满 SM 占用；反之若尾块本身已接近对齐粒度，padding 进相邻组更划算。这个选择没有统一拐点，需按组大小分布实测。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-5\">五 · 分类维度四：尾块处理与通信重叠的 SM 预留</h3>\n<p>尾块处理方式分为 padding 与拆分两类。padding 把不足对齐粒度的组补到粒度，实现简单但浪费算力；拆分把尾组沿 M 切成多个片段分给不同 SM，填满占用但增加描述符与同步开销。两者的分界由组大小分布决定：短组多时 padding 率上升，拆分收益变大；组普遍接近粒度时，拆分的额外开销超过收益。</p>\n<p>最后一个维度是与 All-to-All 重叠时的 SM 资源分配。分组 GEMM 与通信重叠时，必须预留一部分 SM 给通信侧，否则计算侧会把 SM 占满导致通信无法推进，形成通信计算死锁式的资源争用。预留比例直接改变分组 GEMM 可用的 SM 数，进而改变每 SM 处理组数与尾块效率——这是一个跨条目的耦合维度，本条目只负责把它列为分类维度，具体重叠策略由并行与通信部分展开。</p>\n<p>具体例子：在分离式预填/解码场景中，解码侧的分组 GEMM 组数多、每组 M 小，若不为通信预留 SM，计算侧会把所有 SM 占满，All-to-All 的接收缓冲无法及时排空，端到端延迟被通信拖长。预留 SM 后，每 SM 处理组数上升，尾块更容易填满，但单 SM 的 MMA 发射密度下降，需要靠累加器复用把切换开销压回去。三者——对齐粒度、累加器复用、SM 预留——构成联合调参面，任何单维度最优都不等于端到端最优。</p>\n<p>工程上判断一个分组 GEMM 实现是否踩坑，看两条即可：是否按平均 token 数设对齐粒度（短专家 padding 会吞掉大量 MMA 算力），是否每组结束即写回累加器（TMEM 读写成为瓶颈）。这两条对应本条目最常见的失败模式，也是分类维度里最容易被忽略的两项。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-6\">六 · 边界条件：分组 GEMM 在什么情况下反而变慢</h3>\n<p>分组 GEMM 的收益来自把变长 token 段拼成多个 M 维不等的 GEMM、每组对应一个专家权重，从而在一次 kernel 内覆盖全部专家。但它的适用边界由三个量共同划定：每专家实际 token 数相对对齐粒度的比值、同时驻留 TMEM 的累加器数量、以及尾块能否填满 SM。设第 e 个专家实际 token 数为 m<sub>e</sub>，对齐粒度 a（常见 64 或 128），则该组的有效 MMA 利用率为</p>\n<div class=\"formula\">$$\\eta_e=\\frac{m_e}{\\lceil m_e/a\\rceil\\cdot a},\\qquad \\eta_{\\text{total}}=\\frac{\\sum_e m_e}{\\sum_e \\lceil m_e/a\\rceil\\cdot a}$$</div>\n<p>当短专家（m<sub>e</sub> 远小于 a）占比高时，η<sub>total</sub> 被零填充稀释，padding 率可超过 50%。此时按名义 token 数估算算力会严重高估有效 MMA 吞吐——这是最常见的失效条件：容量因子收紧、路由把 token 集中到少数专家，长尾专家每组的 M 维只剩个位数，却仍要占满一个对齐块。工程上的判别标准不是平均 token 数，而是分布的低分位：若低分位专家数超过分组数的一定比例，就应在路由侧按对齐粒度合并或拆分专家批次，而不是继续加大分组数。</p>\n<p>第二个边界是累加器复用。tcgen05 MMA 的累加器驻留 TMEM，连续 MMA 之间保持可避免每组结束写回再读入；一旦逐组重置，TMEM 读写与同步开销随分组数上升。TMEM 容量限制同时驻留的累加器数量，超出即需分波执行，分波带来的 barrier 与角色切换会吃掉合并带来的收益。因此分组数增大并不单调变快：组数多则每组 MMA 发射与 barrier 开销摊薄变差，尾块受对齐粒度与 SM 占用限制无法填满，kernel 启动开销可能超过计算本身。</p>\n<p>第三个边界是与通信重叠时的 SM 资源分配。分组依据（按专家还是按容量上限）、尾块处理方式（padding 还是拆分）、warp specialization 的角色划分，都会改变留给 All-to-All 的 SM 预留；把分组数调大追求负载均衡，往往同时压缩了重叠窗口。判断是否该用分组 GEMM，应看每 SM 处理组数、对齐粒度与组大小分布三者的联合取值，而非单看专家数。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>短专家占比高，η 低</td><td>MMA 算力被零填充稀释</td><td>路由侧按粒度合并/拆分</td></tr><tr><td>逐组重置累加器</td><td>TMEM 读写与同步随组数上升</td><td>跨组合并到同一累加器流水</td></tr><tr><td>分组数过大</td><td>尾块填不满 SM，启动与 barrier 超算</td><td>限制每 SM 组数，保留重叠 SM</td></tr></tbody></table>\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-7\">七 · 速查表的字段口径：先定义“量的是什么”</h3>\n<p>分组 GEMM 的调参争论，十次有八次源于字段口径不一致：有人报的是名义 token 数，有人报的是对齐后 M；有人算的是单组 MMA 时间，有人算的是整 kernel 的墙钟。速查表要能“照着用”，第一件事是把每个字段的测量口径钉死，否则阈值无法复用。</p>\n<p>本表统一采用如下口径。分组数 E 指一次 kernel 启动内实际参与 MMA 的专家组数，不含被路由侧合并掉的空组。每专家 M 分布记录的是<b>对齐前</b>的真实 token 数直方图，而非均值——均值对短专家毫无解释力。对齐粒度 A 是 M 维向上取整的步长，取值 64 或 128，对应 tcgen05 MMA 的指令粒度。padding 率定义为对齐后总量与真实总量之比减一：</p>\n<div class=\"formula\">$$\\rho_{\\text{pad}}=\\frac{\\sum_{e=1}^{E}\\lceil M_e/A\\rceil A}{\\sum_{e=1}^{E}M_e}-1$$</div>\n<p>TMEM 累加器占用按“同时驻留的累加器块数”计，而不是按总分配字节计——因为 tcgen05 的约束是同时驻留数量，超出即需分波。warp 角色与同步点数量记录的是每个角色 warp 在单次 kernel 内经过的 barrier 次数，这是尾块效率的直接解释变量。尾块效率定义为最后若干小组实际占用 SM 的 MMA 吞吐与满占用之比。kernel 启动开销含 grid launch、参数加载与首个 barrier 之前的固定延迟。与通信重叠的 SM 预留指为 All-to-All 或 P2P 搬运显式让出的 SM 数或比例。</p>\n<p>代价敏感度上，前四个字段决定<b>算力有效利用率</b>（padding 直接稀释 MMA 吞吐），中间三个决定<b>延迟尾部</b>（尾块与启动开销不进稳态吞吐但进 P99），最后一个决定<b>带宽与算力的争抢</b>。工程上把字段分成这两簇，调参时就不会拿吞吐指标去解释尾延迟。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-8\">八 · 速查表主体：字段、典型取值与判据</h3>\n<p>下表按“字段—口径—典型取值/阈值—越界后的代价”四列组织，可直接作为调参检查单。典型取值只写给定事实中出现的数字（64、128、50%），其余以定性判据表述，不虚构曲线。</p>\n<table class=\"mini\">\n<thead><tr><th>字段</th><th>口径</th><th>典型取值 / 判据</th><th>越界代价</th></tr></thead>\n<tbody>\n<tr><td>分组数 E</td><td>实际发射 MMA 的组数</td><td>与每 SM 处理组数联合定；E 增大需同步检查尾块与启动开销</td><td>barrier 与 MMA 发射开销摊薄变差，启动开销可能超过计算</td></tr>\n<tr><td>每专家 M 分布</td><td>对齐前真实 token 数直方图</td><td>关注短专家占比，而非均值</td><td>按均值设粒度 → 短专家 padding 吞算力</td></tr>\n<tr><td>对齐粒度 A</td><td>M 向上取整步长</td><td>64 或 128</td><td>A 过大 → padding 率上升；A 过小 → MMA 指令效率与发射开销变差</td></tr>\n<tr><td>padding 率 ρ<sub>pad</sub></td><td>对齐后/真实 − 1</td><td>短专家占比高时可超过 50%</td><td>有效 MMA 吞吐被零填充稀释，名义算力估算失真</td></tr>\n<tr><td>TMEM 累加器占用</td><td>同时驻留累加器块数</td><td>受 TMEM 容量限制，超出需分波</td><td>分波带来额外同步；逐组重置则读写随 E 线性上升</td></tr>\n<tr><td>warp 角色与同步点</td><td>加载/MMA 发射/epilogue 各自 barrier 次数</td><td>同步点随 E 增多</td><td>角色间等待拉长，MMA 发射 warp 空转</td></tr>\n<tr><td>尾块效率</td><td>末几组 SM 占用率</td><td>受对齐粒度与 SM 占用限制，E 增大时下降</td><td>尾块填不满 SM，端到端变慢</td></tr>\n<tr><td>kernel 启动开销</td><td>launch + 首 barrier 前固定延迟</td><td>与总计算时间比较</td><td>E 过大时占比上升，收益被抵消</td></tr>\n<tr><td>通信重叠 SM 预留</td><td>让出的 SM 数/比例</td><td>与 All-to-All 重叠时显式预留</td><td>预留过多 → GEMM 并行度不足；过少 → 搬运阻塞 MMA</td></tr>\n</tbody>\n</table>\n<p>读表顺序建议固定为：先看 M 分布与 ρ<sub>pad</sub>（决定算力是否被浪费），再看 TMEM 占用与同步点（决定 kernel 内部是否卡住），最后看尾块与启动开销（决定 E 是否调过头）。这个顺序对应失败模式的发生频率：padding 误判最常见，累加器写回次之，E 调大导致尾块塌陷排第三。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-9\">九 · 阈值怎么用：三个联合判据而非单点门限</h3>\n<p>表中没有任何一个字段可以单独设阈值。工程上真正可执行的是三个联合判据。</p>\n<p><b>判据一：对齐粒度对短专家的惩罚。</b>设某专家真实 token 数为 M<sub>e</sub>，其有效 MMA 利用率为 M<sub>e</sub>/(⌈M<sub>e</sub>/A⌉A)。当 M<sub>e</sub> 远小于 A 时该比值趋近于零。因此判据不是“平均 M 是否大于 A”，而是“短专家（M<sub>e</sub> &lt; A）承载的 token 占比是否显著”。若该占比高到使整体 ρ<sub>pad</sub> 超过 50%，说明对齐粒度或分组方式必须改——要么在路由侧按对齐粒度合并专家批次，要么拆分大专家以腾出对齐空间。注意 ρ<sub>pad</sub> 超过 50% 是给定事实中的量级锚点，不是普适红线；它标记的是“名义算力估算已不可用”的状态。</p>\n<p><b>判据二：累加器复用与 TMEM 容量的匹配。</b>若同时驻留的累加器块数超过 TMEM 容量，kernel 被迫分波，波间同步开销随 E 上升。此时若仍采用“每组结束即写回”的策略，TMEM 读写与同步开销随分组数线性上升，与分波开销叠加。可执行的检查是：把“跨组合并到同一累加器流水”的组数与“逐组重置”的组数分别计数，若后者占比高且 E 在增长，则 kernel 已进入读写瓶颈区。</p>\n<p><b>判据三：E 的边际收益。</b>E 增大换来负载均衡，但代价是每组的 MMA 发射与 barrier 开销摊薄变差，且尾块受对齐粒度与 SM 占用限制无法填满。可操作的做法是把“每 SM 处理组数”“对齐粒度”“组大小分布”三者作为联合调参维度，而不是单独调 E。判断 E 是否过头的信号是：kernel 启动与 barrier 开销在总时间中的占比随 E 上升而上升，同时尾块效率下降——两者同时出现即说明计算收益已被调度开销吃掉。</p>\n<p>延迟侧的口径要单独强调：padding 浪费与尾块效率影响的是稳态吞吐，而 kernel 启动开销与尾块等待影响的是 P99。用吞吐指标去调 E，往往会放过尾块塌陷；用 P99 去调 A，又容易把 padding 率推高。两个口径必须分开记录。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-10\">十 · 一个照表执行的例子：短专家占比高的分组</h3>\n<p>设某次 decode 步中，路由把 token 分到 E 个专家，M 分布呈长尾：多数专家只有个位数 token，少数专家有数百 token。按表逐项走。</p>\n<p>第一步查 M 分布：短专家（M<sub>e</sub> &lt; 64）承载的 token 占比高。第二步算 ρ<sub>pad</sub>：若取 A=128，个位数 token 的专家被补齐到 128，ρ<sub>pad</sub> 轻易超过 50%，名义算力估算失效。第三步改口径：把 A 降到 64，padding 率下降但 MMA 指令粒度变细、发射开销上升；或在路由侧把多个短专家按对齐粒度合并为一批，使每批 M 接近 A 的整数倍。第四步查 TMEM：合并后组数减少，同时驻留累加器块数下降，分波概率降低，跨组合并的累加器复用得以生效。第五步查尾块：合并批次后尾块组数减少，SM 占用更满，尾块效率回升。第六步查启动开销：组数减少使 barrier 与发射开销摊薄改善。</p>\n<p>这个例子的代价账是这样记的：padding 率下降直接换算为有效 MMA 吞吐上升；累加器复用减少 TMEM 读写，换算为 kernel 内部同步等待下降；组数减少改善尾块与启动开销，换算为 P99 尾部缩短。三者方向一致时才值得改路由侧合并逻辑——若合并导致单组 M 过大、TMEM 累加器占用超容，则分波开销会抵消收益，此时应改为拆分大专家而非继续合并。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-11\">十一 · 表外但必须同表检查的两个耦合项</h3>\n<p>速查表若只列 GEMM 内部字段，会漏掉两个直接改变上述判据的耦合项。</p>\n<p>其一是与通信重叠时的 SM 预留。分组 GEMM 常与 All-to-All 或 P2P 搬运重叠执行，预留 SM 给通信会直接压低 GEMM 可用并行度，使尾块更容易填不满。表中“通信重叠 SM 预留”一栏必须与“尾块效率”联动读：预留比例上升时，尾块效率的判据要相应放宽，否则会把通信争抢误判为分组数过大。</p>\n<p>其二是路由侧的容量因子。容量因子收紧会同时放大短专家占比与 padding 率，因为被丢弃或截断的 token 使部分专家 M 进一步变小。表中 ρ<sub>pad</sub> 的读数必须标注当时的容量因子口径，否则两次测量不可比。这一点与路由术语、容量因子与丢弃代价两处条目相接，此处只作指路：容量因子是 padding 率的上游变量，调 GEMM 前先确认容量因子是否已变。</p>\n<p>把这两个耦合项写进同一张表的意义在于：分组 GEMM 的调参从来不是 kernel 内部的事，路由分布与通信预留会从外部改写表内每一个字段的读数。照表执行时，先在表头记下容量因子与通信预留比例，再读其余字段，才能保证阈值判据不被上游变量污染。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-12\">十二 · 速查表：分组 GEMM 落到 tcgen05 时的边界与代价口径</h3>\n<p>这张表不是参数推荐，而是把“能不能这么配”的判断依据固定下来：每一行给出字段、可照抄的阈值口径、以及越界后首先崩掉的系统代价。读法是先看分组数 E 与每专家 M 分布两行，再决定对齐粒度与累加器策略，最后用尾块效率与 SM 预留两行做否决。表中阈值只使用确定量：M 对齐粒度 64 或 128，padding 率可超过 50%；其余为定性口径，拐点不写死。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>阈值/口径</th><th>越界后的首个代价</th></tr></thead><tbody><tr><td>分组数 E</td><td>与每 SM 处理组数联合定，不单独调大</td><td>barrier 与 MMA 发射开销摊薄变差，启动开销吃掉收益</td></tr><tr><td>每专家 M 分布</td><td>按分布而非均值设粒度；短专家占比高即预警</td><td>padding 率超 50%，有效 MMA 吞吐被零填充稀释</td></tr><tr><td>对齐粒度</td><td>64 或 128，与 MMA 指令粒度一致</td><td>粒度越粗，短专家零填充越多，总算力虚高</td></tr><tr><td>TMEM 累加器占用</td><td>同时驻留数受 TMEM 容量限制，超出即分波</td><td>逐组重置导致 TMEM 读写与同步随 E 上升</td></tr><tr><td>warp 角色/同步点</td><td>加载、MMA 发射、epilogue 分工，同步点随 E 增</td><td>角色间等待拉长，MMA 发射 warp 空转</td></tr><tr><td>尾块效率</td><td>受对齐粒度与 SM 占用双重限制</td><td>最后几个小组填不满 SM，并行度塌陷</td></tr><tr><td>通信重叠 SM 预留</td><td>与 All-to-All 重叠时先划走 SM，再算 GEMM 占用</td><td>预留不足则重叠退化为串行，端到端变慢</td></tr></tbody></table>\n<p>把 padding 率写成可核算的口径，才能在路由侧做决策。设第 e 个专家实际 token 数为 $t_e$、对齐粒度为 $a$，则该组发出的 MMA 工作量按 $\\lceil t_e/a\\rceil \\cdot a$ 计，整体有效率为</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_e t_e}{\\sum_e \\lceil t_e/a\\rceil \\cdot a}$$</div>\n<p>当大量 $t_e \\ll a$ 时 $\\eta$ 迅速下滑，padding 率 $1-\\eta$ 可超过 50%——此时按名义 token 数估算算力必然高估吞吐。工程动作是在路由侧按对齐粒度合并或拆分专家批次，而不是把 $a$ 调细了事：$a$ 受 tcgen05 MMA 指令粒度约束，64 与 128 是硬边界。</p>\n<p>三个失效条件按发生顺序排列。其一，按平均 token 数设对齐粒度，短专家 padding 吞掉 MMA 算力，这是最常见的误判入口。其二，每组 GEMM 结束即把 TMEM 累加器写回全局内存，累加器复用失效，TMEM 读写与同步开销随分组数上升，此时即便 padding 率可控，kernel 仍被访存拖住；正确做法是把多个小组合并到同一累加器流水，减少切换。其三，为追求负载均衡把 E 调大，尾块受对齐粒度与 SM 占用限制无法填满，kernel 启动与 barrier 开销超过计算收益，端到端反而变慢。判断顺序应是：先算 $\\eta$ 与 TMEM 驻留是否需分波，再看尾块能否填满 SM，最后才动 E；与通信重叠的场景还要先扣掉预留 SM，否则重叠只是纸面收益。</p>\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-13\">十三 · 对齐粒度的实测标定：从名义 M 到有效 M</h3>\n<p>工程上第一个必须钉死的数字是 M 对齐粒度。Blackwell 上每组专家的 token 段被映射为若干 tcgen05 MMA 指令，M 维必须补齐到指令粒度（64 或 128），因此“名义 M”与“有效 M”之间永远存在一道缝。把这道缝量化出来，是调参的起点而不是终点。设第 e 个专家实际 token 数为 $m_e$，对齐粒度为 $a$，则该组的有效计算量为</p>\n<div class=\"formula\">$$M^{\\text{eff}}_e = a\\left\\lceil \\frac{m_e}{a} \\right\\rceil,\\qquad \\rho_{\\text{pad}} = \\frac{\\sum_e (M^{\\text{eff}}_e - m_e)}{\\sum_e M^{\\text{eff}}_e}$$</div>\n<p>$\\rho_{\\text{pad}}$ 就是 padding 率，它不是一个可以拍脑袋设定的常数，而是路由输出分布的因变量。测量方法很直接：在真实流量上抓取每个 expert 的 token 计数直方图，按候选粒度 $a\\in\\{64,128\\}$ 分别算出 $\\rho_{\\text{pad}}$ 与总算力膨胀倍数 $\\sum_e M^{\\text{eff}}_e / \\sum_e m_e$。注意这里的分母必须是“有效 token 数”而非批次名义 token 数——容量因子收紧时被丢弃的 token 不计入 GEMM，若按名义数估算会把 padding 率系统性低估。短专家占比高时 $\\rho_{\\text{pad}}$ 可超过 50%，这意味着超过一半的 MMA 算力打在零上；此时把粒度从 128 降到 64 往往能把 padding 率砍掉近一半，代价是 MMA 指令数翻倍、发射开销上升，两者的净效应只能靠实测决定，不存在通用最优解。</p>\n<p>系统代价落在吞吐而非延迟上：padding 直接稀释有效 MMA 吞吐，而 tcgen05 的 MMA 单元在零填充上照样消耗同样的周期与 TMEM 带宽。一个具体例子：某层路由后 64 个专家、平均每专家 40 个 token，若取 $a=128$，每组有效 M 都是 128，总算力膨胀约 3.2 倍；若取 $a=64$，每组有效 M 为 64，膨胀降到约 1.6 倍，但 MMA 指令数从 64 条变成 128 条，发射与 barrier 开销翻倍。判断依据是这两项开销在 profiler 上的占比谁更大，而不是凭直觉选小粒度。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-14\">十四 · 累加器驻留的容量阈值：TMEM 决定分波数</h3>\n<p>第二个阈值来自 TMEM。累加器驻留 TMEM 是 tcgen05 路径的核心收益，但 TMEM 容量有限，同时驻留的累加器数量有上限，超出就必须分波执行。设单个累加器占用 $c$ 个 TMEM 列（由 M 粒度与 N 宽度决定），TMEM 可用列数为 $C$，则单波可并行的累加器数上界为</p>\n<div class=\"formula\">$$K_{\\max} = \\left\\lfloor \\frac{C}{c} \\right\\rfloor,\\qquad W = \\left\\lceil \\frac{E_{\\text{active}}}{K_{\\max}} \\right\\rceil$$</div>\n<p>$W$ 是波数。这个公式的工程含义是：分组数 $E$ 一旦超过 $K_{\\max}$，kernel 就从“一次铺开”退化为“多波串行”，每波之间要等前一波的累加器写回或释放。测量 $c$ 与 $C$ 的办法不是查表，而是在 kernel 里做二分探测：固定 N 宽度，逐步增加同时活跃的组数，观察是否出现波次切换导致的吞吐台阶式下跌，那个拐点就是 $K_{\\max}$。这条曲线必须在自己模型的 N 宽度上测，因为 $c$ 随 N 变化。</p>\n<p>与累加器复用策略耦合的是写回频率。若每组 GEMM 结束即把累加器写回全局内存，TMEM 读写与同步开销随分组数线性上升，复用失效；若把多个小组合并到同一累加器流水，写回次数从 $E$ 降到 $W$，但要求这些组的 N 宽度与数据类型一致，且合并后的 M 不能突破单条 MMA 指令的合法范围。系统代价体现在显存带宽上：写回是 TMEM→寄存→全局的链路，分组数大时这条链路的流量可与权重加载相当。一个可操作的判据是统计每波内实际合并的组数 $g$，若 $g$ 接近 1，说明合并策略没有生效，应回头检查对齐粒度是否把小组切得太碎。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-15\">十五 · 尾块效率：拐点只能测不能猜</h3>\n<p>分组数增大时尾块效率下降，这一点在事实里明确，但拐点未给出——所以本节的立场是：拐点必须由测量定义，且测量协议要写死。尾块的成因是并行度不足：最后几个小组受对齐粒度与 SM 占用限制无法填满 SM，而 warp specialization 把角色分为加载、MMA 发射、epilogue，组数增多使角色间同步点增多，尾块阶段这些角色大量空转。定义尾块效率为</p>\n<div class=\"formula\">$$\\eta_{\\text{tail}} = \\frac{\\text{尾块阶段有效 MMA 周期}}{\\text{尾块阶段墙钟周期} \\times \\text{SM 数}}$$</div>\n<p>测量方法是把 kernel 按组切分打时间戳，取最后 $W$ 个组的区间计算上式；同时记录该区间的活跃 SM 数与 barrier 等待计数。工程上关心的不是 $\\eta_{\\text{tail}}$ 的绝对值，而是它随 $E$ 变化的斜率：当 $E$ 从某个值继续增大、$\\eta_{\\text{tail}}$ 开始陡降且 kernel 启动与 barrier 开销的占比超过计算本身时，那个 $E$ 就是该模型该层的实用上限。事实里说“以每 SM 处理组数、对齐粒度与组大小分布三者联合调参”，落地就是把这三个量做成扫描网格：每 SM 组数取 1、2、4，粒度取 64、128，组大小分布用真实路由直方图而非均匀分布，逐点记录端到端时延。</p>\n<p>具体例子：某 MoE 层 $E=128$、每 SM 分到 1 组时尾块只有寥寥几个 SM 在工作，$\\eta_{\\text{tail}}$ 明显偏低；把每 SM 组数提到 2 并允许跨组合并累加器后，尾块被摊薄到更多 SM 上，但同步点数量上升。这两股力量的净效应只能由扫描网格给出，任何“分组数别超过某个值”的口头经验都不可靠，因为组大小分布一变结论就翻。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-16\">十六 · 启动与 barrier 开销的摊销判据</h3>\n<p>第三个阈值是摊销比。组数多则每组的 MMA 发射与 barrier 开销摊薄变差，判据可以写成每组的固定开销与计算量之比：</p>\n<div class=\"formula\">$$\\kappa_e = \\frac{t_{\\text{launch}} + t_{\\text{barrier}}}{t_{\\text{MMA},e}},\\qquad \\kappa = \\max_e \\kappa_e$$</div>\n<p>$\\kappa$ 由最大而非平均决定，因为尾块里最慢的那组决定墙钟。测量 $t_{\\text{launch}}$ 与 $t_{\\text{barrier}}$ 的办法是在 kernel 里插入空组（M 极小、几乎不计算）做对照，用总时延差除以空组数得到单组固定开销；再用真实组减去该固定开销得到 $t_{\\text{MMA},e}$。这条测量必须在与 All-to-All 重叠的真实场景下做，因为重叠时 SM 资源被预留，$t_{\\text{MMA},e}$ 会被拉长而固定开销不变，$\\kappa$ 因此上升。事实里速查表专门列了“与通信重叠的 SM 预留”这一列，原因就在这里：重叠不是免费的，它改变的是分母。</p>\n<p>系统代价是端到端时延而非单 kernel 吞吐。一个具体判断：若 $\\kappa$ 在重叠场景下超过某个可观比例，说明该层的分组数已经让固定开销吃掉计算收益，此时正确动作是减少分组数（按对齐粒度合并专家批次）而不是继续调大以追求负载均衡——后者正是事实里列出的失败模式之一。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-17\">十七 · 测量协议：把三个阈值串成一条流水线</h3>\n<p>上述三类阈值不能各自孤立地测，否则会得到互相矛盾的结论。推荐的协议是单层离线扫描加全模型在线校验：离线阶段固定一层，扫 $a\\in\\{64,128\\}$、每 SM 组数、累加器合并开关三个维度，每点记录 $\\rho_{\\text{pad}}$、$W$、$\\eta_{\\text{tail}}$、$\\kappa$ 与端到端时延；在线阶段用真实流量重放，只校验被选中的那个配置点在流量漂移下是否仍然成立。漂移的敏感量是组大小分布：路由倾斜会让短专家更多，$\\rho_{\\text{pad}}$ 上升，原本选中的粒度可能失效，因此在线校验要监控 $\\rho_{\\text{pad}}$ 的滑动值并在越过实测拐点时触发重扫。</p>\n<p>这里要强调一个反直觉的工程判断：padding 率超过 50% 并不自动意味着该换小粒度。若该层的 N 宽度大、MMA 指令本身很长，翻倍指令数带来的发射开销可能超过 padding 节省，实测端到端反而变慢。所以阈值的作用不是给出动作，而是给出“必须去测”的触发条件——把 $\\rho_{\\text{pad}}&gt;50\\%$、$W&gt;1$、$\\eta_{\\text{tail}}$ 陡降、$\\kappa$ 超限这四个信号做成监控项，任何一个亮起就重跑扫描网格，这才是把经验数字变成工程纪律的方式。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-18\">十八 · 阈值不是拍脑袋：对齐粒度、padding 率与尾块拐点的实测口径</h3>\n<p>把「M 对齐 64 或 128」当成配置项抄进 kernel 是这一步最常见的误用。对齐粒度不是精度参数，而是<b>算力折算系数</b>：设第 e 个专家的实际 token 数为 $t_e$，对齐粒度为 $a$，则该组有效算力占比为</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_{e=1}^{E} t_e}{\\sum_{e=1}^{E} a\\cdot\\lceil t_e/a\\rceil}=\\frac{1}{1+\\rho},\\qquad \\rho=\\frac{\\sum_e (a\\lceil t_e/a\\rceil-t_e)}{\\sum_e t_e}$$</div>\n<p>$\\rho$ 就是 padding 率。它只由 $t_e$ 相对 $a$ 的分布决定，与总 token 数无关——这意味着扩容 batch 并不能稀释它。工程上的判断规则是：当 $t_e$ 的中位数落在 $a$ 以下时，$\\rho$ 由短专家主导，此时把 $a$ 从 128 降到 64 换来的算力回收，必须与 MMA 指令数翻倍带来的发射开销对账；而当短专家占比高到 $\\rho$ 越过 50% 量级，正确动作不是继续调 $a$，而是在路由侧按对齐粒度合并或拆分专家批次，把多个短专家的 token 段拼进同一组 M 维。测量方法很直接：在真实路由分布下（不是均匀分布）dump 每个专家的 $t_e$，离线算 $\\rho$，再与 kernel 实测的有效 MMA 吞吐对照——两者若出现系统性偏差，说明瓶颈已不在 padding 而在别处。</p>\n<p>第二个阈值是 TMEM 累加器驻留数。TMEM 容量决定了同一时刻能有多少个累加器存活，超出即分波执行，而分波意味着一次额外的 epilogue 写回与 barrier。判断是否该做跨组合并的量化条件是：设单次累加器切换（写回 + 重新就绪 + 同步）代价为 $c_s$，单组计算时间为 $c_e$，则合并 $k$ 个小组的收益条件近似为 $k\\cdot c_e &gt; c_s$。$c_s$ 随分组数线性上升，因为每组结束即写回会让同步点数量与 $E$ 同阶；这正是「累加器复用失效」的代价形态——它不是慢一点，而是把 TMEM 读写变成随 $E$ 增长的项。实测 $c_s$ 的办法是构造 $E$ 递增、总 token 数固定的合成路由，观察 kernel 时间对 $E$ 的斜率：斜率显著为正即说明累加器切换已成为主项，此时应把多个小组合并到同一累加器流水，而不是逐组重置。</p>\n<p>第三个是尾块拐点，也是最难给数字的一个。尾块效率受对齐粒度与 SM 占用双重限制：最后几个小组的 M 维不足一个对齐块，无法填满 SM，而 warp specialization 的角色（加载、MMA 发射、epilogue）之间的同步点在分组数增大时增多，barrier 开销摊薄变差。拐点没有通用数值，只能按「每 SM 处理组数 × 对齐粒度 × 组大小分布」三者联合扫描：固定总 token 与 $E$，扫每 SM 组数，记录端到端时间；曲线的最低点即该分布下的可用工作点。判据是——当 kernel 启动与 barrier 开销的增量超过尾块负载均衡带来的收益时，调大 $E$ 就是负优化。与 All-to-All 重叠时还要把 SM 预留计入这张扫描表，否则测出的最优点在真实流水里不成立。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>测法</th><th>失效信号</th></tr></thead><tbody><tr><td>padding 率 $\\rho$</td><td>真实路由下 dump $t_e$，按 $a$ 离线折算</td><td>名义 token 估算算力，实测吞吐被零填充稀释</td></tr><tr><td>累加器切换代价 $c_s$</td><td>固定总算力、扫 $E$，看时间斜率</td><td>斜率随 $E$ 线性上升，TMEM 读写成瓶颈</td></tr><tr><td>尾块拐点</td><td>扫每 SM 组数，取端到端最低点</td><td>启动与 barrier 开销超过计算收益</td></tr></tbody></table>\n<p>这三项的共同点是：都不能从架构参数推出来，只能在目标路由分布上测。把 $a$、累加器复用策略、尾块处理方式写进速查表时，必须同时记录测量所依据的 $t_e$ 分布形态——换一个专家负载分布，同一组阈值就不再成立。</p>\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-19\">十九 · 踩坑清单：三类高频失效的机理拆解</h3>\n<p>分组 GEMM 在 Blackwell 上的失效很少来自单点 bug，多数来自三个结构性错配。第一类是 <strong>M 维对齐错配</strong>：按专家平均 token 数选对齐粒度，短专家被向上取整到 64 或 128 后，零填充直接进入 MMA 指令。tcgen05 MMA 的指令粒度决定每组至少吃掉一个对齐块，短专家 token 数远小于粒度时，有效 MMA 吞吐被 padding 稀释，padding 率在短专家占比高时可超过 50%。代价落在算力而非显存：SM 执行的是零乘加，功耗照付、周期照占，端到端吞吐按名义 token 数估算会系统性高估。</p>\n<p>第二类是 <strong>累加器复用失效</strong>：每组 GEMM 结束即把 TMEM 累加器写回全局内存，下一组重新读入。TMEM 读写与同步开销随分组数线性上升，分组数越大越像在测 TMEM 带宽而不是测 MMA。正确做法是让累加器在连续 MMA 间保持，把多个小组合并到同一累加器流水，减少切换次数；代价是 TMEM 容量限制同时驻留的累加器数量，超出必须分波执行，波与波之间的 barrier 又变成新的同步点。</p>\n<p>第三类是 <strong>尾块与启动开销反噬</strong>：为追求负载均衡把分组数调大，最后几个小组受对齐粒度与 SM 占用限制无法填满，kernel 启动与 barrier 开销超过计算收益。典型例子是专家并行度高的 MoE 解码步：单 token 批次下每专家 token 数极少，分组数等于专家数，尾块并行度不足，端到端反而慢于合并分组。这三类坑的共同特征是“名义指标好看、有效吞吐塌陷”，检查时必须用有效 MMA 周期而非名义 FLOPs 做分母。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-20\">二十 · 检查顺序：从路由分布到 kernel 计数的自底向上排查</h3>\n<p>排查顺序应固定为“分布 → 对齐 → 累加器 → 尾块 → 重叠”，每一步都有可观测的判据，避免在 kernel 内部盲目调参。第一步看每专家 M 分布：把路由输出的 token 数按专家排序，统计小于对齐粒度的专家占比。若该占比高，padding 率必然抬头，此时任何 MMA 侧优化都是徒劳，应先回到路由侧按对齐粒度合并或拆分专家批次。</p>\n<div class=\"formula\">$$\\text{padding 率} = \\frac{\\sum_{e}\\left(\\lceil M_e / A \\rceil \\cdot A - M_e\\right)}{\\sum_{e} M_e}$$</div>\n<p>其中 $A$ 为对齐粒度（64 或 128），$M_e$ 为专家 $e$ 的实际 token 数。该比值直接给出被零填充吞掉的 MMA 算力比例，是判断是否需要改路由的第一指标。</p>\n<p>第二步核对对齐粒度与累加器策略是否匹配：对齐粒度越小，短专家 padding 越少，但每组 MMA 指令数增加、发射开销上升；累加器若逐组重置，TMEM 读写次数等于分组数，需确认是否已改为跨组合并。第三步看尾块：统计最后若干组的 SM 占用率与 barrier 等待时间，若尾块效率下降明显而分组数仍在增加，说明已越过拐点。第四步才看与 All-to-All 重叠时的 SM 资源分配——通信与计算争抢 SM 会放大尾块效应，重叠策略必须在分组数与 SM 预留之间联合定参，而非先定分组数再补重叠。</p>\n<p>检查顺序的工程意义在于代价归因：padding 浪费的是算力周期，累加器重置浪费的是 TMEM 带宽与同步，尾块浪费的是 SM 占用与启动开销，三者优化手段互不替代。先定位再动手，避免把尾块问题误判为对齐问题而反复调粒度。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-21\">二十一 · 调参联合空间：分组数、对齐粒度与组大小分布</h3>\n<p>实践中以每 SM 处理组数、对齐粒度与组大小分布三者联合调参，任何单变量扫描都会给出误导性结论。分组数 $E$ 增大时，每组的 MMA 发射与 barrier 开销摊薄变差；对齐粒度 $A$ 增大时 padding 率上升但每组指令效率提高；组大小分布越倾斜，尾块越难填满。三者存在耦合：把 $A$ 从 64 提到 128 会同时改变 padding 率与每 SM 可容纳的组数，进而改变尾块形态。</p>\n<table class=\"mini\"><thead><tr><th>调参变量</th><th>增大时的收益</th><th>增大时的代价</th><th>观测判据</th></tr></thead><tbody><tr><td>分组数 E</td><td>负载更均衡，单组 M 更小</td><td>启动与 barrier 开销摊薄变差，尾块并行度不足</td><td>尾块 SM 占用率、barrier 等待</td></tr><tr><td>对齐粒度 A</td><td>每组 MMA 指令效率提高</td><td>短专家 padding 率上升</td><td>padding 率、有效 MMA 周期占比</td></tr><tr><td>组大小分布倾斜度</td><td>—</td><td>尾块无法填满，累加器切换增多</td><td>组大小方差、TMEM 驻留数</td></tr></tbody></table>\n<p>具体例子：某解码步路由后 64 个专家中过半 token 数低于 64，若按 128 对齐，padding 率远超 50%，此时把对齐降到 64 并合并相邻短专家到同一累加器流水，可在不增加分组数的前提下压低 padding；反之若 token 分布均匀且每专家 M 远大于 128，提高对齐粒度换取指令效率更划算。调参的终点不是某个固定值，而是让 padding 率、尾块效率与 TMEM 驻留数同时落在可接受区间。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-22\">二十二 · 回滚方案：分级降级与可逆开关</h3>\n<p>分组 GEMM 的调参必须配可逆开关，因为失败模式往往是端到端变慢而非报错，没有回滚点就只能整段回退。回滚分三级：一级回滚对齐粒度，从 128 退回 64，代价是每组指令数增加但 padding 率下降，适用于短专家占比突增的场景；二级回滚累加器策略，从跨组合并退回逐组重置，代价是 TMEM 读写上升，适用于 TMEM 容量不足导致分波频繁的场景；三级回滚分组数，把 $E$ 降回上一稳定值并接受负载不均，适用于尾块效率已越过拐点的情况。</p>\n<p>每级回滚都应有对应的可观测触发条件：padding 率超过阈值触发一级，TMEM 驻留数逼近容量上限触发二级，尾块 SM 占用率持续低于预期触发三级。回滚开关应做成 kernel 启动参数而非编译期常量，使同一模型在不同批次形态下可切换配置；代价是运行时分支增加少量调度开销，但远小于整段回退的代价。工程判断上，宁可保留一个略保守的默认配置加三个显式降级档，也不要把所有调参压在一个“最优值”上——分组 GEMM 的最优值随路由分布漂移，固定值必然在某个批次形态下失效。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-23\">二十三 · 上线前检查清单与判定落点</h3>\n<ul>\n<li>每专家 M 分布已统计，短专家（小于对齐粒度）占比与 padding 率已量化，padding 率超过 50% 时路由侧合并或拆分已生效。</li>\n<li>对齐粒度与路由分布匹配，未按平均 token 数设粒度；粒度变更已做端到端对比而非仅看单 kernel。</li>\n<li>累加器跨组合并已启用，TMEM 驻留累加器数量未超容量，分波次数与 barrier 开销已计入延迟预算。</li>\n<li>分组数增大时尾块效率已实测，kernel 启动与 barrier 开销未超过计算收益，拐点已记录。</li>\n<li>与 All-to-All 重叠的 SM 预留已与分组数联合定参，通信争抢未放大尾块。</li>\n<li>三级回滚开关可用，触发条件已接入监控，回滚后端到端指标可复现。</li>\n</ul>\n<p>清单的判定落点应放在有效 MMA 周期占比上：把 padding 浪费、TMEM 同步、尾块空转三类周期从总周期中扣除，剩余部分才是分组 GEMM 的真实吞吐。若该占比在分组数扫描中先升后降，下降段即为尾块与启动开销反噬的区间，回滚三级应在此处触发。工程上把这个占比作为上线门禁，比看名义 FLOPs 或单 kernel 延迟更能拦住“调大分组数求均衡”这类典型误判。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-24\">二十四 · 分组 GEMM 上机前的失效模式与回滚路径</h3>\n<p>按平均 token 数选对齐粒度是最常见的第一类失效。路由分布一旦长尾，短专家实际 token 数远小于对齐粒度，M 维向上取整后整块都是零填充；名义算力按总 token 数估，实际有效 MMA 吞吐被零填充稀释。设专家 $e$ 的实际 token 数为 $m_e$、对齐粒度为 $A$，则有效算力占比为</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_e m_e}{\\sum_e \\lceil m_e/A\\rceil\\cdot A}$$</div>\n<p>短专家占比高时 $\\eta$ 可跌破一半，padding 率超过 50%。检查顺序应固定为：先看每专家 M 分布直方图，再看 $\\eta$，最后才看端到端时延——因为 $\\eta$ 低时时延曲线会呈现“加卡不变快”的假象。工程动作是在路由侧按 $A$ 合并或拆分专家批次，把 token 数接近对齐粒度的专家并组，而不是简单调大 $A$。代价是合并引入跨专家权重的额外加载与 TMEM 累加器切换，需与 padding 节省的 MMA 周期做对比。</p>\n<p>第二类失效是累加器复用被打断：每组 GEMM 结束即把 TMEM 累加器写回全局内存，下一组重新读入。TMEM 读写与 barrier 同步开销随分组数 $E$ 线性上升，而 MMA 计算量并不随 $E$ 增长，于是 kernel 从算力受限滑向 TMEM 带宽与同步受限。判断依据是看每 SM 的 MMA 发射间隔是否被 epilogue 写回拉长；若分组数增大而 MMA 利用率下降，基本可确认复用失效。回滚方案是把多个小组绑定到同一累加器流水，只在流水末尾统一写回，代价是单条流水的尾延迟变长、TMEM 容量限制同时驻留的累加器数量，超出需分波执行，波次切换又带来新的同步点。</p>\n<p>第三类失效是分组数调大追求负载均衡，尾块却填不满 SM。尾块受对齐粒度与 SM 占用限制，最后几个小组并行度不足；同时每组的 MMA 发射与 barrier 开销摊薄变差，启动开销超过计算收益，端到端变慢。此时应联合调参每 SM 处理组数、对齐粒度与组大小分布三者，而不是单向增大 $E$。回滚路径按代价从低到高：先把尾块从 padding 改为拆分（拆成更小 M 的子 GEMM 以填满 SM），再回退累加器复用策略到逐组重置以换取调度简单，最后才回退对齐粒度。与 All-to-All 重叠时还要预留 SM 给通信，重叠收益被尾块拖累时应优先缩减重叠窗口而非加组。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>对齐粒度与 padding 率</td><td>$\\eta$ 偏低、加卡不变快</td><td>路由侧按 $A$ 合并专家批次</td></tr><tr><td>TMEM 累加器复用</td><td>MMA 发射间隔被 epilogue 拉长</td><td>跨组绑定累加器流水、末尾统一写回</td></tr><tr><td>尾块效率</td><td>组数增大而 MMA 利用率下降</td><td>尾块拆分、缩减通信重叠窗口</td></tr><tr><td>kernel 启动开销</td><td>barrier 开销占比上升</td><td>回退组数、合并小组合并发射</td></tr></tbody></table>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-25\">二十五 · 踩坑清单与回滚判据：从 padding 率反推对齐粒度</h3>\n<p>最常见的失效不是 kernel 写错，而是容量规划用错了分母。按名义 token 数估算 GEMM 算力，忽略短专家的 M 维 padding，实际有效 MMA 吞吐会被零填充稀释。设第 e 组实际 token 数为 $n_e$、对齐粒度为 $A$，则该组有效算力占比为 $\\eta_e = n_e / (\\lceil n_e/A \\rceil \\cdot A)$，整体有效吞吐 $\\eta = \\sum_e n_e / \\sum_e \\lceil n_e/A \\rceil A$。A 取 64 或 128 时，短专家占比高的负载下 padding 率可超过 50%——此时名义 FLOPs 翻倍而有效 MMA 只走一半，延迟预算直接失效。检查顺序应是：先量每专家 M 分布与 padding 率，再决定是否在路由侧按对齐粒度合并或拆分专家批次，最后才调分组数。</p>\n<p>第二个坑是累加器复用被无意打断。每组 GEMM 结束即把 TMEM 累加器写回全局内存，下一组重新读入，TMEM 读写与同步开销随分组数线性上升，本该由跨组合并摊薄的成本反而成了瓶颈。判据是看每 SM 上同时驻留的累加器数量是否触到 TMEM 容量上限：超出即需分波执行，波次切换的 barrier 会把 warp specialization 的加载、MMA 发射、epilogue 三角色同步点成倍放大。回滚方案在此处最直接——把逐组重置改回跨组合并流水，牺牲一点负载均衡换回累加器复用。</p>\n<p>第三个坑是分组数调大追求负载均衡，尾块却因对齐粒度与 SM 占用限制填不满，kernel 启动与 barrier 开销超过计算收益，端到端变慢。此时不要继续加组，而应把尾块处理方式从 padding 切到拆分，并核对与 All-to-All 重叠时的 SM 预留是否挤占了尾块可用的 SM。检查表按此顺序走：分组数 E → 每专家 M 分布 → 对齐粒度与 padding 率 → TMEM 累加器占用 → warp 角色与同步点数量 → 尾块效率 → kernel 启动开销 → 通信重叠 SM 预留。任一列越界即触发回滚到上一组参数，而不是就地微调。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>短专家 padding 稀释</td><td>padding 率 &gt; 50%</td><td>路由侧按 A 合并/拆分批次</td></tr><tr><td>累加器逐组重置</td><td>TMEM 读写随 E 线性涨</td><td>恢复跨组合并流水</td></tr><tr><td>尾块填不满</td><td>启动+barrier 开销 &gt; 计算</td><td>降 E、尾块改拆分</td></tr></tbody></table>\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-26\">二十六 · 上游依赖：路由分布是分组 GEMM 的输入契约</h3>\n<p>分组 GEMM 在 Blackwell 上的性能上限，并不由 kernel 自身决定，而是由上游 MoE 路由吐出的 token 段分布决定。tcgen05 MMA 要求 M 维对齐到 64 或 128 的指令粒度，因此路由侧必须把每个专家的 token 数按对齐粒度合并或拆分；这一步在路由术语速查与容量因子条目里是策略问题，在分组 GEMM 这里则变成硬性的输入契约。上游若只保证“负载均衡”，而不保证“段长对齐友好”，kernel 拿到的就是一组长短悬殊的变长段，短专家被 padding 撑到 64 或 128，零填充直接进入 MMA 流水。</p>\n<p>把这一点写成可传递的约束，路由侧需要输出的是每个专家的实际 token 数 $m_e$ 与对齐后的段长：</p>\n<div class=\"formula\">$$M_e = \\left\\lceil \\frac{m_e}{A} \\right\\rceil \\cdot A,\\qquad \\text{padding 率} = 1 - \\frac{\\sum_e m_e}{\\sum_e M_e}$$</div>\n<p>其中 $A$ 为对齐粒度（64 或 128）。这个式子的分母就是分组 GEMM 真正要算的 M 维总量，分子才是有效算力。工程上这意味着：容量因子收紧、专家数增大时，padding 率可以超过 50%，而按名义 token 数估算的 GEMM 算力会被系统性高估。上游依赖的具体机制是——路由的 top-k 选择与容量截断决定了 $m_e$ 的分布形状，而这个形状决定了分组 GEMM 的尾块结构与 TMEM 累加器的分波次数。代价落在算力利用率上：padding 率每上升一档，等效 MMA 吞吐按同一比例被稀释，而 kernel 启动与 barrier 开销不变，端到端延迟不降反升。</p>\n<p>具体例子：某层路由把 8192 个 token 分给 64 个专家，平均每专家 128 个 token，但分布长尾——若短专家实际只有 20 个 token，对齐到 64 后有效占比不足三分之一；这些组在 tcgen05 流水里照常发射 MMA，算的是零。上游若能在路由侧按对齐粒度做合并（把多个短专家拼进同一段）或拆分（把超长专家切成多段以填满 SM），kernel 侧的 padding 率才可控。这就是分组 GEMM 对上游的唯一硬要求：分布要可对齐，而不是仅仅均衡。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-27\">二十七 · 上游依赖：量化精度与权重布局决定 MMA 形态</h3>\n<p>NVFP4/FP8 权重激活条目定义了数值格式，分组 GEMM 则决定这些格式如何落到 tcgen05 指令上。Blackwell 的 tcgen05 MMA 对操作数精度、K 维步长与权重在 TMEM/共享内存中的布局有固定约束；分组 GEMM 的每一组对应一个专家的权重矩阵，权重若按专家连续排布，则每组的 MMA 描述符可以复用同一套模板，切换成本低；若权重按全局矩阵交错排布，则每组都要重算描述符与地址，warp specialization 中的加载角色负担陡增。</p>\n<p>这里的机制是累加器复用与精度格式的耦合：TMEM 中的累加器在连续 MMA 间保持，避免每组结束写回再读入；但不同精度格式下累加器的位宽与占用不同，TMEM 容量限制同时驻留的累加器数量，超出需分波执行。分组数增大时，若每组都重置累加器，TMEM 读写与同步开销随分组数线性上升——这正是失败模式里“每组 GEMM 完成即写回”的代价。量化校准数据管线条目关心的是数值误差，而分组 GEMM 关心的是：精度切换是否迫使累加器流水断流。</p>\n<p>代价体现在带宽与显存两侧：权重按专家连续排布时，加载角色可以整段预取，共享内存带宽被有效利用；交错排布则产生碎片化访问，加载 warp 的同步点增多，MMA 发射 warp 等待 TMEM 就绪的时间被拉长。具体例子：同一组 FP8 权重，按专家连续存放时一次加载覆盖整组 K 维，按全局交错存放时同一组需要多次非连续取数，加载与 MMA 的流水重叠度下降，尾块效率进一步恶化。工程判断是：分组 GEMM 的权重布局必须在上游量化导出阶段就按专家分块确定，而不是留给 kernel 运行时重排。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-28\">二十八 · 下游影响：与 All-to-All 重叠时的 SM 资源分配</h3>\n<p>专家并行与 All-to-All 条目讲通信原语，分组 GEMM 则是这些原语落地后的计算端。Blackwell NVL72 上，All-to-All 的收发与分组 GEMM 的 MMA 发射共享 SM 资源：分组 GEMM 的 warp specialization 把 warp 分为加载、MMA 发射、epilogue 等角色，通信若占用 SM 或共享内存带宽，加载角色的预取就被挤压。分类维度里“与 All-to-All 重叠时的 SM 资源分配”正是这条下游关系的接口。</p>\n<p>可操作的机制是 SM 预留：分组 GEMM kernel 在启动时声明用于通信重叠的 SM 数，剩余 SM 承担 MMA 与 epilogue；组数多时，尾块受对齐粒度与 SM 占用限制无法填满，预留越多，尾块越难找到空闲 SM 收尾。写成约束：</p>\n<div class=\"formula\">$$T_{\\text{group}} \\approx \\max\\left(\\frac{W_{\\text{MMA}}}{S_{\\text{avail}}},\\ T_{\\text{comm}}\\right) + T_{\\text{tail}}(E, A)$$</div>\n<p>其中 $S_{\\text{avail}}$ 是扣除通信预留后的可用 SM 数，$T_{\\text{tail}}$ 是尾块收尾时间，随分组数 $E$ 增大而上升。工程代价是双面的：预留不足则通信等待拖长加载流水，预留过多则尾块并行度不足。具体例子：E 较大、单组 M 维仅对齐到 64 时，最后若干小组各占一个 SM 也填不满 MMA 流水，此时若还把 SM 留给通信，尾块时间被放大；反之若不留，All-to-All 的到达数据无法及时进入下一组 GEMM，流水断流。判断依据是每 SM 处理组数、对齐粒度与组大小分布三者联合调参，而不是单独调通信或单独调分组。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-29\">二十九 · 下游影响：分离式预填/解码与 KV 压缩改变分组形态</h3>\n<p>分离式预填解码条目把预填与解码拆到不同实例，这对分组 GEMM 的下游影响是 batch 形态的变化：预填侧 token 数大、每专家段长容易对齐，padding 率低；解码侧每步 token 少、专家多，段长普遍短于对齐粒度，padding 率飙升。MoE 场景 KV 压缩条目进一步压缩了每步的有效 token 量，使解码侧的分组 GEMM 更偏向“多组、小组、高 padding”的形态。</p>\n<p>机制上，这直接改变累加器复用策略的选择：预填侧适合跨组合并到同一累加器流水以减少切换；解码侧组太小，合并收益被同步点抵消，kernel 倾向逐组重置累加器，TMEM 读写开销占比上升。warp specialization 的角色划分也随之偏移——解码侧加载角色预取量小，MMA 发射 warp 的 barrier 等待成为主导，尾块效率受 SM 占用限制更明显。代价落在延迟上：解码侧每步的分组 GEMM 启动开销与 barrier 开销摊薄变差，单步延迟被固定开销主导，吞吐随 batch 增大才回升。</p>\n<p>具体例子：同一 MoE 模型，预填实例上每专家段长对齐到 128 后 padding 率低，分组 GEMM 接近满流水；解码实例上每步每专家仅数个 token，对齐到 64 后绝大部分是零填充，此时若沿用预填侧的累加器复用与角色划分，TMEM 同步开销超过有效 MMA 时间。工程判断是：分组 GEMM 的调参必须按预填/解码两侧分别设定对齐粒度与累加器策略，不能一套参数跨实例复用。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-30\">三十 · 下游影响：框架与剖析工具链的观测口径</h3>\n<p>MoE 推理框架选型与 MoE 剖析工具链条目提供的是上层调度与观测，分组 GEMM 是它们观测口径里的一个 kernel 族。框架侧关心的是连续批处理如何把不同 batch 的 token 拼成组，分组 GEMM 关心的是拼出来的段长是否可对齐；剖析工具链关心的是尾块效率、kernel 启动开销与 TMEM 占用，而这些指标只有在分组 GEMM 的 warp 角色与同步点数量已知时才有意义。</p>\n<p>机制上，剖析口径需要区分“名义 M 维”与“对齐后 M 维”：前者是框架报告的 token 数，后者是 MMA 实际执行的量，两者之差就是 padding 浪费。速查表里的列——分组数 E、每专家 M 分布、对齐粒度与 padding 率、TMEM 累加器占用、warp 角色与同步点数量、尾块效率、kernel 启动开销、与通信重叠的 SM 预留——正是把这条下游关系结构化的方式。代价体现在容量规划上：若框架按名义 token 数估算算力，容量规划会系统性低估所需 SM 数与显存带宽，SLO 在短专家占比高的负载下失守。</p>\n<p>具体例子：剖析工具报告某 MoE 层分组 GEMM 的 MMA 利用率偏低，若只看名义 M 维会误判为 kernel 实现问题；把对齐后 M 维与 padding 率并列后，才能定位到是路由分布导致短专家零填充，而非 tcgen05 发射效率。工程判断是：分组 GEMM 的性能归因必须与路由分布、对齐粒度、累加器策略三者同时记录，否则剖析结论无法回传到上游调参。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-31\">三十一 · 在全书中的位置：算子精度层与调度层的接缝</h3>\n<p>把分组 GEMM 放回全书结构，它处在算子与数值精度层（NVFP4/FP8、tcgen05、TMEM、2-SM MMA）与批调度层（连续批处理、分离式预填解码、专家并行）的接缝上。上游它接收路由分布与量化布局，下游它把尾块效率与 SM 预留传给通信重叠与容量规划；它自身的技术内容——M 维对齐、padding 浪费、累加器复用、warp specialization 调度约束——是把“精度格式”翻译成“调度代价”的那一步。</p>\n<p>这个位置决定了它的工程判断方式：分组 GEMM 的调参不是孤立 kernel 调优，而是每 SM 处理组数、对齐粒度与组大小分布三者的联合权衡；分组数增大时尾块效率下降、kernel 启动与 barrier 开销摊薄变差，具体拐点未给出，因此必须以实测的 padding 率与尾块时间为准，而不是按名义 token 数推演。与通信计算死锁条目的关系也在此：分组 GEMM 的 barrier 同步点与 All-to-All 的等待若在同一 SM 上交错，死锁风险随分组数上升；解法是在 SM 预留与角色划分阶段就把通信等待与 MMA 发射的同步点分离。</p>\n<p>最终落在具体机制上：分组 GEMM 的 kernel 启动开销与尾块效率是一对反向指标，分组数调大追求负载均衡时，尾块受对齐粒度与 SM 占用限制无法填满，启动与 barrier 开销超过计算收益，端到端变慢。工程上可执行的判断是——先固定对齐粒度与累加器复用策略，再按组大小分布决定是否合并短专家；若合并后 padding 率仍高，则问题在路由侧而不在 kernel 侧，应回传上游调整容量因子与 top-k，而不是继续在 tcgen05 发射路径上加并行度。</p>\n\n<h3 id=\"ap-grouped-gemm-tcgen05-sec-32\">三十二 · 边界条件：分组 GEMM 在什么情况下反而变慢</h3>\n<p>分组 GEMM 的收益来自“把变长 token 段拼成多个 M 维不等的 GEMM、每组对应一个专家权重”，但它并非单调有利。失效的第一条边界是<b>短专家占比</b>：每专家实际 token 数向上取整到对齐粒度（64 或 128），若某专家只有个位数 token，其 MMA 指令里绝大多数行是零填充。设第 e 组实际 token 数为 $M_e$、对齐粒度为 $A$，则有效算力占比为</p>\n<div class=\"formula\">$$\\eta_{\\text{pad}}=\\frac{\\sum_e M_e}{\\sum_e \\lceil M_e/A\\rceil\\cdot A}$$</div>\n<p>当容量因子收紧、路由把 token 集中到少数专家时，$\\eta_{\\text{pad}}$ 可跌破 50%，此时按名义 token 数估算的 GEMM 算力被零填充大幅稀释——这是本模块最常见的踩坑，代价直接体现在 MMA 吞吐与功耗上：SM 执行的是满宽 MMA，但产出有效结果的行不到一半。工程上的应对不是调小对齐粒度（会破坏 tcgen05 指令粒度），而是在路由侧按对齐粒度合并或拆分专家批次，把多个短专家拼进同一累加器流水。</p>\n<p>第二条边界是<b>累加器复用失效</b>。TMEM 累加器在连续 MMA 间保持才有意义；若每组 GEMM 结束即写回全局内存再读入，TMEM 读写与同步开销随分组数线性上升，且与 MMA 争用同一 warp 调度资源。TMEM 容量同时限制驻留累加器数量，超出即需分波执行，波与波之间的 barrier 把尾块暴露出来。第三条边界是<b>分组数本身</b>：组数增大使每组的 MMA 发射与 barrier 开销摊薄变差，尾块（最后几个小组）受对齐粒度与 SM 占用限制无法填满，kernel 启动开销可能超过计算收益，端到端变慢。三者联合调参的对象是每 SM 处理组数、对齐粒度与组大小分布，不存在单点最优。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接代价</th><th>缓解手段</th></tr></thead><tbody><tr><td>短专家占比高</td><td>padding 率 &gt;50%，MMA 吞吐被稀释</td><td>路由侧按对齐粒度合并/拆分</td></tr><tr><td>逐组写回累加器</td><td>TMEM 读写与同步随组数线性上升</td><td>跨组合并到同一累加器流水</td></tr><tr><td>组数过多</td><td>尾块填不满 SM，启动与 barrier 开销占主导</td><td>限制每 SM 组数，尾块拆分而非 padding</td></tr></tbody></table>\n<p>在全书位置上，本节的上游是路由与批调度（决定 $M_e$ 分布与容量因子），下游是 epilogue 与 All-to-All 重叠（尾块与通信共享 SM 资源，需预留 SM 才能重叠）。判断准则很具体：先测 $\\eta_{\\text{pad}}$ 与尾块 SM 占用率，若前者低于有效阈值或后者长期填不满，就应回退到更少分组、更大对齐批次的形态，而不是继续调大分组数追求名义负载均衡。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-grouped-gemm-tcgen05\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>解释按专家分组的变长 GEMM 如何映射到 tcgen05 MMA 与 TMEM，说明 M 维对齐、paddi…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-grouped-gemm-tcgen05 · 共 5 个片段</p>\n"},{"id":"ap-nvfp4-fp8-moe","title":"NVFP4/FP8 权重激活","summary":"说明 NVFP4 的块级缩放与两级量化在 MoE 权重上的误差传播、FP8 E4M3 激活的动态范围与 per-tensor/per-block 缩放选择，以及混合精度下路由分数与专家输出的数值稳定性校验点。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-1\">一 · 条目边界：NVFP4 到底指什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-2\">二 · 两级结构的误差传播路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-3\">三 · FP8 E4M3 激活侧：动态范围与缩放粒度选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-4\">四 · 混合精度下的数值稳定性校验点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-5\">五 · 速查表的列设计与分类落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-6\">六 · 边界条件：块缩放的两级结构与失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-7\">七 · 速查表的字段口径与读取顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-8\">八 · 阈值：块大小、动态范围与精度旁路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-9\">九 · 两级量化的误差传播与校验点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-10\">十 · 混合精度下的数值稳定性校验清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-11\">十一 · 速查表的使用口径：从字段到工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-12\">十二 · 速查表之外的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-13\">十三 · 块缩放粒度的工程折中：16 还是 32</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-14\">十四 · FP8 激活的缩放粒度：per-tensor 与 per-block 的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-15\">十五 · 路由分数的高精度旁路：阈值与翻转测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-16\">十六 · 块缩放因子的布局校验：错位比精度更致命</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-17\">十七 · 混合精度的测量流程：从离线到端到端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-18\">十八 · 失效边界与代价刻度：NVFP4/FP8 混合精度在 MoE 上的工程阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-19\">十九 · 路由分数被量化：翻转不是随机噪声</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-20\">二十 · 块缩放因子与元素布局错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-21\">二十一 · 缩放因子自身的二次舍入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-22\">二十二 · 残差与归一化的高精度旁路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-23\">二十三 · 检查顺序与回滚方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-24\">二十四 · 失效边界与回滚：从错位反量化到路由翻转的排查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-25\">二十五 · 上游依赖：块缩放布局与校准数据是硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-26\">二十六 · 下游影响：路由分数保护与累加精度决定系统行为</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-27\">二十七 · 横向关系：与分组 GEMM、KV 压缩、通信条目的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-28\">二十八 · 在全书中的位置：精度层的入口与出口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-29\">二十九 · 工程判断：把关系写成可执行的校验点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-nvfp4-fp8-moe-sec-30\">三十 · 边界条件：这套精度方案在什么情况下会失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-nvfp4-fp8-moe\"><svg style=\"max-width:489px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 488.9 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"406.9\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：NVFP4/FP8 权重激活</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">说明 NVFP4 的块级缩放与两级量化在 MoE 权重上的误差传播、</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">FP8 E…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"406.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"406.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"406.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-nvfp4-fp8-moe-sec-1\">一 · 条目边界：NVFP4 到底指什么</h3>\n<p>在本卷的语境里，NVFP4 是一个<strong>格式族</strong>而非单一 dtype：4 位浮点元素 + 固定大小元素块共享一个 FP8 E4M3 缩放因子，构成“块缩放 + 元素量化”的两级结构。它描述的是<em>权重的存储与乘加输入形态</em>，不是某种 kernel 名字，也不等同于“把权重压到 4 bit”这一句话。工程上判断一个实现是否属于本条目，看三条：元素位宽为 4；缩放因子按块共享且类型为 FP8 E4M3（或 E5M2）；反量化发生在 MMA 消费操作数之前或融合于其中。三条缺一，就落到相邻条目去了。</p>\n<p>与之相邻但不同的概念需要一次性切开。<strong>INT4 权重量化</strong>是整数格点 + 零点/尺度，误差结构是均匀量化噪声，对离群值敏感且没有指数位可吸收动态范围；NVFP4 有指数位，块内尾数只有几位，因此它的误差不是“均匀噪声”而是“块内相对误差 + 块间缩放误差”的叠加。<strong>MXFP4</strong> 同样共享块缩放，但缩放因子取 E8M0（纯幂次），块大小与缩放语义不同，二者不可互换反量化代码。<strong>FP8 权重+激活</strong>是另一档位宽，讨论的是 E4M3 的动态范围与 per-tensor/per-block 缩放选择，位宽不同、误差量级不同，不能把 FP8 的校准结论直接搬到 FP4 上。<strong>KV cache 量化</strong>属另一条链路，量化对象是缓存张量而非权重，其误差经注意力 softmax 放大，机制与本条目正交。</p>\n<p>代价上要立刻建立量级感：FP4 权重配合 FP8 块缩放可将权重显存压至 FP16 的约四分之一，激活侧 FP8 相对 FP16 显存减半。这不是免费的——每个块要多带一个缩放因子，块大小 16 时缩放因子的额外开销是每 16 个元素 1 字节，折算到 4 位元素上相当于位宽从 4 位抬到约 4.5 位；块越小精度越好、缩放开销越大。举例：一个专家权重矩阵若按 16 元素块量化，反量化路径上每个 MMA 操作数都要先做一次“元素 × 块缩放”的乘，这个乘在 tcgen05 路径上通常被折进操作数准备阶段，代价体现为额外的 TMEM/寄存器读写与指令发射，而不是矩阵乘本身变慢。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-2\">二 · 两级结构的误差传播路径</h3>\n<p>两级量化的误差要分开记账。第一级是元素级：块内以 FP4 的尾数与指数表示，引入的是相对于块缩放基准的舍入误差，量级由块内动态范围决定。第二级是块级：缩放因子本身是 FP8 E4M3，它把块的幅值映射到 FP4 可表示的区间，这一步引入的是<em>缩放因子的表示误差</em>，并且它对块内所有元素同向偏移。两级串联后，单个元素的重建值为</p>\n<div class=\"formula\">$$\\hat{w}_i = s_b \\cdot q_i,\\quad s_b = \\mathrm{FP8}\\!\\left(\\frac{\\max_{j\\in b}|w_j|}{\\text{FP4}_{\\max}}\\right),\\quad q_i = \\mathrm{FP4}\\!\\left(\\frac{w_i}{s_b}\\right)$$</div>\n<p>关键在于 $s_b$ 一旦被低精度存储又参与逐元素乘，就产生二次舍入：先量化 $s_b$，再用量化后的 $s_b$ 去除 $w_i$ 得到 $q_i$，反量化时又用同一个 $s_b$ 乘回去。误差不会互相抵消，而是在长累加中同向累积。这正是“两级量化中缩放因子本身用低精度存储引入二次舍入”这条失败模式的机理。</p>\n<p>MoE 权重按专家分块量化时，缩放因子随专家粒度独立，误差不会跨专家传播——这是 NVFP4 在 MoE 上相对 per-tensor 的核心优势。per-tensor 缩放让所有专家共享一个尺度，小幅值专家的量化信噪比骤降；per-expert 或 per-block 则把每个专家的幅值各自归一化。代价是缩放因子的读写：专家数越多、块越小，缩放因子表越大，反量化前的元数据加载越占带宽。举例：路由到某专家的一批 token 只触发该专家权重的部分块，若块边界与专家边界不对齐，一次反量化可能跨专家取缩放因子，表现为个别通道数值爆炸而非整体误差——这就是“按行量化却按 128 元素块反量化”造成还原错位的具体形态。</p>\n<p>校验点上，误差传播的可观测性依赖三个位置：块缩放因子表的一致性校验（轴与块边界是否匹配）、反量化后逐块的最大相对误差、以及累加器精度。专家输出在累加时用 FP32 累加器以避免 FP4/FP8 乘积的舍入累积，这一条不是可选项，而是把“块内误差”限制在单次乘加、不让它跨 K 维放大的必要条件。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-3\">三 · FP8 E4M3 激活侧：动态范围与缩放粒度选择</h3>\n<p>FP8 E4M3 的动态范围约 $$\\pm 448$$，最小正规数约 $$2^{-6}$$。这个区间对激活来说偏窄：激活分布的长尾很容易越过 448 饱和，而小幅值部分又贴近最小正规数掉进次正规区。因此激活侧必须靠缩放把分布压进该范围，缩放粒度的选择直接决定误差形态。</p>\n<p>per-tensor 缩放实现最简单，一次乘加即可还原，反量化开销几乎为零，适合激活幅值在张量内相对均匀的情形。但 MoE 中不同专家的激活幅值差异大，per-tensor 会令小幅值专家量化信噪比骤降——大专家把尺度撑大，小专家的有效位数被挤掉。per-block 缩放以额外缩放因子读写换取精度：每个块独立归一化，块内动态范围被压缩，E4M3 的尾数利用率上升。代价是反量化路径上多一次按块的乘与一次元数据加载，块越小越精确、带宽开销越大。工程经验是块大小 16–32 个元素在缩放开销与精度间折中，这与 NVFP4 权重侧的块大小选择逻辑同源，但激活侧还要额外考虑激活是逐 token 动态生成的，缩放因子必须在运行时计算而不能预存。</p>\n<p>分类维度在这里显形：<em>量化对象</em>（仅权重 / 权重+激活 / KV）决定缩放因子是静态还是动态；<em>缩放粒度</em>（per-tensor / per-channel / per-block / per-expert）决定误差被限制在哪一层；<em>缩放因子数据类型</em>（E4M3 / E5M2 / FP16）决定二次舍入的量级；<em>是否两级量化</em>决定是否存在块级与元素级误差的串联；<em>是否对路由分数做保护性高精度计算</em>决定 MoE 的选择稳定性。这五个维度不是并列的选项清单，而是互相约束的：选了 per-block 就必须接受动态缩放因子的计算与加载代价，选了 FP4 权重就必须回答缩放因子用什么精度存。</p>\n<p>具体例子：同一层激活，per-tensor 缩放下若张量最大值把尺度顶到接近 448，则幅值小于 1 的元素只剩很少的有效尾数位，反量化后相对误差显著；切到 per-block（块 32）后，每个块按自身最大值归一，小幅值块的元素重新获得有效位，代价是每 32 个元素多一次缩放因子读取。这个交换在带宽受限的解码阶段尤其敏感，因为解码是 memory-bound，缩放因子表的额外流量直接折算成 token 间隔。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-4\">四 · 混合精度下的数值稳定性校验点</h3>\n<p>混合精度不是“权重 FP4、激活 FP8”这一句话就完了，它要求明确哪些张量<em>不</em>参与低精度路径。路由分数建议保留 FP32 或 BF16 计算：把路由 logits 也量化到 FP4/FP8 会导致 top-k 选择翻转、专家负载分布漂移。这是本条目最常被踩的坑，机理清楚——top-k 是在边界样本上做比较，logits 之间的差距可能小于量化步长，一旦量化就把排序关系打乱，选中的专家集合改变，负载分布随之漂移，而负载漂移又反过来改变每个专家看到的 token 分布，形成正反馈。</p>\n<p>残差连接与归一化同样要保持高精度。误差经多层放大：单层的块内舍入误差在残差通路上不被归一化重新标定，逐层累加后可能压过信号。校验点应设在三处：路由分支的 logits 比较是否在 FP32/BF16 下完成；专家输出的 K 维累加是否用 FP32 累加器；残差与归一化是否绕过低精度路径。缺任一校验点，故障表现是“边界样本 top-k 翻转 + 负载不均 + 精度塌陷”的组合，而不是均匀的精度下降，定位难度高。</p>\n<p>代价维度上，保护性高精度计算不是零成本：路由 logits 用 FP32 意味着这一小段张量不享受位宽收益，但它占总计算量的比例极小，换来的选择稳定性远超其开销。真正贵的是 FP32 累加器——它在 MMA 之后、写回之前占用寄存器/TMEM 资源，长 K 维下累加器驻留时间拉长，影响流水编排。工程判断是：累加器精度不能省，路由精度可以按模型对 top-k 边界的敏感度分级处理。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-5\">五 · 速查表的列设计与分类落地</h3>\n<p>把上述维度落成一张可查的表，列必须能回答“这个格式在我这条链路上会怎么错”。建议列：格式、位宽、块大小、缩放因子类型、适用张量、误差传播路径、是否需要校准。前四列是格式身份，第五列限定作用对象，第六列是诊断入口，第七列决定部署时是否要跑校准数据管线。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>位宽</th><th>块大小</th><th>缩放因子类型</th><th>适用张量</th><th>误差传播路径</th><th>需校准</th></tr></thead><tbody><tr><td>NVFP4（权重）</td><td>4</td><td>16–32 元素</td><td>FP8 E4M3</td><td>专家权重</td><td>块内舍入 + 块缩放二次舍入，按专家隔离</td><td>是（块尺度）</td></tr><tr><td>FP8 E4M3（激活）</td><td>8</td><td>per-tensor / per-block</td><td>FP16 或 FP32（动态）</td><td>激活</td><td>饱和截断 + 小幅值信噪比下降</td><td>动态，无需离线校准</td></tr><tr><td>FP8 E4M3（权重）</td><td>8</td><td>per-channel</td><td>FP16</td><td>权重</td><td>通道级尺度误差，无块内串联</td><td>是</td></tr><tr><td>路由分数</td><td>32 / 16</td><td>—</td><td>—</td><td>logits</td><td>不量化，避免 top-k 翻转</td><td>否</td></tr></tbody></table>\n<p>表的用法不是查完就完，而是把“误差传播路径”列当作排障索引：出现个别通道数值爆炸，先查块边界与张量轴是否匹配；出现整体精度缓慢下降，先查缩放因子是否被低精度存储又参与逐元素乘；出现负载不均与边界样本翻转，先查路由分支是否被降精度。这三类症状对应三条不同的失败模式，混在一起排查会浪费大量时间。</p>\n<p>最后落到一个工程判断上：NVFP4 的收益来自“块缩放把误差锁在块内、专家粒度把误差锁在专家内”，因此任何破坏块边界或专家边界的实现——无论是反量化轴错位，还是把缩放因子表跨专家复用——都会把可控的块内误差变成不可控的跨通道爆炸。定义与分类的价值就在于：在写第一行反量化代码之前，先确认块大小、缩放因子类型、张量轴三者对齐，并确认路由与累加两条高精度旁路存在。这两条确认做完，后面的 kernel 选择与调度才有意义。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-6\">六 · 边界条件：块缩放的两级结构与失效面</h3>\n<p>NVFP4 的“块缩放 + 元素量化”两级结构决定了它的失效面不在整体误差，而在块边界与缩放因子的存储精度上。块内 16 或 32 个元素共享一个 FP8 E4M3 缩放因子，反量化时元素必须与所属块的因子严格对齐：若按行量化却按 128 元素块反量化，个别通道会出现数值爆炸而非均匀误差，这类错位在整层输出上表现为稀疏的尖峰，常规的层间误差统计难以捕获。更隐蔽的是缩放因子本身用低精度存储又参与逐元素乘，二次舍入在长上下文累加中逐步累积，缺少校验点时几乎无法定位。工程上应把缩放因子按 FP16 或 FP32 保存、仅在计算时降精度，并在反量化后插入一次块级一致性校验。</p>\n<p>激活侧的边界由 FP8 E4M3 的动态范围决定。其可表示范围约 <span class=\"formula\">$$\\pm 448$$</span>，最小正规数约 <span class=\"formula\">$$2^{-6}$$</span>，激活分布必须被缩放压入该区间。per-tensor 缩放只需一次乘加即可还原，代价最低；但在 MoE 中不同专家的激活幅值差异显著，单一 per-tensor 因子会让小幅值专家的量化信噪比骤降，等效于对该专家做了粗粒度截断。per-block 缩放以额外的因子读写换取精度，代价是反量化路径上多一次因子加载与乘运算，在带宽受限的解码阶段直接体现为每 token 的额外访存。</p>\n<p>路由分数是另一条不可压缩的边界。把路由 logits 一并量化到 FP4/FP8，会使 top-k 选择在边界样本上翻转，专家负载分布随之漂移，进而改变批内实际激活的专家集合，使容量规划失效。因此路由分数应保留 FP32 或 BF16 计算，专家输出在累加时使用 FP32 累加器，避免 FP4/FP8 乘积的舍入在多专家求和时累积。残差连接与归一化同样需要高精度旁路，否则误差会经多层放大。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>块轴与因子广播不匹配</td><td>元素与缩放因子错位</td><td>个别通道数值爆炸，需逐层排查</td></tr><tr><td>缩放因子低精度存储</td><td>二次舍入累积</td><td>长上下文精度漂移，定位成本高</td></tr><tr><td>路由 logits 量化</td><td>top-k 翻转</td><td>专家负载漂移，容量与显存规划失准</td></tr></tbody></table>\n<h3 id=\"ap-nvfp4-fp8-moe-sec-7\">七 · 速查表的字段口径与读取顺序</h3>\n<p>这张表不是格式清单，而是决策入口：给定一个张量（权重、激活、KV、路由 logits），先确定它的角色，再沿“位宽→块大小→缩放因子类型→适用张量→误差传播路径→是否需要校准”六列读一行。读表顺序固定为：先看“适用张量”锁定对象，再看“误差传播路径”判断该量化会不会跨专家、跨层扩散，最后看“是否需要校准”决定上线前要不要跑校准集。字段口径必须统一，否则同一格式在不同条目里被读出两种含义：位宽指存储位宽而非有效精度位宽；块大小指共享一个缩放因子的元素个数，且必须与反量化时的张量轴一致；缩放因子类型写具体浮点格式（FP8 E4M3、FP8 E5M2、FP16），不写“低精度”；误差传播路径写“是否跨专家/跨层”，因为 MoE 权重按专家分块量化时缩放因子随专家粒度独立，误差不跨专家传播，这一条直接决定校准集能否按专家切分。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>位宽</th><th>块大小</th><th>缩放因子类型</th><th>适用张量</th><th>误差传播路径</th><th>是否需要校准</th></tr></thead><tbody>\n<tr><td>NVFP4 权重</td><td>4 bit</td><td>16 或 32 元素</td><td>FP8 E4M3</td><td>专家权重矩阵</td><td>块内累积，不跨专家</td><td>需要（按专家粒度）</td></tr>\n<tr><td>NVFP4 激活</td><td>4 bit</td><td>16 或 32 元素</td><td>FP8 E4M3</td><td>专家输入激活</td><td>块内累积，经层放大</td><td>需要（含路由边界样本）</td></tr>\n<tr><td>FP8 E4M3 权重</td><td>8 bit</td><td>per-tensor 或 per-block</td><td>FP16 或 FP8</td><td>专家权重、稠密层</td><td>per-tensor 跨通道，per-block 限块内</td><td>需要（per-tensor 需全局统计）</td></tr>\n<tr><td>FP8 E4M3 激活</td><td>8 bit</td><td>per-tensor 或 per-block</td><td>FP16 或 FP8</td><td>激活、KV 写入前</td><td>per-tensor 令小幅值专家信噪比骤降</td><td>需要（按专家分布分桶）</td></tr>\n<tr><td>路由 logits</td><td>FP32/BF16</td><td>不量化</td><td>—</td><td>路由分数</td><td>不进入量化路径</td><td>不需要</td></tr>\n<tr><td>专家输出累加</td><td>FP32 累加器</td><td>—</td><td>—</td><td>归约缓冲</td><td>抑制乘积舍入累积</td><td>不需要</td></tr>\n</tbody></table>\n<p>表里两行“不量化”是硬约束而非建议：路由 logits 一旦进入 FP4/FP8 路径，top-k 选择会在边界样本上翻转，专家负载分布随之漂移，代价是尾延迟与容量因子同时恶化；专家输出若用低精度累加器，FP4/FP8 乘积的舍入会在长上下文归约中累积。工程上把这两行当作旁路（bypass）通道设计，而不是量化候选。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-8\">八 · 阈值：块大小、动态范围与精度旁路</h3>\n<p>材料未给出统一阈值，可用的只有领域经验与格式本身的硬边界。FP8 E4M3 的动态范围约 <span>±448</span>，最小正规数约 <span>2<sup>-6</sup></span>，这两条是判断“激活能否直接进 FP8”的硬口径：激活分布若超出 ±448 必须靠缩放压回，若大量元素落在 2<sup>-6</sup> 以下则退化为次正规数、有效位骤减。缩放粒度选择由此分叉：per-tensor 一次乘加即可还原，实现代价最低；per-block 以额外缩放因子的读写换精度。MoE 中不同专家的激活幅值差异大，per-tensor 会让小幅值专家的量化信噪比骤降，这是选择 per-block 的唯一充分理由，而不是“精度更高”这种笼统说法。</p>\n<div class=\"formula\">$$\\text{snr}_{\\text{expert}} \\approx 20\\log_{10}\\frac{\\sigma_{\\text{expert}}}{\\Delta_{\\text{quant}}},\\quad \\Delta_{\\text{quant}} \\propto \\frac{\\max|\\mathbf{a}|_{\\text{tensor}}}{2^{b-1}}$$</div>\n<p>上式说明：per-tensor 的量化步长由全张量最大幅值决定，小幅值专家的 σ 与 Δ 之比被拉低，信噪比按专家幅值比例下降；per-block 把 max 限制在块内，步长随块自适应。代价是缩放因子本身的读写：块大小 16–32 元素是缩放开销与精度间的折中口径，块越小缩放因子越多、反量化时的带宽与指令开销越高。FP4 权重配合 FP8 块缩放可将权重显存压至 FP16 的约四分之一，激活侧 FP8 相对 FP16 显存减半——这两个比例是容量规划的输入，不是精度承诺。</p>\n<p>精度旁路阈值同样要写进口径：路由分数保留 FP32 或 BF16 计算，专家输出用 FP32 累加器。判断某层能否降精度的检查点是“该层输出是否直接参与路由或残差”，参与则保留高精度旁路。归一化与残差连接保持高精度的理由不是保守，而是误差经多层放大的路径最短：这两处一旦量化，误差不经过任何非线性压缩就进入下一层。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-9\">九 · 两级量化的误差传播与校验点</h3>\n<p>NVFP4 的两级结构是“块缩放 + 元素量化”：固定大小元素块共享一个 FP8 E4M3 缩放因子，块内元素以 FP4 尾数与指数表示。误差因此有两条路径：元素量化的舍入在块内累积，缩放因子的表示误差则整体乘到块上。若缩放因子本身用低精度存储又参与逐元素乘，二次舍入在长上下文累加中累积，且校验点缺失时难以定位——现象是整体误差缓慢抬升而非个别通道爆炸，排查时容易误判为激活分布漂移。</p>\n<div class=\"formula\">$$\\hat{w}_i = s_b\\cdot q_i,\\quad \\text{err}=\\underbrace{(s_b-\\hat{s}_b)q_i}_{\\text{缩放二次舍入}}+\\underbrace{s_b(q_i-\\hat{q}_i)}_{\\text{元素量化}}$$</div>\n<p>校验点应放在三处：块缩放因子反量化后的逐块均值与方差、专家输出归约前的 FP32 缓冲抽样、以及路由 top-k 边界样本的选择一致性。第一处抓缩放因子错位，第二处抓累加舍入，第三处抓路由漂移。工程代价上，校验点本身要读回张量，per-block 校验的带宽开销与块大小成反比；把校验点放在专家粒度而非全张量粒度，可以把开销限制在单专家缓冲内，不打断连续批处理的流水。</p>\n<p>具体例子：某专家权重按行量化却按 128 元素块反量化，缩放因子与元素布局错位，表现为个别通道数值爆炸而非整体误差——这正是“块缩放因子按错误张量轴广播”的典型失败模式，校验点一（逐块均值方差）会立刻显示该块方差偏离，而全张量误差指标几乎不动。因此速查表的“误差传播路径”列必须写清块边界与张量轴的对应关系，不能只写“块内”。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-10\">十 · 混合精度下的数值稳定性校验清单</h3>\n<p>混合精度不是“权重 FP4、激活 FP8”这么一句配置，而是一组必须逐项确认的稳定性条件。清单按张量角色排列：权重侧确认缩放因子随专家粒度独立、块边界与反量化轴一致；激活侧确认 per-block 缩放覆盖小幅值专家、FP8 动态范围未被击穿；路由侧确认 logits 未进入量化路径、top-k 在边界样本上稳定；归约侧确认 FP32 累加器覆盖全部专家输出；残差与归一化确认保持高精度。每一项对应一个可观测现象，而不是抽象原则。</p>\n<ul>\n<li>路由 logits 量化到 FP4/FP8 → top-k 选择翻转、专家负载分布漂移，尾延迟上升；对应校验为边界样本 top-k 一致性抽样。</li>\n<li>块缩放因子与元素布局不匹配 → 个别通道数值爆炸而非整体误差；对应校验为逐块均值方差。</li>\n<li>缩放因子低精度存储并参与逐元素乘 → 二次舍入在长上下文累加中累积；对应校验为归约前 FP32 缓冲抽样。</li>\n<li>残差与归一化未保持高精度 → 误差经多层放大；对应校验为层间输出范数比值。</li>\n</ul>\n<p>这些失败模式的共同点是“局部正确、全局漂移”，所以校验必须按专家、按块、按层分段做，而不是只看端到端指标。分段校验的代价是额外读回与比对，收益是把定位时间从“整网排查”压到“单专家缓冲”。在连续批处理下，校验点应挂在批次边界而非每 token，避免打断流水。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-11\">十一 · 速查表的使用口径：从字段到工程判断</h3>\n<p>表的每一列都对应一个工程判断，读表时要能把列值翻译成动作。“缩放因子类型”为 FP8 E4M3 时，若该因子还参与逐元素乘，就要检查二次舍入，动作是把因子提升到 FP16 或在校验点加抽样；“块大小”为 16–32 时，动作是确认反量化核的块边界与量化时一致，而不是在 kernel 里按 128 元素重排；“误差传播路径”写“不跨专家”时，动作是校准集可按专家切分、单专家精度回归可独立做，这直接降低校准数据管线的规模。</p>\n<p>容量侧的口径同样来自表：FP4 权重配 FP8 块缩放把权重显存压到 FP16 的约四分之一，激活 FP8 减半，这两个比例进入显存预算；但缩放因子本身的存储要单独计——块越小因子越多，per-block 的因子开销与块大小成反比，块大小 16 时因子数量是块大小 32 时的两倍。带宽侧，per-block 反量化要多读因子，因子读取与元素读取的比例决定该层是带宽受限还是计算受限。延迟侧，路由旁路与 FP32 累加器不增加量化开销，但分段校验点会增加批次边界的同步，需在 SLO 预算里单列。</p>\n<p>最后一条口径是“是否需要校准”列与失败模式的联动：需要校准的行，校准集必须覆盖路由边界样本与小幅值专家，否则 per-tensor 的信噪比下降和 top-k 翻转都不会在校准阶段暴露。校准阶段不测这两类样本，等于把失败模式推迟到线上。速查表的价值不在于列全，而在于每一行都能追到一个可观测现象和一个可执行动作——字段是入口，阈值是判据，口径是动作，三者对齐后这张表才能直接照着用。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-12\">十二 · 速查表之外的失效边界与系统代价</h3>\n<p>速查表能回答“填什么”，回答不了“什么时候这张表会骗你”。NVFP4 的两级结构里，真正决定成败的不是 FP4 尾数，而是缩放因子的布局契约：块大小 16 或 32、缩放因子为 FP8 E4M3、按专家粒度独立——三者必须与 kernel 的反量化循环完全对齐。若权重按行量化却让 kernel 按 128 元素块广播缩放因子，反量化时元素与因子错位，症状不是整体误差抬升，而是个别通道数值爆炸，校验点若只看全局 MSE 会完全漏掉。工程上应把“块边界—张量轴—kernel tile”三元组写进速查表的一列，而不是散落在注释里。</p>\n<p>误差传播路径要按张量分开登记。MoE 权重按专家分块量化时缩放因子随专家独立，误差不跨专家传播，这是 NVFP4 在 MoE 上可用的前提；但激活侧 FP8 E4M3 的动态范围约 <span class=\"formula\">$$\\pm 448$$</span>、最小正规数约 <span class=\"formula\">$$2^{-6}$$</span>，per-tensor 缩放一次乘加即可还原、实现最省，却在专家激活幅值差异大时令小幅值专家量化信噪比骤降。per-block 缩放以额外缩放因子的读写换取精度，代价是反量化路径上多一次访存与一次乘：在解码阶段每 token 都要走这条路径，缩放因子带宽开销会直接体现在 TPOT 上，而不是只体现在显存占用上。</p>\n<p>路由分数是速查表必须单列的高精度旁路。把 logits 一并压到 FP4/FP8，top-k 选择会在边界样本上翻转，专家负载分布漂移，随后被连续批处理的调度器放大成尾延迟抖动——这是精度问题转化为 SLO 问题的典型链路。专家输出累加需 FP32 累加器，否则 FP4/FP8 乘积的舍入在长上下文累加中累积；两级量化中缩放因子本身若用低精度存储又参与逐元素乘，二次舍入同样在累加中沉淀，缺校验点时难以定位。残差连接与归一化保持高精度，是防止误差经多层放大的最低成本手段。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测症状</th><th>系统代价口径</th></tr></thead><tbody><tr><td>缩放因子轴/块边界错配</td><td>个别通道数值爆炸，全局指标正常</td><td>反量化访存翻倍，TPOT 抬升</td></tr><tr><td>路由 logits 量化</td><td>top-k 翻转、专家负载漂移</td><td>批内尾延迟抖动，吞吐方差变大</td></tr><tr><td>缩放因子低精度二次舍入</td><td>长上下文累加偏差</td><td>需回退高精度重算，显存与带宽双升</td></tr></tbody></table>\n<h3 id=\"ap-nvfp4-fp8-moe-sec-13\">十三 · 块缩放粒度的工程折中：16 还是 32</h3>\n<p>NVFP4 的两级结构里，块大小是第一个必须拍板的工程参数。块内共享一个 FP8 E4M3 缩放因子，块越大，缩放因子带来的额外读写与元数据开销越小，但块内元素幅值差异被同一个因子压缩，尾数动态范围不足导致的量化信噪比下降就越明显。工程上的经验区间是 16–32 个元素：16 元素块让每个块的幅值分布更集中，适合专家权重这种本身已经按专家切分、内部统计相对一致的张量；32 元素块把缩放因子数量减半，在权重显存与反量化带宽上更省。</p>\n<p>代价要算清楚。设权重元素数为 $N$，块大小为 $B$，缩放因子用 FP8 存储，则每元素平均位宽为</p>\n<div class=\"formula\">$$w_{\\text{eff}} = 4 + \\frac{8}{B}\\ \\text{bit}$$</div>\n<p>B=16 时约 4.5 bit，B=32 时约 4.25 bit。相对 FP16 的 16 bit，两者都把权重压到约四分之一量级，但 B=16 多出的 0.25 bit 换来的是块内更窄的幅值跨度。反量化路径上，每个块要读一次缩放因子再做一次向量乘，B=16 意味着缩放因子的读取次数是 B=32 的两倍，在权重流式读取为主的解码阶段，这部分元数据带宽不可忽略。</p>\n<p>具体判断方法：取一个代表性专家的权重张量，按 B=16 与 B=32 分别做块量化再反量化，统计每个块的 max/min 幅值比。若大量块的幅值比超过 FP4 尾数能覆盖的范围，说明块内已经“挤不下”，应缩到 16；若幅值比普遍很小，32 更划算。这个测量不需要端到端跑推理，单层离线即可完成，是选块大小的第一道筛子。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-14\">十四 · FP8 激活的缩放粒度：per-tensor 与 per-block 的分界</h3>\n<p>FP8 E4M3 的动态范围约 $\\pm 448$，最小正规数约 $2^{-6}$，激活要落进这个窗口必须靠缩放。per-tensor 缩放一次乘加即可还原，实现最简，但在 MoE 里致命：不同专家的激活幅值差异大，一个全局缩放因子会让小幅值专家的量化信噪比骤降，等效于把它们的有效位宽砍掉。per-block 缩放用额外的缩放因子读写换精度，是 MoE 激活侧的默认选择。</p>\n<p>分界怎么定？工程上按“专家内激活幅值的相对离散度”判断。对每个专家单独统计激活的绝对值分位数（如 99.9% 分位与中位数之比），若该比值在专家间跨度大，per-tensor 必然牺牲部分专家；若各专家内部该比值本身就大，则 per-block 的块也不能太大，否则块内又被压平。测量方法是：固定校准集，逐专家导出激活直方图，计算“若用单一缩放因子，有多少比例的元素落入非正规数区间或饱和区”。这个比例是选粒度的直接依据，而不是凭格式直觉。</p>\n<p>代价方面，per-block 缩放让激活反量化多一次因子读取与向量乘，在预填阶段计算密集、这部分开销可被 MMA 掩盖；在解码阶段激活量小、因子开销占比上升，但仍远小于权重读取。真正的风险在两级量化的二次舍入：缩放因子若本身用低精度存储又参与逐元素乘，长上下文累加中误差会累积，校验点缺失时难以定位。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-15\">十五 · 路由分数的高精度旁路：阈值与翻转测量</h3>\n<p>路由 logits 是 MoE 推理中最不能省的数值。把路由分数也量化到 FP4/FP8，top-k 选择会在边界样本上翻转，专家负载分布随之漂移，尾延迟与精度同时受损。工程经验是路由分数保留 FP32 或 BF16 计算，专家输出累加用 FP32 累加器，避免 FP4/FP8 乘积的舍入累积。这条旁路的成本是每次路由一次高精度小矩阵乘，相对专家 GEMM 的体量可以忽略，但它是负载均衡的前提。</p>\n<p>翻转怎么测？构造一批接近 top-k 边界的样本：对每个 token 取路由分数的第 k 与第 k+1 名，计算其差值 $\\Delta = s_{(k)} - s_{(k+1)}$。把路由计算降到目标低精度再算一遍，统计 $\\Delta$ 小于低精度路由误差量级的样本比例，这个比例就是翻转率的上界估计。翻转率高的模型，路由旁路不能省；翻转率极低的模型，才可以考虑在路由上做量化实验，且必须保留回退路径。</p>\n<p>另一个校验点是专家输出的数值稳定性：混合精度下若残差连接与归一化未保持高精度，误差会经多层放大。测量方法是逐层注入已知扰动，观察输出偏差是否随层数线性增长还是指数增长；指数增长说明该层的归一化或残差路径被低精度污染，需要把这一小段拉回高精度。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-16\">十六 · 块缩放因子的布局校验：错位比精度更致命</h3>\n<p>最常见的踩坑不是精度不够，而是缩放因子与元素布局不匹配。按行量化却按 128 元素块反量化，或缩放因子按错误的张量轴广播，反量化时元素与因子错位，表现为个别通道数值爆炸而非整体误差。这类错误在整体 loss 上不一定明显，但在逐通道统计上极其刺眼。</p>\n<p>校验方法：反量化后逐通道计算重构误差的方差，正常情况下方差应在通道间平滑；若少数通道方差高出数量级，几乎可以断定是块边界或广播轴错位。另一个快速检查是缩放因子的形状与元素张量的形状是否满足整除关系，以及块索引的展开顺序是否与量化时一致。工程上应把“量化-反量化-逐通道误差”作为单元测试固化，而不是等到端到端精度掉点才回头查。</p>\n<p>代价上，错位造成的不是均匀的精度损失，而是局部数值爆炸，可能直接触发 NaN 或让某些专家的输出完全失真，表现为路由看似正常但专家输出异常。这类失败模式比单纯的量化噪声更难定位，因为误差不随层数平滑传播。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-17\">十七 · 混合精度的测量流程：从离线到端到端</h3>\n<p>没有统一阈值，所以测量流程本身就是工程规范。建议三段式：第一段离线逐张量，测块大小与缩放粒度的重构误差，筛掉明显不合适的组合；第二段逐层，测路由翻转率与专家输出偏差，确认高精度旁路的位置；第三段端到端，测精度掉点与吞吐、显存的实际收益，确认混合精度配置的净收益为正。</p>\n<p>端到端阶段要同时记录三类代价：权重显存（FP4 权重配 FP8 块缩放约为 FP16 的四分之一，激活侧 FP8 相对 FP16 减半）、反量化带宽（缩放因子读取次数随块大小变化）、以及路由旁路带来的额外计算。三者中任何一项吃掉收益，配置就要回退。测量时应固定校准集与输入分布，避免分布漂移掩盖真实的量化误差。</p>\n<p>最后落在具体机制上：把“路由高精度旁路 + 专家权重按专家粒度块量化 + 激活 per-block 缩放 + FP32 累加器”作为默认基线，任何偏离基线的配置都必须通过翻转率与逐通道误差两道校验才能上线。阈值不是拍出来的，是这三段测量在具体模型与具体负载上量出来的。</p>\n\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-18\">十八 · 失效边界与代价刻度：NVFP4/FP8 混合精度在 MoE 上的工程阈值</h3>\n<p>本方案真正危险的不是平均误差，而是误差沿三条路径的非线性放大：路由 logits、块边界错位、缩放因子二次舍入。路由分数一旦降到 FP4/FP8，top-k 选择在 logits 间距小于量化步长的边界样本上翻转，专家负载分布随之漂移——这不是精度问题而是调度问题，被翻转的 token 进入错误专家，其输出与残差相加后污染下游层，且翻转本身不可从单层误差指标观测。因此路由计算必须保留 FP32 或 BF16 旁路，量化只作用于专家权重与激活，校验点应设在“路由 top-k 索引在量化前后是否一致”这一离散量上，而非输出张量的相对误差。块边界错位是第二种失效：按行量化却按 128 元素块反量化，缩放因子与元素错位广播，表现为个别通道数值爆炸而非整体误差抬升——整体 loss 曲线平滑，个别通道已溢出。工程上必须把“块大小 × 张量轴 × 广播形状”作为三元组在加载时断言，块大小取 16–32 个元素是缩放开销与精度的折中，但折中点必须与布局绑定，不能跨轴复用。</p>\n<p>代价刻度需要按张量分开记。FP4 权重配 FP8 块缩放把权重显存压到 FP16 的约四分之一，激活侧 FP8 相对 FP16 显存减半；但块缩放引入额外缩放因子读写，每 16 个元素一个 FP8 因子意味着反量化路径上每元素多一次乘加与一次因子加载，块越小因子带宽占比越高。设块大小 $B$、元素位宽 $w_e$、因子位宽 $w_s$，则有效位宽为</p>\n<div class=\"formula\">$$w_{\\text{eff}} = w_e + \\frac{w_s}{B}$$</div>\n<p>B=16、w_e=4、w_s=8 时有效位宽 4.5 bit，B=32 时降至 4.25 bit；但 B=32 在专家激活幅值剧烈变化时块内动态范围不足，小幅值元素被同一因子压到 FP4 尾数下溢。这正是 per-tensor 缩放在 MoE 上的失效条件：不同专家激活幅值差异大，per-tensor 令小幅值专家量化信噪比骤降，per-block 以因子读写换精度。判断阈值不在论文里，在测量里：对每个专家分别统计激活绝对值分位数，若专家间 P99 幅值比超过 FP8 E4M3 动态范围（约 ±448，最小正规数约 $2^{-6}$）可容纳的比值，per-tensor 即不可用；该比值可直接由校准集前向统计得出，无需训练。</p>\n<p>两级量化的二次舍入是长上下文累加中最难定位的失效：缩放因子本身以 FP8 存储又参与逐元素乘，因子量化误差在每层、每 token 重复注入，FP32 累加器只能抑制乘积舍入累积，抑制不了因子偏差的系统性漂移。测量方法是把同一校准集跑三遍——因子 FP8、因子 FP16、无量化——比较逐层输出范数与路由索引翻转率，若因子 FP8 与 FP16 的范数偏差随层数单调增长，说明二次舍入已进入累积区，此时应把因子升到 FP16 或改为两级中第二级用高精度。残差与归一化必须保持高精度是同一逻辑的延伸：混合精度下若残差通路也降精度，误差经多层放大且无法由单层校验点捕获。工程判断落在校验点的选择上——路由索引翻转率、逐通道最大值溢出计数、因子精度消融的范数漂移，三者构成可观测的失效前兆，比端到端精度指标更早暴露边界。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测前兆</th><th>系统代价</th></tr></thead><tbody><tr><td>路由 logits 量化</td><td>top-k 索引翻转率上升、专家负载方差增大</td><td>负载不均导致批调度空转，吞吐下降</td></tr><tr><td>块边界错位</td><td>个别通道最大值溢出计数</td><td>反量化错位，需回退整层精度</td></tr><tr><td>因子二次舍入</td><td>因子 FP8/FP16 消融的范数漂移随层增长</td><td>长上下文累加偏差，校验点缺失难定位</td></tr></tbody></table>\n<h3 id=\"ap-nvfp4-fp8-moe-sec-19\">十九 · 路由分数被量化：翻转不是随机噪声</h3>\n<p>踩坑清单里排第一的，永远是把路由 logits 一并塞进 FP4/FP8 通路。MoE 的 top-k 选择是一个<b>离散决策</b>：logits 经过 softmax 或直接比较大小后取前 k 个专家，量化误差一旦让两个专家的分数次序互换，输出就不是“略有偏差”，而是换了一条完全不同的计算路径。更麻烦的是这种翻转具有样本相关性——边界样本上分数差本就极小，量化噪声足以跨过它；而分数差大的样本纹丝不动。结果是精度塌陷只出现在分布尾部，聚合指标看起来还行，线上却出现个别请求质量骤降。</p>\n<p>机制上要区分两件事：路由分数的<b>计算精度</b>与专家输出的<b>累加精度</b>。前者建议保留 FP32 或 BF16 旁路，即门控网络的矩阵乘可以用低精度，但 logits 的比较与 top-k 排序在高精度域完成；后者在专家内部 GEMM 之后用 FP32 累加器收口。一个可操作的伪代码思路是：</p>\n<div class=\"formula\">$$ \\text{logits} = \\text{cast}_{FP32}(\\text{gate}(x));\\quad \\text{idx} = \\text{topk}(\\text{logits}, k);\\quad y = \\sum_{i \\in \\text{idx}} w_i \\cdot \\text{cast}_{FP32}(\\text{expert}_i(x)) $$</div>\n<p>代价落在哪里？路由 logits 的张量极小（batch × 专家数），保留 FP32 几乎不增加显存，也不改变主 GEMM 的吞吐；真正的代价是<b>多一次 cast 与一次排序的同步点</b>，在连续批处理下这会引入额外的 kernel launch 与调度开销，尤其当 batch 很小、专家数很大时，排序本身可能成为微秒级瓶颈。工程判断是：宁可让门控走一个独立的小 kernel 保持高精度，也不要为了省一次 launch 把它融进量化主路径。</p>\n<p>具体例子：一个 64 专家的 MoE，某 token 的第 3、第 4 专家 logits 相差 0.02，FP8 E4M3 在 $$\\pm 448$$ 范围内对小幅值区间的分辨率有限，量化后两者次序颠倒，原本路由到专家 3 的 token 全被推给专家 4。单看这一 token 的输出误差不大，但整批 token 的专家负载分布随之漂移，All-to-All 的通信量在热点专家上堆积——这正是“量化后路由漂移”条目要展开的连锁反应，此处只需记住：<b>路由分数不进量化通路</b>是硬约束，不是调优项。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-20\">二十 · 块缩放因子与元素布局错位</h3>\n<p>第二类坑比第一类隐蔽得多：缩放因子按错误的张量轴或块边界广播。NVFP4 的两级结构要求每个固定大小元素块（16 或 32 个元素）共享一个 FP8 E4M3 缩放因子，反量化时必须<b>逐块</b>把因子乘回对应元素。若量化时按行切块、反量化时按 128 元素块还原，元素与因子的对应关系就整体错位。</p>\n<p>这类错误的症状很有辨识度：不是整体误差均匀抬升，而是<b>个别通道数值爆炸</b>。因为错位后某个元素乘上了邻块的缩放因子，而邻块的幅值量级可能差一个数量级，于是少数通道出现尖峰，其余通道看起来正常。聚合的 MSE 被尖峰主导，但逐层剖析时又会发现大部分通道“没问题”，极易误判为偶发数值异常而非系统性布局错误。</p>\n<p>检查顺序上，这类问题必须在<b>单算子级别</b>拦截，而不是等到端到端精度回归。做法是构造一个已知分布的合成张量，走一遍量化—反量化往返，逐元素比对原始值与还原值的相对误差；若误差分布出现双峰或长尾尖峰，基本可以判定布局错位。表格化的检查项应包含：块大小是否与 kernel 的 tile 边界对齐、缩放因子的张量形状是否为元素数除以块大小、广播轴是否与量化轴一致。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>错位表现</th><th>拦截手段</th></tr></thead><tbody><tr><td>块大小 vs tile 边界</td><td>跨 tile 元素取错因子</td><td>合成张量往返比对</td></tr><tr><td>因子形状</td><td>广播维度不匹配、静默截断</td><td>shape 断言</td></tr><tr><td>广播轴</td><td>个别通道尖峰</td><td>逐通道误差直方图</td></tr></tbody></table>\n<p>系统代价体现在修复成本而非运行成本：布局错位不会显著改变吞吐，但会让整条量化流水线的可信度归零，回滚时不得不把整层权重退回 FP16 重新校准。块大小 16–32 个元素的选择本身就是缩放开销与精度的折中，一旦选定，kernel 的 tile 划分、因子的存储布局、反量化的向量化宽度全部绑定在这个数字上，任何一处不一致都是错位源。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-21\">二十一 · 缩放因子自身的二次舍入</h3>\n<p>两级量化的第二级是缩放因子，它通常以 FP8 E4M3 存储。坑在于：因子本身被量化一次，随后又在反量化时参与逐元素乘法，等于对同一个数值做了两次舍入。单次乘法的误差可忽略，但在长上下文、多层残差累加的场景下，误差沿深度与序列两个维度累积。</p>\n<p>机制上，设元素真值为 $$x$$，块因子为 $$s$$，量化元素为 $$q$$，还原值为 $$\\hat{x} = \\hat{s} \\cdot q$$，其中 $$\\hat{s}$$ 是 $$s$$ 经 FP8 舍入后的值。误差包含两部分：元素量化误差与因子舍入误差，后者被元素值放大。若因子用 FP8 E5M2 存储，动态范围更大但尾数更短，舍入更粗；用 E4M3 则在范围与精度间取平衡。关键判断是：<b>因子是否参与逐元素乘</b>决定了二次舍入是否可接受——若因子只在块级别参与一次缩放，误差被块内元素平均；若因子被展开成逐元素向量再乘，误差无处平均。</p>\n<div class=\"formula\">$$ \\hat{x} - x = (\\hat{s} - s)\\,q + s\\,(q - x_q) $$</div>\n<p>校验点缺失时这类问题极难定位：端到端精度掉几个点，逐层剖析每层都“差不多”，没有哪一层明显异常。可行的检查顺序是插入<b>分层误差探针</b>——在若干中间层比对 FP32 参考输出与量化输出的相对误差，观察误差是否随层数单调增长；若是，则指向累加型误差而非单点故障。代价是探针本身要求保留一份高精度参考通路，显存与算力开销在调试期可接受，生产期必须摘除。</p>\n<p>具体例子：一个专家权重按 16 元素块量化，因子存 FP8 E4M3，某块因子真值为 0.0031，E4M3 最小正规数约 $$2^{-6}$$，该值落在次正规区间，舍入后相对误差显著放大，块内所有元素被同一比例偏移。单块影响有限，但若这类小块在权重中占比高，整层输出的系统性偏移就会显现。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-22\">二十二 · 残差与归一化的高精度旁路</h3>\n<p>混合精度最常见的结构性错误，是把残差连接与归一化也拉进低精度通路。残差是跨层的信息高速公路，归一化的分母是整层数值尺度的锚点，两者都不该被 FP4/FP8 的块缩放切割。归一化尤其敏感：它要对一个 token 的隐藏维度求均值与方差，若输入已被量化，统计量本身带误差，再除回去等于把误差放大到整个向量。</p>\n<p>机制上应保持一条<b>高精度旁路</b>：主 GEMM 走 NVFP4/FP8，但残差累加在 FP32 或 BF16 域完成，LayerNorm/RMSNorm 的统计量在高精度域计算后再广播。伪代码思路是让量化只作用于 GEMM 的输入操作数，输出立即 cast 回高精度再进入残差：</p>\n<div class=\"formula\">$$ h_{l+1} = \\text{cast}_{BF16}\\big(\\text{GEMM}_{FP4/FP8}(h_l, W_l)\\big) + h_l;\\quad \\text{norm}(h) = \\frac{h - \\mu_{FP32}(h)}{\\sigma_{FP32}(h)} $$</div>\n<p>代价是每次 GEMM 后多一次 cast 与一次残差加法，在 kernel 融合良好的实现里这可以并进 epilogue，几乎不增加显存带宽；但若 cast 与残差被拆成独立 kernel，就会多一轮 HBM 读写，在解码阶段（batch 小、算术强度低）这轮读写可能占总时延的可观比例。工程判断：<b>epilogue 融合是这条旁路能否落地的关键</b>，不能融合时宁可牺牲部分 GEMM 吞吐也要保住高精度残差。</p>\n<p>具体例子：一个 32 层模型，若每层残差都在 FP8 域累加，误差随层数线性叠加；而把残差拉回 BF16 后，误差被限制在单层 GEMM 内，不跨层传播。这正是“误差经多层放大”的典型形态——单层看不出问题，深了才暴露，因此检查顺序必须包含<b>深度方向的误差增长曲线</b>，而不只是单层比对。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-23\">二十三 · 检查顺序与回滚方案</h3>\n<p>把上述坑串成一条可执行的检查链，顺序不能颠倒，因为后一环的故障会掩盖前一环。建议的顺序是：算子级往返比对 → 单层端到端比对 → 路由一致性校验 → 深度误差增长曲线 → 全模型精度回归 → 负载分布与尾延迟观测。前两步拦截布局与因子舍入，第三步拦截路由翻转，第四步拦截残差放大，最后两步才看系统级指标。</p>\n<ul>\n<li><b>算子级</b>：合成张量往返，查块边界与因子形状，成本最低、定位最准。</li>\n<li><b>单层级</b>：固定输入比对 FP32 参考，查二次舍入与 epilogue 融合是否正确。</li>\n<li><b>路由一致性</b>：同一批 token 在高精度与量化通路下的 top-k 索引比对，统计翻转率与翻转样本的分数差分布。</li>\n<li><b>深度曲线</b>：逐层相对误差，判断是否累加型。</li>\n<li><b>系统级</b>：专家负载直方图与 P99 尾延迟，确认无热点堆积。</li>\n</ul>\n<p>回滚方案要按<b>粒度</b>设计，而不是一刀切退回 FP16。第一级回滚是把路由与残差旁路从量化通路中摘出（通常只是配置开关，不改权重）；第二级是把激活侧从 FP8 退回 BF16，权重仍保持 NVFP4，显存收益保留大半；第三级才是整层退回 FP16 并重新校准。粒度化回滚的价值在于：多数故障源于旁路缺失或布局错位，前两级就能覆盖，不必付出权重重新校准的时间成本。</p>\n<p>系统代价要算清楚：整层回滚到 FP16 意味着该层权重显存回到 FP16 水平，NVFP4 配合 FP8 块缩放把权重压至 FP16 约四分之一的收益在该层失效；若故障集中在少数专家，按专家粒度回滚可以把显存损失限制在局部——这正是“缩放因子随专家粒度独立、误差不跨专家传播”这一结构带来的运维红利。回滚触发条件应写成可观测的判据：路由翻转率超过设定阈值、逐层误差曲线出现拐点、某专家负载偏离均值超过容量因子允许范围，三者任一触发即降级，而不是等端到端指标跌破再人工排查。</p>\n<p>最后一个工程判断落在<b>校准与回滚的耦合</b>上：回滚到高精度后重新校准，校准数据必须覆盖触发故障的那批分布——否则重新量化后同样的边界样本会再次翻转。把故障样本回流进校准管线，是让回滚不止于止血、而能真正收敛的机制。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-24\">二十四 · 失效边界与回滚：从错位反量化到路由翻转的排查顺序</h3>\n<p>NVFP4/FP8 混合精度推理的失效很少表现为“整体误差略大”，而是集中在三类可定位的边界条件上。第一类是<strong>布局错位</strong>：块缩放因子按行量化，反量化却按 128 元素块广播，元素与缩放因子不再一一对应，症状是个别通道数值爆炸而非均匀劣化——这类错误不会在平均 loss 上暴露，只会在逐通道 max-abs 上跳变。第二类是<strong>二次舍入</strong>：两级量化中缩放因子本身以低精度存储又参与逐元素乘，长上下文累加时误差单调累积，校验点缺失时无法区分是缩放因子误差还是元素量化误差。第三类是<strong>路由翻转</strong>：把路由 logits 一并降到 FP4/FP8，top-k 在边界样本上换专家，负载分布漂移与精度塌陷同时出现。三者的共同点是：误差传播路径与量化对象不匹配，而校准集上的平均指标对此不敏感。</p>\n<p>检查顺序应按“代价从低到高、定位从粗到细”排列，而不是按精度损失大小排列。先用单层替换法把某一层临时回退到 FP16/BF16，观察输出是否恢复——若恢复则锁定该层，若不变则问题在更上游的路由或归一化旁路。再做<strong>逐通道残差检查</strong>：对反量化后的权重与原始高精度权重求逐通道相对误差，公式为</p>\n<div class=\"formula\">$$ e_c = \\frac{\\lVert W_c - \\hat{W}_c \\rVert_2}{\\lVert W_c \\rVert_2},\\quad \\max_c e_c \\gg \\text{median}_c e_c $$</div>\n<p>当最大通道误差远高于中位数时，几乎必然是块边界或张量轴广播错误，而非量化噪声。第三步才检查路由：固定输入，比较 FP32 路由分数与量化后分数的 top-k 集合是否一致，统计翻转率；翻转集中在分数间距小于量化步长的样本上，说明需要为路由保留 FP32/BF16 旁路。最后检查累加器：专家输出若未用 FP32 累加，FP4/FP8 乘积的舍入会在长序列上叠加，表现为随上下文长度增长的漂移。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>最可能原因</th><th>首查项</th><th>系统代价</th></tr></thead><tbody><tr><td>个别通道数值爆炸</td><td>缩放因子轴/块边界错位</td><td>逐通道相对误差 e_c</td><td>反量化额外缩放因子读写，带宽上升</td></tr><tr><td>长上下文缓慢漂移</td><td>缩放因子低精度二次舍入</td><td>累加器精度与校验点</td><td>FP32 累加占用寄存器与 TMEM 带宽</td></tr><tr><td>负载不均、精度塌陷</td><td>路由 logits 被量化</td><td>top-k 集合翻转率</td><td>路由高精度旁路增加少量算力与延迟</td></tr></tbody></table>\n<p>回滚方案必须是<strong>分层可逆</strong>的，而不是整模型开关。工程上把量化配置做成按专家、按张量轴的独立开关：MoE 权重按专家分块量化时缩放因子随专家粒度独立，误差不跨专家传播，因此单个专家回退到 FP8 或 BF16 不会污染其他专家，回滚代价仅为该专家的显存与带宽回升。激活侧 per-tensor 缩放实现简单、一次乘加即可还原，但不同专家激活幅值差异大时小幅值专家信噪比骤降，回滚应优先切到 per-block 而非直接回 FP16。需要守住的高精度旁路只有两条：路由分数用 FP32/BF16 计算，残差与归一化保持高精度；其余路径可按块大小 16–32 元素在缩放开销与精度间折中。判断是否回滚的准则不是平均精度，而是翻转率与逐通道误差是否越过校准集上设定的边界——越过即回滚该粒度，未越过则保留 FP4 权重配合 FP8 块缩放的显存收益。</p>\n<h3 id=\"ap-nvfp4-fp8-moe-sec-25\">二十五 · 上游依赖：块缩放布局与校准数据是硬约束</h3>\n<p>本条目在全书中的位置，首先由它依赖什么决定。NVFP4/FP8 权重激活不是孤立格式，它的上游是两条链：一条是<strong>张量布局链</strong>，一条是<strong>校准数据链</strong>。前者决定块缩放因子能否被正确反量化，后者决定 per-block 缩放因子的数值是否落在 FP8 E4M3 的可表示范围内。上游任何一环松动，下游所有推理优化都建立在错误的数值基座上。</p>\n<p>张量布局链的具体机制是：NVFP4 以固定大小元素块（16 或 32 个元素）共享一个 FP8 E4M3 缩放因子，块内元素用 FP4 尾数与指数表示。这意味着权重的物理排布必须与量化时的分块轴一致。若量化阶段按输出通道分块，而推理内核按 128 元素连续块反量化，元素与缩放因子就会错位——失败模式不是整体误差上升，而是个别通道数值爆炸。这类错误在 MoE 权重上尤其隐蔽，因为专家权重按专家粒度独立分块，缩放因子随专家边界重置，跨专家的块边界天然不对齐。上游的布局契约必须写成内核可校验的元数据：块大小、分块轴、专家边界偏移，三者缺一不可。</p>\n<p>校准数据链的约束更直接。FP8 E4M3 的动态范围约 <span>$$\\pm 448$$</span>，最小正规数约 <span>$$2^{-6}$$</span>，激活必须靠 per-tensor 或 per-block 缩放压入该范围。MoE 中不同专家的激活幅值差异大，per-tensor 缩放会让小幅值专家的量化信噪比骤降，因此校准数据必须覆盖每个专家的真实激活分布，而不是全局混采。校准不足的直接代价是精度，但工程代价同样明确：per-block 缩放意味着激活侧要额外读写缩放因子，激活显存相对 FP16 减半的同时，缩放因子带来额外带宽开销，在解码阶段的带宽受限内核上这笔开销会被放大。</p>\n<p>具体例子：一个 8 专家 MoE 层，若校准集只覆盖路由最频繁的两个专家，其余专家的 per-block 缩放因子会被压到接近 FP8 最小正规数附近，反量化后权重幅值系统性偏小，专家输出整体偏低。这不是随机噪声，而是可复现的偏置，且只在冷门专家被路由命中时暴露——上游校准缺口直接转化为下游尾延迟样本上的精度塌陷。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-26\">二十六 · 下游影响：路由分数保护与累加精度决定系统行为</h3>\n<p>本条目向下游输出的不是一组权重，而是一份<strong>精度契约</strong>：哪些张量允许降到 FP4/FP8，哪些必须保留高精度旁路。下游受影响最深的是路由与累加两处，它们分别对应负载分布与数值稳定性。</p>\n<p>路由侧的下游影响是负载分布。路由 logits 若被量化到 FP4/FP8，top-k 选择会在边界样本上翻转。翻转的代价不是单个 token 的精度损失，而是专家负载分布漂移：原本应落到专家 A 的 token 被推给专家 B，在专家并行下直接改变 All-to-All 的通信量与各专家的排队长度。工程判断很明确——路由分数保留 FP32 或 BF16 计算，量化只作用于专家权重与专家内激活。这条旁路是下游调度器稳定性的前提，容量因子与丢弃代价的估算都建立在路由分布可预测之上，路由漂移会让容量规划失效。</p>\n<p>累加侧的下游影响是数值稳定性。FP4/FP8 乘积在长上下文累加中会累积舍入误差，专家输出必须用 FP32 累加器。伪代码思路是：块内 FP4 元素与 FP8 缩放因子相乘得到反量化值，进入 FP32 累加器；残差连接与归一化保持高精度，误差不经过多层放大。两级量化中若缩放因子本身用低精度存储又参与逐元素乘，二次舍入会在累加中叠加，校验点缺失时难以定位——这正是下游剖析工具链需要观测的指标。</p>\n<p>系统代价可以定性给出：路由保留高精度意味着路由 GEMM 不能用最低精度内核，吞吐略低于全量化路径，但换来的是负载可预测；FP32 累加器意味着寄存器压力与累加带宽上升，在 tcgen05 与 TMEM 路径上影响内核的占用率与流水深度。具体例子：分离式预填/解码场景中，预填阶段激活幅值大、解码阶段激活幅值小，若两阶段共用一套 per-tensor 缩放，解码阶段的量化信噪比会明显劣化；按阶段切换 per-block 缩放或独立校准，是下游框架选型时必须确认的能力。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-27\">二十七 · 横向关系：与分组 GEMM、KV 压缩、通信条目的接口</h3>\n<p>本条目与同模块其他条目不是并列关系，而是<strong>数值底座与上层机制</strong>的关系。分组 GEMM 与 tcgen05 条目讲的是如何把多专家的矩阵乘拼成一次内核发射，本条目决定这些 GEMM 的输入位宽与缩放因子布局；分组 GEMM 的 tile 划分必须与块缩放边界对齐，否则每个 tile 的反量化都要处理跨块元素，内核复杂度与带宽开销同时上升。</p>\n<p>与 MoE 场景 KV 压缩条目的接口在激活侧：KV 压缩通常把 KV 降到 FP8，而本条目管的是权重与专家内激活。两者共享 FP8 E4M3 的动态范围约束，但缩放粒度选择不同——KV 按头或按 token 分块，权重按专家与通道分块。接口处的一致性要求是：同一层内 KV 与激活的缩放因子类型统一，避免混合精度下反量化路径分叉。</p>\n<p>与专家并行及 All-to-All 条目的接口在路由分数：All-to-All 的 token 分发量由路由结果决定，路由分数保留高精度是本条目对通信条目的上游承诺。与量化后路由漂移条目的关系更直接——路由漂移的根因之一就是把路由 logits 一并量化，本条目给出的保护性高精度旁路正是该问题的预防机制。与通信计算死锁条目的关系在混合精度内核的同步点：两级量化的反量化与 GEMM 若分属不同流，缩放因子读写与累加的顺序必须显式约束，否则精度校验点与通信重叠会互相干扰。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-28\">二十八 · 在全书中的位置：精度层的入口与出口</h3>\n<p>放到全书结构里看，本条目属于<strong>算子与数值精度</strong>这一层，是精度层的入口与出口。入口方向，它承接硬件能力：Blackwell 的 tcgen05、TMEM、2-SM MMA 决定了 FP4/FP8 的吞吐上限与累加器布局，本条目把这些硬件约束翻译成格式选择与缩放粒度。出口方向，它向显存与 KV cache、批调度、投机解码、分离式预填/解码各层输出精度契约：显存账本里权重占 FP16 约四分之一、激活占 FP16 一半，这两个系数直接进入容量规划；批调度依赖路由分布稳定；投机解码的草稿模型与验证模型若精度不一致，接受率会被数值差异侵蚀。</p>\n<p>表格可以固定这层关系：</p>\n<table class=\"mini\"><thead><tr><th>下游层</th><th>本条目输出的契约</th><th>被破坏时的代价</th></tr></thead><tbody><tr><td>显存与 KV cache</td><td>权重 FP4 + FP8 块缩放、激活 FP8 的显存系数</td><td>容量规划偏保守或超卖</td></tr><tr><td>批调度与连续批处理</td><td>路由分数高精度、负载分布可预测</td><td>容量因子失效、尾延迟抬升</td></tr><tr><td>分离式预填/解码</td><td>按阶段切换缩放粒度</td><td>解码阶段信噪比劣化</td></tr><tr><td>剖析工具链</td><td>缩放因子元数据与校验点</td><td>错位故障无法定位</td></tr></tbody></table>\n<p>具体例子：容量规划时若把权重显存按 FP16 估算，会在 NVL72 机架级部署上系统性高估单卡可承载的专家数，导致并行切分过细、All-to-All 跳数增加；反之若忽略缩放因子与 FP32 累加器的额外开销，又会低估。本条目给出的不是单一数字，而是一套可核对的账本结构。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-29\">二十九 · 工程判断：把关系写成可执行的校验点</h3>\n<p>关系条目若只停留在“谁依赖谁”，对工程没有价值。可执行的形式是<strong>校验点</strong>：每个上游依赖与下游影响都对应一个可在推理系统中观测的量。布局链的校验点是反量化后逐通道的最大绝对值与量化前的比值，偏离阈值即说明块边界错位；校准链的校验点是每个专家缩放因子的分布直方图，落在 FP8 最小正规数附近的专家需要补采校准数据。</p>\n<p>下游的校验点分两类：路由侧统计 top-k 选择在量化前后的翻转率，翻转率与负载分布的偏移量直接关联；累加侧在长上下文样本上比对 FP32 累加与低精度累加的专家输出偏差，偏差随序列长度增长即说明二次舍入在累积。这些校验点应嵌入剖析工具链，而不是事后离线分析——在线校验才能在连续批处理中捕捉到只在特定批次组合下出现的漂移。</p>\n<p>最终落到一个具体机制上：混合精度内核的边界应当以“是否参与路由决策”和“是否跨层累加”划线。参与路由决策的张量保留 FP32/BF16，跨层累加的通路保留 FP32 累加器，其余张量才允许进入 NVFP4/FP8 的快路径。这条划线规则把本条目与全书其他条目的关系固化为内核级的精度分区，上游的块缩放布局与校准数据在这一分区内被消费，下游的显存账本、调度稳定性与尾延迟都从这一分区获得可预测的输入。</p>\n\n<h3 id=\"ap-nvfp4-fp8-moe-sec-30\">三十 · 边界条件：这套精度方案在什么情况下会失效</h3>\n<p>本方案的上游依赖是显存与带宽预算模型：只有当权重被压到 FP16 的四分之一、激活减半之后，KV cache 与专家并行的布局才有腾挪空间；下游影响则直接落在批调度与 SLO 上——精度选择改变了单 token 的显存占用与反量化开销，进而改变可承载的并发批大小。因此它不是一个孤立的数值格式选项，而是容量规划的前置输入。失效的第一类条件是路由路径被一并降精度：把路由 logits 量化到 FP4/FP8 后，top-k 选择在边界样本上翻转，专家负载分布漂移，此时即便专家输出本身精度尚可，整体吞吐也会因负载不均而塌陷。工程上必须为路由分数保留 FP32 或 BF16 旁路，这条旁路的代价是每层一次小规模高精度矩阵乘，相对专家主体的计算量可忽略，但它是不可省略的系统开销。</p>\n<p>第二类失效来自块缩放因子与元素布局的错位。块大小取 16–32 个元素是缩放开销与精度的折中，但前提是反量化时的块边界与量化时严格一致；若按行量化却按 128 元素块反量化，元素与缩放因子错位，表现为个别通道数值爆炸而非整体误差抬升，这类故障在监控上极难与真实数值溢出区分。第三类失效是两级量化的二次舍入：缩放因子本身以 FP8 存储又参与逐元素乘，舍入误差在长上下文累加中累积，若校验点缺失则无法定位是哪一级引入的偏差。设元素 $$x$$、块缩放 $$s$$、FP4 量化值 $$q$$，还原值为 $$\\hat{x}=s\\cdot q$$，则相对误差上界近似为</p>\n<div class=\"formula\">$$\\left|\\frac{\\hat{x}-x}{x}\\right|\\le \\epsilon_{q}+\\epsilon_{s}+\\epsilon_{q}\\epsilon_{s}$$</div>\n<p>其中 $$\\epsilon_{q}$$ 为 FP4 尾数量化误差，$$\\epsilon_{s}$$ 为缩放因子存储误差；两项相乘项说明低精度缩放因子会把误差从可加变为可乘，这正是二次舍入难以用单点校验发现的原因。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测症状</th><th>系统代价</th></tr></thead><tbody><tr><td>路由分数降精度</td><td>top-k 翻转、专家负载漂移</td><td>吞吐抖动，尾延迟抬升</td></tr><tr><td>块边界错位</td><td>个别通道数值爆炸</td><td>需回滚精度配置，重跑校准</td></tr><tr><td>缩放因子低精度</td><td>长上下文累积偏差</td><td>校验点缺失时定位成本高</td></tr><tr><td>残差/归一化未保高精度</td><td>多层放大后的整体漂移</td><td>精度塌陷，需混合精度旁路</td></tr></tbody></table>\n<p>第四类失效是混合精度下残差连接与归一化未保持高精度，误差经多层放大，单层看似合格但端到端不可用。这决定了本方案在全书中的位置：它是显存与带宽章节的输入，是批调度章节的约束，也是数值稳定性校验点的来源；专家输出累加必须用 FP32 累加器，否则 FP4/FP8 乘积的舍入会在归约中叠加。工程判断是：把高精度旁路（路由、残差、归一化、累加器）视为不可压缩的固定成本，只在权重与专家激活主体上做块级两级量化，并按专家粒度独立缩放因子以阻断跨专家误差传播——一旦越界压缩旁路，节省的显存会被负载不均与精度回滚的成本抵消。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-nvfp4-fp8-moe\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>说明 NVFP4 的块级缩放与两级量化在 MoE 权重上的误差传播、FP8 E4M3 激活的动态范围与 per…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-nvfp4-fp8-moe · 共 5 个片段</p>\n"},{"id":"ap-kv-cache-moe","title":"MoE场景KV压缩","summary":"讨论 MoE 模型中 KV cache 与专家权重显存的竞争关系，说明 MLA/GQA、量化 KV、分页管理与前缀共享在长上下文下的收益边界，以及在 GB200 NVL72 统一显存池中跨节点 KV 放置的访问代价。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-1\">一 · 条目的边界：KV 压缩在 MoE 推理里到底指什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-2\">二 · 分类维度一：注意力结构决定每 token KV 的基线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-3\">三 · 分类维度二：量化位宽与缩放粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-4\">四 · 分类维度三：分页粒度与前缀共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-5\">五 · 分类维度四：放置层级与跨节点访问代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-6\">六 · 与相邻概念的区分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-7\">七 · 边界条件与失效面：这条条目管什么、不管什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-8\">八 · 速查表的字段口径与填写规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-9\">九 · 阈值列的三种口径：容量、带宽、命中率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-10\">十 · 放置层级与跨节点访问代价的对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-11\">十一 · 共享策略与页大小的耦合填写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-12\">十二 · 量化格式列的精度护栏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-13\">十三 · 表的使用纪律与失效判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-14\">十四 · 先定“每 token KV 字节”这条基线，再谈阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-15\">十五 · FP8 与 FP4 的可用性判据：缩放粒度决定成败</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-16\">十六 · 页大小的两端代价与命中率门槛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-17\">十七 · 放置分层：用访问热度而非容量决定冷热</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-18\">十八 · 阈值表怎么落地成一次测量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-19\">十九 · 阈值不是拍脑袋：把“该不该压、压到哪一层”变成可测的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-20\">二十 · 踩坑清单：五类高频失效及其机理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-21\">二十一 · 检查顺序：从显存账本到访存路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-22\">二十二 · 前缀共享的引用计数与写时复制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-23\">二十三 · 量化缩放的粒度与饱和检测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-24\">二十四 · 回滚方案：分级降级而非一刀切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-25\">二十五 · 失效边界与上线前检查顺序：从“能跑”到“敢开”的七道闸</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-26\">二十六 · 上游依赖：注意力结构与量化格式决定了下游一切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-27\">二十七 · 上游依赖：专家权重换入与 KV 增长争夺同一显存池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-28\">二十八 · 下游影响：分页与前缀共享的收益边界被上游命中率锁定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-29\">二十九 · 下游影响：跨节点放置把压缩收益转化为 fabric 带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-30\">三十 · 在全书中的位置：连接注意力选型、量化、并行与框架四条线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-kv-cache-moe-sec-31\">三十一 · 接口约定：本条目向上下游交付什么</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-kv-cache-moe\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：MoE场景KV压缩</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">讨论 MoE 模型中 KV cache 与专家权重显存的竞争关系，说</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">明 MLA…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-kv-cache-moe-sec-1\">一 · 条目的边界：KV 压缩在 MoE 推理里到底指什么</h3>\n<p>本条目讨论的对象是 <strong>MoE 模型推理过程中，KV cache 所占显存与专家权重所占显存之间的竞争关系，以及为缓解这一竞争而对 KV 采取的压缩、组织与放置手段</strong>。它既不是通用的“长上下文 KV 优化”综述，也不是“专家权重压缩”条目。判据很明确：一项技术若只改变专家权重的字节数而不改变 KV 的字节数或访问模式，归专家量化条目；若只改变 KV 的字节数而不涉及与专家权重的显存争抢，则属于稠密模型 KV 优化，不在本条目核心范围内。MoE 的特殊性在于，专家权重不是常驻的固定集合——激活专家按 token 路由结果动态换入，KV 却随上下文长度与并发批线性增长，两者在同一显存池里此消彼长。因此本条目关心的压缩手段必须同时回答两个问题：省下多少 KV 字节，以及省下的空间是否真的能被专家换入利用。</p>\n<p>形式化地，设单请求上下文长度为 $L$、并发批为 $B$、每 token KV 字节为 $k$、激活专家权重驻留量为 $W_{\\text{act}}$、常驻非专家参数为 $W_{\\text{fix}}$，则显存约束可写成：</p>\n<div class=\"formula\">$$k \\cdot L \\cdot B + W_{\\text{act}} + W_{\\text{fix}} \\le M_{\\text{pool}}$$</div>\n<p>压缩的直接作用是压低 $k$，间接作用是让 $W_{\\text{act}}$ 有更大预算容纳更多激活专家、减少换入换出。这个不等式是本条目所有分类维度背后的同一根轴：任何压缩手段都在改动 $k$、$L\\cdot B$ 的有效上限，或 $M_{\\text{pool}}$ 的可用边界（例如把冷 KV 移出 HBM）。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-2\">二 · 分类维度一：注意力结构决定每 token KV 的基线</h3>\n<p>第一个维度是注意力结构，它决定 $k$ 的基线量级与访存图形态。MHA 每个 KV 头独立保存，$k$ 最大；GQA 让一组查询头共享同一对 KV 头，头数下降直接线性压低 $k$，但注意力计算图基本不变，只是 KV 读取的并行度变窄；MLA 把 KV 压缩为低秩潜向量，缓存的是潜向量而非完整的 K/V，$k$ 显著下降，代价是注意力计算图被改写——解码时需要先上投影还原 K/V 或在与潜向量空间等价的形式下做吸收式矩阵乘，访存模式从“按头读连续块”变为“读潜向量再做投影”。这三者对 MoE 的意义不同：GQA 省下的是纯容量，访存模式友好，适合与分页管理直接叠加；MLA 省得更多，但改变了注意力的算子形态，与 tcgen05 上的 MMA 切分、TMEM 占用需要重新对齐。分类时不能只写“每 token KV 字节”一列，必须同时标注注意力计算图是否被改写，否则压缩收益会在算子层面被抵消。</p>\n<p>工程代价的具体体现：GQA 在解码步中每个 KV 头的读取被更多查询头复用，单次读取摊薄到更多计算上，属于带宽友好型压缩；MLA 的潜向量读取次数少但每次伴随投影，若投影未被吸收进权重则引入额外 MMA，解码步时延不一定随 $k$ 下降而同比例下降。一个典型例子是长上下文、高并发的 MoE 服务：GQA 把 KV 头数从每层数十个降到个位数后，KV 容量下降使批上限提升，吞吐受益直接；而 MLA 在同样容量收益下需要确认解码 kernel 是否已按吸收形式实现，否则省下的显存换不来时延。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-3\">三 · 分类维度二：量化位宽与缩放粒度</h3>\n<p>第二个维度是 KV 量化位宽，FP8、FP4、INT8 三档。位宽决定 $k$ 的乘性因子，缩放粒度决定精度是否守得住。领域经验是 FP8 KV 可近似减半 KV 显存且精度损失可控，这是当前工程默认档；FP4 KV 的收益更大，但必须配合 per-head 或 per-page 缩放，并保留高精度 softmax 统计，否则注意力分数失真。这里的关键区分是“位宽”与“缩放粒度”必须作为两列分别记录：同为 FP4，per-tensor 缩放会在长上下文尾部 token 幅值异常时饱和，per-page 缩放则把异常幅值限制在单页内。</p>\n<p>量化对 MoE 的额外含义在于它与专家换入的耦合：KV 量化省下的显存若被用于提高激活专家驻留量，路由倾斜时的换入抖动会下降；但若量化 kernel 与分组 GEMM 争用同一批 SM，解码步时延可能上升。因此本条目把量化视为“容量—带宽—精度”三向权衡，而不是单纯的压缩比。失败模式很具体：按整层 per-tensor 选择缩放，长上下文尾部 token 幅值异常时量化饱和，注意力分数失真——这类失真在 MoE 上会被路由放大，因为注意力输出进入路由打分，分数偏差可能改变专家选择。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-4\">四 · 分类维度三：分页粒度与前缀共享</h3>\n<p>第三个维度是分页粒度与共享策略。分页管理把 KV 切成固定页并按需分配，前缀共享让相同系统提示的请求复用同一批物理页，二者在长上下文下同时降低碎片与重复存储。收益边界取决于两个量：前缀命中率与页大小。页过大浪费尾部空间，页过小元数据与查表开销上升；材料未给出具体页大小阈值，工程上需按实际序列长度分布实测。前缀共享命中率低于一定比例时，管理开销可能抵消收益，同样需按实际命中率实测而非套用固定值。</p>\n<p>与 MoE 的耦合点在于引用计数与写时复制：共享物理页被并发请求同时写入或回收时，缺少引用计数与写时复制会导致 KV 内容被污染或提前释放。这在 MoE 上尤其危险，因为不同请求可能路由到不同专家，但共享的前缀页是同一份注意力上下文，污染会跨请求传播。分类表应把“共享策略”与“页大小”并列，并注明共享页的生命周期管理是否具备写时复制。代价方面，前缀共享降低的是重复存储量，对解码步时延的直接影响小，但对批上限的提升是间接的——省下的页让更多请求进入批，吞吐受益，而单步时延取决于页表查表开销，页过小时这部分开销会显现。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-5\">五 · 分类维度四：放置层级与跨节点访问代价</h3>\n<p>第四个维度是放置位置：HBM、NVLink 跨节点统一显存池、CPU 卸载。这一维度只在 GB200 NVL72 这类统一显存池形态下才有完整意义。跨节点 KV 放置的访问代价取决于链路：同机架 NVLink 域内访问延迟与带宽优于跨机架 IB。分层放置的策略是把热 KV 页放在本地 HBM、冷页放在远端池，以降低平均访问代价；但远端页的每次注意力读取都要经过 fabric，长上下文下带宽成为瓶颈。分类表因此必须含“跨节点访问代价”一列，且该列不是常数——它随页的热度分布与链路类型变化。</p>\n<p>失败模式在此维度最典型：把 KV 页放到远端统一显存池却未按访问热度分层，注意力读取频繁跨 fabric，解码步时延被远端带宽拖垮。判断依据是解码步中远端页读取次数占总读取次数的比例，以及这些读取是否与专家权重的 All-to-All 通信争用同一 fabric 带宽。MoE 的专家并行已经把 All-to-All 压在 fabric 上，KV 远端读取与之叠加会形成带宽竞争，这是本条目区别于稠密模型 KV 放置的核心代价项。工程判断落在具体机制上：远端池适合承载低命中率的长尾上下文页，而系统提示前缀这类高复用页应留在本地 HBM，因为它们的读取频次由并发批决定而非由序列位置决定。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-6\">六 · 与相邻概念的区分</h3>\n<p>需要划清的边界有四条。其一，与专家权重量化：后者改变 $W_{\\text{act}}$ 的字节数，本条目改变 $k$ 或 $M_{\\text{pool}}$ 的可用边界，二者在显存预算上互补但优化对象不同。其二，与容量因子和丢弃代价：容量因子调节的是激活专家驻留量与丢弃率，属于调度侧；本条目通过压缩 KV 为容量因子腾出预算，属于容量侧，二者通过第一节的不等式耦合。其三，与分离式预填/解码：后者把预填与解码放到不同资源池，改变的是 $L\\cdot B$ 在时间上的分布；本条目改变的是单位 token 的 KV 成本，两者可叠加但收益来源不同。其四，与路由倾斜尾延迟：路由倾斜造成专家换入抖动，KV 压缩通过释放显存降低抖动幅度，但抖动的主因仍在路由分布，不能把尾延迟归因于 KV 压缩。</p>\n<p>分类的落地形式是一张速查表，列固定为：结构、每 token KV 字节、量化格式、页大小、共享策略、放置层级、跨节点访问代价。七列缺一不可，因为任何一行都同时被注意力结构、量化、分页与放置四个维度约束，只填其中两三列的分类在工程上无法直接用于容量规划。一个具体例子：一行记录为“GQA / FP8 / 中等页 / 前缀共享开启 / 本地 HBM 加热页远端池 / 同机架 NVLink 优先”，这行信息足以让容量规划者估算批上限与远端读取占比，而只写“GQA + FP8”则无法回答远端带宽是否成为瓶颈。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-7\">七 · 边界条件与失效面：这条条目管什么、不管什么</h3>\n<p>本条目讨论的是 MoE 推理中 KV cache 与专家权重对同一显存池的竞争关系，以及 MLA/GQA、KV 量化、分页管理与前缀共享在长上下文下的收益边界，外加 GB200 NVL72 统一显存池中跨节点 KV 放置的访问代价。它不覆盖专家路由算法本身、专家并行切分策略，也不覆盖注意力核函数实现细节——那些属于算子与并行章节。与相邻概念的区别在于：KV 量化条目只回答“每 token KV 字节如何下降”，而本条目必须同时回答“下降之后注意力计算图与访存模式如何改变、省下的字节是否被专家权重换入吃掉”。因此判断这条方案是否适用，先看两个条件：上下文长度与并发批是否使 KV 成为显存主导项，以及激活专家数是否使权重换入成为持续带宽事件。二者同时成立时，KV 压缩的收益才会被专家权重挤占所放大；若专家权重常驻、KV 占比很低，压缩只降低带宽不改变容量格局。</p>\n<p>失效条件集中在三处。其一，KV 页放到远端统一显存池却未按访问热度分层，解码步每次注意力读取都跨 fabric，时延被远端带宽拖垮——可用一个粗略代价式判断分层是否必要：</p>\n<div class=\"formula\">$$T_{step} \\approx T_{local} + h \\cdot \\frac{B_{kv}}{BW_{fabric}}$$</div>\n<p>其中 $h$ 为落在远端池的 KV 字节占比，$B_{kv}$ 为单步需读取的 KV 字节，$BW_{fabric}$ 为跨节点有效带宽。$h$ 稍大便使第二项压过本地项，此时应把热页钉在本地 HBM、冷页外放。其二，前缀共享的物理页被并发请求同时写入或回收，缺少引用计数与写时复制，KV 内容被污染或提前释放，表现为输出错乱而非性能下降，属正确性失效。其三，量化缩放按整层 per-tensor 选择，长上下文尾部 token 幅值异常时饱和，注意力分数失真；FP4 KV 必须配 per-head 或 per-page 缩放并保留高精度 softmax 统计。前缀共享命中率低于一定比例时，管理开销可能抵消收益，材料未给统一阈值，须按实际命中率实测。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>取值</th><th>对本条目的影响</th></tr></thead><tbody><tr><td>注意力结构</td><td>MHA / GQA / MLA</td><td>决定每 token KV 字节与访存模式</td></tr><tr><td>量化位宽</td><td>FP8 / FP4 / INT8</td><td>FP8 近似减半且损失可控；FP4 需细粒度缩放</td></tr><tr><td>分页粒度</td><td>页大小、是否前缀共享</td><td>页过大浪费尾部，页过小元数据开销上升</td></tr><tr><td>放置层级</td><td>HBM / 跨节点池 / CPU 卸载</td><td>远端页每次读取过 fabric，长上下文带宽成瓶颈</td></tr></tbody></table>\n<p>系统代价必须按维度合并计算，而非单看 KV 字节：GQA 降低头数减少 KV 字节，但同时改变注意力计算图的并行度与访存合并方式；MLA 压成低秩潜向量后每 token 字节下降，却把部分计算移入投影，解码步的算力与带宽配比随之变化。工程判断落在速查表的“跨节点访问代价”一列：只有当远端页占比与 fabric 带宽满足 $h \\cdot B_{kv} / BW_{fabric}$ 小于本地读取时间的一个可接受份额时，统一显存池的容量收益才不被时延吞掉；否则应优先做本地分层与前缀命中率优化，再谈跨节点放置。</p>\n<h3 id=\"ap-kv-cache-moe-sec-8\">八 · 速查表的字段口径与填写规则</h3>\n<p>这张表不是参数清单，而是决策卡：每一行对应一个可落地的 KV 配置方案，列与列之间存在强约束关系——填错一列，其余列的最优取值随之漂移。字段定义必须固定口径，否则跨团队对齐时会出现“同名不同义”。结构列填注意力形态（MHA/GQA/MLA），它决定每 token KV 字节的基数；量化格式列填实际存储位宽（FP8/FP4/INT8）与缩放粒度（per-tensor/per-head/per-page），二者不可拆开填写，因为 FP4 若不带 per-head 或 per-page 缩放，长上下文尾部幅值异常会直接导致量化饱和；页大小列填分页管理的物理页 token 容量，它与前缀共享策略列耦合：共享粒度不能细于页，页过大则共享收益被尾部浪费吃掉；放置层级列填 HBM、NVLink 域内统一显存池、跨机架远端池或 CPU 卸载，跨节点访问代价列则填该层级的定性代价等级与瓶颈类型（延迟敏感还是带宽敏感）。填写顺序建议自左向右：先定结构与量化，再定页大小与共享，最后定放置——因为放置决策的收益完全取决于前三列产生的每 token 字节与访问频次。</p>\n<p>每 token KV 字节的计算口径必须写死在表头注释里，避免有人用“每层每头”口径去乘错维度。对 GQA，设层数 $L$、KV 头数 $H_{kv}$、头维 $d$、每元素字节 $b$：</p>\n<div class=\"formula\">$$\\text{Bytes}_{\\text{tok}} = 2 \\cdot L \\cdot H_{kv} \\cdot d \\cdot b$$</div>\n<p>系数 2 来自 K 与 V 两份。MLA 则把 KV 压成低秩潜向量，口径变为潜向量维度 $d_c$ 与解耦的 RoPE 分量之和，公式形态相同但 $H_{kv}$ 退化为 1、$d$ 替换为潜维，因此字节数显著下降，代价是注意力计算图从标准 QKV 投影变为先解压再注意，访存模式随之改变。举例：一个 GQA 配置若 $L=60$、$H_{kv}=8$、$d=128$、$b=1$（FP8），单 token 约 120 KB；同样层数与头维改用 MLA 潜维 512 加 RoPE 64，单 token 降到数十 KB 量级，这正是长上下文下 MLA 被选中的直接原因。表里这一列必须由填写者按公式现算，不允许抄别处的数字，因为层数与头数在不同模型上差异极大。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-9\">九 · 阈值列的三种口径：容量、带宽、命中率</h3>\n<p>阈值列最容易写错，因为它同时承载三类互不相同的判据，必须分列或加后缀标注口径。第一类是容量阈值：KV 池与专家权重共享同一显存池，KV 随上下文长度与并发批线性增长，专家权重随激活专家数按需换入，因此容量阈值应写成“KV 占比上限”——当 KV 池占用超过池容量某一比例时，专家换入的可用空间被挤压，换入延迟上升。这个比例没有统一数字，材料明确未给出，表里应填“按实测换入延迟拐点标定”，并附上标定方法：固定批大小扫上下文长度，记录专家换入等待时间随 KV 占用的变化曲线，取曲线斜率突变点。第二类是带宽阈值：远端池的每次注意力读取都要过 fabric，长上下文下带宽成为瓶颈，阈值应写成“远端页读取带宽占 fabric 可用带宽的比例”，超过该比例即应把热页迁回本地 HBM。第三类是命中率阈值：前缀共享命中率低于一定比例时，管理开销（引用计数、写时复制、页表查表）可能抵消收益，材料同样未给数字，表里填“按实际命中率实测”，并注明测法为对照开关前缀共享两组的解码步时延与显存占用。</p>\n<p>三类阈值对应三种不同的系统代价，不能混在一格里。容量阈值失守表现为显存不足触发的专家换入抖动，代价是解码步时延的尾部分布恶化；带宽阈值失守表现为注意力读取被 fabric 拖慢，代价是平均步时延整体抬升；命中率阈值失守表现为管理开销吃掉存储收益，代价是吞吐不升反降。工程上建议在表里为每类阈值加一个“观测指标”列：容量看换入等待时间，带宽看远端读取占比，命中率看共享页复用次数与页表操作耗时。这样阈值不是拍出来的数字，而是可回归的判据。举例：某长上下文服务若前缀命中率很高但页大小选得过大，共享页尾部浪费会推高显存占用，此时命中率阈值看似达标，容量阈值却先失守——表里两列必须同时看，单看一列会得出错误结论。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-10\">十 · 放置层级与跨节点访问代价的对照</h3>\n<p>放置层级列只有四个合法取值，每个取值对应一条明确的代价曲线，表里应把代价写成“瓶颈类型 + 分层建议”而非单一数字。本地 HBM：延迟最低、带宽最高，适合热 KV 页，代价是占用与专家权重共享的池容量。NVLink 域内统一显存池：同机架 NVLink 域内访问延迟与带宽优于跨机架 IB，适合温页，代价是读取要经 fabric 但仍在高带宽域内。跨机架远端池：每次注意力读取都过 IB，长上下文下带宽成为瓶颈，只适合冷页或极长上下文下访问频次极低的页。CPU 卸载：容量大但访问代价最高，仅适合被换出后短期不再读的页。表里跨节点访问代价列应填“延迟敏感/带宽敏感”标签，并配一条分层规则：热页本地、冷页远端，按访问热度周期性迁移。</p>\n<p>分层迁移的判据可以用一个简化的代价模型表达。设页 $i$ 在窗口内的访问次数 $f_i$，本地访问单位代价 $c_l$，远端单位代价 $c_r$，迁移一次代价 $c_m$，则页留在远端优于迁回本地的条件近似为：</p>\n<div class=\"formula\">$$f_i \\cdot (c_r - c_l) &lt; c_m$$</div>\n<p>即访问频次不足以摊薄迁移成本时不要迁。这个不等式在表里不必写出解析式，但应作为“热度阈值”列的填写依据：热度阈值就是 $c_m/(c_r-c_l)$ 的实测值。失败模式在这里非常具体：把 KV 页放到远端统一显存池却未按访问热度分层，注意力读取频繁跨 fabric，解码步时延被远端带宽拖垮。表里若放置层级填了远端池而热度列空着，这张表就是不合格的。举例：GB200 NVL72 统一显存池中，同机架 NVLink 域内与跨机架 IB 的代价差异决定了同一份 KV 页放在哪一层更划算；长上下文解码时每步都要读全部历史 KV，若历史页大量落在跨机架远端池，每步的 fabric 流量随上下文线性增长，带宽瓶颈会在上下文变长后迅速显现。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-11\">十一 · 共享策略与页大小的耦合填写</h3>\n<p>共享策略列填“无共享/前缀共享/前缀共享+写时复制”，页大小列填物理页 token 容量，两列必须成对填写并注明耦合约束：共享粒度不能细于页，因此页大小直接决定共享的最小复用单元。页过大时，相同系统提示的请求虽能复用同一批物理页，但每个请求尾部不满页的空间被浪费，长上下文下这种尾部浪费会累积；页过小时，页表元数据与查表开销上升，前缀共享的引用计数操作频次也随之上升。材料未给出具体页大小阈值，表里应填“按前缀长度分布与尾部浪费实测标定”，标定方法是扫页大小网格，记录显存占用与页表操作耗时两条曲线，取二者之和的最小点。共享策略列还必须标注并发安全要求：前缀共享的物理页被并发请求同时写入或回收时，缺少引用计数与写时复制会导致 KV 内容被污染或提前释放，因此填“前缀共享”就必须同时填“引用计数+COW”，否则该行无效。</p>\n<p>共享收益的边界可以用一个粗略的收益式表达，用于表内“共享策略”列的备注：设前缀命中率为 $h$、共享前缀长度为 $P$、总上下文为 $C$，则共享节省的 KV 存储比例近似为 $h \\cdot P/C$，而管理开销随并发请求数与页表操作次数增长。当 $h$ 低到使节省比例小于管理开销对应的等效损失时，共享不划算——这正是命中率阈值列的来源。举例：固定系统提示很长、请求前缀高度同构的服务，$h$ 高、$P/C$ 大，共享收益明显；而前缀各异、请求短的服务，$h$ 低且 $P/C$ 小，共享页的引用计数与 COW 开销反而拖慢解码步。表里这两列若只填“前缀共享”而不填命中率实测值，读者无法判断该行是否值得照抄。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-12\">十二 · 量化格式列的精度护栏</h3>\n<p>量化格式列不能只填位宽，必须同时填缩放粒度与精度护栏，三者是一组。FP8 KV 可近似减半 KV 显存且精度损失可控，这是领域经验而非材料给出的统一数字，表里应写成“FP8：默认候选，需验证注意力分数分布”。FP4 KV 需 per-head 或 per-page 缩放并配合高精度 softmax 统计，因为 FP4 的动态范围窄，若缩放按整层 per-tensor 选择，长上下文尾部 token 幅值异常时量化饱和，注意力分数失真——这是明确的失败模式，表里应在量化格式列旁加“缩放粒度”子列，禁止填 per-tensor 配 FP4 的组合。INT8 则介于两者之间，缩放粒度选择同样关键。精度护栏列的填法是“验证项清单”：量化后对比注意力分数分布的尾部、对比解码输出与高精度基线的偏差、检查 softmax 统计是否仍用高精度累加。</p>\n<p>量化对放置决策有连锁影响：每 token KV 字节减半后，同样容量池能容纳的上下文与并发翻倍，容量阈值列的标定点随之移动；但量化也改变了访存模式，FP4 解压需要额外的缩放乘法，若解压发生在注意力读取路径上，远端页的 fabric 带宽压力不减而计算开销上升。因此表里量化格式列与放置层级列必须联动复核：把 KV 量化到 FP4 后若仍把页放远端，节省的字节可能被解压开销与 fabric 流量抵消。举例：一个原本因容量不足而把冷页放远端的配置，量化到 FP8 后容量阈值达标，应把原先放远端的页迁回本地，否则等于用带宽换来了本已不需要的容量。表里应有一行备注强制填写者回答：“量化后容量阈值是否已满足？若满足，远端页是否应迁回？”</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-13\">十三 · 表的使用纪律与失效判据</h3>\n<p>这张速查表的使用纪律有三条，写进表头比写进正文更有效。其一，每行必须自洽：结构、量化、页大小、共享、放置五列之间存在约束链，任何一列改动都要重算每 token KV 字节并复核容量与带宽阈值，不允许局部改一格就照用。其二，阈值列必须带观测指标，没有观测指标的阈值视为未标定，不得作为容量规划输入。其三，失败模式列必须显式填写，至少覆盖三条已知失效：远端页未按热度分层导致 fabric 带宽拖垮解码步时延；前缀共享页缺引用计数与 COW 导致内容污染或提前释放；FP4 配 per-tensor 缩放导致长上下文尾部量化饱和。这三条不是警示语，而是表内可勾选的检查项，任一项未勾选则该行标记为“待验证”。</p>\n<p>失效判据本身也应表格化：当解码步时延的尾部随上下文长度超线性增长，优先怀疑远端页带宽瓶颈；当显存占用高于按公式现算的预期，优先怀疑页过大导致的尾部浪费或共享页未正确回收；当注意力输出与高精度基线偏差在长上下文尾部放大，优先怀疑量化缩放粒度选错。工程判断落在具体机制上：这张表的价值不在于给出唯一正确答案，而在于把“结构—量化—分页—共享—放置”这条约束链显式化，使任何一行配置都能被追溯到它依赖的假设与它对应的观测指标；一旦某行的观测指标偏离标定点，该行即失效，必须重新标定而非继续沿用。</p>\n<h3 id=\"ap-kv-cache-moe-sec-14\">十四 · 先定“每 token KV 字节”这条基线，再谈阈值</h3>\n<p>工程上所有 KV 压缩阈值的讨论，都必须锚定在一个可复算的量上：每 token、每层的 KV 字节数。对 GQA，它是 <span class=\"inline-code\">2 × n_kv_heads × d_head × bytes_per_elem</span>；对 MLA，潜向量维度替代了 K/V 头数，字节数按潜向量与解耦的 RoPE 分量计算。这个数字乘以层数、上下文长度、并发批，就是 KV 池的稳态占用，也是它与专家权重争夺同一显存池时的“对手盘”。在 GB200 NVL72 这类统一显存池里，这个乘积还要乘以放置层级系数——本地 HBM 与远端池的每字节访问代价不同，所以字节数本身不足以决定策略，字节数×访问频次才是。</p>\n<p>测量方法很直接：在目标框架里跑一个固定 prompt 长度的合成负载，打开显存分配追踪，把 KV 池的 reserved 与 allocated 分开记录，再除以实际驻留 token 数，得到实测每 token 字节。与解析值对比，偏差超过一个页大小量级就说明分页尾部浪费或前缀共享未生效。这一步不做，后面所有“减半”“压缩比”都是空谈。</p>\n<div class=\"formula\">$$B_{kv} = L \\cdot n_{kv} \\cdot d_{h} \\cdot b \\cdot C \\cdot N_{batch}$$</div>\n<p>其中 L 为层数、b 为每元素字节、C 为上下文长度、N 为并发批。这个式子是容量规划的骨架：任何一项的压缩收益，都要落到这五个因子上才有意义。代价面在于，缩小 b（量化）改变访存模式，缩小 n_kv（GQA/MLA）改变注意力计算图，二者不是等价替换。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-15\">十五 · FP8 与 FP4 的可用性判据：缩放粒度决定成败</h3>\n<p>领域经验是 KV 量化到 FP8 可近似减半 KV 显存且精度损失可控，这是当前最稳的一档。判据不在位宽本身，而在缩放粒度：per-tensor 缩放在长上下文尾部 token 幅值异常时会饱和，注意力分数失真；per-head 或 per-page 缩放能把异常幅值隔离在局部页内。FP4 KV 则必须配 per-head 或 per-page 缩放，并保留高精度 softmax 统计——softmax 的分母与最大值若也用低精度累计，误差会在长上下文上放大。</p>\n<p>测量方法是构造“幅值异常”探针：在 prompt 尾部注入高幅值 token，比较 FP8/FP4 与高精度基线的注意力分数分布尾部，看饱和比例与 top-k 排序翻转率。工程代价上，per-page 缩放意味着每个页多一份缩放元数据，页越小元数据开销占比越高，这与分页粒度的取舍直接耦合。一个具体例子：同一模型在 32K 上下文、批 8 下，per-tensor FP8 与 per-page FP8 的显存占用几乎相同，但前者在尾部 token 上的分数失真会传导到路由之外的下游层，表现为生成质量抖动——这类问题只能靠探针测出来，不能靠位宽推断。</p>\n<table class=\"mini\"><thead><tr><th>量化档</th><th>缩放粒度要求</th><th>主要代价</th><th>验证手段</th></tr></thead><tbody><tr><td>FP8 KV</td><td>per-tensor 可接受，per-page 更稳</td><td>访存字节减半，反量化开销</td><td>尾部幅值探针</td></tr><tr><td>FP4 KV</td><td>必须 per-head 或 per-page</td><td>缩放元数据、softmax 高精度统计</td><td>top-k 排序翻转率</td></tr></tbody></table>\n\n<h3 id=\"ap-kv-cache-moe-sec-16\">十六 · 页大小的两端代价与命中率门槛</h3>\n<p>分页管理把 KV 切成固定页，页过大浪费尾部空间，页过小元数据与查表开销上升。材料未给出具体页大小阈值，因此工程做法是扫一条曲线：固定负载下改变页大小，记录（a）尾部浪费字节占比、（b）页表查表与元数据的每步开销、（c）前缀共享可复用的物理页数。三条曲线的交点就是该负载下的可用区间。注意这条曲线随上下文长度移动——长上下文下尾部浪费的相对占比下降，小页的元数据开销反而成为主项。</p>\n<p>前缀共享的收益边界取决于命中率。命中率低于一定比例时，管理开销（引用计数、写时复制、页表比对）可能抵消收益，需按实际命中率实测。测量方法：在真实流量回放中统计相同系统提示的请求占比与物理页复用率，同时记录开启/关闭前缀共享的每步解码时延。一个具体判断是，若复用率带来的显存节省不足以让并发批提升一档，而每步时延因页表比对上升，则共享在该负载下是负收益。代价面还包括正确性风险：共享物理页被并发请求同时写入或回收，缺少引用计数与写时复制会导致 KV 内容被污染或提前释放——这是必须在压测中专门构造并发写冲突场景来验证的失败模式。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-17\">十七 · 放置分层：用访问热度而非容量决定冷热</h3>\n<p>GB200 NVL72 统一显存池中，跨节点 KV 放置的访问代价取决于链路：同机架 NVLink 域内访问延迟与带宽优于跨机架 IB。把热 KV 页放在本地 HBM、冷页放在远端池可降低平均访问代价，但远端页的每次注意力读取都要经过 fabric，长上下文下带宽成为瓶颈。失败模式很明确：把 KV 页放到远端池却未按访问热度分层，注意力读取频繁跨 fabric，解码步时延被远端带宽拖垮。</p>\n<p>因此阈值不该按“容量水位”定，而该按“每页每步被读取的次数”定。测量方法：给每个 KV 页打访问计数器，统计一个解码窗口内的读取频次分布，取分位数作为冷热分界；再用远端页占比与 fabric 带宽占用做敏感性分析。工程判断是，远端页占比的上限由 fabric 带宽除以注意力读取速率决定，而不是由远端池剩余容量决定。一个具体例子：长上下文解码阶段每步只新增一个 token，但要对全部历史 KV 做注意力读取，远端页比例一旦超过 fabric 能承载的读取带宽，步时延立刻由 fabric 主导，此时增加本地 HBM 容量比增加远端池容量更有效。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-18\">十八 · 阈值表怎么落地成一次测量</h3>\n<p>把上述判据收拢成一次可执行的测量流程：先测每 token KV 字节基线并与解析值对齐；再在目标上下文与批大小下扫页大小曲线，取尾部浪费与元数据开销的平衡点；然后开/关前缀共享，用真实命中率算净收益；接着对 FP8/FP4 做尾部幅值探针与排序翻转率；最后按页访问频次分位定冷热分界，用 fabric 带宽反推远端页占比上限。每一步都产出可回填到容量模型的数字，而不是定性结论。</p>\n<p>代价面贯穿始终：页大小影响元数据与尾部浪费，量化粒度影响精度与反量化开销，共享策略影响正确性与页表开销，放置分层影响 fabric 带宽占用。这些量互相耦合，不能单独调优某一项就宣布收益。工程判断落在最后一步——当远端页占比触及 fabric 带宽上限时，优先把热页迁回本地 HBM 或缩小页粒度以提高本地命中，而不是继续扩容远端池。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-19\">十九 · 阈值不是拍脑袋：把“该不该压、压到哪一层”变成可测的判据</h3>\n<p>这一节只谈边界：什么条件下 MLA/GQA、KV 量化、分页与前缀共享、跨节点放置这四件事从“省”变成“亏”。前提是 MoE 场景下 KV 与专家权重抢同一个池子，因此任何 KV 侧的节省都要换算成“给专家权重腾出的换入空间”与“解码步时延的净变化”，而不是单看 KV 字节数下降。判断一个压缩手段是否值得上线，先固定三个观测量：每 token KV 字节 <span class=\"formula\">$$B_{kv}=2 \\cdot L \\cdot H_{kv} \\cdot d_h \\cdot b_q$$</span>（$L$ 层数、$H_{kv}$ 有效 KV 头数、$d_h$ 头维、$b_q$ 每元素字节），它决定并发上限；解码步注意力读 KV 的实际字节流量，它决定时延；以及专家权重换入的等待时间占比，它决定 MoE 是否被 KV 挤到“算力空转”。三者必须在同一 batch 形状下测，否则阈值不可迁移。</p>\n<p>量化阈值的经验判据是“减半可控、再减半要付代价”。KV 压到 FP8 近似减半 KV 显存且精度损失可控，这是可以默认开启的一档；FP4 KV 不是免费的第二档，它要求 per-head 或 per-page 缩放，并配合高精度 softmax 统计，否则长上下文尾部 token 幅值异常时按整层 per-tensor 选缩放会直接量化饱和，注意力分数失真——这类失效不会在短 prompt 压测里暴露，只在长上下文尾段出现。测量方法：固定并发与输出长度，扫上下文长度 4k/16k/64k/128k，对比 FP8 与 FP4 在长尾位置的注意力分数偏差与任务指标，同时记录缩放粒度从 per-tensor 改到 per-page 后元数据开销的增量。若 per-page 缩放带来的查表与反量化开销吃掉了带宽收益，FP4 就该退回 FP8。</p>\n<p>前缀共享与分页的阈值取决于命中率，材料未给出具体页大小阈值，因此只能实测。判据是：共享收益 ≈ 命中率 × 被复用页的存储与预填节省，管理开销 ≈ 引用计数、写时复制与页表查表的固定成本 × 请求数。命中率低于某个比例时，管理开销可能抵消收益，这个比例必须用真实流量测——把系统提示、few-shot 前缀、多轮历史分别打标，统计各段的物理页复用次数，再看关闭共享后的 TTFT 与显存占用差。页大小的取舍同理：页过大浪费尾部空间，页过小元数据与查表开销上升，扫描 16/32/64/128 token 页在目标上下文分布下的碎片率与页表项数量，取碎片损失与元数据开销之和最小的点。失效条件写死两条：物理页被并发请求同时写入或回收而缺少引用计数与写时复制，会污染 KV 或提前释放；这两条不是概率问题，是必须有的正确性约束。</p>\n<p>跨节点放置的阈值是带宽账，不是容量账。GB200 NVL72 统一显存池里，同机架 NVLink 域内访问延迟与带宽优于跨机架 IB；把热 KV 页放本地 HBM、冷页放远端池能降低平均访问代价，但远端页的每次注意力读取都要过 fabric，长上下文下带宽成为瓶颈。可算的判据：设远端页占比 $f$，单步注意力 KV 流量 $S$，则跨 fabric 流量为 $f \\cdot S$，当 $f \\cdot S$ 逼近 fabric 可用带宽时，解码步时延被远端带宽拖垮——此时应提高本地热页比例或缩短远端页生命周期，而不是继续扩容远端池。典型失效模式是把 KV 页放到远端池却未按访问热度分层，注意力读取频繁跨 fabric。测量方法：按页记录访问频次与最近访问步，做热度分层后对比分层前后的单步时延与 fabric 利用率；同时把专家权重换入流量计入同一 fabric 账本，因为 MoE 的权重换入与远端 KV 读取共享链路，二者叠加才是真实瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>手段</th><th>收益侧观测量</th><th>代价侧观测量</th><th>失效判据</th></tr></thead><tbody><tr><td>FP8 KV</td><td>KV 字节近似减半</td><td>反量化开销、精度偏差</td><td>长尾注意力分数失真</td></tr><tr><td>FP4 KV</td><td>再减半</td><td>per-page 缩放元数据</td><td>per-tensor 缩放下饱和</td></tr><tr><td>前缀共享</td><td>复用页存储与预填</td><td>引用计数/COW 开销</td><td>命中率过低、页被并发写坏</td></tr><tr><td>远端 KV 放置</td><td>本地 HBM 让给专家权重</td><td>fabric 流量与时延</td><td>未分层导致频繁跨 fabric</td></tr></tbody></table>\n<h3 id=\"ap-kv-cache-moe-sec-20\">二十 · 踩坑清单：五类高频失效及其机理</h3>\n<p>MoE 场景的 KV 压缩失效很少来自单一参数选错，而是来自“压缩策略—放置策略—并发模型”三者耦合处的缝隙。按工程现场出现频率排序，第一类是<strong>远端页未分层</strong>：把 KV 页整体推进 GB200 NVL72 统一显存池，却不区分热页与冷页，解码每步的注意力读取都跨 fabric，单步时延被远端带宽而非本地 HBM 带宽决定。第二类是<strong>前缀共享页的并发写污染</strong>：相同系统提示的请求复用同一批物理页，若缺少引用计数与写时复制，一个请求的追加写入会污染另一个请求的 KV 内容，或引用归零时提前释放仍在被读的页。第三类是<strong>per-tensor 量化缩放</strong>：整层共用一个 scale，长上下文尾部 token 幅值异常时直接饱和，注意力分数失真，且这种失真在路由倾斜的专家上被放大。第四类是<strong>页大小与专家换入粒度错配</strong>：页过大导致尾部浪费，页过小使元数据与查表开销上升，同时专家权重按需换入时与 KV 页争抢同一显存池的分配器锁。第五类是<strong>MLA 潜向量与分页假设冲突</strong>：MLA 把 KV 压成低秩潜向量后，按 token 头数估算的页容量公式失效，页内布局与注意力访存模式不再对齐。</p>\n<p>这五类坑的共同特征是：单看每一项都在“合理范围”，但叠加后表现为解码步时延抖动而非均值恶化。因此检查不能只看平均吞吐，必须看 P99 步时延与跨 fabric 读取占比。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-21\">二十一 · 检查顺序：从显存账本到访存路径</h3>\n<p>排查应遵循“先账本、再路径、后数值”的顺序，避免在数值精度上反复调参却忽略放置错误。第一步做<strong>显存账本对账</strong>：分别统计 KV 页占用、激活专家权重占用、临时 workspace 与分配器碎片，确认 KV 与专家权重是否在同一池内互相挤压。可用如下伪代码思路定位竞争：</p>\n<div class=\"formula\">$$\\text{peak} = \\underbrace{B \\cdot L \\cdot H \\cdot d_{\\text{kv}} \\cdot b_{\\text{kv}}}_{\\text{KV 页}} + \\underbrace{\\sum_{e \\in \\mathcal{A}} W_e}_{\\text{激活专家}} + \\text{frag}$$</div>\n<p>其中 $B$ 为并发批、$L$ 为上下文长度、$b_{\\text{kv}}$ 为每元素字节。若 peak 逼近池容量而 frag 持续上升，说明页分配与专家换入在争抢同一分配器。第二步查<strong>访存路径</strong>：统计注意力读取中跨 NVLink 域与跨机架 IB 的比例，热页是否真的落在本地 HBM。第三步才查<strong>数值</strong>：量化 scale 的粒度是 per-tensor 还是 per-head/per-page，softmax 统计是否用高精度累加。第四步查<strong>共享正确性</strong>：前缀共享页是否有引用计数、写时复制路径是否被并发请求触发。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>观测信号</th><th>系统代价</th><th>处置方向</th></tr></thead><tbody><tr><td>显存账本</td><td>peak 逼近池容量、碎片上升</td><td>吞吐下降、OOM 风险</td><td>分离 KV 池与专家池配额</td></tr><tr><td>访存路径</td><td>跨 fabric 读取占比高</td><td>解码步时延被远端带宽拖垮</td><td>热页本地化、冷页远端</td></tr><tr><td>量化粒度</td><td>尾部 token 饱和</td><td>注意力分数失真</td><td>改 per-head 或 per-page scale</td></tr><tr><td>共享正确性</td><td>KV 内容被污染或提前释放</td><td>结果不可复现</td><td>引用计数 + 写时复制</td></tr></tbody></table>\n\n<h3 id=\"ap-kv-cache-moe-sec-22\">二十二 · 前缀共享的引用计数与写时复制</h3>\n<p>前缀共享的收益边界取决于命中率，但正确性边界取决于并发写。工程上必须把共享页视为<strong>只读基页 + 请求私有增量页</strong>：基页由引用计数保护，任何请求要追加 token 时先触发写时复制，把增量写入新页并挂到该请求的页表链上。伪代码思路为：</p>\n<div class=\"formula\">$$\\text{append}(r, t):\\ \\text{if } \\text{ref}(p_{\\text{base}}) &gt; 1 \\text{ then } p \\leftarrow \\text{copy}(p_{\\text{base}});\\ \\text{ref}(p) \\mathrel{+}= 1;\\ \\text{write}(p, t)$$</div>\n<p>代价是写时复制瞬间的额外显存分配与一次页拷贝，若页过大则拷贝带宽开销显著；若页过小则引用计数元数据与页表查表开销上升。命中率低于一定比例时，管理开销可能抵消收益，需按实际命中率实测而非按经验拍板。一个具体例子：多轮对话中系统提示极长而用户轮次很短，共享基页命中率高，写时复制只发生在增量页上，收益明确；反之若每个请求前缀各异，引用计数只增不减，页回收滞后，显存反而被占死。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-23\">二十三 · 量化缩放的粒度与饱和检测</h3>\n<p>KV 量化到 FP8 可近似减半 KV 显存且精度损失可控，但前提是缩放粒度匹配幅值分布。per-tensor 缩放在长上下文尾部 token 幅值异常时饱和，表现为注意力分数在某几个头上系统性偏移。正确做法是 per-head 或 per-page 缩放，并配合高精度 softmax 统计：累加与最大值比较用 FP32，避免低精度统计放大饱和误差。检测手段是统计每个 head 每页的饱和比例，若某页饱和比例异常升高，说明该页应单独提精度或重算 scale。代价是 per-page scale 增加元数据字节与反量化时的乘加开销，页越小元数据占比越高，需与页大小联合调参。FP4 KV 的约束更紧，必须 per-head 或 per-page 缩放，且不能省掉高精度 softmax 统计，否则路由倾斜的专家上误差被放大到不可接受。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-24\">二十四 · 回滚方案：分级降级而非一刀切</h3>\n<p>回滚不是把整套压缩关掉，而是按影响面分级。第一级回滚<strong>放置策略</strong>：把远端池中的热页迁回本地 HBM，保留冷页远端，代价是一次页迁移带宽与短暂的步时延抬升，但不影响数值正确性。第二级回滚<strong>共享策略</strong>：关闭前缀共享或改为只读共享加禁用写时复制路径，代价是显存占用回升与命中率收益消失，但消除污染风险。第三级回滚<strong>量化粒度</strong>：把可疑层或可疑 head 从 FP4 提到 FP8，代价是 KV 显存回升，但注意力分数恢复。第四级才是<strong>整体关闭 KV 压缩</strong>，此时 KV 与专家权重竞争加剧，需同步下调并发批或上下文长度以守住 SLO。回滚顺序应与检查顺序相反：先动数值、再动共享、最后动放置，因为放置迁移的代价最高且最易引发抖动。</p>\n<p>工程判断落在一条具体机制上：为每个 KV 页维护“饱和比例、跨 fabric 读取次数、引用计数”三个计数器，任一越界即触发对应级别的自动降级，而不是等人发现 P99 抖动后再手工排查。这三个计数器本身就是压缩策略的健康度探针，比任何离线压测都更贴近真实负载。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-25\">二十五 · 失效边界与上线前检查顺序：从“能跑”到“敢开”的七道闸</h3>\n<p>这套方案最危险的时刻不是压测峰值，而是“参数看起来都对、线上却慢慢变坏”。MoE 场景下 KV 压缩的失效往往不是崩溃，而是精度漂移、尾延迟抬升、显存池抖动三者叠加，且互相掩盖。先给出可执行的检查顺序，按“代价从低到高、失败从显性到隐性”排列：①量化缩放粒度审计——逐层检查是否存在 per-tensor 缩放，长上下文尾部 token 幅值异常时整层共享的 scale 会饱和，注意力分数失真；改为 per-head 或 per-page 缩放，并保留高精度 softmax 统计（max/sum 用 FP32 累加）。②前缀共享引用计数与写时复制验证——构造并发请求同时命中同一系统提示页、其中一路触发回收的用例，观察物理页是否被污染或提前释放；缺引用计数的实现会在高并发下静默产出错乱 KV。③页大小与尾部浪费测算——页过大浪费尾部空间，页过小元数据与查表开销上升，材料未给阈值，必须按实际序列长度分布实测“浪费字节/元数据开销”两条曲线取交点。④放置分层校验——检查是否存在“KV 页进了远端统一显存池但未按访问热度分层”的配置，这是解码步时延被 fabric 带宽拖垮的头号原因。⑤跨 fabric 读带宽预算——按长上下文注意力读取量估算远端页占比上限。⑥回滚开关演练——量化位宽、共享策略、放置层级三项必须能独立热切换。⑦SLO 尾延迟回归——只看均值会漏掉远端页引发的 P99 抬升。</p>\n<p>跨节点放置的代价必须被显式建模，而不是靠“池子大就多放”。设远端页占比为 <i>r</i>，单 token 注意力读取字节为 <i>b</i>，本地 HBM 有效带宽 <i>B<sub>L</sub></i>，fabric 有效带宽 <i>B<sub>F</sub></i>，则解码步内 KV 读取的平均代价可写为：</p>\n<div class=\"formula\">$$T_{read} \\approx \\frac{(1-r)\\,b}{B_L} + \\frac{r\\,b}{B_F}, \\qquad r^\\* = \\arg\\min_r \\big(T_{read}(r)\\big)\\ \\text{s.t.}\\ \\text{HBM 容量约束}$$</div>\n<p>由于 <i>B<sub>F</sub></i> 显著低于 <i>B<sub>L</sub></i>（同机架 NVLink 域内优于跨机架 IB），<i>r</i> 稍大便使 <i>T<sub>read</sub></i> 被第二项主导；长上下文下 <i>b</i> 随上下文线性增长，远端页的每次注意力读取都要过 fabric，带宽成为瓶颈。工程判断：热页留本地、冷页放远端，且远端页占比必须由“每步 fabric 字节预算 ÷ 单步可用 fabric 带宽”反推上限，而不是由显存余量决定。一个具体例子：某长上下文会话的 KV 页被整体迁到远端池以腾出本地空间给专家权重换入，单步时延在上下文超过一定长度后由 fabric 往返主导，表现为解码吞吐随 batch 增大反而下降——这正是“显存省了、SLO 崩了”的典型形态。</p>\n<p>量化与共享的收益边界要用命中率和幅值分布两个实测指标卡住，不能按“FP8 近似减半”直接外推。KV 量化到 FP8 可近似减半 KV 显存且精度损失可控，但 FP4 KV 必须配 per-head 或 per-page 缩放与高精度 softmax 统计，否则尾部 token 饱和会先污染注意力分数、再污染路由（MoE 中注意力输出进入 gate 打分，误差会被专家选择放大）。前缀共享同理：命中率低于一定比例时，引用计数、页表查找与写时复制的管理开销可能抵消收益，材料未给统一数字，须按实际命中率实测“省下的字节 vs 增加的元数据与查表周期”。检查清单应把这两项列为“必须带数据上线”的门禁项，而非默认开启。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>检查动作</th><th>回滚粒度</th></tr></thead><tbody><tr><td>远端页未分层</td><td>P99 解码步时延随上下文抬升、batch 增大吞吐反降</td><td>统计远端页占比与每步 fabric 字节</td><td>按请求/按页迁回本地</td></tr><tr><td>共享页污染/提前释放</td><td>并发命中同一前缀时输出不一致</td><td>引用计数与写时复制并发用例</td><td>关闭前缀共享，保留分页</td></tr><tr><td>per-tensor 量化饱和</td><td>长上下文尾部注意力分数失真、路由偏移</td><td>逐层缩放粒度审计 + 幅值分布</td><td>FP4→FP8 或回退未量化 KV</td></tr></tbody></table>\n<p>回滚方案的设计原则是“三项解耦、按页回滚”：量化位宽、共享策略、放置层级各自独立开关，避免一处异常牵连全局；放置层级的回滚应支持按页迁移而非整池重配，因为远端页问题只影响部分请求。上线前必须演练一次“关闭前缀共享但保留分页”和一次“FP4 回 FP8”的热切换，确认切换期间在途请求的 KV 不被重复释放。最终判断落在具体机制上：把每步 fabric 字节数与 P99 解码时延做成同图监控，任一越界即触发按页迁回，这是这套方案唯一可靠的止损点。</p>\n<h3 id=\"ap-kv-cache-moe-sec-26\">二十六 · 上游依赖：注意力结构与量化格式决定了下游一切</h3>\n<p>本条目讨论的 KV 压缩策略不是孤立存在的，它在全书中的位置首先由上游条目决定。具体而言，KV 压缩的可行空间由两个上游决策锁定：注意力结构（MHA/GQA/MLA）与 KV 量化位宽（FP8/FP4/INT8）。这两者不是并列选项，而是有先后关系的——注意力结构决定了每 token KV 的“形状”，量化位宽决定了这个形状能被压到多小。MLA 把 KV 压成低秩潜向量，GQA 以分组共享 KV 头降低头数，二者都减少每 token KV 字节，但改变注意力计算图与访存模式。这意味着：一旦上游选定了 MLA，下游的分页粒度、前缀共享的物理页布局、跨节点放置的传输单元都要按潜向量的维度重新设计，而不是沿用 GQA 时代的页结构。</p>\n<p>用公式表达这个依赖关系。设每 token KV 字节为 <span>B<sub>kv</sub></span>，头数为 <span>H</span>，头维度为 <span>d</span>，层数为 <span>L</span>，量化位宽为 <span>q</span>（字节），则对 GQA：</p>\n<div class=\"formula\">$$B_{kv} = 2 \\cdot L \\cdot H_{kv} \\cdot d \\cdot q$$</div>\n<p>其中 <span>H<sub>kv</sub></span> 是 KV 头数（GQA 下小于查询头数）。MLA 则把 <span>H<sub>kv</sub>·d</span> 替换为潜向量维度 <span>d<sub>c</sub></span>，公式变为 <span>B<sub>kv</sub> = L·d<sub>c</sub>·q</span>（不含 RoPE 解耦部分时）。上游选型直接改变了这个乘式的因子个数，下游的页大小、前缀共享的页对齐、远端池的传输块大小都必须跟着变。</p>\n<p>系统代价在这里体现为：上游若选了 FP4 KV，则必须配 per-head 或 per-page 缩放并配合高精度 softmax 统计；这个约束会向下游传导——分页管理必须支持 per-page 缩放因子的存储与查表，前缀共享的物理页在被多请求复用时缩放因子不能冲突。这是一个具体的机制耦合：量化格式不是“存进去就完事”，它把元数据带进了页结构。举例：一个长上下文请求在 FP8 KV 下每 token KV 字节近似减半且精度损失可控，但若上游为省显存改选 FP4，则下游页表必须多存一份缩放因子，页元数据开销上升，页过大浪费尾部空间、页过小元数据与查表开销上升的权衡被进一步挤压。上游的量化选择因此不是免费的，它把成本转移到了下游的分页与共享层。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-27\">二十七 · 上游依赖：专家权重换入与 KV 增长争夺同一显存池</h3>\n<p>第二个上游依赖来自 MoE 本身：KV cache 与专家权重竞争同一显存池。KV 随上下文长度与并发批线性增长，专家权重随激活专家数按需换入。这个竞争关系是本条目所有压缩策略的出发点，也是它与“专家并行与 All-to-All”“分组GEMM与tcgen05”等条目的接口。KV 压缩的收益边界不能只看 KV 本身省了多少字节，而要看省下来的字节是否真的让专家权重换入更顺畅——如果压缩 KV 后显存池仍然被其他东西占满，收益就被抵消。</p>\n<p>伪代码思路表达这个竞争：</p>\n<div class=\"formula\">$$\\text{free} = \\text{pool} - B_{kv}(ctx, batch) - W_{active}(experts) - W_{static}$$</div>\n<p>KV 压缩的作用是缩小 <span>B<sub>kv</sub></span> 项，从而给 <span>W<sub>active</sub></span> 留出换入空间。但注意：<span>W<sub>active</sub></span> 是随激活专家数动态变化的，而 <span>B<sub>kv</sub></span> 随上下文与并发线性增长。两者都是动态项，压缩 KV 只是把其中一个动态项压小，并不能保证 <span>free</span> 始终为正。工程判断是：KV 压缩的收益必须与专家权重换入策略联合评估，单独看 KV 字节减少会高估收益。</p>\n<p>系统代价具体化：在 GB200 NVL72 统一显存池中，这个竞争跨越节点。把热 KV 页放在本地 HBM、冷页放在远端池可降低平均访问代价，但远端页的每次注意力读取都要经过 fabric，长上下文下带宽成为瓶颈。这意味着 KV 压缩的上游收益（省字节）与下游代价（远端访问带宽）是耦合的：压缩得越狠，单页越小，跨 fabric 传输的块越小，fabric 效率可能下降；压缩得不够，本地 HBM 放不下，被迫外溢到远端。举例：一个高并发长上下文场景，若 KV 未压缩导致本地 HBM 不足，冷页外溢到远端池，解码步时延被远端带宽拖垮——这正是失败模式“把 KV 页放到远端统一显存池却未按访问热度分层”的直接后果。上游的专家权重换入压力因此会反向影响 KV 放置决策。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-28\">二十八 · 下游影响：分页与前缀共享的收益边界被上游命中率锁定</h3>\n<p>向下游看，本条目直接影响分页管理与前缀共享两个机制。分页管理把 KV 切成固定页并按需分配，前缀共享让相同系统提示的请求复用同一批物理页，二者在长上下文下降低碎片与重复存储。但收益边界取决于前缀命中率与页大小，而命中率不是本条目能控制的——它由上游的请求分布与系统提示设计决定。因此本条目在下游的角色是：提供压缩后的页结构，但收益兑现取决于外部命中率。</p>\n<p>公式化收益边界。设前缀共享节省的物理页比例为 <span>r<sub>hit</sub></span>，管理开销为 <span>C<sub>meta</sub></span>（随页数增长），则净收益：</p>\n<div class=\"formula\">$$\\text{gain} = r_{hit} \\cdot B_{kv,shared} - C_{meta}(N_{pages})$$</div>\n<p>前缀共享命中率低于一定比例时管理开销可能抵消收益，需按实际命中率实测。这是一个明确的工程判断：不能假设前缀共享总是正收益。页大小的选择同样受上游量化格式影响——FP4 KV 的 per-page 缩放因子使每页元数据变大，页过小则元数据与查表开销上升更快，页过大则尾部浪费更严重。材料未给出具体页大小阈值，因此工程上必须按实际命中率与页元数据成本实测，而不是套用固定值。</p>\n<p>系统代价落在显存与延迟两侧：前缀共享省的是显存（重复存储消除），但引用计数与写时复制带来的是延迟与复杂度。失败模式“前缀共享的物理页被并发请求同时写入或回收，缺少引用计数与写时复制，导致 KV 内容被污染或提前释放”说明下游机制的正确性依赖本条目定义的页生命周期。举例：两个并发请求共享同一系统提示的物理页，若其中一个请求的 KV 量化缩放因子与另一个不同（因为上游选了 per-head 缩放），共享页就不能直接复用，必须按缩放因子分桶——这是上游量化选择对下游共享策略的直接约束。下游因此不能把前缀共享当作纯显存优化，它同时是正确性问题。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-29\">二十九 · 下游影响：跨节点放置把压缩收益转化为 fabric 带宽账</h3>\n<p>本条目最直接的下游影响在放置层：GB200 NVL72 统一显存池中跨节点 KV 放置的访问代价取决于链路，同机架 NVLink 域内访问延迟与带宽优于跨机架 IB。KV 压缩在这里的作用是改变“有多少页需要跨 fabric”这个数量，但它不能改变单次跨 fabric 访问的代价。因此压缩收益必须换算成 fabric 带宽账才能判断是否值得。</p>\n<p>用公式表达分层放置的平均访问代价。设本地命中率为 <span>h</span>，本地访问代价为 <span>c<sub>local</sub></span>，远端访问代价为 <span>c<sub>remote</sub></span>（含 fabric 延迟与带宽），则：</p>\n<div class=\"formula\">$$\\bar{c} = h \\cdot c_{local} + (1-h) \\cdot c_{remote}$$</div>\n<p>KV 压缩通过缩小 <span>B<sub>kv</sub></span> 提高 <span>h</span>（更多页能放进本地 HBM），从而降低 <span>\\(\\bar{c}\\)</span>。但若压缩后页变小导致跨 fabric 传输块变小、fabric 效率下降，<span>c<sub>remote</sub></span> 可能上升，抵消 <span>h</span> 的提升。这是一个非单调的权衡：压缩不是越多越好，存在一个与 fabric 传输粒度匹配的最优点。材料未给出具体数值，工程上必须按实际链路实测 <span>c<sub>remote</sub></span> 随块大小的变化。</p>\n<p>系统代价是解码步时延：长上下文下远端页的每次注意力读取都要经过 fabric，带宽成为瓶颈。失败模式已经明确——未按访问热度分层，注意力读取频繁跨 fabric，解码步时延被远端带宽拖垮。举例：一个 NVL72 机架内，热 KV 页放本地 HBM、冷页放远端池，若热度分层缺失，所有页等概率被读，则 <span>h</span> 退化为本地容量占比，<span>\\(\\bar{c}\\)</span> 被远端项主导。本条目因此在下游的角色是：提供压缩后的页尺寸与量化格式，但放置策略必须独立做热度分层，两者不能混为一谈。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-30\">三十 · 在全书中的位置：连接注意力选型、量化、并行与框架四条线</h3>\n<p>把本条目放回全书结构，它的位置是四条线的交汇点。第一条线是注意力选型（MHA/GQA/MLA），本条目消费其输出——每 token KV 字节与访存模式。第二条线是量化（NVFP4/FP8 权重激活），本条目消费其 KV 侧约束——缩放粒度与 softmax 统计精度。第三条线是并行与通信（NVLink 5、NCCL、NIXL），本条目把压缩收益转化为跨节点放置的 fabric 账。第四条线是框架（TensorRT-LLM、vLLM、SGLang、Dynamo），本条目定义的页结构与共享策略必须能被框架的分页管理器实现。</p>\n<p>这个位置决定了本条目不能独立成章。它依赖“MoE 路由术语速查”提供的专家激活语义来判断 <span>W<sub>active</sub></span> 的动态性，依赖“容量因子与丢弃代价”来判断显存池的余量，依赖“分离式预填解码”来判断预填与解码阶段的 KV 放置是否应该不同（预填阶段 KV 写入密集，解码阶段 KV 读取密集，两者的放置策略不应相同）。它向下影响“路由倾斜尾延迟”——KV 压缩不足导致显存紧张时，尾延迟被放大；也影响“量化后路由漂移”——KV 量化与权重量化是两套校准，不能混用同一份校准数据管线。</p>\n<p>系统代价在全书层面是容量规划：SLO 与容量规划条目需要本条目提供每 token KV 字节的压缩后数值，才能算出单卡/单节点能承载的并发上下文长度。若本条目给出的数值偏乐观（例如假设前缀共享高命中率但实际未达标），容量规划会系统性低估显存需求。举例：容量规划按 FP8 KV 近似减半估算并发数，但实际部署中前缀命中率低于收益边界，管理开销抵消收益，则实际可承载并发低于规划值——这是本条目与容量规划条目之间必须显式对齐的接口。工程判断是：本条目输出的应是“压缩后字节 + 收益边界条件”这一对，而不是单一数字。</p>\n\n<h3 id=\"ap-kv-cache-moe-sec-31\">三十一 · 接口约定：本条目向上下游交付什么</h3>\n<p>最后落到具体机制：本条目在全书中的交付物是三个接口约定，而不是一组孤立结论。第一个接口是页结构契约——页大小、量化格式、缩放因子存放位置、引用计数与写时复制语义。上游注意力选型与量化格式决定页内布局，下游分页管理与前缀共享按此契约实现。第二个接口是放置契约——哪些页允许跨 fabric、热度分层的判定依据、远端池的传输块大小与页大小的对齐关系。下游跨节点放置按此契约做分层，而不是自行决定。第三个接口是收益边界契约——前缀共享命中率的实测口径、页大小与元数据开销的实测口径、KV 量化精度损失的验收口径。</p>\n<p>这三个契约的共同点是：它们都是“条件式”的，不是无条件的最优值。材料未给出统一数字，领域经验是 KV 量化到 FP8 可近似减半 KV 显存且精度损失可控，FP4 KV 需 per-head 或 per-page 缩放并配合高精度 softmax 统计。这意味着本条目交付的不是“用 FP8 就对了”，而是“用 FP8 时页结构必须支持 per-page 缩放，且 softmax 统计精度必须单独验收”。下游条目消费这些契约时，必须把条件一起带走，否则就会出现失败模式——量化缩放按整层 per-tensor 选择，长上下文尾部 token 幅值异常时量化饱和，注意力分数失真。这个失败模式的根源正是接口契约被简化：上游给了 per-head 缩放的约束，下游却按 per-tensor 实现，契约在传递中丢失。</p>\n<p>工程判断落在最后一句：本条目在全书中的价值不在于给出一个压缩比，而在于把“压缩收益”与“收益兑现的条件”绑定交付。任何下游条目若只取压缩比而不取条件，都会在长上下文、高并发、跨节点这三个维度上系统性高估收益。反过来，上游条目若只给注意力结构与量化格式而不给页结构约束，本条目就无法给出可实现的压缩方案。这就是它在全书中的位置：一个必须双向对齐的接口层，而不是一个可以单独优化的局部模块。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-kv-cache-moe\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>讨论 MoE 模型中 KV cache 与专家权重显存的竞争关系，说明 MLA/GQA、量化 KV、分页管理与…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-kv-cache-moe · 共 5 个片段</p>\n"},{"id":"ap-pd-disaggregation","title":"分离式预填解码","summary":"说明预填与解码分离后 KV 传输的带宽与时延预算、MoE 专家在两侧的放置策略、解码侧批调度与预填侧 chunked prefill 的配比，以及 NVL72 内 NVLink 传输与跨机架 IB 传输的 SLO 差异。","kind":"术语","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-1\">一 · 条目边界：什么算分离式预填解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-2\">二 · 分类维度一：KV 传输链路的三层阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-3\">三 · 分类维度二：预填 chunk 与解码批的配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-4\">四 · 分类维度三：MoE 专家在两侧的放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-5\">五 · 与相邻概念的边界与误用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-6\">六 · 速查表结构与分类落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-7\">七 · 速查表的结构与口径约定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-8\">八 · 单 token KV 字节的算法与显存代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-9\">九 · 传输时间公式与链路预算的填法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-10\">十 · 专家放置列的三种填法与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-11\">十一 · chunk 与批配比的判定口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-12\">十二 · 跨机架 SLO 差异与重叠的填法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-13\">十三 · 速查表背后的口径与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-14\">十四 · 速查表之外的边界：何时这张表会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-15\">十五 · 预填 chunk 的测量口径：把 kernel 启动开销折算成 token 成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-16\">十六 · KV 传输预算的实测：有效带宽不是标称带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-17\">十七 · 预填 chunk 与解码批的配比：用排队指标而非平均值定阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-18\">十八 · 专家放置的阈值判断：远程取专家输出的步时延代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-19\">十九 · 跨机架与机架内的 SLO 差异：把时延预算拆到每层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-20\">二十 · 阈值不是拍脑袋：把 chunk、批与链路代进同一条预算式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-21\">二十一 · 预填 chunk 与解码批配比失衡的链路占满坑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-22\">二十二 · 专家只放预填侧导致 All-to-All 与 KV 争抢同一 fabric</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-23\">二十三 · 跨机架 IB 传输未与解码计算重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-24\">二十四 · 检查清单与检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-25\">二十五 · 回滚方案与降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-26\">二十六 · 预填解码分离的失效边界与上线检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-27\">二十七 · 上游依赖：KV 传输预算决定了本条目的一切参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-28\">二十八 · 下游影响：解码侧调度与 MoE 放置被本条目反向塑形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-29\">二十九 · 与量化、KV 压缩条目的接口：字节数而非算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-30\">三十 · 与框架条目的接口：谁实现配比，谁暴露背压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-31\">三十一 · 在全书中的位置：从单实例算子到多实例系统的分界线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-pd-disaggregation-sec-32\">三十二 · 边界条件：链路层级、专家放置与配比失衡如何把分离式架构拖回串行</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-pd-disaggregation\"><svg style=\"max-width:535px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 535.4 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"453.4\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：分离式预填解码</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">说明预填与解码分离后 KV 传输的带宽与时延预算、MoE 专家在两侧的</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">放置策略…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"453.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"453.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"453.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-pd-disaggregation-sec-1\">一 · 条目边界：什么算分离式预填解码</h3>\n<p>分离式预填解码（PD 分离）的准确含义是：把一次请求生命周期中计算形态完全不同的两段——预填（prefill，一次性处理整段上下文、生成首 token 并产出每层 KV）与解码（decode，逐 token 自回归、每步只处理一个 token 但需读取全部历史 KV）——放到不同的实例、不同的进程组乃至不同的物理节点上执行，两侧通过一条显式的 KV 传输通道耦合。判定一个系统是否属于本条目，看三条同时成立：其一，预填与解码不在同一计算图内串行执行；其二，KV 以显式张量形式跨实例搬运，而非留在同一显存内被后续 kernel 直接引用；其三，两侧各自拥有独立的批调度器，预填侧的 chunk 划分与解码侧的连续批处理互不阻塞。</p>\n<p>由此可以划出与相邻概念的界线。连续批处理（continuous batching）是解码侧内部的调度技术，它解决的是同一实例上多请求交织、避免批内空洞的问题，本身不改变预填与解码的物理位置；PD 分离则把“位置”作为一等设计变量，连续批处理在分离架构中降级为解码侧的一个子策略。Chunked prefill 同样不是 PD 分离：它把长上下文切成若干 chunk 在同一实例上与解码请求混批，目的是压平单次计算图规模与显存峰值，属于“同实例内的形态混合”；PD 分离则是“跨实例的形态拆分”，chunked prefill 在其中扮演预填侧的节流阀。至于分离式服务（disaggregated serving）这一更宽的提法，还包含把权重、调度、缓存分层拆开的多类形态，PD 分离只是其中以 KV 为耦合介质的一支。</p>\n<p>代价侧要立刻说清：PD 分离用一条 KV 传输链路换取了两个自由度——预填侧可以按吞吐最优配置大 chunk 与高算力密度，解码侧可以按低时延最优配置小批与高显存容量。代价是每层 KV 必须离开生产它的显存再进入消费它的显存，这条路径的带宽与时延直接进入关键路径。对 NVL72 内的 NVLink 链路，这笔开销可以被解码计算掩盖；对跨机架 IB 链路，若不做重叠，KV 传输就线性计入首 token 时延。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-2\">二 · 分类维度一：KV 传输链路的三层阶梯</h3>\n<p>链路是 PD 分离分类中最硬的维度，因为它直接决定预算量级。第一层是同节点 NVLink：预填与解码实例共享同一台 GPU 节点的显存语义域，KV 以 peer-to-peer 方式写入对端显存，无需经过主机内存或网卡。第二层是机架内 NVLink：在 NVL72 这类机架级域内，两侧实例分处不同计算托盘但仍在同一 NVLink 域，KV 走域内交换，带宽高、时延低，但受域内拓扑与并发流量影响。第三层是跨机架 IB：两侧落在不同机架，KV 必须经 RDMA 网卡与交换机搬运，带宽下降、时延抬升，且与训练/其他推理流量共享 fabric。</p>\n<p>预算的基本式是传输时间对 KV 字节数的比值：</p>\n<div class=\"formula\">$$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$</div>\n<p>其中 S 为序列长度、L 为层数、H 为 KV 头数、d 为每头维度、B 为有效带宽。这个式子说明传输量正比于上下文长度、层数与 KV 头维度——三者任一放大都线性推高 T。工程含义是：长上下文请求在跨机架链路上天然吃亏，因为 T 随 S 线性增长，而解码每步的计算量几乎不随 S 增长（只随批大小增长），重叠窗口有限。因此分类时必须把“单 token KV 字节”作为速查表的核心列，它等于 L·H·d·每元素字节数，是判断某条链路能否承载某类负载的第一道筛子。</p>\n<p>具体例子：一个层数较深、KV 头维度较大的模型，其单 token KV 字节落在数十 KB 到上百 KB 量级；一条跨机架 IB 链路在共享流量下的有效带宽远低于域内 NVLink，于是同一段上下文在跨机架场景的 T 可能是域内的数倍。系统代价因此分层：域内 NVLink 场景可以把 KV 传输当作可忽略的附加项，跨机架场景必须把它当作与解码计算并列的关键路径项来排布。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-3\">三 · 分类维度二：预填 chunk 与解码批的配比</h3>\n<p>第二个维度是预填侧的 chunk 大小与解码侧批大小及调度策略的组合。Chunked prefill 在预填侧的作用是把一次长上下文拆成若干计算图规模可控的片段，平滑显存峰值并让预填 kernel 的占用可预测；解码侧的连续批调度则在每步维持一个尽量饱满的批以摊薄权重读取。两者配比决定了整条流水线的节流特性。</p>\n<p>伪代码思路可写成两侧的节流闭环：预填侧每完成一个 chunk 就产出一段 KV 并推入传输队列，解码侧每步从队列取走已到达的 KV 段并纳入批。若预填 chunk 过大，预填侧单次占用链路的时间变长，解码侧等待 KV 到达的间隔被拉长，尾时延出现抖动；若 chunk 过小，预填 kernel 启动开销在总时间中的占比上升，预填吞吐下降，队列供不上解码侧。配比的目标是让预填吞吐与解码时延同时满足 SLO，材料未给出统一数字，领域经验是靠实测把 chunk 与批的比值调到两侧都不成为瓶颈的位置。</p>\n<p>代价体现在三个量上：预填侧显存峰值随 chunk 增大而上升，因为激活与中间张量按 chunk 规模分配；解码侧批大小上升会挤占 KV 容量，因为每增加一个并发请求就多一份 KV 驻留；链路占用率随 chunk 增大而出现尖峰，尖峰期间解码侧的 KV 到达延迟抖动。具体例子：当预填侧连续推入多个长 chunk 时，链路被占满，解码侧新请求的 KV 段排在队尾，其首 token 时延超出 SLO——这正是失败模式中“预填 chunk 与解码批配比失衡”的机理。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-4\">四 · 分类维度三：MoE 专家在两侧的放置</h3>\n<p>第三个维度只在 MoE 模型上出现，却足以改变整个分类结论：专家权重放在哪一侧。三种放置各有明确代价。全量复制到解码侧，解码每步本地取专家、无跨实例通信，但专家权重挤占解码侧显存，KV 容量下降，可承载的并发上下文变短。只放在预填侧，解码侧显存全留给 KV，但解码每步都要远程取专家输出，All-All 通信与 KV 传输叠加在同一 fabric 上竞争。按层切分，两侧各自持有部分层的专家，显存压力分摊，但跨层路由需要跨实例通信，路由路径变长。</p>\n<p>把这一维度与链路维度交叉，就得到分类矩阵的关键格：跨机架 IB 加专家只放预填侧，是最不利的组合，因为解码步时延同时被远程专家取回与 KV 传输拉长，两者在同一 fabric 上争带宽，材料明确指出这种情形下解码步时延翻倍。反之，域内 NVLink 加按层切分，跨层路由通信落在高带宽域内，代价可控。速查表因此必须含“专家放置”列，与“链路”“单 token KV 字节”“chunk 大小”“批大小”“SLO 目标”“传输时延预算”并列，否则同一链路下不同专家放置会给出完全不同的容量结论。</p>\n<p>系统代价的量化抓手是解码侧显存账：专家权重占用与 KV 容量在同一块显存上竞争，全量复制的直接后果是每卡可驻留的 KV 字节数下降，进而压低最大并发批。这个账必须在分类阶段就算清，而不是等到容量规划时才发现解码侧装不下目标批。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-5\">五 · 与相邻概念的边界与误用</h3>\n<p>把 PD 分离与“多实例部署”混为一谈是常见误用。多实例只是把请求分到多张卡上做同构复制，每张卡都完整执行预填与解码；PD 分离则是异构分工，两侧的计算图、批形态、显存结构都不同。另一类误用是把 PD 分离当成 KV 缓存优化的替代品：KV 压缩、量化、前缀复用解决的是 KV 占用与重复计算，PD 分离解决的是计算形态错配与资源配比，两者正交，可以叠加，但任何一个都不能替代另一个。</p>\n<p>还有一条边界要划在“预填侧 chunked prefill”与“解码侧连续批”之间：前者控制的是单次计算图规模与显存峰值，后者控制的是每步批的饱满度与请求排队。二者通过 KV 传输队列耦合，但调度目标不同——预填侧追吞吐，解码侧追时延。分类时若把两者当作同一层策略，就会在配比调优时失去抓手。具体例子：把 chunk 调小以降低预填显存峰值，却未同步调大解码批，结果是预填 kernel 启动开销吃掉吞吐、解码侧仍因 KV 到达稀疏而排队，两侧 SLO 同时失守。</p>\n<p>最后一条边界是 SLO 归属：PD 分离把首 token 时延与每 token 时延拆给了不同实例。首 token 时延由预填侧 chunk 推进速度与 KV 传输时延共同决定，每 token 时延由解码侧批调度与 KV 读取带宽决定。分类时必须标明每个 SLO 目标挂在哪一侧，否则容量规划会把两条不同性质的预算混成一个数。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-6\">六 · 速查表结构与分类落地</h3>\n<p>把上述维度固化成一张表，是分类工作的落地形态。表的最小列集为：链路、单 token KV 字节、chunk 大小、批大小、专家放置、SLO 目标、传输时延预算。每一行是一个可部署的配置格，行与行之间的差异必须能追溯到某一个维度的变化，否则说明维度划分有冗余。</p>\n<table class=\"mini\"><thead><tr><th>链路</th><th>单 token KV 字节</th><th>chunk 大小</th><th>批大小</th><th>专家放置</th><th>SLO 目标</th><th>传输时延预算</th></tr></thead><tbody><tr><td>同节点 NVLink</td><td>由 L·H·d 决定</td><td>可放大</td><td>中等</td><td>全量复制或按层切分</td><td>首 token 紧、每 token 紧</td><td>可忽略量级</td></tr><tr><td>机架内 NVLink</td><td>同上</td><td>需与批配比</td><td>中等偏大</td><td>按层切分优先</td><td>首 token 中等、每 token 紧</td><td>需与解码计算重叠</td></tr><tr><td>跨机架 IB</td><td>同上</td><td>宜小且均匀</td><td>偏小以保时延</td><td>避免只放预填侧</td><td>首 token 放宽、每 token 紧</td><td>必须重叠，否则线性恶化</td></tr></tbody></table>\n<p>读表方法是先定链路再看预算：跨机架 IB 行的传输时延预算一栏写着“必须重叠”，意味着该配置格只有在 KV 传输与解码计算并行时才成立，串行插入关键路径会让首 token 时延随上下文长度线性恶化。机架内 NVLink 行允许更大的 chunk，因为域内带宽足以吸收尖峰。同节点行则把传输当作可忽略项，分类重心回到批与显存的配比。</p>\n<p>分类的工程判断落在一条：先按链路把候选配置格筛到可行集，再用专家放置修正解码侧显存账，最后用 chunk 与批的配比把两侧 SLO 同时压进目标。任何一格若出现“专家只放预填侧 + 跨机架 IB + 小批”的组合，就应直接判为不可行，因为 All-to-All 与 KV 传输在同一 fabric 上竞争会使解码步时延翻倍，这不是调参能救回的，而是分类阶段就该排除的结构性缺陷。</p>\n<h3 id=\"ap-pd-disaggregation-sec-7\">七 · 速查表的结构与口径约定</h3>\n<p>这张表不是参数推荐表，而是把分离式预填/解码的部署决策压缩成一行一行的“可填字段”。每一行代表一种链路与放置组合，列则是必须在下发配置前确定的量。使用方式是：先按链路选行，再按模型结构算单 token KV 字节，最后用 SLO 目标反推 chunk 与批的配比。表中所有阈值均为口径定义而非实测数字，因为材料未给出统一数值；工程上必须用本集群的实测带宽与 kernel 启动开销回填。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>链路</th><th>单 token KV 字节</th><th>chunk 大小</th><th>解码批大小</th><th>专家放置</th><th>SLO 目标</th><th>传输时延预算</th></tr>\n</thead>\n<tbody>\n<tr><td>同节点 NVLink</td><td>2·L·H·d·b<sub>kv</sub></td><td>中等，覆盖 kernel 启动开销</td><td>大，连续批满载</td><td>全量复制或按层切分</td><td>首 token 紧、步时延稳</td><td>可基本不计入关键路径</td></tr>\n<tr><td>机架内 NVLink</td><td>同上</td><td>中等偏大</td><td>中大</td><td>按层切分优先</td><td>首 token 中等</td><td>需与预填计算重叠</td></tr>\n<tr><td>跨机架 IB</td><td>同上</td><td>小到中，避免占满链路</td><td>中，留出抖动余量</td><td>按层切分，避免远程取专家</td><td>首 token 宽松、尾时延严</td><td>必须与解码计算重叠</td></tr>\n</tbody>\n</table>\n<p>口径上要区分三件事：单 token KV 字节是“每生成一个 token、每层、每头、每维”的累加量，不是整段上下文的传输量；chunk 大小指预填侧单次计算图覆盖的 token 数；传输时延预算指允许 KV 到达解码侧而不推高首 token 时延的那部分时间窗。三者混用会让容量规划直接失真。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-8\">八 · 单 token KV 字节的算法与显存代价</h3>\n<p>表中第二列由模型结构唯一确定：每层每头每维存一份 K 和一份 V，若 KV 量化到 b<sub>kv</sub> 字节则乘以该字节数。写成式子即</p>\n<div class=\"formula\">$$K_{\\text{tok}} = 2 \\cdot L \\cdot H \\cdot d \\cdot b_{kv}$$</div>\n<p>系数 2 来自 K 与 V 两份。这个量决定两件事：一是解码侧每接受一个请求要预留多少 KV 容量，二是跨实例传输时每 token 的搬运成本。以层数深、KV 头多的模型为例，单 token KV 字节会显著抬高解码侧显存占用，直接压缩可并发的批大小；此时若专家权重又全量复制到解码侧，KV 容量与专家权重在同一块显存上互相挤占，批大小被迫下调，解码吞吐随之下降。工程判断是：先算 K<sub>tok</sub>，再算“解码侧显存减去专家权重”剩下的 KV 预算，用预算除以 K<sub>tok</sub> 与目标上下文长度得到单卡可容纳的并发序列数，这个数才是批大小的上限，而不是反过来先定批再找显存。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-9\">九 · 传输时间公式与链路预算的填法</h3>\n<p>第七列“传输时延预算”的算法是传输时间公式的逆用：</p>\n<div class=\"formula\">$$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$</div>\n<p>其中 S 为序列长度、B 为有效带宽。注意分子里没有系数 2 与 b<sub>kv</sub> 时，是把 K 与 V 合并按元素计；实际填表时应把 K<sub>tok</sub>·S 作为总字节数除以 B。这个式子的工程含义是：T 随上下文长度线性增长，因此跨机架 IB 场景下长上下文请求的 KV 传输必然进入关键路径，除非与解码计算重叠。填表时把 T 与“首 token 时延目标减去预填计算时间”比较：若 T 大于该余量，则必须启用重叠，否则首 token 时延随 S 线性恶化。同节点与机架内 NVLink 的 B 足够大，T 通常落在余量内，可把该列填为“不计入关键路径”；跨机架 IB 则应填“重叠后计入残差”。</p>\n<p>一个具体例子：某模型 L 层、H 头、d 维，单 token KV 为 K<sub>tok</sub>；当 S 增长到使 K<sub>tok</sub>·S 接近链路单次传输窗口时，T 开始与预填 chunk 的计算时间同量级，此时若 chunk 仍取大值，预填侧会长时间占满链路，解码侧 KV 到达出现抖动，尾时延超出 SLO——这正是失败模式里“长 chunk 占满链路”的机理。对策不是简单调小 chunk，而是把 chunk 与解码批配比绑定：chunk 覆盖的计算时间应略大于一个解码步的 KV 传输时间，使链路在两次预填之间有空窗。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-10\">十 · 专家放置列的三种填法与代价</h3>\n<p>第五列不是自由选项，而是由链路与显存共同约束的。全量复制到解码侧：解码步无需跨实例取专家输出，步时延稳定，代价是专家权重挤占 KV 容量，K<sub>tok</sub> 越大越不可行，适合小专家数或解码侧显存充裕的部署。只放预填侧：解码每步都要远程取专家输出，All-All 与 KV 传输在同一 fabric 上竞争，解码步时延翻倍，这是材料明确列出的失败模式；填表时应把该组合标为禁止，除非 fabric 有独立通道。按层切分：两侧各持部分层专家，跨层路由需跨实例通信，但单侧显存压力减半，是跨机架 IB 场景的默认填法；代价是路由通信与 KV 传输共享带宽，因此传输时延预算列必须留出路由流量的份额，不能把 B 全部算给 KV。</p>\n<p>填表时的顺序是：先按链路排除不可行组合，再用 K<sub>tok</sub> 与解码侧显存预算筛掉全量复制，最后在按层切分下核算路由流量占用的带宽比例。若路由流量占比高到使 T 超出余量，则退回“专家只放预填侧但增加解码侧本地缓存”的折中，而不是硬扛远程取数。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-11\">十一 · chunk 与批配比的判定口径</h3>\n<p>第三、四列必须成对填写，因为它们的配比决定两个 SLO 能否同时满足。判定口径有两条硬边界：chunk 过小则预填 kernel 启动开销占比升高，预填吞吐下降，单位时间能喂给解码侧的请求变少；chunk 过大则解码请求在预填侧排队，首 token 时延抬升。配比的目标是让预填侧在一个 chunk 的计算时间内产出足够解码侧消费的 KV，同时链路有空窗。写成伪代码思路：</p>\n<ul>\n<li>取解码侧单步时间 t<sub>dec</sub> 与单步 KV 传输时间 T<sub>step</sub>；</li>\n<li>令 chunk 计算时间 t<sub>chunk</sub> ≥ T<sub>step</sub>，使传输被计算掩盖；</li>\n<li>令 chunk 产出的 token 数不小于解码批在一个 t<sub>chunk</sub> 内消耗的 token 数，否则解码侧饥饿；</li>\n<li>若 t<sub>chunk</sub> 超出首 token 余量，则减小 chunk 并提高解码批，用批的吞吐补预填的粒度。</li>\n</ul>\n<p>代价体现在三处：chunk 小则预填侧 kernel 启动开销摊薄变差，功耗中固定开销占比上升；chunk 大则解码侧排队，尾时延抖动；批大则解码侧 KV 显存压力上升，与专家权重争抢。工程上把这三条边界画在同一张时间轴上，取交集即为可填区间。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-12\">十二 · 跨机架 SLO 差异与重叠的填法</h3>\n<p>第六列在不同链路下不是同一个量。同节点与机架内 NVLink 的首 token SLO 可以定紧，因为 T 落在余量内；跨机架 IB 的首 token SLO 必须放宽，而尾时延 SLO 要收紧，原因是 IB 的带宽抖动会通过 KV 到达时间传导到解码步。填表时把跨机架行的 SLO 目标写成“首 token 宽松、尾时延严”，并在传输时延预算列注明“重叠后计入残差”。重叠的具体机制是把 KV 传输拆成按层或按 chunk 的分片，在解码侧计算上一层时预取下一层 KV，使 T 只以残差形式进入关键路径；若不重叠，T 串行插入关键路径，首 token 时延随上下文长度线性恶化，这正是第三条失败模式。判定是否重叠成功的口径是：解码步时延的方差是否随 S 增长而扩大，若扩大则说明残差未被完全掩盖，应减小 chunk 或增加分片数。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-13\">十三 · 速查表背后的口径与失效边界</h3>\n<p>这张表不是配置模板，而是把分离式预填/解码的七个字段绑定成一套可核对的预算口径：链路决定有效带宽 <em>B</em>，单 token KV 字节与上下文长度共同决定传输量，chunk 大小与解码批大小共同决定两侧的排队形态，专家放置决定解码侧显存与 fabric 竞争，SLO 目标则是唯一不可协商的约束。填表时先算传输时间 <em>T</em>，再反推 chunk 与批的配比，而不是先定 chunk 再祈祷 SLO 达标。传输时间近似为 <em>T = S·L·H·d / B</em>，其中 <em>S</em> 为序列长度、<em>L</em> 为层数、<em>H</em> 为 KV 头数、<em>d</em> 为每头维度、<em>B</em> 为有效带宽；注意分子是每层 KV 的字节量乘以层数，分母必须是该链路在真实拥塞下的有效带宽，而非峰值带宽。</p>\n<table class=\"mini\"><thead><tr><th>链路</th><th>单 token KV 字节</th><th>chunk 大小</th><th>解码批大小</th><th>专家放置</th><th>SLO 目标</th><th>传输时延预算</th></tr></thead><tbody><tr><td>同节点 NVLink</td><td>按 L·H·d 实算</td><td>与批配比，避免 kernel 启动占比过高</td><td>连续批，维持低时延</td><td>按层切分</td><td>首 token 时延为主</td><td>可计入关键路径，余量最小</td></tr><tr><td>机架内 NVLink</td><td>同上</td><td>中等 chunk，平滑显存峰值</td><td>连续批，批间不空转</td><td>按层切分或按专家切分</td><td>首 token 与尾时延并重</td><td>需与解码计算部分重叠</td></tr><tr><td>跨机架 IB</td><td>同上</td><td>偏小 chunk，降低单次突发</td><td>批大小受 KV 到达抖动约束</td><td>避免全量复制到解码侧</td><td>尾时延优先</td><td>必须与解码计算重叠，否则线性恶化</td></tr></tbody></table>\n<p>专家放置是表中最容易被低估的一列。全量复制到解码侧会直接挤占 KV 容量，使解码侧可承载的并发序列数下降，等于用显存换掉了本可用于批调度的空间；专家只放在预填侧则解码每步都要远程取专家输出，All-to-All 与 KV 传输在同一 fabric 上叠加竞争，解码步时延被拉长；按层切分让两侧各持部分层专家，代价是跨层路由需要跨实例通信，这条通信同样要计入 <em>T</em> 的预算口径。工程判断是：跨机架 IB 场景优先按层切分并把专家输出取回与 KV 传输合并到同一重叠窗口，同节点 NVLink 场景才允许更激进的复制策略。</p>\n<p>失效条件集中在三处。其一，预填 chunk 与解码批配比失衡：长 chunk 占满链路，解码侧 KV 到达延迟抖动，尾时延超出 SLO；chunk 过小则预填 kernel 启动开销占比升高，预填吞吐塌陷。其二，专家只部署在预填侧而解码侧每步远程取输出，All-to-All 与 KV 传输争抢同一 fabric，解码步时延翻倍，此时表里的“传输时延预算”列必须按双倍流量重算。其三，跨机架 IB 传输未与解码计算重叠，KV 传输串行插入关键路径，首 token 时延随上下文长度线性恶化——这正是 <em>T</em> 公式中 <em>S</em> 线性增长的直接后果。填表时的硬口径是：任何一列的取值若使 <em>T</em> 落入关键路径且无重叠窗口，该行即判定为不可用配置，而非“调参后可接受”。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-14\">十四 · 速查表之外的边界：何时这张表会失效</h3>\n<p>速查表的每一行都隐含一个前提——KV 传输与解码计算可以被调度器当作两条独立流水。一旦这个前提被打破，表里的阈值就只剩参考意义。最典型的破口是预填侧 chunk 与解码侧批配比失衡：预填侧一个长 chunk 占满 NVLink 或 IB 链路，解码侧新到 token 的 KV 分片被排在其后，到达时间出现抖动，尾时延直接越过 SLO。判断是否越界不看均值，而看单 token KV 字节与链路有效带宽的比值是否已接近解码步计算时间；若传输时间与一步解码计算同量级，重叠窗口就被吃满，任何 chunk 抖动都会穿透到用户侧。</p>\n<div class=\"formula\">$$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B},\\qquad \\rho=\\frac{T}{t_{\\text{decode-step}}}$$</div>\n<p>把 ρ 作为速查表的隐藏列：ρ 远小于 1 时链路不是瓶颈，chunk 可放大以摊薄 kernel 启动开销；ρ 接近或超过 1 时，跨机架 IB 场景必须把 KV 传输切碎并与解码计算逐层重叠，否则首 token 时延随上下文长度线性恶化。同节点与机架内 NVLink 的 ρ 通常留有余量，跨机架 IB 则是先撞墙的那一档，表中该行的“传输时延预算”应理解为可被重叠隐藏的上限，而非可串行插入关键路径的额度。</p>\n<p>第二个失效条件是 MoE 专家放置与链路选择不匹配。专家全量复制到解码侧，权重挤占显存、KV 容量下降，表里“批大小”一列随之失真；专家只放预填侧，解码每步远程取专家输出，All-to-All 与 KV 传输在同一 fabric 上竞争，解码步时延成倍上升，此时无论 chunk 怎么调都救不回来。按层切分是折中，但跨层路由引入跨实例通信，需在表中把“专家放置”与“链路”两列绑定评估，不能各自独立取值。</p>\n<table class=\"mini\"><thead><tr><th>失效信号</th><th>口径</th><th>处置</th></tr></thead><tbody><tr><td>ρ 接近 1</td><td>单 token KV 字节 / 有效带宽 vs 解码步时间</td><td>缩小 chunk、逐层重叠传输</td></tr><tr><td>尾时延抖动</td><td>KV 到达间隔的 P99 而非均值</td><td>预填与解码链路配额隔离</td></tr><tr><td>解码步时延翻倍</td><td>All-to-All 与 KV 共用 fabric</td><td>专家放置改为按层切分或本地复制</td></tr></tbody></table>\n<p>工程判断落在配额上：给预填侧 chunk 设上限，使单次传输占用链路的时间不超过一个解码步的隐藏窗口；给解码侧批大小设下限，保证重叠窗口内始终有计算可填。跨机架场景若无法保证重叠，就应把该行从速查表降级为“仅同步路径可用”，并在容量规划中按串行时延计入首 token 预算。</p>\n<h3 id=\"ap-pd-disaggregation-sec-15\">十五 · 预填 chunk 的测量口径：把 kernel 启动开销折算成 token 成本</h3>\n<p>chunk 大小的阈值不是拍脑袋定的，它由两个可测的量夹出来：预填侧单 chunk 的固定开销，与解码侧等待 KV 到达的空转时长。预填侧固定开销包括计算图下发、TMEM 分配与 tcgen05 MMA 的流水填充，这部分与 chunk 内 token 数无关，因此 chunk 越小，摊到每 token 上的固定成本越高。测量方法是：固定序列长度与层数，扫一组 chunk 大小，记录预填侧每 chunk 的墙钟时间，对 chunk token 数做线性拟合，截距即固定开销、斜率即每 token 边际成本。判据是固定开销占单 chunk 总时间不超过一个可接受比例——这个比例由 SLO 中预填吞吐余量决定，余量越紧，允许的占比越低。</p>\n<div class=\"formula\">$$\\text{固定开销占比}=\\frac{t_0}{t_0+k\\cdot C}\\quad\\Rightarrow\\quad C_{\\min}=\\frac{t_0}{k}\\cdot\\frac{r}{1-r}$$</div>\n<p>其中 $$t_0$$ 为截距、$$k$$ 为每 token 边际时间、$$C$$ 为 chunk token 数、$$r$$ 为允许的固定开销占比上限。这个式子给的是下界：chunk 不能小到让 kernel 启动与流水填充吃掉预填算力。上界则来自解码侧——预填 chunk 越大，单次占用链路与显存峰值越久，解码请求的 KV 到达间隔抖动越大。上界的测量不在预填侧做，而在解码侧记录 KV 到达时间戳的分布，取 P99 到达间隔与 SLO 中解码步时延预算比较。两侧测量必须用同一套 trace 时间基准，否则拟合出的阈值不可信。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-16\">十六 · KV 传输预算的实测：有效带宽不是标称带宽</h3>\n<p>公式 $$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$ 里的 $$B$$ 是有效带宽，必须实测而非取链路标称值。测量方法：在预填与解码实例之间跑一次纯 KV 搬运（不夹带计算），按层分块发送，记录每层完成时间与总字节数，得到端到端有效带宽；再单独测单层小消息的往返时延，得到每层固定协议开销。两者结合才能判断某条链路是带宽受限还是时延受限。NVL72 内 NVLink 传输的每层固定开销小、有效带宽高，KV 传输时间基本由字节数决定；跨机架 IB 传输的每层固定开销显著，短上下文时固定开销占比高，长上下文时才转为带宽受限。</p>\n<p>工程判断的分界线由此得出：当 $$S\\cdot L\\cdot H\\cdot d$$ 折算出的传输时间小于解码侧单步计算时间时，KV 传输可以完全藏在解码计算背后，不进入关键路径；反之必须做重叠或分块流水。测量时要把解码侧单步时间与 KV 传输时间放在同一时间轴上比对，看两者是否真的重叠——很多部署名义上做了重叠，实际因流同步点位置不对而串行插入。代价体现在首 token 时延上：跨机架 IB 未重叠时，首 token 时延随上下文长度线性增长，这是可观测的斜率，斜率等于每 token KV 字节数除以有效带宽。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-17\">十七 · 预填 chunk 与解码批的配比：用排队指标而非平均值定阈值</h3>\n<p>配比失衡的失败模式是尾时延，不是均值。测量口径应取解码侧 KV 到达等待时间的 P99 与预填侧 chunk 队列深度的 P99，两者任一越界即配比不合适。具体机制：预填侧以 chunk 为单位排队，解码侧以步为单位消费 KV；当预填 chunk 占满链路时，解码侧某一步需要的 KV 被排在长 chunk 之后，该步等待时间出现尖峰。经验做法是给预填 chunk 设一个字节上限而非固定 token 数——因为不同上下文长度下每 token KV 字节不同，固定 token 数会让长上下文 chunk 的传输时间远超短上下文。字节上限由链路有效带宽乘以允许的单次占用时长得出，允许占用时长取解码步时延预算的一个分数。</p>\n<ul>\n<li>测预填侧：每 chunk 的墙钟时间、固定开销占比、chunk 队列深度 P99。</li>\n<li>测解码侧：KV 到达间隔 P99、单步时延 P99、批内 token 数分布。</li>\n<li>测链路：有效带宽、每层固定开销、重叠窗口内实际搬运字节数。</li>\n</ul>\n<p>这三个测量必须同时采集，缺一个就无法归因：只看预填吞吐会掩盖解码尾时延，只看解码均值会掩盖 chunk 排队尖峰。显存代价也在配比里：chunk 越大，预填侧激活峰值越高，若预填侧与解码侧共享节点显存，chunk 上限还要受解码侧 KV 容量约束——解码侧批越大，留给预填激活峰值的余量越小。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-18\">十八 · 专家放置的阈值判断：远程取专家输出的步时延代价</h3>\n<p>专家放置没有统一数字，但有明确的测量判据。若专家只部署在预填侧，解码侧每步都要远程取专家输出，该步时延由 All-to-All 往返加 KV 传输叠加构成。测量方法：在解码侧单步内插入时间戳，分别记录本地计算、All-to-All 发出、All-to-All 返回、KV 到达四个时刻，得到各段占比。判据是 All-to-All 段与 KV 传输段是否在同一 fabric 上竞争——若两者共享跨机架 IB，解码步时延会因竞争而翻倍，此时应把专家按层切分，让解码侧本地持有部分层的专家，把跨实例通信限制在层间而非每步。</p>\n<p>全量复制到解码侧的代价是显存：专家权重挤占 KV 容量，解码侧可维持的批大小下降，吞吐随之下降。测量方法是固定解码侧显存预算，扫专家复制比例，记录可维持的最大批大小与 KV 命中长度。按层切分的代价是跨层路由需跨实例通信，测量点是层间切换处的额外时延。三种放置的取舍最终落在同一个指标上：解码侧单步时延 P99 是否满足 SLO，以及在该时延下解码侧能维持多大批。功耗维度上，远程取专家输出意味着解码侧 NIC 与 fabric 持续活跃，而全量复制把功耗压到本地 HBM 访问，这是放置策略在功耗上的直接体现。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-19\">十九 · 跨机架与机架内的 SLO 差异：把时延预算拆到每层</h3>\n<p>NVL72 内 NVLink 与跨机架 IB 的 SLO 差异不能用一个总时延预算概括，必须拆到每层 KV 的传输预算。做法是：给定首 token 时延 SLO，减去预填计算时间与解码首步计算时间，剩余即 KV 传输总预算；再除以层数得到每层预算。机架内 NVLink 的每层预算通常远大于实际每层传输时间，余量可用于吸收抖动；跨机架 IB 的每层预算接近实际传输时间，余量薄，任何协议开销或竞争都会击穿预算。测量方法是逐层打时间戳，看哪一层的传输时间超出预算——超出的层就是需要做重叠或预取的目标层。</p>\n<p>重叠的具体机制是流水：预填侧完成第 $$i$$ 层即发送第 $$i$$ 层 KV，解码侧在第 $$i$$ 层计算开始前等待第 $$i$$ 层 KV 到达，两者以层为粒度流水，而非整段 KV 传完再解码。这样 KV 传输时间被解码计算掩盖，代价是解码侧需要为流水预留层缓冲，占用显存。跨机架场景下流水粒度还应更细，按头或按 token 分块，以降低单次消息的固定开销占比。判断流水是否生效的测量点：解码侧第 $$i$$ 层开始时刻与第 $$i$$ 层 KV 到达时刻的差值，若该差值稳定为正且小于单层计算时间，流水生效；若出现负值，说明解码侧在等 KV，流水未覆盖。</p>\n<table class=\"mini\"><thead><tr><th>测量对象</th><th>采集量</th><th>判据</th></tr></thead><tbody><tr><td>预填 chunk</td><td>固定开销占比、队列深度 P99</td><td>固定开销占比低于吞吐余量允许值</td></tr><tr><td>KV 链路</td><td>有效带宽、每层固定开销</td><td>传输时间可被解码单步计算掩盖</td></tr><tr><td>解码侧</td><td>KV 到达间隔 P99、单步时延 P99</td><td>尾时延不越 SLO</td></tr><tr><td>专家放置</td><td>All-to-All 段与 KV 段占比</td><td>两段不在同一 fabric 上竞争</td></tr></tbody></table>\n<p>最后落在工程判断上：阈值不是一次标定就固定的，上下文长度分布、批大小分布、专家路由倾斜都会移动有效带宽与固定开销的位置，因此这套测量应作为常驻观测而非一次性压测；当解码侧 KV 到达间隔 P99 开始抬升而预填吞吐未变时，先查链路有效带宽是否被同 fabric 上的 All-to-All 挤占，再查 chunk 字节上限是否因上下文变长而失效。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-20\">二十 · 阈值不是拍脑袋：把 chunk、批与链路代进同一条预算式</h3>\n<p>分离式预填/解码的工程阈值从来不是孤立参数，而是一组必须联立求解的约束。预填侧 chunk 大小决定单次计算图规模与显存峰值，解码侧批大小决定每步时延与吞吐，两者通过 KV 传输链路耦合。判断失衡的第一条准则是：把 KV 传输时间代进首 token 时延预算。用 $$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$ 估算单请求 KV 搬运代价，其中 S 为序列长度、L 为层数、H 为 KV 头数、d 为每头维度、B 为有效带宽。工程上先测出本集群在目标链路（同节点 NVLink、机架内 NVLink、跨机架 IB）上的有效带宽 B，再把 S 取为你 SLO 覆盖的最长上下文，算出 T；若 T 已经逼近首 token 时延预算的可分配份额，则跨机架 IB 场景必须把 KV 传输与解码计算重叠，否则这条链路就是硬边界。测量方法不是看峰值带宽标称值，而是用固定 L、H、d 的真实模型层做端到端 KV 搬运压测，记录从预填侧写完成到解码侧可读的完整时延分布，取 P99 而非均值作为预算输入。</p>\n<p>第二条准则是 chunk 与批的配比阈值。chunk 过小时，预填 kernel 启动开销在单次计算图中占比升高，预填吞吐被固定开销吃掉；chunk 过大时，预填侧长 chunk 占满链路，解码侧 KV 到达延迟出现抖动，尾时延超出 SLO。可操作的做法是测出预填侧单 chunk 的 kernel 启动开销占比曲线与解码侧每步时延随批大小的变化曲线，找到两条曲线的交点区间：在该区间内，预填吞吐满足目标、解码 P99 时延不越线。配比不是固定值，而是随上下文长度分布漂移的——长上下文请求占比升高时，应缩小 chunk 以平滑显存峰值，同时提高解码侧批调度对 KV 到达抖动的容忍度（例如在调度器中为跨实例 KV 预留到达窗口）。</p>\n<p>第三条准则是 MoE 专家放置的显存与 fabric 竞争阈值。专家全量复制到解码侧，解码侧显存被专家权重挤占、KV 容量下降，可承载的并发序列数随之下滑；专家只放在预填侧，解码每步都要远程取专家输出，All-to-All 与 KV 传输在同一 fabric 上竞争，解码步时延翻倍是典型失效形态。按层切分可让两侧各持部分层专家，但跨层路由需跨实例通信。判断阈值时，把解码侧可用 KV 容量与专家权重占用做显存账，把 All-to-All 流量与 KV 流量做 fabric 带宽账；两项账目任一越线，就应改放置策略而非调 chunk。测量方法是分别压测三种放置下的解码步时延分布与 fabric 利用率，观察 All-to-All 与 KV 是否在同一时间窗内叠加。</p>\n<table class=\"mini\"><thead><tr><th>链路</th><th>单 token KV 字节</th><th>chunk 大小</th><th>批大小</th><th>专家放置</th><th>SLO 目标</th><th>传输时延预算</th></tr></thead><tbody><tr><td>同节点 NVLink</td><td>由 L·H·d 决定</td><td>按 kernel 开销占比定</td><td>连续批调度</td><td>按层切分</td><td>首 token 时延</td><td>可被计算重叠隐藏</td></tr><tr><td>机架内 NVLink</td><td>同上</td><td>需与解码批配比</td><td>连续批调度</td><td>按层切分</td><td>首 token 与尾时延</td><td>部分重叠</td></tr><tr><td>跨机架 IB</td><td>同上</td><td>宜缩小以平滑峰值</td><td>需预留到达窗口</td><td>避免仅预填侧持有</td><td>首 token 时延</td><td>必须与解码计算重叠</td></tr></tbody></table>\n<p>失效条件的共同特征是“串行插入关键路径”。跨机架 IB 传输未与解码计算重叠时，KV 传输直接计入首 token 时延，且随上下文长度线性恶化；专家只部署在预填侧时，All-to-All 与 KV 在同一 fabric 上竞争，解码步时延翻倍。这两类失效都无法靠调 chunk 或批大小修复，只能改链路选择或放置策略。工程判断落在一条可测的准则上：在目标 SLO 下，先测出 KV 传输 P99 时延占首 token 预算的比例，再测出 All-to-All 与 KV 流量在同一 fabric 上的时间窗重叠度；比例越线或重叠度非零，就说明当前配比已到边界，应把解码侧专家放置改为按层切分或把跨机架链路替换为机架内 NVLink，而不是继续在 chunk 与批之间微调。</p>\n<h3 id=\"ap-pd-disaggregation-sec-21\">二十一 · 预填 chunk 与解码批配比失衡的链路占满坑</h3>\n<p>这是分离式 PD 部署里最常见、也最容易被误判为“网络抖动”的坑。预填侧为了压住单次计算图规模与显存峰值，会把长上下文切成 chunk 做 chunked prefill；解码侧用连续批调度维持步间低时延。两侧一旦配比失衡，预填侧连续发出的大 chunk 会在同一链路上形成突发，解码侧等待的 KV 分片被排到突发之后到达，表现为解码步时延的抖动，而平均时延看起来仍然正常——这是典型的尾时延超 SLO 而监控面板“健康”的形态。</p>\n<p>机制上，KV 传输时间由 <span class=\"formula\">$$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$</span> 给出，其中 S 为序列长度、L 为层数、H 为 KV 头数、d 为每头维度、B 为有效带宽。注意这里的 B 不是链路的空载带宽，而是被预填突发挤占后的有效带宽。当预填 chunk 变大，单次传输的 S 增大，T 线性增长；解码侧每个步都要等这一批 KV 到齐才能继续，于是 T 直接进入解码步的关键路径。chunk 过小则另一个方向的代价浮现：预填 kernel 启动开销占比升高，预填吞吐下降，预填队列积压反过来拉长首 token 时延。两个方向都不便宜，配比就是在这两者之间取一个让两侧同时满足 SLO 的点。</p>\n<p>检查顺序上，先看解码侧步时延的 P99 与预填侧 chunk 发出时刻的相关性：把两侧时间线对齐，若解码步时延尖峰总是紧跟预填 chunk 发出，基本可确认是链路争用而非计算问题。再看有效带宽的实际占用曲线，而不是链路标称带宽。具体例子：一个长上下文请求被切成若干 chunk 连续预填，解码侧此时正有若干活跃序列在跑连续批，若 chunk 发出节奏与解码步节奏没有错开，解码步就会周期性撞上传输窗口。工程判断是：chunk 大小必须与解码批调度配比设计，而不是各自独立调参；配比的目标函数是“预填吞吐满足 SLO 且解码尾时延不越界”，不是单侧最优。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-22\">二十二 · 专家只放预填侧导致 All-to-All 与 KV 争抢同一 fabric</h3>\n<p>MoE 模型在 PD 分离下的专家放置是第二个高频坑。三种放置各有代价：专家全量复制到解码侧，解码侧显存被专家权重挤占，KV 容量下降，长上下文场景直接压缩可驻留序列数；专家只放在预填侧，解码每步都要远程取专家输出，All-to-All 流量与 KV 传输叠加在同一 fabric 上；按层切分让两侧各持部分层专家，跨层路由需要跨实例通信。失败模式最尖锐的是第二种：解码侧每步远程取专家输出，All-to-All 与 KV 传输在同一 fabric 上竞争，解码步时延翻倍。</p>\n<p>伪代码层面的判断很直接：解码步的关键路径是“取本步 KV 分片 → 注意力 → 路由 → 取远程专家输出 → 合并”。当 KV 传输与 All-to-All 共用链路，两步的传输时间不是相加而是互相排队，有效带宽被两次切分。用上面的公式估算 KV 部分，再叠加 All-to-All 的激活字节量，就能看出这一步是否已经越过 SLO 预算。代价落在解码侧：步时延翻倍意味着解码批的有效吞吐下降，为了维持时延只能缩小批，进一步损失吞吐——这是一个自我强化的退化环。</p>\n<p>检查顺序：先确认解码侧每步是否存在远程专家调用，再看该调用的流量是否与 KV 传输走同一链路（同节点 NVLink、机架内 NVLink、跨机架 IB 三类的 SLO 差异很大）。具体例子：解码侧只持有注意力相关权重、专家全在预填侧，则每个解码步都要发起一次跨实例的专家取回，若这一步恰好与 KV 分片到达同窗口，两个传输互相等待。工程判断是：专家放置必须与 KV 链路预算一起算，不能把“省显存”当成唯一目标；按层切分虽然引入跨层路由通信，但把流量摊到两侧、避免单侧 fabric 被两类流量同时打满，往往是更稳的折中。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-23\">二十三 · 跨机架 IB 传输未与解码计算重叠</h3>\n<p>第三个坑是串行化。跨机架 IB 的时延与带宽劣于 NVL72 内 NVLink，这是链路分类的基本事实；真正致命的是把 KV 传输串行插入关键路径而不做重叠。失败模式写得很清楚：跨机架 IB 传输未与解码计算重叠，KV 传输串行插入关键路径，首 token 时延随上下文长度线性恶化。因为 T 正比于 S，上下文越长，这段串行时间越长，而它完全没有被计算掩盖。</p>\n<p>机制上，重叠的前提是解码侧在等待 KV 分片到达之前已经有可执行的计算——例如上一步的注意力或本步已到达分片的计算。若调度器把“等 KV 到齐”作为步的起点，重叠窗口就是零。检查顺序：先量出解码步中传输与计算的时间占比，若传输占比随上下文长度上升而计算占比不变，说明没有重叠；再看 KV 分片是否按层流水到达，逐层到达才能让“到达即计算”成立，整请求一次性到齐则必然串行。具体例子：一个跨机架部署的长上下文请求，首 token 时延由预填完成时刻加上整段 KV 传输时间构成，若这段传输没有与预填尾部的计算或解码首步的准备重叠，首 token 时延就随 S 线性增长，而机架内 NVLink 场景下这段传输被压得很短，同样的调度策略看不出问题——这就是“同代码跨机架才暴露”的坑。</p>\n<p>代价落在首 token 时延与链路利用率两侧：串行意味着链路在计算期间空闲、在等待期间满载，峰值带宽需求被抬高。工程判断是：跨机架场景必须把 KV 传输拆成可按层消费的分片并与解码计算交错，链路预算按“重叠后的剩余时延”算，而不是按传输总时间算。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-24\">二十四 · 检查清单与检查顺序</h3>\n<p>把上述坑收敛成一张按顺序执行的检查表，顺序本身有讲究：先排除链路争用，再看放置，最后看重叠，因为前两类问题会伪装成后一类。</p>\n<table class=\"mini\"><thead><tr><th>序</th><th>检查项</th><th>判据</th><th>代价落点</th></tr></thead><tbody>\n<tr><td>1</td><td>解码步 P99 与预填 chunk 发出时刻的相关性</td><td>尖峰紧跟 chunk 发出即为链路争用</td><td>尾时延、有效带宽</td></tr>\n<tr><td>2</td><td>有效带宽占用曲线 vs 标称带宽</td><td>突发期占用逼近上限</td><td>传输时延 T</td></tr>\n<tr><td>3</td><td>chunk 大小与解码批的配比</td><td>过小则 kernel 启动占比高，过大则解码排队</td><td>预填吞吐、首 token 时延</td></tr>\n<tr><td>4</td><td>解码侧是否存在每步远程专家调用</td><td>存在则 All-to-All 与 KV 同 fabric</td><td>解码步时延、显存</td></tr>\n<tr><td>5</td><td>专家放置模式（全量复制/按层/按专家）</td><td>复制挤占 KV 容量，单侧放置叠加流量</td><td>KV 容量、fabric 占用</td></tr>\n<tr><td>6</td><td>KV 分片是否按层流水到达</td><td>整请求到齐则无法重叠</td><td>首 token 时延</td></tr>\n<tr><td>7</td><td>跨机架 IB 传输与解码计算的重叠窗口</td><td>传输占比随 S 上升即未重叠</td><td>首 token 时延线性恶化</td></tr>\n</tbody></table>\n<p>每一项都要落到具体链路类型上判断：同节点 NVLink、机架内 NVLink、跨机架 IB 的 SLO 差异决定了同一现象在不同链路上的严重程度不同。检查时不要用平均时延做判据，尾时延才是 SLO 的约束面；也不要用标称带宽代替有效带宽，因为争用正是坑的核心。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-25\">二十五 · 回滚方案与降级路径</h3>\n<p>回滚不是“切回单体部署”一句话，而是按坑的类型选择最小回滚面，避免把已经获得的收益全部丢掉。针对配比失衡：把预填 chunk 调小并限制预填侧并发 chunk 数，让解码侧 KV 到达节奏可预测；代价是预填吞吐下降、预填队列变长，因此需要同时放宽预填侧的吞吐 SLO 或增加预填实例。针对专家只放预填侧：临时把热点专家复制到解码侧，用显存换 fabric 争用，代价是 KV 容量下降，需同步下调解码侧最大批或序列驻留数。针对跨机架串行：把请求调度回机架内 NVLink 链路，或把 KV 分片改为按层流水并在调度器里显式插入重叠窗口；前者牺牲部署灵活性，后者需要改调度逻辑，属于代码级回滚而非配置级。</p>\n<p>回滚的判据要事先定好，不能等尾时延爆了再讨论：以解码步 P99 与首 token 时延两个指标各自设阈值，任一越界即触发对应回滚项。具体例子：跨机架部署下首 token 时延随上下文长度线性上升并越过阈值，第一动作是把该流量切到机架内链路验证是否为传输串行所致，确认后再决定是改流水化还是保留链路切换。工程判断是：回滚方案必须与检查清单同序，先动配置项（chunk、并发、批大小、专家复制），再动调度逻辑（流水化、重叠窗口），最后才动拓扑（链路切换），因为越往后改动面越大、验证成本越高。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-26\">二十六 · 预填解码分离的失效边界与上线检查顺序</h3>\n<p>分离式预填/解码的失效很少来自单点性能不足，而是来自两侧配比失衡后关键路径被串行插入。最典型的失败模式是预填侧 chunk 过大：长 chunk 在计算图内占满 KV 传输链路，解码侧已排队的请求等不到 KV 到达，尾时延出现抖动并越过 SLO。检查顺序应从链路开始：先确认 KV 走的是同节点 NVLink、机架内 NVLink 还是跨机架 IB，再核对单 token KV 字节数（正比于层数、KV 头数与每头维度），用 <div class=\"formula\">$$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$</div> 估算一次传输的时间预算，其中 S 为序列长度、B 为有效带宽。跨机架 IB 场景必须把 KV 传输与解码计算重叠，否则传输时间直接计入首 token 时延，且随上下文长度线性恶化；这是回滚到同机架部署或缩短 chunk 的第一触发条件。</p>\n<p>第二类坑在 MoE 专家放置。专家全量复制到解码侧会挤占显存、压缩 KV 容量，长上下文下先崩的是 KV 池而非算力；专家只放预填侧则解码每步都要远程取专家输出，All-to-All 与 KV 传输在同一 fabric 上竞争，解码步时延成倍上升。按层切分是折中，但跨层路由引入跨实例通信，需单独计入步时延预算。上线前应固定一张检查表，按“链路—单 token KV 字节—chunk 大小—解码批大小—专家放置—SLO 目标—传输时延预算”逐列核对，任一行不满足即回退到上一版配比。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失效信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>预填 chunk 与解码批配比</td><td>尾时延抖动、KV 到达延迟不稳</td><td>缩小 chunk，恢复上一版批调度参数</td></tr><tr><td>专家放置</td><td>解码步时延翻倍、KV 池吃紧</td><td>改回按层切分或同侧全量复制</td></tr><tr><td>跨机架 IB 重叠</td><td>首 token 时延随上下文线性增长</td><td>切回机架内 NVLink 或启用传输计算重叠</td></tr></tbody></table>\n<p>回滚方案要按代价排序而非按直觉排序：先回滚 chunk 大小与解码批大小这一对软参数，它不改变拓扑、恢复最快；再回滚专家放置，涉及权重重新分布与显存重算；最后才回滚链路拓扑（跨机架 IB 退回机架内 NVLink），因为后者改变容量规划与实例数。chunk 过小时预填 kernel 启动开销占比升高、预填吞吐下降，这本身也是需要监控的反向信号，不能只朝一个方向调。判断标准落在具体机制上：只要 KV 传输仍串行插入解码关键路径、或 All-to-All 与 KV 共享同一 fabric 且无重叠，该配置就不具备上线资格。</p>\n<h3 id=\"ap-pd-disaggregation-sec-27\">二十七 · 上游依赖：KV 传输预算决定了本条目的一切参数</h3>\n<p>分离式预填解码不是一套自洽的方法论，它的每一个可调参数都由上游条目给出的物理量反向锁定。最直接的上游是 KV 传输带宽与时延预算：<div class=\"formula\">$$T=\\frac{S\\cdot L\\cdot H\\cdot d}{B}$$</div>其中 S 为序列长度、L 为层数、H 为 KV 头数、d 为每头维度、B 为有效带宽。这条式子在本条目里不是用来算一个数，而是用来做“预算切分”：给定 SLO 的首 token 时延上限，先扣掉预填侧 chunked prefill 的计算时间，剩下的才是 KV 传输可用的时间窗；把这个时间窗除以单 token KV 字节数，得到的是链路能承受的最大上下文长度，而不是反过来。因此本条目中“chunk 大小”“批大小”“专家放置”三列不是自由变量，而是被 T 的上界约束出来的因变量。上游若把 NVFP4/FP8 的 KV 量化做进去，单 token KV 字节数下降，T 同比缩小，预算表里就能容纳更长的 S 或更窄的链路——这是量化条目对本条目的直接传导，不需要在本条目重复量化的数值细节。</p>\n<p>第二个上游依赖是 tcgen05 与 TMEM 决定的单次计算图规模。预填侧 chunked prefill 的 chunk 大小之所以存在上限，根源在于一次 MMA 计算图在 TMEM 中的驻留与 2-SM MMA 的协作粒度：chunk 越大，单次 kernel 内的 tile 数与中间缓冲越大，显存峰值越陡。本条目在速查表中把 chunk 大小列为独立一列，正是因为它同时受“传输预算”和“计算图规模”两头夹击。工程代价很具体：chunk 过小，预填 kernel 启动开销占比升高，预填吞吐下降，单位 token 的功耗摊薄变差；chunk 过大，显存峰值抬高，挤占同实例上并存的 KV 容量，并且解码侧请求在链路排队。第三个上游是并行与通信条目：NVL72 内 NVLink 与跨机架 IB 的带宽差异直接改写 T 中的 B，进而改写“同节点/机架内/跨机架”这条分类维度的边界。链路一旦跨机架，B 下降，T 上升，重叠就从“可选优化”变成“必须项”。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-28\">二十八 · 下游影响：解码侧调度与 MoE 放置被本条目反向塑形</h3>\n<p>本条目向下游输出的第一个约束是解码侧连续批调度的批大小上限。解码侧要维持低时延，批大小受每步 KV 到达节奏约束：若预填侧以长 chunk 占满链路，解码侧每步等待 KV 到达的时间抖动增大，尾时延超出 SLO。于是解码侧的调度器不能只看自身队列深度，还要看预填侧的在途 chunk 队列——这是一个跨实例的背压信号。工程上表现为：解码侧批大小与预填侧 chunk 大小必须成配比调节，任何一侧单独调参都会破坏配比。代价落在两个指标上：批大小偏小则解码吞吐不足、GPU 利用率低；批大小偏大则单步时延抬高，SLO 被击穿。这条约束会传导到容量规划条目：容量因子不能按单实例算，必须按“预填实例数 : 解码实例数”的配比算，因为两侧的吞吐曲线形状不同。</p>\n<p>第二个下游影响是 MoE 专家放置策略。本条目给出的三种放置——全量复制、按层切分、按专家切分——各自向下游的 MoE 条目提出不同要求。全量复制到解码侧，解码侧显存被专家权重挤占，KV 容量下降，直接压缩了可容纳的并发序列数，等于把压力推回 KV 压缩条目；专家只放预填侧，解码每步远程取专家输出，All-to-All 与 KV 传输在同一 fabric 上竞争，解码步时延翻倍，这条失败模式把专家并行条目的 All-to-All 流量与本条目的 KV 流量绑定成同一个带宽池；按层切分则让两侧各持部分层专家，代价是跨层路由需要跨实例通信，路由倾斜尾延迟条目里的倾斜问题会在两个实例上分别出现并被放大。换言之，本条目不是替 MoE 做决定，而是把“专家放哪”变成一个受 KV 传输预算约束的联合优化问题。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-29\">二十九 · 与量化、KV 压缩条目的接口：字节数而非算法</h3>\n<p>本条目与量化条目的接口只有一个量：单 token KV 字节。NVFP4/FP8 权重激活条目关心的是计算侧的精度与吞吐，而本条目只关心它把 H·d 的有效位宽压到多少，从而把 T 的分母做大。接口的工程含义是：量化收益在分离式架构下被放大，因为省下的每一个字节都直接减少跨实例传输量；而在单体架构下，省字节只影响显存占用。反过来，量化后路由漂移条目提醒的风险在本条目里表现为“预填侧与解码侧精度路径不一致”——若两侧对 KV 采用不同量化策略，跨实例拼接的 KV 需要反量化或统一格式，这一步会插入关键路径，抵消部分带宽收益。KV 压缩条目同理：它压缩的是 S，本条目压缩的是 B 与字节宽度，两者在 T 的分子分母上各自发力，但压缩后的 KV 若需要解码侧额外解压计算，就把节省的传输时间换成了计算时间，是否净赚取决于解码侧是否有空闲算力。这是本条目在全书中的位置决定的：它处在“精度/压缩”与“调度/并行”之间的转换层，把前者的字节收益翻译成后者的时延预算。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-30\">三十 · 与框架条目的接口：谁实现配比，谁暴露背压</h3>\n<p>本条目描述的配比与背压必须由框架落地。TensorRT-LLM、vLLM、SGLang、Dynamo 在分离式部署上的差异，不在于是否支持拆实例，而在于是否把“预填 chunk 队列深度”作为解码侧调度器的输入信号暴露出来。若框架只提供两个独立实例、各自独立调度，配比失衡的失败模式就无法在运行时纠正，只能靠静态容量规划硬扛。NIXL 一类传输层决定 KV 传输能否与解码计算重叠：重叠的前提是传输被拆成可按层流水的小块，并在解码 kernel 执行期间异步推进；若传输层只提供整块同步语义，跨机架 IB 场景下 KV 传输就串行插入关键路径，首 token 时延随上下文长度线性恶化。工程判断是：选框架时先问“KV 传输是否按层可流水、是否有在途字节数的可观测指标”，再问吞吐。这条判断把本条目与框架选型条目接上，但结论方向相反——框架选型看功能矩阵，本条目看的是该框架是否暴露了配比调节所需的控制面。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-31\">三十一 · 在全书中的位置：从单实例算子到多实例系统的分界线</h3>\n<p>把全书条目按“优化对象”排开，算子与数值精度、显存与 KV cache、批调度属于单实例内的资源管理；并行与通信、分离式预填解码属于跨实例的系统编排；SLO 与容量规划、七个领域的推理形态属于需求侧。本条目正好站在分界线上：它把单实例条目产出的字节数、计算图规模、批调度策略当作输入，把跨实例的链路选择、专家放置、配比当作输出。这也解释了为什么本条目不能给出统一阈值——阈值是单实例条目的语言，而本条目处理的是两个实例之间的耦合，耦合的可行域由上游的 T 与下游的 SLO 共同围成。在七个领域的推理形态里，长上下文、高并发、MoE 三类负载最依赖本条目：长上下文把 S 推大，直接压 T 的分子；高并发把解码批大小推大，压 SLO 的余量；MoE 把专家放置变成必答题。三者叠加时，唯一可靠的工程动作是把 KV 传输与解码计算的重叠做成默认路径，并把预填 chunk 与解码批的配比做成可在线调节的旋钮，而不是离线定死的常数。</p>\n\n<h3 id=\"ap-pd-disaggregation-sec-32\">三十二 · 边界条件：链路层级、专家放置与配比失衡如何把分离式架构拖回串行</h3>\n<p>分离式预填/解码不是无条件的加速器，它的收益上界由三个耦合变量决定：KV 传输链路所处的物理层级、MoE 专家在两侧的驻留方式、以及预填 chunk 与解码批的配比。三者任一越界，系统就从“并行流水”退化为“串行关键路径”。以传输链路为例，同节点 NVLink、机架内 NVLink、跨机架 IB 三档的有效带宽 <em>B</em> 差异直接决定 KV 传输时间 <em>T</em>=<em>S</em>·<em>L</em>·<em>H</em>·<em>d</em>/<em>B</em> 是否可被解码计算掩盖。跨机架 IB 场景下，若未把 KV 传输与解码步重叠，<em>T</em> 会线性叠加进首 token 时延，上下文越长恶化越明显；此时唯一可行的工程手段是把 KV 分块流水化，让第 <em>i</em> 层的 KV 到达与第 <em>i</em>−1 层的解码计算在同一时间窗内完成，用计算时间做“隐式缓冲”。这条边界意味着：分离式架构在跨机架部署时的可行性，取决于解码侧单步计算时长能否覆盖单层 KV 的传输时延，而不是取决于总带宽的峰值数字。</p>\n<p>专家放置是第二条边界。全量复制到解码侧会把专家权重压进解码实例的显存，直接挤占 KV cache 容量，长上下文场景下可驻留的并发序列数下降，连续批调度失去腾挪空间；只放在预填侧则让解码每步都要远程取专家输出，All-to-All 通信与 KV 传输共享同一 fabric，两者竞争使解码步时延成倍上升。按层切分是折中，但跨层路由需要跨实例通信，路由表的维护成本与失败重试逻辑会侵入解码步的确定性。判断准则很直接：若解码侧每步的远程专家取数次数与 KV 传输次数在同一量级，两条流量在 fabric 上无法区分优先级，SLO 的尾时延必然抖动。</p>\n<p>配比失衡是最常见的失效模式。预填 chunk 过小，预填侧 kernel 启动开销占比升高，单位时间产出的 KV 块变少，解码侧排队；chunk 过大，预填侧长 chunk 占满链路，解码侧 KV 到达延迟出现抖动，尾时延越过 SLO。工程上应把 chunk 大小与解码批大小作为一对联合参数调优，使预填吞吐与解码时延同时落在目标区间，而不是各自独立取极值。</p>\n<table class=\"mini\"><thead><tr><th>链路</th><th>单 token KV 字节</th><th>chunk 大小</th><th>批大小</th><th>专家放置</th><th>SLO 目标</th><th>传输时延预算</th></tr></thead><tbody><tr><td>同节点 NVLink</td><td>正比于 L·H·d</td><td>中等</td><td>较大</td><td>按层切分</td><td>低首 token 时延</td><td>可被计算完全掩盖</td></tr><tr><td>机架内 NVLink</td><td>同上</td><td>中等偏小</td><td>中等</td><td>按层切分</td><td>首 token 与吞吐兼顾</td><td>需部分重叠</td></tr><tr><td>跨机架 IB</td><td>同上</td><td>小</td><td>小</td><td>预填侧为主</td><td>吞吐优先</td><td>必须与解码计算重叠</td></tr></tbody></table>\n<p>这张表的作用不是给出固定配置，而是标明每条链路下“传输时延预算”这一列的语义：同节点 NVLink 上预算是“可被掩盖”，跨机架 IB 上预算是“必须被掩盖”，两者的工程动作完全不同——前者可以容忍 chunk 偏大，后者必须把 chunk 压小并把 KV 传输拆到解码步之间。在全书中，本节处于上游“KV 传输带宽与时延预算”与下游“SLO 与容量规划”之间：上游给出 <em>T</em> 的解析式，本节给出该式在链路层级与专家放置约束下的适用边界，下游则据此把尾时延目标反解为 chunk 与批大小的可行域。任何容量规划若忽略这条边界，把跨机架 IB 的分离式部署按同节点 NVLink 的参数外推，得到的并发数与时延指标都会在真实负载下失效。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-pd-disaggregation\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>说明预填与解码分离后 KV 传输的带宽与时延预算、MoE 专家在两侧的放置策略、解码侧批调度与预填侧 chun…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-pd-disaggregation · 共 5 个片段</p>\n"},{"id":"ap-moe-profiler-tools","title":"MoE剖析工具链","summary":"列出 Nsight Systems/Compute 对分组 GEMM 与 All-to-All 的联合时间线采集方法、CUDA Graph 捕获下的 kernel 命名还原、NCCL 通信与计算重叠的可视化，以及自定义路由分布直方图与专家利用率采样的注入点。","kind":"工具","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-1\">一 · 条目边界：什么算“MoE 剖析工具链”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-2\">二 · 分类维度：四个正交轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-3\">三 · 与“性能分析”常识的区别：MoE 的联合时间线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-4\">四 · CUDA Graph 下的命名还原：条目成立的前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-5\">五 · 注入点的位置与代价：路由直方图与专家利用率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-6\">六 · 产物形态与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-7\">七 · 边界条件：工具链在什么情况下会失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-8\">八 · 速查表的列语义与口径约定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-9\">九 · 系统级时间线：四段同轴与重叠判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-10\">十 · CUDA Graph 捕获下的名称还原</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-11\">十一 · 自定义注入点：直方图与利用率采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-12\">十二 · 联合采集的字段对照表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-13\">十三 · 采集前置检查与失败模式对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-14\">十四 · 速查表的适用边界：什么时候这张表会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-15\">十五 · 阈值从哪来：先定判据，再定数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-16\">十六 · 重叠判定的三个反例与采集前置条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-17\">十七 · 专家负载倾斜：用直方图定丢弃边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-18\">十八 · 单 kernel 效率：分组 GEMM 的测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-19\">十九 · 注入点开销的自检：先证明测量不改时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-20\">二十 · 阈值不是拍脑袋：从时间线对齐到注入点开销的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-21\">二十一 · 捕获顺序与命名还原：先标注，再捕获，最后过滤</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-22\">二十二 · 注入点的位置与开销：放在 top-k 之后、分组 GEMM 之前</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-23\">二十三 · 联合时间线的读法：NCCL 事件与 SM 占用同轴对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-24\">二十四 · 踩坑清单：按失败模式归类，逐条给检查动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-25\">二十五 · 检查顺序：从系统级到 kernel 级，从无注入到有注入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-26\">二十六 · 回滚方案：把采集配置当作可版本化的产物</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-27\">二十七 · 上游依赖：剖析链路的输入契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-28\">二十八 · 下游影响：谁在消费剖析结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-29\">二十九 · 与 CUDA Graph 条目的耦合面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-30\">三十 · 与通信条目的边界划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-31\">三十一 · 在全书中的位置：从观测到决策的接口层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-profiler-tools-sec-32\">三十二 · 边界条件：工具链在什么情况下会给出错误结论</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-moe-profiler-tools\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 303\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"66.9\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"45.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"49.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：MoE剖析工具链</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">列出 Nsight Systems/Compute 对分组 GEMM 与 Al…</text><line x1=\"82.0\" y1=\"80.9\" x2=\"82.0\" y2=\"97.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 96.9 L 86.5 96.9 L 82.0 104.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"104.9\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"127.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"131.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"132.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"151.8\" x2=\"82.0\" y2=\"168.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 167.8 L 86.5 167.8 L 82.0 175.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"175.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"198.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"202.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"203.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"222.6\" x2=\"82.0\" y2=\"239.6\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 238.6 L 86.5 238.6 L 82.0 246.6 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"246.6\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"269.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"273.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"274.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-moe-profiler-tools-sec-1\">一 · 条目边界：什么算“MoE 剖析工具链”</h3>\n<p>本卷把“MoE 剖析工具链”限定为一个可交付的工程对象：它由采集器、事件对齐层、注入点与产物格式四部分组成，目标是在一次真实推理服务的时间窗内，同时拿到<strong>系统级时间线</strong>与<strong>kernel 级指标</strong>，并把 MoE 特有的四个阶段——路由 kernel、分组 GEMM、All-to-All、反量化 kernel——落到同一根时间轴上。判定一个工具是否属于本条目，看它能否回答三个问题：分组 GEMM 与 All-to-All 是否重叠、重叠被谁打断、路由分布是否让某个专家的分组 GEMM 变成关键路径。只能给出单 kernel 指令指标的 Nsight Compute 单独使用不算完整条目，因为它缺少 NCCL 通信事件，无法判断通信是否被计算隐藏；只能给出整图执行时长的 CUDA Graph 回放时间线也不算，因为图节点编号折叠后无法区分阶段归属。</p>\n<p>与相邻概念的边界要划清。路由术语（top-k、容量因子、丢弃）属于语义层，本条目只消费其输出计数，不重新定义；专家并行与 All-to-All 属于并行策略层，本条目只观测其时间区间与 SM 占用，不设计切分方案；分组 GEMM 与 tcgen05 属于算子实现层，本条目只读取其 kernel 符号与占用率。换句话说，工具链是<strong>观测面</strong>，不是策略面：它不改路由、不改并行度、不改精度，只保证测到的东西代表真实部署时序。</p>\n<p>代价上，剖析本身要付费。系统级时间线采集的固有开销来自事件缓冲与 flush，量级随采集窗口线性增长；kernel 级指标采集需要 replay kernel，吞吐会显著下降，因此不能与在线服务同窗长时间并行。工程判断是：系统级时间线用于常态观测，kernel 级指标用于定点复现，两者分窗采集，再按 NVTX 范围与时间戳对齐，而不是一次抓全。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-2\">二 · 分类维度：四个正交轴</h3>\n<p>把工具按四个轴分类，可以避免“工具名罗列”式的速查表。第一轴是<strong>采集层级</strong>：系统级时间线（CPU/GPU 活动、NCCL 通信事件、跨流依赖）与 kernel 级指标（指令吞吐、访存、SM 占用）。第二轴是<strong>是否启用 CUDA Graph</strong>：图捕获前后的时间线语义不同，捕获后 kernel 名可能折叠为图节点编号，必须靠捕获前的 NVTX 标注或保留符号表映射还原。第三轴是<strong>通信库事件</strong>：是否接入 NCCL 事件，决定能否把 All-to-All 的发送/接收区间画到与分组 GEMM 同一根轴上。第四轴是<strong>自定义注入点</strong>：路由分布直方图与专家利用率采样是否可插桩，插在哪。</p>\n<table class=\"mini\"><thead><tr><th>工具</th><th>采集对象</th><th>时间分辨率</th><th>Graph 捕获</th><th>注入点</th><th>输出格式</th><th>开销</th></tr></thead><tbody>\n<tr><td>Nsight Systems</td><td>CPU/GPU 时间线、NCCL 事件</td><td>事件级，跨流对齐</td><td>需 NVTX/符号映射还原</td><td>无原生，靠 NVTX 包裹</td><td>时间线报告</td><td>随窗口线性增长</td></tr>\n<tr><td>Nsight Compute</td><td>单 kernel 指令与访存</td><td>kernel 级，需 replay</td><td>可对图内节点采集</td><td>无</td><td>kernel 报告</td><td>高，吞吐显著下降</td></tr>\n<tr><td>NCCL 事件接入</td><td>All-to-All 收发区间</td><td>通信区间级</td><td>与图节点对齐</td><td>无</td><td>与时间线合并</td><td>低</td></tr>\n<tr><td>自定义直方图</td><td>每专家 token 计数、路由分数</td><td>按步抽样</td><td>需在图外或图内固定位置</td><td>softmax/top-k 之后、分组 GEMM 之前</td><td>计数/分布</td><td>低开销需抽样</td></tr>\n</tbody></table>\n<p>四个轴正交，意味着“Nsight Systems + NCCL 事件 + 图外 NVTX 标注”与“Nsight Compute + 图内节点”是两种不同产物，不能互相替代。分类的目的是让读者在选型时先问：我要回答的是重叠问题（第一、三轴）还是单 kernel 效率问题（第一轴的另一半），以及我的服务是否跑在 CUDA Graph 下（第二轴）。</p>\n<p>代价示例：一次解码步内，若 All-to-All 未被分组 GEMM 隐藏，它会直接暴露为步时延的一部分；此时系统级时间线能看出空泡位置，而 kernel 级指标只能告诉你分组 GEMM 本身很快——两者结论相反，正是分类轴存在的理由。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-3\">三 · 与“性能分析”常识的区别：MoE 的联合时间线</h3>\n<p>通用性能分析关心“哪个 kernel 最慢”，MoE 剖析关心“阶段之间是否重叠”。前者是排序问题，后者是<strong>区间代数</strong>问题：把路由 kernel、分组 GEMM、All-to-All、反量化 kernel 各自的起止区间投影到同一轴，求交与求差。设分组 GEMM 的 SM 占用区间集合为 $G$，All-to-All 的收发区间集合为 $C$，则暴露的通信时间为</p>\n<div class=\"formula\">$$T_{\\text{exposed}} = \\left| \\bigcup_{c \\in C} c \\setminus \\bigcup_{g \\in G} g \\right|$$</div>\n<p>这个式子说明：只看 All-to-All 总时长会高估代价，只看分组 GEMM 总时长会低估代价，必须做区间差。工程上，这要求采集器把 NCCL 事件与 kernel 时间线按同一时钟对齐，并把 SM 占用画成与通信区间同轴的色带。材料未给出具体重叠比例阈值，领域经验是重叠不足时 All-to-All 直接暴露为解码步时延，因此判断标准不是“重叠率多少”，而是“暴露区间是否落在关键路径上”。</p>\n<p>具体例子：一个解码步内，路由 kernel 先产生 token 到专家的映射，随后分组 GEMM 按专家分组计算，中间插入 All-to-All 把 token 送往持有专家的设备，返回后再反量化。若时间线显示 All-to-All 的接收区间与下一段分组 GEMM 的 SM 占用完全错开，则这一步的时延由通信主导；若两者部分交叠，则要检查交叠段内分组 GEMM 的 SM 占用是否被通信的 SM 抢占稀释。后者只有联合时间线能看出，单 kernel 报告看不出。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-4\">四 · CUDA Graph 下的命名还原：条目成立的前提</h3>\n<p>CUDA Graph 捕获后，kernel 名称可能被折叠为图节点编号，图回放时间线只剩整图执行时长。此时按 kernel 名过滤会失效，分组 GEMM 与 All-to-All 无法区分，时间线分析直接归零。这是本条目最典型的失败模式，也是分类轴第二轴存在的根本原因。</p>\n<p>还原手段有两条：其一，在捕获前用 NVTX 范围标注路由、分组 GEMM、All-to-All 阶段，使图节点携带范围标签；其二，在捕获时保留 kernel 符号表映射，把节点编号反查回符号。伪代码思路是：捕获前对每个阶段包一层 <code>nvtxRangePush</code>，捕获后在图实例化时记录节点到符号的映射表，回放时用映射表把节点编号翻译成阶段名，再与 NCCL 事件对齐。两条路都不做，就只能看到整图时长。</p>\n<p>代价上，NVTX 包裹本身开销低，但范围粒度过细会膨胀事件缓冲；符号表映射需要额外的实例化期记录，属于一次性成本。工程判断：图捕获路径下，剖析产物的可信度取决于捕获前是否埋好标注，而不是回放后是否努力分析——埋点在前，分析在后。</p>\n<p>具体例子：同一服务在 eager 模式下时间线清晰可读，切到 CUDA Graph 后所有节点变成编号，若捕获前未埋 NVTX，则无法回答“这一步 All-to-All 是否被分组 GEMM 隐藏”；补救只能重新捕获并埋点，已采集的数据不可逆。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-5\">五 · 注入点的位置与代价：路由直方图与专家利用率</h3>\n<p>自定义注入点是本条目区别于通用工具的部分。路由分布直方图与专家利用率采样的正确位置在<strong>路由 softmax/top-k 之后、分组 GEMM 之前</strong>：此处已确定每个 token 归属哪些专家，记录每专家 token 计数与路由分数分布，可发现专家负载倾斜；放在 top-k 之前则拿到的是未归一化的分数，无法对应到实际分组。</p>\n<p>注入的代价必须可控。逐 token 同步写回会引入主机同步与额外 kernel，测得的时间线不再代表真实部署时序——这是第二个典型失败模式。可行做法是按步抽样而非逐 token：每 N 步抽一步，在设备侧聚合计数后一次性拷回，避免每 token 一次同步。设采样步数为 $s$、总步数为 $S$，注入开销近似正比于 $s/S$，抽样率的选择由“能否稳定看出倾斜”决定，而非由“能否拿到全量”决定。</p>\n<p>具体例子：某专家在连续若干步内 token 计数显著高于其他专家，直方图在 top-k 之后立刻可见；若注入点在 top-k 之前，看到的只是分数分布，无法判断该专家是否真的被选中，负载倾斜结论不成立。代价上，抽样注入的额外 kernel 会占用少量 SM，若与分组 GEMM 同流，需确认它没有把关键路径拉长——这正是注入点必须低开销的原因。</p>\n<p>与相邻概念的边界再强调一次：容量因子与丢弃代价讲的是“丢弃多少”，本条目讲的是“怎么测到丢弃发生在哪”；量化后路由漂移讲的是“分布变了”，本条目讲的是“用什么注入点看到它变了”。工具链不解释现象，只保证现象可被观测。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-6\">六 · 产物形态与工程判断</h3>\n<p>条目最终交付的产物不是一张图，而是三份可对齐的记录：系统级时间线（含 NCCL 事件与 NVTX 范围）、kernel 级指标（定点复现时采集）、注入点计数（按步抽样）。三者的对齐键是时间戳与阶段标签，缺一不可。只采集 Nsight Compute 单 kernel 指标而缺少系统级 NCCL 事件，会把通信暴露误判为计算瓶颈；只采集时间线而缺少注入点，则看不出负载倾斜与关键路径的因果关系。</p>\n<p>工程判断落在采集顺序上：先在 eager 或带 NVTX 的图捕获下拿系统级时间线，确认分组 GEMM 与 All-to-All 的重叠关系；再对可疑 kernel 做定点 kernel 级采集；注入点全程按步抽样常开，作为负载倾斜的常态信号。三者分窗，不互相污染时序。产物格式上，速查表必须带“是否支持 Graph 捕获”与“注入点”两列，否则选型时会重复踩命名折叠与同步写回两个坑。</p>\n<p>最后落在具体机制：注入点的设备侧聚合与一次性拷回，是把“观测”与“被测时序”解耦的关键——聚合在设备完成，主机只在抽样步边界同步一次，时间线因此保留真实部署的形状；若这一步做错，后面所有区间代数都建立在被观测行为改变过的数据上，结论不可用。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-7\">七 · 边界条件：工具链在什么情况下会失真</h3>\n<p>这套工具链的有效性有明确前提：采集必须发生在部署形态的时序路径上，且阶段归属必须可还原。两个条件任一被破坏，产出就不是“更细的观测”，而是另一条时间线。最典型的失效是 CUDA Graph 捕获后的名称折叠——图回放时 kernel 名被替换为图节点编号，按名称过滤分组 GEMM 与 All-to-All 会直接落空，时间线上只剩整图执行时长，重叠关系无从判断。规避方式只有两条：捕获前用 NVTX 范围把路由、分组 GEMM、All-to-All、反量化逐段标注，或在捕获时保留 kernel 符号表映射。代价是 NVTX 区间本身进入图结构，标注粒度过细会抬高图节点数，回放时的调度开销与显存占用同步上升，因此标注应停在阶段级而非算子级。</p>\n<p>第二个边界在注入点位置。路由直方图与专家利用率采样必须落在 softmax/top-k 之后、分组 GEMM 之前：此处既能拿到每专家 token 计数，也能拿到路由分数分布，用于识别专家负载倾斜。若把注入放到 top-k 之前，观测到的是未裁剪的分数分布，与真实分组形态不符；若逐 token 同步写回主机，则引入主机同步与额外 kernel，测得的时间线已不代表部署时序。采样应按步抽样而非逐 token，把注入开销压到相对解码步时延可忽略的量级。设单步注入开销为 <span class=\"inline-math\">$t_{inj}$</span>、解码步时延为 <span class=\"inline-math\">$T_{step}$</span>，则失真判据可写为</p>\n<div class=\"formula\">$$ \\varepsilon = \\frac{t_{inj}}{T_{step}},\\qquad \\varepsilon \\ll 1 \\text{ 才可视为无扰观测} $$</div>\n<p>第三个边界是采集层级的错配。只跑 Nsight Compute 拿单 kernel 的指令与访存指标，缺少系统级 NCCL 事件，就无法把 All-to-All 的发送/接收区间与分组 GEMM 的 SM 占用画在同一轴上，也就无法判断通信是否被计算隐藏；此时把通信暴露误读为计算瓶颈是常见误判。联合采集的必要性正来自此：Nsight Systems 给 CPU/GPU 时间线与 NCCL 通信事件，Nsight Compute 给单 kernel 微观指标，两者缺一，MoE 的“计算—通信—空泡”三元结构就无法闭合。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测后果</th><th>系统代价</th></tr></thead><tbody><tr><td>Graph 捕获后按名过滤</td><td>阶段归属丢失，仅剩整图时长</td><td>需重跑采集，图回放调度开销上升</td></tr><tr><td>注入点前置或逐 token 同步</td><td>时间线被观测行为改写</td><td>主机同步与额外 kernel 抬高步时延</td></tr><tr><td>仅有 kernel 级指标</td><td>无法判定通信重叠</td><td>误判瓶颈，容量规划偏离</td></tr></tbody></table>\n<h3 id=\"ap-moe-profiler-tools-sec-8\">八 · 速查表的列语义与口径约定</h3>\n<p>这张表不是工具清单，而是采集口径的契约。七列的定义必须先在团队内对齐，否则不同人跑出来的时间线无法互相印证。工具列只写实际承担采集的组件（Nsight Systems、Nsight Compute、NCCL 事件通道、自定义注入点）；采集对象列必须落到具体阶段名——路由 kernel、分组 GEMM、All-to-All、反量化 kernel，四者缺一不可，因为 MoE 解码步的时延归属正是在这四段之间转移的。时间分辨率列区分两种口径：系统级时间线以事件时间戳对齐，kernel 级指标以采样周期为单位，两者不可混用于同一张重叠图。是否支持 Graph 捕获列只有“原生”“需 NVTX 标注”“不支持”三种取值，任何模糊表述都会导致后续过滤失效。注入点列写清代码位置（如路由 softmax/top-k 之后、分组 GEMM 之前），输出格式列写清是时间线文件、指标表还是直方图序列，开销列则必须给出对被测步时延的相对影响量级，而不是“低开销”这类形容词。</p>\n<p>口径上有一条硬约束：同一份速查表内，所有“开销”必须相对于同一基线步时延测量。若基线取自未注入的纯解码步，而注入项按步抽样，则开销列反映的是抽样频率的函数，而非注入点本身的成本。工程上把开销拆成两项记录更稳：注入代码路径的固定成本，以及采样频率带来的可变成本。前者决定能否常开，后者决定采样窗口长度。用公式表达采样预算：</p>\n<div class=\"formula\">$$C_{\\text{inject}} = c_0 + \\frac{N_{\\text{sample}}}{N_{\\text{step}}} \\cdot c_s$$</div>\n<p>其中 c₀ 为注入点固定成本，c_s 为单次采样成本，N_sample/N_step 为抽样比例。速查表要求填的是使 C_inject 低于步时延预算某一比例时的最大抽样比例，这个比例才是可照抄的参数。举例：某 MoE 解码步以分组 GEMM 与 All-to-All 交替为主，若逐 token 同步写回直方图，注入会插入主机同步并额外启动 kernel，测得时间线已不代表部署时序；改为按步抽样后，固定成本与可变成本分离，速查表里“按步抽样、比例上限”一栏才有意义。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-9\">九 · 系统级时间线：四段同轴与重叠判定</h3>\n<p>Nsight Systems 承担的是系统级时间线，其价值不在单 kernel 细节，而在把路由 kernel、分组 GEMM、All-to-All、反量化 kernel 放进同一时间轴。判定通信是否被计算隐藏，靠的是把 All-to-All 的发送/接收区间与分组 GEMM 的 SM 占用画在同一轴上，观察两者是否在时间上真正交叠。这里不需要具体重叠比例阈值——材料未给出，领域经验是重叠不足时 All-to-All 直接暴露为解码步时延。因此速查表在“采集对象”列对系统级时间线的要求是：必须同时勾选 NCCL 通信事件与计算 kernel，缺一不可。</p>\n<p>失败模式很明确：只采集 Nsight Compute 单 kernel 指标而缺少系统级 NCCL 事件，就无法判断 All-to-All 是否与分组 GEMM 重叠，容易把通信暴露误判为计算瓶颈，进而把优化资源投到错误的算子上。速查表应把这一条写成采集前置检查项，而不是事后分析建议。代价层面，系统级时间线的开销主要来自事件记录与缓冲区写入，对长序列采集会占用可观的主机内存与磁盘带宽；工程判断是按解码步窗口采集而非全程常开，窗口长度以覆盖若干个完整的“路由—GEMM—通信—反量化”循环为准。</p>\n<p>具体例子：一个专家并行度较高的解码步中，分组 GEMM 的 SM 占用呈锯齿状，All-to-All 区间若完全落在锯齿间隙之外，则时间线上表现为一段无计算覆盖的通信条带；此时速查表的“重叠判定”列应记录为“通信暴露”，并把后续采集重点转向通信库事件通道，而不是继续加深 kernel 级指标。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-10\">十 · CUDA Graph 捕获下的名称还原</h3>\n<p>启用 CUDA Graph 后，kernel 名称可能被折叠为图节点编号，按 kernel 名过滤直接失效——这是速查表“是否支持 Graph 捕获”列必须存在的根本原因。还原路径有两条：捕获前用 NVTX 范围标注路由、分组 GEMM、All-to-All 阶段，使图回放时间线中保留阶段归属；或在捕获时保留 kernel 符号表映射，把节点编号反查回符号。两条路径在速查表中对应不同的注入点列取值：前者注入点在阶段边界，后者注入点在捕获配置。</p>\n<p>失败模式是捕获后才尝试按 kernel 名过滤，此时名称已折叠，分组 GEMM 与 All-to-All 无法区分，整条时间线只剩整图执行时长，重叠关系彻底丢失。工程上把这条写成捕获前的强制检查：先确认 NVTX 范围覆盖四段，再启动捕获。伪代码思路如下：</p>\n<ul>\n<li>在路由入口压入 NVTX 范围，在分组 GEMM 与 All-to-All 调用处各自压入独立范围，反量化 kernel 单独标注；</li>\n<li>捕获阶段保持这些范围不被优化掉，回放时按范围名而非 kernel 名聚合；</li>\n<li>若采用符号表映射路径，则在捕获配置中登记节点编号到阶段名的映射表，回放后按表还原。</li>\n</ul>\n<p>代价上，Graph 回放本身降低了启动开销，但名称还原的元数据会增大图对象的常驻内存；速查表“开销”列应记录为“图对象内存增量”，并注明该增量与图节点数成正比。具体例子：一个包含路由、两组分组 GEMM、一次 All-to-All、一次反量化的图，若未标注 NVTX，回放时间线上只能看到一段连续执行条带，无法回答“All-to-All 是否被前一组 GEMM 隐藏”这个问题；标注后同一张图可拆出四段，重叠判定才成立。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-11\">十一 · 自定义注入点：直方图与利用率采样</h3>\n<p>路由分布直方图与专家利用率采样的注入点必须放在路由 softmax/top-k 之后、分组 GEMM 之前。此处记录每专家的 token 计数与路由分数分布，才能发现专家负载倾斜；放在 top-k 之前则统计的是未裁剪的分数分布，与真实分组 GEMM 的输入不符。采样需低开销，按步抽样而非逐 token，否则注入本身改变时序——逐 token 同步写回会引入主机同步与额外 kernel，测得的时间线不再代表真实部署时序。</p>\n<p>速查表在这一行要填三个字段：注入点代码位置、抽样粒度、写回方式。写回方式必须是异步或批量落盘，禁止在关键路径上做同步写。专家利用率的统计口径也要固定：分子是该专家实际处理的 token 数，分母是本步参与路由的 token 总数，得到每专家占比；直方图则按路由分数分桶。代价上，按步抽样的注入对步时延的影响主要来自固定成本 c₀，而逐 token 采样的可变成本会随 token 数线性增长，在长上下文解码中足以淹没被观测的信号。具体例子：某步路由分数分布呈双峰，直方图在 top-k 之后采集显示被选中的专家集中在少数几个桶，而 top-k 之前采集则显示分数均匀——两者结论相反，说明注入点位置直接决定倾斜判定的真伪。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-12\">十二 · 联合采集的字段对照表</h3>\n<p>下表把七列落到可直接照抄的取值，供采集脚本与评审清单共用。表中不写具体数字阈值，只写口径与判定方式，因为材料未给出重叠比例等定量阈值，任何填入的数字都会变成伪事实。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>工具</th><th>采集对象</th><th>时间分辨率</th><th>Graph 捕获</th><th>注入点</th><th>输出格式</th><th>开销口径</th></tr>\n</thead>\n<tbody>\n<tr><td>Nsight Systems</td><td>路由 kernel、分组 GEMM、All-to-All、反量化 kernel 同轴</td><td>事件时间戳对齐</td><td>需 NVTX 标注</td><td>阶段边界 NVTX 范围</td><td>时间线文件</td><td>事件缓冲与落盘带宽，按窗口采集</td></tr>\n<tr><td>Nsight Compute</td><td>单 kernel 指令与访存指标</td><td>采样周期</td><td>不支持图内聚合</td><td>kernel 启动点</td><td>指标表</td><td>单 kernel 重放，改变时序，仅离线用</td></tr>\n<tr><td>NCCL 事件通道</td><td>All-to-All 发送/接收区间</td><td>事件时间戳</td><td>原生</td><td>通信库回调</td><td>事件序列</td><td>事件记录固定成本</td></tr>\n<tr><td>自定义注入点</td><td>每专家 token 计数、路由分数直方图</td><td>按步抽样</td><td>需在图外或标注后注入</td><td>softmax/top-k 之后、分组 GEMM 之前</td><td>直方图序列</td><td>c₀ 固定 + 抽样比例×c_s</td></tr>\n</tbody>\n</table>\n<p>读表方式是按行取用、按列对齐：同一分析任务必须同时取系统级时间线行与 NCCL 事件行，否则重叠判定缺一半证据；kernel 级指标行只在定位到具体算子后使用，且必须承认其重放会改变时序。自定义注入点行与系统级时间线行可并行开启，但抽样比例要按第一节的预算公式约束，避免注入成本污染时间线。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-13\">十三 · 采集前置检查与失败模式对照</h3>\n<p>速查表落地时，前置检查比事后分析更省工。检查项按顺序执行：确认四段阶段名在代码中可标注；确认 Graph 捕获前 NVTX 范围已覆盖四段；确认 NCCL 事件通道与计算 kernel 同时开启；确认路由直方图注入点在 top-k 之后且写回异步；确认抽样比例满足注入预算。任一项不满足，后续时间线分析都不可信。</p>\n<p>失败模式对照可直接写进评审清单：捕获后按 kernel 名过滤导致分组 GEMM 与 All-to-All 不可区分；注入点放在 top-k 之前或逐 token 同步写回引入主机同步与额外 kernel；只采集单 kernel 指标而缺 NCCL 事件导致通信暴露被误判为计算瓶颈。三条失败模式分别对应速查表的 Graph 捕获列、注入点列与采集对象列，说明这三列不是可选项而是判定链的关节。工程判断落在最后一条：当时间线上出现无计算覆盖的通信条带时，先补 NCCL 事件与系统级时间线的联合采集，再决定是否加深 kernel 级指标，顺序颠倒会把优化预算花在错误的算子上。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-14\">十四 · 速查表的适用边界：什么时候这张表会骗你</h3>\n<p>速查表按「采集层级 × 是否启用 CUDA Graph × 通信库事件 × 自定义注入点」四维展开，列固定为工具、采集对象、时间分辨率、Graph 捕获支持、注入点、输出格式、开销。它的适用前提是：路由 kernel、分组 GEMM、All-to-All、反量化 kernel 能被放进同一条时间轴且各自可命名。一旦进入 CUDA Graph 回放路径，这个前提就失效——kernel 名被折叠为图节点编号，按名过滤只能得到整图时长，分组 GEMM 与 All-to-All 的重叠关系不可见。此时速查表的正确用法是回退到捕获前的 NVTX 范围标注，或在捕获时保留符号表映射，把「是否支持 Graph 捕获」一列当作硬门槛而非参考项。</p>\n<p>注入点的位置决定了表里所有时间数字的可信度。路由直方图与专家利用率采样必须落在 softmax/top-k 之后、分组 GEMM 之前，且按步抽样而非逐 token 同步写回；放到 top-k 之前或逐 token 写回会引入主机同步与额外 kernel，测得的时间线不再代表部署时序。设单步注入开销为 <span class=\"formula\">$$T_{inj}$$</span>，真实解码步时延为 <span class=\"formula\">$$T_{step}$$</span>，则有效观测误差为 <span class=\"formula\">$$\\varepsilon = T_{inj}/T_{step}$$</span>，工程判断是 ε 必须小到不改变 All-to-All 是否被计算隐藏的结论，否则直方图给出的专家负载倾斜只是测量伪影。</p>\n<p>系统代价体现在三处：联合采集要求系统级 NCCL 事件与 kernel 级指标同时在线，Nsight Systems 的时间线开销随采集范围与事件密度上升，长序列解码下会压缩可观测步数；Nsight Compute 单 kernel 采集会串行化并放大单 kernel 时延，不能用来判断重叠；只采单 kernel 指标而缺 NCCL 事件，会把通信暴露误判为计算瓶颈。下表给出失效条件与对应口径。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>表内症状</th><th>口径修正</th></tr></thead><tbody><tr><td>Graph 捕获后按名过滤</td><td>只见整图时长</td><td>改用 NVTX 阶段标注或符号表映射</td></tr><tr><td>注入点在 top-k 之前或逐 token 写回</td><td>时延被注入拉长</td><td>移到 top-k 之后、按步抽样</td></tr><tr><td>仅 Nsight Compute 单 kernel</td><td>无 NCCL 事件对齐</td><td>补系统级时间线再判重叠</td></tr></tbody></table>\n<p>阈值口径上，材料未给出具体重叠比例阈值，因此速查表不写数字门槛，只写判据：把 All-to-All 发送/接收区间与分组 GEMM 的 SM 占用画在同一轴，若通信区间未被 SM 占用覆盖，则通信直接暴露为解码步时延，此时应优先查路由分布是否倾斜导致分组 GEMM 缩短、隐藏能力下降，而不是先去调 GEMM 本身。</p>\n<h3 id=\"ap-moe-profiler-tools-sec-15\">十五 · 阈值从哪来：先定判据，再定数字</h3>\n<p>工程阈值的合法性不来自“业界常用”，而来自它绑定的判据。MoE 剖析里真正需要盯的判据只有四条：解码步时延是否被 All-to-All 暴露、分组 GEMM 的 SM 占用是否被通信切碎、专家负载倾斜是否越过丢弃边界、注入点开销是否改变了被测时序。每条判据对应一个可测的量，阈值只是这个量在特定 SLO 下的分界。因此本部分不给“通用阈值表”，而给“判据—测量量—判定方法”的三元组，数字只在能从可用事实推出的地方出现，其余一律写成测量协议。</p>\n<p>判定“通信是否被计算隐藏”的测量量是重叠率。把 All-to-All 的发送/接收区间与分组 GEMM 的 SM 占用画在同一时间轴，取交集时长除以通信总时长：</p>\n<div class=\"formula\">$$\\eta_{\\text{ovl}}=\\frac{T_{\\text{comm}}\\cap T_{\\text{gemm}}}{T_{\\text{comm}}}$$</div>\n<p>材料未给出重叠比例的合格阈值，领域经验是重叠不足时 All-to-All 直接暴露为解码步时延——这句话的正确用法是把它当判据而非当数字：只要解码步时延对 All-to-All 时长敏感（拉长通信即拉长步时延），就说明 η_ovl 不够，无需先凑一个百分比。测量方法是用 Nsight Systems 联合采集分组 GEMM 与 All-to-All 的时间线，把路由 kernel、分组 GEMM、All-to-All、反量化 kernel 放在同一轴上。代价上，系统级时间线采集本身有开销，长序列采集会放大存储与后处理成本，因此按“稳态若干步 + 一次冷启步”分段采集，而不是全程录制。</p>\n<p>具体例子：某解码步时间轴上，All-to-All 区间完整落在分组 GEMM 的 SM 占用区间之外，两者无交集，η_ovl 接近零，此时把分组 GEMM 的 tile 调大或改调度都不会降低步时延，应先动通信与计算的排布。反之若交集覆盖通信区间的大部分，则瓶颈不在通信暴露，应转去查单 kernel 指标。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-16\">十六 · 重叠判定的三个反例与采集前置条件</h3>\n<p>重叠判定最常见的失效不是算错，而是采错了对象。第一个反例：只采集 Nsight Compute 的单 kernel 指标而缺少系统级 NCCL 事件。单 kernel 指标能告诉你分组 GEMM 的指令与访存效率，但无法回答“All-to-All 是否与它重叠”，于是很容易把通信暴露误判成计算瓶颈，去优化一个本来不是瓶颈的 kernel。判据要求两条采集层级同时在场：系统级时间线给重叠关系，kernel 级指标给单点效率，缺一不可。</p>\n<p>第二个反例：在 CUDA Graph 捕获后才按 kernel 名过滤。捕获后 kernel 名称可能被折叠为图节点编号，分组 GEMM 与 All-to-All 无法区分，时间线分析直接失效。前置条件是在捕获前用 NVTX 范围标注路由、分组 GEMM、All-to-All 阶段，或在捕获时保留 kernel 符号表映射，才能在图回放时间线中还原各阶段归属；否则只能看到整图执行时长，重叠关系无从判断。这条前置条件的代价是标注本身要落在捕获路径上，标注粒度过细会稀释图回放的收益，粒度太粗又还原不出阶段边界，实践中按“一个 MoE 层一个 NVTX 范围、阶段内部不再细分”的粒度标注。</p>\n<p>第三个反例：路由直方图注入点放错位置或写回方式过重。注入点应放在路由 softmax/top-k 之后、分组 GEMM 之前，在此处记录每专家的 token 计数与路由分数分布，可发现专家负载倾斜；若放在 top-k 之前，记录的是未归一化的候选分布，与真正进入分组 GEMM 的 token 归属不一致。采样需低开销，如按步抽样而非逐 token，逐 token 同步写回会引入主机同步与额外 kernel，测得的时间线不再代表真实部署时序。</p>\n<p>具体例子：一次 Graph 回放采集里，时间线只剩整图执行时长，无法定位分组 GEMM 与通信的重叠关系；回退到捕获前加 NVTX 标注后重采，阶段归属恢复，重叠率才可计算。这里的系统代价是重采一轮的工程时间，而不是 GPU 时间。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-17\">十七 · 专家负载倾斜：用直方图定丢弃边界</h3>\n<p>专家负载倾斜的测量量是每专家 token 计数的分布，以及它与容量因子的比值。容量因子与丢弃代价的机制不在本部分展开，这里只给判定协议：在注入点按步抽样记录计数直方图，取最大专家计数与平均计数之比作为倾斜度，再与容量因子对照，判断哪些专家会溢出、溢出 token 被丢弃的比例有多大。</p>\n<div class=\"formula\">$$\\text{skew}=\\frac{\\max_e n_e}{\\frac{1}{E}\\sum_e n_e},\\qquad \\text{drop}_e=\\max\\left(0,\\,1-\\frac{C\\cdot \\bar n}{n_e}\\right)$$</div>\n<p>其中 n_e 为专家 e 的 token 计数，E 为专家数，C 为容量因子，丢弃比例按专家逐个算再聚合。材料未给出倾斜度的合格阈值，因此判定不靠绝对值，而靠“丢弃是否落在 SLO 允许的范围内”以及“倾斜是否随步漂移”。漂移比绝对值更值得关注：同一模型在长上下文与短上下文下路由分布不同，单步直方图可能正常而多步序列出现周期性尖峰。</p>\n<p>测量代价必须计入：直方图注入若逐 token 写回，会插入主机同步与额外 kernel，改变时序；按步抽样则把开销压到每步一次聚合，代价可接受。具体例子：某步直方图显示少数专家计数远高于均值，skew 明显偏大，同时这些专家的丢弃比例非零；此时扩容或改路由不是第一选择，应先确认该倾斜是稳态还是抽样噪声——用连续多步的直方图序列判断，若尖峰只在个别步出现，则属于路由抖动而非结构性倾斜。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-18\">十八 · 单 kernel 效率：分组 GEMM 的测量口径</h3>\n<p>分组 GEMM 的效率不能只看一个平均利用率，因为不同专家的 tile 形状与 token 数差异很大。测量口径是：用 Nsight Compute 采集单 kernel 的指令与访存指标，但必须与系统级时间线对齐，否则会把“被通信切碎的空泡”误读成 kernel 本身低效。判定方法是把分组 GEMM 的 SM 占用区间与 All-to-All 区间求交，若交集小且 kernel 内部指标也不佳，才是真正的 kernel 问题；若交集大而 kernel 指标尚可，问题在排布不在 kernel。</p>\n<p>代价维度上，单 kernel 采集会放大被采集 kernel 的执行时间（指标采集本身有开销），因此不能在被采集状态下读步时延，只能用其相对指标做效率判断，绝对时延回到系统级时间线读取。具体例子：对同一分组 GEMM 分别在“通信与计算重叠良好”和“通信完全暴露”两种排布下采集单 kernel 指标，若指标接近而步时延差异明显，则瓶颈确认在重叠而非 kernel，这条对照实验比任何阈值都可靠。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-19\">十九 · 注入点开销的自检：先证明测量不改时序</h3>\n<p>所有自定义注入点都必须先通过一项自检：开启注入与关闭注入两次采集，系统级时间线上的阶段边界与步时延是否一致。若不一致，注入本身改变了时序，后续所有阈值判定作废。这项自检的代价是两轮采集，但它是唯一能证明“测得的时间线代表真实部署时序”的方法。失败模式已经明确：逐 token 同步写回引入主机同步与额外 kernel，测得的时间线不再代表真实部署时序。</p>\n<p>自检的判据不是“开销小于某个百分比”，而是“阶段归属不变、重叠关系不变”。具体做法：在捕获前用 NVTX 标注阶段，分别在注入开/关下做 Graph 回放采集，比较分组 GEMM 与 All-to-All 区间的相对位置；位置关系一致则注入可用，位置关系漂移则降低采样频率或改为按步聚合。这条判据把“低开销”从模糊形容词变成可验证的工程条件。</p>\n<p>工程判断落在最后一步：阈值只在判据、测量量、注入自检三者都成立时才有意义。先证明测量不改时序，再用同一时间轴算重叠率与倾斜度，最后才谈数字；顺序颠倒，得到的任何阈值都只是对一次被污染采集的拟合。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-20\">二十 · 阈值不是拍脑袋：从时间线对齐到注入点开销的工程判据</h3>\n<p>这一节要处理的是工具链里最容易被含糊过去的部分：什么算“重叠不足”、什么算“专家负载倾斜”、什么算“注入点开销过大”。材料没有给出任何现成阈值，所以正确的做法不是编一个百分比，而是把每个判据还原成可测量的量，并明确它的失效边界。以 All-to-All 与分组 GEMM 的重叠为例，判据应写成暴露时间占比：设解码步总时延为 <span class=\"formula\">$$T_{\\text{step}}$$</span>，All-to-All 区间中未被分组 GEMM 的 SM 占用覆盖的部分为 <span class=\"formula\">$$T_{\\text{exposed}}$$</span>，则暴露比 <span class=\"formula\">$$\\rho = T_{\\text{exposed}} / T_{\\text{step}}$$</span>。工程上要盯的不是 <span class=\"formula\">$$\\rho$$</span> 的绝对值，而是它在不同批大小、不同专家并行度下的斜率——斜率陡说明通信没有被计算隐藏，容量规划时增加并发只会线性放大时延。测量方法只有一个可靠路径：Nsight Systems 联合采集，把 NCCL 的发送/接收区间与分组 GEMM 的 SM 占用画在同一时间轴；只采 Nsight Compute 的单 kernel 指标无法回答这个问题，会把通信暴露误判成计算瓶颈。</p>\n<p>第二个判据是路由分布的倾斜度。注入点必须落在路由 softmax/top-k 之后、分组 GEMM 之前，在此记录每专家的 token 计数。设专家 <span class=\"formula\">$$i$$</span> 分得 <span class=\"formula\">$$n_i$$</span> 个 token，总 token 数为 <span class=\"formula\">$$N$$</span>，均匀基线为 <span class=\"formula\">$$N/E$$</span>（<span class=\"formula\">$$E$$</span> 为专家数），则倾斜度可写成 <span class=\"formula\">$$\\sigma = \\max_i n_i \\,/\\, (N/E)$$</span>。这个量直接对应系统代价：<span class=\"formula\">$$\\sigma$$</span> 越大，最热专家所在设备的 GEMM 与显存带宽先饱和，其余设备空转，整步时延由最慢的那条专家并行链路决定。注意采样方式本身会污染测量——逐 token 同步写回会引入主机同步与额外 kernel，测得的时间线不再代表真实部署时序；应按步抽样，把直方图写入设备端缓冲区后异步回读。</p>\n<p>第三个判据是 CUDA Graph 下的可归属性。捕获后 kernel 名称被折叠为图节点编号，此时按 kernel 名过滤必然失效，分组 GEMM 与 All-to-All 无法区分，整图只剩一个总时长。规避方式是在捕获前用 NVTX 范围标注路由、分组 GEMM、All-to-All 阶段，或保留 kernel 符号表映射，使图回放时间线能还原阶段归属。这项工作的代价是采集开销：NVTX 标注与低开销采样对稳态吞吐的影响应单独测一次空跑基线，把“带工具”与“不带工具”的每步时延差作为工具链自身的成本记账。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>可测量</th><th>失效条件</th><th>系统代价指向</th></tr></thead><tbody><tr><td>通信重叠</td><td>暴露比 ρ 随批大小的斜率</td><td>缺 NCCL 事件，仅有单 kernel 指标</td><td>解码步时延线性放大</td></tr><tr><td>专家倾斜</td><td>σ = max n_i /(N/E)</td><td>注入点在 top-k 之前或逐 token 同步</td><td>最慢专家链路决定整步</td></tr><tr><td>图内归属</td><td>阶段级时长可分辨</td><td>捕获后才按 kernel 名过滤</td><td>分析失效，无法定位空泡</td></tr></tbody></table>\n<p>落到工程判断上：这三个判据共享一个前提——采集必须与部署时序同构。任何改变同步行为、改变 kernel 数量、改变图结构的采集手段，测出来的都不是生产路径。因此阈值应当由团队在自己的模型、自己的并行度、自己的批调度策略下扫出来，而不是引用外部数字；工具链的职责是保证这些量可复现地测到，而不是替工程师决定红线画在哪里。</p>\n<h3 id=\"ap-moe-profiler-tools-sec-21\">二十一 · 捕获顺序与命名还原：先标注，再捕获，最后过滤</h3>\n<p>MoE 剖析里最昂贵的一类返工，是时间线已经采完、图已经回放，才发现无法把分组 GEMM 与 All-to-All 分开。根因不在采集工具，而在采集顺序。CUDA Graph 捕获会把 kernel 折叠为图节点编号，捕获完成后按 kernel 名过滤只能得到一串无语义的节点；此时唯一可用的信息是整图执行时长，分组 GEMM 与通信的重叠关系彻底丢失。正确顺序是：先在捕获前用 NVTX 范围把路由、分组 GEMM、All-to-All、反量化四个阶段各自框住，或在捕获时保留 kernel 符号表映射，再执行捕获，最后才在回放时间线上按 NVTX 或符号表归属做过滤。这条顺序不可交换，因为 NVTX 范围是捕获时刻写入图结构的元数据，事后无法补写。</p>\n<p>机制上，NVTX 范围在 Graph 捕获期间被记录为图节点的关联注解，回放时随节点一同重现；符号表映射则依赖捕获时未被剥离的 kernel 符号，一旦图被序列化并重新加载，符号信息可能不再完整。因此工程上应把“阶段标注”做成捕获脚本的前置断言：若检测到目标 kernel 未落在任何 NVTX 范围内，直接中止捕获并报错，而不是产出一份不可用的时间线。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{capture}(G):\\ \\forall k \\in \\text{kernels}(G),\\ \\exists r \\in \\text{NVTX},\\ k \\subset r \\ \\Rightarrow\\ \\text{accept};\\ \\text{else}\\ \\text{abort}$$</div>\n<p>系统代价体现在返工成本上：一次完整的联合采集通常覆盖数十个解码步与预填步，捕获、回放、导出、分析构成一条长链路；命名还原失败意味着整条链路重跑，且重跑时若仍不修正标注顺序，会再次失败。具体例子：某分组 GEMM 在捕获后被折叠为节点编号，分析者误以为图中只剩一个计算节点，把整图时长当作分组 GEMM 时长，进而把 All-to-All 的暴露时延错记到计算账上，后续所有容量规划都建立在错误的计算占比之上。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-22\">二十二 · 注入点的位置与开销：放在 top-k 之后、分组 GEMM 之前</h3>\n<p>自定义路由分布直方图与专家利用率采样的注入点只有一个正确位置：路由 softmax/top-k 之后、分组 GEMM 之前。此处每专家的 token 计数与路由分数分布已经确定，尚未进入分组 GEMM 的专家分派，记录到的负载倾斜是真实的、未被后续 kernel 改写的。把注入点放在 top-k 之前，记录的是未归一化的分数，无法反映最终分派；逐 token 同步写回则引入主机同步与额外 kernel，测得的时间线不再代表真实部署时序，注入本身改变了被测量的对象。</p>\n<p>采样必须低开销，按步抽样而非逐 token。设每步 token 数为 $T$、专家数为 $E$、抽样率为 $p$，直方图更新的期望写入次数为 $pT$，而逐 token 写回为 $T$；当 $T$ 达到数千量级、$E$ 为数十到数百时，逐 token 写回的原子操作与同步开销足以把解码步时延推高到不可忽略的比例。工程判断是：直方图用设备端原子累加、按步一次性拷回，拷贝与解码步的计算重叠；专家利用率用固定间隔的步采样，采样步与非采样步的时延差异应小于测量噪声，否则说明注入开销已污染时序。</p>\n<p>具体机制上，注入点应实现为路由 kernel 尾部的一个轻量分支：仅在采样步置位标志，累加到预分配的设备缓冲区，主机侧在步边界异步拷回。系统代价有三项：显存上多一份 $E$ 长度的计数缓冲与分数直方图桶，量级很小；带宽上每采样步一次小拷贝，可被计算隐藏；延迟上非采样步零额外同步，采样步增加一次异步拷贝的排队。例子：路由倾斜导致某专家承接了远超均值的 token 数，若注入点在 top-k 之前，看到的是分数分布而非分派结果，会误判为分数集中而非容量因子不足，修复方向完全错位。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-23\">二十三 · 联合时间线的读法：NCCL 事件与 SM 占用同轴对齐</h3>\n<p>只采集 Nsight Compute 的单 kernel 指标而缺少系统级 NCCL 事件，是另一类高频失败：单 kernel 指标能告诉你分组 GEMM 的指令与访存效率，却无法回答 All-to-All 是否被计算隐藏。判断重叠必须把 All-to-All 的发送/接收区间与分组 GEMM 的 SM 占用画在同一时间轴。Nsight Systems 提供 CPU/GPU 时间线与 NCCL 通信事件，Nsight Compute 提供单 kernel 的指令与访存指标，两者联合采集才能同时看到重叠关系与 kernel 内部效率。</p>\n<p>读法上，先看 NCCL 事件区间是否落在分组 GEMM 的 SM 占用区间之内：落在之内说明通信被计算隐藏，落在之外则是暴露时延。材料未给出具体重叠比例阈值，领域经验是重叠不足时 All-to-All 直接暴露为解码步时延，表现为解码步时长随 batch 增大而阶梯式上升，而非平滑增长。此时若只看单 kernel 指标，会看到分组 GEMM 效率正常，从而把瓶颈误判为计算，实际瓶颈在通信未被隐藏。</p>\n<div class=\"formula\">$$t_{\\text{step}} \\approx \\max(t_{\\text{GEMM}},\\ t_{\\text{A2A}}) + t_{\\text{exposed}},\\quad t_{\\text{exposed}} = t_{\\text{A2A}} - \\text{overlap}$$</div>\n<p>系统代价：All-to-All 暴露意味着解码步时延由通信主导，吞吐随并发上升而收益递减；显存上，通信缓冲与分组 GEMM 的输出缓冲同时驻留，暴露期间 SM 空泡不产生有效计算，功耗上表现为计算单元闲置而互连活跃。具体例子：把发送/接收区间与 SM 占用同轴画出后，发现接收区间尾部超出分组 GEMM 占用区间，超出部分即为暴露时延；修复方向是调整分组 GEMM 的分块顺序，使先到的专家分片先计算，让通信与计算在时间上咬合，而不是去优化分组 GEMM 的指令效率。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-24\">二十四 · 踩坑清单：按失败模式归类，逐条给检查动作</h3>\n<p>把失败模式整理成清单，比逐次调试更省时间。清单按“采集顺序、注入点、联合采集、图回放”四类组织，每条给出可执行的检查动作，而不是笼统的注意事项。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测征兆</th><th>检查动作</th><th>系统代价</th></tr></thead><tbody>\n<tr><td>捕获后才按 kernel 名过滤</td><td>时间线只剩图节点编号，阶段不可分</td><td>检查捕获脚本是否在捕获前写入 NVTX 范围或保留符号表</td><td>整条采集链路返工</td></tr>\n<tr><td>注入点在 top-k 之前</td><td>直方图反映分数而非分派，倾斜判断失真</td><td>核对注入点是否位于 softmax/top-k 之后、分组 GEMM 之前</td><td>误判修复方向，容量因子调错</td></tr>\n<tr><td>逐 token 同步写回</td><td>采样步与非采样步时延差异显著</td><td>对比开启/关闭注入的步时延，差异应小于噪声</td><td>注入改变时序，测量失效</td></tr>\n<tr><td>只采单 kernel 指标</td><td>分组 GEMM 效率正常但步时延偏高</td><td>补采 NCCL 事件，与 SM 占用同轴对齐</td><td>把通信暴露误判为计算瓶颈</td></tr>\n<tr><td>图回放后符号丢失</td><td>重新加载的图无法归属阶段</td><td>确认序列化前后符号映射是否保留</td><td>离线分析不可复现</td></tr>\n</tbody></table>\n<p>清单的价值在于把“症状”映射到“动作”。例如看到解码步时延随 batch 阶梯上升，先查联合时间线中 All-to-All 是否暴露，再查注入点是否污染了采样步；看到专家利用率直方图异常集中，先确认注入点在 top-k 之后，再判断是路由倾斜还是容量因子不足。每条检查动作都对应一个具体的系统代价，避免把排查变成无边界的试错。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-25\">二十五 · 检查顺序：从系统级到 kernel 级，从无注入到有注入</h3>\n<p>检查顺序应遵循两条原则：先系统级后 kernel 级，先无注入后有注入。系统级时间线回答“重叠与空泡在哪里”，kernel 级指标回答“单个 kernel 内部效率如何”；若系统级已显示通信暴露，则 kernel 级的分组 GEMM 优化是次要的。先无注入采集一次基线，确认基线时序稳定，再开启注入对比，才能把注入开销从真实信号中分离出来。</p>\n<p>具体顺序可固化为五步：第一步，无注入、无图捕获的系统级时间线，确认路由、分组 GEMM、All-to-All、反量化的阶段边界；第二步，开启 NVTX 标注后的图捕获回放，确认阶段归属可还原；第三步，开启低开销注入，对比采样步与非采样步时延；第四步，联合 NCCL 事件与 SM 占用，判定重叠是否充分；第五步，仅在系统级无异常时，才进入 Nsight Compute 的单 kernel 指标分析。任何一步出现异常，回退到上一步而不是继续深入。</p>\n<p>系统代价上，这个顺序把最贵的采集放在最后：单 kernel 指标采集通常需要多次重放与逐 kernel 过滤，开销远高于系统级时间线；先做便宜的判断，能避免在错误方向上做昂贵的采集。例子：若第二步发现图回放中阶段不可分，应立即回到第一步补标注，而不是在不可分的时间线上继续做第四步的重叠判断——后者只会产出无法解释的结论。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-26\">二十六 · 回滚方案：把采集配置当作可版本化的产物</h3>\n<p>回滚方案的核心是把采集配置当作可版本化的产物：捕获脚本、NVTX 标注点、注入点位置、采样率、NCCL 事件开关，全部纳入版本管理，每次采集记录配置指纹。当某次采集产出异常时间线时，能定位到是哪一项配置变更导致的，而不是靠记忆复现。回滚的触发条件应明确：阶段归属不可还原、采样步时延差异超出噪声、联合时间线中 NCCL 事件缺失，任一触发即回滚到上一个已知可用的配置指纹。</p>\n<p>机制上，配置指纹可由各配置项的哈希构成，采集产物头部写入指纹，分析脚本在读取产物时校验指纹与当前配置一致，不一致则拒绝分析并提示回滚。这样做的代价是每次采集多一次哈希与校验，量级可忽略；收益是杜绝“用旧配置的产物配新配置的结论”这类隐蔽错误。具体例子：某次为降低注入开销把采样率调低，产物指纹变化，分析脚本拒绝沿用旧的直方图基线，强制重新建立基线，避免了把采样率变化误读为路由分布变化。</p>\n<p>回滚方案还应包含产物保留策略：系统级时间线体积大但信息密度高，保留最近若干次即可；单 kernel 指标体积更大，按需采集、按需保留。工程判断是：把“可回滚”定义为“能在不重跑全部采集的前提下，回到上一个可解释的时间线”，因此基线时间线与配置指纹必须长期保留，其余产物可轮转。最后落在具体机制上：分析脚本在每次读取产物时先校验指纹、再校验阶段归属断言，两项任一失败即触发回滚提示，把踩坑清单从人工经验变成流水线里的硬约束。</p>\n<h3 id=\"ap-moe-profiler-tools-sec-27\">二十七 · 上游依赖：剖析链路的输入契约</h3>\n<p>MoE 剖析工具链不是自足的。它消费的是上游各条目产出的结构化事实：路由术语速查定义了“专家命中”“容量因子”“丢弃率”的口径，剖析器若自行解释这些词，直方图与框架侧统计就对不上；量化校准数据管线决定了权重与激活的数值格式，NVFP4/FP8 条目给出的反量化 kernel 位置，正是时间线上必须被标注的一段；专家并行与 All-to-All 条目确定了通信原语的粒度与分组方式，剖析器据此才知道该在 NCCL 事件里找哪一类集合通信。换句话说，工具链的采集对象不是“一个 MoE 模型”，而是“一组已被上游条目命名并参数化的阶段”。</p>\n<p>这个契约可以用一个映射关系表达：设上游条目集合为 <span>U</span>，每个条目贡献一组可观测符号 <span>s<sub>i</sub></span>（阶段名、kernel 族、通信原语、精度格式），剖析器构造标注函数 <span>A: kernel → s<sub>i</sub></span>。若 <span>A</span> 的定义域覆盖不全，时间线上就会出现无法归属的区间，而这些区间恰恰是分组 GEMM 与 All-to-All 重叠判断的关键。工程代价直接体现在采集开销上：NVTX 范围标注是主机侧插桩，单次标注的 CPU 开销在微秒量级，但解码步的步长本身就在毫秒量级，密集标注会挤占调度线程；因此标注必须按阶段而非按 kernel 打点。</p>\n<p>具体例子：一次预填阶段中，路由 kernel、分组 GEMM、All-to-All、反量化 kernel 四段需要落在同一时间轴。若上游的量化条目未指明反量化 kernel 的命名族，剖析器只能把它归入“其他”，于是分组 GEMM 之后的空泡被误判为计算尾部，而实际是反量化未与通信重叠。这类误判不会报错，只会让容量规划得出偏乐观的结论。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-28\">二十八 · 下游影响：谁在消费剖析结论</h3>\n<p>剖析输出向下游三个方向流动，且每个方向对输出的精度要求不同。第一是框架选型与配置：MoE 推理框架选型条目需要知道分组 GEMM 的实际 SM 占用与 All-to-All 暴露程度，才能判断某框架的通信计算重叠策略是否生效；剖析给出的不是“快或慢”，而是“通信是否被计算隐藏”这一布尔判断及其时间证据。第二是尾延迟治理：路由倾斜尾延迟条目消费专家利用率采样，把“某专家 token 计数偏高”翻译成“该专家所在 rank 的分组 GEMM 段变长”，进而决定是否调整容量因子。第三是量化后路由漂移：漂移检测需要路由分数分布的历史基线，而基线正是剖析注入点在 softmax/top-k 之后采集的直方图。</p>\n<p>下游消费的代价是采样频率与信噪比的权衡。按步抽样而非逐 token 记录，可以把注入开销压到不影响时序的水平；但步级抽样对短时尖峰的捕捉能力弱，尾延迟条目若只看步均值，会漏掉单步内的专家倾斜。这里存在一个可量化的约束：设单步注入开销为 <span>c</span>，步时长为 <span>T</span>，则要求 <span>c/T</span> 足够小以至于不改变被测时序；逐 token 同步写回会引入主机同步，<span>c</span> 随 token 数线性增长，直接破坏该约束。</p>\n<div class=\"formula\">$$\\text{采样可信度} \\propto \\frac{1}{c/T},\\qquad c_{\\text{step}} \\ll c_{\\text{token}} \\cdot N_{\\text{token}}$$</div>\n<p>具体例子：解码阶段每步只处理少量 token，逐 token 写回直方图会让每个 token 触发一次主机可见的更新，步时延被注入本身拉长；改为每步聚合一次、在分组 GEMM 之前落盘，则时间线保持可解释，同时仍能发现“某专家连续多步高负载”的倾斜模式。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-29\">二十九 · 与 CUDA Graph 条目的耦合面</h3>\n<p>CUDA Graph 捕获是剖析链路中最容易断裂的一环，也是与其他条目耦合最紧的地方。捕获后 kernel 名称折叠为图节点编号，这一事实本身属于工具链的失败模式清单，但它对下游的影响超出工具链：任何依赖 kernel 名做归因的下游分析——框架选型的重叠判断、尾延迟的阶段拆解——都会在图回放模式下失效。解法只有两条：捕获前用 NVTX 范围标注路由、分组 GEMM、All-to-All 阶段，或在捕获时保留 kernel 符号表映射。前者把归属信息编码进图结构，后者把归属信息留在旁路表里。</p>\n<p>两条路径的代价不同。NVTX 标注随图一起被捕获，回放时无需额外查表，但标注密度受限于捕获时的插桩点，动态分支多的路由逻辑难以全覆盖；符号表映射不侵入图结构，却要求剖析器在回放时做一次节点编号到符号的解析，解析本身是主机侧操作，对稳态吞吐无影响，但对单步时延的观测有轻微扰动。工程判断是：预填阶段用 NVTX 全覆盖，解码阶段用符号表映射，因为解码步短、对主机侧扰动更敏感。</p>\n<p>具体例子：图回放时间线上若只剩整图执行时长，分组 GEMM 与 All-to-All 的重叠关系不可见，下游会把“整图变长”笼统归因为计算瓶颈，而真实原因可能是通信未被隐藏。此时即便 NCCL 事件采集正常，缺少阶段归属也无法把发送/接收区间与 SM 占用画在同一轴上。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-30\">三十 · 与通信条目的边界划分</h3>\n<p>剖析工具链与通信条目（专家并行与 All-to-All、通信计算死锁）共享 NCCL 事件这一数据源，但消费角度不同。通信条目关心原语的正确性与死锁条件，剖析关心的是时间轴上的重叠与空泡。边界在于：剖析不判断通信是否“该发生”，只判断它“是否被计算隐藏”。这一划分避免了重复劳动——死锁检测依赖的是原语顺序与依赖图，而非时间线重叠率；重叠率分析依赖的是 NCCL 发送/接收区间与分组 GEMM 的 SM 占用对齐，而非依赖图。</p>\n<p>重叠不足的代价是直接暴露为解码步时延。材料未给出具体重叠比例阈值，领域经验是：当 All-to-All 区间在时间轴上完全落在分组 GEMM 之外，通信即为暴露；此时增加计算量不会缩短步时延，只会拉长暴露段之外的区间。这个判断对分离式预填/解码条目同样关键：预填与解码的通信模式不同，剖析需分别采集，不能把预填阶段的高重叠率外推到解码阶段。</p>\n<p>具体例子：把 All-to-All 的发送/接收区间与分组 GEMM 的 SM 占用画在同一轴，若发送区间与 SM 占用区间无交叠，说明通信未被隐藏；此时下游的框架选型应优先考虑具备通信计算重叠调度的运行时，而非单纯提高分组 GEMM 的 tile 效率。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-31\">三十一 · 在全书中的位置：从观测到决策的接口层</h3>\n<p>把工具链放回全书结构，它的位置是“观测层”与“决策层”之间的接口。算子与数值精度条目给出分组 GEMM 与 tcgen05 的实现形态，显存与 KV cache 条目给出容量约束，批调度条目给出步的边界，这些是观测对象；SLO 与容量规划、框架选型、尾延迟治理是决策消费者。工具链不产生新的优化手段，它产生的是“哪一段该被优化”的归因证据。缺少这一层，决策层只能依据端到端指标做黑箱调参，无法区分计算瓶颈、通信暴露与注入扰动。</p>\n<p>这一位置决定了工具链的输出格式必须是机器可读且阶段对齐的：时间线要带阶段标签，直方图要带步编号与专家编号，NCCL 事件要与 kernel 区间可连接。输出格式的代价是存储与后处理开销——系统级时间线的数据量随采集时长线性增长，长时间采集需分段落盘；kernel 级指标的数据量随 kernel 数增长，全量采集会拖慢回放。工程判断是按问题选层级：定位重叠关系用系统级时间线，定位单 kernel 访存效率用 Nsight Compute，二者不可互相替代。</p>\n<p>具体例子：容量规划需要的是“每步中通信暴露段占步时长的比例”这一派生量，它由系统级时间线加阶段标签计算得出；若只有单 kernel 指标，则无法得出该比例，规划只能退回保守估算。反过来，若发现分组 GEMM 的 SM 占用已满而步时延仍高，则需下钻到 kernel 级指标看访存与指令效率，此时系统级时间线不再提供新信息。</p>\n<p>最终落在注入点的工程约束上：路由直方图与专家利用率采样必须放在 softmax/top-k 之后、分组 GEMM 之前，且按步聚合。这个位置不是任意选的——放在 top-k 之前会记录未被选中的分数分布，与专家负载无关；放在分组 GEMM 之后则混入了 GEMM 的执行时间，无法区分路由倾斜与计算变长。注入点一旦错位，下游的尾延迟治理与漂移检测都会建立在错误的归因上，而工具链本身不会给出任何告警。</p>\n\n<h3 id=\"ap-moe-profiler-tools-sec-32\">三十二 · 边界条件：工具链在什么情况下会给出错误结论</h3>\n<p>这套剖析链路的有效性建立在三个前提上：时间线可归属、注入不扰动、层级可对齐。任一前提破裂，输出就不是“精度下降”而是“结论反向”。最典型的失效是 CUDA Graph 捕获后的符号折叠：捕获完成后 kernel 名被替换为图节点编号，此时再按名称过滤分组 GEMM 与 All-to-All 已不可能，回放时间线只剩整图执行时长，重叠关系无从判断。规避方式只有两条——捕获前用 NVTX 范围把路由、分组 GEMM、All-to-All 分段标注，或在捕获时保留 kernel 符号表映射。工程判断是：只要部署路径启用 Graph，剖析脚本必须在捕获阶段而非回放阶段埋点，这是一次性的架构约束，不能靠事后补。</p>\n<p>第二个边界是注入点位置与采样粒度。路由直方图与专家利用率必须落在 softmax/top-k 之后、分组 GEMM 之前，此处才能同时拿到每专家 token 计数与路由分数分布，暴露负载倾斜。若放在 top-k 之前，拿到的是未归一化的候选分布，与真正进入 GEMM 的 token 集合不一致；若逐 token 同步写回，主机同步与额外 kernel 会插入关键路径，测得的时间线不再代表部署时序。按步抽样是可行折中，其扰动代价可写成：</p>\n<div class=\"formula\">$$T_{\\text{obs}} = T_{\\text{real}} + n_{\\text{sync}} \\cdot t_{\\text{sync}} + \\sum_{k} t_{\\text{inject},k}$$</div>\n<p>其中 $n_{\\text{sync}}$ 为同步次数、$t_{\\text{sync}}$ 为单次主机往返延迟。当 $n_{\\text{sync}}$ 随 token 数线性增长时，观测开销会吞掉解码步中本就很薄的通信隐藏窗口，使 All-to-All 看起来“暴露”，而真实部署中它被分组 GEMM 掩盖。</p>\n<p>第三个边界是采集层级的错配。仅用 Nsight Compute 取单 kernel 指令与访存指标、缺少系统级 NCCL 事件，就无法把 All-to-All 的发送/接收区间与分组 GEMM 的 SM 占用画在同一轴，也就无法判断通信是否被计算隐藏；此时把通信暴露误判为计算瓶颈，优化方向会整体走偏。反之，仅有系统级时间线而无 kernel 级指标，则无法解释分组 GEMM 内部为何在某专家上变慢。两类采集必须成对使用，且时间分辨率要能覆盖解码步量级，否则重叠窗口在采样网格下被抹平。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测假象</th><th>系统代价</th></tr></thead><tbody><tr><td>Graph 捕获后按名过滤</td><td>只见整图时长</td><td>定位失效，重叠分析归零</td></tr><tr><td>注入点前置或逐 token 同步</td><td>通信看似未隐藏</td><td>主机同步拉长解码步时延</td></tr><tr><td>缺 NCCL 事件仅看单 kernel</td><td>误判计算瓶颈</td><td>优化错配，SM 占用与带宽浪费</td></tr></tbody></table>\n<p>这三条边界共同界定了工具链在全书中的位置：它不产生性能，只负责把分组 GEMM、All-to-All、反量化 kernel 的重叠与空泡还原成可判读的证据；一旦证据本身被采集行为污染，后续的批调度、并行策略与容量规划都会建立在错误前提上。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-moe-profiler-tools\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>列出 Nsight Systems/Compute 对分组 GEMM 与 All-to-All 的联合时间线采…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-moe-profiler-tools · 共 5 个片段</p>\n"},{"id":"ap-quant-calib-pipeline","title":"量化校准数据管线","summary":"给出 NVFP4/FP8 校准集的采样配方：按路由分布分层采样、覆盖长尾专家、控制序列长度分布，说明校准统计的收集脚本、块缩放搜索流程与量化后路由一致性回归的自动化比对工具。","kind":"工具","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-1\">一 · 条目边界：校准数据管线在量化链路中的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-2\">二 · 三轴分类：采样来源、分层粒度、统计对象</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-3\">三 · 与&quot;容量因子&quot;&quot;路由漂移&quot;两个相邻条目的切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-4\">四 · 序列长度分桶：分布偏离如何污染激活统计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-5\">五 · 统计收集脚本的拆分契约：按层还是按专家</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-6\">六 · 速查表列定义与&quot;均匀随机采样&quot;踩坑的根因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-7\">七 · 校准条目的边界：三轴分类如何决定失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-8\">八 · 速查表主结构与九列口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-9\">九 · 阈值三档与过采样加权公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-10\">十 · 块缩放搜索步长与统计对象对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-11\">十一 · 回归比对工具命令与判定闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-12\">十二 · 填表时的三条硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-13\">十三 · 速查表的适用边界：何时这张表会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-14\">十四 · 阈值的来源：从“每专家 token 数”倒推校准集规模</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-15\">十五 · 序列长度分桶：三档覆盖与长序列桶的样本下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-16\">十六 · 块缩放搜索步长：搜索精度与离线成本的折中</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-17\">十七 · top-k 一致率阈值：路由一致性回归的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-18\">十八 · 统计收集脚本的入口与聚合键：可测量性先于数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-19\">十九 · 校准集失效的边界条件与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-20\">二十 · 踩坑清单：从采样偏差到统计粒度错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-21\">二十一 · 检查顺序：先采样覆盖，再统计粒度，后缩放搜索</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-22\">二十二 · 长尾专家的过采样与缩放上限校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-23\">二十三 · 路由一致性回归的自动化比对与定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-24\">二十四 · 回滚方案：分级回滚与基线快照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-25\">二十五 · 校准管线的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-26\">二十六 · 上游依赖：校准管线吃的是谁产出的分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-27\">二十七 · 下游影响：块缩放与路由一致性回归都靠它喂数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-28\">二十八 · 横向关系：与 KV 压缩、分离式预填解码共享“分布假设”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-29\">二十九 · 与剖析工具链和框架选型的接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-30\">三十 · 在全书中的位置：离线侧的唯一分布权威</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-calib-pipeline-sec-31\">三十一 · 校准管线的上下游耦合与失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-quant-calib-pipeline\"><svg style=\"max-width:520px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 519.9 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"437.9\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：量化校准数据管线</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">给出 NVFP4/FP8 校准集的采样配方：按路由分布分层采样、覆盖长尾</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">专家、…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"437.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"437.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"437.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-quant-calib-pipeline-sec-1\">一 · 条目边界：校准数据管线在量化链路中的位置</h3>\n<p>量化校准数据管线（calibration data pipeline）是 NVFP4/FP8 权重与激活量化之前的离线工具链，其产物不是\"一个校准集文件\"，而是一组可复现的、按层与按专家索引的统计量，以及由这些统计量驱动的块缩放（block scale）参数。把它与三个相邻概念切开是理解本条目的前提：其一，它与<strong>量化算子本身</strong>（tcgen05 上的 NVFP4 MMA、FP8 累加路径）不同，管线不产生 kernel，只产生喂给 kernel 的 scale 与 amax 元数据；其二，它与<strong>量化后精度评估</strong>不同，评估消费管线的产物并给出误差结论，而管线自身只负责\"采样—统计—搜索\"三段；其三，它与<strong>在线校准</strong>（推理时动态更新 scale）不同，本条目严格是离线的，一次运行产出一份冻结的 scale 表，线上不再回写。</p>\n<p>这个边界决定了管线的三个不可省略的输出：逐层权重 amax 与块缩放候选、逐层激活的离群值分布（尤其是 FP8 的 per-tensor 与 per-block 之争）、以及门控分数（router logits）的分布快照——后者是 NVFP4 量化 MoE 时判断路由是否漂移的唯一依据。缺任何一项，下游的块缩放搜索都只能退化为全局默认值。</p>\n<div class=\"formula\">$$\\text{Pipeline} = \\{\\mathcal{S}_{\\text{sample}},\\ \\mathcal{T}_{\\text{stat}},\\ \\mathcal{B}_{\\text{scale}}\\}\\ \\rightarrow\\ \\{\\text{amax}_{l,e},\\ \\text{scale}_{l,e,b},\\ \\text{router-hist}\\}$$</div>\n<p>代价上要认清一件事：这条管线是<strong>显存与带宽密集型而非算力密集型</strong>。它要把校准 batch 前向一遍并逐层 dump 激活，激活 dump 的显存峰值正比于\"校准集 token 数 × 隐藏维 × 保留层数\"。工程上通常只保留需要块缩放的层、并按专家拆分后立即归约，否则一次 FP8 校准在 NVL72 单机上就能把 HBM 吃满，反过来压制采样规模。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-2\">二 · 三轴分类：采样来源、分层粒度、统计对象</h3>\n<p>条目说明给出的分类维度是三轴组合，三轴不是并列选项而是笛卡尔积，任一组合都唯一确定校准集的规模与显存占用。</p>\n<ul>\n<li><strong>采样来源</strong>：真实流量回放（replay）、合成提示（synthetic）、混合。回放保真度最高，能自然带出长尾专家的真实触发频率，但受限于可回放流量的隐私与留存；合成提示可控但极易引入分布偏置；混合则是用回放定分层键、用合成补长尾桶。</li>\n<li><strong>分层粒度</strong>：全局、按专家、按路由桶。全局粒度只产出一套 scale，显存最省但直接踩中\"长尾专家与头部专家共用缩放参数\"的失败模式；按专家粒度是 MoE 场景的正确解，代价是 scale 表体积正比于专家数；按路由桶粒度则在专家之上再按 top-k 命中位置分桶，用于捕捉同一专家在不同路由上下文下的激活差异。</li>\n<li><strong>统计对象</strong>：权重、激活、门控分数。权重统计可离线一次算完、与采样无关；激活统计强依赖采样配方；门控分数统计是路由一致性回归的输入，必须与激活统计同批采集，否则无法对齐。</li>\n</ul>\n<table class=\"mini\"><thead><tr><th>组合</th><th>典型用途</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>回放 × 按专家 × 激活</td><td>MoE 激活 FP8 块缩放</td><td>激活 dump 显存 ∝ 专家数 × 每专家 token</td></tr>\n<tr><td>混合 × 按路由桶 × 门控分数</td><td>NVFP4 路由漂移回归基线</td><td>需与激活同批，采样成本翻倍</td></tr>\n<tr><td>合成 × 全局 × 权重</td><td>稠密层权重 NVFP4 快速校准</td><td>显存最低，但对长尾无覆盖</td></tr>\n</tbody></table>\n<p>选轴的工程判断很直接：只要模型含 MoE 且量化格式为 NVFP4，分层粒度就不能停在全局——因为 NVFP4 的块缩放粒度本身比 FP8 更细，全局 scale 会把长尾专家的动态范围压死。反过来，稠密模型的权重校准用\"合成 × 全局 × 权重\"就够，多花的采样成本换不来精度。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-3\">三 · 与\"容量因子\"\"路由漂移\"两个相邻条目的切分</h3>\n<p>本丛书其他条目已经处理了容量因子与丢弃代价、量化后路由漂移，这里只做一句话指路并划清界限：容量因子讨论的是<strong>运行时</strong>每专家分到多少 token、丢弃如何发生；路由漂移讨论的是<strong>量化之后</strong>top-k 选择发生了多少偏移。本条目夹在两者之间，处理的是\"漂移的<em>根因数据</em>从哪来\"——即校准集是否覆盖了会被丢弃的那部分长尾 token。</p>\n<p>具体机制上，管线必须显式记录每个专家的<strong>路由概率加权采样率</strong>。设专家 $e$ 在回放流量中的路由概率为 $p_e$，则过采样权重取 $w_e \\propto p_e^{-\\alpha}$（$\\alpha\\in[0,1]$），$\\alpha=0$ 退化为按真实频率采样、$\\alpha=1$ 退化为按专家均匀采样。领域经验是每专家至少覆盖数百至上千 token 才能稳定块缩放，因此当 $p_e$ 对应的自然采样量低于该下限时，必须靠 $w_e$ 抬升；这就是\"按路由概率加权过采样\"的确切含义，而不是简单地给每个专家塞等量 token。</p>\n<div class=\"formula\">$$n_e = \\max\\left(n_{\\min},\\ N\\cdot\\frac{w_e}{\\sum_{e'} w_{e'}}\\right),\\quad w_e = p_e^{-\\alpha}$$</div>\n<p>代价：$\\alpha$ 越大，校准集里头部专家的 token 被稀释，头部专家的块缩放统计方差上升；$\\alpha$ 越小，长尾专家 $n_e$ 趋零、scale 退化为全局默认值。这个 trade-off 无法用单一 $\\alpha$ 消除，工程做法是分桶设 $\\alpha$：短序列桶用低 $\\alpha$ 保头部精度，长序列桶用高 $\\alpha$ 补长尾。显存上，$n_e$ 抬升直接抬高激活 dump 峰值，因此过采样必须与\"按专家即时归约\"配对，否则采样规模被显存反向锁死。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-4\">四 · 序列长度分桶：分布偏离如何污染激活统计</h3>\n<p>序列长度分桶通常覆盖短、中、长三档，这不是为了\"多样性\"，而是因为激活离群值的统计量与序列长度强相关：长序列下注意力的 KV 累积与 MoE 激活的动态范围都会外扩，若长序列桶样本过少，激活 amax 被低估，块缩放上限随之被低估，量化后长序列请求的误差会显著高于短请求——这正是失败模式里\"序列长度分布与线上实际分布偏离\"的机理。</p>\n<p>机制上，管线对每个长度桶独立收集激活直方图，再按线上流量中各桶的占比做加权合并，得到用于块缩放搜索的等效 amax。伪代码思路：</p>\n<div class=\"formula\">$$\\text{amax}^{\\text{eff}}_{l,e} = \\max_{b\\in\\{\\text{short,mid,long}\\}} \\text{amax}_{l,e,b}\\cdot \\mathbb{1}\\left[\\frac{N_b}{N}\\ge \\theta_b\\right]$$</div>\n<p>其中 $\\theta_b$ 是桶占比下限，低于下限的桶不参与 max，避免个别长序列样本把 scale 抬到浪费精度的程度；但若长序列桶整体缺失，则 $\\text{amax}^{\\text{eff}}$ 系统性偏低。工程判断：桶占比下限应参照线上 SLO 里长序列请求的实际占比设定，而不是拍一个固定值——容量规划里长序列桶往往只占少数请求却贡献多数尾延迟，校准集若按请求数等比例采样就会天然欠采样长序列。</p>\n<p>代价落在两处：一是长序列桶的激活 dump 显存按序列长度平方级增长（注意力部分），二是为补齐长序列桶所需的合成提示生成成本。折中做法是长序列桶只保留需要块缩放的层、且用滑动窗口截断 dump，把显存代价压回线性。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-5\">五 · 统计收集脚本的拆分契约：按层还是按专家</h3>\n<p>失败模式明确指出：统计收集脚本按层聚合而未按专家拆分，会让长尾专家与头部专家共用一套缩放参数，且量化后路由一致性回归无法定位到具体专家。这不是脚本 bug，而是接口契约缺失。管线的统计入口必须把\"聚合键\"作为显式参数暴露，聚合键至少是 $(l, e)$ 二元组，路由桶粒度下是 $(l,e,\\text{bucket})$ 三元组。</p>\n<p>机制上，收集脚本在每个 MoE 层的前向 hook 里拿到 dispatch 后的 token 归属，按专家索引 scatter 到独立的 amax 累加器，再在层末统一归约。若脚本只做 layer-level reduce，专家维度在归约时被 sum 掉，后续块缩放搜索拿到的就是一个混合了头部与长尾动态范围的 amax，长尾专家的 scale 被头部拉低，量化误差在长尾上放大。</p>\n<p>代价：按专家拆分使累加器数量正比于\"层数 × 专家数 × 桶数\"，在 GB200 NVL72 这类专家数很大的配置下，累加器本身占用的显存不可忽略，通常用低精度累加（FP32 amax 足够）并把不活跃专家惰性分配。另一个代价是回归比对工具的可定位性：只有按专家拆分的统计，回归工具才能输出\"某专家 top-k 一致率跌破阈值\"的逐专家报告，否则只能给出整层一个数，无法指导重采样。</p>\n<p>具体例子：一个含数十个专家的 MoE 层，若某长尾专家在回放流量中仅偶发触发、自然采样 token 数为零，按层聚合时它的 amax 完全由头部专家决定，块缩放搜索在该专家上无候选可搜，直接落全局默认值；按专家拆分后，脚本能报出该专家 $n_e=0$，触发过采样重采，回归工具再以该专家为键比对量化前后 top-k 一致率。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-6\">六 · 速查表列定义与\"均匀随机采样\"踩坑的根因</h3>\n<p>条目说明给出的速查表列不是罗列，而是把三轴分类与工程阈值固化成可查字段：条目名、量化格式（NVFP4/FP8）、采样分层键、每专家最少 token 数、序列长度分桶、统计收集脚本入口、块缩放搜索步长、top-k 一致率阈值、回归比对工具命令。其中\"采样分层键\"直接对应第二轴的粒度选择，\"每专家最少 token 数\"对应第三节的 $n_{\\min}$，\"块缩放搜索步长\"决定搜索成本与 scale 分辨率之间的取舍——步长越细，搜索遍历的候选 scale 越多，离线耗时线性上升，但 NVFP4 的块粒度细，步长过粗会让 scale 落在两个候选之间、误差抬升。</p>\n<p>最常见踩坑\"只用均匀随机提示采样\"的根因不在采样器，而在<strong>分层键缺省</strong>：均匀随机提示下，路由分布自然服从头部集中，长尾专家的期望 token 数为 $N\\cdot p_e$，当 $p_e$ 极小时该期望远低于 $n_{\\min}$，实际采样结果就是零。此时块缩放退化为全局默认值，量化后该专家输出误差显著高于头部专家，而按层聚合的统计脚本又让这个误差在回归里不可见——两个失败模式在此叠加。修复路径是双管：采样侧按 $w_e=p_e^{-\\alpha}$ 过采样补齐 $n_e$，统计侧按 $(l,e)$ 拆分聚合键，回归侧以专家为键比对 top-k 一致率。</p>\n<p>工程判断落在规模与显存的耦合上：校准集规模由 $\\sum_e n_e$ 与长度桶占比共同决定，而激活 dump 显存正比于该规模乘以保留层数。因此在 NVL72 上做 NVFP4 校准时，先定 $n_{\\min}$ 与桶占比，再反推可承受的保留层数，而不是先定校准集大小再祈祷显存够用——这个顺序决定了管线能否在单次离线运行内产出逐专家 scale 表，而不是被迫退回全局粒度。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-7\">七 · 校准条目的边界：三轴分类如何决定失效面</h3>\n<p>条目在管线里不是“一批提示词”，而是一个三元组：采样来源 × 分层粒度 × 统计对象。三轴组合直接决定校准集的显存占用与可诊断性。设专家数为 $E$、每专家最少 token 数为 $n_{\\min}$、序列长度桶数为 $B$、统计对象数为 $S$，则统计张量的最小规模约为 <span class=\"formula\">$$M \\approx E \\cdot n_{\\min} \\cdot B \\cdot S \\cdot b_{\\text{stat}}$$</span> 其中 $b_{\\text{stat}}$ 是单统计量字节数。按路由桶分层时 $E$ 换成路由桶数，粒度越细显存越高，但块缩放搜索的可分辨性越强；按层聚合则把 $E$ 压成 1，代价是长尾专家与头部专家共用一套缩放参数，量化后路由一致性回归无法定位到具体专家——这是分类维度选错时最典型的失效面，而非精度问题。</p>\n<p>与相邻概念的边界要划清：真实流量回放不等于“拿线上日志直接跑”，它必须带路由标签才能做分层；合成提示不等于均匀随机采样，后者会让长尾专家校准 token 数为零，其块缩放退化为全局默认值，该专家输出误差显著高于头部专家。混合来源的价值在于用合成提示补齐长尾桶的 $n_{\\min}$，但合成分布与真实路由分布的 KL 偏离会直接污染门控分数统计，因此混合比例本身是校准集的一个超参，不是数据工程细节。</p>\n<p>失效条件集中在两处。其一是序列长度分桶与线上实际分布偏离，长序列桶样本过少，激活离群值统计失真，块缩放上限被低估，表现为长上下文下逐层激活量化误差抬升而权重侧看不出异常。其二是统计收集脚本按层聚合而未按专家拆分，此时回归比对工具只能报“整层 top-k 一致率下降”，无法归因到专家，排障成本从分钟级升到重跑校准集。工程判断：分层粒度优先按专家而非按层，序列长度至少覆盖短、中、长三档，每专家 token 数不足时按路由概率加权过采样，而不是降低 $n_{\\min}$。</p>\n<table class=\"mini\"><thead><tr><th>分类轴</th><th>取值</th><th>系统代价</th><th>失效信号</th></tr></thead><tbody><tr><td>采样来源</td><td>回放 / 合成 / 混合</td><td>回放需路由标签存储</td><td>合成占比高时门控统计偏移</td></tr><tr><td>分层粒度</td><td>全局 / 按专家 / 按路由桶</td><td>显存随粒度线性增长</td><td>按层聚合时无法定位专家</td></tr><tr><td>统计对象</td><td>权重 / 激活 / 门控分数</td><td>激活统计需前向回放算力</td><td>长序列桶不足时离群值失真</td></tr></tbody></table>\n<h3 id=\"ap-quant-calib-pipeline-sec-8\">八 · 速查表主结构与九列口径</h3>\n<p>这张表是给工程同学直接抄进配置仓库的：每一行对应一个校准条目（一个模型、一种量化格式、一套分层策略的组合），九列缺一不可。列的顺序本身有讲究——前三列决定“采什么”，中间三列决定“怎么算”，后三列决定“怎么验收”。采样分层键与每专家最少 token 数必须成对出现，因为前者只声明分层维度（全局/按专家/按路由桶），后者才是把长尾专家从“零覆盖”拉回“可统计”的硬约束。序列长度分桶列不是自由文本，必须写成短/中/长三档的具体 token 区间，否则后面统计收集脚本无法按桶对齐激活离群值。统计收集脚本入口列写的是可执行入口而非描述，块缩放搜索步长列写的是搜索网格的量化步长而非迭代次数，top-k 一致率阈值列与回归比对工具命令列构成闭环：前者是判定线，后者是产出判定所需数据的命令。九列中任何一列为空，该条目视为未完成校准，不允许进入量化产物构建。</p>\n<table class=\"mini\"><thead><tr><th>列</th><th>取值口径</th><th>空缺后果</th></tr></thead><tbody><tr><td>条目名</td><td>模型标识 + 量化格式 + 分层策略三元组</td><td>产物无法追溯，回归失败时无法定位条目</td></tr><tr><td>量化格式</td><td>NVFP4 或 FP8，二选一，不混填</td><td>块缩放搜索步长失去意义</td></tr><tr><td>采样分层键</td><td>全局 / 按专家 / 按路由桶</td><td>长尾专家与头部共用缩放</td></tr><tr><td>每专家最少 token 数</td><td>数百至上千量级的硬下限</td><td>块缩放退化为全局默认值</td></tr><tr><td>序列长度分桶</td><td>短/中/长三档的具体区间</td><td>激活离群值统计失真</td></tr><tr><td>统计收集脚本入口</td><td>可执行入口，按层且按专家拆分</td><td>回归无法定位到具体专家</td></tr><tr><td>块缩放搜索步长</td><td>搜索网格的量化步长</td><td>块缩放上限被低估</td></tr><tr><td>top-k 一致率阈值</td><td>量化前后路由 top-k 重合率的判定线</td><td>路由漂移不可见</td></tr><tr><td>回归比对工具命令</td><td>产出逐专家一致率的命令行</td><td>阈值无数据可判</td></tr></tbody></table>\n<p>代价口径要写清：这张表每多一行，校准集的显存占用就按“每专家最少 token 数 × 序列长度桶数 × 统计对象数”线性增长；而统计收集脚本若按层聚合而不按专家拆分，显存是省了，但回归比对工具拿不到逐专家一致率，等于把定位能力换成了显存。工程判断是：分层粒度选“按专家”时，统计收集必须逐专家落盘，宁可多占一份中间存储，也不要事后从层聚合结果里反推专家。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-9\">九 · 阈值三档与过采样加权公式</h3>\n<p>阈值不是拍脑袋的一个数，而是三档联动：每专家最少 token 数、序列长度桶的最小样本占比、top-k 一致率判定线。领域经验给的是每专家至少覆盖数百至上千 token 才能稳定块缩放；长尾专家不足时按路由概率加权过采样。加权公式写成采样配额分配：</p>\n<div class=\"formula\">$$q_e = \\max\\left(n_{\\min},\\ \\left\\lceil N_{\\text{total}} \\cdot \\frac{p_e^{\\gamma}}{\\sum_{e'} p_{e'}^{\\gamma}} \\right\\rceil\\right)$$</div>\n<p>其中 $p_e$ 是专家 $e$ 的路由概率，$\\gamma$ 是过采样锐度（$\\gamma=1$ 为按概率正比分配，$\\gamma&gt;1$ 向长尾倾斜），$n_{\\min}$ 即每专家最少 token 数下限。这个式子的工程含义是：头部专家按概率拿配额，长尾专家被 $n_{\\min}$ 托底，两者取大。若只用均匀随机提示采样，$p_e$ 极小的专家配额趋近于零，块缩放退化为全局默认值，量化后该专家输出误差显著高于头部专家——这是最常见踩坑，速查表里“采样分层键”列填“全局”就是它的直接诱因。序列长度分桶的阈值同理：短、中、长三档各自要有最小样本占比，长序列桶样本过少会让激活离群值统计失真，块缩放上限被低估。代价上，$\\gamma$ 调大提升长尾覆盖，但校准集总 token 数上升，收集脚本的显存与离线时长同步上涨；判断标准是长尾专家配额刚好达到 $n_{\\min}$ 即停止加大 $\\gamma$，不再为边际覆盖付费。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-10\">十 · 块缩放搜索步长与统计对象对齐</h3>\n<p>块缩放搜索步长这一列直接决定量化误差的地板。搜索是在每个块上找缩放因子，步长过粗会把最优缩放跳过，表现为块缩放上限被低估；步长过细则搜索耗时按网格点数线性膨胀。伪代码思路：对每个块枚举候选缩放 $s \\in \\{s_0, s_0+\\delta, \\dots\\}$，以该块内激活或权重的最大绝对值定上界，选使量化误差最小的 $s$；$\\delta$ 就是速查表里的步长列。统计对象必须与步长口径对齐：统计对象填“权重”时，块内统计只需权重张量，显存占用低；填“激活”时，收集脚本要跑前向并缓存逐层激活，显存与带宽代价显著上升；填“门控分数”时，统计的是路由输入而非专家内部，用于校验路由一致性而非块缩放本身。三者组合决定校准集规模与显存占用，速查表里不允许把“激活+门控分数”塞进同一行而不注明两份统计分开落盘。</p>\n<p>具体例子：某 MoE 模型按路由桶分层，头部专家配额充足、长尾专家靠 $n_{\\min}$ 托底；若统计收集脚本按层聚合，长尾与头部共用一套缩放参数，则块缩放搜索在长尾块上实际是在用头部块的统计定上界，量化后路由一致性回归只能看到“某层一致率下降”，无法定位到具体专家。正确做法是脚本入口按“层 × 专家”双键落盘，回归比对工具命令按专家维度输出一致率，速查表两列必须成对填写。代价是中间统计存储按专家数倍增，但换来的是回归可定位性——这是本管线最值得付的一笔显存。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-11\">十一 · 回归比对工具命令与判定闭环</h3>\n<p>回归比对工具命令列不是装饰：它要产出量化前后逐专家的路由 top-k 重合率，供 top-k 一致率阈值列判定。命令的最小语义是“输入原始模型与量化模型、输入校准集回放流量、输出按专家分组的一致率表”。判定闭环是：一致率低于阈值的专家，回查其配额是否达到 $n_{\\min}$、序列长度桶是否覆盖、统计是否按专家拆分；三者任一不满足，则该条目的校准视为无效，而不是调低阈值蒙混。工程代价上，回归比对要跑两遍前向（原始与量化），其耗时与校准集规模成正比，因此校准集规模要在“覆盖长尾”与“回归可跑”之间取平衡；判断是回归比对必须全量跑校准集而非抽样，因为长尾专家样本本就稀少，抽样会把唯一能暴露漂移的样本抽掉。</p>\n<p>失败模式的排查顺序写进速查表备注：先看序列长度分布与线上实际分布是否偏离（长序列桶样本过少→激活离群值统计失真→块缩放上限被低估），再看统计收集是否按专家拆分（未拆分→长尾与头部共用缩放→回归无法定位到具体专家），最后看采样是否只用均匀随机提示（长尾专家 token 数为零→块缩放退化为全局默认值）。这三条对应速查表的三列，排查即查表。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-12\">十二 · 填表时的三条硬约束</h3>\n<ul>\n<li>量化格式列与块缩放搜索步长列必须同源：NVFP4 与 FP8 的步长口径不同，混填会让搜索网格失去物理意义，直接表现为块缩放上限被低估。</li>\n<li>采样分层键填“按路由桶”时，每专家最少 token 数列不得留空，且必须与过采样公式中的 $n_{\\min}$ 一致；留空即等于允许长尾专家零覆盖。</li>\n<li>统计收集脚本入口与回归比对工具命令必须指向同一份逐专家落盘目录；入口按层聚合、命令按专家读取的组合是无效配置，速查表校验脚本应直接拒绝该行入库。</li>\n</ul>\n<p>这三条约束的代价都是显存与离线时长，收益是可定位的量化误差。工程判断落在最后一条：当显存预算不足以支撑逐专家落盘时，优先砍序列长度桶数而不是砍专家维度——桶少了只影响离群值统计精度，专家维度没了则整条回归链路失效，长尾专家的块缩放再也无法被验证。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-13\">十三 · 速查表的适用边界：何时这张表会失效</h3>\n<p>这张速查表把“条目名—量化格式—分层键—每专家最少 token—长度分桶—统计脚本入口—块缩放步长—top-k 一致率阈值—回归命令”九列钉死，本质是把校准集构造约束成一组可审计的契约。它成立的前提是三条同时满足：采样来源与线上路由分布同源（真实流量回放或按路由概率加权的混合），分层粒度细到专家级而非全局级，统计对象按权重/激活/门控分数分开收集。任一前提破裂，表里的阈值就失去意义——例如分层键写成“全局”时，每专家最少 token 数这一列无从校验，块缩放搜索会退化为全局默认值。表的价值不在于数字本身，而在于把“校准集是否覆盖了长尾专家”从定性判断变成可对照的字段。</p>\n<p>失效条件集中在两类。其一是长度分布偏离：当校准集序列长度分桶的长桶样本过少，激活离群值统计被短序列主导，块缩放上限被低估，量化后长上下文激活的动态范围被截断。其二是统计聚合粒度错误：收集脚本按层聚合而未按专家拆分时，长尾专家与头部专家共用一套缩放参数，此时 top-k 一致率回归只能报出“某层不一致”，无法定位到具体专家，排查成本从一次字段比对退化为逐专家重跑。两种失效都不会在离线指标上显形，只在线上路由一致性回归中暴露。</p>\n<div class=\"formula\">$$\\text{有效校准 token}_e=\\sum_{s\\in\\text{buckets}} n_{e,s}\\cdot w_s,\\quad w_s\\propto \\frac{p_s^{\\text{online}}}{p_s^{\\text{calib}}}$$</div>\n<p>上式给出速查表“每专家最少 token”一列的校验口径：按长度桶加权后的有效 token 数，权重取线上与校准集桶概率之比。工程代价随之而来——按路由概率过采样长尾专家会推高校准集规模与显存占用，统计收集阶段逐专家拆分使聚合脚本的中间张量从每层一份变为每层×专家数，显存与带宽开销随专家并行度线性上升；块缩放搜索步长调细则拉长离线搜索的墙钟时间。判断准则很直接：若某专家的有效 token 数低于表列下限且其路由概率不可忽略，就必须过采样而非接受默认缩放；若回归工具无法按专家输出一致率，先修脚本入口再谈阈值。</p>\n<h3 id=\"ap-quant-calib-pipeline-sec-14\">十四 · 阈值的来源：从“每专家 token 数”倒推校准集规模</h3>\n<p>校准集规模不是拍脑袋定的，它由三个约束反推：块缩放估计的方差、显存占用、以及离线管线跑一遍的墙钟时间。核心约束是每专家 token 数。NVFP4 的块缩放沿权重块与激活块分别搜索，块内元素共享一个缩放因子，缩放因子的估计误差直接进入该块的量化误差；token 数越少，激活块统计量的样本方差越大，缩放上限越容易被低估——这正是长尾专家在均匀采样下退化的机理。</p>\n<p>设某专家 <i>e</i> 在路由桶 <i>b</i> 中被选中的概率为 <i>p<sub>e,b</sub></i>，校准集总 token 数为 <i>N</i>，则该专家期望校准 token 数为 <i>N·p<sub>e,b</sub></i>。要让每个专家都达到最小覆盖 <i>n<sub>min</sub></i>，需满足：</p>\n<div class=\"formula\">$$N \\ge \\frac{n_{\\min}}{\\min_{e,b} p_{e,b}} \\quad\\text{或等价地}\\quad N = \\sum_{e} \\max\\left(n_{\\min},\\; n_{\\min}\\cdot\\frac{p_{\\text{head}}}{p_e}\\right)$$</div>\n<p>第二个式子是按路由概率加权过采样的直接写法：头部专家按自然分布取，长尾专家被抬到 <i>n<sub>min</sub></i> 以上。领域经验是 <i>n<sub>min</sub></i> 取数百至上千 token 才能稳定块缩放；低于这个量级，激活离群值统计失真，块缩放上限被低估，量化后该专家输出误差显著高于头部专家。代价很直接：<i>N</i> 抬升线性推高校准激活的显存占用（每层激活按 token 数 × 隐藏维 × 精度计），也线性推高统计收集脚本的墙钟时间。工程判断是先把 <i>n<sub>min</sub></i> 定死，再看 <i>N</i> 是否落在单卡或单节点的显存预算内；超了就把分层粒度从“按专家”降到“按路由桶”，用桶内共享统计换显存。</p>\n<p>具体例子：某 MoE 层有 64 个专家，路由概率呈幂律，头部专家 <i>p</i>≈0.08，尾部专家 <i>p</i>≈0.0005。若 <i>n<sub>min</sub></i>=512，尾部专家需要约 10<sup>6</sup> 个 token 才自然覆盖，显然不可行；按上式加权过采样后，总 <i>N</i> 被压到尾部专家 512 token、头部专家按自然比例的量级，校准集规模从百万级降到十万级，显存与时间都可接受。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-15\">十五 · 序列长度分桶：三档覆盖与长序列桶的样本下限</h3>\n<p>序列长度分布偏离是校准集最常见的失真源。激活离群值在长序列上更容易出现（注意力与 KV 路径的累积效应），若长序列桶样本过少，激活统计量的高分位被系统性低估，块缩放上限随之被低估。工程做法是短、中、长三档分桶，每档独立统计、独立搜索块缩放，而不是把所有长度混在一起聚合。</p>\n<p>每档的样本下限不能按 token 总数平摊，要按“桶内独立序列条数”计：长序列桶单条序列就贡献大量 token，但序列间相关性高，独立样本数远小于 token 数。伪代码思路：</p>\n<div class=\"formula\">$$\\text{for each bucket } b:\\quad n_{\\text{seq}}(b) \\ge \\max\\left(n_{\\min}^{\\text{seq}},\\; \\frac{c}{\\text{var}(\\hat{s}_b)}\\right)$$</div>\n<p>其中 <i>ŝ<sub>b</sub></i> 是该桶块缩放估计量，<i>c</i> 是由目标相对误差反推的常数。没有实验数字时，测法很明确：固定其余两桶，只对长序列桶做自助重采样（bootstrap），观察块缩放估计的相对波动随序列条数的收敛曲线，取波动降到目标误差以内的最小条数作为下限。代价方面，长序列桶直接决定校准阶段的峰值显存——单条长序列的激活张量可能比短序列大一个量级以上，分桶收集而不是一次性全量加载，是控制峰值显存的必要手段。</p>\n<p>具体例子：线上流量短序列占多数、长序列占少数但承载了大部分 token。若校准集按请求条数均匀采样，长序列桶的序列条数会远低于下限，激活离群值统计失真；改为按 token 数加权、并对长序列桶设独立条数下限后，长序列桶的块缩放上限才与线上一致。这里的关键判断是：分桶键必须与线上监控的序列长度分布用同一套分位定义，否则离线桶与线上桶对不上，回归比对无法定位偏差来源。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-16\">十六 · 块缩放搜索步长：搜索精度与离线成本的折中</h3>\n<p>块缩放搜索是在每个块的缩放候选网格上找使量化误差最小的点。步长决定网格密度：步长越细，缩放上限估计越准，但搜索次数线性增长，离线管线墙钟时间与统计脚本的吞吐直接承压。NVFP4 的块缩放粒度比 FP8 更细（块更小、块数更多），同样的步长意味着更多的独立搜索，这是 NVFP4 校准比 FP8 更贵的主要来源。</p>\n<p>搜索流程的伪代码思路是分层搜索而非全网格暴力：先粗步长定位候选区间，再在区间内细步长收敛，误差度量用块内量化后重建误差（或加权分位误差）。公式上，若候选网格点数为 <i>G</i>、块数为 <i>B</i>、每块统计收集成本为 <i>c<sub>s</sub></i>，则离线总成本约为 <i>G·B·c<sub>s</sub></i>；把 <i>G</i> 从全网格降到两级搜索，成本降一个量级而缩放上限的偏差可控。</p>\n<p>步长怎么定，没有数字时这样测：对同一批校准统计，用逐步减半的步长跑搜索，记录块缩放估计的相对变化；当步长减半带来的估计变化小于量化误差本身的量级时，再细的步长不再有收益。代价判断落在两处：一是离线管线的墙钟时间（决定校准集能否在版本发布窗口内重跑），二是缩放参数的存储与加载开销（每块一个缩放因子，块越细、参数越多，推理时的反量化路径访存压力越大）。具体例子：某层权重块数在 NVFP4 下是 FP8 的数倍，若沿用 FP8 的搜索步长，搜索次数同比放大，离线时间成为瓶颈；改为按块大小自适应步长后，头部块用细步长、长尾块用粗步长，总搜索次数回落而长尾专家的缩放上限仍被覆盖。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-17\">十七 · top-k 一致率阈值：路由一致性回归的判据</h3>\n<p>量化后路由一致性回归是校准管线的最后一道闸门：它比对量化前后同一批校准/回归提示上的 top-k 路由结果，用一致率作为放行判据。一致率的定义要写死：对每个 token，量化前后 top-k 专家集合的交集大小除以 k，再对 token 取平均；按专家拆分统计，才能定位到具体专家。</p>\n<div class=\"formula\">$$\\text{agree} = \\frac{1}{T}\\sum_{t=1}^{T}\\frac{|\\,\\text{top-}k_{\\text{fp}}(t)\\cap \\text{top-}k_{\\text{q}}(t)\\,|}{k},\\qquad \\text{agree}_e \\text{ 按专家 } e \\text{ 单独统计}$$</div>\n<p>阈值没有给定数字，测法是：先用未量化的模型跑两遍不同随机种子/不同批次的回归集，得到一致率的上界（这是路由本身的数值噪声底），再把量化后的一致率与之比较；阈值应设在噪声底之下一个可接受裕度，而不是拍一个绝对值。按专家拆分统计是硬要求——统计收集脚本若按层聚合而未按专家拆分，长尾专家与头部专家共用一套缩放参数，量化后路由一致性回归就无法定位到具体专家，只能看到一个层级的平均一致率，掩盖了长尾专家的系统性漂移。</p>\n<p>代价落在回归集的规模与重跑频率上：一致率是按 token 统计的，回归集 token 数不足时，长尾专家的 <i>agree<sub>e</sub></i> 方差极大，阈值判定不可靠。工程判断是把回归集按路由桶分层，保证每个专家在回归集里有足够 token，回归比对工具的命令行入口固定为可复现的一键比对（同一校准集、同一回归集、同一随机种子），使一致率差异只归因于量化参数变化。具体例子：某次校准后层级平均一致率达标，但按专家拆分后发现尾部专家一致率显著偏低，追溯发现该专家校准 token 数不足、块缩放退化为全局默认值——这正是回归工具按专家拆分才能暴露的失败模式。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-18\">十八 · 统计收集脚本的入口与聚合键：可测量性先于数字</h3>\n<p>所有阈值的可信度都建立在统计收集脚本的聚合键正确之上。脚本入口要固定、可复现，聚合键必须是“层 × 专家 × 路由桶 × 序列长度桶”的组合，而不是层内平均。聚合键错一层，后面所有阈值都失去意义：按层聚合会把长尾专家的离群值摊薄进头部专家，块缩放搜索拿到的是混合统计，量化后误差在长尾专家上放大而回归工具定位不到。</p>\n<p>测量方法上，脚本应输出每个聚合单元的样本计数与分位统计，并附带一个覆盖检查：对每个专家，报告其校准 token 数是否达到 <i>n<sub>min</sub></i>，未达标的专家列表直接作为校准集重采样的输入。这是一个闭环——覆盖检查的输出驱动按路由概率加权过采样，过采样后的校准集再跑一遍统计，直到未达标列表为空。代价是脚本的 I/O 与聚合开销随聚合单元数增长，单元数 = 层数 × 专家数 × 桶数，在专家数大的 MoE 上这个乘积不小；工程上按桶分批落盘、按专家增量聚合，避免一次性把全部统计量驻留显存。</p>\n<p>具体例子：脚本按层聚合时，某层平均块缩放看起来正常，但按专家拆分后发现尾部专家的激活分位统计几乎为空，其块缩放退化为全局默认值；把聚合键改为按专家后，覆盖检查立刻列出未达标专家，重采样补齐 token 数，回归比对的一致率按专家拆分也随之上报。这里的工程判断是：先保证聚合键与覆盖检查可测量，再谈阈值取多少；没有可测量性，任何经验数字都只是对平均值的猜测。</p>\n\n\n<h3 id=\"ap-quant-calib-pipeline-sec-19\">十九 · 校准集失效的边界条件与代价核算</h3>\n<p>校准管线并非“采一批提示、跑一遍统计”就收敛。它的失效边界由三件事界定：长尾专家的 token 覆盖是否越过块缩放可辨识的门槛、序列长度分桶是否与线上分布同形、统计聚合粒度是否保住了专家维度。经验判据是每专家至少覆盖数百至上千 token 才能稳定块缩放；低于此门槛时，该专家的缩放搜索退化为全局默认值，量化后其输出误差显著高于头部专家。工程上应把这条门槛写成可计算的准入条件：设专家 e 的校准 token 数为 n<sub>e</sub>、路由概率为 p<sub>e</sub>，则按路由概率加权过采样的目标配额可写为</p>\n<div class=\"formula\">$$n_e^{\\text{target}} = \\max\\left(n_{\\min},\\; N \\cdot \\frac{p_e^{\\gamma}}{\\sum_{j} p_j^{\\gamma}}\\right),\\quad \\gamma&gt;1$$</div>\n<p>γ 抬高长尾权重，n<sub>min</sub> 是硬下限。代价是显存与采集时长：校准集规模随专家数与序列长度分桶数近似线性增长，激活统计需常驻逐层缓冲，长序列桶样本会把单次前向的激活峰值推高，进而压缩可并行采集的 batch 上限。因此配额不是越大越好，而是在“长尾专家可辨识”与“采集显存可承受”之间取点。</p>\n<p>第二个边界是长度分布偏离。校准集若短、中、长三档覆盖失衡，长序列桶样本过少，激活离群值统计失真，块缩放上限被低估——量化后长上下文场景的激活截断误差在线上才暴露，而离线回归看不出来。测量方法不依赖猜测：从真实流量回放中抽取长度直方图，与校准集直方图做逐桶 KL 或最大偏差比对，偏差超限即触发补采；补采按桶配额而非均匀随机，避免再次踩“均匀随机提示采样致长尾专家 token 为零”的坑。</p>\n<p>第三个边界是聚合粒度。统计收集脚本若按层聚合而未按专家拆分，长尾与头部专家共用一套缩放参数，量化后路由一致性回归无法定位到具体专家，只能看到整体 top-k 一致率下降，排查成本陡增。工程判断是：统计对象必须保留（层 × 专家 × 路由桶）三元键，回归比对工具按专家维度输出一致率明细，把阈值卡在“单专家一致率”而非全局均值上。代价是统计产物体积与比对耗时上升，但换来的是失效可归因——这比事后在整网误差里反推便宜得多。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>可测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>长尾专家 token 不足</td><td>每专家 token 计数低于门槛</td><td>该专家缩放退化，输出误差抬升</td></tr><tr><td>长度桶偏离</td><td>校准与回放长度直方图偏差</td><td>长序列激活离群统计失真</td></tr><tr><td>按层聚合</td><td>回归无法定位到专家</td><td>排查耗时、返工采集</td></tr></tbody></table>\n<h3 id=\"ap-quant-calib-pipeline-sec-20\">二十 · 踩坑清单：从采样偏差到统计粒度错位</h3>\n<p>校准管线的失败几乎从不以“脚本报错”的形式出现，而是以“量化后某个专家悄悄变差”的形式潜伏下来。按发生位置归类，坑集中在四处。第一处是采样层：只用均匀随机提示采样，长尾专家在校准集中命中 token 数为零，其块缩放搜索无数据可依，退化为全局默认缩放，量化后该专家输出误差显著高于头部专家，而全局指标被头部专家稀释，看不出异常。第二处是分布层：校准集序列长度分布与线上实际分布偏离，长序列桶样本过少，激活离群值统计失真，块缩放上限被低估——长序列里少数极大激活值恰恰决定了该桶的缩放上限，样本不足时上限偏低，量化后这些激活被截断，误差在长上下文场景集中爆发。第三处是统计粒度层：收集脚本按层聚合而未按专家拆分，长尾与头部专家共用一套缩放参数，回归比对只能定位到“某层变差”，无法定位到具体专家。第四处是回归层：量化后路由一致性回归没有基线快照，top-k 一致率下降时无法判断是量化引入还是路由本身波动。</p>\n<p>这四类坑的共同结构是：错误发生在离线管线，代价显现在线上推理。以 MoE 模型为例，单个长尾专家校准缺失带来的代价不是全局吞吐下降，而是该专家被路由命中时出现局部精度塌陷——按路由概率加权，若该专家承载 2% 的 token，端到端指标只损失可忽略的幅度，但命中它的请求延迟与质量双双劣化，SLO 按 P99 统计时直接暴露。工程判断是：校准管线的验收标准必须按专家粒度而非全局粒度设定，任何“全局指标正常”都不构成放行依据。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-21\">二十一 · 检查顺序：先采样覆盖，再统计粒度，后缩放搜索</h3>\n<p>检查必须按依赖顺序进行，因为后一环的正确性以前一环为前提。顺序如下：采样覆盖 → 分层键完整性 → 统计拆分粒度 → 序列长度分桶 → 块缩放搜索收敛 → 路由一致性回归。伪代码思路：</p>\n<div class=\"formula\">$$\\text{for each } e \\in \\text{experts}: \\quad n_e = \\sum_{s \\in \\mathcal{C}} \\mathbb{1}[\\text{route}(s) \\ni e] \\cdot |s|$$</div>\n<p>先算每个专家的有效校准 token 数 $n_e$，与速查表中“每专家最少 token 数”逐项比对；不足者按路由概率加权过采样补齐，而不是简单调大全局采样量。第二步验证分层键：采样来源（真实流量回放/合成提示/混合）、分层粒度（全局/按专家/按路由桶）、统计对象（权重/激活/门控分数）三轴组合是否与本次量化格式匹配——NVFP4 与 FP8 对激活离群值的敏感度不同，统计对象漏掉门控分数会让路由桶分层失去意义。第三步检查收集脚本输出结构：逐层/逐专家统计量是否真正按专家拆分，而非层内聚合后再广播。第四步核对序列长度分桶是否覆盖短、中、长三档且长桶样本量与线上占比匹配。第五步才进入块缩放搜索，检查搜索步长与上限是否被长桶数据支撑。最后跑量化后路由一致性回归，比对工具命令输出 top-k 一致率，与阈值列对照。</p>\n<p>顺序不可颠倒的代价很具体：若先跑缩放搜索再查采样覆盖，搜索会在缺失专家的层上产出“收敛”的假象，浪费一轮完整搜索的 GPU 时；若先跑回归再查统计粒度，回归只能给出层级别的告警，排查成本从“改一个分层键”升级为“重跑整条管线”。回归比对工具的价值在于把定位粒度压到专家级，前提是统计输出本身带专家维度。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-22\">二十二 · 长尾专家的过采样与缩放上限校验</h3>\n<p>长尾专家不足时的标准动作是按路由概率加权过采样：对路由概率 $p_e$ 低的专家，采样权重取 $1/p_e$ 的截断版本，使 $n_e$ 达到数百至上千 token 的覆盖下限。这里有一个容易忽略的代价：过采样会改变校准集的序列长度分布，若长尾专家恰好只在短序列上被命中，过采样后短桶占比上升，长桶被进一步稀释。因此过采样必须与长度分桶联合约束——按（专家 × 长度桶）二维配额采样，而不是只按专家配额。显存代价随之上升：逐专家、逐桶的激活统计量驻留显存，规模随专家数与桶数相乘增长，收集脚本需分片落盘而非全量驻留。</p>\n<p>缩放上限校验是第二个关口。长序列桶样本过少时，块缩放搜索得到的上限偏低，表现为该桶量化后激活截断率异常。校验方法是把搜索得到的上限与该桶激活统计的分位数对照：若上限显著低于统计分位数指示的范围，说明样本不足而非数据本身平缓，应回补长桶样本重跑搜索，而不是手动抬高上限——手动抬高会让缩放因子失去数据支撑，在头部专家上引入新的误差。这一步的推理系统代价是离线 GPU 时：每轮重跑搜索覆盖全部层与专家，属于管线中最重的一环，因此采样覆盖与分桶校验必须前置，避免搜索反复返工。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-23\">二十三 · 路由一致性回归的自动化比对与定位</h3>\n<p>量化后路由一致性回归的比对工具承担两件事：判定与定位。判定用 top-k 一致率对照速查表阈值；定位则要求比对输出按专家拆分，指出一致率下降集中在哪些专家、哪些路由桶。自动化比对的基本结构是：对固定提示集分别跑量化前基线快照与量化后模型，逐 token 记录 top-k 路由集合，按专家聚合不一致计数，输出（专家 ID，不一致率，涉及长度桶）三元组。若统计收集阶段未按专家拆分，这一步只能退化为层级别比对，定位能力丧失——这正是“统计粒度错位”坑的代价在回归阶段的兑现。</p>\n<p>回归的工程代价在吞吐侧：比对需要完整前向两遍（基线一遍、量化后一遍），提示集规模决定离线机时。实践上把回归集与校准集分离，回归集取真实流量回放的小样本，覆盖各长度桶与各路由桶，避免用校准集自评——校准集上的一致率天然偏好，无法暴露长尾专家的退化。另一个判断是：回归不通过时不要直接回滚整条管线，先看三元组分布，若不一致集中在少数专家，回滚范围应缩到这些专家的缩放参数与采样配额，重跑局部搜索即可；只有不一致弥散到多层多专家，才触发全量回滚。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-24\">二十四 · 回滚方案：分级回滚与基线快照</h3>\n<p>回滚方案按影响面分三级。一级是参数级：仅回滚个别专家的块缩放参数到上一版，保留其余量化结果，代价最小，适用于回归三元组定位明确的场景。二级是分层键级：回滚采样配方（例如从按专家分层退回按路由桶分层并补采样），重跑统计收集与缩放搜索，代价是一轮完整离线管线机时。三级是全量级：整条校准集与量化产物回退到上一基线快照，适用于一致率弥散下降或无法定位的情形。三级回滚的前提是基线快照必须包含三样东西：校准集采样配方与随机种子、逐层/逐专家统计量原始输出、块缩放搜索结果与对应的路由一致率记录。缺任一项，回滚后无法复现上一版行为，只能盲回退。</p>\n<p>回滚的推理系统代价需要提前量化：一级回滚只影响离线参数文件，线上推理无感；二级回滚期间线上仍跑旧量化产物，无服务中断，但新版本上线推迟一个管线周期；三级回滚意味着放弃本轮全部量化收益，若线上已切到新产物，需一次权重热切换，切换窗口内的显存峰值与加载延迟是必须预留的容量。工程判断是：把一级回滚做成常态能力——每次缩放搜索产出按专家粒度的参数包与独立校验记录，使局部回滚成为默认路径，全量回滚只作为兜底。校准管线的成熟度不体现在一次跑通，而体现在失败时能以多小的代价退回已知良好状态。</p>\n\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失败表征</th><th>回滚级别</th><th>主要代价</th></tr></thead><tbody><tr><td>每专家 token 覆盖</td><td>长尾专家缩放退化为全局默认</td><td>二级（补采样重跑）</td><td>一轮管线机时</td></tr><tr><td>序列长度分桶</td><td>长桶激活截断率异常</td><td>二级（回补长桶）</td><td>缩放搜索重跑</td></tr><tr><td>统计拆分粒度</td><td>回归只能定位到层</td><td>二级（改脚本重收集）</td><td>统计收集全量重跑</td></tr><tr><td>top-k 一致率</td><td>少数专家不一致集中</td><td>一级（参数包回退）</td><td>离线参数替换，线上无感</td></tr><tr><td>基线快照缺失</td><td>无法复现上一版</td><td>三级（全量回退）</td><td>权重热切换窗口</td></tr></tbody></table>\n\n<p>把这张表嵌进管线脚本的出口检查：任何一项未通过即阻断产物发布，而不是等线上回归告警再补救。校准数据管线的可靠性来自检查顺序的强制性与回滚粒度的可执行性，两者共同决定量化产物能否在长尾专家上稳定交付。</p>\n\n\n<h3 id=\"ap-quant-calib-pipeline-sec-25\">二十五 · 校准管线的失效边界与回滚判据</h3>\n<p>这条管线最脆弱的环节不是采样算法，而是<strong>统计口径与部署拓扑的对齐</strong>。当模型以专家并行（EP）切分时，每张卡只持有部分专家，校准脚本若在单卡上按层聚合，得到的激活分位数是跨专家的混合分布，块缩放搜索会把头部专家的高幅值离群点当成全局上界，长尾专家被迫共用一套偏保守的缩放参数——量化后其输出被系统性压小。判定失效的信号很直接：路由一致性回归中，top-k 一致率在头部路由桶上正常，却在低频桶上成片跌落，且跌落位置与专家切分边界重合。此时必须按专家拆分统计入口，以每专家 token 数为权重做路由概率加权过采样，再重跑块缩放搜索。</p>\n<p>第二个边界是序列长度分桶的覆盖度。校准集的短桶样本天然占多数，长桶样本稀少，而激活离群值几乎全部由长序列的 attention 与 MLP 中间态贡献。设第 <em>b</em> 个长度桶的样本数为 <em>n<sub>b</sub></em>、桶内激活分位数为 <em>q<sub>b</sub></em>，则全局缩放上界可写成 <em>S</em> = max<sub>b</sub>(<em>q<sub>b</sub></em>) 与按 <em>n<sub>b</sub></em> 加权的稳健估计之间的较大者；当长桶 <em>n<sub>b</sub></em> 低于阈值时，<em>q<sub>b</sub></em> 的方差主导结果，块缩放上限被低估，NVFP4 的 E4M3 缩放因子在推理时反复饱和，表现为吞吐不变但精度骤降。检查顺序应是：先验证长度桶样本数与线上分布的分位对齐，再验证逐专家统计是否独立，最后才看 top-k 一致率——顺序颠倒会把采样偏差误判为量化算法问题。</p>\n<p>回滚方案要按代价分层，不能一律重跑全管线。最轻的一级是仅回退块缩放搜索步长与 top-k 阈值，保留已采集统计量，代价是一次离线搜索的显存与算力开销；中间一级是回退采样配方（换回真实流量回放或提高长尾过采样倍率），代价是重新采集统计量并占用校准集显存；最重一级是回退量化格式本身（NVFP4 降级为 FP8），代价是权重显存翻倍、单卡可容纳的 KV cache 预算被压缩，直接改变容量规划。下表给出触发条件与代价的对应关系。</p>\n<table class=\"mini\"><thead><tr><th>触发信号</th><th>回滚层级</th><th>系统代价</th></tr></thead><tbody><tr><td>低频路由桶 top-k 一致率跌落且与 EP 边界重合</td><td>按专家拆分统计入口并重采</td><td>校准集显存与采集时长增加</td></tr><tr><td>长序列桶样本不足、缩放因子饱和</td><td>重设长度分桶与过采样倍率</td><td>离线采集算力，线上无影响</td></tr><tr><td>逐专家误差普遍超标且无法定位</td><td>NVFP4 降级 FP8</td><td>权重显存翻倍，KV cache 预算收紧</td></tr></tbody></table>\n<p>检查清单的落地形式应是脚本化的断言而非人工目检：每专家最少 token 数、长度桶样本占比、统计文件是否含专家维度键、top-k 一致率是否分桶报告，四项任一不满足即阻断发布。工程判断上，宁可让校准管线多跑一轮采集，也不要在推理时用饱和的缩放因子去赌精度——后者的代价藏在 SLO 之外，直到容量规划阶段才暴露。</p>\n<h3 id=\"ap-quant-calib-pipeline-sec-26\">二十六 · 上游依赖：校准管线吃的是谁产出的分布</h3>\n<p>校准数据管线在全书里不是孤立工具，它的输入契约由三个上游条目共同定义，任何一环变更都会让校准集失效。第一是路由分布：MoE 路由术语速查定义了 top-k 选择与路由桶的语义，校准管线的分层采样键直接建立在这套语义上——按专家 ID 分层、按路由概率分桶，都是对路由输出的再切片。第二是真实流量形态：容量因子与丢弃代价决定了线上请求在专家间的实际落点，校准集若按理论均匀分布采样，就会与丢弃发生后的真实 token 分布错位。第三是并行切分：专家并行与 All-to-All 决定了每个 rank 上驻留哪些专家，校准统计必须按本地专家而非全局专家聚合，否则统计收集脚本会在错误的粒度上求均值。</p>\n<p>这三条依赖可以用一个约束式表达。设全局专家集合为 $E$，rank $r$ 上的本地专家子集为 $E_r$，校准集为 $S$，则每个 rank 的统计收集必须满足：</p>\n<div class=\"formula\">$$\\forall e \\in E_r:\\quad n_e(S) \\ge n_{\\min},\\qquad S = \\bigcup_{b \\in \\text{buckets}} S_b$$</div>\n<p>其中 $n_e(S)$ 是校准集中落入专家 $e$ 的 token 数，$n_{\\min}$ 是每专家最少 token 阈值，$S_b$ 是按路由桶与序列长度桶切出的子集。这个式子的工程含义是：上游任何一个条目改变了 $E_r$ 的划分（换并行度、换专家放置策略），校准集就必须重新按新的本地专家视图切分，而不是复用旧的全局统计。代价体现在离线侧——重新采样与重跑统计收集脚本要占用整机显存与带宽，尤其当校准集需要覆盖长尾专家而过采样时，激活统计的显存占用随 $n_{\\min}$ 与专家数线性上升。</p>\n<p>具体例子：一个 64 专家、8 路专家并行的部署，每个 rank 驻留 8 个专家。若校准集按全局 64 专家均匀采样，单个 rank 上长尾专家的 token 数会被稀释到阈值以下；正确做法是在每个 rank 的本地视图内按路由概率加权过采样，使 8 个本地专家都达到 $n_{\\min}$。这一步不做，下游的块缩放搜索就没有可用的逐专家统计。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-27\">二十七 · 下游影响：块缩放与路由一致性回归都靠它喂数</h3>\n<p>校准管线的直接下游是 NVFP4/FP8 权重激活条目里的块缩放搜索。块缩放搜索需要逐层、逐专家的激活最大值与分布尾部信息，这些量只能由校准统计收集脚本产出。管线给出的统计对象有三类：权重、激活、门控分数。权重统计决定权重块的缩放因子，激活统计决定激活块的缩放上限，门控分数统计则服务于量化后路由一致性回归——因为门控分数是 top-k 选择的直接输入，量化误差在门控上的放大倍数决定了路由是否漂移。</p>\n<p>块缩放搜索的伪代码思路可以写成：对每个专家 $e$ 与每个块 $j$，在候选缩放集合 $\\mathcal{S}$ 上最小化量化误差：</p>\n<div class=\"formula\">$$s^*_{e,j} = \\arg\\min_{s \\in \\mathcal{S}} \\left\\| W_{e,j} - \\text{dequant}\\big(\\text{quant}(W_{e,j}; s)\\big) \\right\\|^2$$</div>\n<p>候选集合 $\\mathcal{S}$ 的步长由速查表中的“块缩放搜索步长”列给定，而 $W_{e,j}$ 的统计范围来自校准集。若校准集对长尾专家覆盖不足，$s^*$ 会退化为全局默认值，该专家的量化误差显著高于头部专家——这正是量化后路由漂移条目所描述现象的根因之一。下游的路由一致性回归工具因此必须能定位到具体专家：它比对量化前后 top-k 选择的一致率，阈值由速查表的“top-k 一致率阈值”列给出，比对命令入口也在同一张表里。若统计收集脚本按层聚合而未按专家拆分，回归工具只能报出“某层不一致”，无法指出是哪个长尾专家被量化压垮，排查成本从分钟级升到小时级。</p>\n<p>系统代价在这里表现为三重耦合：校准集规模决定离线显存占用，块缩放搜索步长决定离线搜索时间，回归比对频率决定每次量化变更后的验证延迟。工程判断是——把回归比对做成量化流水线的强制门禁，而不是事后抽查；比对工具读的是校准管线落盘的逐专家统计与量化后重放的门控分数，两者必须同源同版本，否则一致率数字没有意义。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-28\">二十八 · 横向关系：与 KV 压缩、分离式预填解码共享“分布假设”</h3>\n<p>校准管线与 MoE 场景 KV 压缩条目共享同一个隐含假设：线上 token 分布是稳定的，且可以用离线采样近似。KV 压缩按层或按头决定保留哪些 token，其阈值若按均匀采样标定，会在长序列桶上失准；校准管线的序列长度分桶（短、中、长三档）正是为这类下游提供分布对齐的依据。两者的接口是序列长度桶的边界值：校准管线产出的分桶统计，直接告诉 KV 压缩条目在哪个长度区间需要更保守的保留策略。</p>\n<p>与分离式预填解码的关系则在批调度侧。分离式部署把预填与解码拆到不同资源池，预填阶段的激活分布与解码阶段差异明显——预填是长序列、高并行，解码是短序列、低并行但高频率。校准管线若只采一种形态，NVFP4 激活缩放会偏向一侧。工程做法是按预填/解码两种流量形态分别分层采样，并在速查表中把“采样来源”列标为混合，统计收集脚本按阶段打标。代价是校准集规模翻倍，离线显存占用上升，但换来的是两个资源池各自的激活离群值统计不失真。</p>\n<p>具体例子：一个分离式部署中，预填池看到的是 8K 以上长提示，解码池看到的是逐 token 生成。若校准集全部来自短提示回放，长序列桶样本过少，预填池的激活离群值统计失真，块缩放上限被低估，量化后预填阶段的激活截断误差会在长提示上累积。这不是理论风险，而是校准集序列长度分布与线上实际分布偏离的直接后果。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-29\">二十九 · 与剖析工具链和框架选型的接口</h3>\n<p>MoE 剖析工具链条目提供的是线上逐专家 token 计数与路由熵，这些数据是校准管线分层采样的先验。管线不应自行猜测路由分布，而应消费剖析工具落盘的专家直方图，按直方图做按比例分层抽样，再对低于 $n_{\\min}$ 的长尾专家做概率加权过采样。这条上游链路决定了校准集的代表性：剖析工具采样窗口若只覆盖高峰时段，校准集就会低估冷专家的权重，量化后冷专家的误差在低峰时段暴露。</p>\n<p>框架选型条目则决定校准统计的收集入口。TensorRT-LLM、vLLM、SGLang 各自暴露的逐层统计钩子不同：有的在量化插件里内置校准回调，有的需要外挂 hook 抓取激活。速查表的“统计收集脚本入口”列就是为跨框架对齐而设——同一份校准集配方，在不同框架上要落到不同的脚本入口，但统计对象与分层键必须保持一致，否则跨框架的量化结果无法比对。系统代价是维护成本：每接一个新框架，就要验证其钩子抓到的激活是否与块缩放搜索期望的张量布局一致，布局错位会让统计静默失真而不报错。</p>\n<p>具体例子：同一校准集在 vLLM 与 TensorRT-LLM 上分别跑统计收集，若前者按 token 聚合、后者按层聚合，两份逐专家统计的 $n_e$ 会对不上，块缩放搜索结果不可比。工程判断是把“统计粒度”写进校准集的元数据，作为跨框架比对的前置校验项。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-30\">三十 · 在全书中的位置：离线侧的唯一分布权威</h3>\n<p>把全书条目按数据流排开，校准数据管线处在离线侧的最上游：它消费路由分布与流量形态，产出逐层逐专家统计，供块缩放搜索与路由一致性回归消费，再往下才进入 NVFP4/FP8 权重激活、分组 GEMM 与 tcgen05 的执行路径。它不直接决定 kernel 性能，但决定了量化参数的质量——一个覆盖不足的校准集会让最好的 tcgen05 分组 GEMM 跑在错误的缩放因子上，吞吐再高也是错的。</p>\n<p>它与通信计算死锁、路由倾斜尾延迟这类运行时条目没有直接调用关系，但共享同一个分布视图：尾延迟条目关心的是长尾专家在高峰时的排队，校准管线关心的是长尾专家在量化后的误差放大，两者都以“长尾专家 token 数不足”为共同病灶。因此校准管线的分层采样配方，实际上也是尾延迟分析的数据底座。</p>\n<p>工程判断落在版本治理上：校准集、统计收集脚本、块缩放搜索步长、回归比对工具四者必须版本绑定。任何一方单独升级，都会让 top-k 一致率的数字失去可比性。把这条绑定写进量化流水线的元数据，是这套管线在全书里承担的最终职责——它不是一次性脚本，而是量化参数可复现性的锚点。</p>\n\n<h3 id=\"ap-quant-calib-pipeline-sec-31\">三十一 · 校准管线的上下游耦合与失效边界</h3>\n<p>这条管线在全书里处在“精度决策”与“服务运行时”之间的接缝上：上游吃的是路由分布与流量画像（连续批处理与路由条目给出的专家命中统计），下游把块缩放表交给 tcgen05 内核与 KV cache 的量化路径。它本身不产生任何在线收益，代价全部体现为离线开销——校准集规模直接决定统计收集阶段的显存占用与回放时长，按专家分层时显存约为“每专家 token 数 × 隐藏维 × 层数”的量级，长尾过采样会把这一项放大数倍。边界很清楚：当线上路由分布本身在漂移（微调后专家负载重排、或投机解码改变了接受路径），离线校准集就是过期快照，缩放表按旧分布拟合，误差在新热点专家上集中暴露。</p>\n<div class=\"formula\">$$\\,\\hat{s}_{e}=\\arg\\min_{s\\in S}\\ \\sum_{t\\in T_{e}}\\big\\lVert W_{e}x_{t}-\\mathcal{Q}_{s}(W_{e}x_{t})\\big\\rVert^{2},\\quad |T_{e}|\\ge N_{\\min}\\,$$</div>\n<p>上式点明了失效的第一个条件：每专家样本数低于下限时，块缩放搜索的解不唯一，搜索步长再细也只是在噪声上拟合。领域经验要求每专家覆盖数百至上千 token，长尾专家不足时按路由概率加权过采样；若省掉这一步，长尾专家的缩放退化为全局默认值，其输出误差显著高于头部专家——而路由一致性回归恰恰是在 top-k 层面比对，头部专家掩盖了长尾的偏移，工具报“通过”却掩盖了真实退化。第二个失效条件是序列长度分桶偏离线上分布：长序列桶样本过少时，激活离群值统计失真，块缩放上限被低估，长上下文请求一进来就出现逐层放大的截断误差。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>长尾专家 token 为零</td><td>该专家缩放等于全局默认</td><td>专家输出误差抬升，回归工具无法定位</td></tr><tr><td>按层聚合未按专家拆分</td><td>头尾专家共用一套参数</td><td>定位粒度丢失，返工需重跑全量统计</td></tr><tr><td>长度桶偏移</td><td>长序列桶样本稀疏</td><td>激活离群值低估，长上下文精度塌陷</td></tr></tbody></table>\n<p>第三个边界在工具链的耦合方式上：统计收集脚本若按层聚合而未按专家拆分，缩放表就失去“按专家”这一维，回归比对只能给出全局 top-k 一致率，无法把偏差归因到具体专家，工程上等于把一次可定位的修复变成一次全量重采。因此这条管线的正确位置是：向上要求路由统计具备专家粒度且与线上同分布，向下要求内核按专家索引缩放表、回归工具按专家输出一致率。当路由分布变动超出预设漂移阈值时，唯一稳妥的判断是重采校准集而非复用旧表——离线几小时的显存与回放代价，换的是在线不出现无法归因的精度缺口。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-quant-calib-pipeline\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>给出 NVFP4/FP8 校准集的采样配方：按路由分布分层采样、覆盖长尾专家、控制序列长度分布，说明校准统计的…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-quant-calib-pipeline · 共 5 个片段</p>\n"},{"id":"ap-moe-serving-frameworks","title":"MoE推理框架选型","summary":"对比 TensorRT-LLM、vLLM、SGLang 在 Blackwell 上对分组 GEMM、专家并行、分离式预填解码的支持成熟度，说明各自插件接口、CUDA Graph 兼容性与自定义路由 kernel 的接入成本，避免泛泛而谈。","kind":"工具","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-1\">一 · 条目边界：什么算“MoE 推理框架选型”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-2\">二 · 分类维度一：分组 GEMM 后端与 tcgen05 路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-3\">三 · 分类维度二：专家并行通信原语与部署形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-4\">四 · 分类维度三：CUDA Graph 捕获粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-5\">五 · 分类维度四：自定义路由 kernel 接入成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-6\">六 · 选型矩阵的读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-7\">七 · 选型边界：五维分类与三类失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-8\">八 · 速查表的字段口径：先定义“可判定”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-9\">九 · 速查表主体：三框架八列对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-10\">十 · 阈值列：桶数、回退判定与同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-11\">十一 · 接入成本的口径：插件与编译期注册</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-12\">十二 · NVFP4/FP8 路径成熟度的判定口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-13\">十三 · 表的用法：三态判定与失败模式前置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-14\">十四 · 速查表之外的边界：何时这张表会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-15\">十五 · 阈值从哪里来：先测形状分布，再定桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-16\">十六 · 专家计数的倾斜阈值：什么时候该动容量因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-17\">十七 · 后端回退的检测阈值：算力利用率与告警缺口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-18\">十八 · 插件接入的宿主同步阈值：图内同步点计数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-19\">十九 · 分离式预填解码下的图策略阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-20\">二十 · 把阈值写成可复跑的测量清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-21\">二十一 · 失效边界：图捕获、路由插件与后端回退的三条暗线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-22\">二十二 · 坑一：整图 CUDA Graph 撞上分离式预填解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-23\">二十三 · 坑二：插件路由 kernel 在图内引入宿主同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-24\">二十四 · 坑三：All-to-All 原语与分组 GEMM 后端版本错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-25\">二十五 · 检查顺序：从合法性到形状再到性能</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-26\">二十六 · 回滚方案：按层回退而非整体回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-27\">二十七 · 失效边界：图捕获、路由插件与后端回退的三处断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-28\">二十八 · 上游依赖：分组 GEMM 后端与通信原语的版本耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-29\">二十九 · 下游影响：CUDA Graph 捕获粒度反向约束路由与调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-30\">三十 · 横向耦合：分离式预填解码把选型拆成两个子决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-31\">三十一 · 与量化条目的接口：NVFP4/FP8 路径成熟度决定回退风险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-32\">三十二 · 在全书中的位置：从单点机制到部署形态的收束点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-serving-frameworks-sec-33\">三十三 · 边界条件：上游依赖与下游失效的耦合点</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-moe-serving-frameworks\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 303\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"66.9\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"45.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"49.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：MoE推理框架选型</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">对比 TensorRT-LLM、vLLM、SGLang 在 Blackwell…</text><line x1=\"82.0\" y1=\"80.9\" x2=\"82.0\" y2=\"97.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 96.9 L 86.5 96.9 L 82.0 104.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"104.9\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"127.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"131.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"132.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"151.8\" x2=\"82.0\" y2=\"168.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 167.8 L 86.5 167.8 L 82.0 175.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"175.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"198.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"202.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"203.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"222.6\" x2=\"82.0\" y2=\"239.6\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 238.6 L 86.5 238.6 L 82.0 246.6 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"246.6\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"269.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"273.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"274.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-moe-serving-frameworks-sec-1\">一 · 条目边界：什么算“MoE 推理框架选型”</h3>\n<p>本条目讨论的对象不是“哪个框架更快”，而是一个可判定的工程决策：给定 Blackwell 上的 MoE 模型、给定的 SLO 与部署形态，判断 TensorRT-LLM、vLLM、SGLang 三者中哪一个能以最低接入成本满足分组 GEMM、专家并行通信、分离式预填解码这三条能力线，并且不破坏 CUDA Graph 的稳定性。选型的输出应当是一张可核对的矩阵，而不是一句偏好。因此本条目把“选型”定义为对七个正交属性的取值判定：分组 GEMM 支持状态、专家并行拓扑、分离式预填解码支持、插件接口类型、CUDA Graph 兼容性、自定义路由 kernel 接入成本、NVFP4/FP8 路径成熟度。任何一个属性缺失，都会在某个具体负载上变成吞吐或尾延迟的硬约束。</p>\n<p>与相邻概念的分界必须说清。路由术语（top-k、容量因子、token 丢弃）属于算法层语义，本条目只把它们当作“框架必须正确表达的输入形状”；专家并行与 All-to-All 属于通信机制，本条目只关心框架暴露该机制的方式（原生原语还是插件）；分组 GEMM 与 tcgen05 属于算子实现，本条目只关心框架能否走到 tcgen05 路径以及回退路径是否可见。换句话说，本条目评的是“框架把底层能力交付给用户的接口形状与成熟度”，不是底层能力本身。</p>\n<p>一个具体例子可以固定这个边界：某团队在 GB200 NVL72 上部署细粒度 MoE，解码侧 batch 随连续批处理波动。他们需要的判定是——所选框架能否在不重捕获整图的前提下容纳动态路由形状，以及自定义路由 kernel 是以插件还是编译期注册接入。这属于选型；而“容量因子取多少”不属于本条目，属于容量因子条目。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-2\">二 · 分类维度一：分组 GEMM 后端与 tcgen05 路径</h3>\n<p>第一个维度是分组 GEMM 后端。MoE 层的本质是“按专家分组、每组不同 M”的批量矩阵乘，框架必须把路由结果转成分组 GEMM 的 problem 描述。在 Blackwell 上这条路径分两支：走 tcgen05（TMEM、2-SM MMA）的专用路径，以及回退到通用 GEMM 的路径。选型时要问的不是“支持不支持分组 GEMM”，而是“能否稳定走到 tcgen05 路径，回退时是否有可观测信号”。</p>\n<p>机制上，tcgen05 路径要求分组 GEMM 的 tile 形状、累加器布局与 TMEM 分配匹配，框架的 kernel 选择器需要按专家分组大小做启发式分派。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{dispatch}(g)=\\begin{cases}\\text{tcgen05\\_grouped\\_gemm}, &amp; \\text{tile\\_m}(g)\\ge T_{\\text{tc}}\\ \\land\\ \\text{align}(g)\\ \\text{ok}\\\\ \\text{fallback\\_gemm}, &amp; \\text{otherwise}\\end{cases}$$</div>\n<p>代价体现在算力利用率上：一旦回退，MoE 层从 tensor-core 密集路径掉到通用路径，SM 利用率与每 token 的算力开销同时恶化，而监控面板往往没有告警——这正是给定失败模式之一“专家并行 All-to-All 与分组 GEMM 后端版本不匹配，tcgen05 路径回退到通用 GEMM，MoE 层算力利用率大幅下降而监控无告警”。选型时因此要把“回退可见性”列为独立属性：框架是否暴露 kernel 选择日志、是否有 per-layer 的路径标记。</p>\n<p>具体例子：同一 MoE 模型，在 A 框架上分组 GEMM 走 tcgen05，在 B 框架上因版本不匹配静默回退；两者端到端吞吐差距来自 MoE 层而非注意力层，但 B 框架的默认指标只报整体 tokens/s，无法定位。选型的判断是：优先选择能把分组 GEMM 路径状态暴露到指标面的框架，其次才比较峰值。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-3\">三 · 分类维度二：专家并行通信原语与部署形态</h3>\n<p>第二个维度是专家并行通信原语的暴露方式：All-to-All 还是 AllGather。二者不是性能优劣问题，而是拓扑适配问题。All-to-All 在专家分散于多卡时把 token 直接发往持有目标专家的 rank，通信量与路由倾斜强相关；AllGather 则把激活汇聚后再本地计算，通信量随隐藏维与 batch 线性增长。框架若只提供其中一种，选型就被拓扑锁死。</p>\n<p>第三个维度是预填解码是否分离部署。分离式预填/解码在 MoE 上的意义是：预填侧是 compute-bound 的大 batch 分组 GEMM，解码侧是 memory-bound 的小 batch 且路由形状逐 step 变化。框架对分离部署的支持成熟度，直接决定解码侧能否独立配置 CUDA Graph 策略。选型矩阵里这一列必须是三态：原生支持、需插件拼装、不支持。</p>\n<p>代价可以用一个通信-计算比来定性刻画：</p>\n<div class=\"formula\">$$\\rho=\\frac{V_{\\text{comm}}\\cdot B_{\\text{link}}^{-1}}{F_{\\text{gemm}}\\cdot P_{\\text{sm}}^{-1}}$$</div>\n<p>ρ 越大，All-to-All 越容易成为 MoE 层的瓶颈；当 ρ 接近 1 时，框架能否把通信与分组 GEMM 重叠（而非串行）就成为吞吐分水岭。NVLink 5 与 NCCL 提供带宽底座，但重叠调度是框架责任。具体例子：GB200 NVL72 单域内专家并行度较高时，All-to-All 走域内 NVLink，框架若把 All-to-All 放在分组 GEMM 之后串行执行，解码 step 的延迟被通信段直接拉长；若框架支持通信-计算流水，则同一拓扑下 step 时间由较长的那个阶段决定。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-4\">四 · 分类维度三：CUDA Graph 捕获粒度</h3>\n<p>第四个维度是 CUDA Graph 捕获粒度，取值为整图、分段、不捕获。这是 MoE 选型中最容易被低估的一列，因为 MoE 的路由形状随 batch 与 token 分布变化，整图捕获要求形状固定。工程经验是：当 CUDA Graph 与动态路由形状冲突时，需按 batch 形状分桶捕获，桶数过多会显著增加捕获与显存开销，通常控制在个位数到十余桶。</p>\n<p>机制上，分段捕获把 MoE 层单独成图、注意力与通信段各自成图，从而让形状多变的 MoE 段按桶切换，而形状稳定的段复用同一张图。伪代码思路：</p>\n<div class=\"formula\">$$\\text{graph\\_key}=(\\text{bucket}(B),\\ \\text{topk},\\ \\text{ep\\_degree}),\\quad \\text{replay}[\\text{graph\\_key}]$$</div>\n<p>代价有两面：捕获本身消耗显存（每张图持有自己的中间缓冲与参数视图），桶数上升使显存线性增长；重捕获发生在运行时，直接表现为解码延迟抖动。给定失败模式“在支持分离式预填解码的框架中启用整图 CUDA Graph，解码侧 batch 形状随调度变化导致图重捕获频繁，吞吐反而低于分段捕获配置”正是这一维度的典型判据。选型时应把“解码侧默认捕获策略”作为必查项，而不是部署后再调。</p>\n<p>具体例子：分离部署下预填侧 batch 大且稳定，整图捕获收益明显；解码侧 batch 由连续批处理决定，逐 step 变化，整图捕获触发频繁重捕获，端到端吞吐低于分段捕获。结论是同一框架内两侧应采用不同捕获粒度，选型要确认框架允许这种非对称配置。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-5\">五 · 分类维度四：自定义路由 kernel 接入成本</h3>\n<p>第五个维度是自定义路由 kernel 的接入方式：插件接口还是编译期注册。这一列决定团队能否把自研路由算法（带容量因子、带丢弃策略、带倾斜修正）落到生产路径上，而不只是跑在参考实现里。接入成本不只是“能不能编译进去”，还包括是否适配框架的 CUDA Graph 捕获流程、是否引入图内宿主同步。</p>\n<p>机制上，插件式接入在运行时被框架调用，若插件内部做了 device-to-host 的同步（例如为动态形状读取计数），该同步会被捕获进图，破坏图的可重放性。给定失败模式“自定义路由 kernel 以插件形式接入但未适配框架的 CUDA Graph 捕获流程，图内出现宿主同步，解码延迟抖动明显”即为此。编译期注册则把路由 kernel 编进框架的图构建流程，形状信息在捕获期已知，代价是每次改动需重新构建、与框架版本强耦合。</p>\n<p>代价判断可以写成一个接入成本函数：</p>\n<div class=\"formula\">$$C_{\\text{int}}=c_{\\text{build}}+c_{\\text{graph}}+c_{\\text{ver}},\\quad c_{\\text{graph}}\\ \\text{在插件路径上随同步点数量上升}$$</div>\n<p>具体例子：团队自研带倾斜修正的路由 kernel，若以插件接入且内部含宿主同步，解码侧每 step 出现同步等待，尾延迟抖动明显；若改为编译期注册并把形状查询移到捕获期，抖动消失但升级框架时需重新验证。选型的判断是：路由算法迭代频繁选插件并强制“无宿主同步”约束，算法稳定后迁到编译期注册。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-6\">六 · 选型矩阵的读法</h3>\n<p>把上述维度合成一张表，才是本条目要求的可核对输出。速查表应含列：框架名、分组 GEMM 支持状态、专家并行拓扑、分离式预填解码支持、插件接口类型、CUDA Graph 兼容性、自定义路由 kernel 接入成本、NVFP4/FP8 路径成熟度。读表时不要逐列打分求和，而要按负载找“硬约束列”：若部署形态是分离式预填解码，则分离支持与解码侧捕获粒度是硬约束；若专家并行度高，则通信原语与分组 GEMM 路径匹配是硬约束。</p>\n<table class=\"mini\"><thead><tr><th>判定项</th><th>硬约束场景</th><th>失败信号</th></tr></thead><tbody><tr><td>分组 GEMM 后端</td><td>高 EP 度、专家分组小</td><td>tcgen05 静默回退，MoE 层利用率下降无告警</td></tr><tr><td>专家并行原语</td><td>跨 rank 专家分散</td><td>All-to-All 与 GEMM 串行，ρ 接近 1</td></tr><tr><td>分离式预填解码</td><td>预填解码负载差异大</td><td>解码侧整图捕获，重捕获频繁</td></tr><tr><td>CUDA Graph 粒度</td><td>路由形状随 batch 变化</td><td>桶数膨胀，捕获与显存开销上升</td></tr><tr><td>自定义路由接入</td><td>自研路由算法</td><td>插件内含宿主同步，图内抖动</td></tr></tbody></table>\n<p>这张表的用法是排除而非排序：任一硬约束列不满足，该框架在该负载上即出局，无论其峰值吞吐多高。NVFP4/FP8 路径成熟度作为独立列，是因为量化路径与分组 GEMM 后端、路由漂移相互耦合，选型时必须确认框架的量化路径与所选 GEMM 后端在同一版本上闭合，否则会出现“量化能跑但走不到 tcgen05”的隐性降级。</p>\n<p>最后落在一个工程判断上：MoE 推理框架选型的本质是把“框架接口形状”与“负载形状变化率”对齐——负载形状变化越快（解码侧路由逐 step 变），越需要分段捕获与编译期注册的稳定路径；变化越慢（预填侧大 batch），越能承受整图捕获与插件式接入。选型矩阵的每一列，都是在问同一个问题：这条路径在形状变化时会不会静默降级。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-7\">七 · 选型边界：五维分类与三类失效条件</h3>\n<p>把“支持 MoE”当作布尔量是选型中最常见的错误。本卷采用的分类维度是五个正交轴：分组 GEMM 后端（tcgen05 原生路径 vs. 回退到通用 GEMM）、专家并行通信原语（All-to-All 还是 AllGather）、预填与解码是否分离部署、CUDA Graph 捕获粒度（整图/分段/不捕获）、自定义路由 kernel 的接入方式（运行时插件 vs. 编译期注册）。这五轴决定了一个框架在给定拓扑下的实际可用区间，而不是它的宣传口径。任一轴上的降级都会以不同方式吃掉收益：后端回退损失算力利用率，通信原语错配损失带宽，捕获粒度错配损失调度弹性。选型表必须按这五列逐格填写，缺一列就失去判别力。</p>\n<p>失效条件一：专家并行 All-to-All 与分组 GEMM 后端版本不匹配时，tcgen05 路径静默回退到通用 GEMM。此时 MoE 层的算力利用率大幅下降，而监控面板没有任何告警——因为 kernel 仍正常返回，只是走了慢路径。判别式可写成后端有效利用率：</p>\n<div class=\"formula\">$$\\eta_{\\text{MoE}}=\\frac{T_{\\text{tcgen05}}}{T_{\\text{tcgen05}}+T_{\\text{fallback}}}\\cdot\\frac{B_{\\text{eff}}}{B_{\\text{peak}}}$$</div>\n<p>其中回退时间占比不体现在任何框架级指标里，必须靠逐 kernel 的 profiler 采样或后端选择日志确认。工程判断是：在启用 All-to-All 前先验证分组 GEMM 后端与通信库版本矩阵，把“后端是否走 tcgen05”作为上线前的硬性检查项，而不是事后调优项。</p>\n<p>失效条件二：自定义路由 kernel 以插件形式接入，但未适配框架的 CUDA Graph 捕获流程，图内出现宿主同步。后果是解码延迟抖动明显——单步 P99 被宿主侧同步点拉长，而平均延迟看起来尚可，掩盖了问题。失效条件三：在支持分离式预填解码的框架里启用整图 CUDA Graph，解码侧 batch 形状随连续批处理调度持续变化，触发频繁重捕获，吞吐反而低于分段捕获配置。这与“图捕获总是更快”的直觉相反，根因是捕获开销与显存占用随桶数增长。工程阈值上，按 batch 形状分桶捕获时桶数应控制在个位数到十余桶；超出后捕获时间与图内存开销会侵蚀收益。因此分类维度中的“捕获粒度”不是风格选项，而是与调度器形状分布绑定的容量决策。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th><th>可观测信号</th></tr></thead><tbody><tr><td>后端静默回退</td><td>All-to-All 与分组 GEMM 版本不匹配</td><td>MoE 算力利用率下降，无告警</td><td>逐 kernel 后端选择日志</td></tr><tr><td>图内宿主同步</td><td>路由插件未适配捕获流程</td><td>解码延迟抖动，P99 抬升</td><td>捕获期同步点计数</td></tr><tr><td>重捕获风暴</td><td>分离式部署 + 整图捕获 + 动态 batch</td><td>吞吐低于分段捕获，显存被图占用</td><td>单位时间重捕获次数</td></tr></tbody></table>\n<h3 id=\"ap-moe-serving-frameworks-sec-8\">八 · 速查表的字段口径：先定义“可判定”</h3>\n<p>这张表不是功能清单，而是选型判定器。每一列都必须能用“是/否/条件成立”回答，否则它就不该进表。字段口径固定为八列：框架名、分组 GEMM 支持状态、专家并行拓扑、分离式预填解码支持、插件接口类型、CUDA Graph 兼容性、自定义路由 kernel 接入成本、NVFP4/FP8 路径成熟度。其中“支持状态”一列不接受“支持”这种二元答案，必须写成三态：原生 tcgen05 路径、可配置但存在回退、仅通用 GEMM。回退态是 MoE 推理最危险的中间地带——它跑得通，所以监控不告警，但 MoE 层算力利用率已经掉档。判定方法很直接：抓一次 MoE 层的 kernel 名与 MMA 指令形态，若出现通用 GEMM 而非 tcgen05 路径，即记为回退。</p>\n<p>“专家并行拓扑”一列记录的是通信原语而非并行度数字：All-to-All 还是 AllGather，是否支持分层/节点内优先。这一列与分组 GEMM 后端存在版本耦合——All-to-All 的切分粒度必须与分组 GEMM 的 group 划分对齐，否则 token 排布在进入 GEMM 前要多一次重排，代价落在解码侧就是每层固定的额外延迟。“分离式预填解码支持”只填三态：原生支持、需自建、不支持。原生支持指框架自带 P/D 角色拆分与 KV 传输接口；需自建指框架只提供请求级路由，KV 搬运要自己接。</p>\n<div class=\"formula\">$$\\text{选型可行} = \\big[\\text{GEMM}_{\\text{tcgen05}} \\wedge \\text{EP}_{\\text{对齐}} \\wedge \\text{Graph}_{\\text{分桶}}\\big] \\Rightarrow \\text{进入压测}$$</div>\n<p>这条判据的含义是：三态里任一为假，就不必进入容量压测阶段，直接换配置或换框架。工程代价上，一次错误的回退判定会让整轮压测白跑——MoE 层的算力利用率下降在端到端吞吐上被注意力层与通信掩盖，只有分列剖析才能看见。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-9\">九 · 速查表主体：三框架八列对照</h3>\n<table class=\"mini\">\n<thead>\n<tr><th>字段</th><th>TensorRT-LLM</th><th>vLLM</th><th>SGLang</th></tr>\n</thead>\n<tbody>\n<tr><td>分组 GEMM 支持状态</td><td>原生 tcgen05 路径，编译期确定</td><td>可配置，存在回退到通用 GEMM 的路径</td><td>可配置，回退判定依赖后端选择</td></tr>\n<tr><td>专家并行拓扑</td><td>All-to-All 为主，拓扑在引擎构建期固化</td><td>All-to-All / AllGather 可选，运行期可切</td><td>All-to-All 为主，与分组 GEMM group 划分耦合紧</td></tr>\n<tr><td>分离式预填解码支持</td><td>原生支持，P/D 角色与 KV 传输接口内建</td><td>需自建，框架提供请求级路由与 KV 连接器</td><td>原生支持，角色拆分与调度器同源</td></tr>\n<tr><td>插件接口类型</td><td>编译期注册为主，算子需随引擎重建</td><td>运行期插件，Python/C++ 双入口</td><td>运行期插件，与调度器共享形状元数据</td></tr>\n<tr><td>CUDA Graph 兼容性</td><td>整图捕获友好，形状在构建期静态</td><td>分段捕获为主，整图需按桶静态化</td><td>分段捕获为主，整图与动态调度冲突明显</td></tr>\n<tr><td>自定义路由 kernel 接入成本</td><td>高：需适配编译期注册与图捕获流程</td><td>中：插件入口清晰，但需自行处理图内宿主同步</td><td>中低：路由与调度元数据同源，形状声明成本低</td></tr>\n<tr><td>NVFP4/FP8 路径成熟度</td><td>高：量化路径与 GEMM 后端同批固化</td><td>中：路径可用，回退组合需逐配置验证</td><td>中：路径可用，与分组 GEMM 后端绑定验证</td></tr>\n</tbody>\n</table>\n<p>读表方式：先看第一列与第五列的乘积。TensorRT-LLM 的强项是“编译期固化”——分组 GEMM、拓扑、量化路径在引擎构建时一次性锁定，换来整图 CUDA Graph 的稳定捕获；代价是任何路由 kernel 变更都要重建引擎，接入成本记为高。vLLM 的强项是运行期灵活性，插件入口清晰，但整图捕获需要把动态形状静态化成桶，接入成本落在“图内宿主同步”这一项上。SGLang 的强项是路由与调度元数据同源，形状声明便宜，代价是整图捕获与动态调度天然冲突。</p>\n<p>一个具体例子：同一套 MoE 模型、同一批请求，在 TensorRT-LLM 上以整图捕获运行，解码侧图重捕获次数为零；迁到以分段捕获为主的配置后，若仍按整图思路配置，解码侧 batch 形状随调度变化，图重捕获频繁，吞吐反而低于分段捕获配置。这不是框架缺陷，而是捕获粒度与调度动态性的口径错配。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-10\">十 · 阈值列：桶数、回退判定与同步点</h3>\n<p>材料未给出具体数字，因此阈值列只写口径与判定动作，不写凭空数字。第一条阈值是 CUDA Graph 分桶数：当动态路由形状与图捕获冲突时，按 batch 形状分桶捕获，桶数控制在个位数到十余桶。超过这个量级，捕获开销与每桶独立显存的累积会吃掉分桶带来的收益——桶数是显存与捕获时间的双重代价，不是越多越稳。判定动作：统计解码侧实际命中的桶数与未命中率，未命中率高说明桶划分与调度分布不匹配，应先改桶边界而非加桶。</p>\n<div class=\"formula\">$$\\text{桶代价} \\approx N_{\\text{bucket}} \\times \\big(C_{\\text{capture}} + M_{\\text{graph}}\\big), \\quad N_{\\text{bucket}} \\in [\\text{个位数}, \\text{十余}]$$</div>\n<p>第二条阈值是回退判定：分组 GEMM 后端版本与专家并行 All-to-All 原语必须同批验证。判定动作是抓 MoE 层 kernel 名，出现通用 GEMM 即判回退，且必须配告警——因为回退态下监控无告警是已知失败模式，MoE 层算力利用率大幅下降而端到端指标只轻微劣化。第三条阈值是宿主同步点：自定义路由 kernel 以插件形式接入后，必须检查图内是否出现宿主同步。判定动作是看解码延迟的抖动幅度，图内宿主同步会表现为规律性尖峰而非均匀分布。</p>\n<p>代价口径要分开记：桶数增加主要吃显存与首次捕获延迟；回退主要吃 MoE 层算力利用率；宿主同步主要吃解码侧尾延迟抖动。三者不在同一指标上体现，混在一张端到端吞吐表里会互相掩盖。工程上应把这三项拆成独立监控项，任一越界即触发配置复核。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-11\">十一 · 接入成本的口径：插件与编译期注册</h3>\n<p>“自定义路由 kernel 接入成本”一列不能填“高/中/低”了事，要拆成三个可核对的子项：注册方式（编译期还是运行期）、形状声明责任方（框架还是插件作者）、图捕获适配责任方。TensorRT-LLM 以编译期注册为主，三个子项的责任都偏插件作者一侧：路由 kernel 要随引擎重建，形状必须在构建期静态化，图捕获流程要显式适配。vLLM 运行期插件入口清晰，形状声明可由插件自带，但图捕获适配仍需插件作者处理宿主同步。SGLang 因路由与调度器共享形状元数据，形状声明成本最低。</p>\n<ul>\n<li>注册方式决定迭代节奏：编译期注册意味着每次路由逻辑调整都要重建引擎，压测周期被拉长。</li>\n<li>形状声明责任方决定动态性上限：形状由框架静态化时，动态路由只能靠分桶近似。</li>\n<li>图捕获适配责任方决定尾延迟稳定性：插件未适配捕获流程，图内宿主同步就是必然结果。</li>\n</ul>\n<p>具体例子：一个带动态专家选择的路由 kernel 以运行期插件接入 vLLM，注册与形状声明都顺利，但未处理图捕获流程，结果图内出现宿主同步，解码延迟抖动明显——此时表上“接入成本”应记为“中，但需补图捕获适配”，而不是“中”。这就是为什么这一列必须带子项：单一评级会把已踩的坑藏起来。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-12\">十二 · NVFP4/FP8 路径成熟度的判定口径</h3>\n<p>这一列不评“能不能量化”，而评“量化路径与 GEMM 后端是否同批固化”。判定口径三条：量化路径是否与 tcgen05 分组 GEMM 路径绑定验证；回退到通用 GEMM 时量化是否仍成立；路由漂移是否在量化后被单独监控。TensorRT-LLM 因编译期固化，量化与 GEMM 后端同批锁定，成熟度记为高；vLLM 与 SGLang 路径可用，但回退组合需逐配置验证，成熟度记为中。注意这里不涉及校准数据管线本身——那是另一条目的主题，此处只关心“路径组合是否被验证过”。</p>\n<p>代价口径：量化路径与 GEMM 后端不匹配时，最坏情况不是精度掉，而是回退到通用 GEMM 后 MoE 层算力利用率大幅下降，而量化收益仍在账面上，形成“看起来省了、实际更慢”的错配。判定动作是在压测矩阵里强制加入“量化开 + 回退态”这一组合，观察 MoE 层 kernel 名与端到端吞吐的背离程度。若背离明显，说明该框架在此配置下的量化路径未与分组 GEMM 后端同批验证，成熟度应下调一档。</p>\n<p>另一个具体例子：专家并行 All-to-All 与分组 GEMM 后端版本不匹配时，tcgen05 路径回退到通用 GEMM，MoE 层算力利用率大幅下降而监控无告警。此时若同时开着 NVFP4，账面显存与带宽收益仍在，容易误判为“量化生效、系统健康”。速查表的作用就是在压测前把这一组合标为“需验证”，而不是等端到端指标劣化后再回溯。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-13\">十三 · 表的用法：三态判定与失败模式前置</h3>\n<p>用法固定为三步。第一步，按“分组 GEMM 支持状态”与“专家并行拓扑”两列做交集判定：只有原生 tcgen05 路径且 All-to-All 切分与 group 划分对齐的配置，才进入下一步。第二步，按“CUDA Graph 兼容性”与“自定义路由 kernel 接入成本”做捕获粒度判定：整图捕获只对形状静态化的配置成立，动态调度配置一律按分段捕获并分桶，桶数个位数到十余。第三步，按“分离式预填解码支持”与“NVFP4/FP8 路径成熟度”做部署形态判定：原生支持 P/D 拆分的框架才允许在解码侧启用整图捕获，否则解码侧 batch 形状随调度变化，图重捕获频繁。</p>\n<p>失败模式必须前置到表里，而不是留给压测发现。两条已知失败模式对应两列：插件接入未适配图捕获流程，对应“自定义路由 kernel 接入成本”列必须标注“需补图捕获适配”；All-to-All 与分组 GEMM 后端版本不匹配导致回退，对应“分组 GEMM 支持状态”列必须标注“回退态需告警”。把这两条写进表，选型就从“功能有没有”变成“代价在哪、谁来担”。</p>\n<p>最后落在工程判断上：这张表的价值不在横向比较三家框架的强弱，而在把每个配置的代价归属到具体一列——桶数归属显存与捕获时间，回退归属 MoE 层算力利用率，宿主同步归属解码尾延迟。任何一列填不出可判定口径，就说明该配置还没被验证过，不应进入容量规划。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-14\">十四 · 速查表之外的边界：何时这张表会骗你</h3>\n<p>速查表把七列压成一行结论，但它成立的前提是“静态形状 + 静态拓扑”。一旦 MoE 路由在解码侧按 token 动态分桶，专家并行 All-to-All 的通信量与分组 GEMM 的 M 维同时变成运行时变量，表里“支持”二字就必须打折。判定口径：若单层 MoE 的激活专家数随 batch 波动超过一个数量级，则分组 GEMM 的 tcgen05 路径大概率退化为通用 GEMM 回退路径，此时表里的“支持状态”只代表接口存在，不代表算力利用率。监控上要盯的是 MoE 层实际吞吐与理论峰值之比，而不是 kernel 是否启动成功——后者永远为真。</p>\n<p>CUDA Graph 一列是最容易误读的。整图捕获要求解码 batch 形状稳定，而连续批处理框架的调度器每步都在改形状，二者天然冲突。工程口径是分桶捕获，桶数 N 与捕获开销、显存占用近似线性：</p>\n<div class=\"formula\">$$C_{\\text{graph}} \\approx N \\cdot (T_{\\text{capture}} + M_{\\text{pool}})$$</div>\n<p>桶数控制在个位数到十余桶是经验边界，超过后重捕获频率上升，收益被抵消。典型失效场景：在支持分离式预填解码的框架里开整图捕获，解码侧形状随调度漂移，图重捕获频繁，吞吐反而低于分段捕获配置——这是表里“兼容性=高”最容易误导人的地方。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>判定口径</th><th>失效信号</th></tr></thead><tbody><tr><td>分组 GEMM 后端</td><td>确认走 tcgen05 还是回退</td><td>MoE 层利用率骤降、无告警</td></tr><tr><td>路由 kernel 接入</td><td>插件是否进图捕获流程</td><td>图内宿主同步、解码延迟抖动</td></tr><tr><td>CUDA Graph 粒度</td><td>整图 / 分段 / 不捕获</td><td>桶数膨胀、重捕获频繁</td></tr></tbody></table>\n<p>自定义路由 kernel 的接入成本要按“是否参与图捕获”重估：插件形式接入但未适配捕获流程，图内出现宿主同步，解码延迟抖动明显，这类代价不会出现在功能测试里，只出现在 P99 上。同理，专家并行 All-to-All 与分组 GEMM 后端版本不匹配时，tcgen05 路径静默回退，算力利用率大幅下降而监控无告警——速查表只能告诉你“有这条路”，走不走得通要靠版本对齐与端到端压测来验。</p>\n<h3 id=\"ap-moe-serving-frameworks-sec-15\">十五 · 阈值从哪里来：先测形状分布，再定桶</h3>\n<p>MoE 推理框架的工程阈值不是拍脑袋定的，它由两个可测量的分布决定：解码侧每步的 token 数分布，以及路由后每专家的 token 数分布。前者决定 CUDA Graph 的捕获粒度，后者决定分组 GEMM 的尾块浪费。测量方法很直接：在目标框架上打开调度日志，记录连续 N 个解码步的 batch 形状（实际参与计算的序列数 × 每序列 token 数），把形状按出现频次排序；同时记录每层路由输出的专家计数向量，统计其最大值与均值的比值。这两个分布是后续所有阈值决策的输入，缺一不可。</p>\n<p>形状分布的用途是分桶。当 CUDA Graph 与动态路由形状冲突时，按 batch 形状分桶捕获是唯一可行路径，桶数过多会显著增加捕获与显存开销，工程上通常控制在个位数到十余桶。桶的边界不应等距切分，而应按频次累积覆盖：把排序后的形状按累计占比切段，让前几个桶覆盖绝大多数解码步，尾部形状走非图路径或分段捕获。代价是显式的——每个桶一份图实例，捕获时间随桶数线性增长，显存占用随桶内中间缓冲增长；桶数从个位数涨到十余桶时，捕获开销与显存会进入需要重新评估的区间。</p>\n<div class=\"formula\">$$B_{\\text{bucket}} = \\arg\\min_{k}\\ \\Big( T_{\\text{capture}}(k) + \\lambda \\cdot M_{\\text{graph}}(k) \\Big),\\quad \\text{s.t.}\\ \\sum_{i=1}^{k} p_i \\ge 1-\\epsilon$$</div>\n<p>其中 $p_i$ 是第 $i$ 个形状桶的命中概率，$\\epsilon$ 是允许走非图路径的尾部比例。这个式子的工程含义是：桶数不是越多越好，命中率增益要能抵消捕获与显存代价。具体例子：某解码服务在调度日志中发现单步 token 数集中在少数几个离散值附近，按频次切出少量桶即可覆盖绝大多数步，剩余长尾形状交给分段捕获；若强行给每个观测到的形状建桶，捕获阶段耗时与图实例显存会明显抬升，而命中率提升有限。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-16\">十六 · 专家计数的倾斜阈值：什么时候该动容量因子</h3>\n<p>容量因子与丢弃代价已在别处展开，这里只讲它的触发阈值怎么测。测量对象是每层每专家的 token 计数向量，指标用最大专家负载与平均负载之比，以及前若干专家的累计占比。前者刻画单点热点，后者刻画整体倾斜。工程判断的分界不在绝对数值，而在“热点专家是否已经打满其分组 GEMM 的尾块”——即该专家的 token 数是否跨过 GEMM tile 的整数倍边界，导致多出一个几乎空转的 tile。这个判断需要把路由计数与分组 GEMM 的 tile 尺寸对齐来看，而不是只看比例。</p>\n<p>测量方法：在固定 batch 与固定输入分布下，逐层导出专家计数，按 tile 尺寸向上取整得到每专家的 tile 数，再与实际有效 token 数相除得到 tile 利用率。利用率低于某个经验水位时，说明倾斜已经在浪费算力，此时调容量因子或改路由分桶才有收益；利用率接近满值时，倾斜只是负载不均而非算力浪费，动容量因子反而引入丢弃。代价侧要同时记录：容量因子收紧会带来丢弃率上升，丢弃直接体现为输出质量下降与重算，吞吐上的收益必须与丢弃代价一起看。具体例子：某层路由计数显示单专家占比突出，但按 tile 取整后该专家的 tile 利用率仍高，说明热点尚未造成尾块浪费，此时不应触发容量调整；反之若多个专家的 tile 利用率普遍偏低，则是分组 GEMM 后端或容量因子需要介入的信号。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-17\">十七 · 后端回退的检测阈值：算力利用率与告警缺口</h3>\n<p>失败模式里最隐蔽的一条是专家并行 All-to-All 与分组 GEMM 后端版本不匹配，tcgen05 路径回退到通用 GEMM，MoE 层算力利用率大幅下降而监控无告警。这条的工程阈值必须靠主动测量建立，因为回退本身不报错。测量方法有三层：第一层是编译期检查，确认分组 GEMM 实际链接的是 tcgen05 路径而非回退路径，可在框架的 kernel 选择日志或 profiler 的 kernel 名里核对；第二层是运行期对比，用同一形状分别在两条路径上跑微基准，记录单层 MoE 的耗时比值，比值偏离预期即回退嫌疑；第三层是端到端指标，MoE 层耗时占整步比例突然抬升而其他层不变，是回退的典型指纹。</p>\n<p>阈值设定上，微基准比值是最可靠的判据：当实测单层耗时明显高于同形状的 tcgen05 参考值时，应视为回退并触发告警，而不是等端到端吞吐下滑才发现。代价侧要量化回退的代价：通用 GEMM 路径在 MoE 层上的算力利用率下降是结构性的，表现为该层耗时占比抬升，进而拉长每步解码延迟；在预填阶段则表现为吞吐下降。具体例子：某部署在升级通信原语版本后，All-to-All 的切分方式与分组 GEMM 的 tile 假设不再对齐，kernel 选择静默落到回退路径，profiler 里 MoE 层 kernel 名变化但无报错，端到端只有轻微抖动，直到微基准对比才定位。这类问题的测量习惯应固化为：每次变更通信或 GEMM 后端版本后，跑一次同形状微基准对比并留档。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-18\">十八 · 插件接入的宿主同步阈值：图内同步点计数</h3>\n<p>自定义路由 kernel 以插件形式接入但未适配框架的 CUDA Graph 捕获流程，图内出现宿主同步，解码延迟抖动明显——这条的阈值是可数的：图内宿主同步点的个数。测量方法是抓取捕获后的图执行轨迹，统计图内出现的同步类操作次数，任何非零值都意味着图执行被切成多段、CPU 与 GPU 交替等待，抖动随之而来。工程上把“图内宿主同步点为零”作为插件合格的门槛，而不是容忍少量同步。</p>\n<p>接入成本要按框架的插件接口类型分档测量：编译期注册的路径在捕获前完成形状与内存规划，天然避开图内同步；运行期插件若在 kernel 内做动态形状查询或内存分配，就会引入宿主同步。测量步骤是：先在非图模式下验证插件正确性，再在分段捕获下测抖动幅度，最后尝试整图捕获并统计同步点；若整图捕获下同步点非零，应退回分段捕获而非强行整图。代价侧：图内同步点使解码延迟的方差显著放大，尾延迟抬升，而平均延迟可能看不出问题，因此必须用分位数而非均值来判定。具体例子：某路由插件在 kernel 内读取调度器维护的专家映射表，该读取在整图捕获下变成宿主同步，解码延迟抖动明显；改为编译期注册并把映射表作为图输入后，同步点归零，抖动收敛。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-19\">十九 · 分离式预填解码下的图策略阈值</h3>\n<p>最常见踩坑是在支持分离式预填解码的框架中启用整图 CUDA Graph，解码侧 batch 形状随调度变化导致图重捕获频繁，吞吐反而低于分段捕获配置。这里的阈值是重捕获频次：单位时间内图重捕获的次数超过某个水位，就说明整图策略与调度动态性不匹配。测量方法是在解码侧记录每次图失效与重捕获的时间戳，计算重捕获间隔与单次捕获耗时；当重捕获耗时占解码总时间的比例不可忽略时，整图策略已经在拖累吞吐。</p>\n<p>判断规则可以写成：设单次捕获耗时为 $T_c$，解码步平均耗时为 $T_s$，重捕获间隔为 $n$ 步，则图策略的摊销代价为 $T_c/(n \\cdot T_s)$；当该比值超过分段捕获带来的额外调度开销时，应切换到分段捕获。分段捕获把图切成固定段、段间允许形状变化，代价是段间有调度开销但重捕获极少。具体例子：某分离式部署的解码侧在连续批处理下形状持续变化，整图配置下重捕获频繁，吞吐低于分段配置；切到分段捕获后重捕获基本消失，解码延迟方差收窄。这条经验应固化为选型检查项：凡启用分离式预填解码，先测重捕获频次再决定图粒度。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-20\">二十 · 把阈值写成可复跑的测量清单</h3>\n<p>上述阈值要落地，需要一份可复跑的测量清单，每项都对应一个具体机制与一个代价指标。清单至少包含：解码步形状频次分布（决定桶数与桶边界）、逐层专家计数与 tile 利用率（决定容量因子是否介入）、分组 GEMM 路径的微基准耗时比值（检测 tcgen05 回退）、图内宿主同步点计数（判定插件是否适配图捕获）、解码侧重捕获频次与摊销代价（决定整图还是分段）。每项测量的输入应固定：固定模型、固定量化路径、固定输入长度分布，否则阈值不可比。</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>机制</th><th>代价指标</th><th>触发动作</th></tr></thead><tbody><tr><td>形状频次分布</td><td>按频次累积切桶</td><td>捕获耗时、图实例显存</td><td>桶数控制在个位数到十余桶</td></tr><tr><td>专家 tile 利用率</td><td>计数按 tile 取整</td><td>尾块浪费、丢弃率</td><td>调容量因子或改分桶</td></tr><tr><td>GEMM 路径耗时比值</td><td>同形状双路径微基准</td><td>MoE 层耗时占比</td><td>回退告警与版本对齐</td></tr><tr><td>图内同步点计数</td><td>捕获后轨迹统计</td><td>解码延迟方差、尾延迟</td><td>改编译期注册或退分段</td></tr><tr><td>重捕获频次</td><td>图失效时间戳</td><td>捕获摊销、吞吐</td><td>整图切分段</td></tr></tbody></table>\n<p>清单的执行节奏应与变更绑定：每次升级通信原语、分组 GEMM 后端或路由插件后，重跑对应项并留档对比，而不是等端到端指标恶化再回溯。测量本身有代价——微基准占用算力、profiler 改变时序——因此应在独立实例或低峰窗口执行，避免污染在线指标。最后落在工程判断上：阈值不是一次性配置，而是随形状分布与版本组合漂移的量；把测量清单固化为发布门禁，比记住任何单个经验数字都更可靠。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-21\">二十一 · 失效边界：图捕获、路由插件与后端回退的三条暗线</h3>\n<p>本方案的边界不在功能有无，而在三条耦合链上。第一条是 CUDA Graph 与动态路由形状的冲突：MoE 解码侧每个 token 命中的专家集合随调度变化，整图捕获会把 batch 形状钉死，形状一变即触发重捕获。工程上按 batch 形状分桶捕获，桶数控制在个位数到十余桶；桶数继续增长时，捕获耗时与图私有显存（每桶独立的中间缓冲与参数副本）线性上升，收益被抵消。代价可用下式判断是否值得加桶：<div class=\"formula\">$$T_{\\text{step}} \\approx \\frac{C_{\\text{capture}}(N_b)}{N_{\\text{replay}}} + T_{\\text{kernel}}(B) + T_{\\text{sync}}$$</div>其中 $N_b$ 为桶数、$N_{\\text{replay}}$ 为单桶被复用次数。若某桶复用次数低于捕获开销摊薄阈值，该桶应退化为分段捕获或 eager 执行。</p>\n<p>第二条是自定义路由 kernel 以插件形式接入却未适配框架的捕获流程：图内出现宿主同步（如路由结果回传 CPU 做索引），解码延迟抖动明显，P99 被单次同步拉高。测量方法固定为三步：先用 Nsight Systems 抓一次解码 step 的图内 API 序列，确认是否存在 cudaStreamSynchronize 或隐式同步；再用固定 prompt 集做 1→N 并发扫描，记录 P50/P99 与图重捕获计数；最后对比整图与分段两种配置的 token/s，若整图低于分段，即为典型踩坑信号。表列判据：</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>根因</th><th>处置</th></tr></thead><tbody><tr><td>P99 抖动、图重捕获频繁</td><td>整图捕获 + 解码 batch 随调度变化</td><td>改分段捕获，按桶捕获</td></tr><tr><td>图内出现宿主同步</td><td>路由插件未走图安全路径</td><td>路由结果留在设备侧，索引预分配</td></tr><tr><td>MoE 层算力利用率骤降、监控无告警</td><td>tcgen05 路径回退通用 GEMM</td><td>版本对齐校验 + 回退计数器告警</td></tr></tbody></table>\n<p>第三条是专家并行 All-to-All 与分组 GEMM 后端版本不匹配：通信原语与 tcgen05 路径的版本组合失配时，MoE 层静默回退到通用 GEMM，算力利用率大幅下降而监控无告警——因为回退不抛错，只体现在 kernel 名与 SM 占用上。因此选型验收必须把“回退检测”作为独立项：在 profiler 中核对 MoE 层实际执行的 kernel 名是否落在 tcgen05 路径，并把回退次数做成计数器接入告警。对分离式预填解码部署，还需单独测解码侧：预填节点与解码节点的 batch 形状分布不同，图捕获策略必须分开配置，否则预填侧的长序列桶会挤占解码侧的显存预算。</p>\n<h3 id=\"ap-moe-serving-frameworks-sec-22\">二十二 · 坑一：整图 CUDA Graph 撞上分离式预填解码</h3>\n<p>这是本卷反复强调、但工程现场仍然最高频的失败模式：在支持分离式预填解码（PD 分离）的框架里，把解码侧配置成整图 CUDA Graph 捕获。机制上并不复杂——解码实例的 batch 形状由上游调度器决定，连续批处理下每个 step 的 token 数、序列长度分布都在变，而整图捕获要求形状固定。于是框架只能在形状变化时重捕获，重捕获本身要跑一遍完整的 warmup 前向、写图、校验，这段窗口里请求排队、解码 step 被拉长。更糟的是图池随形状膨胀，显存被图占住，KV cache 可用块数下降，调度器被迫更早触发抢占或重算。</p>\n<p>正确的做法是按 batch 形状分桶捕获，桶边界对齐调度器的 max_num_seqs 与 token 预算，而不是对齐真实流量。桶数控制在个位数到十余桶是工程上可接受的区间：桶太少则命中率低、频繁走 eager 回退；桶太多则捕获时间与图显存线性上升，且低命中桶长期闲置。判断是否踩坑的检查项很直接——看解码实例的图重捕获计数是否随 QPS 上升而上升，若是，说明桶设计没有覆盖真实形状分布。</p>\n<div class=\"formula\">$$T_{\\text{step}} = \\underbrace{T_{\\text{eager}}}_{\\text{未命中桶}} \\cdot p_{\\text{miss}} + \\underbrace{T_{\\text{graph}}}_{\\text{命中桶}} \\cdot (1-p_{\\text{miss}}) + \\underbrace{T_{\\text{recap}} \\cdot \\lambda_{\\text{recap}}}_{\\text{重捕获摊销}}$$</div>\n<p>其中 λ_recap 是单位时间重捕获次数。当 p_miss 与 λ_recap 同时偏高时，整图配置的 T_step 会超过分段捕获配置，这就是“配了更激进的技术反而更慢”的来源。代价落在尾延迟上：重捕获期间解码 step 拉长，P99 ITL 出现尖刺，而平均吞吐可能看起来还行，监控容易漏掉。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-23\">二十三 · 坑二：插件路由 kernel 在图内引入宿主同步</h3>\n<p>自定义路由 kernel 以插件形式接入时，最常见的隐性代价不是 kernel 本身慢，而是它破坏了 CUDA Graph 的捕获合法性。路由逻辑里若出现任何需要 CPU 参与的分支——按 top-k 结果决定 dispatch 形状、读取设备端计数做 host 侧判断、调用框架未注册为图安全的同步原语——捕获阶段就会失败或被迫在图内插入同步点。图内同步意味着每个解码 step 都要等 CPU 与 GPU 对齐，解码延迟抖动明显，且这种抖动不体现在 kernel 耗时统计里。</p>\n<p>检查顺序应当是：先确认插件是否走框架提供的图安全注册路径（编译期注册优于运行时插件回调），再确认路由 kernel 的输出形状是否在捕获前就已确定（例如按容量因子向上取整到固定桶），最后用一次捕获后的图 replay 做数值比对，确认路由结果与 eager 路径一致。接入成本在这里体现为两处：一是把动态形状改成静态桶带来的容量浪费，二是为图安全而放弃的 host 侧快速路径。</p>\n<ul>\n<li>机制检查：路由 kernel 内是否存在 cudaStreamSynchronize / cudaMemcpy 到 host / 条件分支依赖设备值。</li>\n<li>形状检查：top-k 后的 token 分发是否在捕获前固定，还是运行时由计数决定。</li>\n<li>代价检查：为图安全引入的固定桶造成的专家容量浪费，是否吃掉了路由优化带来的收益。</li>\n</ul>\n<p>具体例子：某插件把“按专家负载动态调整每专家 token 上限”写在路由 kernel 里，上限值需要回读到 host 再传给分组 GEMM 的 grid 配置。整条链路在 eager 下正常，一进图捕获就退化为分段捕获，解码侧每 step 多出一次同步，ITL 抖动肉眼可见，而 GPU 利用率曲线看不出异常。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-24\">二十四 · 坑三：All-to-All 原语与分组 GEMM 后端版本错配</h3>\n<p>这一类失败最隐蔽：功能正确、结果正确、监控全绿，只是慢。机制是专家并行的通信原语与分组 GEMM 后端在版本上不匹配，导致 tcgen05 路径静默回退到通用 GEMM。回退通常发生在框架按“通信原语版本 + GEMM 后端版本”做能力探测时，探测失败不报错而是走 fallback 分支，MoE 层的算力利用率大幅下降，但因为延迟仍在 SLO 内、错误率为零，告警不会触发。</p>\n<p>检查顺序应把“后端是否真的走了 tcgen05”放在功能验证之前：用框架的 kernel 选择日志或 profiler 的 kernel 名确认分组 GEMM 实际调用的实现，而不是相信配置项。再核对 All-to-All 的通信库版本与 GEMM 后端是否在同一兼容矩阵内——这两者往往由不同依赖引入，升级其一会打破组合。代价体现在算力利用率与功耗上：同样的 token 吞吐需要更多 SM 周期，机架功率预算被无声吃掉。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失败表现</th><th>代价落点</th><th>确认手段</th></tr></thead><tbody><tr><td>GEMM 后端实际路径</td><td>tcgen05 回退通用 GEMM</td><td>算力利用率、功耗</td><td>kernel 名与 profiler 比对</td></tr><tr><td>通信原语版本匹配</td><td>All-to-All 与 GEMM 组合不兼容</td><td>吞吐、尾延迟</td><td>依赖兼容矩阵核对</td></tr><tr><td>图捕获合法性</td><td>图内宿主同步</td><td>ITL 抖动</td><td>捕获日志与 replay 比对</td></tr><tr><td>形状桶覆盖</td><td>重捕获频繁</td><td>吞吐、图显存</td><td>重捕获计数随 QPS 变化</td></tr></tbody></table>\n<p>具体例子：升级通信库以获取新的 All-to-All 实现后，分组 GEMM 的能力探测因版本字符串不匹配而走回退路径，MoE 层每层多出可观的通用 GEMM 时间，端到端吞吐下降但 P99 仍在 SLO 内，容量规划据此认为“还有余量”，实际是把功耗换成了虚假的延迟余量。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-25\">二十五 · 检查顺序：从合法性到形状再到性能</h3>\n<p>踩坑清单需要一个固定顺序，否则容易在性能数字上打转而漏掉合法性前提。建议的顺序是：图合法性 → 形状桶覆盖 → 后端实际路径 → 通信原语匹配 → 数值一致性 → 性能与 SLO。前两项决定“能不能稳定跑”，中间两项决定“跑的是不是想要的实现”，后两项才是调优。把性能检查放在最后，是因为回退路径与图内同步都会污染性能数字，先测性能只会得到无法归因的曲线。</p>\n<p>每一步都要有可观测的判据，而不是靠配置项自证。图合法性看捕获是否一次成功、replay 是否与 eager 数值一致；形状桶看重捕获计数是否随负载平稳；后端路径看 kernel 名；通信匹配看依赖矩阵；数值一致性看路由结果与量化前后的 top-k 是否漂移（量化后路由漂移的判据见对应片段，此处只作为检查项引用）。这套顺序的代价是首次上线多花一轮验证时间，收益是把“静默回退”和“图内同步”这两类不告警的失败挡在容量规划之前。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-26\">二十六 · 回滚方案：按层回退而非整体回退</h3>\n<p>MoE 推理框架的配置是多层叠加的：图捕获粒度、路由 kernel 接入方式、GEMM 后端、通信原语、量化路径。整体回滚到上一版镜像代价大且会丢掉已经验证过的优化。可行的回滚方案是按层设开关，并预先定义每层的回退目标：图捕获从整图回退到分段捕获（保留桶设计），路由 kernel 从插件回退到框架内置路由（放弃自定义优化但恢复图安全），GEMM 后端从 tcgen05 回退到通用路径（确认兼容后再升），通信原语回退到上一兼容版本。</p>\n<p>回滚的触发条件要绑定具体判据而非主观感受：重捕获计数超阈值触发图粒度回退；图内同步检测到即触发路由接入方式回退；kernel 名显示回退路径且算力利用率低于预期触发后端回退。每层回退都要记录它牺牲了什么——分段捕获牺牲部分吞吐换稳定 ITL，内置路由牺牲倾斜处理能力换图安全——这样容量规划才能在下一次上线时正确预估余量。</p>\n<ul>\n<li>图粒度层：整图 → 分段，保留形状桶，代价是每 step 多一次 launch 开销。</li>\n<li>路由接入层：插件 → 编译期注册或内置，代价是放弃动态负载调整。</li>\n<li>后端层：tcgen05 → 通用 GEMM，代价是算力利用率与功耗。</li>\n<li>通信层：新原语 → 上一兼容版本，代价是部分拓扑优化不可用。</li>\n</ul>\n<p>具体机制上，回滚开关应落在配置加载阶段而非运行时代码路径，避免“回滚了但热路径仍走新分支”的假回滚。最后落在一条工程判断上：MoE 推理的失败大多不是崩溃而是静默降级，因此检查清单的价值不在于列出所有坑，而在于把“实际走了哪条路径”变成每次上线都必须回答的问题——图是否一次捕获成功、kernel 名是否指向 tcgen05、重捕获计数是否随 QPS 平稳，这三个判据同时成立，才允许把性能数字写进容量规划。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-27\">二十七 · 失效边界：图捕获、路由插件与后端回退的三处断点</h3>\n<p>这套选型结论的适用边界，集中在三个会静默失效的接缝上。第一处是 CUDA Graph 与动态路由形状的冲突：MoE 解码侧每个 token 的路由目标数随调度批次变化，整图捕获要求形状固定，于是框架只能按 batch 形状分桶重捕获。桶数 <span class=\"formula\">$$N_{bucket}$$</span> 直接决定捕获次数与图私有显存占用，经验上需压到个位数到十余桶；一旦调度器把 batch 分布拉散，重捕获频率上升，图带来的启动开销节省被抵消，吞吐反而低于分段捕获配置——这正是“支持分离式预填解码的框架里启用整图 CUDA Graph”最常见的翻车方式。判断依据不是框架文档写了“支持”，而是看解码侧 batch 形状的方差是否落在桶覆盖范围内。</p>\n<p>第二处是自定义路由 kernel 以插件形式接入却未适配框架的捕获流程。插件注册只解决了算子可见性，没解决图内宿主同步：路由 kernel 若在捕获路径里做 device-to-host 的计数回读或动态分配，图内就嵌入同步点，解码延迟出现周期性抖动，P99 与 P50 的差距被拉大。接入成本应按“编译期注册 &lt; 插件注册 &lt; 插件注册且改造捕获流程”三档估算，最后一档要动框架的 graph capture 回调，是真正的工程量所在。检查顺序上，先验证插件在 eager 模式下数值正确，再单独跑一次捕获并检查图内是否有同步算子，最后才放进连续批处理压测。</p>\n<p>第三处最隐蔽：专家并行 All-to-All 与分组 GEMM 后端版本不匹配，tcgen05 路径静默回退到通用 GEMM。此时 MoE 层的算力利用率大幅下降，但监控面板没有任何告警——kernel 名变了、耗时涨了，却没有错误码。回滚方案因此不能只回滚模型权重或并行度，必须同时锁定分组 GEMM 后端与通信原语的版本组合，把“tcgen05 路径是否命中”做成显式断言而非事后排查。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>失效信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>CUDA Graph 捕获粒度</td><td>解码 P99 抖动、重捕获计数上升</td><td>退回分段捕获，限制桶数</td></tr><tr><td>路由插件捕获适配</td><td>图内宿主同步、延迟周期性尖峰</td><td>禁用该插件图捕获，走 eager 路由</td></tr><tr><td>分组 GEMM 后端</td><td>MoE 层耗时上涨且无告警</td><td>锁定后端与 All-to-All 版本组合</td></tr></tbody></table>\n<p>系统代价要按维度记：整图捕获省的是 kernel 启动延迟，付出的是图私有显存与重捕获 CPU 开销；插件化路由省的是框架改动量，付出的是捕获兼容性风险；tcgen05 路径省的是算力，回退后付出的是 MoE 层吞吐。三者不能同时取最优，选型时须明确哪一项是可回滚的、哪一项是不可回滚的——后端回退属于后者，必须在灰度阶段就用断言卡住。</p>\n<h3 id=\"ap-moe-serving-frameworks-sec-28\">二十八 · 上游依赖：分组 GEMM 后端与通信原语的版本耦合</h3>\n<p>MoE 推理框架选型不是独立决策，它把上游两组能力锁死在同一个版本平面上：分组 GEMM 后端（tcgen05 路径与其回退路径）和专家并行通信原语（All-to-All / AllGather）。这两者在框架内部往往由不同团队维护、走不同发布节奏，选型时必须把它们当作一个联合约束而不是两个独立选项。典型失败模式是：框架侧的专家并行 All-to-All 实现按某一版通信原语编译，而分组 GEMM 后端因版本不匹配退回通用 GEMM 路径，MoE 层算力利用率大幅下降，而监控面板上没有任何告警——因为回退是编译期或初始化期的静默行为，运行时指标只反映“变慢了”，不反映“为什么慢”。工程上的对策是把后端选择做成可观测的：在初始化时打印实际命中的 GEMM 路径标识，并把该标识作为推理服务的启动自检项，版本不匹配直接拒绝启动，而不是带着回退路径上线。</p>\n<p>这条依赖链还决定了插件接口的形态。分组 GEMM 若走 tcgen05 路径，其调用契约对张量布局、对齐和累加器驻留位置（TMEM）有硬性要求；框架的插件接口若只暴露“通用 GEMM”签名，自定义 kernel 就无法在不绕过框架调度器的前提下接入 tcgen05。因此选型时要问的第一个问题不是“支持不支持分组 GEMM”，而是“插件接口是否把后端选择权交给插件”。公式化地看，一次 MoE 层的前向代价可拆为：</p>\n<div class=\"formula\">$$T_{\\text{layer}} = T_{\\text{route}} + T_{\\text{dispatch}} + T_{\\text{gemm}} + T_{\\text{combine}}$$</div>\n<p>其中 $T_{\\text{gemm}}$ 在回退路径下会因失去 tcgen05 的吞吐优势而显著放大，$T_{\\text{dispatch}}$ 由 All-to-All 原语决定。两者版本错配时，$T_{\\text{gemm}}$ 的膨胀会掩盖 $T_{\\text{dispatch}}$ 的优化收益，使调优方向被误导。举例：一个已经按专家并行拓扑调好 All-to-All 重叠策略的部署，在升级框架后分组 GEMM 静默回退，端到端吞吐下降但通信指标正常，工程师会继续在通信侧加码，实际瓶颈却在 GEMM 路径。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-29\">二十九 · 下游影响：CUDA Graph 捕获粒度反向约束路由与调度</h3>\n<p>框架选型向下游输出的第一个硬约束是 CUDA Graph 捕获粒度：整图、分段、不捕获三档。MoE 的动态路由使每个 token 的专家归属随输入变化，专家侧的 batch 形状因此是数据相关的，这与整图捕获要求的静态形状直接冲突。领域经验做法是按 batch 形状分桶捕获，桶数控制在个位数到十余桶；桶数过多会显著增加捕获时间与显存开销，因为每张图都持有自己的中间缓冲与内核参数副本。</p>\n<p>这个约束会反向传导到批调度与连续批处理：调度器若不能把请求稳定地归入既有桶，就会触发重捕获。最常见踩坑正是在支持分离式预填解码的框架中启用整图 CUDA Graph——解码侧 batch 形状随调度变化，图重捕获频繁，吞吐反而低于分段捕获配置。伪代码层面的判断逻辑是：</p>\n<ul>\n<li>若解码侧 batch 形状方差大且调度器允许动态合批 → 选分段捕获，把 MoE 层单独成段，段间允许形状变化；</li>\n<li>若形状可被调度器钳制到有限桶 → 整图捕获收益最大，但需在调度侧加入桶亲和性约束；</li>\n<li>若路由 kernel 内含宿主同步 → 任何图捕获都会把同步点固化，解码延迟抖动明显，必须先改 kernel 再谈捕获。</li>\n</ul>\n<p>下游影响的第二个面是自定义路由 kernel 的接入成本。以插件形式接入但未适配框架的 CUDA Graph 捕获流程，是已记录的失败模式：图内出现宿主同步，解码延迟抖动明显。这说明“插件接口类型”这一列在速查表中不是装饰项——插件式接入灵活但需要自行承担图捕获适配，编译期注册式接入则把适配责任转移给框架，代价是迭代周期变长。选型时要把接入成本折算成工程人日与上线风险，而不是只看功能清单。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-30\">三十 · 横向耦合：分离式预填解码把选型拆成两个子决策</h3>\n<p>分离式预填解码在 MoE 场景下把框架选型从单一决策变成两个可以不同答案的子决策：预填侧与解码侧的负载特征差异极大，预填是计算密集、形状相对规整，解码是访存密集、形状随调度抖动。上游的分组 GEMM 与专家并行能力在两侧的权重不同——预填侧更依赖 tcgen05 路径的算力利用率，解码侧更依赖 CUDA Graph 的捕获稳定性与 KV 压缩策略。因此允许预填与解码使用不同框架、不同捕获粒度，是这一层耦合给出的工程自由度。</p>\n<p>代价出现在跨侧的数据通路：预填侧产出的 KV 与路由元数据要传给解码侧，传输走 NVLink 5 与 NIXL 一类通路，带宽与延迟成为新的约束项。若两侧框架对 KV 布局的约定不一致，就要插入重排步骤，这部分开销不进任何单侧的性能剖析，却直接抬高端到端延迟。工程判断是：优先选择 KV 布局契约一致的框架组合，其次才比较单侧吞吐；跨侧重排的代价在长上下文场景下会被放大，因为重排量与序列长度成正比。</p>\n<p>横向耦合还牵动容量规划：预填与解码的实例配比不再是固定比例，而随输入输出长度分布变化。选型时要确认框架是否暴露两侧的独立扩缩接口，否则分离部署的收益会被配比刚性抵消。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-31\">三十一 · 与量化条目的接口：NVFP4/FP8 路径成熟度决定回退风险</h3>\n<p>量化条目讨论的是数值精度本身，本条目只关心框架侧的接口面：NVFP4/FP8 路径成熟度在速查表中单列一列，原因是它决定了分组 GEMM 后端能否稳定命中 tcgen05 路径。低精度权重与激活要求 GEMM 内核按精度特化，若框架的插件接口只接受一种精度签名，自定义路由 kernel 与量化内核之间就会出现布局与缩放因子传递的裂缝。裂缝的代价是回退：低精度路径不可用时退回高精度通用 GEMM，显存带宽与算力利用率同时恶化，而路由逻辑本身不受影响，因此监控上看不出异常。</p>\n<p>量化校准数据管线与量化后路由漂移是另外条目的主题，此处只指出接口关系：校准产出的缩放因子必须能通过框架的插件接口传入自定义 kernel，且在图捕获时作为静态参数固化，不能在每次前向时重新计算。若缩放因子在图内动态生成，等于在图里引入数据相关分支，捕获失效。工程上把缩放因子视为“编译期常量 + 版本号”，与 GEMM 路径标识一起纳入启动自检，是避免静默回退的最低成本手段。</p>\n<p>显存侧的代价同样具体：低精度路径省下的是权重与激活的驻留空间，但图捕获的桶数增加会吃掉这部分收益。当桶数从个位数升到十余桶，每张图的中间缓冲叠加起来可能抵消量化带来的显存节省，选型时要把这两项放在同一张预算表里核算。</p>\n\n<h3 id=\"ap-moe-serving-frameworks-sec-32\">三十二 · 在全书中的位置：从单点机制到部署形态的收束点</h3>\n<p>把本条目放回全书结构看，它处在“机制条目”与“部署形态条目”之间的收束位置。上游它依赖算子与数值精度条目给出的 tcgen05、TMEM、NVFP4/FP8 事实，依赖并行与通信条目给出的 All-to-All 与 NVLink 5 通路事实；下游它向 SLO 与容量规划条目输出三个可量化输入：CUDA Graph 桶数带来的捕获与显存开销、分离式部署的跨侧传输代价、GEMM 回退导致的算力利用率折损。这三个输入都不是框架评测式的“快慢排名”，而是可以直接进入容量模型的参数。</p>\n<p>它与其他 MoE 条目的关系是分工而非重复：路由术语速查给出词汇，容量因子与丢弃代价给出调度侧参数，专家并行与 All-to-All 给出通信机制，分组 GEMM 与 tcgen05 给出算子机制，剖析工具链给出观测手段；本条目只回答“这些机制在三个框架里以什么接口形态暴露、接入成本多少、失败模式是什么”。七个领域的推理形态条目则会反向消费本条目：长上下文场景更看重分离式预填解码与 KV 布局契约，低延迟交互场景更看重解码侧图捕获稳定性，批量离线场景更看重 GEMM 路径命中率。选型结论因此不是全局唯一的，而是按领域形态取不同的权重组合。</p>\n<p>最后一个工程判断落在启动自检上：把 GEMM 路径标识、通信原语版本、图捕获桶数、缩放因子版本四项做成服务启动时的硬断言，任何一项不匹配即拒绝上线。这比事后在监控里追查静默回退便宜得多，也是本条目在全书中最直接的落地形式。</p>\n\n\n<h3 id=\"ap-moe-serving-frameworks-sec-33\">三十三 · 边界条件：上游依赖与下游失效的耦合点</h3>\n<p>本条目处在全书“框架层”与“并行通信层”的接缝上：向上依赖 tcgen05 分组 GEMM 后端与 NVLink 5/NCCL All-to-All 原语的实际可用性，向下决定 KV cache 分页、连续批处理调度器与 SLO 容量模型能否成立。选型结论一旦落到“分组 GEMM 走 tcgen05 还是回退路径”，就直接改写 MoE 层的算力利用率与单 token 显存带宽账；一旦落到“预填解码是否分离”，就改写解码侧的 batch 形状分布，从而反向约束 CUDA Graph 的捕获粒度。工程判断的顺序应是：先确认专家并行通信原语与分组 GEMM 后端版本匹配，再定分离式部署，最后才谈图捕获——顺序颠倒会把失效点埋在监控看不到的地方。</p>\n<p>最隐蔽的失效是版本错配：All-to-All 拓扑按某套分组 GEMM 后端调优，而实际加载的 tcgen05 路径因形状或对齐条件不满足回退到通用 GEMM，MoE 层算力利用率大幅下降，监控却无告警，因为 kernel 仍在跑、通信仍在发。可用的判据是有效算力占比：</p>\n<div class=\"formula\">$$\\eta_{\\text{MoE}}=\\frac{\\sum_g \\text{FLOPs}_g}{t_{\\text{gemm}}+t_{\\text{a2a}}}\\Big/\\text{Peak}$$</div>\n<p>当 <span>η</span> 明显低于同形状稠密层基准时，应视为后端回退信号而非负载波动。下游影响随之传导：η 下降迫使调度器提高并发以维持吞吐，KV cache 压力上升，分离式部署下的解码实例更早触顶。</p>\n<p>第二个失效点在插件接口与图捕获的耦合。自定义路由 kernel 以插件形式接入但未适配框架的 CUDA Graph 捕获流程，图内出现宿主同步，解码延迟抖动明显；而在支持分离式预填解码的框架中启用整图捕获，解码侧 batch 形状随调度变化导致频繁重捕获，吞吐反低于分段捕获。按 batch 形状分桶捕获通常控制在个位数到十余桶，桶数过多会显著增加捕获与显存开销。</p>\n<table class=\"mini\"><thead><tr><th>接入方式</th><th>图捕获兼容性</th><th>主要系统代价</th></tr></thead><tbody><tr><td>插件式路由 kernel</td><td>需显式声明无宿主同步</td><td>解码延迟抖动、重捕获开销</td></tr><tr><td>编译期注册</td><td>随图整体捕获</td><td>编译期绑定形状，桶数受限</td></tr></tbody></table>\n<p>因此本条目在全书中的位置是“约束传递器”：它把上游 kernel 与通信的成熟度翻译成下游调度与容量的可行域，选型表里的每一列都应能被追到某个具体失效模式，而不是停留在支持与否的二元标注。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-moe-serving-frameworks\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>对比 TensorRT-LLM、vLLM、SGLang 在 Blackwell 上对分组 GEMM、专家并行、…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-moe-serving-frameworks · 共 5 个片段</p>\n"},{"id":"ap-router-imbalance-fail","title":"路由倾斜尾延迟","summary":"表现为少数专家承载多数 token 导致 All-to-All 热点与分组 GEMM 尾块膨胀，根因是路由分布随输入漂移且容量因子静态；需给出按 batch 监控专家直方图、动态容量与冗余专家复制的缓解手段及其显存代价。","kind":"失败模式","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-1\">一 · 条目边界：什么叫“路由倾斜尾延迟”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-2\">二 · 与相邻概念的切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-3\">三 · 分类维度一：倾斜来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-4\">四 · 分类维度二：观测粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-5\">五 · 分类维度三：缓解手段及其代价归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-6\">六 · 速查表字段与本条目的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-7\">七 · 速查表总览：一张表覆盖监控、容量、复制与放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-8\">八 · 监控口径：为什么必须按 batch，而不是按均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-9\">九 · 容量与复制的联动：阈值触发顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-10\">十 · 两个失败模式在表上的投影</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-11\">十一 · 字段之间的口径一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-12\">十二 · 速查表的失效边界：阈值口径与代价归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-13\">十三 · 阈值从哪里来：从直方图到可判定的数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-14\">十四 · 容量因子：静态值与调整步长的经验设定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-15\">十五 · 冗余专家复制：副本数与显存增量的换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-16\">十六 · 测量方法：把尾延迟变成可复现的数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-17\">十七 · 触发阈值与动作的对应表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-18\">十八 · 阈值怎么定、代价怎么量：倾斜判据的工程边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-19\">十九 · 坑一：容量因子按全局均值配置，倾斜在均值上不可见</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-20\">二十 · 坑二：动态容量因子调整滞后于路由漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-21\">二十一 · 坑三：冗余专家复制未同步路由表，副本空转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-22\">二十二 · 检查顺序：从观测到根因的固定路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-23\">二十三 · 回滚方案：把容量与副本各自独立回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-24\">二十四 · 倾斜治理的失效边界与上线检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-25\">二十五 · 上游依赖：本失败模式寄生在哪些机制之上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-26\">二十六 · 下游影响：谁在为倾斜买单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-27\">二十七 · 与剖析工具链的接口：观测口径决定修复顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-28\">二十八 · 在全书中的位置：失败模式卷的横切面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-29\">二十九 · 跨条目的一致性约束：三个不能各自为政的参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-router-imbalance-fail-sec-30\">三十 · 边界条件：倾斜缓解何时反成新瓶颈</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-router-imbalance-fail\"><svg style=\"max-width:541px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540.6 341\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"458.6\" height=\"66.9\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"45.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"49.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：路由倾斜尾延迟</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">表现为少数专家承载多数 token 导致 All-to-All 热点与分组 G…</text><line x1=\"82.0\" y1=\"80.9\" x2=\"82.0\" y2=\"97.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 96.9 L 86.5 96.9 L 82.0 104.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"104.9\" width=\"458.6\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"146.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"150.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"132.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"155.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">需给出按 batch 监控专家直方图、动态容量与冗余专家复制的缓解手段</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">及其显存…</text><line x1=\"82.0\" y1=\"190.0\" x2=\"82.0\" y2=\"207.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 206.0 L 86.5 206.0 L 82.0 214.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"214.0\" width=\"458.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"236.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"240.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"241.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"260.8\" x2=\"82.0\" y2=\"277.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 276.8 L 86.5 276.8 L 82.0 284.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"284.8\" width=\"458.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"307.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"311.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"312.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-router-imbalance-fail-sec-1\">一 · 条目边界：什么叫“路由倾斜尾延迟”</h3>\n<p>路由倾斜尾延迟（routing-skew tail latency）是 MoE 推理的一种失败模式，不是一种性能指标，也不是一种路由算法缺陷。它的准确定义包含三个必须同时成立的要素：其一，<strong>分布层面</strong>，少数专家承载了显著超出均值的 token 份额；其二，<strong>系统层面</strong>，该不均衡在两条链路上产生可观测代价——All-to-All 的某些 rank 对成为热点链路，分组 GEMM 的某些分组形成尾块膨胀（tail block inflation），即分组内 M 维被撑大而其余分组空转，单次 kernel 的完成时间由最慢分组决定；其三，<strong>时间层面</strong>，这种不均衡随输入漂移而变动，而容量因子（capacity factor）是静态配置的，于是溢出发生在配置与实际分布脱钩的那一段窗口内，表现为 p99 而非均值上的延迟抬升。</p>\n<p>把这三要素写成判据，可以给出一个便于工程落地的形式化描述。设第 $l$ 层第 $b$ 个 batch 的专家 token 直方图为 $h_{l,b}(e)$，$e=1..E$，定义倾斜度</p>\n<div class=\"formula\">$$\\sigma_{l,b}=\\frac{\\max_e h_{l,b}(e)}{\\frac{1}{E}\\sum_e h_{l,b}(e)},\\qquad \\text{overflow}_{l,b}=\\sum_e \\max\\bigl(0,\\;h_{l,b}(e)-C_{l}\\bigr)$$</div>\n<p>其中 $C_l=\\lceil \\kappa \\cdot T_b / E\\rceil$ 是容量因子 $\\kappa$ 下的每专家容量，$T_b$ 为该 batch 的 token 总数。尾延迟事件的充分条件是 $\\text{overflow}_{l,b}&gt;0$ 且 $\\sigma_{l,b}$ 超过工程阈值。领域经验是 $\\sigma$ 超过约 2–3 倍即视为倾斜；材料未给出具体数字，因此这个区间只能作为触发监控告警的量级参考，不能当作 SLA 常数。注意 overflow 是“被丢弃或被排队”的 token 计数，它直接对应输出质量回退与延迟回退的耦合——这正是本条目区别于单纯“负载不均”的地方：负载不均只是统计现象，只有叠加静态容量与漂移，才升级为失败模式。</p>\n<p>一个具体例子：某层 $E=64$、batch 内 $T_b=8192$ token、$\\kappa=1.25$，则 $C_l=160$。若某 batch 因输入域漂移使某个专家收到 420 个 token，则该专家溢出 260 个 token，这些 token 要么被丢弃（质量回退），要么排队到后续 micro-batch（尾延迟）。此时全局平均负载可能看起来完全正常，均值监控不可见。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-2\">二 · 与相邻概念的切分</h3>\n<p>本条目最容易与四个相邻概念混淆，切分的关键在于“失效发生在哪一层”。</p>\n<ul>\n<li><strong>与容量因子/丢弃代价的区别</strong>：容量因子是配置旋钮，丢弃代价是它的静态取值带来的确定性后果；路由倾斜尾延迟是“配置与漂移分布不匹配”这一动态失配过程。前者是参数，后者是过程。容量因子与丢弃代价的完整讨论见同模块对应条目，此处只用一句话指路：静态 $\\kappa$ 是尾延迟的必要条件，不是充分条件。</li>\n<li><strong>与专家并行/All-to-All 的区别</strong>：All-to-All 是通信原语与拓扑问题，其代价即使在完美均衡分布下也存在（固定开销）；路由倾斜只是把这份固定开销在少数 rank 对上放大成热点。判断方法是看 All-to-All 各 rank 对字节数的方差，而非总量。</li>\n<li><strong>与分组 GEMM/tcgen05 的区别</strong>：分组 GEMM 是计算形态，尾块膨胀是它在倾斜输入下的性能表现。tcgen05 的 MMA 指令按分组 tile 发射，最慢分组决定 kernel 完成时刻，因此倾斜直接转化为 SM 占用时间的不均衡。</li>\n<li><strong>与量化后路由漂移的区别</strong>：路由漂移指量化改变 router logits 导致的专家选择分布变化，是倾斜的<em>来源</em>之一；本条目是漂移造成的系统级后果。前者是原因侧，后者是后果侧，二者可独立发生——未量化的模型同样会因输入域漂移而倾斜。</li>\n</ul>\n<p>代价上做一个对照：均衡分布下，All-to-All 的耗时为 $t_{\\text{comm}}\\approx \\alpha + \\beta \\cdot (T_b/E)$，其中 $\\alpha$ 为固定启动开销、$\\beta$ 为每 token 传输成本；倾斜使热点 rank 对的传输量变为 $\\sigma$ 倍，于是该链路耗时约为 $\\alpha+\\beta\\sigma T_b/E$，而其余链路仍在原位等待，形成 barrier 式的尾延迟。分组 GEMM 侧同理，kernel 时间由最大分组决定，SM 利用率按 $E/\\sigma$ 量级下降。显存侧不直接受损，但冗余专家复制作为缓解手段会带来与副本数成正比的专家权重显存增量，需与 KV cache 预算权衡——这条代价链是本条目在容量规划中的落点。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-3\">三 · 分类维度一：倾斜来源</h3>\n<p>来源分类决定缓解手段的选择顺序，三者机制不同，不可混用同一套阈值。</p>\n<p><strong>输入域漂移</strong>：router 是输入的函数，当 batch 内的请求从通用对话切换到代码、数学或长文档摘要时，token 的隐状态分布整体平移，若干专家被系统性偏好。其特征是倾斜在 batch 之间<em>持续</em>存在且与请求内容类型相关，$\\sigma_{l,b}$ 的时间序列呈台阶状。这类倾斜可用路由惩罚/负载均衡损失在推理期做修正，但修正会改变路由决策本身，需评估质量影响。</p>\n<p><strong>负载突增</strong>：总 token 量在短时间内跃升，而 $\\kappa$ 与并行度未同步调整，导致每专家容量相对不足。其特征是 $\\sigma$ 未必显著升高，但 overflow 快速上升——因为分母 $T_b/E$ 也变大了，容量却按旧配置固定。这类倾斜的正确应对是动态容量因子与批调度联动，而非复制专家。</p>\n<p><strong>专家故障</strong>：某个 rank 上的专家因硬件或进程异常不可用，路由表未及时更新，流量被挤压到副本或邻近专家。其特征是倾斜呈<em>阶跃</em>且不可恢复，且往往伴随 All-to-All 某条链路的重传或超时。这类倾斜必须走故障转移路径，任何容量调整都只是掩盖。</p>\n<p>工程判断：先看 $\\sigma_{l,b}$ 的时间形态——台阶状归入漂移，脉冲状归入突增，阶跃不回落归入故障。三种来源对应三套不同的触发阈值与缓解动作，混判会导致“扩容了但热点未缓解”的典型现象。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-4\">四 · 分类维度二：观测粒度</h3>\n<p>粒度决定了尾延迟能否被看见。这是本条目最容易被工程团队忽略的一维。</p>\n<ul>\n<li><strong>按 batch 专家直方图</strong>：$h_{l,b}(e)$ 是唯一能在溢出发生前给出预警的粒度。它需要在 router 之后、dispatch 之前采样，代价是一次 $E$ 维的 reduction，相对分组 GEMM 可忽略，但要求框架暴露 per-batch 的路由统计（TensorRT-LLM、vLLM、SGLang 均有相应钩子，具体接口见框架条目）。</li>\n<li><strong>按层</strong>：$h_l(e)=\\sum_b h_{l,b}(e)$ 聚合后能定位“哪一层最斜”。实践中倾斜往往集中在少数层（尤其是靠近输入的层与任务特异性强的层），按层定位可把冗余专家复制的显存代价压到最小——只复制热点层的热点专家。</li>\n<li><strong>按 rank</strong>：把专家映射到 rank 后统计每 rank 的收发字节，用于识别 All-to-All 热点链路。这一粒度与专家并行条目共享数据源，但解读角度不同：那边看总量与拓扑，这边看方差与 $\\sigma$。</li>\n</ul>\n<p>代价对照：按 batch 监控的存储开销是 $O(L\\cdot E)$ 计数器，可忽略；但它带来的收益是把“均值不可见”的尾延迟变成可告警量。反之，只按全局平均负载设置容量因子是最常见的踩坑——突发输入使单专家 token 溢出容量被丢弃或排队，而监控面板上的均值曲线平滑如常。一个具体例子：某服务在均值口径下每专家负载 128 token、$\\kappa$ 设为 1.25 即容量 160，看似有 25% 余量；但某个 batch 的 $\\sigma=3.2$，热点专家需 410 token，溢出 250 token，p99 延迟抬升而均值不变。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-5\">五 · 分类维度三：缓解手段及其代价归属</h3>\n<p>三类手段对应三种不同的代价科目，选型时先问“代价记在哪个预算上”。</p>\n<table class=\"mini\">\n<thead><tr><th>手段</th><th>作用点</th><th>主要代价科目</th><th>失效形态</th></tr></thead>\n<tbody>\n<tr><td>动态容量因子</td><td>dispatch 前的容量分配</td><td>延迟（调整滞后）与吞吐（容量放大后分组 GEMM 空转）</td><td>调整滞后于路由漂移，扩容前已发生 token 丢弃，质量与延迟同时回退且难以复现</td></tr>\n<tr><td>冗余专家复制</td><td>专家放置与路由表</td><td>显存（与副本数成正比的专家权重增量）</td><td>未同步更新 All-to-All 路由表，副本未被调度命中，显存付出而热点未缓解</td></tr>\n<tr><td>路由惩罚/负载均衡损失推理期修正</td><td>router logits</td><td>质量（改变专家选择）与额外计算</td><td>惩罚过强导致专家专精被破坏，困惑度上升</td></tr>\n</tbody>\n</table>\n<p>动态容量因子的机制可以写成伪代码思路：每个 batch 先采样 $h_{l,b}(e)$，计算 $\\sigma_{l,b}$ 与预测 overflow，若超阈值则把 $\\kappa$ 提升到覆盖 $\\max_e h_{l,b}(e)$ 的水平，再进入 dispatch。代价是容量放大后分组 GEMM 的 M 维被撑大、SM 空转增加，吞吐下降；更关键的是控制环路的时延——扩容决策若在 dispatch 之后到达，本 batch 的丢弃已经发生。这正是失败模式“动态容量因子调整滞后于路由漂移”的机制根源。</p>\n<p>冗余专家复制的机制是把热点专家的权重在另一个 rank 上再放一份，并在路由表中为该专家登记两个目的地。显存代价与副本数成正比：若专家权重占显存 $W$，复制 $r$ 个热点专家则增量约为 $r\\cdot W$，这部分必须从 KV cache 预算中扣除。其失效形态是路由表未同步——副本存在但调度器仍把全部流量发给原 rank，热点链路字节数不变，显存却已付出。判断方法是比对副本 rank 的实际接收字节数与预期份额，若接近零即为未命中。</p>\n<p>工程判断上，三者不是互斥而是分层：先用按 batch 直方图确认来源，漂移类优先考虑路由惩罚与按层冗余复制，突增类优先动态容量并与批调度联动，故障类走故障转移。任何手段上线前必须回答两个问题——代价记在延迟、吞吐还是显存上；以及该手段的失效形态是否已被监控覆盖（热点 rank 字节方差、副本命中率、overflow 计数）。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-6\">六 · 速查表字段与本条目的落点</h3>\n<p>把上述分类固化为速查表，字段必须能同时支撑“发现—归因—处置”三步。监控指标列至少含专家 token 直方图、最大/均值比 $\\sigma$、尾块占比（最慢分组 M 维占该 kernel 总 M 维的比例）；配置列含容量因子当前值与调整策略、冗余专家副本数与放置；代价列含显存增量；定位列含 All-to-All 热点 rank；动作列含触发阈值。这张表的价值在于它把“均值口径”与“尾部分布口径”并列，使监控均值上不可见的尾延迟获得独立字段。</p>\n<p>本条目在整卷中的位置是失败模式的定义层：后续部分将分别展开动态容量的控制环路、冗余复制的放置与路由表同步、以及按 batch 直方图的采样开销。此处只需钉住一条工程判断——路由倾斜尾延迟的判据不是“某个专家很忙”，而是“$\\sigma$ 超阈值、overflow 大于零、且该状态随 batch 漂移而变动”；三者缺一，就只是负载不均或静态容量不足，不该按本条目处置。落到具体机制上：在 router 与 dispatch 之间插入一次 per-batch 直方图 reduction 与 $\\sigma$ 判定，是成本最低、且唯一能在溢出前给出信号的观测点；没有这个观测点，后续所有缓解手段都只能事后补救。</p>\n<h3 id=\"ap-router-imbalance-fail-sec-7\">七 · 速查表总览：一张表覆盖监控、容量、复制与放置</h3>\n<p>本节的速查表按“先观测、再调容量、再复制专家、最后核账”的顺序排列。每一行对应一个可落地的字段，而不是一个概念名词。字段分为四组：监控指标组回答“现在斜不斜”，容量组回答“允不允许溢出”，复制组回答“要不要加副本、加在哪”，代价组回答“显存和 All-to-All 付了多少”。读表时按列从左到右执行：先用监控列判定是否触发，再用容量列决定调整方向，再用复制列决定是否加副本，最后用代价列确认预算是否被击穿。任何一列缺项，都会导致后文列出的两类典型失败——调整滞后于漂移，或副本加了却没被路由命中。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>字段</th><th>口径（怎么算）</th><th>触发阈值</th><th>动作</th><th>代价口径</th></tr>\n</thead>\n<tbody>\n<tr><td>专家 token 直方图</td><td>按 batch 统计每层每个专家的 token 数，不做跨 batch 平均</td><td>与全局均值偏离即记录，不设硬阈值</td><td>作为其余所有字段的输入</td><td>统计本身近乎零成本，但必须每 batch 落盘</td></tr>\n<tr><td>最大/均值比</td><td>同一层内 max(专家 token 数) / mean(专家 token 数)</td><td>超过约 2–3 倍视为倾斜</td><td>进入容量调整与复制评估</td><td>比值本身不耗资源，误判会引发无效扩容</td></tr>\n<tr><td>尾块占比</td><td>分组 GEMM 中 token 数不足一个 tile 的专家组所占比例</td><td>定性观察，随最大/均值比同步恶化</td><td>提示分组 GEMM 尾块膨胀</td><td>尾块直接拉低 MMA 利用率，属吞吐代价</td></tr>\n<tr><td>容量因子当前值</td><td>每专家允许承载的 token 上限 = 容量因子 × 平均 token 数</td><td>静态配置值需与实时直方图对照</td><td>按 batch 动态上调或下调</td><td>上调增加分组 GEMM 工作量与显存占用</td></tr>\n<tr><td>容量调整策略</td><td>依据最近若干 batch 的最大/均值比设定，而非全局平均</td><td>比值越阈值即上调，回落即下调</td><td>动态容量因子</td><td>滞后于漂移则先丢 token，见失败模式</td></tr>\n<tr><td>冗余专家副本数</td><td>对热点专家增加的副本数量</td><td>由最大/均值比与热点持续 batch 数共同决定</td><td>复制热点专家</td><td>专家权重显存增量与副本数成正比</td></tr>\n<tr><td>副本放置</td><td>副本落在哪些 rank / 哪些 GPU</td><td>需覆盖 All-to-All 热点 rank</td><td>与路由表同步更新</td><td>放置不当则副本空转，显存白付</td></tr>\n<tr><td>显存增量</td><td>副本数 × 单专家权重字节数，叠加在原有专家权重之上</td><td>与 KV cache 预算并列核算</td><td>超预算则减副本或改放置</td><td>挤占 KV cache 即压缩并发 batch 数</td></tr>\n<tr><td>All-to-All 热点 rank</td><td>按 rank 统计收发 token 量与链路占用</td><td>与专家直方图的热点专家所在 rank 对齐</td><td>作为副本放置与路由修正的依据</td><td>热点链路决定尾延迟，而非平均带宽</td></tr>\n<tr><td>路由惩罚/均衡修正</td><td>推理期对过热专家的打分施加惩罚</td><td>仅在容量与复制仍不足时启用</td><td>修正路由分布</td><td>改变输出分布，需评估质量回退</td></tr>\n</tbody>\n</table>\n\n<h3 id=\"ap-router-imbalance-fail-sec-8\">八 · 监控口径：为什么必须按 batch，而不是按均值</h3>\n<p>表里第一行“专家 token 直方图”的口径写得极窄：按 batch、按层、按专家统计，不做跨 batch 平均。原因在于路由倾斜的失败模式本身是突发性的——少数专家在特定输入下承载多数 token，而全局平均负载会把这一瞬间抹平。若监控只保留滚动均值，单专家 token 溢出容量被丢弃或排队的事实就不可见，尾延迟在均值曲线上完全消失。直方图是唯一能把“斜”变成可读数字的观测粒度；按层拆开是因为不同层的路由分布漂移方向不同，按 rank 拆开是因为热点专家最终会落到具体链路上。</p>\n<p>最大/均值比是直方图的压缩形式，口径为同一层内最大专家 token 数除以该层均值。工程阈值取约 2–3 倍：低于此值，分组 GEMM 的尾块尚可被其他专家的计算掩盖；超过此值，尾块膨胀开始主导该层耗时，同时 All-to-All 上发往热点专家的流量在对应 rank 上形成排队。这个比值必须逐 batch 计算并与容量因子当前值并排显示，否则运维看到的是两个互不关联的数字。尾块占比作为辅助字段，口径是 token 数不足一个 tile 的专家组比例，它把“斜”翻译成分组 GEMM 的利用率损失，属于吞吐侧代价，与最大/均值比同步恶化但不替代它。</p>\n<div class=\"formula\">$$\\text{skew}_b=\\frac{\\max_{e\\in E} n_{b,e}}{\\frac{1}{|E|}\\sum_{e\\in E} n_{b,e}},\\qquad \\text{cap}_{b,e}=\\alpha_b\\cdot\\frac{1}{|E|}\\sum_{e\\in E} n_{b,e}$$</div>\n<p>式中 $n_{b,e}$ 是 batch $b$ 中专家 $e$ 的 token 数，$\\alpha_b$ 是该 batch 的容量因子。注意容量上限用的是均值乘以因子，而不是历史峰值——这正是“仅按全局平均负载设置容量因子”这一最常见踩坑的数学形态：$\\alpha$ 静态、均值被平滑，突发输入下 $\\text{skew}_b$ 冲高而 $\\text{cap}_{b,e}$ 不动，溢出即刻发生。速查表的动作列因此要求 $\\alpha_b$ 随 $\\text{skew}_b$ 联动，而不是随均值联动。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-9\">九 · 容量与复制的联动：阈值触发顺序</h3>\n<p>表里容量组与复制组的字段不是并列选项，而是有先后。判定倾斜后，第一动作是上调动态容量因子，因为它不改路由、不动权重、显存增量最小；只有当容量上调仍无法吸收热点（例如热点专家在连续多个 batch 上持续承载高比例 token），才进入冗余专家复制。复制的副本数由最大/均值比与热点持续 batch 数共同决定，口径上不设固定倍数，因为副本的边际收益取决于该专家所在 rank 的链路是否已是瓶颈。副本放置字段要求覆盖 All-to-All 热点 rank：若热点专家的流量集中在某几个 rank 的出口，副本应落在能分摊这些出口的位置，否则副本虽在、路由表未同步，调度不会命中，显存代价付出而热点未缓解——这是速查表里代价列与放置列必须成对读取的原因。</p>\n<p>显存增量字段的口径必须写成“副本数 × 单专家权重字节数”，并与 KV cache 预算并列核算，而不是只报专家权重的绝对增量。原因是 MoE 推理的显存预算里，专家权重与 KV cache 争抢同一池子：副本增加直接压缩可并发 batch 数，进而改变 batch 组成，反过来又改变路由分布。这是一个闭环，速查表把它拆成两列，是为了让工程判断落在“加几个副本、KV cache 让出多少”的具体数字上，而不是笼统地说“显存变紧”。</p>\n<ul>\n<li>触发顺序：直方图 → 最大/均值比越阈值 → 上调 $\\alpha_b$ → 仍不足 → 定副本数 → 定放置 → 同步路由表 → 核显存增量。</li>\n<li>回退顺序：热点消退 → 先撤副本（显存回收快）→ 再降 $\\alpha_b$（避免容量骤降引发丢弃）。</li>\n<li>禁止动作：在路由表未更新时先加副本；在未按 batch 监控时调 $\\alpha_b$。</li>\n</ul>\n\n<h3 id=\"ap-router-imbalance-fail-sec-10\">十 · 两个失败模式在表上的投影</h3>\n<p>第一个失败模式——动态容量因子调整滞后于路由漂移——在表上表现为“容量调整策略”行的动作列被执行得太晚：扩容前已发生 token 丢弃，输出质量与延迟同时回退且难以复现。投影到公式上，就是 $\\alpha_b$ 依据的是前若干 batch 的 $\\text{skew}$，而当前 batch 的 $\\text{skew}_b$ 已跃升，$\\text{cap}_{b,e}$ 低于 $n_{b,e}$，溢出被丢弃或排队。速查表对此的防御是把“最大/均值比”与“容量因子当前值”并排放在同一屏，并要求策略行明确写出滞后窗口的 batch 数，让滞后成为可审计的参数而非隐含行为。</p>\n<p>第二个失败模式——冗余专家复制未同步更新 All-to-All 路由表——投影在“副本放置”与“All-to-All 热点 rank”两行的错位上：显存增量已付，热点 rank 的收发量未降。判断方法很直接：加副本后若热点 rank 的 token 量不下降而显存增量上升，即为路由表未同步。速查表把“与路由表同步更新”写进放置行的动作列，就是为了让这一步成为流程的强制项，而不是复制完成后的补救。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>失败模式</th><th>表上可见信号</th><th>对应字段</th><th>代价形态</th></tr>\n</thead>\n<tbody>\n<tr><td>容量调整滞后</td><td>$\\text{skew}_b$ 已越阈值而 $\\alpha_b$ 未变，溢出计数上升</td><td>最大/均值比、容量因子当前值</td><td>延迟与质量同时回退，不可复现</td></tr>\n<tr><td>副本未命中</td><td>显存增量上升而热点 rank 流量不降</td><td>副本放置、All-to-All 热点 rank</td><td>显存白付，尾延迟不变</td></tr>\n</tbody>\n</table>\n\n<h3 id=\"ap-router-imbalance-fail-sec-11\">十一 · 字段之间的口径一致性</h3>\n<p>速查表最容易出错的地方不是阈值，而是口径不一致：直方图按 batch 统计，容量因子却按全局均值设定；副本数按热点专家计，显存增量却按整层专家权重估算；热点 rank 按链路占用排，副本放置却按 GPU 编号排。口径不一致会让表上的数字彼此不可比，运维据此做出的调整方向可能是错的。因此每一行的口径列都写成可复算的表达式，而不是描述性文字。工程判断落在具体机制上：把 $\\text{skew}_b$、$\\alpha_b$、副本数与显存增量四个量放进同一张按 batch 的时间序列，任何一次尾延迟抬升都能回溯到是哪一个量先动、哪一个量没跟上。这张表的价值不在于阈值本身，而在于它强制四个量在同一口径下被同时观测——阈值只是触发读表的条件。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-12\">十二 · 速查表的失效边界：阈值口径与代价归属</h3>\n<p>这张速查表能照着用，前提是每一列都写清“口径”。监控指标一栏必须区分三种粒度：按 batch 的专家 token 直方图（用于捕捉瞬时倾斜）、按层的直方图（用于定位是哪一层的路由先崩）、按 rank 的直方图（用于对齐 All-to-All 热点链路）。最大/均值比要在同一 batch 内计算，跨 batch 取平均会把突发倾斜抹平——这正是“尾延迟在监控均值上不可见”的机制根源。尾块占比定义为分组 GEMM 中超出中位块尺寸的 token 数占比，它比最大/均值比更贴近实际 kernel 时长，因为尾块膨胀直接决定 SM 占用不均衡。触发阈值列必须绑定调整策略：最大/均值比越过领域经验区间（约 2–3 倍）只应触发“观测加密度”，而不是直接扩容；扩容动作要由连续若干 batch 的尾块占比与丢弃计数共同确认，否则动态容量因子会在路由漂移的抖动中反复横跳。</p>\n<p>容量因子与冗余专家两列的代价归属不同，速查表必须分开记。动态容量因子的显存代价近似线性于因子增量与单 token 激活量之积：</p>\n<div class=\"formula\">$$\\Delta M_{\\text{cap}} \\approx \\alpha \\cdot \\Delta c \\cdot \\frac{T}{G}\\cdot d_{\\text{hidden}}\\cdot b_{\\text{bytes}}$$</div>\n<p>其中 Δc 为容量因子增量，T 为 batch token 数，G 为分组数，α 为溢出缓冲系数；代价落在激活缓冲与分组 GEMM 临时区，属于可回收的瞬态占用。冗余专家复制的代价则是常驻的：副本数 k 带来与 k 成正比的专家权重显存增量，必须从 KV cache 预算里扣，在长上下文场景下这笔账往往比容量因子更贵。放置列要写清副本落在哪些 rank、是否跨 NVLink 域，因为副本若与热点 rank 同域，All-to-All 热点只是被摊薄而未被消除。</p>\n<table class=\"mini\"><thead><tr><th>字段</th><th>口径要求</th><th>失效条件</th></tr></thead><tbody><tr><td>最大/均值比</td><td>同 batch 内、按层分别记</td><td>跨 batch 平均后失去敏感性</td></tr><tr><td>尾块占比</td><td>相对中位块尺寸</td><td>仅看全局均值时不可见</td></tr><tr><td>容量因子</td><td>当前值 + 调整滞后窗口</td><td>滞后于路由漂移，扩容前已丢弃 token</td></tr><tr><td>副本数与放置</td><td>副本 rank + 路由表版本</td><td>路由表未同步，副本不被命中</td></tr></tbody></table>\n<p>两个失败模式在表上表现为“字段齐全但因果断裂”。动态容量因子的调整滞后于路由漂移时，扩容发生在 token 已被丢弃或排队之后，输出质量与延迟同时回退，且因依赖输入序列而难以复现——速查表应把“丢弃计数”与“排队深度”作为扩容的前置触发，而不是事后诊断。冗余专家复制未同步更新 All-to-All 路由表时，副本存在却不被调度命中，显存代价已经付出而热点未缓解；因此放置列必须携带路由表版本号，副本上线与路由重分布要作为一次原子操作提交。工程判断落在这一点：速查表的价值不在于列出阈值，而在于每个阈值都标注了“谁付代价、代价是瞬态还是常驻、失效时先看哪一列”。</p>\n<h3 id=\"ap-router-imbalance-fail-sec-13\">十三 · 阈值从哪里来：从直方图到可判定的数</h3>\n<p>工程上判断“倾斜”不能靠均值，均值会把尾块抹平。可操作的量是每个 batch、每一层、每个 rank 上的专家 token 直方图，从中派生三个标量：最大/均值比 <span class=\"formula\">$$R=\\frac{\\max_e n_e}{\\frac{1}{E}\\sum_e n_e}$$</span>、尾块占比（承载超过容量因子上限的专家数占总专家数的比例）、以及热点 rank 的入向字节数。R 是无量纲的，跨层可比；尾块占比直接对应分组 GEMM 里被切碎的小块数量；入向字节数对应 All-to-All 的链路占用。三者缺一不可：只看 R 会把“均匀但整体过载”误判为正常，只看字节数会把“总量大但分布平”误判为倾斜。</p>\n<p>领域经验给出的判定线是 R 超过约 2–3 倍即视为倾斜。这个区间不是精确阈值，而是分档依据：R 在 2 以下时分组 GEMM 的尾块膨胀通常还能被流水掩盖；R 越过 3 之后，最大专家所在 rank 的 All-to-All 发送队列开始成为关键路径，尾延迟从“偶发”变成“结构性”。因此工程上把 2 设为观察线、3 设为动作线，中间区间只做记录不做扩容，避免容量因子随噪声抖动。测量方法必须固定窗口：按 batch 而非按请求统计，因为单请求的 token 数太少、直方图方差大；按层记录而非全局聚合，因为倾斜往往集中在少数层，全局平均会把热点稀释掉。</p>\n<p>代价体现在测量本身。逐 batch、逐层采集直方图意味着每层一次小规模归约，若在关键路径上同步做，会引入可观测的延迟；可行做法是把直方图写入设备端环形缓冲，由独立流异步归约，代价是占用少量显存与一次额外的 kernel 启动。对 B200 这类显存带宽充裕但 SM 资源紧张的器件，这笔开销通常可接受；对 GB200 NVL72 这种跨节点规模，直方图还需按 rank 聚合，聚合频率决定了检测延迟的下界。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-14\">十四 · 容量因子：静态值与调整步长的经验设定</h3>\n<p>容量因子 <span class=\"formula\">$$c=\\frac{C_e}{\\mathbb{E}[n_e]}$$</span>（<span class=\"formula\">$$C_e$$</span> 为单专家容量上限）决定了溢出即丢弃还是排队。静态配置的通病是按全局平均负载设定，突发输入使单专家 token 溢出。工程上的经验做法是把 c 设为“观察窗口内 R 的分位数”而非均值：取近若干 batch 的 R 的较高分位（例如接近上沿），使容量覆盖常见倾斜而不为极端情况预留过多。代价是显存与分组 GEMM 的块尺寸同时上升——容量越大，每个专家分到的缓冲区越大，分组 GEMM 的尾块越难被填满，吞吐反而下降。</p>\n<p>调整步长同样需要经验约束。动态容量因子的失败模式是滞后于路由漂移：扩容决策做出时，token 已经在旧容量下被丢弃或排队，输出质量与延迟同时回退且难以复现。可行的伪代码思路是“先观测后扩容、扩容只升不降、降档走慢路径”：</p>\n<ul>\n<li>每个 batch 结束读取直方图，若 R 越过动作线且连续若干 batch 维持，则把 c 提升一档；</li>\n<li>提升立即生效，因为扩容不改变已有 token 的路由结果；</li>\n<li>收缩必须等待连续多个窗口低于观察线，且以较小步长回落，避免在漂移边界反复震荡；</li>\n<li>任何一次溢出丢弃都打点记录 batch 标识与层号，供离线复现。</li>\n</ul>\n<p>具体例子：某层专家数为数十、单 batch token 数千，均值每专家百余 token；若 c 取 1.5 而某专家实际拿到均值的三倍，则该专家溢出近半，这些 token 要么被丢弃要么排队到下一 batch，尾延迟在监控均值上完全不可见——均值仍是百余，直方图的最大值才暴露问题。这就是“仅按全局平均负载设置容量因子”成为最常见踩坑的原因。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-15\">十五 · 冗余专家复制：副本数与显存增量的换算</h3>\n<p>冗余专家复制的收益是把热点专家的 token 分流到副本，代价是与副本数成正比的专家权重显存增量。工程上必须先算这笔账再决定副本数：单个专家的权重显存为 <span class=\"formula\">$$S_e=\\text{参数量}\\times\\text{每参数字节}$$</span>，在 NVFP4/FP8 权重下每参数字节显著低于 FP16，因此同样显存预算能容纳更多副本——这是低精度带来的隐性容量红利，但激活与 KV cache 并不因此缩小。副本数 k 的显存增量为 <span class=\"formula\">$$\\Delta M=k\\cdot S_e$$</span>，必须与 KV cache 预算并列权衡：在长上下文、大并发场景，KV cache 往往已占去大头，复制专家会直接压缩可服务的并发数。</p>\n<p>副本放置决定收益能否兑现。副本应放在与热点 rank 相邻、且 All-to-All 链路余量较大的 rank 上；若副本与主专家同处一个热点 rank，分流无效。更关键的失败模式是冗余专家复制未同步更新 All-to-All 路由表：副本已加载、显存已付出，但调度器仍把 token 发往主专家，副本从未被命中，热点未缓解而显存代价照付。因此复制必须与路由表更新作为一个原子操作发布，并在发布后校验副本的命中计数非零。</p>\n<p>代价的另一个维度是分组 GEMM 的块数增加：副本使参与计算的专家数变多，尾块更碎，单次 kernel 的调度开销上升。经验判断是副本数从 1 增到 2 的边际收益最大，继续增加时收益递减而显存线性上升，因此工程上通常把副本数控制在个位数低位，并以“热点 rank 的入向字节数是否下降”作为是否继续增加的依据，而不是以 R 是否下降为依据——R 下降可能只是统计口径变化。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-16\">十六 · 测量方法：把尾延迟变成可复现的数</h3>\n<p>尾延迟的测量难点在于它不出现在均值里。可行方法是分层打点：在 All-to-All 发送端记录每个 batch 的入向字节数与排队时长，在分组 GEMM 前后记录每专家的实际 token 数与块尺寸，在输出端记录端到端延迟的分位数。三者对齐到同一 batch 标识，才能判断“尾延迟由热点链路还是尾块膨胀主导”。测量窗口要覆盖负载突增与输入域漂移两类场景，因为二者的直方图形状不同：突增是整体抬升，漂移是分布重心迁移。</p>\n<p>可复现性依赖固定随机源与固定 batch 组成。工程上把触发过溢出的 batch 的输入指纹留存，离线重放时能稳定复现丢弃与排队；否则同一配置在不同流量下表现不同，团队会陷入“无法复现所以无法修复”的循环。代价是留存输入指纹带来存储与隐私处理开销，通常只保留指纹与直方图摘要而非原始 token。</p>\n<p>具体例子：某 rank 的入向字节数在均值上平稳，但分位数上出现尖峰，对齐直方图后发现是单一专家在若干连续 batch 中持续吸收 token，容量因子未变而 R 已越过动作线；此时扩容决策若按均值触发则永不发生，按分位数触发则能在尖峰扩散前介入。这就是把阈值挂在分位数而非均值上的工程理由。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-17\">十七 · 触发阈值与动作的对应表</h3>\n<p>阈值必须与动作一一绑定，否则监控只是数字堆砌。下表给出工程上常用的对应关系，数值为经验分档而非实测结论；材料未给出具体数字的部分以定性表述呈现。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>观测量</th><th>观察线</th><th>动作线</th><th>对应动作</th><th>主要代价</th></tr>\n</thead>\n<tbody>\n<tr><td>最大/均值比 R</td><td>约 2 倍</td><td>约 3 倍</td><td>提升容量因子一档</td><td>分组 GEMM 尾块变碎、吞吐下降</td></tr>\n<tr><td>尾块占比</td><td>低比例</td><td>持续上升</td><td>检查分组 GEMM 块尺寸与专家分组</td><td>kernel 调度开销上升</td></tr>\n<tr><td>热点 rank 入向字节</td><td>接近链路均值</td><td>显著高于均值</td><td>增加冗余专家副本并更新路由表</td><td>专家权重显存增量与副本数成正比</td></tr>\n<tr><td>溢出丢弃计数</td><td>零星</td><td>连续窗口非零</td><td>留存 batch 指纹、离线复现</td><td>存储与隐私处理开销</td></tr>\n<tr><td>副本命中计数</td><td>非零</td><td>长期为零</td><td>校验路由表同步、回滚复制</td><td>显存已付出而无收益</td></tr>\n</tbody>\n</table>\n<p>这张表的用法是“先看 R 再看字节”：R 越过动作线但字节未升，说明倾斜尚未传导到链路，可先调容量因子；字节先升而 R 未动，说明总量抬升而非分布倾斜，扩容无益，应查负载突增来源。两类信号混在一起时，优先处理字节，因为链路热点对尾延迟的传导更快。</p>\n<p>最后落在工程判断上：阈值不是一次设定就固定的常数，而应随流量画像周期性重估；重估的依据是溢出丢弃计数与副本命中计数这两个“事后指标”，它们比 R 更能反映配置是否真的起了作用。若丢弃计数在扩容后仍非零，说明扩容滞后于漂移，应缩短观测窗口而非继续加大容量因子；若副本命中计数长期为零，说明路由表未同步，应先修发布流程再谈显存预算。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-18\">十八 · 阈值怎么定、代价怎么量：倾斜判据的工程边界</h3>\n<p>把“最大/均值比”当作唯一判据会失效，因为分母是 batch 内均值，一个 batch 的 token 总量小、专家数多时，比值对单点抖动极敏感。工程上应同时看三个量：专家 token 直方图的最大/均值比、尾块占比（分组 GEMM 中超出平均 tile 数的专家所占比例）、以及 All-to-All 上单 rank 发送量相对均值的偏离。判据写成可执行形式：设第 b 个 batch 第 l 层专家负载为 $n_{b,l,e}$，则触发条件为 $\\max_e n_{b,l,e} / \\mathrm{mean}_e n_{b,l,e} &gt; \\tau$ 且尾块占比超过 $\\rho$，两个条件同时成立才调整容量因子，避免对短 batch 的噪声误触发。领域经验是最大/均值比超过约 2–3 倍即视为倾斜，但该阈值必须绑定观测粒度——按层看比按全局平均看更早暴露问题，按 rank 看则直接对应热点链路。</p>\n<p>测量方法决定阈值是否可信。专家直方图要在每个 micro-batch 的 dispatch 前后各采一次，前者反映路由概率分布，后者反映实际被容量因子截断后的落点，两者之差就是丢弃量的直接证据；只采后者会把溢出掩盖成“负载均匀”。尾延迟不能看 batch 均值，要按 P99 与单 rank 最大发送字节数记录，因为热点链路的排队时间在均值上不可见。容量因子调整策略应记录当前值、调整步长与调整后的首个 batch 的丢弃计数，形成“调整—验证”闭环；动态容量因子若滞后于路由漂移，扩容前已发生 token 丢弃，输出质量与延迟同时回退且难以复现，这是该方案最典型的失效条件。</p>\n<p>冗余专家复制的代价必须与收益一起记账。副本带来与副本数成正比的专家权重显存增量，在 KV cache 已占满剩余显存的解码阶段，这笔增量直接从并发 batch 数里扣；因此复制前要算清每副本的权重字节数与可让出的 KV 预算，再决定复制哪些专家——只复制直方图长期偏高的热点专家，而不是均匀复制。更隐蔽的失效是副本未同步更新 All-to-All 路由表：副本存在但调度不命中，显存代价付出而热点未缓解，表现为显存占用上升、尾延迟不变。验证方法是比对副本命中的 token 数与副本容量，命中率接近零即说明路由表未刷新。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>采样点</th><th>失效信号</th></tr></thead><tbody><tr><td>最大/均值比</td><td>每层、每 micro-batch</td><td>仅全局均值正常而单层超阈值</td></tr><tr><td>尾块占比</td><td>分组 GEMM 前后</td><td>均值不变、P99 抬升</td></tr><tr><td>单 rank 发送字节</td><td>All-to-All 入口</td><td>热点 rank 偏离均值</td></tr><tr><td>副本命中率</td><td>dispatch 落点</td><td>显存增、延迟不降</td></tr></tbody></table>\n<h3 id=\"ap-router-imbalance-fail-sec-19\">十九 · 坑一：容量因子按全局均值配置，倾斜在均值上不可见</h3>\n<p>最普遍的失败形态是把容量因子当成一个静态的、由离线统计得出的常数写进部署配置，而这个常数来自跨若干天的全局平均专家负载。问题在于，路由倾斜是<b>按 batch 局部发生</b>的事件：全局均值把突发 batch 里某个专家的 token 洪峰完全抹平。一个 batch 内某专家承载的 token 数可以远超其容量上限，超出部分要么被丢弃（drop），要么在分组 GEMM 前排队等待，两条路径都表现为尾延迟而非平均延迟抬升。</p>\n<p>机制上要盯住的是<b>单 batch 单层的专家 token 直方图</b>，而不是跨 batch 聚合后的均值。设第 <i>l</i> 层第 <i>e</i> 个专家在 batch <i>b</i> 中分到 <i>t<sub>l,e,b</sub></i> 个 token，容量上限为 <i>C<sub>l</sub></i>，则溢出量</p>\n<div class=\"formula\">$$O_{l,b}=\\sum_{e}\\max\\left(0,\\;t_{l,e,b}-C_{l}\\right),\\qquad \\rho_{l,b}=\\frac{\\max_{e}t_{l,e,b}}{\\frac{1}{E}\\sum_{e}t_{l,e,b}}$$</div>\n<p>其中 <i>ρ</i> 是最大/均值比，也是速查表里的核心监控列。<i>O<sub>l,b</sub></i> 大于零即意味着该 batch 已经发生了容量违约，此时尾块膨胀与 All-to-All 热点同时出现：热点 rank 上该专家的输入分片体积最大，分组 GEMM 的最后一个 tile 只填了少量有效行，算力被浪费在 padding 上。代价是双向的——被丢弃的 token 直接损伤输出质量且不可复现（同一请求重放可能不丢），排队的 token 则把 P99 拉长到与 <i>O<sub>l,b</sub></i> 成正比。</p>\n<p>具体例子：一个客服意图分类服务，平时各专家负载均衡，但促销日输入域整体漂移到某几类意图，单个 batch 内某专家 token 数达到均值的数倍。监控面板上的全局平均负载曲线几乎不动，而 P99 已经翻倍——这就是“尾延迟在均值上不可见”的典型现场。检查动作：把专家直方图从“按小时聚合”改为“按 batch 采样并保留最近若干个 batch 的快照”，并在 <i>ρ</i> 越过经验区间（约 2–3 倍）时立刻打印该 batch 的层号、专家号与热点 rank。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-20\">二十 · 坑二：动态容量因子调整滞后于路由漂移</h3>\n<p>第二个坑出现在已经上了动态容量因子的团队：机制有了，但控制回路太慢。容量因子的调整依赖对专家直方图的观测，而观测本身有窗口（一个 batch 或若干个 batch 的滑动平均），调整又要经过配置下发、分组 GEMM 的 workspace 重算、可能的显存重分配。当路由分布在一个 batch 内快速漂移时，扩容动作落地时洪峰已经过去，而<b>扩容前的那几个 batch 已经发生了 token 丢弃</b>。结果是输出质量与延迟同时回退，且因为丢弃发生在扩容之前，日志里看到的是一条“扩容成功、指标恢复”的曲线，问题难以复现。</p>\n<p>伪代码思路是把控制回路拆成“预测—预留—回收”三段，而不是“观测—扩容”两段：</p>\n<ul>\n<li>预测段：用当前 batch 的 <i>ρ<sub>l,b</sub></i> 与前若干 batch 的漂移速度估计下一 batch 的容量需求，向上取整到分组 GEMM 的 tile 粒度；</li>\n<li>预留段：容量上限只增不减地抬到一个高水位，高水位对应的 workspace 显存在稳态时就预留好，避免扩容时触发重分配；</li>\n<li>回收段：连续若干个 batch 的 <i>ρ</i> 回落到阈值以下才降水位，降水位比抬水位慢一个数量级。</li>\n</ul>\n<p>代价判断很直接：高水位预留的 workspace 显存是常态占用，抬得越高，留给 KV cache 的预算越少。对长上下文服务，这个权衡往往决定成败——容量因子抬高带来的分组 GEMM workspace 增量必须与 KV cache 预算一起核算，而不是单独看 MoE 侧。工程判断是：宁可让高水位略高于观测峰值，也不要让扩容发生在丢弃之后；把“扩容前已丢弃”作为一个独立的告警指标（丢弃计数与扩容事件的时间戳对齐）来监控。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-21\">二十一 · 坑三：冗余专家复制未同步路由表，副本空转</h3>\n<p>冗余专家复制的直觉很朴素：热点专家多放几个副本，把它的 token 分摊开。失败模式在于<b>复制动作与路由表更新是两套流程</b>。副本权重被加载到目标 rank、显存已经付出，但 All-to-All 的发送侧路由表仍按原专家到 rank 的映射分发 token，副本从未被调度命中。现象是显存占用上升、热点 rank 的入站分片体积不变、尾延迟毫无改善——付出代价而热点未缓解，且因为“复制已完成”的检查项打了勾，排查方向会被误导到别处。</p>\n<p>机制上，副本生效需要三件事同时成立：发送侧路由表把该专家的 token 按某个分摊策略（轮询或按副本所在 rank 的链路负载）分配到多个目标 rank；接收侧的分组 GEMM 在每个副本上独立完成局部归约；结果的合并（若需要）在正确的同步点上完成。任何一环缺失，副本就是死权重。检查顺序应当是<b>先验证命中、再验证分摊、最后验证合并</b>：在副本所在 rank 上打印该专家实际收到的 token 数，若为零则路由表未更新；若不为零但各副本间分布严重不均，则分摊策略或链路负载估计有问题。</p>\n<p>显存代价与副本数成正比，这是硬约束：每多一份专家权重副本，就多一份常驻显存，且这份显存不能像 KV cache 那样按请求弹性伸缩。因此复制的决策必须与 KV cache 预算联动——在显存紧张时，优先复制<b>跨层持续热点</b>的专家（在多个 batch 的直方图里都排在前列），而不是复制单 batch 的偶发峰值专家。后者用动态容量因子吸收更划算。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-22\">二十二 · 检查顺序：从观测到根因的固定路径</h3>\n<p>尾延迟告警触发后，排查顺序应当是固定的，避免每次从头试错。建议的顺序与每步的判定依据如下表。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>步骤</th><th>观测对象</th><th>判定与动作</th></tr>\n</thead>\n<tbody>\n<tr><td>1</td><td>按 batch 的专家直方图与 <i>ρ</i></td><td><i>ρ</i> 越过经验区间即确认倾斜；记录层号、专家号、batch 标识</td></tr>\n<tr><td>2</td><td>容量违约计数 <i>O<sub>l,b</sub></i></td><td>大于零说明已发生丢弃或排队，区分二者看是质量回退还是纯延迟</td></tr>\n<tr><td>3</td><td>All-to-All 热点 rank 的入站分片体积</td><td>与直方图对齐，确认热点来自倾斜而非链路故障</td></tr>\n<tr><td>4</td><td>分组 GEMM 尾块占比</td><td>尾块膨胀说明 padding 浪费，与 <i>O<sub>l,b</sub></i> 同源</td></tr>\n<tr><td>5</td><td>副本命中计数</td><td>为零则路由表未同步；分布不均则分摊策略失效</td></tr>\n<tr><td>6</td><td>容量因子调整事件时间戳</td><td>与丢弃计数对齐，确认是否存在调整滞后</td></tr>\n</tbody>\n</table>\n<p>这个顺序的价值在于它把“倾斜来源”的三分类（输入域漂移、负载突增、专家故障）落到不同步骤上：输入域漂移表现为直方图形状持续偏移且跨 batch 相关；负载突增表现为单 batch 尖峰、前后 batch 正常；专家故障表现为某专家 token 数骤降而其邻居骤升——最后一种在步骤 1 就能与倾斜区分开，因为它的 <i>ρ</i> 可能并不高，但分布形状异常。代价上，步骤 1–4 只需读监控与日志，步骤 5 需要副本侧埋点，步骤 6 需要配置变更审计，全部为低开销观测，不引入额外推理延迟。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-23\">二十三 · 回滚方案：把容量与副本各自独立回退</h3>\n<p>动态容量因子与冗余专家复制是两类改动，回滚必须能分别执行，否则一次失败会把两个变量搅在一起。回滚方案的设计原则是<b>每个缓解手段有独立的开关与独立的前置快照</b>：容量因子回滚到上一版静态配置（连同其 workspace 显存预算），副本回滚到复制前的专家放置表与路由表。两者都要求路由表与权重放置的一致性校验——回滚副本时若只卸载权重而不回退路由表，发送侧仍指向已不存在的目标，会直接触发通信失败而非性能问题。</p>\n<p>回滚触发条件应当是量化的：扩容后若丢弃计数未归零、或 <i>ρ</i> 未回落而尾延迟继续抬升，说明扩容方向错误（可能是热点不在被扩容的层，或瓶颈已转移到 All-to-All 链路），此时回滚容量因子并转向链路侧排查。副本侧若命中计数为零且已确认路由表同步无误，回滚副本以回收显存。工程判断落在最后一步：任何缓解手段上线前，先在影子流量上跑通“开启—观测—回滚”全链路，确认回滚后显存与路由表恢复到基线，再放到生产；因为尾延迟问题的复现成本高，回滚路径不通畅会让团队在故障现场失去唯一的确定性手段。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-24\">二十四 · 倾斜治理的失效边界与上线检查顺序</h3>\n<p>动态容量因子与冗余专家复制都不是“设好即忘”的开关，它们各自有明确的失效条件。动态容量因子最典型的失效是调整滞后于路由漂移：容量扩容依赖上一窗口的专家直方图统计，而突发输入在统计窗口内已经把单专家 token 推到容量上限之上，溢出 token 被丢弃或排队，扩容生效时损失已经发生。此时输出质量与尾延迟同时回退，且因为丢弃发生在个别 batch 上，事后难以复现。判断是否落入该失效模式，看的是扩容动作与丢弃计数的时间先后，而不是平均负载曲线。冗余专家复制则有另一类失效：副本权重加载完成但 All-to-All 路由表未同步更新，调度侧仍按原专家编号寻址，副本从未被命中，显存代价已经付出而热点链路毫无缓解。检查方法是比对路由表中各专家的可达副本数与实际命中计数，命中为零的副本即为无效复制。</p>\n<p>检查顺序应按“先观测、再容量、后复制”推进，避免用昂贵的显存手段掩盖观测缺失。第一步确认按 batch 的专家直方图确实在采集，而非只有全局平均；第二步核对容量因子当前值与调整策略是否绑定到直方图的触发阈值；第三步才评估冗余专家副本数与放置。用最大/均值比作为倾斜判据时，需注意它只反映分布形状、不反映绝对溢出量，因此要与尾块占比、丢弃计数联合判读。设第 $b$ 个 batch 中专家 $e$ 承载 token 数为 $n_{b,e}$、容量为 $C_e$，则溢出量可写为：</p>\n<div class=\"formula\">$$O_b=\\sum_e \\max(0,\\; n_{b,e}-C_e)$$</div>\n<p>该式直接给出“容量因子是否够用”的判据：只要 $O_b$ 在正常输入下非零，就说明静态容量已经失效，此时任何仅优化 GEMM 尾块切分的努力都是次要的。</p>\n<p>回滚方案必须与缓解手段成对设计。动态容量因子的回滚点是容量策略版本与触发阈值，回滚后需确认丢弃计数回到基线、尾延迟分布恢复；冗余专家复制的回滚点是副本放置表与路由表，两者必须原子地一起回退，否则会出现路由指向已卸载副本的悬空寻址。下表给出上线前的最小检查清单，各列对应可观测项与代价项：</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判据</th><th>系统代价</th></tr></thead><tbody><tr><td>按 batch 专家直方图</td><td>最大/均值比超阈值即告警</td><td>采集开销落在调度侧，不影响 GEMM</td></tr><tr><td>容量因子与触发阈值</td><td>扩容动作早于丢弃计数上升</td><td>扩容抬高分组 GEMM 尾块，占用算力</td></tr><tr><td>副本数与路由表一致性</td><td>每个副本命中计数非零</td><td>专家权重显存随副本数线性增长，挤压 KV cache</td></tr><tr><td>All-to-All 热点 rank</td><td>热点链路与倾斜专家对应</td><td>热点未缓解时链路带宽成为尾延迟主因</td></tr></tbody></table>\n<p>工程判断落在代价的权衡上：冗余专家复制的显存增量与副本数成正比，在 KV cache 预算紧张的部署中，复制两个热点专家可能比调高容量因子更贵；而容量因子调高只增加尾块计算量、不增加权重常驻显存，代价形态完全不同。因此当倾斜主要来自输入域漂移而非持续负载突增时，优先修正路由惩罚与容量策略，把复制留给稳定复现的热点专家。任何一项缓解上线前，都应先在单 batch 粒度验证 $O_b$ 归零且副本命中非零，再放开到全量流量。</p>\n<h3 id=\"ap-router-imbalance-fail-sec-25\">二十五 · 上游依赖：本失败模式寄生在哪些机制之上</h3>\n<p>路由倾斜尾延迟不是一个可以独立修复的缺陷，它是四个上游机制耦合出来的症状：路由函数、容量因子、专家并行 All-to-All、分组 GEMM。任何一项的上游条目发生变更，倾斜的观测口径与缓解手段都要跟着改。路由函数决定了直方图的形状——top-k 的 k 值、softmax 温度、是否有 bias 修正项，都会改变最大/均值比；容量因子决定溢出何时发生；All-to-All 决定热点落在哪条 NVLink 5 链路上；分组 GEMM 决定尾块膨胀折算成多少 SM 空闲周期。因此本条目在全书中的定位是“横切诊断条目”：它不拥有任何一个机制，却要求读者同时读懂这四个条目的接口。</p>\n<p>具体机制上，倾斜的代价可以写成一个可加分解：</p>\n<div class=\"formula\">$$T_{\\text{tail}} \\approx T_{\\text{GEMM}}^{\\text{mean}} + \\Delta T_{\\text{GEMM}}^{\\text{skew}} + \\Delta T_{\\text{A2A}}^{\\text{hot}} + T_{\\text{drop/queue}}$$</div>\n<p>其中第二项来自分组 GEMM 中最大组与平均组的差，第三项来自热点 rank 的链路排队，第四项是容量溢出后的丢弃或重排队。工程判断是：如果监控只看到总时延，这四项会互相掩盖；只有按 batch 采集专家直方图，才能把 $\\Delta T$ 归因到具体项。举例：一个 batch 内某专家 token 数达到均值的 2–3 倍以上时，分组 GEMM 的尾块开始主导，而 All-to-All 侧同一 rank 的发送队列同时变长，两项叠加使 p99 抬升，但均值几乎不动——这正是上游“仅按全局平均设容量因子”踩坑的物理来源。</p>\n<p>上游依赖还体现在数值精度条目上：NVFP4/FP8 的权重激活改变了专家权重的显存占用，从而改变了“冗余专家复制”的预算上限。复制一个专家副本的显存增量与副本数成正比，精度越低单副本越便宜，可复制的冗余度越高；但量化后路由漂移条目又会改变直方图形状，使原本的冗余放置失效。这两条上游条目与本条目是双向约束关系，不能各自独立调参。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-26\">二十六 · 下游影响：谁在为倾斜买单</h3>\n<p>倾斜的下游第一个受害者是分离式预填/解码。预填阶段 token 密度高、batch 大，直方图更容易出现尖峰；一旦预填节点的 All-to-All 热点 rank 拥塞，KV cache 的写入节奏被打乱，解码侧拿到的首 token 时间被拉长。分离式架构把预填与解码放在不同资源池，倾斜造成的排队不会自动跨池传导，但 SLO 是按端到端算的，于是容量规划被迫给预填池留出额外余量——这部分余量在正常 batch 上是纯浪费。</p>\n<p>第二个下游是批调度与连续批处理。连续批处理把不同请求的 token 拼进同一 micro-batch，路由直方图是这些请求的混合分布；倾斜的出现往往不是单请求造成，而是某类输入域在同一时间窗内聚集。调度器若按请求数而非按专家负载做准入，就会在不知不觉中把一批同域请求塞进同一 batch，制造人为尖峰。可行的机制是在准入侧维护一个按层的专家负载估计，伪代码思路为：</p>\n<ul>\n<li>对每个待准入请求，用轻量路由前向（或历史直方图）估计其对各专家的 token 贡献向量；</li>\n<li>与当前 batch 的累计直方图相加，若某专家预计超过容量因子阈值则推迟该请求或降低其 batch 优先级；</li>\n<li>准入决策与动态容量因子联动：容量上调需要时间，准入是唯一能在扩容生效前挡住溢出的手段。</li>\n</ul>\n<p>代价是调度器多了一次估计开销与排队延迟，吞吐在倾斜场景下换取 p99 稳定，在均匀场景下则是纯损耗，因此需要按监控指标开关。第三个下游是 KV 压缩与显存预算：冗余专家复制吃掉的是专家权重显存，与 KV cache 争同一块 HBM；MoE 场景 KV 压缩条目压缩的是激活侧缓存，两者预算此消彼长。工程上必须把“副本数 × 单副本权重显存”作为一项显式预算列入容量规划表，否则复制策略会在长上下文场景下把 KV 挤到换出。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-27\">二十七 · 与剖析工具链的接口：观测口径决定修复顺序</h3>\n<p>本条目与 MoE 剖析工具链的关系是“消费方”而非“提供方”。工具链给出按层、按 rank、按 batch 的专家直方图与 All-to-All 链路占用，本条目定义读法：先看最大/均值比是否越过 2–3 倍的经验线，再看尾块占比，最后看热点 rank 是否与直方图峰值同址。三者顺序不能颠倒——若先看链路再看直方图，会把“副本未被调度命中”误判为“副本不足”，从而付出显存代价却没缓解热点。</p>\n<p>一个具体的检查序列：取一个 batch 的直方图，计算每层最大组 token 数与均值之比；若某层越线，检查该层容量因子当前值与最近一次调整的时间戳；若调整滞后于直方图漂移，说明动态容量策略的采样窗口太长。再检查冗余专家副本的放置：副本所在 rank 是否出现在 All-to-All 热点列表中，若副本从未被路由表命中，则问题在路由表同步而非副本数量。这条序列把“扩容前已发生丢弃”与“副本未命中”两类失败模式区分开，前者是时间问题，后者是拓扑问题。</p>\n<p>代价维度上，剖析本身要采样，采样频率与 batch 时长挂钩：频率过低会漏掉突发尖峰，过高则剖析开销侵占计算。工程判断是把直方图采集挂在分组 GEMM 的组边界上，而非固定时间间隔，这样采样点天然对齐尾块统计，且不引入额外同步。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-28\">二十八 · 在全书中的位置：失败模式卷的横切面</h3>\n<p>本书按“算子与精度—显存与 KV—调度—并行与通信—框架—SLO 与容量”分层，本条目落在失败模式卷，且是唯一同时触及四层的条目。它向上引用算子层的分组 GEMM 与 tcgen05 尾块行为，向并行层引用 All-to-All 与 NVLink 5 拓扑，向调度层引用连续批处理准入，向容量层引用冗余复制的显存预算。因此它在全书中的功能是“把分层知识缝合成一次故障归因”。</p>\n<p>与相邻条目的边界需要明确：容量因子与丢弃代价条目讲的是静态配置的代价模型，本条目讲的是静态配置在漂移下如何失效；专家并行与 All-to-All 条目讲的是通信原语与拓扑，本条目只讲热点链路如何被直方图尖峰点亮；量化后路由漂移条目讲的是精度变化对路由分布的影响，本条目把它当作上游扰动源之一。通信计算死锁条目与本条目共享“All-to-All 队列”这一观测面，但死锁是活性问题，倾斜是尾延迟问题，两者的监控指标不可混用。</p>\n<p>框架选型条目提供落地载体：TensorRT-LLM、vLLM、SGLang、Dynamo 对动态容量因子与冗余专家复制的支持程度不同，本条目给出的阈值与检查清单需要按框架能力裁剪。例如某些框架的容量因子在编译期固化，动态调整只能通过重新加载引擎实现，此时准入侧限流就是唯一可行的在线手段——这不是框架缺陷，而是本条目必须承认的工程约束。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-29\">二十九 · 跨条目的一致性约束：三个不能各自为政的参数</h3>\n<p>容量因子、冗余副本数、路由惩罚系数是三个必须联合标定的参数，分别属于调度层、显存层与路由层。单独调容量因子会把溢出转成排队；单独加副本会在路由表未同步时白付显存；单独加路由惩罚会改变直方图形状却可能损害模型质量。联合标定的机制是：以按 batch 直方图的最大/均值比为输入，先定副本放置（拓扑问题），再定容量因子（时间问题），最后才考虑路由惩罚（质量与负载的折中）。</p>\n<table class=\"mini\"><thead><tr><th>参数</th><th>所属层</th><th>失效表现</th><th>代价</th></tr></thead><tbody><tr><td>容量因子</td><td>调度</td><td>调整滞后于漂移，扩容前已丢弃</td><td>丢弃后输出质量与延迟同时回退</td></tr><tr><td>冗余副本数</td><td>显存</td><td>路由表未同步，副本未命中</td><td>显存增量与副本数成正比，热点未缓解</td></tr><tr><td>路由惩罚系数</td><td>路由</td><td>推理期修正改变分布，质量漂移</td><td>需与量化校准数据管线对齐验证</td></tr></tbody></table>\n<p>这张表的意义在于：三个参数的失效表现互不相同，但都会在端到端 p99 上表现为“尾延迟变差”，因此监控必须按参数分列指标，否则修复顺序无从判断。工程判断是，把三者写进同一份容量规划表，并规定任何一项变更都要重跑按 batch 直方图基线，否则变更的效果无法归因。</p>\n<p>最后落在具体机制上：冗余专家复制的放置应优先选择 All-to-All 热点 rank 的邻居 rank，使副本命中的流量走最短 NVLink 5 跳数；副本的调度命中率必须作为一等指标与直方图并列采集，命中率不上升就回滚副本，而不是继续加副本。这条规则把显存代价与热点缓解绑定成可验证的因果关系，也是本条目与全书其他条目共享的工程底线。</p>\n\n<h3 id=\"ap-router-imbalance-fail-sec-30\">三十 · 边界条件：倾斜缓解何时反成新瓶颈</h3>\n<p>本条目在全书中的位置是“失败模式诊断层”而非“性能优化层”：它上游依赖分组 GEMM 与 All-to-All 通信两条条目给出的时延分解，下游则把结论交给容量规划与 SLO 条目去折算成副本预算。边界在于，动态容量因子与冗余专家复制都只对“路由漂移慢于调度周期”的场景有效。设 batch <em>b</em> 的专家直方图最大/均值比为 <em>R<sub>b</sub></em>，调度周期为 <em>T<sub>s</sub></em>，路由分布漂移时间常数为 <em>τ</em>，则缓解有效的前提可写成：</p>\n<div class=\"formula\">$$T_s \\ll \\tau \\quad\\text{且}\\quad \\max_b R_b \\le \\frac{C_{\\text{cap}}}{C_{\\text{base}}}$$</div>\n<p>一旦 <em>τ</em> 收缩到与 <em>T<sub>s</sub></em> 同量级（突发输入、专家故障引发的瞬时重路由），扩容决策落地前 token 已按旧容量被丢弃或排队，输出质量与尾延迟同时回退，且因依赖输入序列而难以复现——这正是该方案最典型的失效条件。冗余专家复制还有独立的失效面：副本放置若未同步更新 All-to-All 路由表，调度器仍按原映射发 token，副本永不命中，显存代价照付而热点未减。因此复制必须与路由表版本绑定发布，二者原子切换。</p>\n<p>系统代价需在三个维度上同时记账，不能只看均值延迟：</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>随什么增长</th><th>冲突对象</th></tr></thead><tbody><tr><td>专家权重显存</td><td>副本数（近似正比）</td><td>KV cache 预算</td></tr><tr><td>All-to-All 带宽</td><td>副本带来的额外目的 rank 数</td><td>NVLink 域内热点链路</td></tr><tr><td>调度抖动</td><td>容量因子调整频率</td><td>连续批处理的稳态吞吐</td></tr></tbody></table>\n<p>工程判断上，本条目只应在监控已按 batch 采集专家直方图、且最大/均值比越过经验阈值（约 2–3 倍）时被触发；若监控粒度仍是全局平均，则任何缓解手段都失去判据，尾延迟在均值上不可见。与容量规划条目的接口是显存增量与 KV cache 的此消彼长，与并行通信条目的接口是副本放置对 rank 拓扑的约束——本条目给出触发条件与代价结构，具体配额由那两条目闭合。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-router-imbalance-fail\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>表现为少数专家承载多数 token 导致 All-to-All 热点与分组 GEMM 尾块膨胀，根因是路由分布…</td></tr><tr><td>关键点</td><td>需给出按 batch 监控专家直方图、动态容量与冗余专家复制的缓解手段及其显存代价。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-router-imbalance-fail · 共 5 个片段</p>\n"},{"id":"ap-quant-drift-fail","title":"量化后路由漂移","summary":"低比特量化改变门控分数排序，造成专家选择变化与输出质量回退；需说明路由层保持高精度的必要性、量化前后 top-k 一致率指标、以及激活离群值导致的块缩放失效检测方法。","kind":"失败模式","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-1\">一 · 条目边界：什么叫“量化后路由漂移”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-2\">二 · 分类维度一：漂移对象落在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-3\">三 · 分类维度二：度量口径决定你能否看见漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-4\">四 · 分类维度三：检测手段与触发条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-5\">五 · 速查表的列设计与精度策略归类</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-6\">六 · 定义落地的判断顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-7\">七 · 路由漂移的边界条件：何时该判“失效”，而不是“误差略大”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-8\">八 · 速查表主表：七列字段与填写口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-9\">九 · 阈值带：三档判定与不可协商项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-10\">十 · 一致率与重叠率的读法：两种翻转要分开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-11\">十一 · 离群值与块缩放饱和：检测动作与告警口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-12\">十二 · 回归工具列：比对对象决定这张表是否有效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-13\">十三 · 阈值的落点：先定“测什么”，再定“卡多少”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-14\">十四 · 经验区间与它的适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-15\">十五 · 离群值与块缩放的失效判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-16\">十六 · 回归工具与切片口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-17\">十七 · 没有数字时怎么测：可复现的标定流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-18\">十八 · 阈值落地的三重盲区：全局一致率、块缩放饱和与长尾稀释</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-19\">十九 · 踩坑清单：门控层被统一量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-20\">二十 · 踩坑清单：回归只比对 loss 不比对集合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-21\">二十一 · 踩坑清单：块缩放饱和被逐层误差掩盖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-22\">二十二 · 检查顺序：从数据到集合到端到端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-23\">二十三 · 回滚方案：分层回滚而非整体回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-24\">二十四 · 路由漂移回归的失效边界与检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-25\">二十五 · 上游依赖：门控精度策略与量化格式选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-26\">二十六 · 下游影响：容量因子、尾延迟与丢弃代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-27\">二十七 · 度量口径的上下游对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-28\">二十八 · 在全书中的位置：量化失败模式的验收端点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-29\">二十九 · 放行判断：把漂移检测写成可执行的回归门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-quant-drift-fail-sec-30\">三十 · 边界条件：路由漂移在什么系统形态下才真正致命</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-quant-drift-fail\"><svg style=\"max-width:541px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540.6 341\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"458.6\" height=\"66.9\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"45.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"49.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：量化后路由漂移</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">低比特量化改变门控分数排序，造成专家选择变化与输出质量回退</text><line x1=\"82.0\" y1=\"80.9\" x2=\"82.0\" y2=\"97.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 96.9 L 86.5 96.9 L 82.0 104.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"104.9\" width=\"458.6\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"146.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"150.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"132.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"155.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">需说明路由层保持高精度的必要性、量化前后 top-k 一致率指标、以及</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">激活离群…</text><line x1=\"82.0\" y1=\"190.0\" x2=\"82.0\" y2=\"207.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 206.0 L 86.5 206.0 L 82.0 214.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"214.0\" width=\"458.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"236.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"240.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"241.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"260.8\" x2=\"82.0\" y2=\"277.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 276.8 L 86.5 276.8 L 82.0 284.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"284.8\" width=\"458.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"307.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"311.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"312.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-quant-drift-fail-sec-1\">一 · 条目边界：什么叫“量化后路由漂移”</h3>\n<p>量化后路由漂移（post-quantization routing drift）指模型在低比特量化之后，<strong>门控网络输出的分数排序发生改变</strong>，从而使 top-k 专家集合与量化前不一致，最终表现为输出质量回退。它有三个必要成分，缺一不可：其一，量化作用于门控通路（门控线性层权重或激活、路由 logits）；其二，排序发生变化而非仅仅是数值整体平移；其三，变化穿透到 top-k 选择并影响下游计算。若量化只让 logits 整体缩小一个常数倍而 top-k 集合不变，那是数值尺度问题，不是路由漂移；若 top-k 变了但下游专家输出经加权后几乎等价（例如被选中的专家本身近似），那是无害翻转，属于度量口径要排除的情形。</p>\n<p>与相邻概念的分界必须说清。它与“专家层量化误差”不同：后者作用于专家自身的 GEMM，误差在固定路由下传播，度量对象是逐层输出偏差；路由漂移的误差源在<em>选择器</em>，即使每个专家都量化得很准，选错了专家依然回退。它与“路由倾斜/负载不均”不同：倾斜是路由分布本身的统计形态，量化前就存在；漂移是量化<em>引入的分布改变</em>，两者叠加时表现为倾斜被放大或方向反转。它与“激活离群值导致的块缩放失效”是因果关系而非同义：离群值饱和是机制，路由漂移是可观测后果之一，同一机制也可能只造成专家内部精度损失而不改变排序。它与 MoE 场景的 KV 压缩分属不同对象：后者压缩的是注意力侧缓存，路由漂移发生在门控侧，二者的度量工具与回归基线不可混用。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-2\">二 · 分类维度一：漂移对象落在哪一层</h3>\n<p>按被量化的对象分三类，工程处置完全不同。第一类是<strong>门控线性层权重</strong>量化：权重静态，误差可离线分析，漂移表现为对输入域的整体敏感性上升，通常在特定 token 分布上集中爆发。第二类是<strong>门控激活</strong>量化：动态范围随 batch 变化，是 NVFP4 块缩放最容易失效的位置，因为门控输入的离群通道会撑爆块上限。第三类是<strong>路由 logits 本身</strong>被低精度承载（例如在融合内核里以 FP8 累加或写回），这类漂移最隐蔽——它不改变任何权重，只在数值通路上引入舍入，却直接决定 top-k 边界上的名次交换。</p>\n<p>分类的工程意义在于定位修复点。权重类漂移的修复是“门控层保持高精度”（BF16/FP16 权重、FP8 仅用于专家），代价是门控 GEMM 的吞吐下降，但门控计算量相对专家 GEMM 极小，对端到端延迟影响有限；激活类漂移的修复是门控输入走非量化通路或提高块缩放粒度，代价是额外的反量化与带宽；logits 类漂移的修复是保证排序在 FP32 域完成，代价是一次小的类型转换与同步。判断顺序应是：先确认漂移对象，再谈阈值，否则会把权重问题误诊为激活问题而反复调校准集。</p>\n<div class=\"formula\">$$\\text{top-}k\\ \\text{一致率}=\\frac{1}{N}\\sum_{i=1}^{N}\\frac{|S_i^{\\text{fp}}\\cap S_i^{\\text{q}}|}{k},\\quad S_i=\\text{top-}k(\\text{logits}_i)$$</div>\n<p>该式给出最基础的度量，但它的代价必须被意识到：逐 token 求集合交集需要在推理路径上同时保留量化前后两套 logits，等于把门控计算做两遍，离线回归可接受，在线监控则要采样。以每层 64 专家的 MoE 为例，单 token 门控 logits 仅数百字节，双份保留的显存代价可忽略，真正的代价是<em>回归吞吐</em>——比对工具跑一遍校准集的时间翻倍。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-3\">三 · 分类维度二：度量口径决定你能否看见漂移</h3>\n<p>三类度量回答三个不同问题。<strong>top-k 一致率</strong>回答“选中的集合是否相同”，是最贴近下游的指标；<strong>专家集合重叠率</strong>（Jaccard 或交集基数）在 k 较大或存在并列分数时比一致率更稳健，因为它不要求名次完全对齐；<strong>排序 Kendall 相关</strong>回答“整体名次是否单调保持”，用于诊断漂移是局部边界抖动还是全局重排。三者不可互相替代：一致率高而 Kendall 低，说明只有边界附近在抖；一致率低而 Kendall 高，说明少数 token 发生了剧烈翻转，往往是离群值饱和的特征。</p>\n<p>口径陷阱在事实中已点明：按全局统计的 top-k 一致率会被头部专家稀释。头部专家承接大量 token，其路由稳定，把整体一致率拉高；长尾专家上的翻转在全局平均里几乎不可见，但特定输入域的质量下降恰恰来自那里。工程做法是<strong>分层统计</strong>：按专家 ID、按 token 来源域、按序列位置分桶计算一致率，并对长尾桶单独设阈值。代价是回归工具需要保留每条样本的路由标签，存储与比对复杂度上升，但这是唯一能避免“工具判定通过而线上回退”的口径。</p>\n<table class=\"mini\"><thead><tr><th>度量</th><th>回答的问题</th><th>主要代价</th><th>典型误用</th></tr></thead><tbody><tr><td>top-k 一致率</td><td>集合是否相同</td><td>需双份 logits，回归吞吐减半</td><td>全局平均掩盖长尾翻转</td></tr><tr><td>专家重叠率</td><td>重叠程度</td><td>需按专家分桶存储</td><td>并列分数下高估稳定性</td></tr><tr><td>Kendall 相关</td><td>名次是否单调</td><td>O(k log k) 排序开销</td><td>与一致率混用导致误判</td></tr></tbody></table>\n\n<h3 id=\"ap-quant-drift-fail-sec-4\">四 · 分类维度三：检测手段与触发条件</h3>\n<p>检测分两条线。<strong>激活离群值扫描</strong>在量化前统计门控输入各通道的最大幅值，与块缩放的可表示上限比较；一旦某块的离群值超出上限，该块内的小值在量化后全部塌缩为零，门控分数排序随之改变，而逐层误差指标可能仍未超阈值——这正是事实中给出的失败模式。触发条件是定性的：离群值超出块缩放可表示范围即告警，不需要等回归失败。<strong>块缩放饱和检测</strong>则直接统计饱和块计数，作为量化格式与门控层精度策略是否匹配的判据。</p>\n<p>第二条线是回归比对。事实明确指出最常见的踩坑：只比对最终 loss 而不比对 top-k 集合，漂移被 loss 的平滑性掩盖。正确做法是把 top-k 一致率、重叠率、饱和计数作为一等回归项，与 loss 并列。领域经验给出的阈值是 top-k 一致率低于约 95%–98% 时输出质量回退风险明显上升——这是经验区间而非材料给定的确定数字，因此工程上应把它当作<em>告警线而非合格线</em>，并结合分桶统计收紧长尾桶的门限。检测的代价是回归流水线变长：每个候选量化配置都要跑一遍双路门控与分桶统计，容量规划时需为回归集群预留算力，否则团队会因回归太慢而退回只看 loss。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-5\">五 · 速查表的列设计与精度策略归类</h3>\n<p>把上述维度固化成表，是让不同人复现同一判断的前提。事实给出的列集合是：量化格式、路由层精度策略、top-k 一致率（量化前后）、专家重叠率、激活离群值比例、块缩放饱和计数、回归比对工具与阈值。这张表的关键在于<strong>“路由层精度策略”必须是显式列</strong>，因为它是唯一能解释其余各列差异的自变量：门控层保持 BF16 而专家走 NVFP4，与门控层一并走 NVFP4，会在同一模型上给出完全不同的漂移画像。</p>\n<p>按精度策略可把配置归为三档：门控全高精度（排序稳定，代价是门控通路无法享受低比特带宽收益）；门控权重量化而激活保持高精度（折中，漂移主要来自权重静态误差）；门控权重与激活同时低比特（漂移风险最高，离群值饱和与 logits 舍入叠加）。第三档正是事实点名的踩坑：将门控层与专家层统一按 NVFP4 量化，门控分数的微小扰动就足以改变 top-k 排序。归类之后，速查表不再是配置清单，而是<em>风险分档表</em>——看到“统一 NVFP4”这一行，就应预期饱和计数非零并强制分桶回归。</p>\n<ul><li>量化格式列回答“用了什么”，精度策略列回答“哪里没用”，二者合起来才定义漂移的来源。</li><li>一致率与重叠率必须成对出现：单看一致率会把并列分数造成的假翻转计入。</li><li>离群值比例与饱和计数是<em>事前</em>指标，可在不跑完整回归的情况下预判风险。</li><li>回归工具与阈值列强制团队写下口径，避免“通过”二字在不同人那里含义不同。</li></ul>\n<p>这张表的运行代价体现在回归频率上：每换一次量化格式或校准集，所有列都要重算，双路门控使单次回归的门控开销翻倍，分桶统计又要求保留路由标签。对 64 专家、数十层的模型，这意味着回归集群的存储与算力需求随配置数线性增长，容量规划时应把回归负载与在线推理负载分开计量，否则量化迭代速度会被回归排队拖住。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-6\">六 · 定义落地的判断顺序</h3>\n<p>面对一次质量回退，判断顺序应是：先看路由层精度策略是否与专家层统一低比特，若是，直接怀疑路由漂移而非专家精度；再看块缩放饱和计数与激活离群值比例，非零即触发离群值扫描；然后用分桶的 top-k 一致率与重叠率确认漂移是否集中在长尾专家或特定输入域；最后才比对逐层误差与 loss。这个顺序把最便宜的静态指标放在最前，把最贵的双路回归放在最后，符合工程上“先用饱和计数筛掉明显不匹配的配置”的直觉。</p>\n<p>需要强调的是，路由漂移的<strong>定义本身就包含下游后果</strong>：仅有排序变化而无质量回退，应记为“路由翻转”而非“漂移失败”。这一区分决定了修复投入——无害翻转可以只记录不修复，而一旦分桶一致率跌破经验区间且对应输入域出现回退，就必须回到门控层精度策略这一自变量上动刀，而不是继续调校准集或块缩放粒度。把定义、维度、度量、检测四件事在条目层面锁死，后续的阈值设定与修复手段才有共同的坐标系。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-7\">七 · 路由漂移的边界条件：何时该判“失效”，而不是“误差略大”</h3>\n<p>把“量化后路由漂移”当作一个可判定的失效模式，而不是泛泛的精度损失，关键在于它满足三个同时成立的条件：漂移发生在<em>排序</em>而非数值幅值上、漂移对象是门控线性层的权重或激活（进而污染路由 logits）、且该漂移在常规逐层误差指标下不可见。这三点把它与相邻概念划开界限：与“权重量化误差”不同，后者可用逐层相对误差直接度量；与“专家层量化回退”不同，后者影响的是被选中专家内部的计算精度，top-k 集合本身不变；与“负载不均导致的专家冷热”不同，后者源于调度与批内分布，而非量化引入的分数扰动。判据可写成集合层面的定义：设量化前路由集合为 \\(S_q=\\mathrm{topk}(g_q(x))\\)、量化后为 \\(S_{\\hat q}=\\mathrm{topk}(g_{\\hat q}(x))\\)，漂移事件即 \\(S_q\\neq S_{\\hat q}\\) 且 \\(|g_q-g_{\\hat q}|\\) 未超过逐层误差阈值——两个条件同时成立才构成“被掩盖的漂移”。</p>\n<p>失效条件的边界由两条机制划定。其一是<strong>块缩放饱和</strong>：激活离群值超出块缩放可表示范围时，该块上限被钉死，块内小值整体塌缩为零，门控分数排序随之改变，而逐层误差指标因块均值被离群值主导而不超阈值——此时检测应转向块缩放饱和计数与激活离群值扫描，而非继续看 loss。其二是<strong>统计口径稀释</strong>：top-k 一致率按全局统计时，长尾专家上的路由翻转会被头部专家的大量一致样本稀释，回归工具判定通过，但特定输入域质量明显下降；因此度量必须落到专家集合重叠率与排序 Kendall 相关上，并按输入域分层统计，而非单一全局一致率。</p>\n<p>系统代价体现在三处：路由层保持高精度（门控权重与激活不进入 NVFP4/FP8）意味着这部分 GEMM 无法享受低比特吞吐，门控层虽小但位于每 token 的关键路径上，其延迟不被专家层的大矩阵乘摊薄；检测本身要付带宽代价，激活离群值扫描与块缩放饱和计数需要在每层插入统计通路，与主计算争抢 HBM 带宽；分层回归则付出离线算力与回归时间。工程上可用一张最小判据表约束放行：</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>触发失效</th><th>代价落点</th></tr></thead><tbody><tr><td>top-k 一致率（分层）</td><td>低于约 95%–98%</td><td>离线回归算力</td></tr><tr><td>块缩放饱和计数</td><td>离群值超出可表示范围</td><td>在线统计带宽</td></tr><tr><td>专家重叠率 / Kendall 相关</td><td>集合翻转但 loss 未动</td><td>门控层高精度 GEMM 延迟</td></tr></tbody></table>\n<p>最常见的越界是把门控层与专家层统一按 NVFP4 量化，并只比对最终 loss：门控分数微小扰动足以改变 top-k 排序，而 loss 对单 token 的路由翻转不敏感，漂移被完全掩盖。判断准则应落在“排序是否稳定”而非“误差是否可接受”上——一旦回归工具只输出 loss 曲线，该方案就已失去对路由漂移的判定能力。</p>\n<h3 id=\"ap-quant-drift-fail-sec-8\">八 · 速查表主表：七列字段与填写口径</h3>\n<p>这张表的设计目标只有一个：让做量化回归的工程师在不读论文的情况下，把一次门控层量化实验的全部证据填进同一行，并据此判定“能不能放行”。七列不是并列的检查项，而是有因果顺序的证据链——格式决定精度策略，精度策略决定一致率与重叠率，离群值与块缩放饱和解释一致率为何掉，回归工具与阈值给出最终裁决。填表时按列从左到右推进，任何一列留空都意味着该行不可判定，不得以“其余指标正常”替代。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>列</th><th>字段</th><th>填写口径</th><th>判定用法</th></tr>\n</thead>\n<tbody>\n<tr><td>1</td><td>量化格式</td><td>门控线性层权重与激活各自的格式，分开写（如权重 NVFP4、激活 FP8），并注明块大小与缩放粒度</td><td>格式不同则一致率不可跨行比较，只在本行内纵向比对量化前后</td></tr>\n<tr><td>2</td><td>路由层精度策略</td><td>门控层是否保持高精度、是否仅权重低比特而激活保高精、logits 是否在 FP32 累加</td><td>策略为空视为默认统一低比特，直接标记高风险</td></tr>\n<tr><td>3</td><td>top-k 一致率</td><td>同一批校准/回归输入上，量化前后 top-k 专家集合完全相同的 token 占比；分母写清是 token 数还是层×token 数</td><td>低于经验区间即触发回退风险告警</td></tr>\n<tr><td>4</td><td>专家重叠率</td><td>量化前后 top-k 集合的交集大小除以 k，按 token 平均；与第 3 列的区别在于它容忍部分重叠</td><td>与第 3 列同时看：一致率低而重叠率高，说明翻转发生在 k 内排序而非集合外</td></tr>\n<tr><td>5</td><td>激活离群值比例</td><td>门控层输入激活中绝对值超出块缩放可表示上限的元素占比，按块统计后汇总</td><td>非零即进入第 6 列核查</td></tr>\n<tr><td>6</td><td>块缩放饱和计数</td><td>缩放因子取到格式上限的块数，以及这些块内被压到零的元素数</td><td>饱和计数大于零即判定块缩放失效，无论第 3 列是否达标</td></tr>\n<tr><td>7</td><td>回归比对工具与阈值</td><td>工具名、比对对象（top-k 集合、logits 排序、逐层误差、最终 loss）、阈值数值</td><td>比对对象必须含 top-k 集合，只比对 loss 的行视为无效回归</td></tr>\n</tbody>\n</table>\n<p>口径上最容易出错的是第 3、4 列的分母。若按“层×token”统计，深层门控层因输入分布更集中往往一致率更高，会把浅层的严重漂移平均掉；若按 token 统计而不分层，长尾专家上的翻转又被头部专家稀释。工程做法是双口径并填：一行给全局 token 口径用于放行判定，另一份分层明细用于定位。第 5、6 列必须来自同一批激活采样，否则离群值比例与饱和计数无法互相解释。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-9\">九 · 阈值带：三档判定与不可协商项</h3>\n<p>材料未给出具体数字，因此表中阈值列写的是区间与判定语义，而不是可以照抄的常数。领域经验把 top-k 一致率划成三段：高于区间上沿视为排序稳定，落进区间内视为需要看第 4 至 6 列的解释性证据，低于区间下沿视为输出质量回退风险明显上升、不得放行。这个区间本身不是精度指标，而是风险分档线，填写时必须连同输入域一起记录——同一模型在不同输入域上的一致率可以差出一个档位。</p>\n<div class=\"formula\">$$\\text{risk}=\\begin{cases}\\text{pass}, &amp; \\text{agree} \\ge a_{\\text{hi}}\\ \\land\\ \\text{sat}=0\\\\ \\text{review}, &amp; a_{\\text{lo}} \\le \\text{agree} &lt; a_{\\text{hi}}\\ \\lor\\ \\text{sat}&gt;0\\\\ \\text{block}, &amp; \\text{agree} &lt; a_{\\text{lo}}\\ \\lor\\ (\\text{sat}&gt;0 \\land \\text{collapse}&gt;0)\\end{cases}$$</div>\n<p>公式里的 sat 是块缩放饱和计数，collapse 是饱和块内被压到零的元素数。三个分支的关键在于：饱和计数大于零时，即使一致率落在 pass 档也强制降为 review，因为块缩放失效是逐层误差指标看不见的失败模式——离群值把缩放上限顶满，块内小值全部塌缩为零，门控分数排序已经改变，而该层的相对误差仍在阈值内。这是本表把第 6 列设为不可协商项的原因：它不参与加权，只做一票降级。</p>\n<p>代价侧要写清三档各自的系统含义。pass 档意味着门控层可以维持低比特，门控 GEMM 的权重带宽按格式位宽折算，路由计算不额外占用高精度通路；review 档通常对应“门控权重低比特、激活保高精”的混合策略，代价是门控层激活以更高位宽驻留，单层激活显存上升，且 GEMM 需走混合精度路径，SM 上的 MMA 吞吐低于纯低比特；block 档则回到门控层整体高精度，代价是这部分权重带宽回到高精度水平，在 MoE 层数占比高的模型上直接体现为解码阶段每 token 的门控读取字节数上升。三档的吞吐差异不在算术峰值，而在门控这一小层的字节搬运与流水线切换开销上——门控层计算量小，却卡在每层注意力和专家 GEMM 之间，它的精度策略改变的是流水线节拍而非单算子效率。</p>\n<p>具体例子：某 MoE 模型门控层权重与激活统一按 NVFP4 量化，全局 top-k 一致率落在区间上沿附近，回归工具判定通过；但分层明细显示浅层一致率明显低于深层，且浅层门控输入的激活离群值比例非零、块缩放饱和计数为正。按本表判定，该行从 pass 降为 review，处置是把门控层激活改回高精度、权重保留低比特，重跑后浅层一致率回到上沿以上、饱和计数归零。若只按全局一致率放行，长尾专家上的路由翻转会被头部专家稀释，特定输入域的质量下降在全局指标上不可见。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-10\">十 · 一致率与重叠率的读法：两种翻转要分开</h3>\n<p>第 3、4 列常被当成同一件事的粗细版本，实际上它们对应两类不同的漂移。top-k 一致率统计的是集合完全相同，专家重叠率统计的是交集占 k 的比例。当一致率下降而重叠率保持高位，说明量化扰动只改变了 k 个专家内部的排序或边界上的一个名额，专家集合基本没动，输出回退通常有限；当两者同时下降，说明有专家被整体换出，这类翻转直接改变 MoE 层的输出组合，回退风险高。读表时先看两列的差，差值大意味着漂移集中在排序层，处置优先级低于集合层漂移。</p>\n<p>排序层面的度量还应补一列 Kendall 相关，用于量化 logits 排序的整体扰动程度。它与一致率的关系可以写成：一致率只采样 top-k 边界，Kendall 相关覆盖全专家排序，两者背离时说明扰动集中在边界附近而非全局。工程上不必把 Kendall 相关放进主表，但应在分层明细里保留，因为它是判断“边界敏感”还是“全局失真”的唯一低成本手段。伪代码思路：对每个 token 取量化前后 logits 向量，算全排序的 Kendall tau，再与 top-k 一致率做散点；散点呈“高 tau、低 agree”的形态即边界敏感，处置是提高门控 logits 的累加精度而非整体回退格式。</p>\n<p>代价上，这两列的统计成本不同。一致率只需 top-k 索引比对，可以在推理框架的回归脚本里随前向一起采集，几乎不增加显存；Kendall 相关需要对全专家 logits 排序，采集时要把门控 logits 落盘或在线排序，显存与带宽开销随专家数上升，通常只在抽样 token 上做。因此主表用一致率与重叠率做全量门控，Kendall 相关做抽样定位，两者分工明确，不要为了“指标齐全”把全排序统计铺到全量回归上，那会让回归本身的吞吐代价超过被回归的推理。</p>\n<p>具体例子：一次 NVFP4 门控量化后，全局一致率达标、重叠率略低，分层明细里某几层出现“一致率下降但重叠率不变”的组合，Kendall 相关仍高。判定为边界敏感型漂移，处置是把门控 logits 的累加改为高精度，权重格式不动，重跑后该层一致率回升而其他层指标不变。若误判为集合层漂移而整体回退门控精度，代价是这部分权重带宽白白回到高精度，收益却只来自累加精度这一项。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-11\">十一 · 离群值与块缩放饱和：检测动作与告警口径</h3>\n<p>第 5、6 列是本表区别于普通精度回归表的地方。激活离群值扫描的动作是：在门控层输入上按块统计绝对值最大值，与当前格式的块缩放可表示上限比较，超出即计入离群值比例；块缩放饱和检测则直接读量化后的缩放因子，统计取到格式上限的块数，并进一步统计这些块内被压到零的元素数。两步必须都做——离群值比例告诉你“有多少块面临风险”，饱和计数告诉你“有多少块已经失效”，前者是预警，后者是事实。</p>\n<p>失效机理可以写成一句话的判据：块内最大值顶满缩放上限后，量化步长被该最大值锁定，块内小值除以步长后落到零，门控分数在这些维度上的微小差异被整体抹平，排序随之改变。这个过程不产生大的逐层相对误差，因为块内最大值本身量化得很准，误差集中在小值上，而小值对 L2 误差贡献小、对排序贡献大。这正是“逐层误差指标未超阈值而路由已漂移”的成因，也是本表要求饱和计数一票降级的原因。</p>\n<p>告警口径要写死三件事：采样批次、块粒度、判定边界。采样批次必须与第 3、4 列同批，否则离群值比例与一致率无法对应；块粒度必须与量化格式的块大小一致，NVFP4 与 FP8 的块划分不同，混用会让饱和计数失真；判定边界是“超出可表示范围即告警”，不设缓冲带，因为饱和是硬失效而非渐变。工程代价上，离群值扫描需要在门控层输入处插入统计钩子，若在推理框架里常驻会带来每层一次归约的开销，通常只在回归与校准阶段开启；饱和检测读的是量化器输出，开销可忽略，可以常驻在量化流水线里作为守门。</p>\n<p>具体例子：门控层激活按 NVFP4 量化，离群值比例非零且集中在少数块，饱和计数为正、塌缩元素数非零；同批 top-k 一致率落在 review 档。按表判定为块缩放失效，处置不是调阈值而是改格式或改块策略——把门控激活移出低比特，或对离群块采用更细的缩放粒度。若只提高一致率阈值来“过滤”这次回归，失效块仍在，换一批输入域就会重新暴露。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-12\">十二 · 回归工具列：比对对象决定这张表是否有效</h3>\n<p>第 7 列不是工具清单，而是比对对象的声明。本表要求回归至少比对三项：top-k 专家集合、门控 logits 排序、最终 loss。三项的敏感度依次递减：集合比对能抓住任何跨边界的翻转，排序比对能抓住 k 内扰动，loss 比对只能抓住已经传导到输出的回退。最常见踩坑正是只比对最终 loss——门控分数的微小扰动在单层上改变 top-k，经过后续层与残差后被平滑，loss 变化落在噪声内，漂移被完全掩盖。因此表中把“比对对象含 top-k 集合”设为该行有效性的前提，缺这一项的回归结果不得作为放行依据。</p>\n<p>工具选型上，回归脚本应直接复用推理框架的前向路径并在门控层挂钩，而不是另建一套离线复现。理由是门控层的数值路径（累加精度、激活量化位置、块缩放应用点）在框架内有具体实现细节，离线复现容易在这些细节上偏离，导致回归通过而线上漂移。代价是回归运行占用与线上相同的显存与批调度资源，吞吐低于纯离线比对，但换来的是比对对象与线上一致。对于大模型，回归通常按输入域抽样而非全量，抽样策略应覆盖长尾专家被激活的输入，否则第 3 列的双口径问题会再次出现。</p>\n<p>阈值填写要与比对对象绑定：集合比对的阈值是一致率区间，排序比对的阈值是 Kendall 相关的下限，loss 比对的阈值是相对回退上限。三者不可互相替代，也不可只填一项。表中建议把三项阈值并列写在同一格里，用分号分隔，任何一项越界即该行不通过。这样做的工程含义是：回归的判定权从“单一 loss 指标”转移到“路由一致性”，与门控层保持高精度的策略形成闭环——策略改变必须同时反映在一致率与饱和计数上，否则策略变更无法被验证。</p>\n<p>具体例子：某次量化把门控层与专家层统一按 NVFP4 处理，回归只比对最终 loss，判定通过；上线后特定输入域质量下降。按本表回填该行，第 7 列因缺少 top-k 集合比对被判无效，第 3 列按分层口径重算后落在 block 档，第 6 列饱和计数为正。处置是把门控层从统一低比特策略中拆出，权重与激活分别定格式，并把 top-k 集合比对加入回归脚本的必填项。这张表的价值不在于给出一个新阈值，而在于把“路由层是否必须保持高精度”从经验判断变成一行可复核的证据链：格式、策略、一致率、重叠率、离群值、饱和计数、比对对象，七列齐备才允许放行。</p>\n<h3 id=\"ap-quant-drift-fail-sec-13\">十三 · 阈值的落点：先定“测什么”，再定“卡多少”</h3>\n<p>路由漂移的工程阈值不能凭空拍一个数，它必须绑定到可复现的测量对象上。门控线性层的权重与激活、路由 logits、top-k 集合三者是三个不同的观测面：权重/激活量化误差是原因侧，logits 排序是中间量，top-k 集合与专家重叠率是结果侧。工程上把阈值挂在结果侧最稳，因为结果侧直接对应输出质量回退，而原因侧的误差指标容易被逐层平均稀释。一个可操作的判定链是：先算量化前后 top-k 一致率与专家集合重叠率，再算 logits 的排序 Kendall 相关，最后才看激活离群值与块缩放饱和计数作为归因证据。顺序不能倒——先看归因指标容易把“块缩放饱和但 top-k 未翻转”的良性情形误判为失败。</p>\n<p>测量方法上，一致率的统计口径必须显式声明。按 token 计的一致率定义为量化前后 top-k 集合完全相同的 token 占比：</p>\n<div class=\"formula\">$$R_{\\text{topk}}=\\frac{1}{N}\\sum_{i=1}^{N}\\mathbf{1}\\{\\,\\mathcal{S}_i^{\\text{fp}}=\\mathcal{S}_i^{\\text{q}}\\,\\}$$</div>\n<p>其中 $\\mathcal{S}_i$ 为第 $i$ 个 token 的 top-k 专家索引集合。这个量对头部专家极度不敏感：若某 token 的 top-k 全落在高频专家上，翻转一个长尾专家仍然计入“不一致”，但若翻转发生在头部专家之间，对输出的扰动反而更大。因此单看 $R_{\\text{topk}}$ 会同时漏掉两类问题，必须配一个按专家加权的版本，把每个专家被选中的次数作为权重，避免长尾翻转被头部稀释。代价上，这个统计本身几乎不花钱——门控层输出是 $[\\text{tokens}\\times \\text{experts}]$ 的小矩阵，一次全量比对在单卡上就是毫秒级，真正的成本在于要跑足够多的、覆盖不同输入域的校准与回归样本，样本覆盖面决定了阈值的可信度，而不是阈值本身。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-14\">十四 · 经验区间与它的适用边界</h3>\n<p>领域经验给出的区间是：top-k 一致率低于约 95%–98% 时，输出质量回退风险明显上升。这个区间要当作“告警带”而非“合格线”来用。95% 附近意味着每二十个 token 就有一个换了专家集合，对稠密激活比例低的 MoE 尚可被后续层吸收；一旦跌到 90% 量级，翻转开始在相邻层间累积，回归比对才会在最终指标上显形——而这正是最常见踩坑的成因：只比对最终 loss，漂移被掩盖到无法定位。工程判断应当是双阈值：98% 作为“关注线”，触发对 logits 排序相关性与离群值的例行扫描；95% 作为“阻断线”，禁止该量化配置进入灰度。两个阈值之间不做自动放行，必须人工看输入域切片。</p>\n<p>区间不能跨配置平移。门控层保持高精度、仅专家层量化的配置，一致率天然靠近上界；把门控层与专家层统一按 NVFP4 量化，微小的分数扰动就足以改变排序，一致率会明显下移，此时 95% 的阻断线对前者过松、对后者过紧。因此阈值表必须按“量化格式 × 路由层精度策略”分桶，每个桶独立标定，而不是全局一个数。代价层面，保持门控高精度意味着门控 GEMM 走 FP8/BF16 而非 NVFP4，门控层在总计算中占比很小，额外显存与带宽开销可忽略，真正的代价是失去门控层与专家层统一量化带来的 kernel 融合机会，需要多一次精度切换与可能的 layout 转换，这在 decode 阶段的小 batch 下会体现为额外的 kernel launch 开销。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-15\">十五 · 离群值与块缩放的失效判据</h3>\n<p>激活离群值导致的块缩放失效有一个干净的判据：离群值超出块缩放可表示范围，即触发告警。NVFP4 的块缩放以块为单位共享一个缩放因子，块内最大值决定缩放上限；当某个激活值远大于同块其余元素，缩放因子被它拉高，块内小值在量化后全部塌缩为零。此时逐层误差指标（如 MSE）可能并未超阈值，因为误差被大值主导，而门控分数排序已经改变——这正是“指标未超阈值但排序翻转”的隐蔽失败模式。检测手段是块缩放饱和计数：统计每个块内缩放因子达到格式可表示上限的次数，以及块内非零元素塌缩比例。</p>\n<ul>\n<li>饱和计数按层、按块位置聚合，定位到具体是哪些通道持续饱和，而不是只看全局均值。</li>\n<li>塌缩比例与 top-k 一致率做联合判据：饱和计数上升但一致率未动，属于可容忍；两者同向恶化，直接判定该层不适合低比特。</li>\n<li>离群值扫描应在校准数据与线上采样两条流上分别跑，前者定配置，后者做漂移监控。</li>\n</ul>\n<p>系统代价在这里体现为监控开销与重算成本：块缩放饱和计数需要保留量化前的块级统计，等于在量化 kernel 里多一次 reduction 与一次写出，对带宽敏感的解码阶段是实打实的额外读写；若判定某层必须回退到高精度，重算该层的门控 GEMM 会打断融合流水，prefill 阶段影响小，decode 阶段的小 batch 下单位 token 的延迟抬升更明显。工程上通常把饱和检测做成离线校准的一次性产物加线上的低频采样，而不是每步都算。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-16\">十六 · 回归工具与切片口径</h3>\n<p>回归比对工具的选择决定了阈值能否落地。只比对最终 loss 的工具无法承担路由一致性回归，因为它对 top-k 集合翻转不敏感；可用的工具链需要输出三件东西：逐层 top-k 一致率、按专家加权的重叠率、以及按输入域切片的指标。切片是关键词——全局统计会把长尾专家上的路由翻转稀释掉，回归工具判定通过，但特定输入域质量明显下降。切片口径至少按任务类型、序列长度分桶、语言/领域分桶三层展开，每层单独设阈值，任一桶跌破阻断线即整体不通过。</p>\n<table class=\"mini\"><thead><tr><th>观测面</th><th>指标</th><th>判据形态</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>结果侧</td><td>top-k 一致率、专家重叠率</td><td>双阈值 98%/95%，分桶标定</td><td>回归样本覆盖面</td></tr>\n<tr><td>中间量</td><td>logits 排序 Kendall 相关</td><td>与一致率联合看，单独不作阻断</td><td>门控全量输出留存</td></tr>\n<tr><td>原因侧</td><td>激活离群值比例、块缩放饱和计数</td><td>饱和即告警，配塌缩比例</td><td>量化 kernel 额外 reduction 与写出</td></tr>\n</tbody></table>\n<p>伪代码层面的判定顺序可以写成：对每个切片桶，若 $R_{\\text{topk}}&lt;0.95$ 则阻断；否则若 $R_{\\text{topk}}&lt;0.98$ 且饱和计数较基线上升，则进入人工复核；否则放行。这个顺序把最贵的归因分析放在最少见的路径上，控制了回归流水线的总算力开销。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-17\">十七 · 没有数字时怎么测：可复现的标定流程</h3>\n<p>材料未给出具体数字的地方，不能靠“大概”糊过去，而应给出可复现的标定流程，让每个部署方在自己的模型与流量上产出数字。流程分四步：第一步，固定校准集与回归集，回归集必须包含长尾专家被激活的输入域，否则一致率统计天然偏高；第二步，对门控层单独做量化前后比对，产出逐层一致率与排序相关，作为该模型的路由敏感度基线；第三步，扫描块缩放饱和，把饱和通道与一致率下降的层做交集，交集非空即说明该层的失败由离群值驱动，应优先考虑门控高精度或对离群通道做保护；第四步，在灰度流量上以低频采样复算一致率，观察其随输入分布漂移的变化，把线上采样的一致率与离线基线之差作为漂移告警量。</p>\n<p>这套流程的成本主要是回归集的构造与留存，而非计算。工程判断上，宁可把回归集做窄做深（覆盖长尾专家与极端序列长度），也不要用一个巨大的通用集换一个好看但失敏的全局一致率。阈值最终是“模型 × 量化格式 × 路由精度策略 × 输入域”四维的函数，任何把它压成单一数字的做法，都会在长尾输入上付出质量代价。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-18\">十八 · 阈值落地的三重盲区：全局一致率、块缩放饱和与长尾稀释</h3>\n\n<p>把 top-k 一致率当作唯一闸门是这套方案最先失效的地方。一致率按全局 token 统计时，头部专家承载绝大多数路由命中，长尾专家上的翻转被稀释进分母：设头部 k 个专家覆盖比例为 <i>p</i>，长尾翻转率为 <i>r</i><sub>tail</sub>，则全局一致率近似为 1 − (1−<i>p</i>)·<i>r</i><sub>tail</sub>，当 <i>p</i> 接近 1 时该指标对长尾漂移几乎不敏感，回归工具判定通过而特定输入域质量明显下降。工程上必须把一致率拆成两层：全局值用于粗筛，分专家桶的一致率与专家集合重叠率用于定位；对长尾专家单独设更严的阈值，并在回归比对中固定一组覆盖长尾触发条件的探针 prompt，而不是只比对最终 loss。</p>\n\n<div class=\"formula\">$$ \\text{overlap}=\\frac{1}{N}\\sum_{i=1}^{N}\\frac{|S_i^{\\text{fp}}\\cap S_i^{\\text{q}}|}{k},\\qquad \\text{flag}=\\mathbb{1}\\big[\\text{overlap}&lt;\\tau_{\\text{head}}\\big]\\ \\lor\\ \\mathbb{1}\\big[\\text{overlap}_{\\text{tail}}&lt;\\tau_{\\text{tail}}\\big] $$</div>\n\n<p>第二个盲区在块缩放的表示边界。NVFP4 的块缩放把一组元素压到共享指数上，激活离群值一旦超出该块缩放可表示范围即触发饱和，块内小值全部塌缩为零——此时门控分数排序已经改变，但逐层相对误差指标可能仍未越过阈值，因为误差被少数大值主导。检测手段不能只看层误差，要直接扫描激活离群值比例并统计块缩放饱和计数：把每个块的 max|x| 与缩放上限比较，饱和块占比超过经验线即告警，并回退该层到 FP8 或保持高精度。这条路径的系统代价是显存的：门控层与路由 logits 保持高精度意味着这部分权重与激活不参与低比特压缩，在 KV cache 与专家权重已经吃满显存的配置下，路由层的精度预算必须提前在容量规划里留出，否则只能靠降低并发批来换。</p>\n\n<table class=\"mini\"><thead><tr><th>观测项</th><th>测量方法</th><th>触发动作</th></tr></thead><tbody><tr><td>全局 top-k 一致率</td><td>量化前后同批 token 逐层比对 top-k 集合</td><td>低于经验区间下沿即阻断上线</td></tr><tr><td>分专家桶重叠率</td><td>按专家命中数分桶统计集合重叠</td><td>长尾桶单独设更严阈值</td></tr><tr><td>激活离群值比例</td><td>逐块统计超出缩放上限的元素占比</td><td>超限即块缩放失效告警</td></tr><tr><td>块缩放饱和计数</td><td>统计饱和块数与总块数之比</td><td>回退该层精度或改缩放粒度</td></tr></tbody></table>\n\n<p>第三个盲区是阈值本身的来源。材料未给出具体数字，领域经验是 top-k 一致率低于约 95%–98% 时输出质量回退风险明显上升，这个区间只能作为起点而非验收线：它没有区分模型规模、专家数量与输入域分布。可行的测量方法是构造分层探针集——按任务类型与序列长度分桶，每桶内固定采样，量化前后各跑一遍，同时记录一致率、重叠率、排序 Kendall 相关与端到端质量指标，用质量指标出现可复现回退的那一档一致率反推本模型的阈值，而不是照搬通用区间。代价落在回归时间上：分层探针集意味着回归吞吐下降、单轮验证拉长，在持续集成的推理流水线里要把这项开销计入发布节奏，否则团队会为了赶版本而退回只比对 loss 的旧做法，漂移重新被掩盖。</p>\n<h3 id=\"ap-quant-drift-fail-sec-19\">十九 · 踩坑清单：门控层被统一量化</h3>\n<p>最普遍的一类事故，是把门控线性层和专家层放进同一套 NVFP4 量化配置里，图省事共用一份校准缓存与块缩放。门控层的输出是路由 logits，它不承担表征学习，只承担排序；排序对扰动的敏感度远高于数值本身。NVFP4 的块缩放把一组权重/激活压到同一尺度上，门控分数上零点几个百分点的偏移就足以让 top-2 与 top-3 交换位置。专家层被量化后单专家输出略有偏差，但路由不变时误差是局部且可补偿的；门控被量化后路由改变，误差变成结构性——选错了专家，后续所有计算都在错误的子空间里进行。</p>\n<p>代价体现在三个维度上：质量上，被换掉的专家往往在特定输入域承担关键能力，回退是域相关的而非均匀的；显存上，门控层参数量相对专家层极小，把它保持在 FP8 或 BF16 几乎不增加占用，却省掉了整条漂移链路；延迟上，门控是每 token 必经的关键路径，高精度门控的额外算力开销远小于一次错误路由带来的专家负载倾斜与尾延迟放大。工程判断很直接：门控层精度策略应当独立于专家层配置，作为单独一项写进量化 recipe，而不是继承全局默认。</p>\n<div class=\"formula\">$$\\text{route}(x)=\\text{top-}k\\big(\\text{softmax}(W_g x)\\big),\\quad \\hat{W}_g=\\text{Quant}(W_g)\\ \\Rightarrow\\ \\text{rank}(\\hat{W}_g x)\\neq\\text{rank}(W_g x)$$</div>\n<p>具体例子：一个 8 选 2 的 MoE 层，某 token 的原始 logits 为 [3.02, 2.98, 2.95, …]，前两名差距 0.04。NVFP4 量化后该 token 的激活落在一个块缩放偏小的块内，三个分数被压到同一量化格点附近，排序翻转，top-1 变成原本的第三名。逐层误差指标看不出异常，因为三个专家的输出范数接近；只有比对 top-k 集合才能发现这次翻转。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-20\">二十 · 踩坑清单：回归只比对 loss 不比对集合</h3>\n<p>第二类坑在验证环节：量化回归流水线只跑最终 loss 或 perplexity 比对，判定“差异在容差内”即放行。loss 是全局平均量，路由漂移在平均意义上被稀释——大量 token 的路由不变，少数 token 翻转，平均损失只抬升一点点，落在容差内。但推理系统的质量评估不是平均值问题：特定输入域（长尾语言、代码、结构化字段）的路由翻转率可能远高于全局，这些域的生成质量下降不会体现在聚合指标上。</p>\n<p>正确的回归必须同时产出集合级指标：top-k 一致率、专家集合重叠率、排序 Kendall 相关，并按输入域切片统计。检查顺序上，先做集合级比对定位翻转，再做 loss 比对确认影响幅度，顺序反了就会用聚合指标掩盖结构性变化。代价是回归时间变长——集合级比对需要对每个 token 保存量化前后的路由结果，显存与落盘开销上升，但相比线上质量事故的回滚成本，这个开销可以接受。</p>\n<ul>\n<li>top-k 一致率：量化前后 top-k 集合完全相同的 token 占比，低于经验区间即告警。</li>\n<li>专家集合重叠率：按专家维度统计被选中的交集比例，用于发现长尾专家被系统性挤出。</li>\n<li>排序 Kendall 相关：捕捉 top-k 内部顺序变化，对 top-1 翻转敏感。</li>\n</ul>\n<p>具体例子：某模型全局 top-k 一致率为 97%，看似达标；按域切片后发现代码域的 top-k 一致率明显偏低，翻转集中在少数处理标识符与缩进的专家上。全局数字被头部自然语言 token 稀释，这正是“回归工具判定通过但特定输入域质量明显下降”的机制。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-21\">二十一 · 踩坑清单：块缩放饱和被逐层误差掩盖</h3>\n<p>第三类坑最隐蔽：激活离群值把块缩放的上限顶满，量化后该块内的小值全部塌缩为零。NVFP4 的块缩放是每块一个共享指数，块内动态范围由最大值决定；一个远大于同伴的离群值会把缩放因子推到可表示范围的边缘，块内其余元素落到最低量化格点以下，直接归零。门控分数由这些元素线性组合而成，小值塌缩等价于丢掉了一批弱但决定排序的贡献项，排序随之改变。而逐层相对误差指标按整层统计，离群值本身量化误差不大，小值塌缩的绝对误差也小，指标不超阈值。</p>\n<div class=\"formula\">$$s_b=\\frac{\\max_{i\\in b}|x_i|}{q_{\\max}},\\quad |x_i|&lt;s_b\\cdot q_{\\min}\\ \\Rightarrow\\ \\hat{x}_i=0$$</div>\n<p>检测手段是独立的：激活离群值扫描统计每块最大值与块内中位数的比值，块缩放饱和检测统计缩放因子触顶的块数。这两个计数必须作为量化 recipe 的准入条件，而不是事后排查项。代价是校准阶段要多跑一遍扫描，且扫描本身要覆盖真实推理分布而非训练分布——推理时的激活分布与校准集不一致，是饱和漏检的常见来源。</p>\n<p>具体例子：某门控层某块内出现一个幅度远超同伴的激活，块缩放触顶，同块内十余个小值归零，该 token 的 top-2 分数由原本的第二、第三名竞争变为第一名独大，top-1 不变但 top-2 翻转。逐层误差指标正常，集合级比对才暴露这次翻转，而饱和计数在扫描阶段就已给出预警。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-22\">二十二 · 检查顺序：从数据到集合到端到端</h3>\n<p>检查顺序决定排查效率。合理的顺序是：先查校准数据与激活分布是否匹配推理分布，再查块缩放饱和计数与离群值比例，再查门控层精度策略是否独立，最后才做集合级回归与端到端质量比对。理由在于前三级是因果上游：校准分布不匹配会让饱和检测失真，饱和会让集合指标劣化，门控精度策略错误会让集合指标全面劣化。跳过上游直接看集合指标，只能看到症状，无法定位机制。</p>\n<table class=\"mini\"><thead><tr><th>顺序</th><th>检查项</th><th>失败信号</th><th>系统代价</th></tr></thead><tbody>\n<tr><td>1</td><td>校准/推理分布匹配</td><td>饱和计数在校准集为零、线上非零</td><td>校准重跑，显存与时间</td></tr>\n<tr><td>2</td><td>离群值比例与块缩放饱和计数</td><td>缩放因子触顶块数上升</td><td>扫描开销，需覆盖长尾输入</td></tr>\n<tr><td>3</td><td>门控层精度策略</td><td>门控与专家共用 NVFP4 配置</td><td>门控高精度带来的关键路径算力</td></tr>\n<tr><td>4</td><td>top-k 一致率/重叠率/Kendall</td><td>全局达标但分域切片偏低</td><td>逐 token 路由落盘与比对时间</td></tr>\n<tr><td>5</td><td>端到端质量与尾延迟</td><td>特定域质量下降、专家负载倾斜</td><td>线上回滚与容量重排</td></tr>\n</tbody></table>\n<p>每一级都应设准入条件而非参考项。特别是第 2 级：饱和计数是布尔式信号，一旦触发就应阻断发布，而不是与集合指标加权平均。工程上把饱和计数做成量化产物的元数据，随权重一起入库，推理框架加载时可直接读取并拒绝加载饱和超限的产物，这比事后回归更省事。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-23\">二十三 · 回滚方案：分层回滚而非整体回退</h3>\n<p>漂移事故发生后，整体回退到上一版高精度权重是最省事的做法，但代价最大：显存占用回升、吞吐下降，且丢失了其他层量化带来的收益。分层回滚把门控层单独恢复为高精度，专家层保留低比特，通常就能消除漂移——因为漂移的因果链起点是门控排序。分层回滚需要量化产物按层可寻址，权重文件按门控/专家分组存放，推理框架支持混合精度加载。这要求量化 recipe 在设计阶段就把门控层标记为独立精度组，而不是事后拆分。</p>\n<p>回滚的触发条件应分级：饱和计数触发时回滚门控层精度；集合级指标分域切片劣化时回滚对应层的量化配置；端到端质量事故时整体回退并冻结该 recipe。分级的好处是回滚粒度与事故根因对齐，避免用整体回退处理局部问题。代价是运维复杂度上升——需要维护多套精度组合的产物与对应的回归基线，但相比每次事故都整体回退，分层方案在长期容量规划上更可控。</p>\n<p>具体例子：线上发现代码域生成质量下降，集合级比对定位到门控层 top-2 翻转集中在少数专家。回滚动作是把门控层从 NVFP4 切回 FP8，专家层不动，显存增量仅门控层参数量，吞吐几乎不变，代码域质量恢复。整个过程不需要重新量化专家层，也不需要重跑全量校准。</p>\n<p>回滚方案的最后一道保险是把门控层精度策略写进推理框架的加载校验：加载时读取产物元数据中的门控精度标记，若与框架配置的期望精度不符则拒绝启动并给出明确错误，而不是静默按低精度运行。这样漂移从“运行期质量事故”变成“加载期配置错误”，排查成本下降一个量级。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-24\">二十四 · 路由漂移回归的失效边界与检查顺序</h3>\n<p>这套检查清单的适用边界要先划清：它只能捕获“门控分数排序发生可观测变化”的漂移，对两类失效是盲的。第一类是块缩放饱和型失效——激活离群值把某个块的缩放因子顶到可表示上限，块内小值整体塌缩为零，门控 logits 的排序随之改变，但逐层相对误差指标仍落在阈值内，因为误差被少数大值摊平了。第二类是长尾稀释型失效——top-k 一致率按全局 token 统计时，头部专家上的路由翻转被海量正常 token 稀释，回归工具判定通过，而特定输入域（长尾专家承载的那部分）质量已明显下降。因此检查顺序必须是：先做激活离群值扫描与块缩放饱和计数（定位第一类），再做分域、分专家的 top-k 一致率切片（定位第二类），最后才看全局一致率与输出比对。反过来做，等于用聚合指标给局部失效发通行证。</p>\n<p>分域一致率的代价要算清楚。设全局一致率为 $\\bar{r}=\\sum_g w_g r_g$，其中 $w_g$ 为第 $g$ 个输入域或专家簇的 token 占比、$r_g$ 为其一致率，则全局指标对最小簇的敏感度被 $w_g$ 压制：一个占比 2% 的域整体翻转，全局一致率只掉约 0.02，远低于 95%–98% 的经验告警线。工程上必须按专家簇与输入域分别统计并取最小值作为门禁，代价是回归工具要保留逐 token 的路由标签、按域聚合，单次回归的存储与比对开销随域数线性增长；若域划分过细，还会引入统计噪声导致的误报，需要设定每域最小样本量。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>块缩放饱和计数</td><td>离群值超出块缩放可表示范围即告警</td><td>需在前向中插桩，增加校准与回归时长</td></tr><tr><td>分域 top-k 一致率</td><td>任一域低于 95%–98% 经验线</td><td>保留逐 token 路由标签，存储与聚合开销上升</td></tr><tr><td>门控层精度策略</td><td>门控与专家统一 NVFP4</td><td>排序不稳，需回滚门控至更高精度，牺牲门控层吞吐</td></tr></tbody></table>\n<p>回滚方案的关键是粒度而非开关。门控线性层权重与激活应独立于专家层配置精度，回滚时只把门控恢复高精度、专家层保留 NVFP4，这样显存增量仅限门控参数与其激活，吞吐损失集中在路由计算这一小段，而不是整层退回 FP8 把量化收益全部让出。回滚触发条件写成硬门禁：块缩放饱和计数非零、任一分域一致率跌破经验线、专家集合重叠率异常下降，三者任一命中即回滚，不做加权折中。最常被踩的坑正是把门控与专家统一按 NVFP4 量化、回归只比对最终 loss——排序扰动被 loss 的平均效应掩盖，漂移直到上线后才在特定输入域暴露。</p>\n<h3 id=\"ap-quant-drift-fail-sec-25\">二十五 · 上游依赖：门控精度策略与量化格式选择</h3>\n<p>路由漂移条目在全书量化链路中处于“下游验收”位置，它的判定输入全部来自上游两个决定：门控层是否被纳入低比特量化、以及块缩放粒度如何设定。上游若把门控线性层与专家层统一按 NVFP4 处理，本条目所描述的排序扰动就成为必然结果而非偶发缺陷——门控 logits 的数值分辨率被压缩后，top-k 边界附近的专家分数差落入量化步长之内，排序翻转在数学上不可避免。因此本条目对上游的依赖不是“建议”，而是硬约束：路由层保持高精度（FP8 或 BF16）是稳定排序的前提，NVFP4 只应施加于专家权重与激活。</p>\n<p>第二个上游依赖是块缩放的表示范围。块缩放失效的根因在上游校准阶段就已埋下：若校准数据未覆盖某输入域的激活离群值，块缩放上限在推理时饱和，该块内小值塌缩为零，门控分数排序改变而逐层误差指标不超阈值。本条目要求的激活离群值扫描与块缩放饱和计数，本质上是对上游校准数据管线（见该条目）的验收指标回灌——漂移检测发现的饱和块，必须回溯到校准样本的覆盖缺口。</p>\n<div class=\"formula\">$$\\text{top-k 一致率} = \\frac{1}{N}\\sum_{i=1}^{N}\\frac{|S_i^{\\text{fp}}\\cap S_i^{\\text{q}}|}{k},\\quad S_i=\\text{top-}k(\\text{logits}_i)$$</div>\n<p>该指标的计算依赖上游提供量化前后两份门控 logits，工程代价在于需要保留一份高精度门控旁路用于比对，显存开销为门控层参数与激活的额外一份副本；对 GB200 NVL72 这类显存带宽紧张的部署，旁路门控应只在回归阶段开启，生产路径不常驻。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-26\">二十六 · 下游影响：容量因子、尾延迟与丢弃代价</h3>\n<p>路由漂移一旦发生，其代价不会停留在质量指标上，而会沿推理系统的调度链路放大。top-k 集合变化直接改变每个专家的令牌负载分布：原本均衡的分配可能因排序翻转而向某几个专家集中，容量因子（见该条目）按量化前的负载统计设定时，量化后出现超额令牌被丢弃，丢弃代价从“可忽略”变为“可观测”。更隐蔽的是长尾专家上的路由翻转——全局 top-k 一致率被头部专家稀释后仍显示达标，但特定输入域的质量下降在尾延迟上表现为该域请求的专家集合频繁变动，破坏专家并行 All-to-All 的通信模式稳定性。</p>\n<p>对分离式预填/解码（见该条目）而言，漂移的下游影响体现在预填阶段的门控计算与解码阶段的专家选择不一致：预填用高精度门控生成 KV，解码若走量化门控，同一上下文在不同阶段的 top-k 可能不同，KV 压缩策略（见 MoE 场景 KV 压缩条目）所假设的专家访问模式失效。工程判断是：门控精度策略必须在预填与解码两侧保持一致，否则漂移检测的基线本身不成立。</p>\n<table class=\"mini\"><thead><tr><th>漂移表现</th><th>下游系统代价</th><th>触发条件</th></tr></thead><tbody><tr><td>头部专家负载集中</td><td>容量因子溢出、令牌丢弃</td><td>排序翻转偏向高频专家</td></tr><tr><td>长尾专家翻转</td><td>特定输入域尾延迟上升</td><td>全局一致率达标但分域未测</td></tr><tr><td>预填/解码门控不一致</td><td>KV 访问模式失配</td><td>两侧精度策略不同</td></tr></tbody></table>\n\n<h3 id=\"ap-quant-drift-fail-sec-27\">二十七 · 度量口径的上下游对齐</h3>\n<p>本条目给出的三类度量——top-k 一致率、专家集合重叠率、排序 Kendall 相关——必须与上游量化配置和下游 SLO 口径对齐才有意义。上游若只报告逐层量化误差，无法回答“排序是否改变”；下游若只比对最终 loss，漂移被掩盖，因为 loss 对少量令牌的专家错选不敏感。工程做法是把一致率指标嵌入回归比对工具（见 MoE 剖析工具链条目）的必检项，并强制按输入域分桶统计，避免全局统计稀释长尾翻转。</p>\n<p>Kendall 相关的价值在于捕捉“集合未变但排序变了”的情形：top-k 集合相同而内部次序变化，在容量因子紧的调度下仍可能改变专家处理顺序与批内分组，进而影响分组 GEMM 的合并效率（见该条目）。代价是 Kendall 计算需要完整 logits 而非仅 top-k 索引，回归阶段的采样规模与计算开销高于一致率统计，应作为抽检项而非全量项。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-28\">二十八 · 在全书中的位置：量化失败模式的验收端点</h3>\n<p>把全书量化相关条目串起来看，路由漂移是唯一一个以“排序正确性”而非“数值误差”为判据的失败模式。NVFP4/FP8 权重激活条目讲的是表示能力与吞吐收益，量化校准数据管线讲的是覆盖度，本条目则是这两者的联合验收：校准覆盖不足会在块缩放饱和上暴露，表示能力不足会在 top-k 一致率上暴露。它因此位于量化章节的末端，作为放行低比特 MoE 推理前的最后一道门。</p>\n<p>与路由倾斜尾延迟条目的关系是互补而非重叠：后者处理的是负载分布本身的不均，本条目处理的是量化引入的分布偏移。两者共用容量因子这一调度参数，但修正手段不同——倾斜靠调度与冗余专家，漂移靠精度策略与校准回灌。工程上若两者同时出现，应先修漂移再调容量，否则容量参数会被漂移造成的伪倾斜误导。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-29\">二十九 · 放行判断：把漂移检测写成可执行的回归门</h3>\n<p>本条目对全书的贡献最终落在一个可执行判断上：低比特 MoE 推理的放行条件不是“逐层误差低于阈值”，而是“分域 top-k 一致率达标且无块缩放饱和块”。伪代码思路为：对每个输入域桶，取量化前后门控 logits，计算一致率与重叠率；扫描激活离群值比例与饱和计数；任一桶一致率跌破经验区间（约 95%–98%）或饱和计数非零，即拒绝放行并回溯校准样本。该门的运行代价是回归阶段的一次双路门控前向，显存与算力开销可控，但要求回归工具保留高精度门控副本——这是上游精度策略必须允许的旁路。</p>\n<p>最终工程判断落在门控层的精度预算上：把门控保持在 FP8 以上所付出的显存与带宽代价，远小于漂移导致的丢弃、尾延迟与分域质量回退的联合代价；在 Blackwell 上，门控层参数量相对专家层可忽略，这一预算几乎不影响 NVFP4 带来的整体收益。漂移检测因此不是可选项，而是低比特 MoE 推理在容量规划与 SLO 承诺之间的必要校准点。</p>\n\n<h3 id=\"ap-quant-drift-fail-sec-30\">三十 · 边界条件：路由漂移在什么系统形态下才真正致命</h3>\n<p>路由漂移并非在所有推理形态中等价。它的危害被三个系统变量放大：批内序列的异构度、专家并行的通信拓扑、以及解码阶段的步间连续性。连续批处理把不同长度、不同领域的请求拼进同一 micro-batch，门控层面对的是分布被强行混合后的激活；此时量化引入的排序扰动不再只影响单条序列，而会通过 top-k 集合变化改变整个 batch 的 all-to-all 通信模式——专家集合一变，token 要去的目标 rank 就变，NCCL 集合通信的分片边界随之抖动，EP 并行下的负载均衡被破坏。反过来，在固定 shape、单一领域的离线批推理里，路由分布高度集中，漂移往往被头部专家的稳定选择掩盖，回归工具容易放行。判断边界的第一条工程准则：**路由漂移的风险等级与 batch 内领域熵成正比，与 top-k 集合的稳定性成反比**。用公式表达为漂移敏感度</p>\n<div class=\"formula\">$$S=\\frac{H(\\text{domain})}{1-\\text{TopKAgree}}\\cdot\\frac{k}{N_{\\text{exp}}}$$</div>\n<p>其中 H 为批内领域分布熵，TopKAgree 为量化前后 top-k 一致率，k 为激活专家数，N_exp 为专家总数。S 越大，同一份量化配置在容量规划中需要预留的专家负载不均衡裕度越高，直接代价是 EP 组内最热 rank 的显存与带宽成为瓶颈，而平均利用率被拉低。</p>\n<p>第二个边界是失效条件的隐蔽性。激活离群值触发块缩放饱和时，块内小值整体塌缩为零，门控分数排序改变，但逐层相对误差指标可能仍落在阈值内——因为误差被少数大值主导，MSE 类指标看不见小值的集体丢失。这类失效在 NVFP4 的块缩放粒度下尤其难查：块上限被离群值顶满，缩放因子饱和计数是唯一可靠的早期信号。检测逻辑应写成对每个门控线性层输出块的扫描伪代码思路：对每块求 max|a|，若 max|a| 超过该格式缩放可表示上限即计数加一，并把该块标记为“排序不可信”；累计饱和计数超过块总数的给定比例，就拒绝该层的低比特方案，回退到 FP8 或 BF16 门控。这里的系统代价是显存：门控层保持高精度意味着这部分权重与激活不参与 4 bit 压缩，在 GB200 NVL72 这种显存按 rank 切分的部署里，门控层虽小但每层都存在，累计占用会挤压 KV cache 的分配空间，容量规划时必须把“路由层高精度预算”作为独立科目列出，而不是并入专家权重的量化收益里。</p>\n<p>第三个边界是度量口径本身造成的假阴性。按全局统计的 top-k 一致率会被头部专家稀释：长尾专家上的路由翻转在总量中占比极小，回归工具判定通过，但特定输入域的质量明显下降。工程上必须把一致率拆成按专家分桶的条件一致率，并对长尾桶单独设阈值；同时用专家集合重叠率与排序 Kendall 相关作为交叉验证，三者同时达标才允许放行。这带来回归流水线的时间代价：分桶统计需要对每个校准集子域单独跑前向并记录路由 logits，回归耗时随子域数量线性增长，在模型迭代频繁的流水线里会成为发布节奏的瓶颈，因此通常只在门控层配置变更时触发全量分桶回归，日常迭代走抽样。</p>\n<table class=\"mini\"><thead><tr><th>系统形态</th><th>漂移可见性</th><th>主要代价科目</th><th>建议门控精度策略</th></tr></thead><tbody><tr><td>单域离线批推理</td><td>低（头部专家掩盖）</td><td>吞吐</td><td>可试低比特，需分桶回归</td></tr><tr><td>多域连续批处理</td><td>高（批内熵大）</td><td>EP 负载均衡、通信</td><td>门控保持 FP8/BF16</td></tr><tr><td>投机解码</td><td>高（步间路由翻转）</td><td>接受率、验证开销</td><td>门控高精度，草稿模型单独校准</td></tr><tr><td>分离式预填/解码</td><td>中（两阶段分布不同）</td><td>KV 传输、显存</td><td>两阶段分别做一致率回归</td></tr></tbody></table>\n<p>在全书结构中，本条目处在“数值精度”与“批调度/并行通信”的交叉位置：向上它依赖 NVFP4/FP8 的块缩放机制与 tcgen05 的数值路径，向下它约束连续批处理的专家负载模型、EP 并行的 all-to-all 分片策略，以及投机解码中草稿与验证两阶段的路由一致性。最容易被忽略的下游影响在投机解码：草稿模型与主模型若采用不同的门控量化策略，步间 top-k 集合的翻转会直接压低接受率，而接受率的下降又被误归因为草稿模型能力不足。因此路由一致率必须作为跨条目共享的回归指标，在量化配置、批调度策略、并行拓扑任一变更时同步复测，而不是留在单一量化条目的验收清单里。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-quant-drift-fail\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>低比特量化改变门控分数排序，造成专家选择变化与输出质量回退</td></tr><tr><td>关键点</td><td>需说明路由层保持高精度的必要性、量化前后 top-k 一致率指标、以及激活离群值导致的块缩放失效检测方法。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-quant-drift-fail · 共 5 个片段</p>\n"},{"id":"ap-comm-deadlock-fail","title":"通信计算死锁","summary":"All-to-All 与分组 GEMM 重叠时因 SM 占用与流同步顺序不当引发死锁或长尾，表现为吞吐骤降与 NCCL 超时；需给出流优先级、通信 SM 配额、CUDA Graph 下同步点重排的排查清单。","kind":"失败模式","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-1\">一 · 条目边界：什么算通信计算死锁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-2\">二 · 分类维度一：按触发位置划分的四类</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-3\">三 · 分类维度二：按可观测信号与根因定位项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-4\">四 · 与“重叠优化”的区别：重叠率不是越高越好</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-5\">五 · 与 CUDA Graph、流优先级的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-6\">六 · 分类的工程用法：一张表决定排查路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-7\">七 · 边界条件：什么才算死锁，什么只是慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-8\">八 · 速查表的结构与口径约定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-9\">九 · 阈值与判定口径：哪些量必须采、采到什么程度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-10\">十 · 根因定位项：三个旋钮的检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-11\">十一 · CUDA Graph 型：捕获方式与回放口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-12\">十二 · 缓解动作与回归验证的配对原则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-13\">十三 · 表的边界：哪些情况不进这张表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-14\">十四 · 速查表：边界、失效条件与系统代价的对照口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-15\">十五 · 超时窗口：把“挂死”翻译成可判定的时间量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-16\">十六 · 通信 SM 配额：按比例预留，按实测收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-17\">十七 · 流数量与优先级：用事件图而不是直觉来定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-18\">十八 · CUDA Graph 下的同步点：重排的度量方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-19\">十九 · 跨节点联调：只在目标拓扑上采信数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-20\">二十 · 阈值从哪来：三类可测量与一条判死锁的不等式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-21\">二十一 · 踩坑清单：四类失败模式的可观测指纹</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-22\">二十二 · 检查顺序：从最便宜的证据开始</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-23\">二十三 · 回滚方案：分级降级而非一键回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-24\">二十四 · 静态配置项：最容易被忽略的三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-25\">二十五 · 长尾与 SLO 的耦合：死锁的第二种代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-26\">二十六 · 踩坑清单与回滚：从“假重叠”到配额失守的边界判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-27\">二十七 · 上游依赖：死锁条目承接的四类前置知识</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-28\">二十八 · 下游影响：死锁判定如何改变容量规划与 SLO 口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-29\">二十九 · 全书位置：介于算子条目与系统条目之间的编排层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-30\">三十 · 与相邻条目的边界划分：谁讲什么，避免重复</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-31\">三十一 · 依赖失效时的连锁反应：上游条目出错如何放大死锁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-comm-deadlock-fail-sec-32\">三十二 · 本条目在全书中承担的判断职责</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-comm-deadlock-fail\"><svg style=\"max-width:504px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 504.4 357\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"422.4\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：通信计算死锁</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">All-to-All 与分组 GEMM 重叠时因 SM 占用与流同步顺序不当引</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"422.4\" height=\"83.0\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"162.6\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"166.8\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><text x=\"75.0\" y=\"171.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">需给出流优先级、通信 SM 配额、CUDA Graph 下同步点重排的排</text><text x=\"75.0\" y=\"187.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">查清单。</text><line x1=\"82.0\" y1=\"206.1\" x2=\"82.0\" y2=\"223.1\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 222.1 L 86.5 222.1 L 82.0 230.1 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"230.1\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"252.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"256.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"257.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"276.9\" x2=\"82.0\" y2=\"293.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 292.9 L 86.5 292.9 L 82.0 300.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"300.9\" width=\"422.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"323.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"327.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"328.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-comm-deadlock-fail-sec-1\">一 · 条目边界：什么算通信计算死锁</h3>\n<p>在 Blackwell 的 MoE 推理路径上，一个请求要穿过“路由 → 分组 GEMM（专家计算）→ All-to-All（token 重排/回传）→ 下一层”的循环。通信计算死锁（communication–compute deadlock）专指这个循环里出现的<strong>循环等待</strong>：计算核把 SM 占满，通信核无法发射；通信未完成，计算又无法进入下一阶段。两边各自持有对方需要的资源，谁也不放，于是不是“慢”，而是“停”。</p>\n<p>这个定义有三个必须同时满足的成分，缺一不成立。第一，<strong>存在真实的资源争用</strong>——通常是 SM 占用配额，也可能是流/事件这一层的同步资源。第二，<strong>存在依赖成环</strong>——A 等 B 的完成信号，B 等 A 让出的资源。第三，<strong>表现为挂死而非报错</strong>：NCCL 不会立刻抛错，而是等到超时窗口（领域常识为数十秒至数分钟量级）才以超时码收场，期间 GPU 利用率可能很高、吞吐却骤降。第三点决定了它的工程性质：这是一个<em>可观测性</em>问题，不是一个崩溃问题。</p>\n<p>与相邻概念的分界要划清。它不同于单纯的<strong>通信瓶颈</strong>：后者带宽打满但仍在推进，延迟可预测；死锁则是推进停止。它也不同于<strong>路由倾斜尾延迟</strong>（见该条目）：倾斜是负载分布问题，死锁是资源与依赖顺序问题，倾斜可能诱发死锁但不是死锁本身。它更不同于<strong>NCCL 网络故障</strong>：网络故障通常伴随链路错误计数与明确的通信错误码，而死锁的通信侧一切正常，只是“发不出去”。工程上最常见的误判正是把 CUDA Graph 回放时的超时当成网络问题去查网卡。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-2\">二 · 分类维度一：按触发位置划分的四类</h3>\n<p>按触发位置划分是这套条目最实用的主轴，因为它直接对应排查入口。</p>\n<ul>\n<li><strong>SM 占用型</strong>：计算核（分组 GEMM）把每卡 SM 占满，未给通信核预留配额，All-to-All 的通信核排不进调度队列。信号是 GPU 利用率高、All-to-All 带宽利用率接近零、吞吐骤降。</li>\n<li><strong>流同步型</strong>：多流事件等待顺序成环——流 A 等流 B 的事件，流 B 又等流 A 的事件。单卡测试不复现，只在多机 All-to-All 与分离式预填/解码联调时暴露。</li>\n<li><strong>CUDA Graph 型</strong>：捕获时把通信与计算放在同一流上串行化，回放时图内同步点被重排，依赖错位成环。表现为回放阶段 NCCL 超时而非报错。</li>\n<li><strong>跨节点型</strong>：分离式预填/解码架构下，预填实例与解码实例之间的 All-to-All 与 KV 传输互等，两侧都在等对方的传输完成。</li>\n</ul>\n<p>四类不是互斥的：CUDA Graph 型常常叠加 SM 占用型——图捕获把通信与计算压到同一流，回放时计算核又占满 SM，两个条件同时成立才挂死。排查时应把“图捕获方式”与“SM 配额”作为两个独立维度记录，而不是合并成一个“重叠配置不当”。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-3\">三 · 分类维度二：按可观测信号与根因定位项</h3>\n<p>第二个维度是“你看到什么”与“你该查什么”的映射，它决定了速查表的结构。速查表应包含列：失败模式类别、触发条件（SM 占用率/流数量/图捕获方式）、可观测信号（NCCL 超时码、SM 活跃度、All-to-All 带宽利用率）、根因定位项（流优先级、通信 SM 配额、同步点位置）、缓解动作、回归验证项。</p>\n<p>三个信号各自指向不同的层。NCCL 超时码只告诉你“有集合通信没完成”，不告诉你为什么；SM 活跃度高而 All-to-All 带宽利用率低，指向 SM 占用型；SM 活跃度不高但通信仍未完成，指向流同步型或跨节点型。把这三个信号做成一组联合判据，比单看超时码有效得多。</p>\n<div class=\"formula\">$$\\text{deadlock} \\iff \\big(\\text{SM}_{\\text{compute}} \\to \\text{cap}\\big) \\wedge \\big(\\text{dep}(C \\to A) \\wedge \\text{dep}(A \\to C)\\big) \\wedge \\big(t &gt; T_{\\text{nccl}}\\big)$$</div>\n<p>这里 $T_{\\text{nccl}}$ 是 NCCL 超时窗口，是判定“已挂死”而非“仍在推进”的时间门槛。工程上要区分“超时窗口内的高延迟”与“超时窗口外的挂死”：前者是性能问题，后者才是死锁。代价维度上，SM 占用型的代价是<strong>吞吐骤降</strong>（利用率虚高但有效吞吐塌陷）与<strong>长尾堆积</strong>触发 SLO 违约；流同步型的代价是<strong>延迟不可预测</strong>，因为成环发生在事件层，单请求延迟被拉长到超时量级；跨节点型的代价还叠加了<strong>跨节点带宽空转</strong>——KV 传输与 All-to-All 都在等，链路却闲着。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-4\">四 · 与“重叠优化”的区别：重叠率不是越高越好</h3>\n<p>这是本条目最容易被误解的边界。All-to-All 与分组 GEMM 重叠本身是正当的优化目标，死锁不是“重叠”的必然结果，而是<strong>重叠方式</strong>的失败。区别在于：健康的 overlapping 是通信核与计算核在 SM 上<em>共存</em>且有明确的配额划分；死锁是计算核把配额吃光、通信核拿不到发射机会。</p>\n<p>因此“为提升重叠率把计算核 SM 占用拉满而未给通信核预留配额”是一个典型的反向优化：重叠率指标好看，实际挂死。工程判断上，通信 SM 配额常按每卡 SM 总数的固定比例预留（具体比例材料未给出，需按框架与 kernel 实测确定），这个配额是重叠能否成立的前提，而不是可选的调优项。</p>\n<p>另一个边界是与<strong>分组 GEMM 与 tcgen05</strong>（见该条目）的关系：tcgen05 的 MMA 形态会改变计算核的 SM 占用曲线与持续时间，从而改变通信核可用的窗口。同一个配额比例在不同 MMA 形态下未必等效，这是回归验证必须覆盖的变量。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-5\">五 · 与 CUDA Graph、流优先级的边界</h3>\n<p>CUDA Graph 本身不是死锁原因，它是<strong>放大器</strong>。捕获阶段把通信与计算放在同一流上串行化，等于把“重叠”写成了“顺序”；回放阶段图内同步点被重排，原本隐式的顺序依赖变成显式的错误依赖，成环。这里的机制要点是：图捕获记录的是<em>捕获时的流与事件拓扑</em>，回放不重新推导依赖，所以捕获时的一个偷懒（同流串行）会在回放时固化成结构性问题。</p>\n<p>流优先级是缓解手段而非分类维度。给通信流更高优先级可以让通信核在 SM 紧张时优先获得发射机会，但它不能修复已经成环的事件依赖——成环是拓扑问题，优先级只影响调度顺序。把这两者混为一谈，会导致“调了优先级仍然挂死”的困惑。正确的定位顺序是：先确认依赖拓扑无环（流同步型/CUDA Graph 型），再确认 SM 配额留足（SM 占用型），最后才是优先级微调。</p>\n<p>具体例子：一个 MoE 层在单卡上把分组 GEMM 与 All-to-All 放同一流，单卡测试通过（因为单卡 All-to-All 退化为本地拷贝，延迟极短，串行化看不出代价）；上多机后同一份代码在图捕获回放时超时。排查若只看 NCCL 日志会误判为网络，实际根因是捕获时的同流串行加上回放时的同步点重排。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-6\">六 · 分类的工程用法：一张表决定排查路径</h3>\n<p>把上述维度落成排查路径：先看信号组合定位类别，再看触发条件确认是否命中已知踩坑，最后按根因定位项逐项排除。SM 占用型查配额与计算核占用曲线；流同步型查事件等待图是否成环；CUDA Graph 型查捕获时的流拓扑与回放同步点；跨节点型查预填/解码两侧的传输完成条件是否互等。</p>\n<p>回归验证项必须与类别绑定：SM 占用型的回归是“配额调低后吞吐是否仍达标”，流同步型的回归是“多机联调下是否复现”，CUDA Graph 型的回归是“重新捕获后回放是否稳定”，跨节点型的回归是“预填/解码实例比例变化时是否仍无互等”。只做单卡回归不足以覆盖后三类，这是这套条目反复强调的工程判断。</p>\n<table class=\"mini\"><thead><tr><th>类别</th><th>触发条件</th><th>可观测信号</th><th>根因定位项</th></tr></thead><tbody><tr><td>SM 占用型</td><td>计算核占满 SM、无通信配额</td><td>利用率高、All-to-All 带宽≈0</td><td>通信 SM 配额</td></tr><tr><td>流同步型</td><td>多流事件互等</td><td>多机才复现、超时码</td><td>流优先级、事件拓扑</td></tr><tr><td>CUDA Graph 型</td><td>同流捕获、回放重排</td><td>回放阶段超时</td><td>同步点位置、捕获流拓扑</td></tr><tr><td>跨节点型</td><td>预填/解码互等传输</td><td>跨节点带宽空转</td><td>传输完成条件</td></tr></tbody></table>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-7\">七 · 边界条件：什么才算死锁，什么只是慢</h3>\n<p>把“通信计算死锁”与三类相邻现象切开，是排查的第一道分水岭。第一类是<b>纯带宽退化</b>：All-to-All 与分组 GEMM 争抢 HBM 与 L2，SM 仍在推进，只是有效吞吐下降，表现为 All-to-All 带宽利用率与 SM 活跃度同时偏低但非零，NCCL 不超时。第二类是<b>长尾而非死锁</b>：计算核占满 SM 使通信核延迟发射，All-to-All 被推迟到分组 GEMM 尾部才启动，单次迭代时间拉长、尾请求堆积触发 SLO 违约，但依赖关系并未成环，只要下一轮开始前通信能完成，系统仍能前进。第三类才是<b>真死锁</b>：计算核等待 All-to-All 结果才能进入下一分组，通信核等待 SM 配额才能发射，二者互为前提，形成循环等待，唯一的外部信号是 NCCL 超时窗口（数十秒至数分钟量级）到期。判别式可写成：设计算核占用 SM 数为 $S_c$、通信核需求为 $S_m$、每卡 SM 总数为 $S$，当 $S_c + S_m &gt; S$ 且计算核不主动让出时，通信核进入<b>不可发射态</b>；若此时计算路径的下一个依赖恰好是该通信的结果，则状态迁移图闭合，死锁成立。反之若计算路径尚有独立分组可推进，则只是饥饿，属长尾。</p>\n<p>分类维度按触发位置划分，四类的失效条件与代价各不相同。SM 占用型：计算核把 SM 配额拉满而未预留通信配额，通信核无法发射；代价是 GPU 利用率显示很高而吞吐骤降，功耗维持在高位却无有效吞吐，是最具迷惑性的一类。流同步型：多流事件等待顺序成环（流 A 等流 B 的事件、流 B 又等流 A 的事件），单卡测试不复现，只在多机 All-to-All 与分离式预填/解码联调时暴露；代价是跨节点链路空转、预填与解码实例互等 KV 传输与 All-to-All。CUDA Graph 型：捕获时把通信与计算放在同一流上串行化，回放时图内同步点被重排导致依赖错位，表现为 NCCL 超时而非报错，排查时极易误判为网络故障；代价是整图回放停摆，且因为不抛异常，监控上只看到吞吐断崖。分离式预填/解码跨节点型：预填实例与解码实例间的 All-to-All 与 KV 传输互等，属跨进程循环等待，单实例内部指标全部正常。</p>\n<table class=\"mini\"><thead><tr><th>类别</th><th>触发条件</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>SM 占用型</td><td>计算核占满 SM，未预留通信配额</td><td>SM 活跃度高、All-to-All 带宽利用率为零、NCCL 超时</td><td>吞吐骤降、功耗空耗、SLO 违约</td></tr><tr><td>流同步型</td><td>多流事件等待成环</td><td>单卡正常、多机联调超时</td><td>跨节点链路空转</td></tr><tr><td>CUDA Graph 型</td><td>图捕获同流串行、同步点重排</td><td>回放超时无报错</td><td>整图停摆、误判网络</td></tr><tr><td>跨节点型</td><td>预填/解码实例互等</td><td>实例内指标正常、端到端超时</td><td>KV 与 All-to-All 双阻塞</td></tr></tbody></table>\n<p>与相邻概念的区别要落在“谁在等谁”上。流水线气泡是同一流内阶段间的空转，依赖方向单一，不会成环；通信计算死锁的必要条件是<b>双向依赖</b>。资源争抢（SM、HBM 带宽）只造成减速，不改变可达状态集。NCCL 超时本身不是死锁的定义，而是死锁的<b>外部观测手段</b>——超时也可能来自链路故障或对端进程崩溃，因此判定必须同时满足“超时 + 依赖成环 + 单侧资源不可让出”三条。工程上据此设回归验证项：固定通信 SM 配额比例后重跑，若超时消失且 All-to-All 带宽利用率回升，则归因 SM 占用型；若仅在多机联调消失而在单机仍复现，则归因流同步型；若打开 CUDA Graph 才复现、关闭即恢复，则归因图内同步点重排。这三条判据把“慢”与“死”分开，也把网络故障从嫌疑名单里剔除。</p>\n<h3 id=\"ap-comm-deadlock-fail-sec-8\">八 · 速查表的结构与口径约定</h3>\n<p>这张表按“一行一个失败模式”组织，列固定为六项：失败模式类别、触发条件、可观测信号、根因定位项、缓解动作、回归验证项。使用口径有三条硬约定：其一，触发条件列只写可配置或可观测的量（SM 占用比例、流数量、图捕获方式、实例拓扑），不写“负载高”这类模糊描述；其二，可观测信号列必须能在不侵入内核的前提下采到，NCCL 超时码、SM 活跃度采样、All-to-All 带宽利用率三者至少取其二；其三，根因定位项与缓解动作一一对应，避免“先调优先级再调配额”式的盲目试错。判定死锁的窗口以 NCCL 超时为准，量级在数十秒至数分钟，低于该窗口的停顿只能记为长尾，不能记为死锁——这是本表所有“判定”动作的统一口径。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>失败模式类别</th><th>触发条件</th><th>可观测信号</th><th>根因定位项</th><th>缓解动作</th><th>回归验证项</th></tr>\n</thead>\n<tbody>\n<tr><td>SM 占用型</td><td>计算核占用 SM 比例逼近上限，通信核无预留配额</td><td>GPU 利用率高但吞吐骤降；All-to-All 带宽利用率贴近零；NCCL 超时</td><td>通信 SM 配额（按每卡 SM 总数固定比例预留）</td><td>为通信核显式预留 SM 配额，计算核网格按剩余 SM 收缩</td><td>同一 batch 下 All-to-All 带宽利用率回到非零稳态；长尾请求数回落</td></tr>\n<tr><td>流同步型</td><td>多流事件等待顺序成环（流 A 等流 B、流 B 等流 A）</td><td>单卡不复现；多机联调时 NCCL 超时；事件等待链无法收敛</td><td>流优先级与事件插入位置</td><td>拆环：固定一条流为“发起方”，另一条只做被动等待</td><td>多机 All-to-All 与分离式预填/解码联调下不再超时</td></tr>\n<tr><td>CUDA Graph 型</td><td>捕获时通信与计算同流串行化，回放时图内同步点被重排</td><td>回放阶段 NCCL 超时而非报错；捕获期无异常</td><td>同步点位置与图捕获方式</td><td>重排图内同步点，通信与计算分属不同流并在图内显式建边</td><td>图回放多次后依赖关系稳定，无超时</td></tr>\n<tr><td>跨节点型</td><td>预填与解码实例间 All-to-All 与 KV 传输互等</td><td>跨实例链路带宽利用率一侧为零、另一侧饱和</td><td>两侧传输的发起顺序与完成事件</td><td>规定 KV 传输与 All-to-All 的先后次序，禁止双向互等</td><td>分离式部署下预填/解码两侧均能推进</td></tr>\n</tbody>\n</table>\n<p>这张表的用法不是“查表即修”，而是“查表即缩小假设空间”。例如看到 GPU 利用率高、吞吐骤降、All-to-All 带宽利用率贴零，应直接跳到 SM 占用型一行，把排查预算压在通信 SM 配额上，而不是先去查网卡与链路。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-9\">九 · 阈值与判定口径：哪些量必须采、采到什么程度</h3>\n<p>材料未给出具体数值阈值，因此本表采用“相对口径 + 定性判定”的组合，避免编造数字。三个必采量的口径如下：SM 活跃度按采样窗口内的占用比例读取，判定依据是“计算核占用是否已逼近上限且通信核无发射窗口”，而非某个固定百分比；All-to-All 带宽利用率以链路峰值为参照，死锁态的典型特征是“计算侧活跃、通信侧贴零”，与网络故障的“两侧同时低”可区分；NCCL 超时以超时窗口为唯一判定线，窗口内反复出现的停顿记为长尾，跨窗口才记为死锁。通信 SM 配额按每卡 SM 总数的固定比例预留，具体比例由部署方按模型与并行度标定，表中只登记“是否预留”这一布尔状态，不登记数值。</p>\n<div class=\"formula\">$$\\text{deadlock} \\iff \\big(\\text{SM}_{\\text{compute}} \\to \\text{cap}\\big) \\wedge \\big(\\text{BW}_{\\text{A2A}} \\to 0\\big) \\wedge \\big(t &gt; T_{\\text{nccl}}\\big)$$</div>\n<p>该判据的工程价值在于把“吞吐骤降”拆成两个互斥方向：若 SM 占用未达上限而带宽贴零，问题在流同步或图依赖；若 SM 占用达上限且带宽贴零，问题在配额。一个具体例子：分组 GEMM 的网格按满 SM 配置发射，All-to-All 核排队等 SM，此时观测到计算侧 SM 活跃度持续高位、All-to-All 带宽利用率长期为零，跨过 NCCL 超时窗口后报超时——这条链路完全落在 SM 占用型一行，无需进入网络排查。代价上，这种判定方式要求采样与超时窗口对齐，采样频率过低会把死锁误判为长尾，采样过密则引入额外开销，通常以“每超时窗口内至少若干次采样”为口径，具体次数由工具链决定。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-10\">十 · 根因定位项：三个旋钮的检查顺序</h3>\n<p>表中根因定位项收敛为三个旋钮：流优先级、通信 SM 配额、同步点位置。检查顺序有讲究，按“代价从低到高”排：先看流优先级与事件插入位置（改配置即可验证），再看通信 SM 配额（需改内核网格配置），最后看同步点位置（需改图捕获逻辑并重新捕获）。顺序颠倒的代价是：先改图捕获会掩盖流同步问题，回放时症状变形，反而延长定位时间。</p>\n<ul>\n<li>流优先级：检查是否存在两条流互相等待对方事件。判据是事件等待链能否在有限步内收敛到一条“发起方”流；不能收敛即为成环。</li>\n<li>通信 SM 配额：检查计算核网格是否吃满全部 SM。判据是通信核是否有可发射的 SM 槽位；无槽位即配额缺失。</li>\n<li>同步点位置：检查图内同步点是否在捕获后被重排到与捕获期不同的相对位置。判据是回放期依赖边与捕获期是否一致。</li>\n</ul>\n<p>一个具体例子：单卡测试一切正常，多机 All-to-All 与分离式预填/解码联调时才出现 NCCL 超时。此时按顺序检查，流优先级一项即命中——流 A 等流 B 的事件、流 B 又等流 A 的事件，单卡因拓扑简单未成环，多机联调把两条流的相对顺序打乱后成环。缓解动作是固定一条流为发起方，另一条只做被动等待，代价是重叠率略降，但换来确定性。回归验证项必须包含多机联调场景，单卡回归不足以覆盖此类问题。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-11\">十一 · CUDA Graph 型：捕获方式与回放口径</h3>\n<p>CUDA Graph 型一行的特殊性在于“捕获期无异常、回放期才暴露”。最常见踩坑是把通信与计算放在同一流上串行化做“重叠”，捕获时依赖关系看似正确，回放时图内同步点被重排，依赖成环，表现为 NCCL 超时而非报错。表中该行的触发条件因此写成“捕获时同流串行化 + 回放时同步点重排”两个条件的合取，缺一不成立。可观测信号的口径是：捕获期无超时、回放期出现超时，且超时发生在图回放的固定阶段而非随机位置。</p>\n<div class=\"formula\">$$\\text{cycle} \\iff \\exists\\, e_1 \\to e_2 \\to \\cdots \\to e_1 \\ \\text{in}\\ \\text{Graph}_{\\text{replay}}$$</div>\n<p>缓解动作是重排图内同步点：通信与计算分属不同流，并在图内显式建立依赖边，使回放期的依赖关系与捕获期一致。代价是图捕获逻辑复杂度上升，且每次修改并行策略都需重新捕获与验证；收益是把“回放期偶发超时”变成“捕获期可验证的依赖图”。回归验证项要求图回放多次后依赖关系稳定、无超时，且验证必须在与生产相同的并行度与拓扑下进行。一个具体例子：同一份图在单机回放正常，在多机 All-to-All 场景回放时超时，根因是图内同步点重排后跨节点依赖错位——这正是表中把“图捕获方式”列入触发条件的原因。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-12\">十二 · 缓解动作与回归验证的配对原则</h3>\n<p>表中缓解动作与回归验证项严格配对，原则是“缓解动作改什么，回归就验什么”，不允许跨行借用验证项。SM 占用型的缓解是预留配额，回归就验 All-to-All 带宽利用率回到非零稳态与长尾请求数回落；流同步型的缓解是拆环，回归就验多机联调下不再超时；CUDA Graph 型的缓解是重排同步点，回归就验图回放多次后依赖稳定；跨节点型的缓解是规定传输先后次序，回归就验两侧均能推进。这条原则的工程意义在于：死锁问题的复现成本高，若回归项与缓解动作不匹配，修复后无法证明问题消失，只能证明症状暂时不出现。</p>\n<p>代价维度需在表中体现但不单列：SM 占用型的缓解以吞吐为代价（计算核网格收缩），流同步型的缓解以重叠率为代价，CUDA Graph 型的缓解以捕获复杂度为代价，跨节点型的缓解以流水线深度为代价。四类代价都落在延迟或吞吐上，不涉及显存与功耗的显著变化——这是本表与容量规划类表格的分界。一个具体例子：为提升重叠率把计算核 SM 占用拉满而未预留配额，短期吞吐上升，长尾请求堆积触发 SLO 违约，此时按表回退到预留配额，吞吐略降但 SLO 恢复，回归验证项即为长尾请求数回落。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-13\">十三 · 表的边界：哪些情况不进这张表</h3>\n<p>本表只覆盖“同一 SM 资源或同一流依赖上的循环等待”，三类情况明确排除：其一，纯网络故障导致的 All-to-All 失败，其特征是两侧带宽同时低而非一侧活跃一侧贴零，应走链路排查而非本表；其二，单核内的数值或精度问题，与本表无关；其三，容量不足导致的排队，表现为吞吐随负载线性下降而非骤降，不满足本表的判定式。排除这三类后，表内四行覆盖了材料给出的全部失败模式，且每行都有对应的可观测信号与回归项。使用时的最后一道判断是：若观测信号无法同时满足判定式中的三个条件，则不应套用本表的缓解动作，而应回到采样口径重新对齐超时窗口——这是本表作为速查工具而非诊断工具的边界所在。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-14\">十四 · 速查表：边界、失效条件与系统代价的对照口径</h3>\n<p>这张表不是“最佳实践清单”，而是排查时的判定口径：每一行给出该失败模式在什么条件下才成立、用什么信号确认、以及缓解动作本身的代价。填表时先固定三个字段的取值来源——SM 占用率取计算核发射前的瞬时占用（不是稳态均值），流数量取参与该 All-to-All 的流与事件图节点数，图捕获方式区分“捕获时同流串行”与“捕获后重排同步点”两种。阈值口径上，材料未给出具体数值，工程上以 NCCL 超时窗口（数十秒至数分钟量级）作为死锁判定信号，通信 SM 配额按每卡 SM 总数的固定比例预留，比例需在目标集群上实测标定，不能跨机型照搬。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>触发条件</th><th>可观测信号</th><th>根因定位项</th><th>缓解动作与代价</th></tr></thead><tbody><tr><td>SM 占用型</td><td>计算核占满 SM，未预留通信配额</td><td>GPU 利用率高、吞吐骤降、长尾堆积</td><td>通信 SM 配额、核发射顺序</td><td>按比例预留 SM，计算侧损失部分算力</td></tr><tr><td>流同步型</td><td>多流事件等待成环</td><td>单卡不复现，多机联调暴露</td><td>流优先级、事件依赖方向</td><td>拆环重排，增加一次同步跳数</td></tr><tr><td>CUDA Graph 型</td><td>捕获时同流串行，回放同步点重排</td><td>NCCL 超时而非报错</td><td>图内同步点位置</td><td>重捕获或改多流图，损失图回放收益</td></tr><tr><td>跨节点型</td><td>预填与解码实例互等</td><td>All-to-All 带宽利用率塌陷</td><td>KV 传输与集合通信顺序</td><td>解耦两段依赖，增加跨节点往返</td></tr></tbody></table>\n<p>判定死锁与“慢”的分界，可用一个简单的等待环判据：把流与事件抽象为有向图，若存在节点序列使每条边都是“等待”，即构成环，则无论超时窗口多长都不会自愈。设等待图 $G=(V,E)$，$V$ 为流与通信操作，$E$ 为事件等待边，死锁条件为 $\\exists\\, v_1\\to v_2\\to\\cdots\\to v_k\\to v_1$。这个判据的价值在于它把“NCCL 超时”从网络故障的默认解释里剥离出来——超时只是环存在的外在表现，排查应直接落到环上的边，而不是先查链路。</p>\n<p>缓解动作都有系统代价，必须写进容量口径：预留通信 SM 配额直接压低分组 GEMM 的有效算力，重叠率提升的收益要与这部分损失对冲；拆环重排会引入额外同步跳，抬高单次迭代的固定延迟；CUDA Graph 改多流重捕获则牺牲图回放的发射开销优势，回放路径变长。跨节点型最贵，解耦预填与解码的互等会拉长跨节点往返，在 SLO 紧的时段应优先保证解码侧的 All-to-All 不被预填的 KV 传输阻塞。回归验证项固定为三项：同一图在单机与多机各回放一轮、把通信 SM 配额下调一档看是否复现、以及人为注入一次超时窗口内的长尾请求观察是否成环。</p>\n<h3 id=\"ap-comm-deadlock-fail-sec-15\">十五 · 超时窗口：把“挂死”翻译成可判定的时间量</h3>\n<p>NCCL 超时窗口是这套排查体系里唯一一个几乎总在用的阈值。它的作用不是“等久一点说不定就好了”，而是把循环等待从“吞吐骤降”这种模糊现象转成一个有边界的判定事件：当某个集合通信在窗口内没有完成，NCCL 抛出超时码并终止，进程留下可观测的失败点。材料给出的量级是数十秒至数分钟，具体数值未给出，因此工程上要做的不是背一个数字，而是把窗口当成可配置的判定参数来测。</p>\n<p>测量方法：在健康基线上跑一遍目标负载，记录每次 All-to-All 的完成时间分布，取分位尾部（例如 P99.9）作为下界参考，再把超时窗口设为该尾部的若干倍，使得正常抖动不会误触发、而真实成环能在可接受的时间内暴露。窗口设得过短会把长尾误判为死锁，设得过长则单次故障的恢复代价被放大——在 NVL72 这种单机柜内高带宽域里，一次挂死意味着整条流水线的请求堆积，窗口越长，堆积越深。</p>\n<div class=\"formula\">$$T_{\\text{timeout}} = k \\cdot q_{99.9}\\big(t_{\\text{A2A}}\\big),\\quad k \\in [3,10]$$</div>\n<p>代价面：超时窗口直接决定故障恢复的延迟上限，也决定 SLO 违约的规模。窗口为数十秒量级时，一次成环可能吞掉数百个在途请求；窗口拉到分钟量级，恢复时间与请求堆积量同步放大。因此窗口不是越大越安全，它要和批调度器的在途请求上限一起调。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-16\">十六 · 通信 SM 配额：按比例预留，按实测收敛</h3>\n<p>材料明确指出通信 SM 配额常按每卡 SM 总数的固定比例预留，但具体比例未给出。这意味着工程上必须自己测出这个比例的下限，而不是照抄。机制上，All-to-All 的通信核需要可发射的 SM 才能推进；当分组 GEMM 的计算核把 SM 占满，通信核排队等资源，计算又在等通信结果，环就闭合了。</p>\n<p>测量方法是一个二分式的收敛过程：固定负载与流结构，从“计算核占满全部 SM”开始，逐步下调计算核的 SM 占用上限，观察 All-to-All 的发射延迟与整体吞吐。存在一个拐点：低于它，通信核能及时发射，重叠真正生效，吞吐随配额下降而上升；高于它，通信核被饿死，吞吐骤降且 GPU 利用率虚高。这个拐点就是该负载形态下的配额下界。注意拐点随专家并行度、token 分布倾斜度变化，必须在目标并行配置下测，不能拿单卡数据外推。</p>\n<table class=\"mini\"><thead><tr><th>观测量</th><th>健康特征</th><th>配额不足特征</th></tr></thead><tbody><tr><td>SM 活跃度</td><td>计算与通信核交替占用，曲线有起伏</td><td>计算核长期饱和，通信核几乎不出现</td></tr><tr><td>All-to-All 带宽利用率</td><td>随批次稳定波动</td><td>长时间贴零后突然尖峰</td></tr><tr><td>吞吐</td><td>随配额下调先升后平</td><td>配额拉满时骤降</td></tr></tbody></table>\n<p>代价面：预留配额等于主动放弃一部分计算并行度，直接体现为分组 GEMM 的峰值算力折损；但换回的是通信可发射性，避免整条流水线挂死。这是一个用稳态吞吐换尾延迟确定性的交易，配额比例就是这笔交易的定价。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-17\">十七 · 流数量与优先级：用事件图而不是直觉来定</h3>\n<p>流同步型死锁的阈值不在时间维度，而在拓扑维度：流数量、事件等待的边数、以及是否存在环。多流事件等待顺序成环（流 A 等流 B 的事件、流 B 又等流 A 的事件）在单卡测试中不复现，只在多机 All-to-All 与分离式预填/解码联调时暴露——这一点材料已经点明，因此测量必须在目标拓扑上做。</p>\n<p>测量方法：把每个流的事件等待关系抽成有向图，节点是流与同步点，边是事件依赖，做一次环检测。工程上可用的伪代码思路是：在图捕获前后各导出一次依赖边集合，比较两次的差异，任何新增的逆向边都是重排引入的风险点。流优先级则用另一条测量线：给通信流更高优先级，观察 All-to-All 发射延迟是否收敛；若优先级调整后延迟不变，说明瓶颈不在调度顺序而在 SM 配额，排查方向要切换。</p>\n<ul>\n<li>流数量本身不是阈值，环的存在才是；两条流足以成环，十条流也可能无环。</li>\n<li>优先级只解决“谁先被调度”，不解决“有没有资源可调度”，两者要分开测。</li>\n<li>单卡无环不代表多机无环，跨节点路径上的 KV 传输会引入新的等待边。</li>\n</ul>\n<p>代价面：流数量增加会抬高调度器与事件管理的开销，在图捕获场景下还抬高图的节点数，回放时的启动开销随之上升；优先级反转则可能让计算流被长期压制，表现为计算侧长尾。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-18\">十八 · CUDA Graph 下的同步点：重排的度量方式</h3>\n<p>CUDA Graph 型死锁的根因是图内同步点被重排后依赖错位。材料给出的最常见踩坑是把通信与计算放在同一流上串行化，回放时因图内同步点被重排导致依赖成环，表现为 NCCL 超时而非报错——排查时极易误判为网络故障。这里的“阈值”不是数值，而是结构约束：图内同步点的数量与位置必须与捕获时的语义一致。</p>\n<p>测量方法：对同一逻辑负载分别做“捕获—回放”与“非图直接执行”两条路径，逐阶段比对时间线。若回放路径上出现某阶段开始时间早于其依赖阶段结束时间，即为重排证据。更细的做法是统计图内同步点数量与捕获时的差异，任何减少都意味着依赖被合并或丢弃。判定信号上，NCCL 超时码配合 SM 活跃度曲线可以区分“网络慢”与“依赖成环”：前者带宽利用率持续偏低但仍有推进，后者是长时间零推进后的突然超时。</p>\n<div class=\"formula\">$$\\text{reorder risk} = \\big|\\,\\#\\text{sync}_{\\text{captured}} - \\#\\text{sync}_{\\text{replayed}}\\,\\big| &gt; 0$$</div>\n<p>代价面：为保证图语义正确而保留的同步点会削弱重叠率，回放启动开销与图节点数正相关；若为追求重叠而删同步点，则把正确性押在重排恰好无害上，这在多机联调时不可接受。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-19\">十九 · 跨节点联调：只在目标拓扑上采信数字</h3>\n<p>分离式预填/解码跨节点型的死锁，其阈值必须包含网络侧的量：预填与解码实例间 All-to-All 与 KV 传输互等，任何一侧的等待窗口与另一侧的发射配额共同决定是否成环。材料未给出具体数值，因此测量方法是构造一个最小可复现的跨节点拓扑：两个实例、一条 All-to-All 路径、一条 KV 传输路径，逐条施加延迟与配额约束，观察在哪组参数下出现零推进。</p>\n<p>工程判断上，单卡与单机内的测量结果只能作为下界参考，不能作为配额与超时窗口的最终取值。NVL72 机柜内 NVLink 5 的高带宽会掩盖发射延迟，使配额不足的问题在机内不明显；一旦跨机柜走 NIXL 路径，等待边变长，原本“刚好够用”的配额立刻不够。因此配额与窗口要在最弱链路的目标拓扑上收敛，再回到强链路环境验证不会误触发。</p>\n<p>代价面：跨节点联调的测量成本高，需要占用真实拓扑；但跳过这一步的代价是死锁只在生产暴露，且被误判为网络故障，排查时间以小时计。这里没有捷径，只有把测量放在正确的拓扑上。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-20\">二十 · 阈值从哪来：三类可测量与一条判死锁的不等式</h3>\n<p>本片段只谈一件事：在没有厂商给定数字的前提下，怎么把“通信 SM 配额”“超时窗口”“流数量”这些工程阈值测出来，并判断当前配置是否已经越界。先把可测量分三类。第一类是直接可读的：每卡 SM 总数、通信核实际占用的 SM 数（用 profiler 的 SM 活跃度采样或 occupancy 查询）、All-to-All 带宽利用率、GPU 利用率。第二类是需要构造实验才能得到的：给定分组 GEMM 的 SM 占用率，逐步压缩通信可用 SM，观察 All-to-All 从“正常发射”到“迟迟不发射”的拐点，这个拐点就是该模型该并行度下的通信 SM 下限。第三类是只能靠时间维度观测的：单次 All-to-All 的完成时延分布、连续批处理下 P99 请求的排队时长、NCCL 超时是否触发。三类测量的共同点是都必须带负载测，空载下的 SM 占用率与真实分组 GEMM 的占用率不是一回事，用空载数据定配额是这类死锁最常见的错误来源。</p>\n<p>判据可以写成一个简单的不等式。设每卡 SM 总数为 <span class=\"inline-math\">S</span>，分组 GEMM 在峰值阶段占用的 SM 数为 <span class=\"inline-math\">S_c</span>，为通信核预留的配额为 <span class=\"inline-math\">S_m</span>，则安全条件为 <span class=\"inline-math\">S_c + S_m ≤ S</span>；一旦 <span class=\"inline-math\">S_c</span> 被拉满至 <span class=\"inline-math\">S</span>，则 <span class=\"inline-math\">S_m = 0</span>，通信核无法发射，进入“计算等通信、通信等 SM”的循环等待。工程上更实用的是把它写成余量形式：</p>\n<div class=\"formula\">$$S_m \\ge \\max\\left(S_{\\min},\\ \\alpha \\cdot S\\right),\\quad \\text{且}\\quad S_c \\le S - S_m$$</div>\n<p>其中 <span class=\"inline-math\">S_min</span> 是实测拐点对应的最小可用 SM 数，<span class=\"inline-math\">α</span> 是按 SM 总数固定比例预留的经验系数。材料未给出 <span class=\"inline-math\">α</span> 的具体取值，因此正确做法不是抄一个数，而是对每个模型形状、每个 EP/TP 并行度各做一次拐点扫描：固定 <span class=\"inline-math\">S_c</span>，把 <span class=\"inline-math\">S_m</span> 从较大值逐档下调，记录 All-to-All 发射时延与带宽利用率，取“带宽利用率不再随 <span class=\"inline-math\">S_m</span> 下降而下降”的那一档作为下限，再留一档余量写进配置。这个扫描的代价是显存与时间：每档都要跑完整的分组 GEMM 负载，单卡扫描通常以小时计，但相比线上一次 NCCL 超时导致的长尾堆积与 SLO 违约，这笔测量成本必须付。</p>\n<p>超时窗口的测量方法与之不同。NCCL 超时窗口在领域常识层面是数十秒至数分钟量级，它衡量的是“多久没进展就判定挂死”，而不是“一次 All-to-All 该多快”。因此不能用它当性能指标，只能用它当死锁判定信号。正确的测法是：在已知健康的配置下记录单次 All-to-All 的 P99 完成时延 <span class=\"inline-math\">T_{99}</span>，把超时窗口设为显著大于 <span class=\"inline-math\">T_{99}</span> 的值，使正常的长尾抖动不触发超时；同时在故障注入实验中（人为把 <span class=\"inline-math\">S_m</span> 压到 0、或把通信与计算串到同一流上）确认该窗口能在可接受时间内报出超时而非无限挂起。窗口设得过短会把正常长尾误判为死锁并触发无谓的重启，设得过长则故障发现延迟拉长，长尾请求持续堆积。表里给出这三类测量的对照：</p>\n<table class=\"mini\"><thead><tr><th>测量对象</th><th>测法</th><th>判据</th><th>系统代价</th></tr></thead><tbody><tr><td>通信 SM 下限 <span class=\"inline-math\">S_min</span></td><td>固定 <span class=\"inline-math\">S_c</span>，逐档下调 <span class=\"inline-math\">S_m</span>，看带宽利用率拐点</td><td><span class=\"inline-math\">S_c + S_m ≤ S</span> 且留一档余量</td><td>需带载扫描，小时级测量时间</td></tr><tr><td>超时窗口</td><td>健康配置下取 All-to-All P99 时延，再做故障注入验证</td><td>窗口显著大于 <span class=\"inline-math\">T_{99}</span>，且故障可被报出</td><td>过短误重启，过长延迟发现</td></tr><tr><td>流数量与同步点</td><td>多流事件依赖图逐条核对，单卡与多机分别回放</td><td>依赖图无环，图捕获前后同步点位置一致</td><td>多流增加事件开销与图重排风险</td></tr></tbody></table>\n<p>最后是失效条件的边界。上述阈值只在“通信与计算确实需要重叠”的前提下有意义；如果某层 MoE 的 All-to-All 数据量小到串行执行也不构成瓶颈，强行重叠反而引入流同步型与 CUDA Graph 型的风险，此时正确判断是退回单流串行并把同步点显式化。反过来，当 <span class=\"inline-math\">S_c</span> 因分组 GEMM 的专家数增加而自然逼近 <span class=\"inline-math\">S</span> 时，任何固定比例的 <span class=\"inline-math\">α</span> 都会失效，必须按最坏形状重算 <span class=\"inline-math\">S_min</span>。还有一个易被忽略的边界：这些阈值是在单机内测得的，跨机 All-to-All 与分离式预填/解码联调时，预填与解码实例间的互等会让单机测出的安全配额失去意义，此时应把超时窗口与流依赖图检查作为主要判据，而不是继续调 SM 配额。</p>\n<h3 id=\"ap-comm-deadlock-fail-sec-21\">二十一 · 踩坑清单：四类失败模式的可观测指纹</h3>\n<p>把死锁当成“网络抖动”是排查中最贵的误判。四类失败模式各有其可观测指纹，先认指纹再动手，比直接翻 NCCL 日志有效得多。SM 占用型死锁的指纹是：GPU 利用率读数很高（计算核确实在跑），但端到端吞吐骤降、All-to-All 带宽利用率贴近零，NCCL 超时码在数十秒至数分钟窗口后出现——计算核占满 SM，通信核根本没被发射，于是“忙而无进展”。流同步型死锁的指纹相反：GPU 利用率不高，多流事件等待图上出现环，单卡复现不了，只在多机 All-to-All 与分离式预填/解码联调时暴露。CUDA Graph 型的指纹最隐蔽：图捕获阶段一切正常，回放时同步点被重排、依赖错位，表现为 NCCL 超时而非显式报错，日志里没有任何非法访问痕迹。跨节点型的指纹是预填实例与解码实例互相等待——预填侧等 KV 传输完成才放行 All-to-All，解码侧等 All-to-All 结果才发起 KV 传输，两侧都不超时但都不前进。</p>\n<p>识别指纹的关键是把“谁在等谁”画出来。对每一对参与重叠的通信与计算，标注三件事：发射条件（需要多少 SM、哪个流）、完成条件（事件、屏障还是隐式同步）、下游依赖（谁必须等它完成）。三者构成有向图，环即为死锁候选。这个图的边不是静态的——CUDA Graph 捕获会重排同步点，图回放时的边集与捕获时的代码顺序不一致，所以必须按“回放后的图”而非“源码顺序”建图。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>根因定位项</th><th>缓解动作</th></tr></thead><tbody><tr><td>SM 占用型</td><td>GPU 利用率高、吞吐骤降、All-to-All 带宽趋零</td><td>通信 SM 配额是否预留</td><td>按 SM 总数固定比例划出通信专用配额</td></tr><tr><td>流同步型</td><td>多流事件等待成环、单卡不复现</td><td>流优先级与事件等待方向</td><td>拆环：单向依赖、禁止双向事件等待</td></tr><tr><td>CUDA Graph 型</td><td>捕获正常、回放 NCCL 超时、无报错</td><td>图内同步点位置与重排</td><td>重排同步点，通信与计算分属不同流节点</td></tr><tr><td>跨节点型</td><td>预填/解码互等、两侧均不超时</td><td>KV 传输与 All-to-All 的先后约定</td><td>统一放行顺序，加显式完成信号</td></tr></tbody></table>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-22\">二十二 · 检查顺序：从最便宜的证据开始</h3>\n<p>排查顺序应按“证据获取成本”升序，而不是按“怀疑强度”排序。第一步看 NCCL 超时窗口：超时窗口本身是判定死锁的主信号，出现超时即冻结现场，不要在超时后继续压测——超时后的重试会掩盖首次失败的位置。第二步看 All-to-All 带宽利用率与 SM 活跃度的组合：带宽趋零而 SM 活跃度高，直接指向 SM 占用型；两者都低，指向流同步型或跨节点型。第三步查流优先级配置与通信 SM 配额，这是两个最常被忽略的静态配置项，改动成本低、命中率高。</p>\n<p>第四步才进入 CUDA Graph 层面：把捕获的图导出，逐个节点核对同步点位置与依赖边。这里有一个具体的伪代码思路——对图中每个通信节点，检查其前驱集合中是否包含同一流上的计算节点，且该计算节点又（直接或间接）依赖该通信节点的完成事件：</p>\n<div class=\"formula\">$$\\text{deadlock} \\iff \\exists\\, c \\in \\text{Comm},\\ g \\in \\text{GEMM}:\\ g \\prec c \\ \\wedge\\ c \\prec g$$</div>\n<p>若存在这样的环，重排同步点：把通信节点与计算节点分属不同流，用单向事件连接，通信节点的发射不依赖计算节点的完成。第五步才是跨节点联调，检查预填与解码两侧的放行顺序是否互为前提。这个顺序的代价是：前四步全在单机完成，只有第五步需要多机资源；把多机验证放到最后，能把大部分死锁挡在单机阶段。</p>\n<p>具体例子：某 MoE 服务在压测中出现吞吐骤降，值班先怀疑 NCCL 网络故障，花时间排查链路。按上述顺序，第一步的超时码已出现，第二步发现 SM 活跃度高而 All-to-All 带宽趋零，第三步发现通信 SM 配额未预留——根因在单机配置层，与网络无关。检查顺序的价值就在于把这类误判挡在第一步之后。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-23\">二十三 · 回滚方案：分级降级而非一键回退</h3>\n<p>死锁的回滚不能是“回退到上一个版本”这种粗粒度动作，因为死锁往往由多个独立配置项叠加触发，全量回退会同时丢掉有效的性能优化。分级降级更稳：第一级，关闭计算与通信的重叠，退化为串行执行——吞吐下降但正确性恢复，用于止血；第二级，恢复通信 SM 配额到预留比例，重新开启重叠，验证 SM 占用型是否已解除；第三级，若仍复现，拆开 CUDA Graph 捕获，退回逐 kernel 发射，排除图内同步点重排因素；第四级，跨节点场景下统一预填与解码的放行顺序，必要时临时改为非分离式部署。</p>\n<p>每一级降级都必须配一个回归验证项，否则降级后无法判断是“真的修好了”还是“问题被藏起来了”。回归验证项应包含：All-to-All 带宽利用率在稳定窗口内是否达到预期、NCCL 超时是否在长稳压测中不再出现、长尾请求的 P99 是否回到 SLO 之内。降级的代价要量化：关闭重叠意味着计算与通信串行，端到端延迟增加的是通信阶段的完整时长，吞吐按重叠率折算下降；这个代价必须在降级决策时明确告知容量规划侧，避免降级后静默触发 SLO 违约。</p>\n<p>一个工程判断：回滚方案应预先写入部署清单，而不是等死锁发生后再设计。清单里写明每一级的触发条件（例如“超时码出现且带宽趋零”触发第一级）、执行动作、验证项与恢复条件。死锁的排查窗口通常只有数十秒到数分钟，现场设计回滚方案来不及。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-24\">二十四 · 静态配置项：最容易被忽略的三处</h3>\n<p>三处静态配置是踩坑高发区。其一是通信 SM 配额：计算核把 SM 占用拉满以提升重叠率，是性能直觉，但在 MoE 的 All-to-All 与分组 GEMM 重叠场景下直接导致通信核无法发射。配额应按每卡 SM 总数的固定比例预留，具体比例依模型与并行度而定，但“不预留”一定是错的。其二是流优先级：多流场景下若两条流的事件等待方向未约定为单向，优先级配置反而会加剧成环——高优先级流等待低优先级流的事件，低优先级流又等待高优先级流，调度器无法打破。其三是 CUDA Graph 捕获时的流归属：把通信与计算放在同一流上捕获，回放时退化为串行且同步点错位，这是最常见的一类坑。</p>\n<p>这三处的共同点是：它们都不在“代码逻辑”里，而在“部署配置”里，因此代码评审看不出来，只有配置审查能发现。检查清单应把这三项列为必查项，并在每次变更并行度、批大小或图捕获方式时重新核对——死锁的触发条件随这些参数漂移，昨天的正确配置今天可能成环。</p>\n<p>具体例子：为提升重叠率把分组 GEMM 的 SM 占用调至上限，单卡吞吐测试表现良好，多机 All-to-All 联调时出现 NCCL 超时；按清单核对发现通信 SM 配额为零，恢复预留后重叠率略降但吞吐稳定。这个例子的教训是：单卡测试无法暴露 SM 占用型死锁，因为单卡上没有真实的跨节点 All-to-All 发射压力。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-25\">二十五 · 长尾与 SLO 的耦合：死锁的第二种代价</h3>\n<p>死锁不总是硬挂死。SM 占用型在未完全挂死时会表现为长尾：通信核发射被延迟而非被完全阻塞，部分请求的 All-to-All 完成时间被拉长，长尾请求堆积触发 SLO 违约。这种“软死锁”比硬挂死更难排查，因为没有 NCCL 超时码，只有 P99 劣化。判别方法是看长尾请求的分布是否与专家路由倾斜相关——若长尾集中在路由到特定专家的请求上，说明该专家的分组 GEMM 占满了 SM，挤掉了通信核的发射窗口。</p>\n<p>对这类软死锁，缓解动作不是回滚而是配额再平衡：为通信核保留固定 SM 配额，代价是分组 GEMM 的有效算力下降，吞吐按配额比例折算损失。这个 trade-off 必须显式建模进容量规划，而不是在事故后临时调参。公式上，设通信配额占 SM 总数的比例为 $r$，则计算侧可用算力按 $(1-r)$ 折算，端到端吞吐的上界随之收缩；重叠带来的收益必须大于这部分损失才值得开启重叠。</p>\n<p>工程判断落在具体机制上：把通信 SM 配额与流优先级写入部署模板的必填字段，把 CUDA Graph 同步点检查写入图捕获流程的准入条件，把 NCCL 超时窗口作为死锁判定的唯一主信号而非辅助信号。这三条固定下来，踩坑清单就从“事后复盘”变成“事前拦截”。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-26\">二十六 · 踩坑清单与回滚：从“假重叠”到配额失守的边界判定</h3>\n<p>三类坑的失效边界各不相同，排查顺序应按“先证伪串行化、再验配额、最后查跨机成环”推进。第一类是伪重叠：把 All-to-All 与分组 GEMM 塞进同一流，语义上已退化为串行，CUDA Graph 捕获后同步点被重排，回放时表现为 NCCL 超时而非显式报错，最易被误判为网络故障。判据是看时间线而非看日志——若通信窗口内 SM 活跃度接近零、All-to-All 带宽利用率呈阶跃而非连续，即为串行化证据。第二类是配额失守：计算核占满全部 SM 而未给通信核留出配额，通信核无法发射，GPU 利用率高但吞吐骤降，长尾堆积触发 SLO 违约。第三类是多流事件等待成环，单卡测试不复现，只在多机 All-to-All 与分离式预填/解码联调时暴露。检查顺序固定为：流优先级与同步点位置 → 通信 SM 配额 → 图捕获方式 → 跨节点事件依赖，因为前两项在单机即可证伪，后两项代价高。</p>\n<p>配额侧的代价必须量化到可判定。设每卡 SM 总数为 <span class=\"inline-math\">S</span>，通信预留比例为 <span class=\"inline-math\">r</span>，则计算核可占上限为 <span class=\"inline-math\">(1−r)S</span>；当分组 GEMM 的 grid 配置超过该上限时，通信核的发射被阻塞，等待关系成环：</p>\n<div class=\"formula\">$$T_{\\text{stall}} \\approx \\frac{B_{\\text{A2A}}}{W_{\\text{link}}}\\quad\\text{s.t.}\\quad G_{\\text{GEMM}} \\le (1-r)\\,S$$</div>\n<p>其中 <span class=\"inline-math\">\\(B_{\\text{A2A}}\\)</span> 为单轮交换字节数，<span class=\"inline-math\">\\(W_{\\text{link}}\\)</span> 为可用链路带宽。该式的工程含义是：预留比例 <span class=\"inline-math\">r</span> 过小则 <span class=\"inline-math\">\\(T_{\\text{stall}}\\)</span> 被通信拖长并触发 NCCL 超时窗口（数十秒至数分钟量级），过大则 GEMM 吞吐受损。回滚方案据此分两级：一级回滚把计算 grid 压到 <span class=\"inline-math\">(1−r)S</span> 以下并恢复默认流优先级，验证项是超时码消失且 All-to-All 带宽利用率连续；二级回滚放弃图捕获、退回逐迭代流同步，代价是每步多出主机侧发射开销与图回放收益损失，仅作为止血手段。</p>\n<table class=\"mini\"><thead><tr><th>坑位</th><th>可观测信号</th><th>回滚动作</th><th>回归验证</th></tr></thead><tbody><tr><td>同流伪重叠</td><td>NCCL 超时、通信窗口 SM 活跃度趋零</td><td>拆流并重排图内同步点</td><td>时间线出现真实交叠区间</td></tr><tr><td>配额失守</td><td>GPU 利用率高、吞吐骤降、长尾堆积</td><td>下调 GEMM grid 至预留上限</td><td>超时码消失、SLO 恢复</td></tr><tr><td>多流成环</td><td>仅多机联调复现的事件互等</td><td>退回单流串行或固定事件序</td><td>跨节点联调无挂死</td></tr></tbody></table>\n<p>跨节点型的边界最隐蔽：分离式预填/解码实例间 All-to-All 与 KV 传输互等，成环条件不在单卡资源而在事件序，故任何单机压测都无法证伪。此处的工程判断是：只要拓扑中出现两个以上独立流且各自等待对端事件，就必须在联调前固定事件编号顺序，并把 NCCL 超时窗口作为唯一死锁判据而非依赖异常栈。回滚的最后一档是关闭重叠、改为阶段串行，用吞吐换取可预测性——这不是优化失败，而是把死锁从概率事件变为确定性代价的边界选择。</p>\n<h3 id=\"ap-comm-deadlock-fail-sec-27\">二十七 · 上游依赖：死锁条目承接的四类前置知识</h3>\n<p>本条目不是孤立存在的。要读懂 SM 占用型死锁，读者必须先具备 tcgen05 与分组 GEMM 的发射模型知识：分组 GEMM 的每个专家分组是一个独立的 CTA 集群，其 SM 占用是静态划分的，一旦计算核把 SM 配额吃满，通信核（NCCL 的 All-to-All kernel）在硬件层面就没有可发射的槽位。这条依赖链决定了死锁条目的第一个上游条目是“分组 GEMM 与 tcgen05”——不是因为它讲 GEMM 本身，而是因为它交代了 SM 配额的分配粒度。第二个上游是“专家并行与 All-to-All”：All-to-All 的 ring/tree 算法在不同规模下对 SM 的占用形态不同，ring 算法在小消息下占用少、tree 算法在大消息下占用多，死锁的触发概率随算法选择而变。第三个上游是“分离式预填/解码”：跨节点型死锁只在预填实例与解码实例联调时暴露，读者若不了解 P/D 之间 KV 传输与 All-to-All 的时序耦合，就无法理解“预填等解码的 KV 传输完成、解码等预填的 All-to-All 完成”这种双向等待。第四个上游是 CUDA Graph 捕获语义——这不在 MoE 条目群内，但死锁条目里 CUDA Graph 型失败模式的根因是图内同步点重排，读者需要知道图捕获时流与事件的记录方式，否则排查清单里的“同步点位置”一列无从落地。</p>\n<p>这四类前置知识共同构成一个判断：死锁不是网络问题，而是资源编排问题。上游条目讲的是“怎么把通信和计算各自做快”，本条目讲的是“两者叠加时谁先让路”。一个具体的机制例子：当分组 GEMM 的 CTA 集群按 SM 总数静态划分、且未显式预留通信配额时，NCCL kernel 的 launch 会一直排队；此时 GPU 利用率读数很高（计算核在跑），但 All-to-All 带宽利用率趋近于零，这个“高利用率 + 零通信带宽”的组合是 SM 占用型死锁的指纹信号。代价上，这种状态下吞吐骤降是断崖式的而非渐进的——因为流水线的前一阶段（dispatch）和后一阶段（combine）都被阻塞，整个 MoE 层的有效吞吐退化为零，而功耗仍维持在高位，形成“高功耗零产出”的最差能效点。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-28\">二十八 · 下游影响：死锁判定如何改变容量规划与 SLO 口径</h3>\n<p>死锁条目向下游输出的第一个结论是：容量规划不能只按稳态吞吐做线性外推。因为死锁的判定信号是 NCCL 超时窗口（数十秒至数分钟量级），一次死锁事件在监控上表现为一个长尾请求的延迟尖峰而非错误码，容量模型若只统计 P50 吞吐，会把死锁期间的空转算力误计为可用容量。正确的做法是在容量因子中引入“通信配额折损”：每卡预留的通信 SM 比例直接从可用于计算的 SM 总数中扣除，再算分组 GEMM 的有效算力。公式上可写成有效算力折损项：</p>\n<div class=\"formula\">$$C_{\\text{eff}} = C_{\\text{peak}} \\cdot \\left(1 - r_{\\text{comm}}\\right) \\cdot \\eta_{\\text{overlap}}$$</div>\n<p>其中 $r_{\\text{comm}}$ 是通信 SM 预留比例，$\\eta_{\\text{overlap}}$ 是实际达成的重叠效率（若退化为串行则趋近于 1/(1+通信占比)）。这个折损项直接进入 SLO 容量规划条目：预留比例越大，死锁风险越低但稳态吞吐越低，二者是显式的权衡曲线，而非“调优到最优”的单点。下游的第二个影响落在“路由倾斜尾延迟”条目：死锁造成的长尾与路由倾斜造成的长尾在监控上难以区分，前者伴随 NCCL 超时码、后者伴随专家负载不均衡信号，排查时必须先看通信侧信号再看路由侧信号，否则会把资源编排问题误诊为路由问题并错误地触发容量扩容。第三个影响是“MoE 推理框架选型”：框架是否暴露通信 SM 配额与流优先级配置项，直接决定该框架能否在生产中规避 SM 占用型死锁——TensorRT-LLM 与 vLLM 在这方面的可配置粒度不同，选型条目应把“死锁可配置性”作为一列而非隐含假设。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-29\">二十九 · 全书位置：介于算子条目与系统条目之间的编排层</h3>\n<p>把全书条目按抽象层次排布，死锁条目处在算子层（分组 GEMM、NVFP4/FP8、tcgen05）与系统层（批调度、分离式 P/D、并行与通信、SLO 容量规划）之间的编排层。它不定义任何算子，也不定义任何调度策略，它定义的是“当算子与通信同时存在于一张卡上时，资源如何让路”。这个位置决定了它的引用关系是双向的：向上，它引用算子条目的 SM 占用模型；向下，它被容量规划、框架选型、剖析工具链三个条目引用。剖析工具链条目尤其依赖它——死锁的可观测信号（NCCL 超时码、SM 活跃度、All-to-All 带宽利用率）正是工具链需要采集的三元组，工具链条目的采集项设计必须覆盖这三者，否则死锁在生产中不可观测。一个具体例子：若剖析工具只采集 GPU 利用率与端到端延迟，SM 占用型死锁会呈现为“利用率高、延迟高”的普通过载画像，与真实过载无法区分；加入 All-to-All 带宽利用率这一维后，零带宽即成为判别性特征。</p>\n<p>在七个领域的推理形态中，死锁条目的权重并不均匀。长上下文与高并发在线服务场景下，MoE 层频繁触发 All-to-All，SM 占用型死锁的概率最高；离线批处理场景下，请求队列长、对尾延迟不敏感，死锁表现为整体吞吐下降而非 SLO 违约，优先级较低；边缘与端侧场景通常不跨节点做 All-to-All，跨节点型死锁不适用。这个分布意味着死锁条目在全书中的实际读者群是在线服务与大规模集群的工程团队，而不是单卡部署场景。代价上，编排层的判断失误会同时污染上下游：向上会让算子条目的性能数字失去意义（算子再快，被死锁阻塞时有效吞吐为零），向下会让容量规划条目给出过于乐观的扩容建议。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-30\">三十 · 与相邻条目的边界划分：谁讲什么，避免重复</h3>\n<p>死锁条目与相邻条目存在三处容易重叠的边界，必须显式划清。第一处是与“专家并行与 All-to-All”的边界：后者讲 All-to-All 的算法选择、消息大小与拓扑映射，本条目只讲 All-to-All 与计算核争抢 SM 时的让路规则；读者若需要 All-to-All 本身的性能模型，应回到该条目，本条目不重复其带宽公式。第二处是与“分离式预填/解码”的边界：后者讲 P/D 分离的实例编排与 KV 传输路径，本条目只讲跨节点型死锁中“预填等 KV、解码等 All-to-All”的双向等待成环；P/D 的吞吐收益模型不在本条目展开。第三处是与“MoE 剖析工具链”的边界：后者讲采集项与可视化，本条目只提供死锁的三元判别信号作为工具链的输入需求，不讨论工具实现。划清边界后，本条目的独特贡献收敛为一件事：给出“资源让路”的判定规则与排查顺序，即先看通信 SM 配额、再看流优先级、最后看 CUDA Graph 同步点位置——这个顺序本身是工程判断，因为配额缺失是最常见且最易修的根因，同步点错位是最隐蔽且最难复现的根因。</p>\n<p>一个具体的边界判断例子：多流事件等待成环（流 A 等流 B、流 B 等流 A）在单卡测试中不复现，只在多机 All-to-All 与 P/D 联调时暴露。这个现象横跨本条目与 P/D 条目，划分方式是：成环的机制归本条目，联调拓扑的搭建归 P/D 条目。工程代价上，这类只在联调环境暴露的死锁意味着单卡回归测试无法覆盖，必须把多机联调作为发布前的强制回归项，回归验证项应包含“多流事件依赖图是否存在环”的静态检查，而非仅依赖运行时超时告警。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-31\">三十一 · 依赖失效时的连锁反应：上游条目出错如何放大死锁</h3>\n<p>上游条目的结论若被误用，会直接放大死锁概率。以量化条目为例：NVFP4/FP8 权重激活条目给出的是数值精度与吞吐的权衡，但量化后路由漂移条目指出路由分布会变化——路由更倾斜意味着 All-to-All 的消息大小分布更不均匀，ring 算法在小消息下的 SM 占用形态与均匀分布时不同，原本安全的通信配额在倾斜分布下可能不足。这不是量化条目本身的错，而是死锁条目必须把“路由分布形态”作为通信配额估算的输入变量，而不能假设均匀分布。公式上，通信配额的估算应基于最大分片消息而非平均消息：</p>\n<div class=\"formula\">$$r_{\\text{comm}} \\ge \\frac{S_{\\max}}{S_{\\text{total}}} \\cdot r_{\\text{base}}$$</div>\n<p>其中 $S_{\\max}$ 是最大专家分片的 token 数、$S_{\\text{total}}$ 是总 token 数。这个不等式说明：路由越倾斜，所需预留比例越高，而死锁条目与路由倾斜条目的耦合点正在此处。连锁反应的第二个方向是 CUDA Graph：图捕获时把通信与计算放在同一流上串行化，回放时同步点被重排导致依赖成环——这个失败模式的根因在图捕获语义，但触发条件是“为提升重叠率而把计算核 SM 占用拉满”，即上游分组 GEMM 条目的“吃满 SM”建议在图捕获场景下是有害的。工程判断是：图捕获场景下必须显式保留通信配额，不能沿用非图模式的“吃满”策略。代价上，图捕获带来的 launch 开销节省（每次回放省去逐 kernel 发射）与死锁风险是同一枚硬币的两面，选择图捕获就必须接受配额约束。</p>\n\n<h3 id=\"ap-comm-deadlock-fail-sec-32\">三十二 · 本条目在全书中承担的判断职责</h3>\n<p>死锁条目最终承担的职责不是“消灭死锁”，而是“让死锁可判定、可归因、可回归”。可判定依赖 NCCL 超时窗口这一信号；可归因依赖三元组（NCCL 超时码、SM 活跃度、All-to-All 带宽利用率）与排查顺序（配额→流优先级→同步点）；可回归依赖多机联调作为强制项。这三件事分别对接容量规划、剖析工具链、框架选型三个下游条目。一个具体的工程判断落在最后：当吞吐骤降伴随 GPU 利用率高企时，第一动作不是扩容也不是查网络，而是检查通信 SM 配额是否为零预留——因为这是唯一一个能在不增加任何硬件成本的前提下、通过配置修正即可消除的根因，而其余根因（流同步成环、图内同步点错位）都需要改动代码结构。这个优先级排序本身就是本条目在全书中的位置：它把“资源编排”从隐性假设提升为显式配置项，让上游算子条目的性能数字与下游容量条目的规划数字建立在同一个可验证的配额前提上。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-comm-deadlock-fail\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>All-to-All 与分组 GEMM 重叠时因 SM 占用与流同步顺序不当引发死锁或长尾，表现为吞吐骤降与 …</td></tr><tr><td>关键点</td><td>需给出流优先级、通信 SM 配额、CUDA Graph 下同步点重排的排查清单。</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-comm-deadlock-fail · 共 5 个片段</p>\n"},{"id":"ap-moe-launch-checklist","title":"MoE上线前清单","summary":"逐项核对：路由 top-k 一致率、容量因子与丢弃率上限、分组 GEMM 尾块效率、NVFP4/FP8 精度回归、KV 显存水位、All-to-All 带宽利用率、分离式预填解码 SLO 达标、CUDA Graph 回放正确性与故障降级路径。","kind":"清单","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-1\">一 · 清单条目的准确定义：从“检查动作”到“可判定断言”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-2\">二 · 四个分类维度：按“检查对象失效后伤到什么”划分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-3\">三 · 与相邻概念的区别：门禁、监控、剖析、调优的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-4\">四 · 条目字段的工程语义：阈值口径为何不能由清单本身给定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-5\">五 · 失败模式如何反向定义条目：三个例子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-6\">六 · 定义层面的工程判断：条目粒度与可复现性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-7\">七 · 速查表的七列骨架与填写纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-8\">八 · 正确性三行的口径写法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-9\">九 · 容量三行的阈值绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-10\">十 · 性能与韧性两行的联合判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-11\">十一 · 责任人与复测触发的工程约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-12\">十二 · 填表时的两个硬性判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-13\">十三 · 速查表的失效边界：阈值口径、测量口径与降级路径的交叉验证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-14\">十四 · 阈值的来源：从 SLO 反推，而非拍脑袋</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-15\">十五 · 正确性类的阈值口径：一致率与回放的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-16\">十六 · 性能类：尾块效率与 SLO 达标要用分位数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-17\">十七 · 容量与带宽：水位与利用率的测量姿势</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-18\">十八 · 没有数字时怎么测：把测量方法写进清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-19\">十九 · 阈值怎么定：从口径到复测触发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-20\">二十 · 正确性类坑：一致率只在小批量上成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-21\">二十一 · 精度回归坑：均值掩盖长尾专家退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-22\">二十二 · 容量与带宽坑：尾块效率与水位口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-23\">二十三 · 韧性坑：CUDA Graph 与降级路径联合验证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-24\">二十四 · 检查顺序与回滚方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-25\">二十五 · 失效边界：三类坑为何在清单里最难被抓住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-26\">二十六 · 清单在依赖链上的位置：它是汇聚点，不是起点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-27\">二十七 · 上游依赖：口径必须先于清单存在</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-28\">二十八 · 下游影响：清单输出直接约束上线后的运维动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-29\">二十九 · 与其他条目的边界：谁定义、谁测量、谁判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-moe-launch-checklist-sec-30\">三十 · 在全书中的位置：从机制到判定的收口</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-moe-launch-checklist\"><svg style=\"max-width:510px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 509.6 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"427.6\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：MoE上线前清单</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">逐项核对：路由 top-k 一致率、容量因子与丢弃率上限、分组 </text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">GEMM 尾块…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"427.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-moe-launch-checklist-sec-1\">一 · 清单条目的准确定义：从“检查动作”到“可判定断言”</h3>\n<p>《MoE 上线前清单》不是一份“注意事项汇总”，而是一组<strong>可判定断言</strong>的集合：每一条都必须能回答三个问题——判定指标是什么、口径怎么算、不通过时执行什么处置动作。把条目写成“关注路由一致性”是无效条目；写成“在目标校准集与目标并发下，量化后路由 top-k 与 FP16/FP8 参考路径的 top-k 集合一致率不低于设定阈值，测量工具为路由日志比对脚本，不通过则回退该层量化方案并复测”才是清单条目。定义上的关键区分在于：<em>条目是部署前的门禁</em>，不是运行时的监控指标，也不是调优建议。监控指标回答“现在怎么样”，清单条目回答“能不能放行”。因此每个条目必须携带四个字段：判定指标与口径、通过阈值、测量方法/工具、不通过时的处置动作；再附加责任人与复测触发条件（权重或校准集变更即触发复测）。缺少“处置动作”的条目在工程上等价于没有——它只能产生告警，不能产生决策。</p>\n<p>由此，清单的“通过”是一个<strong>合取</strong>语义：八个维度全部满足才放行，任一维度不通过即阻断。这与性能调优的“加权折中”逻辑相反。用伪代码表达门禁语义：</p>\n<div class=\"formula\">$$\\text{Release} = \\bigwedge_{i=1}^{8} \\left( \\text{metric}_i \\le \\tau_i \\;\\lor\\; \\text{fallback}_i \\text{ 已执行且复测通过} \\right)$$</div>\n<p>其中 $\\tau_i$ 需按部署容量与 SLO 目标设定，材料未给出具体数值，清单只强制要求“阈值口径明确”。代价层面：门禁本身要消耗测量时间与 GPU 机时——路由一致率比对、精度回归、CUDA Graph 回放验证都需要在目标硬件（B200/GB200 NVL72 级别的 SM100 环境）上跑真实 batch，这部分机时属于上线成本而非推理延迟，但它是<strong>一次性且必须计入发布周期</strong>的固定开销；跳过它的代价是上线后长尾丢弃率超限或降级路径输出错误，后者在 MoE 上表现为特定领域回答质量骤降，排查成本远高于门禁成本。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-2\">二 · 四个分类维度：按“检查对象失效后伤到什么”划分</h3>\n<p>材料给出的分类维度是按检查对象划分的四类：正确性类、容量类、性能类、韧性类。这个划分的工程意义不在于归类整齐，而在于<strong>四类失效的伤害形态不同，因而处置动作的性质不同</strong>。正确性类（路由 top-k 一致率、CUDA Graph 回放正确性、NVFP4/FP8 精度回归）失效产生的是<em>错误输出</em>，处置动作是回退（回退量化方案、回退图捕获路径、回退到 eager），不可协商；容量类（容量因子与丢弃率上限、KV 显存水位、All-to-All 带宽利用率）失效产生的是<em>服务能力不足或 token 丢弃</em>，处置动作是调整容量参数或扩容，属于资源配置问题；性能类（分组 GEMM 尾块效率、分离式预填解码 SLO 达标）失效产生的是<em>指标不达标但输出正确</em>，处置动作是内核或调度调优；韧性类（故障降级路径）失效产生的是<em>故障时行为不可预期</em>，处置动作是修补降级逻辑并联合复测。</p>\n<table class=\"mini\"><thead><tr><th>类别</th><th>条目</th><th>失效伤害</th><th>处置动作性质</th></tr></thead><tbody><tr><td>正确性</td><td>路由 top-k 一致率、CUDA Graph 回放正确性、NVFP4/FP8 精度回归</td><td>错误输出</td><td>回退，阻断放行</td></tr><tr><td>容量</td><td>容量因子与丢弃率上限、KV 显存水位、All-to-All 带宽利用率</td><td>丢弃/能力不足</td><td>调参或扩容</td></tr><tr><td>性能</td><td>分组 GEMM 尾块效率、分离式预填解码 SLO 达标</td><td>指标不达标</td><td>内核/调度调优</td></tr><tr><td>韧性</td><td>故障降级路径</td><td>故障时不可预期</td><td>修补逻辑并联合复测</td></tr></tbody></table>\n<p>分类的第二个用途是<strong>确定测量顺序与耦合关系</strong>。正确性类必须先测：路由一致率与精度回归决定了量化方案是否可用，若量化方案被回退，容量类与性能类的阈值都要在回退后的配置上重测——因为低精度与高精度下的显存水位、GEMM 尾块效率、All-to-All 有效载荷都不同。这就是“复测触发条件”字段存在的理由：权重或校准集变更会同时移动正确性与容量两类指标，清单必须显式记录这种依赖，否则会出现“用旧配置的容量阈值放行了新量化方案”的典型漏洞。举例：某层从 FP8 切到 NVFP4 后，权重体积下降使 KV 显存水位看似更宽松，但路由漂移可能使专家负载分布偏移、容量因子失效，此时容量类条目必须在新的路由分布上重测丢弃率，而不能沿用旧阈值。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-3\">三 · 与相邻概念的区别：门禁、监控、剖析、调优的分界</h3>\n<p>清单条目最容易与三类相邻概念混淆，必须逐一切开。<strong>与运行时监控的区别</strong>：监控是连续采样、面向告警与自动扩缩；清单是离散门禁、面向放行决策。监控可以容忍指标抖动并做滑动窗口平滑，清单条目必须给出确定性的测量口径（例如固定校准集、固定并发档位、固定序列长度分布），否则阈值不可复现。监控发现丢弃率上升时触发扩容，清单发现丢弃率超限时触发阻断——前者是运行期反馈环，后者是发布期单向判定。<strong>与剖析工具链的区别</strong>：剖析回答“时间花在哪、带宽被谁占了”，产出的是归因信息；清单回答“是否达标”，产出的是布尔判定。剖析是清单的测量手段之一（例如用剖析数据计算分组 GEMM 尾块效率、All-to-All 带宽利用率），但剖析结果本身不构成门禁——把剖析报告当清单用，等于用“看起来还行”替代阈值判定。<strong>与调优的区别</strong>：调优是在阈值未达标时搜索配置空间；清单只负责判定与指定处置动作的方向，不负责搜索过程。三者关系可以概括为：剖析提供测量，清单做判定，调优在判定失败后介入。</p>\n<p>另一个必须区分的相邻概念是<strong>“平均吞吐达标”与“清单通过”</strong>。材料明确指出最常见踩坑之一是只核对平均吞吐而忽略分组 GEMM 尾块效率与长尾丢弃率。平均吞吐是一个聚合标量，它可以把尾块效率低下与长尾丢弃掩盖在均值里；而清单条目要求的是<em>分布层面的判定</em>——尾块效率要按块尺寸分布看，丢弃率要按请求长度与并发档位看。工程代价上，这意味着测量成本从“跑一个吞吐基准”上升到“跑一组分层负载”：需要在长序列与高并发档位分别测量，机时增加，但换来的是一条能在上线后长序列场景下不触发丢弃超限的保证。举例：一个 MoE 层在短序列高并发下平均吞吐很好，但分组 GEMM 的尾块（专家被少量 token 命中时的窄块）效率低，长序列请求进入后尾块占比上升，平均吞吐指标仍好看而实际 SLO 已破——清单的分层测量正是为了在放行前暴露这种形态。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-4\">四 · 条目字段的工程语义：阈值口径为何不能由清单本身给定</h3>\n<p>清单要求每个条目携带“判定指标与口径、通过阈值、测量方法/工具、处置动作、责任人、复测触发条件”七列，其中<strong>阈值一列必须留空由部署方填写</strong>。这不是清单的缺陷，而是定义上的必然：容量因子与丢弃率上限、KV 显存水位、SLO 达标这三类阈值都依赖部署容量（GPU 数量、NVL72 机架拓扑、显存规格）与 SLO 目标（首 token 延迟、每 token 延迟、可用性），材料未给出具体数值，任何写死的数字都会在另一种部署下失效。清单能做的是强制“口径明确”：例如丢弃率上限必须声明是在哪个并发档位、哪条序列长度分位上测得的，KV 显存水位必须声明是峰值还是稳态、是否含 KV 压缩后的有效占用。口径不明的阈值在复测时不可比，等于没有阈值。</p>\n<div class=\"formula\">$$\\text{丢弃率} = \\frac{\\#\\{\\text{token 因容量因子溢出被丢弃}\\}}{\\#\\{\\text{路由到该专家的 token}\\}},\\quad \\text{按并发档位与序列长度分位分层统计}$$</div>\n<p>字段语义的第二个要点是<strong>责任人与复测触发条件的绑定</strong>。责任人不是形式字段：正确性类条目的责任人必须有权执行回退（例如决定某层放弃 NVFP4 回到 FP8），容量类条目的责任人必须有权调整容量参数或申请扩容，两类权限不同，混用会导致判定失败后无人能执行处置动作。复测触发条件写成“权重或校准集变更”是材料给出的最小集合，其工程含义是：这两类变更同时移动路由分布与数值精度，因而同时影响正确性与容量两类条目，必须整链复测而非只测变更点。代价上，整链复测意味着每次权重更新都要重跑八维度的测量子集，发布周期被拉长；这是 MoE 相比稠密模型多出的一笔固定成本，清单的价值就在于把这笔成本显式化，而不是让它以线上事故的形式出现。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-5\">五 · 失败模式如何反向定义条目：三个例子</h3>\n<p>材料给出的三个失败模式，恰好对应三类条目的定义漏洞，可以反过来校验条目写得对不对。<strong>其一</strong>，路由 top-k 一致率只在离线小批量上核对，未覆盖低精度量化后的路由漂移——这说明条目定义里“测量方法”一列必须写明测量负载包含量化后路径与目标并发，否则“一致率”这个指标在小批量上通过而在线上失效。量化后路由漂移是独立条目的主题，此处只指出：清单条目的口径必须与量化路径绑定，不能把“离线小批量一致”当作“上线一致”。<strong>其二</strong>，NVFP4/FP8 精度回归只测困惑度均值而不测长尾任务——这说明“判定指标”一列不能只写聚合指标，必须写明分层任务集；均值困惑度对个别专家输出退化不敏感，而 MoE 的退化恰恰是专家粒度的，表现为特定领域回答质量骤降。<strong>其三</strong>，CUDA Graph 回放正确性未与故障降级路径联合验证——这说明正确性类与韧性类条目之间存在<em>联合判定</em>要求：降级时流优先级与同步点变化会使图回放结果与 eager 模式不一致，因此“回放正确性”条目的测量方法必须包含降级切换后的回放比对，而不是只在正常路径上验证。</p>\n<p>这三个例子的共同结构是：<strong>条目失效不是因为阈值定错，而是因为测量口径漏掉了失效发生的那个维度</strong>（量化路径、长尾任务、降级状态）。因此清单条目的定义质量可以用一句话检验：测量口径是否覆盖了该条目失效时最可能出现的运行状态。工程代价上，覆盖这三个维度意味着测量矩阵从“单点”扩成“多点”：量化前后、长短序列、正常与降级，每个维度都增加机时；但漏掉任一维度，对应的失效就会以线上事故形式出现，而 MoE 的专家粒度退化与降级路径不一致都极难在事故后定位。清单的定义工作本质上是在发布前把测量矩阵补齐，用可控的机时换取可判定的放行结论。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-6\">六 · 定义层面的工程判断：条目粒度与可复现性</h3>\n<p>最后落在条目粒度的判断上。清单条目过粗（“检查精度”）不可判定，过细（“检查第 37 层第 12 个专家的 FP8 缩放因子”）不可维护且复测成本爆炸。工程上可用的粒度是<strong>与处置动作对齐</strong>：一个条目对应一个可执行的处置动作。路由一致率对应“回退该层量化方案”，容量因子对应“调整容量参数或扩容”，CUDA Graph 回放对应“回退图捕获路径”，故障降级对应“修补降级逻辑”。凡是一个判定结果会触发两种以上性质不同的处置动作，就应拆成两个条目；凡是两个条目共享同一处置动作且测量口径相同，就应合并以降低复测成本。这个粒度规则直接决定清单的维护成本：条目数乘以复测触发频率就是发布周期的固定开销，而 MoE 的权重与校准集变更频率通常高于稠密模型，粒度设计必须把复测成本当作一等约束。</p>\n<p>可复现性是定义层面的第二个判断。清单条目的测量必须在<em>固定口径</em>下可重复：固定校准集版本、固定并发档位、固定序列长度分位、固定降级触发方式。可复现的判定才能支撑“复测触发条件”字段——权重变更后重跑同一口径，结果可比，才能判断是变好还是变坏。不可复现的测量（例如“跑一下看看”）在清单里没有位置，因为它无法产生放行决策。具体机制上，这意味着每个条目的测量脚本必须把口径参数化并随条目一起版本化，与权重、校准集一同纳入变更管理；代价是测量脚本本身成为需要维护的工程资产，收益是发布门禁的判定在每次复测中保持同一语义。清单的准确定义最终收敛为一句话：<strong>条目是可复现口径下的可判定断言，其粒度由处置动作决定，其阈值由部署容量与 SLO 目标填写，其测量矩阵必须覆盖该条目失效时最可能出现的运行状态</strong>。</p>\n<h3 id=\"ap-moe-launch-checklist-sec-7\">七 · 速查表的七列骨架与填写纪律</h3>\n<p>这张表不是给人读的，是给人照着填、照着判的。七列固定为：检查项、判定指标与口径、通过阈值、测量方法/工具、不通过处置、责任人、复测触发条件。列的顺序即判定顺序——先看口径是否写清，再看阈值是否有出处，最后看处置动作是否可执行。任何一行若“判定指标与口径”写成“精度正常”“带宽够用”这类形容词，该行直接判为未填写，因为上线后无法复现判定。口径必须绑定到具体张量形状、batch 形态与采样窗口，例如路由一致率必须写明“同一 prompt 集合、同一 top-k、eager 与目标后端逐 token 比对”。阈值列不允许留空，也不允许写“按 SLO 定”而不附容量假设；材料未给出具体数值，因此每一行的阈值都必须由部署方在容量规划阶段显式落笔，并在责任人列签字。复测触发条件列是本表的生命力所在：权重变更、校准集变更、并行度变更、CUDA Graph 捕获配置变更，四者任一发生即整行失效重测，而不是等下次发版。</p>\n<div class=\"formula\">$$\\text{行有效性} = \\big(\\text{口径可复现}\\big) \\land \\big(\\text{阈值有容量出处}\\big) \\land \\big(\\text{处置可执行}\\big)$$</div>\n<p>代价在于这张表本身要占一次完整的端到端回归窗口：八项检查若串行执行，按每项需一轮预热加一轮稳态采样计，整表跑完的时间预算是上线前必须预留的固定开销，不能压缩进灰度窗口。具体例子：某次权重从 FP8 切到 NVFP4 后，仅“复测触发条件”一列就应把路由一致率、精度回归、分组 GEMM 尾块效率三行同时置为待复测，而不是只重跑困惑度。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-8\">八 · 正确性三行的口径写法</h3>\n<p>正确性类包含路由 top-k 一致率、CUDA Graph 回放正确性、精度回归三行，它们的共同点是“必须逐样本比对，不接受均值”。路由一致率的口径是：固定一组覆盖长尾领域的 prompt，分别在 eager 参考实现与目标推理后端上取每个 token 的 top-k 专家索引集合，按集合交集计一致率，并额外记录“不一致 token 的专家负载偏移量”——后者才是容量因子失效的前兆。精度回归的口径必须拆成两段：困惑度均值只作为粗筛，真正的判定指标是长尾任务上的逐样本输出退化计数，因为量化后个别专家输出退化在均值上被稀释。CUDA Graph 回放正确性的口径是“图回放输出与 eager 输出逐 token 相等，且在故障降级切换后仍相等”，这一条必须与降级路径联合跑，单独验证图回放没有意义。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判定指标与口径</th><th>测量方法</th><th>不通过处置</th></tr></thead><tbody><tr><td>路由 top-k 一致率</td><td>逐 token 专家集合交集率 + 负载偏移量</td><td>eager 与目标后端同 prompt 集合比对</td><td>回退路由精度或收紧量化范围</td></tr><tr><td>精度回归</td><td>长尾任务逐样本退化计数</td><td>分领域采样，禁用单一均值</td><td>定位退化专家，局部提精度</td></tr><tr><td>CUDA Graph 回放</td><td>图回放与 eager 逐 token 相等（含降级后）</td><td>正常路径 + 强制降级路径各跑一轮</td><td>禁用该图捕获配置，回退 eager</td></tr></tbody></table>\n<p>系统代价：这三行全部是离线或半离线检查，不占在线吞吐，但会占用 GPU 小时；若把精度回归做成全量长尾采样，单轮成本按采样 token 数线性增长，因此口径里必须写明采样上限与分层比例，否则复测无法在窗口内完成。具体例子：NVFP4 权重上线前，若只测困惑度均值通过，而长尾任务退化计数未采，则特定领域回答质量骤降会在灰度期才暴露，此时容量因子已按旧负载分布设定，回滚代价是整批权重重灌。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-9\">九 · 容量三行的阈值绑定</h3>\n<p>容量类包含容量因子与丢弃率上限、KV 显存水位、All-to-All 带宽利用率。这三行的阈值不能独立设定，必须绑定到同一组容量假设：目标并发、目标序列长度分布、专家并行度。容量因子的口径是“在目标并发与最长序列分位下，token 丢弃率不超过设定上限”，注意是分位而非均值——长尾丢弃率才是踩坑点。KV 显存水位的口径是“稳态峰值显存占卡容量的比例上限”，并需注明是否含 CUDA Graph 捕获占用的固定池；图捕获会吃掉一块不可回收显存，水位阈值必须把这部分计入分母之外的单列。All-to-All 带宽利用率的判定指标不是峰值带宽百分比，而是“在目标并发下 All-to-All 阶段占单步延迟的比例上限”，因为带宽打满但被计算掩盖时并不构成瓶颈。</p>\n<div class=\"formula\">$$\\text{丢弃率}_{\\text{分位}} = \\frac{\\#\\{\\text{token} \\mid \\text{专家容量溢出}\\}}{\\#\\text{token}},\\quad \\text{阈值绑定于并发} \\times \\text{序列分位}$$</div>\n<p>代价：容量因子调高直接抬显存与 All-to-All 消息量，调低则抬丢弃率；两者在同一张表里必须成对出现，单看一行会得出错误结论。具体例子：长序列高并发下分组 GEMM 尾块效率下降，等效于专家有效容量缩水，若容量因子仍按短序列标定，丢弃率会在尾部分位超限——这正是“只核对平均吞吐”的典型翻车路径。处置动作应写明“按分位重标容量因子并复测尾块效率”，而不是简单调大因子。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-10\">十 · 性能与韧性两行的联合判定</h3>\n<p>性能类只剩分组 GEMM 尾块效率与 SLO 达标两行，韧性类为故障降级路径。尾块效率的口径是“目标并发下分组 GEMM 的实际有效算力占峰值比例，按专家分组大小的分位统计”，必须与容量因子同行复测，因为容量因子改变分组大小分布。SLO 达标的判定指标是分离式预填解码场景下 TTFT 与 TPOT 的分位达标率，口径需写明预填与解码各自的并发假设，不能合并成一个端到端数字。故障降级路径的口径是“强制触发降级后，输出正确性与 SLO 同时满足”，它与 CUDA Graph 回放正确性行强耦合：降级会改变流优先级与同步点，图回放结果可能与 eager 不一致。</p>\n<ul>\n<li>尾块效率不通过 → 调整分组 GEMM 切分或专家放置，复测容量因子行。</li>\n<li>SLO 不达标 → 先查 All-to-All 阶段延迟占比，再查预填解码配比。</li>\n<li>降级路径不通过 → 冻结该降级策略，图捕获配置回退，重跑回放正确性行。</li>\n</ul>\n<p>代价：降级路径的联合验证需要人为注入故障，占用一次完整回归窗口，且降级后吞吐必然下降，因此阈值里要写明“降级态 SLO 允许的松弛量”，否则责任人会在真实故障时因指标不达标而误判为二次故障。具体例子：降级切换后流优先级变化使图回放与 eager 输出不一致，若该行未与回放正确性行联合跑，上线后表现为降级即输出错误，而非降级即变慢——后者可容忍，前者不可。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-11\">十一 · 责任人与复测触发的工程约束</h3>\n<p>责任人列不是署名，是“谁有权签字放行、谁有权叫停”。正确性三行应由模型侧与推理侧双签，容量与性能行由容量规划方签，韧性行由运维方签；任一行未签，整表不得进入灰度。复测触发条件必须写成布尔表达式而非描述：权重哈希变更 ∨ 校准集哈希变更 ∨ 并行度变更 ∨ 图捕获配置变更 → 对应行置为失效。这条约束的代价是每次微小的校准集调整都会触发精度回归与路由一致率重跑，因此工程上应把校准集版本与权重版本绑定为同一发布单元，减少无效复测。</p>\n<table class=\"mini\"><thead><tr><th>触发条件</th><th>失效行</th><th>复测窗口</th></tr></thead><tbody><tr><td>权重精度变更</td><td>路由一致率、精度回归、尾块效率</td><td>整轮回归</td></tr><tr><td>校准集变更</td><td>精度回归</td><td>分层采样轮</td></tr><tr><td>并行度变更</td><td>容量三行、SLO</td><td>整轮回归</td></tr><tr><td>图捕获配置变更</td><td>回放正确性、降级路径</td><td>联合验证轮</td></tr></tbody></table>\n<p>具体例子：并行度从单机扩展到多机后，All-to-All 带宽利用率与容量因子同时失效，若只重测 SLO 而不重测容量行，丢弃率超限会在扩容后反而恶化——扩容本应改善尾延迟，却因容量因子未随并行度重标定而反向。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-12\">十二 · 填表时的两个硬性判据</h3>\n<p>第一，任何一行的“测量方法/工具”若无法在 CI 中自动执行，该行降级为人工检查并必须在表上标注人工复核人，否则复测触发条件形同虚设。第二，处置动作必须是可回退的配置变更，不允许写“重新训练”或“更换框架”这类跨发布单元的动作，因为上线前清单的时间尺度是小时级，不是周级。这两条判据把速查表从文档变成门禁：八行全绿且全签，才允许进入灰度；任一行红，按处置列执行后整行重测，不接受“已知问题带病上线”。</p>\n<div class=\"formula\">$$\\text{放行} = \\bigwedge_{i=1}^{8}\\big(\\text{绿}_i \\land \\text{签}_i \\land \\text{方法可自动}\\big)$$</div>\n<p>工程判断落在最后一行：CUDA Graph 回放正确性与故障降级路径必须作为一对联合门禁，因为二者的失效模式互相掩盖——图回放单独通过、降级单独通过，联合跑却输出错误，这是本清单里唯一无法靠单行阈值拦住的组合失效。因此表中这两行的“复测触发条件”应共享同一触发器，任一方变更即两行同测，这是填表时最容易被省略、也最不该省略的一格。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-13\">十三 · 速查表的失效边界：阈值口径、测量口径与降级路径的交叉验证</h3>\n<p>这张速查表能照着用，前提是每一行的“口径”与“阈值”同时被钉死。工程上最常见的误用是把判定指标写成单一均值：路由 top-k 一致率若只报离线小批量均值，就掩盖了低精度量化后的路由漂移——正确口径是<b>分位数 + 分桶</b>，即按序列长度桶与并发档位分别统计一致率，并单独报告量化前后 top-k 集合差异的样本占比。容量因子与丢弃率同理，必须报<b>长尾丢弃率</b>而非平均丢弃率，因为均值达标而 P99 超限正是长序列高并发下 token 丢弃超限的直接来源。判定式可写成：给定容量因子 $c$、每专家平均 token 数 $\\bar n$ 与峰值 $n_{\\max}$，丢弃条件为 $n_{\\max} &gt; c\\cdot\\bar n$，故阈值应表述为“在目标并发与序列长度分布下，$P(n_{\\max} &gt; c\\bar n)$ 不超过设定上限”，而不是一个与负载无关的固定数字。</p>\n<p>性能类两行的口径最容易被“平均吞吐”污染。分组 GEMM 尾块效率的判定必须用<b>尾块占比与有效 MMA 利用率</b>，而非整层耗时均值：MoE 在 token 数不能被分组边界整除时，尾块会拉低 tcgen05 的 MMA 占用，均值吞吐看不出这一损失，长序列与高并发下才暴露。分离式预填/解码的 SLO 达标要按<b>预填队列等待与解码 ITL 的联合分布</b>核对，因为预填侧排队会以抖动形式传导到解码侧，单看两侧各自的均值会漏掉耦合失效。这两行的共同代价是显存与带宽：尾块效率下降意味着同样的权重需要更多次搬运，All-to-All 带宽利用率一旦接近链路饱和，NVLink 5 上的通信等待就会挤占解码时间片。</p>\n<p>韧性类是本表最易被跳过的一行，也是失效代价最高的一行。CUDA Graph 回放正确性必须与故障降级路径<b>联合验证</b>：降级时流优先级与同步点发生变化，图捕获时的依赖关系与 eager 模式不再等价，回放结果与 eager 输出不一致即判定不通过。因此该行的测量方法应是“注入降级事件后逐 token 比对图回放与 eager 输出”，处置动作是回退到未捕获路径并重建图，复测触发条件包含权重变更、校准集变更与降级策略变更三者。精度回归行同样要加长尾任务维度：只测困惑度均值无法发现个别专家在 NVFP4/FP8 下的输出退化，表现为特定领域回答质量骤降，故口径应为“分领域长尾任务集上的退化幅度上限”。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判定口径</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>路由 top-k 一致率</td><td>分桶分位数 + 量化前后集合差异占比</td><td>仅离线小批量均值达标</td><td>专家负载偏移，容量因子失效</td></tr><tr><td>容量因子/丢弃率</td><td>目标负载下 P99 长尾丢弃率</td><td>均值达标、长序列超限</td><td>token 丢弃，有效吞吐下降</td></tr><tr><td>分组 GEMM 尾块效率</td><td>尾块占比与 MMA 利用率</td><td>只看整层耗时均值</td><td>权重搬运次数上升，带宽吃紧</td></tr><tr><td>CUDA Graph 回放</td><td>降级注入后逐 token 比对</td><td>未覆盖降级路径</td><td>图与流状态不一致，输出错误</td></tr></tbody></table>\n<p>把这张表当“打勾清单”用是危险的：每一行的阈值都必须由部署容量与 SLO 目标反推，材料未给出可直接套用的数值，因此表中“通过阈值”列应写成<b>由容量与 SLO 导出的表达式</b>而非常数，并在权重、校准集或降级策略变更时强制复测。真正决定上线成败的不是八行是否全绿，而是正确性类与韧性类两行是否在同一负载分布下被联合核对——路由漂移与图回放错误都不会在平均吞吐里留下痕迹，只会在长尾与降级切换的瞬间显形。</p>\n<h3 id=\"ap-moe-launch-checklist-sec-14\">十四 · 阈值的来源：从 SLO 反推，而非拍脑袋</h3>\n<p>清单里每一项都要填“通过阈值”，但材料明确没有给出任何具体数值。这不是缺陷，而是设计意图：MoE 的阈值必须由部署容量与 SLO 目标反推，脱离业务谈“丢弃率应低于 X%”没有意义。工程上正确的做法是把阈值写成一条可复算的不等式链，而不是抄一个行业常数。以容量类为例，丢弃率上限的推导起点是解码侧的单 token 时延预算：设 SLO 要求 P99 首 token 时延为 <span>L</span>，单层 MoE 在 All-to-All 后的最慢专家决定该层完成时刻，则容量因子 <span>c</span> 必须满足最慢专家负载不超过 <span>c·(T/P)</span>（<span>T</span> 为该 batch 总 token 数，<span>P</span> 为专家并行度）。丢弃率 <span>d</span> 与 <span>c</span> 的关系不是线性的，因为路由分布有长尾，所以阈值应表述为“在给定 <span>c</span> 下，长尾丢弃率不超过使 P99 时延恰好等于 <span>L</span> 的那个值”，而不是固定百分比。</p>\n<div class=\"formula\">$$c^\\* = \\arg\\min_{c}\\ \\{\\, c \\mid \\mathrm{P99}(L_{\\text{layer}}) \\le L_{\\text{SLO}} \\ \\wedge\\ d(c) \\le d_{\\max}(c) \\,\\}$$</div>\n<p>测量方法：用生产流量的真实路由分布（不是均匀合成分布）回放，扫 <span>c</span> 的取值，同时记录 P99 层时延与丢弃率两条曲线，交点即阈值。代价在于这次扫描要占用真实 GPU 资源，一次完整扫描在 NVL72 级别上按小时计；因此清单要求把扫描结果固化为“复测触发条件”——权重或校准集变更时必须重跑，因为路由分布会漂移。一个具体例子：某部署在离线小批量上测得丢弃率远低于上限，但生产长序列下专家负载偏移，容量因子失效，丢弃率上升——这正是清单把“路由 top-k 一致率”与“容量因子”并列的原因，两者必须联合标定。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-15\">十五 · 正确性类的阈值口径：一致率与回放的分母</h3>\n<p>路由 top-k 一致率最容易写错的是分母。清单要求的口径是“量化前后同一批输入下 top-k 集合的重合率”，分母是 token 数而非专家数，且必须分层统计：整体一致率会被高频专家稀释，真正决定丢弃率的是长尾专家的 top-k 命中。工程上应报告三个数：整体重合率、长尾分位（按专家负载排序后尾部若干专家的重合率）、以及 top-1 翻转率。top-1 翻转即使整体一致率很高也可能致命，因为翻转意味着该 token 被送到不同专家，容量因子按旧分布设定就会溢出。测量方法是用校准集与生产采样集各跑一遍，对比两套分布下的一致率差值；差值本身就是一个阈值——若生产集一致率显著低于校准集，说明校准数据管线覆盖不足，应回到校准环节而非调阈值。</p>\n<p>CUDA Graph 回放正确性的阈值不是“一致率”，而是布尔判定加覆盖矩阵：清单要求回放结果与 eager 模式逐 token 比对，且必须覆盖故障降级路径。这里的代价是显存与流状态：图捕获时固定的显存池在降级切换后可能与新流的同步点不匹配，导致图与流状态不一致、输出错误。测量方法是构造降级注入（例如模拟某条链路失效触发回退），在降级前后各回放同一图，比对 logits。阈值口径应写成“降级路径上的回放差异为零”，而不是“平均差异小于 epsilon”——平均值会掩盖单点错误。具体例子：降级时流优先级变化使同步点偏移，图回放结果与 eager 不一致，这类问题只在联合验证时暴露，单独测图捕获永远测不出来。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-16\">十六 · 性能类：尾块效率与 SLO 达标要用分位数</h3>\n<p>分组 GEMM 尾块效率是清单里最容易被平均值掩盖的指标。MoE 的分组 GEMM 按专家分组，每组 token 数不等，尾块（不足一个 tile 的余量）占比直接决定 tensor core 利用率。阈值应表述为“尾块浪费的算力占比不超过使该层时延预算被吃掉的份额”，测量方法是按专家分组统计每组 token 数对 tile 尺寸取模的分布，算出加权尾块率：</p>\n<div class=\"formula\">$$\\eta_{\\text{tail}} = \\frac{\\sum_{e} \\big(m_e \\bmod M_{\\text{tile}}\\big)\\,/\\,M_{\\text{tile}}}{\\sum_{e} \\lceil m_e / M_{\\text{tile}} \\rceil}$$</div>\n<p>其中 <span>m_e</span> 是第 <span>e</span> 个专家分到的 token 数，<span>\\(M_{\\text{tile}}\\)</span> 是 tcgen05 MMA 的 tile 高度。这个量必须与丢弃率一起看：容量因子调大能降低丢弃但会增加尾块浪费，两者是同一根杠杆的两端。代价体现在吞吐上——尾块率高的层，其有效 FLOPS 显著低于峰值，且这种损失在高并发下被放大，因为专家负载更倾斜。具体例子：只核对平均吞吐的部署，上线后在长序列高并发下尾块率上升、token 丢弃超限，两条曲线同时恶化，根因是容量因子按平均负载设定而非按分位数设定。因此 SLO 达标的阈值口径必须是 P99 而非均值，测量时用连续批处理下的真实到达分布回放。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-17\">十七 · 容量与带宽：水位与利用率的测量姿势</h3>\n<p>KV 显存水位的阈值不能写成“剩余显存大于某值”，而应写成“在峰值并发下，KV 占用不超过总显存的某一比例，且该比例由最大可接受的重算/换出代价决定”。测量方法是压测到 SLO 边界，记录 KV 占用曲线与 preemption 次数；水位阈值实际是 preemption 次数的函数——一旦开始换出，解码时延就会出现台阶。代价很直接：水位设得保守浪费显存、限制并发，设得激进则在长上下文下触发换出，P99 时延失控。具体例子：分离式预填/解码部署中，预填侧与解码侧的 KV 水位要分别设阈值，因为两侧的显存增长速率不同，共用一条阈值会让解码侧先撞墙。</p>\n<p>All-to-All 带宽利用率的阈值口径是“有效载荷带宽占链路峰值的比例”，分母是 NVLink 5 的物理带宽，分子是扣除协议开销后的专家 token 传输量。测量方法是在真实路由分布下跑一次完整 MoE 前向，用 NCCL/NIXL 的计数接口取每次 All-to-All 的字节数与耗时，算利用率。阈值应设为“使 All-to-All 不成为该层关键路径”的那个利用率下限——换句话说，利用率低不一定是坏事（说明有余量），真正要卡的是“利用率高且抖动大”，因为抖动意味着路由倾斜导致某些 step 的通信时间尖峰。代价在延迟：All-to-All 与分组 GEMM 串行，通信尖峰直接叠加到层时延上。具体例子：路由倾斜时少数专家收到大量 token，All-to-All 的某些对等连接饱和而其他空闲，平均利用率看起来正常，但 P99 通信时间翻倍——所以这个指标也必须看分位数。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-18\">十八 · 没有数字时怎么测：把测量方法写进清单</h3>\n<p>材料明确阈值需按部署容量与 SLO 目标设定，因此清单的每一行都应包含“测量方法/工具”列，且该方法必须可被他人复现。工程上把测量方法写成三段式：输入分布（生产采样还是合成）、扫描变量（容量因子、量化格式、并发度）、观测量（分位数时延、丢弃率、尾块率、带宽利用率）。三段式的好处是复测触发条件可以直接挂在“输入分布变更”上——权重或校准集变更即视为输入分布变更，必须重跑。精度回归的测量尤其要注意：清单要求不只测困惑度均值，还要测长尾任务，因为量化后个别专家输出退化在均值上不可见，表现为特定领域回答质量骤降。测量方法是按领域分层跑小样本评测集，每层单独设阈值，任一层退化即不通过。</p>\n<p>韧性类的故障降级路径没有“阈值”，只有通过/不通过，但它的测量成本最高：需要注入故障并观察降级后的图回放、流状态、以及降级切换期间的输出一致性。代价在于这类测试无法在正常压测中顺带完成，必须单独构造场景，且每次权重变更后降级路径的图捕获都要重做。工程判断是：把降级路径的验证与 CUDA Graph 回放正确性合并为一次联合测试，因为两者共享同一套流与图状态，分开测会漏掉交叉问题。清单的处置动作列应写明“不通过时回退到 eager 模式并记录触发条件”，责任人列写明图捕获的 owner，复测触发条件写明“任何流优先级或同步点配置变更”。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>判定口径</th><th>测量方法</th><th>复测触发</th></tr></thead><tbody><tr><td>路由 top-k 一致率</td><td>整体+长尾分层重合率、top-1 翻转率</td><td>校准集与生产采样集对比回放</td><td>权重/校准集变更</td></tr><tr><td>容量因子与丢弃率</td><td>P99 时延约束下的长尾丢弃率</td><td>扫 c 值，记录双曲线交点</td><td>路由分布漂移</td></tr><tr><td>分组 GEMM 尾块效率</td><td>加权尾块率 η_tail</td><td>按专家统计 token 数对 tile 取模</td><td>tile 尺寸或并行度变更</td></tr><tr><td>KV 显存水位</td><td>峰值并发下 KV 占比与 preemption 次数</td><td>压测至 SLO 边界</td><td>上下文长度上限变更</td></tr><tr><td>All-to-All 带宽利用率</td><td>有效载荷占比及其 P99 抖动</td><td>NCCL/NIXL 计数接口逐 step 采样</td><td>并行拓扑变更</td></tr></tbody></table>\n<p>这张表的关键在于第三列：没有具体数字时，测量方法本身就是交付物。工程判断落在最后一行——并行拓扑变更会同时改变 All-to-All 利用率与尾块率，因此这两项的复测触发条件必须联动，任何拓扑调整都要把两条曲线一起重扫，否则会出现“单项达标、组合失效”的典型上线事故。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-19\">十九 · 阈值怎么定：从口径到复测触发</h3>\n<p>本清单八项里，材料明确要求写清“容量因子与丢弃率上限”“KV 显存水位”“SLO 达标”的口径，却不给具体数值——这不是遗漏，而是刻意的工程约束：阈值必须由部署容量与 SLO 目标反推，任何外部给定的数字都会掩盖容量假设。可操作的定法是把阈值写成容量约束的函数，而不是拍一个百分比。以丢弃率为例，设每层路由 top-k 后进入容量因子的 token 数为 N、容量因子为 c、单专家容量为 C，则溢出丢弃率上界可写成 <span class=\"formula\">$$d_{\\max} \\approx 1 - \\frac{c \\cdot C \\cdot E}{N \\cdot k}$$</span> 其中 E 为专家数、k 为 top-k。工程上先把 d_max 设为 SLO 允许的质量退化边界（长尾任务而非均值），再反解出 c 的下限；c 定得过高会直接抬高分组 GEMM 的尾块浪费与显存驻留，c 定得过低则长序列、高并发下 token 丢弃超限。所以这一项的判定指标必须同时记录“平均丢弃率”和“P99 窗口丢弃率”，只报均值等于没测。</p>\n<p>测量方法要绑定工具与口径，不能只写“观察”。路由一致率用离线小批量对比低精度量化前后的 top-k 集合，但必须把校准集按领域切片，因为量化后的路由漂移往往集中在少数专家上；KV 显存水位按“峰值驻留 / 可用 HBM”口径，在最长序列与最大并发批的联合工况下采样，而不是空载读数；All-to-All 带宽利用率按实际传输字节除以链路理论带宽，配合 NCCL 或 NIXL 的通信计时，注意分母要取该拓扑下的可达带宽而非标称值。分组 GEMM 尾块效率则用“有效 MMA 周期 / 总周期”衡量，尾块碎片化在专家负载偏斜时最严重，必须与丢弃率同窗观测。</p>\n<p>失效条件集中在两处。其一，路由一致率只在离线小批量核对，未覆盖量化后漂移，上线后专家负载分布偏移使容量因子失效、丢弃率上升——这是清单里点名的头号踩坑。其二，CUDA Graph 回放正确性未与故障降级路径联合验证：降级切换时流优先级与同步点变化，图回放结果与 eager 模式不一致，输出错误而非性能下降。因此回放正确性必须包含“降级后重放”用例，判定口径是逐 token 比对而非仅比对首 token。</p>\n<p>速查表每行都要带复测触发条件：权重或校准集变更即触发路由一致率与精度回归复测，拓扑或并行度变更即触发 All-to-All 带宽与 SLO 复测，降级路径改动即触发 CUDA Graph 联合验证。没有触发条件的阈值只是一次性快照，无法支撑持续上线。</p>\n<h3 id=\"ap-moe-launch-checklist-sec-20\">二十 · 正确性类坑：一致率只在小批量上成立</h3>\n<p>清单里正确性类最容易糊弄过去的一项，是路由 top-k 一致率。团队通常的做法是拿一个离线小批量、用 eager 模式跑一遍参考路由，再和低精度推理路径的 top-k 输出比对，一致率好看就签字。问题在于这个比对没有覆盖量化后的路由漂移：校准集只喂了通用语料，长尾领域的 token 在 NVFP4/FP8 下激活分布被压扁，router 的 argmax 在若干专家之间来回跳，离线一致率仍然漂亮，上线后专家负载分布却整体偏移，容量因子按旧分布算出来的余量瞬间失效，丢弃率随之上升。这不是精度问题，是分布问题，离线小批量根本采样不到。</p>\n<p>机制上要把一致率拆成两层核对。第一层是逐 token 的 top-k 集合重合度，用 Jaccard 或直接集合相等判定；第二层是聚合层的专家负载直方图偏移，即同一批请求在参考路径与量化路径下各专家承接 token 数的相对偏差。第二层才是容量因子失效的前兆。伪代码思路：</p>\n<div class=\"formula\">$$\\text{drift}_e=\\frac{\\left|n_e^{\\text{fp}}-n_e^{\\text{q}}\\right|}{\\max(n_e^{\\text{fp}},\\epsilon)},\\quad \\text{gate}=\\max_e \\text{drift}_e \\le \\tau_{\\text{load}}$$</div>\n<p>代价落在测量预算上：要覆盖长尾就必须按领域分层采样，每个领域单独算一致率与负载偏移，测量成本随领域数线性上升，且每次权重或校准集变更都要复测。具体例子：一个多语言 MoE，通用语料一致率达标，但按语言分层后发现某低资源语种的负载偏移集中在两三个专家上，正是容量因子被打满的那几个，上线后该语种请求的丢弃率会先于整体指标恶化。处置动作不是调容量因子，而是回到校准数据管线补该语种的样本，重跑量化再复测——这条处置链要写进清单的责任人栏，否则没人认领。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-21\">二十一 · 精度回归坑：均值掩盖长尾专家退化</h3>\n<p>NVFP4/FP8 精度回归只测困惑度均值，是清单里第二个高频坑。困惑度是全体 token 的平均，个别专家输出退化在均值上被稀释到看不见；上线后表现为特定领域回答质量骤降，而整体指标毫无异常。MoE 的特殊性在于退化是专家局部的：某个专家被量化后权重动态范围被压，它承接的那部分 token 全部受影响，但这些 token 在通用评测集里占比极小。</p>\n<p>核对口径要改成按专家分层加按任务分层。按专家分层：对每个专家单独统计其承接 token 上的输出偏差（相对参考路径的 KL 或 top-1 一致率），找出偏差最大的专家集合；按任务分层：长尾任务集单独跑，不看均值看最差分位。判定指标写成“单专家偏差上界 + 长尾任务最差分位”，而不是一个全局均值。代价是评测吞吐：分层评测要把请求按路由结果重新分组，等于在评测阶段引入一次额外的分组开销，且长尾任务集规模小、方差大，需要重复采样才能稳定判定，测量时间显著长于均值评测。</p>\n<p>具体例子：一个代码与通用混合的 MoE，均值困惑度回归通过，但按专家分层后发现承接代码 token 的几个专家 top-1 一致率明显低于其他专家，长尾任务集上代码补全的最差分位掉档。处置动作是这几个专家回退到更高精度（混合精度专家表），而不是整模型回退——整模型回退会把已经通过的专家一起拖慢。复测触发条件写死为“专家精度表变更或校准集增删样本”，因为混合精度方案让专家表本身成了可变状态。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-22\">二十二 · 容量与带宽坑：尾块效率与水位口径</h3>\n<p>容量类三项——容量因子与丢弃率上限、KV 显存水位、All-to-All 带宽利用率——最常见的坑是只核对平均吞吐。分组 GEMM 的尾块效率在平均吞吐里几乎不可见：分组 GEMM 按专家分组后，每组 token 数不均，尾块（不足一个 tile 的余量）在小组上占比高，SM 利用率被拉低，但平均吞吐被大组摊平。上线后在长序列或高并发下，小组数量增多、尾块占比上升，同时丢弃率随容量因子打满而超限，两个恶化叠加，平均吞吐的漂亮数字完全无法预警。</p>\n<p>核对方法要把尾块效率单列成指标：统计每个分组 GEMM 调用中尾块 token 数占总 token 数的比例，以及尾块所在组的 SM 占用时长占比。判定不看单次调用，看高并发压力下的分位。KV 显存水位的坑在于口径：水位要按“峰值 + 预留”算，且要区分预填阶段与解码阶段的峰值形态，分离式预填解码下两阶段的显存峰值出现在不同实例上，合并统计会低估单实例峰值。All-to-All 带宽利用率的坑在于只测空载带宽：真实负载下 All-to-All 与分组 GEMM 交替，带宽利用率受同步点影响，空载测出来的高利用率不代表叠加负载下仍成立。</p>\n<p>代价直接体现在容量规划上：尾块效率低意味着同样的 SLO 需要更多副本，KV 水位口径错意味着按低估的峰值配显存会在长序列下 OOM，带宽利用率虚高意味着并行度可以少配、实际却不够。具体例子：一个高并发短序列场景，平均吞吐达标，但尾块效率在高并发分位上明显偏低，同时丢弃率在容量因子打满时超限；处置动作是调分组 GEMM 的 tile 策略与容量因子联动复核，而不是单独调其中一个——两者共享同一批 token 分布假设。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-23\">二十三 · 韧性坑：CUDA Graph 与降级路径联合验证</h3>\n<p>CUDA Graph 回放正确性未覆盖故障降级路径，是最隐蔽的一类坑。图捕获时固定了流、同步点与内存地址；降级切换（例如某条路径不可用、切到备用执行路径）会改变流优先级与同步点，图回放的结果与 eager 模式不一致，输出错误但不报错。清单里如果只验证“正常路径下图回放与 eager 一致”，这一项等于没查。</p>\n<p>核对机制是把回放正确性做成矩阵：行是执行路径（正常、各降级档位），列是输入形态（短序列、长序列、高并发），每个格子比对图回放输出与 eager 参考输出的逐 token 一致率。降级档位要显式枚举，不能只测“降级后能跑”。判定指标是每个格子的逐 token 一致率下限，任一格子不达标即整项不通过。代价是验证组合数随档位数与输入形态数相乘增长，且每次图结构或降级逻辑变更都要全矩阵复测；工程上通常把矩阵裁剪成“正常路径全覆盖 + 每个降级档位抽一个代表形态”，但裁剪规则本身要写进清单，否则下次变更时没人知道哪些格子被豁免过。</p>\n<p>具体例子：降级切换后流优先级变化，图回放里某个跨流依赖的同步点被跳过，单步输出看似正常，多步累积后与 eager 分叉。这种错误在短序列上不显现，长序列高并发下才暴露。处置动作是降级路径要么重新捕获图、要么强制回退 eager，二选一写死，不允许“沿用旧图”。复测触发条件写为“图捕获参数、降级档位定义、流优先级配置任一变更”。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-24\">二十四 · 检查顺序与回滚方案</h3>\n<p>检查顺序不是按清单条目编号走，而是按依赖关系走：正确性类先行，因为容量与性能的判定都建立在路由与精度正确的前提上；容量类次之，因为尾块效率与带宽利用率的测量需要容量参数已定；性能类再次，SLO 达标要在容量与带宽口径确认后才有意义；韧性类最后，因为降级路径的验证要覆盖前面所有路径形态。顺序错了的代价是返工：先测 SLO 再发现路由漂移，所有 SLO 数据作废重测。</p>\n<p>回滚方案要按“变更类型”而不是“故障现象”组织。权重与校准集变更触发精度与路由复测，回滚点是上一版权重加对应校准集，两者必须成对回滚——只回权重不回校准集，量化参数与权重不匹配，路由漂移照样发生。容量因子与分组 GEMM 策略变更触发容量与性能复测，回滚点是上一版配置快照，且快照要包含 tile 策略与容量因子的联合取值。图捕获与降级逻辑变更触发韧性矩阵复测，回滚点是上一版图结构与降级档位定义。每类回滚都要写明回滚后的验证动作：回滚不是终点，回滚后要重跑该类对应的最小核对集，确认回滚本身没有引入新偏差。</p>\n<p>具体工程判断：清单上每一项的“不通过处置动作”必须落到可执行的回滚点，而不是“排查”“优化”这类动词。凡是没有明确回滚点的检查项，等于没有通过判定——因为不通过时团队会倾向就地调参而不是回滚，就地调参会让状态偏离已知良好版本，下一次故障时无法定位基线。责任人栏与复测触发条件栏的作用正在于此：把“谁在什么变更后必须重跑哪一项”固定下来，让清单在权重、校准集、配置、图结构四类变更下都能自动收敛到已知良好状态。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-25\">二十五 · 失效边界：三类坑为何在清单里最难被抓住</h3>\n<p>清单最容易失守的地方不是漏项，而是“测了口径、没测边界”。路由 top-k 一致率若只在离线小批量、未量化权重上核对，量化为 NVFP4/FP8 后路由分数分布发生漂移，top-k 集合在临界样本上翻转，专家负载随之偏移——容量因子按旧分布设定，长尾专家被挤爆，丢弃率在高并发下超限。这类失效的代价是双重的：一方面 token 丢弃直接损伤生成质量，另一方面负载不均使 All-to-All 出现热点链路，带宽利用率在少数 rank 上饱和而整体利用率虚低，吞吐看似达标、尾延迟却塌陷。判定口径必须写成“量化后、目标 batch 分布下、按专家维度的 top-k 一致率与负载偏度”，而非单一平均值。</p>\n<p>第二类坑在精度回归：只测困惑度均值，长尾任务上个别专家的输出退化被均值掩盖，表现为特定领域回答质量骤降。回归集必须按专家覆盖率分层抽样，并把“单专家输出分布偏移”作为独立判定项，与整体困惑度并列。第三类坑在 CUDA Graph 回放与故障降级路径的联合验证：降级切换会改变流优先级与同步点，图捕获时的流状态与降级后的 eager 路径不一致，回放结果与 eager 输出出现偏差。检查顺序上应把“降级后重放同一 batch、比对图与 eager 输出”作为独立步骤，而不是在正常路径通过后就判定回放正确。系统代价体现在复测成本：权重或校准集任一变更都会触发路由一致率与精度回归的复测，这部分机时必须在容量规划里预留，否则上线窗口会被复测挤占。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被掩盖的指标</th><th>系统代价</th><th>处置动作</th></tr></thead><tbody><tr><td>路由一致率仅离线小批量核对</td><td>量化后专家负载偏度</td><td>长尾丢弃率超限、All-to-All 热点</td><td>量化后按目标分布复测，重设容量因子</td></tr><tr><td>精度回归只测困惑度均值</td><td>单专家长尾任务退化</td><td>特定领域质量骤降</td><td>分层回归集，单专家分布偏移独立判定</td></tr><tr><td>图回放未联合降级路径验证</td><td>降级后图与流状态一致性</td><td>输出错误、SLO 不可信</td><td>降级后重放比对，纳入回滚触发条件</td></tr></tbody></table>\n<div class=\"formula\">$$\\text{丢弃率上限} \\;=\\; \\frac{\\text{容量因子}\\times\\text{每专家容量}-\\text{实际到达 token 数}}{\\text{实际到达 token 数}}\\Big|_{\\text{高并发长序列}}$$</div>\n<p>回滚方案要挂在这三条失效路径上：路由漂移与丢弃率超限触发回滚到上一版容量因子与量化校准集；单专家退化触发回滚到更高精度权重；图回放与降级不一致则回滚到 eager 路径并冻结图捕获，直到流状态对齐验证通过。回滚本身也有代价——重新加载权重与重建图捕获会打断连续批处理，KV 显存水位在切换窗口内需要额外预留，否则回滚期间的请求会因显存不足被拒。</p>\n<h3 id=\"ap-moe-launch-checklist-sec-26\">二十六 · 清单在依赖链上的位置：它是汇聚点，不是起点</h3>\n<p>MoE 上线前清单在整条工程链上处于“汇聚”位置：它不生产任何新指标，只把上游各条目已经产出的判定口径收拢成一次可执行的核对。路由一致性来自路由术语与量化后路由漂移两条条目，容量因子与丢弃率来自容量因子条目，分组 GEMM 尾块效率来自分组 GEMM 与 tcgen05 条目，NVFP4/FP8 精度回归来自低精度条目与校准数据管线，KV 显存水位来自 MoE 场景 KV 压缩，All-to-All 带宽利用率来自专家并行条目，SLO 达标来自分离式预填解码，CUDA Graph 回放正确性与故障降级来自框架选型与剖析工具链。清单的每一项都必须能指回一个上游条目，否则这一项就是悬空的——它没有口径来源，也就没有复测触发条件。</p>\n<p>这条依赖关系决定了清单的写法：每一项不是“要不要检查”，而是“上游条目给出的口径是什么、本项只做判定”。以容量类为例，容量因子与丢弃率上限的阈值不是清单自己拍的，而是由部署容量与 SLO 目标反推出来的；清单只负责确认这个阈值已经被写进配置、被测量方法覆盖、被处置动作绑定。工程代价在这里体现为人力而非算力：一项悬空的检查项会在上线后以一次故障的形式补课，而一次 MoE 故障的定位成本通常高于整条清单的执行成本。</p>\n<p>具体机制上，清单的每一项应携带三个字段：判定指标与口径、测量方法/工具、复测触发条件。复测触发条件是依赖链的显式化——权重变更触发精度回归与路由一致性复测，校准集变更触发精度回归复测，并行度或拓扑变更触发 All-to-All 带宽利用率与 SLO 复测。把触发条件写进清单，等于把上游条目的变更管理接进了上线流程。</p>\n<div class=\"formula\">$$\\text{清单通过} = \\bigwedge_{i \\in \\{1..8\\}} \\big( \\text{口径}_i \\neq \\varnothing \\;\\wedge\\; \\text{测量}_i \\neq \\varnothing \\;\\wedge\\; \\text{处置}_i \\neq \\varnothing \\;\\wedge\\; \\text{复测}_i \\neq \\varnothing \\big)$$</div>\n<p>这个合取式说明清单不是加权评分：任何一项缺字段即整体不通过，因为缺字段的那一项在上线后无法被判定，等价于没有检查。一个具体例子：若“All-to-All 带宽利用率”一项只写了“观察 NCCL 带宽”而没有写拓扑变更后的复测触发条件，那么当集群从单机 NVLink 域扩到跨机架时，这一项不会自动重跑，专家并行的通信瓶颈就会以尾延迟的形式出现在线上。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-27\">二十七 · 上游依赖：口径必须先于清单存在</h3>\n<p>清单对上游的依赖是刚性的，因为清单本身不做测量设计。路由 top-k 一致率的口径必须由路由条目定义清楚：比的是 top-k 集合还是带权排序、在什么 batch 形态下比、eager 与图回放两种模式下是否分别比。若上游只给了“一致率”三个字，清单这一项就无法判定通过与否。同理，分组 GEMM 尾块效率的口径必须区分“平均 tile 利用率”与“尾块占比”，因为前者会被大 batch 掩盖，后者才暴露长尾。</p>\n<p>上游依赖的第二个层面是工具链。剖析工具链条目决定了清单里每一项的测量方法是否可复现：路由一致性需要能 dump 路由 logits 与 top-k 索引的钩子，精度回归需要能按专家切分的评测脚本，CUDA Graph 回放正确性需要能在图捕获与回放之间对比输出的差分工具。清单不发明工具，只引用工具；工具缺失时清单应判不通过，而不是降级为人工目测。</p>\n<p>代价在这里是显存与带宽的测量开销：精度回归与路由一致性核对通常需要保留中间激活与路由张量，在长序列高并发下这批中间量会推高显存水位，与 KV 显存水位一项互相挤占。工程判断是把正确性类核对放在离线固定 batch 上跑，把容量类核对放在接近目标并发的压测上跑，两类不混在同一轮里，避免测量本身改变被测对象。</p>\n<p>一个具体例子：量化后路由漂移条目指出低精度量化会改变专家选择分布，因此清单中“路由 top-k 一致率”一项的基线必须是量化前的同一权重、同一校准集下的路由输出，而不是原始浮点模型的路由输出。基线选错，这一项会给出虚假的通过。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-28\">二十八 · 下游影响：清单输出直接约束上线后的运维动作</h3>\n<p>清单的产出不是一张通过/不通过的表，而是一组被固化的阈值与处置动作，它们在上线后成为告警规则与降级策略的输入。容量因子与丢弃率上限一旦通过，就成为线上丢弃率告警的门限；KV 显存水位一旦通过，就成为驱逐与抢占策略的触发点；SLO 达标一旦通过，就成为分离式预填解码的扩容判据。清单若只写“通过”，不写“通过时的阈值是多少”，下游运维就没有可继承的参数。</p>\n<p>韧性类的下游影响最直接。故障降级路径一项要求 CUDA Graph 回放正确性与降级路径联合验证，因为降级时流优先级与同步点会变化，图回放结果可能与 eager 模式不一致。清单通过意味着这条降级路径已经被演练过；清单不通过意味着线上任何一次降级都可能产出错误输出而非仅仅变慢。这是清单里唯一一项“不通过即禁止上线”的硬性项，因为它影响的是正确性而非性能。</p>\n<p>下游影响还体现在容量规划上。All-to-All 带宽利用率与分组 GEMM 尾块效率两项的通过阈值共同决定了单副本能承载的并发上限；容量规划条目据此推算副本数与扩缩容曲线。清单若把这两项的测量条件写成“实验室单机”，下游容量规划就会高估单机吞吐，跨机架部署时出现通信成为瓶颈、尾块效率塌陷的双重问题。</p>\n<p>具体机制上，清单应把每一项的处置动作写成可执行的分支：不通过时是回退权重、调低容量因子、增加副本、还是禁用图回放改走 eager。分支必须与故障降级路径共用同一套开关，否则上线后会出现“清单说回退、运维做了扩容”的口径分裂。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-29\">二十九 · 与其他条目的边界：谁定义、谁测量、谁判定</h3>\n<p>清单与同模块其他条目共享同一批读者，因此边界必须写死，否则内容会互相复述。规则是：术语与定义由速查类条目给，阈值推导由容量因子条目给，并行与通信机制由专家并行条目给，算子与精度机制由分组 GEMM 与低精度条目给，框架行为由框架选型条目给，测量工具由剖析工具链条目给；清单只做三件事——引用口径、规定判定、绑定处置与复测。任何一条在清单里展开机制解释，都是越界。</p>\n<table class=\"mini\"><thead><tr><th>清单维度</th><th>口径来源条目</th><th>清单只负责</th></tr></thead><tbody><tr><td>路由 top-k 一致率</td><td>路由术语速查、量化后路由漂移</td><td>基线选择、判定、权重变更复测</td></tr><tr><td>容量因子与丢弃率上限</td><td>容量因子与丢弃代价</td><td>阈值入配置、丢弃率告警绑定</td></tr><tr><td>分组 GEMM 尾块效率</td><td>分组 GEMM 与 tcgen05</td><td>尾块口径确认、压测条件</td></tr><tr><td>NVFP4/FP8 精度回归</td><td>低精度条目、校准数据管线</td><td>长尾任务覆盖、校准集变更复测</td></tr><tr><td>KV 显存水位</td><td>MoE 场景 KV 压缩</td><td>水位阈值、与正确性核对的隔离</td></tr><tr><td>All-to-All 带宽利用率</td><td>专家并行与 All-to-All</td><td>拓扑变更复测、容量规划输入</td></tr><tr><td>分离式预填解码 SLO</td><td>分离式预填解码</td><td>SLO 达标判定、扩容判据</td></tr><tr><td>CUDA Graph 回放与降级</td><td>框架选型、剖析工具链</td><td>联合验证、降级开关一致性</td></tr></tbody></table>\n<p>这张表本身就是边界声明：右列之外的内容不属于本清单。工程代价是清单变薄——它不能自解释，读者必须顺着左列去读对应条目。但这正是全书结构的意义：清单是可执行的最后一公里，不是知识本身。</p>\n<p>一个具体例子：精度回归一项在清单里只写“覆盖长尾任务、按专家切分比对、校准集变更即复测”，不解释 NVFP4 的缩放因子机制；机制解释留给低精度条目。若清单里重复解释机制，读者会在两处读到同一段话，而真正需要的“长尾任务清单”反而没有篇幅写。</p>\n\n<h3 id=\"ap-moe-launch-checklist-sec-30\">三十 · 在全书中的位置：从机制到判定的收口</h3>\n<p>把全书按“机制—测量—判定”三层排布，清单位于第三层的最末端。算子与数值精度、显存与 KV、批调度、并行与通信、框架属于机制层；剖析工具链与校准数据管线属于测量层；容量规划与 SLO 属于判定层的上游；清单是判定层的收口。它不产生新知识，只把前两层已经确定的东西压缩成一次可审计的核对，因此它的价值随上游条目的完备度上升而上升——上游口径越清晰，清单越短。</p>\n<p>这个位置决定了清单的失效模式：当上游条目缺失时，清单不会报错，只会静默地少一项或写一个含糊的口径。前文列出的三类失败模式都源于此：路由一致性只在离线小批量核对，是因为路由条目没有定义量化后基线；精度回归只测困惑度均值，是因为低精度条目没有给出长尾任务口径；图回放未与降级联合验证，是因为框架条目没有把降级开关与图状态绑定。清单无法修补上游，只能暴露上游的缺口。</p>\n<p>因此清单的工程判断是：先审计上游，再执行清单。审计方式是逐项追问“这一项的口径写在哪一条目里、测量工具由谁提供、阈值由谁推导”。三项都能指回具体条目，这一项才算可执行；任何一项指不回去，应先补上游条目而不是在清单里临时定义。这条判断把清单从“上线前一天的救火表”变成“条目完备度的体检表”。</p>\n<p>具体机制上，清单执行应分两轮：第一轮只做口径审计，不跑测量，产出缺口列表；第二轮在缺口补齐后跑测量与判定。两轮分离的代价是时间，收益是避免用错误的基线跑出一份看起来通过的报告——后者比不跑更危险，因为它会把未验证的正确性带入生产。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-moe-launch-checklist\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>逐项核对：路由 top-k 一致率、容量因子与丢弃率上限、分组 GEMM 尾块效率、NVFP4/FP8 精度回…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-moe-launch-checklist · 共 5 个片段</p>\n"},{"id":"ap-model-data-license","title":"模型与数据许可","summary":"说明 MoE 权重与校准数据的许可边界：开源权重商用条款、校准集不得含未授权个人数据、量化重分发时的许可证继承、以及 NVL72 多租户部署下 KV cache 与日志的留存与跨境传输合规要求。","kind":"合规","long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-1\">一 · 合规对象：条目究竟在界定什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-2\">二 · 四个分类维度及其判定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-3\">三 · 速查表的列结构与填写纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-4\">四 · 与相邻条目的边界：只指路，不重讲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-5\">五 · 失败模式的分类学：三种断点各自对应哪一维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-6\">六 · 工程判断：把许可做成可执行的元数据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-7\">七 · 速查表的列结构与取值口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-8\">八 · 权重许可行：商用条款与衍生量化权重</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-9\">九 · 校准数据行：来源核验与授权凭证</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-10\">十 · 分发许可行：许可证继承与声明义务的落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-11\">十一 · 部署合规行：多租户 KV cache 与日志的留存与跨境</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-12\">十二 · 审计证据列与填表纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-13\">十三 · 阈值不是常数，是合同与法规的函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-14\">十四 · 权重许可的阈值：衍生量化权重的继承判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-15\">十五 · 校准集的授权核验：测什么、怎么测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-16\">十六 · 多租户下的 KV cache 与日志：留存与隔离的可测边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-17\">十七 · 审计证据的落盘：把阈值变成可查的记录</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-18\">十八 · 合规阈值的可测量化：从“没有数字”到可审计的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-19\">十九 · 量化重分发：许可证继承的三处断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-20\">二十 · 校准集：个人数据授权核验的前置卡点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-21\">二十一 · NVL72 多租户：KV cache 与日志的残留面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-22\">二十二 · 跨境传输：合法性依据与留存证据的绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-23\">二十三 · 回滚方案：许可证缺口的分级处置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-24\">二十四 · 量化重分发与多租户残留：三条失效链的检查顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-25\">二十五 · 上游依赖：许可条目从哪些条目取输入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-26\">二十六 · 下游影响：许可判定如何改变推理系统的实现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-27\">二十七 · 与量化条目的接口：许可继承判定发生在哪一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-28\">二十八 · 与部署条目的接口：多租户边界决定合规粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"ap-model-data-license-sec-29\">二十九 · 在全书中的位置：横切约束而非性能条目</button></li></ol></nav><figure class=\"diagram\" data-fig=\"app-ap-model-data-license\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550.9 319\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"468.9\" height=\"83.0\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"53.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"57.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条目：模型与数据许可</text><text x=\"75.0\" y=\"62.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">说明 MoE 权重与校准数据的许可边界：开源权重商用条款、校准集不得含</text><text x=\"75.0\" y=\"78.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"start\">未授权个…</text><line x1=\"82.0\" y1=\"97.0\" x2=\"82.0\" y2=\"114.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 113.0 L 86.5 113.0 L 82.0 121.0 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"121.0\" width=\"468.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"143.5\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"147.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"148.7\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">关键点</text><line x1=\"82.0\" y1=\"167.9\" x2=\"82.0\" y2=\"184.9\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 183.9 L 86.5 183.9 L 82.0 191.9 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"191.9\" width=\"468.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"214.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"218.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"219.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用法</text><line x1=\"82.0\" y1=\"238.7\" x2=\"82.0\" y2=\"255.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 254.8 L 86.5 254.8 L 82.0 262.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"262.8\" width=\"468.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"285.2\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"289.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"290.4\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">边界</text></svg><figcaption><b>条目结构</b> · 这个附录条目的四段结构；正文按同一顺序展开。</figcaption></figure>\n<h3 id=\"ap-model-data-license-sec-1\">一 · 合规对象：条目究竟在界定什么</h3>\n<p>《模型与数据许可》在 MoE 推理工程里不是一个法律附录，而是一条会直接改变部署拓扑与数据流走向的约束。它的准确定义是：<strong>对一次 MoE 推理服务所涉及的权重、校准数据、量化产物、运行时残留物（KV cache 与请求日志）四类客体，逐类确定其使用边界、分发条件与留存规则</strong>。注意这里的主语是“客体”而不是“模型”——同一个模型在权重层面可能允许商用，但其 NVFP4 校准集若混入未授权个人数据，整条量化链路就不可分发。条目之所以必须按客体拆分，是因为 MoE 的推理栈天然把一份模型拆成了多份可独立流转的物料：原始 BF16/FP8 权重、按专家分片的权重、量化缩放因子（scale）、校准集、以及运行时生成的 KV cache。任何一份物料的许可状态与其他物料不同，都会在分发或审计时形成断点。</p>\n<p>与相邻概念的区别要一次讲清，避免后续混淆。<strong>模型许可证（如权重附带的商用条款）</strong>管的是权重本身的复制、修改与商用；<strong>数据许可</strong>管的是校准集、评测集、提示词与日志中个人数据的处理合法性；<strong>服务条款/SLA</strong>管的是你向租户承诺的性能与可用性，与许可无关；<strong>出口管制与跨境传输规则</strong>管的是数据与技术的物理流向。本条目是这四者的交集，但只落在推理侧：它不涉及训练配方，也不涉及产品评测。工程上判断一个事项是否属于本条目，用一个简单判据：<em>该事项是否改变了“哪份物料可以被谁在何处保留多久”</em>。改变则是，不改变则不是。</p>\n<p>代价维度上，合规不是零成本标签。以 NVL72 多租户部署为例，为满足按租户隔离与限期删除，KV cache 的分配器必须从全局池改为带租户标签的分区池，这会牺牲显存复用率：原本可跨请求复用的前缀缓存（prefix cache）在跨租户时不可共享，等效于可用 KV 显存下降，进而压低最大并发批大小与吞吐。日志侧同理，逐请求打租户标签并写入带 TTL 的存储，会增加写放大与审计查询延迟。这些是真实的推理系统代价，必须在容量规划时计入，而不是事后补丁。</p>\n\n<h3 id=\"ap-model-data-license-sec-2\">二 · 四个分类维度及其判定顺序</h3>\n<p>条目按合规对象划分为四个维度，工程上应固定判定顺序，因为后一维度的结论依赖前一维度。<strong>权重许可</strong>：确定原始权重允许的商用范围，以及衍生量化权重是否继承原许可。<strong>数据许可</strong>：确定校准集来源与个人数据授权凭证。<strong>分发许可</strong>：确定量化重分发时的许可证继承与声明、署名义务。<strong>部署合规</strong>：确定多租户隔离下 KV cache 与日志的留存期限与跨境传输合法性依据。</p>\n<p>判定顺序之所以重要，可用一个伪代码思路表达：</p>\n<div class=\"formula\">$$\n\\begin{aligned}\n&amp;\\text{if } \\neg\\,\\text{weight\\_license.permits\\_commercial} \\Rightarrow \\text{stop}\\\\\n&amp;\\text{if } \\neg\\,\\text{calib\\_set.has\\_personal\\_data\\_grant} \\Rightarrow \\text{block\\_quantize}\\\\\n&amp;\\text{if } \\text{redistribute}(W_q) \\wedge \\neg\\,\\text{inherit}(W_q, W) \\Rightarrow \\text{block\\_distribute}\\\\\n&amp;\\text{if } \\text{multi\\_tenant} \\wedge \\neg\\,\\text{isolate\\_and\\_ttl}(KV,\\,log) \\Rightarrow \\text{block\\_deploy}\n\\end{aligned}\n$$</div>\n<p>第一行是硬闸门：权重不允许商用，后续全部无意义。第二行是量化前置条件——校准集未做个人数据授权核验时，量化过程本身即接触未授权数据，且校准产物（scale、量化后的专家权重）会随权重一并分发，污染面被放大。第三行针对最常见的踩坑：把量化后的 NVFP4/FP8 权重当作新模型独立分发。第四行才进入部署侧。把顺序倒过来，典型后果是先建好多租户集群再发现权重不可商用，返工代价落在显存分区与日志存储的重新设计上。</p>\n<p>具体例子：某团队将一份 BF16 MoE 权重用量化校准管线压到 NVFP4，校准集来自公开语料与内部工单摘要的混合。按上述顺序，第二行先触发——工单摘要含个人数据且无授权凭证，量化必须阻断；即便强行量化，第三行也会因未附原许可声明与署名而在分发时越界。这个例子的工程含义是：量化校准数据管线（见该条目）在设计阶段就必须把“来源凭证”作为一等输入，而不是事后补文档。</p>\n\n<h3 id=\"ap-model-data-license-sec-3\">三 · 速查表的列结构与填写纪律</h3>\n<p>条目要求速查表包含固定列：合规对象、适用许可证/条款、允许与禁止行为、声明与署名义务、数据来源与授权凭证、留存期限与跨境传输限制、审计证据留存位置。这七列不是文档模板，而是审计时的取证路径：任何一次分发或一次租户投诉，都必须能沿这七列回溯到具体凭证。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>合规对象</th><th>适用条款</th><th>允许/禁止</th><th>声明与署名</th><th>来源与凭证</th><th>留存与跨境</th><th>审计证据位置</th></tr>\n</thead>\n<tbody>\n<tr><td>原始权重</td><td>权重附带商用条款</td><td>按条款商用；禁止超范围再分发</td><td>保留版权与许可声明</td><td>权重获取记录</td><td>按合同</td><td>制品库元数据</td></tr>\n<tr><td>量化权重（NVFP4/FP8）</td><td>继承原权重许可</td><td>允许随继承条款分发；禁止当作独立新模型</td><td>附原许可与署名、标注衍生</td><td>量化流水线记录</td><td>按合同</td><td>量化产物清单</td></tr>\n<tr><td>校准集</td><td>数据许可与个人数据授权</td><td>仅限已授权样本；禁止混入未授权个人数据</td><td>记录来源与授权范围</td><td>授权凭证</td><td>按法规与合同</td><td>数据集台账</td></tr>\n<tr><td>KV cache</td><td>部署合规</td><td>按租户隔离；禁止跨租户残留</td><td>不适用</td><td>不适用</td><td>限期删除；跨境需合法性依据</td><td>隔离与删除日志</td></tr>\n<tr><td>请求日志</td><td>部署合规</td><td>按租户隔离；禁止无依据跨境</td><td>不适用</td><td>不适用</td><td>限期删除；跨境需合法性依据</td><td>日志存储 TTL 记录</td></tr>\n</tbody>\n</table>\n<p>填写纪律有两条。其一，<strong>“留存期限与跨境传输限制”列不得填经验数字</strong>：材料未给出具体数值，留存期限与跨境传输白名单须按适用法规与合同确定。工程上正确的做法是把该列写成“引用条款编号 + 责任方”，而不是写一个天数。其二，“审计证据留存位置”必须是可机器检索的地址（制品库元数据、数据集台账、日志存储的 TTL 配置），否则审计时无法提供留存证据，等于该行未填。</p>\n<p>代价上，维护这张表本身消耗工程带宽：每次量化产物更新都要同步更新第二、三行，每次租户新增都要更新第四、五行。若把表做成静态文档，漂移不可避免；把它做成流水线中的门禁（gate），则每次分发前自动比对声明与署名是否齐备，代价从人工审计转为流水线延迟——这是可控的、可预算的代价。</p>\n\n<h3 id=\"ap-model-data-license-sec-4\">四 · 与相邻条目的边界：只指路，不重讲</h3>\n<p>本条目与多个工程条目相邻，但职责不重叠，边界必须钉死。<strong>量化校准数据管线</strong>负责数据如何采集、清洗、采样与喂入量化算子；本条目只回答“这批数据有没有授权凭证、能否随产物分发”。<strong>NVFP4/FP8 权重激活</strong>负责数值格式与算子实现；本条目只回答“量化后的权重是不是衍生作品、分发时继承什么条款”。<strong>MoE 场景 KV 压缩</strong>负责压缩算法与显存收益；本条目只回答“压缩后的 KV 在多租户下如何隔离与限期删除”。<strong>分离式预填解码</strong>负责拓扑与传输；本条目只回答“跨节点传输的 KV 与日志是否构成跨境传输、有无合法性依据”。<strong>容量因子与丢弃代价</strong>负责批调度；本条目指出合规分区会压缩可复用 KV 池，从而影响容量因子的取值——但容量因子本身的计算不在本条目展开。</p>\n<p>一个具体机制上的交界例子：前缀缓存跨请求复用是提升吞吐的常规手段，但在多租户下，若两个租户的提示词前缀恰好相同，共享同一份 KV 会构成跨租户数据残留。工程解法是在 KV 分配器中给每个 block 打租户标签，复用判定增加“标签相等”条件。代价是命中率下降，等效吞吐下降；收益是审计时可证明无跨租户残留。这个判断属于本条目，而命中率如何影响批调度属于容量因子条目。</p>\n\n<h3 id=\"ap-model-data-license-sec-5\">五 · 失败模式的分类学：三种断点各自对应哪一维度</h3>\n<p>材料给出三类失败模式，它们恰好一一对应前述维度，可作为分类学的检验。<strong>分发断点</strong>：量化重分发时未继承原权重许可条款、未附声明与署名，导致衍生权重分发越界——对应分发许可维度。其机制是许可证继承关系被“新模型”叙事切断；代价是分发行为本身失效，已分发的产物需召回，工程上表现为制品库中一批量化产物的元数据被标记为不可用，下游服务必须回滚到未量化权重，吞吐与显存占用同时恶化。<strong>数据断点</strong>：校准集来源未做个人数据授权核验，量化校准过程接触未授权个人数据，且校准产物随权重一并分发——对应数据许可维度。其机制是污染沿流水线传播：scale 与量化权重都携带了校准集的统计痕迹，删除校准集并不能删除产物中的影响。<strong>部署断点</strong>：NVL72 多租户下 KV cache 与请求日志未按租户隔离与限期删除，跨境传输缺少合法性依据，审计时无法提供留存证据——对应部署合规维度。</p>\n<p>三类断点的共同结构是：<em>合规状态在物料流转的某一跳上丢失，且丢失点没有门禁</em>。因此工程上的通用机制是在每一跳设置可执行的检查，而不是在终点做文档补录。用公式表达门禁的通过条件：</p>\n<div class=\"formula\">$$\n\\text{gate}(m) = \\text{decl}(m) \\wedge \\text{prov}(m) \\wedge \\text{ttl}(m) \\wedge \\text{inherit}(m)\n$$</div>\n<p>其中 <span>decl</span> 为声明与署名齐备，<span>prov</span> 为来源与授权凭证可查，<span>ttl</span> 为留存期限与跨境依据已配置，<span>inherit</span> 为衍生关系已登记。任一为假则该物料不得进入下一跳。这个门禁的代价是流水线增加一次元数据查询与比对，延迟量级远小于一次量化或一次权重加载，属于可接受开销；但若门禁放在分发之后，代价就变成召回与回滚。</p>\n<p>具体例子：一次 NVFP4 量化产物的分发，若制品库元数据中缺少“原许可继承”字段，门禁在第三跳拦截，流水线报错并指向权重许可维度；工程师补登记继承关系与署名后重跑，产物才可分发。这个流程把失败模式从“事后审计发现”转为“分发前阻断”，是本条目在工程上的核心价值。</p>\n\n<h3 id=\"ap-model-data-license-sec-6\">六 · 工程判断：把许可做成可执行的元数据</h3>\n<p>最后落在具体机制上。本条目在推理系统中的落地形态不是一份 PDF，而是<strong>附着在每份物料上的结构化元数据，并在流水线各跳设置门禁</strong>。对 MoE 而言，物料粒度必须细到专家分片与 scale：因为专家并行会把权重切成多份独立流转的分片，若元数据只挂在整模型上，分片一旦单独分发就失去继承信息。工程判断是：元数据的键至少包含物料标识、衍生自何物、适用条款引用、声明与署名、来源凭证、留存与跨境依据、审计地址七项，与速查表七列同构。</p>\n<p>第二个判断关于多租户 NVL72 的运行时残留。KV cache 与日志的隔离不能只靠应用层约定，必须在分配器与日志写入路径上强制租户标签与 TTL，且删除动作要留下可检索的证据。代价是显存复用率与日志写放大，收益是审计时可提供留存证据。材料明确：留存期限、跨境传输白名单等需按适用法规与合同确定，材料未给出具体数值——因此工程上不得在配置中硬编码天数，而应把期限与白名单做成外部可配置项，并在门禁中校验其存在性而非具体值。</p>\n<p>第三个判断关于量化重分发的默认姿态：把任何 NVFP4/FP8 产物视为原权重的衍生作品，默认继承原许可并附声明与署名，除非有明确的条款允许独立分发。这个默认姿态的代价是分发流程多一步声明生成，收益是消除最常见踩坑。校准集侧同理：默认要求每个样本带授权凭证，无凭证样本不得进入校准，代价是校准集规模可能缩小、量化精度略受影响，收益是产物可分发。这两条默认姿态合起来，构成本条目在 MoE 推理工程中的可执行结论。</p>\n<h3 id=\"ap-model-data-license-sec-7\">七 · 速查表的列结构与取值口径</h3>\n<p>速查表的价值在于“照着填”，而不是“读完再想”。因此列的定义必须与合规动作一一对应，而不是与法律条文一一对应。本表固定七列：合规对象、适用许可证/条款、允许与禁止行为、声明与署名义务、数据来源与授权凭证、留存期限与跨境传输限制、审计证据留存位置。前四列回答“能不能做、做完要说什么”，后三列回答“凭什么做、做完留什么”。七列的顺序即填表顺序：先定对象，再定条款，再定行为边界，再定声明，最后落到凭证、期限与证据位置。</p>\n<p>口径上有一条硬约束必须写在表头：<strong>凡是材料未给出具体数值的字段，一律填“按适用法规与合同确定”，不得填估算值。</strong>留存期限、跨境传输白名单、个人数据授权有效期这三类字段在材料中均无具体数值，速查表里必须显式标注为待定项，并注明待定项的裁决来源（合同条款编号或法务出具的合规意见编号），而不是留空。留空的字段在审计时等同于“未核验”，这与“核验后判定为不适用”是两种完全不同的合规状态，速查表必须能区分二者。</p>\n<div class=\"formula\">$$\\text{表项完备度} = \\frac{\\text{已裁决字段数}}{\\text{适用字段总数}},\\quad \\text{待定字段必须携带裁决来源编号}$$</div>\n<p>工程代价上，这张表不是文档而是流水线的一个卡点。以一次 NVFP4 量化重分发为例：量化作业产出权重后，分发流水线在打包阶段读取速查表中“声明与署名义务”列，若该列为空则阻断打包。这个卡点带来的是发布延迟——每次权重版本发布多一次人工裁决往返，量化为分钟级、裁决为小时级，因此实际代价是把发布节奏从“随时可发”变成“按裁决周期发”。对多租户 NVL72 集群，同一张表还要被部署侧引用：KV cache 与日志的留存列直接决定清理任务的保留窗口参数，参数填错即意味着清理任务要么删早了丢审计证据，要么删晚了形成跨租户残留。</p>\n\n<h3 id=\"ap-model-data-license-sec-8\">八 · 权重许可行：商用条款与衍生量化权重</h3>\n<p>权重许可行的核心判断是“量化是否产生新模型”。工程上必须把答案固定为“否”：NVFP4/FP8 量化权重是原权重的衍生分发物，许可证继承，声明义务继承。这一行的“允许与禁止行为”列应写成可执行的两条：允许在继承原许可证条款的前提下分发量化权重；禁止将量化权重作为独立新模型分发而不附原许可证与署名。禁止项必须写明触发条件——即“分发动作发生且未附声明”，而不是“量化动作发生”，因为量化本身在内部部署中不构成分发。</p>\n<p>“声明与署名义务”列需要落到文件级：随权重包一同交付的许可证副本、原模型署名、量化方式说明（精度格式与校准集来源类别）。这三项缺一即视为声明义务未履行。工程代价体现在包体与流水线校验上：每个量化权重包多出许可证与署名的固定开销，校验步骤增加一次哈希比对，分发吞吐的瓶颈从带宽转为校验环节；对大规模权重仓库，这一开销随版本数线性增长。</p>\n<p>具体例子：一个团队把某开源 MoE 权重量化为 NVFP4 后，以“自研高效模型”名义上传到内部模型市场，未附原许可证。速查表在该行的“声明与署名义务”列若已填，打包卡点会直接阻断；若该列为空，则这次分发在审计时被判定为衍生权重分发越界。这里的关键不是事后追责，而是把“是否附声明”变成打包阶段的布尔判断。</p>\n\n<h3 id=\"ap-model-data-license-sec-9\">九 · 校准数据行：来源核验与授权凭证</h3>\n<p>校准数据行的口径必须比权重行更严，因为校准过程会让量化管线“接触”数据，而校准产物（量化参数、可能的统计摘要）会随权重一并分发。该行的“数据来源与授权凭证”列要求逐项登记：校准集来源类别、个人数据授权凭证编号、授权覆盖范围（是否覆盖量化校准这一使用目的）。三项中任何一项缺失，该行即判定为不可用，量化作业不得启动。</p>\n<p>“允许与禁止行为”列写成：允许使用已核验授权凭证的校准集；禁止将含未授权个人数据的校准集投入校准流程，禁止校准产物随权重分发时携带可回溯到个人的统计信息。后者容易被忽略——校准产物通常只是缩放因子与统计量，但若统计粒度细到可关联个体，仍构成个人数据扩散。</p>\n<div class=\"formula\">$$\\text{校准可用} = \\text{来源已登记} \\land \\text{授权凭证有效} \\land \\text{目的覆盖校准}$$</div>\n<p>工程代价是校准管线的启动延迟与数据隔离成本。校准作业在启动前需等待凭证核验，核验为人工环节，因此校准从“随时可跑”变为“凭证就绪才跑”；同时校准数据必须与推理数据物理隔离，隔离带来的存储与访问控制开销是持续的，不随校准结束而释放。具体例子：某校准集来自内部日志，日志中含用户请求文本，授权凭证仅覆盖“服务质量分析”而未覆盖“量化校准”，速查表该行判定不可用，量化作业被阻断——这正是材料所列失败模式中“校准集来源未做个人数据授权核验”的典型形态。</p>\n\n<h3 id=\"ap-model-data-license-sec-10\">十 · 分发许可行：许可证继承与声明义务的落地</h3>\n<p>分发许可行与权重许可行不是重复，而是分工：权重行管“能不能分发”，分发行管“分发时带什么、怎么声明”。该行的“适用许可证/条款”列要求填写原许可证标识与继承条款编号；“声明与署名义务”列要求填写声明载体（许可证文件、模型卡、分发清单）与署名位置。允许行为是“在继承条款下分发并附声明”，禁止行为是“剥离声明后分发”与“以新许可证覆盖原许可证”。</p>\n<p>这一行最容易在工程上被绕过：模型市场或内部制品库的上传接口若只校验文件完整性而不校验声明文件，分发行就形同虚设。因此速查表必须与制品库的准入规则绑定，把“声明文件存在”作为上传的前置条件。工程代价是制品库的元数据膨胀与检索复杂度上升——每个量化版本多出若干声明文件与继承关系记录，版本树的深度增加，回滚与追溯的查询成本随之上升。</p>\n<p>具体例子：同一原权重的三个量化版本（不同精度、不同校准集）在制品库中形成三份声明，若其中一份遗漏署名，速查表的分发行在审计抽样时即暴露缺口。这里的判断落在具体机制上：把声明文件作为制品库的必填元数据字段，而不是附加上传的可选附件，使遗漏在写入阶段即失败，而不是在审计阶段才被发现。</p>\n\n<h3 id=\"ap-model-data-license-sec-11\">十一 · 部署合规行：多租户 KV cache 与日志的留存与跨境</h3>\n<p>部署合规行针对 NVL72 多租户场景，列内容与前四行不同：它不填许可证，而填隔离机制、留存期限与跨境传输限制。“允许与禁止行为”列写成：允许在租户隔离前提下按期限留存 KV cache 与请求日志；禁止跨租户残留与无合法性依据的跨境传输。隔离机制必须具体到实现层——KV cache 按租户分区、日志按租户打标、清理任务按租户维度执行，而不是按节点维度执行，因为按节点清理会在共享节点上留下跨租户残片。</p>\n<p>“留存期限与跨境传输限制”列在材料中无具体数值，填“按适用法规与合同确定”，并登记裁决来源。这一列的工程含义是清理任务的参数来源：留存期限直接映射为清理任务的保留窗口，跨境限制映射为数据传输路径的白名单校验。代价体现在两方面：一是隔离带来的显存与存储开销，KV cache 按租户分区意味着分区边界处的碎片无法被其他租户复用，显存利用率下降；二是清理任务的周期性扫描开销，扫描频率由留存期限决定，期限越短扫描越频繁。</p>\n<div class=\"formula\">$$\\text{清理窗口} = f(\\text{留存期限}),\\quad \\text{跨境放行} = \\text{路径} \\in \\text{白名单}$$</div>\n<p>具体例子：一个 NVL72 集群承载多个租户的推理服务，某租户的请求日志在租户退租后仍留在共享节点的本地盘上，且该节点位于跨境区域，速查表该行若未登记隔离机制与清理窗口，审计时无法提供留存证据——这正是材料所列“KV cache 与请求日志未按租户隔离与限期删除，跨境传输缺少合法性依据”的失败形态。工程判断落在具体机制上：把租户标识写入 KV cache 与日志的元数据，使清理任务可按租户维度精确删除，而不是依赖节点级快照回滚。</p>\n\n<h3 id=\"ap-model-data-license-sec-12\">十二 · 审计证据列与填表纪律</h3>\n<p>最后一列“审计证据留存位置”决定前六列是否可被验证。该列要求填写证据的存放位置与可检索键：许可证副本存放于制品库的哪个路径、授权凭证存放于哪个合规系统、清理任务的执行记录存放于哪个日志系统。关键纪律是证据位置必须与合规对象一一对应，不能出现“所有证据都在一个共享目录”的填法，因为共享目录无法证明某个具体分发动作附带了声明。</p>\n<p>填表纪律还包括版本绑定：速查表的每一行必须绑定到具体的权重版本、校准集版本与部署配置版本，而不是绑定到“模型名称”。绑定到名称会导致版本迭代后表项失效而无人察觉。工程代价是表的维护成本随版本数增长，但这一成本换来的是审计时的可追溯性——每个分发动作都能回溯到当时生效的表项与证据位置。</p>\n<p>具体例子：审计抽样一次 NVFP4 分发，需要回答三个问题——原许可证是什么、校准集授权凭证编号是什么、该版本权重的声明文件在哪里。若速查表按版本绑定，三个问题各有一行可查；若按模型名称绑定，则只能给出“当前版本”的答案，历史版本的分发动作无法举证。这里的工程判断是：把速查表当作制品库的元数据表而非独立文档，使表项与制品版本同生命周期，版本删除时表项随之归档而非删除。</p>\n<h3 id=\"ap-model-data-license-sec-13\">十三 · 阈值不是常数，是合同与法规的函数</h3>\n<p>在许可条目里谈“工程阈值”，最容易犯的错是把阈值当成一个可以抄下来的数。留存期限、跨境传输白名单、个人数据授权核验的深度，这三类阈值在材料里明确没有给出具体数值，它们由适用法规与合同条款共同决定。因此本部分给出的不是一张可以直接贴进配置文件的数字表，而是一套“把外部约束翻译成可执行参数”的方法：每个阈值都必须能追溯到一条许可证条款或一份授权凭证，否则它就不是阈值，只是猜测。</p>\n<p>工程上把这套翻译写成三元组 <span class=\"formula\">$$T = (s, u, e)$$</span>，其中 <span class=\"formula\">$$s$$</span> 是约束来源（许可证条款、合同、适用法规），<span class=\"formula\">$$u$$</span> 是计量单位（天、字节、租户、跨境目的地），<span class=\"formula\">$$e$$</span> 是审计证据的落盘位置。任何进入部署配置的阈值若缺少 <span class=\"formula\">$$s$$</span> 或 <span class=\"formula\">$$e$$</span>，就应当在发布前被拦下。这条规则本身就是最值得固化的“经验数字”：三元组完整率应当作为发布门禁的一项，而不是事后审计的补救项。</p>\n<p>代价体现在发布流程上：每新增一个租户或一条跨境链路，都要重新核对 <span class=\"formula\">$$s$$</span>，这会把容量规划从纯性能问题变成合规问题。以 NVL72 多租户部署为例，一个机架内多个租户共享 KV cache 与请求日志的物理介质，留存期限一旦按租户分别设定，清理任务就必须带租户标签执行，否则跨租户残留直接构成合规缺口。</p>\n\n<h3 id=\"ap-model-data-license-sec-14\">十四 · 权重许可的阈值：衍生量化权重的继承判定</h3>\n<p>权重侧最关键的判定不是“能不能商用”，而是“量化后的权重是不是原模型的衍生作品”。材料给出的踩坑正是把 NVFP4/FP8 量化权重当作新模型独立分发，忽略原许可证继承与声明义务。工程上需要一个可判定的继承规则，而不是凭感觉。建议用一条保守判定式：若量化过程使用了原权重的任何参数值（哪怕只用于校准统计），则衍生权重继承原许可；只有当量化完全基于独立获得的、许可允许的数据且不接触原权重时，才可能脱离继承。这条规则把“是否接触原权重”作为唯一判据，避免在“量化是否构成创作”上纠缠。</p>\n<p>落地为发布检查清单时，每一项都要有证据位置：原许可证文本、衍生声明文本、署名清单、分发渠道的声明落点。代价是分发体积与流程延迟——每个量化变体都要携带声明与署名，模型仓库的元数据从“一个权重文件”膨胀为“权重 + 许可 + 声明 + 署名”的四件套；在连续批处理的高频发布节奏下，这套元数据若没有自动化校验，会成为发布流水线的串行瓶颈。</p>\n<p>具体例子：一个团队把 FP8 量化权重上传到内部模型仓库供多个推理服务引用，若仓库只校验文件哈希而不校验声明文件的存在性，衍生权重就会在没有署名的情况下被下游服务加载并对外提供。修复方式不是事后补声明，而是在仓库入口加一条硬规则：缺少继承声明与署名的量化权重拒绝入库。</p>\n\n<h3 id=\"ap-model-data-license-sec-15\">十五 · 校准集的授权核验：测什么、怎么测</h3>\n<p>校准集的风险不在体积，而在来源。材料指出校准集不得含未授权个人数据，且校准产物会随权重一并分发。这意味着核验必须覆盖两个对象：输入校准样本，以及量化过程产生的统计量（缩放因子、激活范围等）。后者常被忽略——统计量本身可能携带可追溯到个体样本的信息，尤其在样本量小、分布窄的校准集上。</p>\n<p>测量方法应当是可复现的流程而非一次性人工审查：对每个校准样本记录来源凭证（授权类型、获取渠道、授权范围），对校准产物记录其依赖的样本集合标识。伪代码思路是给校准管线加一个前置断言：</p>\n<div class=\"formula\">$$\\text{assert}\\ \\forall x \\in D_{cal}:\\ \\text{provenance}(x) \\neq \\varnothing \\ \\land\\ \\text{scope}(x) \\supseteq \\text{quantize}$$</div>\n<p>即每个校准样本必须有来源凭证，且其授权范围覆盖量化用途。代价是校准吞吐：加入凭证校验后，校准数据加载从纯 I/O 变成 I/O 加元数据查询，校准阶段的时间会上升；对需要频繁重校准的 MoE 模型（路由分布漂移后重校准），这会拉长量化迭代周期。工程判断是把凭证校验做成离线批处理并缓存结果，而不是在每次校准运行时逐样本查询。</p>\n<p>具体例子：校准集里混入了一批来源不明的对话日志，量化后统计量被写入权重元数据并随权重分发。审计时无法证明这些日志的授权范围覆盖量化用途，整个量化变体的分发合法性就失去依据。可测的指标是“凭证覆盖率”，即带完整来源凭证的校准样本占比，它应当作为量化发布的前置条件而非事后统计。</p>\n\n<h3 id=\"ap-model-data-license-sec-16\">十六 · 多租户下的 KV cache 与日志：留存与隔离的可测边界</h3>\n<p>NVL72 多租户部署把合规问题推到显存与存储层。KV cache 在推理过程中承载请求上下文，请求日志承载调用记录，两者都可能在租户之间共享物理介质。材料给出的失败模式是 KV cache 与请求日志未按租户隔离与限期删除，跨境传输缺少合法性依据，审计时无法提供留存证据。这里的工程阈值不是“保留多少天”，而是“隔离是否可验证、删除是否可证明”。</p>\n<p>可测的机制有三层。第一层是标签：KV cache 的分配单元与日志记录都携带租户标识，任何跨租户读取都触发拒绝。第二层是期限：每个租户的留存期限作为配置项，清理任务按标签扫描并记录删除事件。第三层是跨境：日志与缓存的落盘位置与传输目的地必须与租户合同中的跨境条款一致，传输前校验目的地是否在允许集合内。三层都可写成断言，代价是显存与带宽开销——标签使 KV cache 的元数据变大，按租户清理会增加存储扫描的 I/O，跨境校验在日志外发路径上引入一次查表延迟。</p>\n<p>具体例子：一个 NVL72 机架同时服务两个租户，租户 A 的合同禁止数据跨境，租户 B 允许。若日志外发管线不按租户查表，A 的请求日志会被发往境外存储，形成合规缺口且审计时无留存证据可查。可测指标是“隔离违规计数”与“删除事件覆盖率”：前者应为零，后者应覆盖全部到期租户数据。这两个指标比任何留存天数都更能反映部署是否合规。</p>\n\n<h3 id=\"ap-model-data-license-sec-17\">十七 · 审计证据的落盘：把阈值变成可查的记录</h3>\n<p>所有阈值的最终形态是审计证据。材料强调审计时无法提供留存证据是典型失败，因此证据落盘位置必须与阈值三元组中的 <span class=\"formula\">$$e$$</span> 绑定。证据至少包括：许可证文本与版本、衍生声明与署名、校准集来源凭证与凭证覆盖率、租户隔离配置与删除事件日志、跨境传输的目的地与合法性依据。每项证据都应有不可篡改的落点与可检索的索引。</p>\n<p>代价是存储与查询开销：证据留存本身占用存储，且审计查询要求索引可用，这与推理系统追求的低延迟高吞吐形成资源竞争。工程判断是把证据存储放在与推理负载隔离的介质上，避免审计查询影响在线服务的显存与带宽。具体例子：把删除事件日志写入独立于推理集群的审计存储，推理侧只上报事件标识，审计侧按标识拉取详情，这样在线路径只增加一次轻量上报，不承担证据存储的容量压力。</p>\n<p>测量方法上，证据完整性可以用“可追溯率”度量：随机抽取若干分发变体与租户数据，检查其证据链是否完整闭合。这个比率应当作为发布与运营的常规指标，而不是审计前的临时盘点。当可追溯率低于发布门禁设定的门槛时，分发应当被阻断——这是本部分唯一可以固化为“经验数字”的工程判断：门槛由合同与法规确定，但阻断动作必须是自动的。</p>\n\n<h3 id=\"ap-model-data-license-sec-18\">十八 · 合规阈值的可测量化：从“没有数字”到可审计的工程判据</h3>\n<p>材料没有给出留存期限、跨境白名单这类具体数值，这不是缺陷而是事实边界：这些阈值由适用法规与合同逐案确定，工程侧的任务不是猜数字，而是把每个待定阈值变成可配置、可测量、可留证的参数。落地做法是三条硬性判据。其一，<strong>许可证继承闭包</strong>：对每个量化产物建立从基座权重到 NVFP4/FP8 衍生权重的许可链，链上任一节点缺失声明或署名即判定为不可分发，这条判据是布尔值而非百分比，失效即阻断。其二，<strong>校准集授权凭证覆盖率</strong>：要求进入校准流程的每条样本都挂接来源与授权凭证，覆盖率必须为 100%，任何未挂接样本在数据加载层直接拒绝，而不是事后抽查。其三，<strong>租户数据生命周期</strong>：KV cache 与请求日志按 tenant_id 打标，删除动作以“租户维度的残留计数”为度量，目标值为零。三者共同构成发布门禁，任一不满足则量化权重不得进入分发流水线。</p>\n<p>测量方法必须落在推理栈的具体位置上，否则合规判据无法执行。许可链检查放在权重导出阶段：量化脚本读取基座模型的许可证元数据，写入衍生权重的 manifest，并在 CI 中比对声明字段与署名义务字段是否齐全，缺失即 fail。校准集核验放在数据管线入口：对每条样本记录来源标识与授权凭证哈希，形成可复核的清单，量化过程只接受清单内样本，产物 manifest 中固化该清单摘要，使“校准产物随权重分发”这一路径可追溯。租户隔离的测量则放在服务层：以 tenant_id 为键统计 KV cache 块与日志条目的存活数量，删除任务执行后复查残留计数；跨境传输则记录每次数据出境的目的地、法律依据标识与时间戳，形成可导出的审计证据。这些测量的代价是明确的系统开销——许可链与清单核验发生在离线导出与数据准备阶段，不进入在线关键路径；而租户残留计数与出境记录写入位于请求路径旁路，按批次聚合写入，避免逐请求同步落盘拖高尾延迟。</p>\n<p>失效条件集中在三个耦合点。第一，量化重分发被当作“新模型”独立发布，manifest 未继承原许可条款与署名，此时许可链闭包判据为假，分发即越界；这一失效不依赖任何数值阈值，属于结构性错误。第二，校准集混入未授权个人数据，覆盖率判据虽可通过（因为凭证字段被填了无效值），但凭证核验环节必须校验凭证本身的合法性而非仅校验字段存在，否则度量被架空。第三，NVL72 多租户下 KV cache 与日志跨租户残留并跨境传输：残留计数目标为零但删除任务与推理调度存在时序竞争，若删除依赖空闲窗口而租户持续有流量，残留会长期非零；此时应以租户下线事件为触发点强制驱逐，而不是等待自然过期。系统代价上，强制驱逐会造成该租户会话的 KV 复用失效，等价于一次预填重算，抬高了该租户的 TTFT；跨境传输的合法性依据缺失则直接阻断出境路径，表现为跨区推理请求被拒绝或降级到本地副本，牺牲的是跨区负载均衡带来的吞吐弹性。</p>\n<div class=\"formula\">$$ \\text{gate} = \\big[\\text{lic\\_chain\\_closed}\\big] \\wedge \\big[\\text{calib\\_cred\\_valid} = 1.0\\big] \\wedge \\big[\\text{residual}(t) = 0\\big] $$</div>\n<table class=\"mini\"><thead><tr><th>判据</th><th>测量位置</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>许可链闭包</td><td>权重导出/CI</td><td>衍生权重缺声明与署名</td><td>阻断分发，无在线开销</td></tr><tr><td>校准凭证合法性</td><td>数据管线入口</td><td>未授权个人数据进入校准</td><td>离线返工，产物需重做</td></tr><tr><td>租户残留计数</td><td>服务层旁路</td><td>KV/日志跨租户残留</td><td>强制驱逐致 TTFT 上升</td></tr></tbody></table>\n<h3 id=\"ap-model-data-license-sec-19\">十九 · 量化重分发：许可证继承的三处断点</h3>\n<p>踩坑最密集的地方不在训练侧，而在量化产物出门的那一刻。把 BF16 权重压成 NVFP4/FP8 之后，工程团队往往把它当成“我们自己造的新模型”独立分发，这是许可链条断裂的第一处断点。原权重许可证的商用条款、署名义务、衍生作品声明义务并不因为数值精度改变而消失——量化权重是衍生作品，许可证继承是默认状态，除非原条款明确允许以另一许可证重分发。</p>\n<p>第二处断点在声明文件。分发包里通常只有 <code>config.json</code>、权重分片和 tokenizer，许可证文本与署名清单被留在内部仓库。接收方拿到的是一个无法追溯来源的二进制集合。第三处断点在量化脚本本身：校准数据来源、量化算法版本、原始权重 commit 都没有写进产物元数据，审计时无法证明“这份 NVFP4 权重确实来自那份许可允许商用的基座”。</p>\n<p>检查顺序应当是反向的：先看分发产物里有没有许可证文本与署名清单，再看产物元数据能否回指原始权重与校准集，最后才看量化流程本身。工程代价上，这一层几乎不占延迟与显存，但它决定了一次分发是否可回滚——一旦发现许可证继承缺失，需要召回已分发的权重并重新打包，代价是整条分发链的停摆，而不是某个 kernel 的调优。</p>\n<div class=\"formula\">$$ \\text{可分发} = \\text{原许可允许衍生} \\wedge \\text{继承声明完整} \\wedge \\text{校准集授权可证} $$</div>\n<p>具体例子：某团队把基座权重量化成 FP8 后上传到内部模型仓库供三条业务线拉取，产物里没有原许可证副本。三个月后其中一条业务线对外提供服务，审计要求出示商用授权链，团队只能回溯到原始权重仓库，却发现量化脚本的校准集路径指向一份来源不明的内部语料——两个断点同时暴露，召回范围从一条业务线扩大到全部三条。</p>\n\n<h3 id=\"ap-model-data-license-sec-20\">二十 · 校准集：个人数据授权核验的前置卡点</h3>\n<p>校准集是量化流程里唯一“必须接触真实数据”的环节，也是个人数据合规最容易失守的环节。校准过程本身不产生持久化的推理日志，但校准产物——激活缩放因子、量化阈值、可能的校准统计量——会随权重一并分发。如果校准集混入了未授权个人数据，那么合规缺口不在校准那一刻，而在产物出门之后。</p>\n<p>前置卡点的做法是把授权核验放在校准任务提交之前，而不是之后。流水线应当要求每次校准运行携带数据来源凭证：语料标识、授权依据、采集范围、是否含个人数据、脱敏方式。没有凭证的校准任务直接拒绝调度。这一步的工程代价是流水线多一次元数据查询，延迟在秒级，但它把“事后追溯”变成“事前阻断”。</p>\n<p>伪代码思路：校准任务提交时校验 <code>dataset_license_ref</code> 是否存在且未过期；校验失败则任务进入隔离队列而非直接失败，保留样本供合规复核；校验通过才允许读取校准分片。注意校准分片应当按需拉取、用完即释放，不在量化节点上留下完整语料副本——这既是数据最小化，也减少了节点被多租户共享时的残留风险。</p>\n<p>具体例子：某量化流水线为 MoE 模型做 FP8 校准，校准集来自一份内部工单语料。凭证核验发现该语料授权范围仅限“内部质量分析”，不含“模型量化与分发”。任务被阻断，团队改用已获授权的合成校准集重跑——合成集不含个人数据，产物可以随权重分发，代价是校准分布偏移带来的精度损失需要重新评估，这属于精度问题而非合规问题，两者不能混为一谈。</p>\n\n<h3 id=\"ap-model-data-license-sec-21\">二十一 · NVL72 多租户：KV cache 与日志的残留面</h3>\n<p>NVL72 机柜级部署把 72 个 GPU 放进一个 NVLink 域，多租户共享同一批 GPU 与同一套高速互连是常态。合规缺口不在计算隔离，而在状态残留：KV cache 在请求结束后并不总是立即释放，连续批处理会把不同租户的序列拼进同一块显存池；请求日志、路由决策记录、token 级 trace 落在节点本地盘或集中日志系统里，留存期限与删除动作往往没有按租户区分。</p>\n<p>残留面的三个具体位置：一是 KV cache 块复用，块释放后未清零就被下一个租户的请求占用，跨租户数据在显存里短暂共存；二是前缀缓存（prefix cache）跨请求命中，若缓存键未绑定租户身份，租户 A 的提示前缀可能被租户 B 复用；三是日志管道的默认留存策略是全局的，没有租户维度的 TTL。这三处都不影响吞吐，但每一处都是审计时的证据缺口。</p>\n<p>工程代价要算清楚：按租户绑定缓存键会让前缀命中率下降，命中率下降直接转化为预填算力的增加；KV 块释放时清零会增加显存写带宽占用；租户级日志 TTL 需要日志系统支持按标签分区删除，存储成本上升。这些代价必须与合规要求一起进入容量规划，而不是部署完再补。</p>\n<p>具体例子：一个 NVL72 多租户推理服务为三家客户共享前缀缓存以提升命中率，缓存键只含提示哈希、不含租户标识。审计发现某客户的提示前缀在另一客户的请求中被命中复用，虽然输出未泄漏，但“跨租户数据接触”本身已构成缺口。修复方案是缓存键加入租户命名空间，命中率下降带来的预填开销被计入 SLO 预算，而不是悄悄牺牲隔离性。</p>\n\n<h3 id=\"ap-model-data-license-sec-22\">二十二 · 跨境传输：合法性依据与留存证据的绑定</h3>\n<p>跨境传输的坑在于把“传输”理解得太窄。在多租户 NVL72 部署里，跨境的不只是权重文件，还包括 KV cache 的持久化快照、请求日志、审计 trace、以及校准产物。每一类数据的合法性依据可能不同：权重依赖许可证条款，日志依赖合同与适用法规，个人数据依赖单独的传输机制。材料未给出具体白名单与留存期限数值，这些必须按适用法规与合同逐项确定，不能套用默认值。</p>\n<p>检查顺序上，先建立数据分类清单，把每一类持久化对象映射到传输路径与合法性依据，再检查传输链路上是否有未声明的副本——例如日志系统在另一区域做了灾备复制，这条复制路径往往不在最初的合规设计里。留存证据的要求是：能证明数据在何时、从何处、传往何处、依据什么。审计时拿不出这条证据链，等同于没有合法性依据。</p>\n<p>具体例子：某部署把请求日志集中到主区域日志系统，灾备策略自动复制到第二区域。合规评审时发现第二区域不在合同允许的传输范围内，且日志中含租户标识。修复不是关掉灾备，而是把日志按租户分区、对不允许跨境的租户关闭复制，并在日志元数据里记录传输依据标识，使每条留存记录都能回指合法性来源。</p>\n\n<h3 id=\"ap-model-data-license-sec-23\">二十三 · 回滚方案：许可证缺口的分级处置</h3>\n<p>回滚不是“撤回文件”这么简单。许可证缺口按影响面分级：产物级缺口（分发包缺声明）、数据级缺口（校准集授权不足）、部署级缺口（跨租户残留或跨境无依据）。三级的回滚动作完全不同，混在一起处置会导致过度召回或召回不足。</p>\n<p>产物级回滚最快：冻结分发、补声明与署名、重新打包、通知接收方替换。数据级回滚需要重跑量化：撤回受影响的量化权重，用合规校准集重新校准，重新评估精度并重新分发——代价是整条量化流水线的重跑时间，以及精度重验的算力。部署级回滚最重：需要按租户清理 KV cache 与日志、修补缓存键、调整传输路径，且清理动作本身要留下证据，否则回滚后仍然无法通过审计。</p>\n<table class=\"mini\"><thead><tr><th>缺口级别</th><th>回滚动作</th><th>主要代价</th><th>证据留存</th></tr></thead><tbody><tr><td>产物级</td><td>冻结分发、补声明、重打包</td><td>分发链停摆</td><td>新旧产物对照清单</td></tr><tr><td>数据级</td><td>撤回量化权重、换校准集重跑</td><td>量化流水线重跑与精度重验</td><td>校准凭证与重跑记录</td></tr><tr><td>部署级</td><td>按租户清理缓存与日志、修缓存键与传输路径</td><td>命中率下降、存储与带宽开销</td><td>清理动作日志与传输依据标识</td></tr></tbody></table>\n<p>回滚方案的关键设计是把“可回滚”做进产物本身：量化产物携带原始权重 commit、校准集凭证标识、许可证副本；部署侧按租户打标签，使清理动作可以精确到租户而不是整机柜。这样缺口被发现时，回滚范围由元数据决定，而不是由人工排查决定。检查清单的最后一格应当是：这次分发或这次部署，如果明天被要求回滚，能否在一小时内说清回滚边界——说不清，就是清单没走完。</p>\n\n<h3 id=\"ap-model-data-license-sec-24\">二十四 · 量化重分发与多租户残留：三条失效链的检查顺序</h3>\n<p>合规条目失效极少是单点错误，而是三条链各自断裂后叠加：<strong>权重链</strong>（原许可→量化衍生→分发声明）、<strong>数据链</strong>（校准集来源→个人数据授权→校准产物随权重流出）、<strong>部署链</strong>（租户隔离→留存期限→跨境合法性）。检查顺序必须与不可逆性对齐：先查数据链，因为校准一旦执行，未授权个人数据已进入量化统计量（scale、amax 等），删除校准集也无法回溯；再查权重链，量化产物在分发前可补救（补声明、补署名、改许可文件）；最后查部署链，KV cache 与日志的残留可在运行期按租户标签清理。反过来先查部署链，往往在权重已分发、校准产物已随包流出后才发现上游缺口，回滚成本最高。</p>\n<p>权重链的判定可写成一条继承闭包条件：设原权重许可条款集为 <span class=\"formula\">$$L_0$$</span>，量化变换 <span class=\"formula\">$$Q$$</span> 产生的 NVFP4/FP8 产物条款集为 <span class=\"formula\">$$L_1$$</span>，则必须满足 <span class=\"formula\">$$L_1 \\supseteq L_0 \\setminus \\{\\text{仅适用于原始精度权重的条款}\\}$$</span>，且分发包内声明与署名义务不得少于原许可要求。工程上把这条检查做成 CI 门禁：量化流水线输出权重时，同时输出一份许可清单（原许可标识、衍生声明、署名文本、校准集来源凭证哈希），缺任一项则阻断打包。代价是每次量化重分发多一次人工复核与清单生成，属于吞吐上的固定开销，但避免了整批权重召回。</p>\n<p>部署链的残留判定按租户维度计算：对租户 <span class=\"formula\">$$t$$</span> 的 KV cache 块与请求日志，其存活时间必须满足 <span class=\"formula\">$$T_{\\text{live}}(t) \\le D_{\\text{retain}}(t)$$</span>，且跨租户可见性为零。NVL72 多租户下真正的坑在于块级复用：KV cache 按 token 块分配，租户切换时若只清指针不清块内容，残留会跨租户出现；日志侧则是请求元数据与提示词片段混存。检查清单应落到可审计证据上——每租户的删除任务执行记录、跨境传输的合法性依据文件、审计证据留存位置，三者缺一即视为部署链断裂。回滚方案按链分层：数据链断裂只能停止分发并重做校准；权重链断裂可补发声明包；部署链断裂靠租户标签清理任务与留存期限策略回补，代价是短时吞吐下降与缓存重建延迟。</p>\n<table class=\"mini\"><thead><tr><th>失效链</th><th>检查时点</th><th>回滚动作</th><th>系统代价</th></tr></thead><tbody><tr><td>数据链（校准集含未授权个人数据）</td><td>量化执行前</td><td>停止分发、重做校准</td><td>整批量化重跑，吞吐归零一段</td></tr><tr><td>权重链（未继承许可与声明）</td><td>打包分发前</td><td>补声明包、改许可文件</td><td>分发延迟，无算力代价</td></tr><tr><td>部署链（KV cache/日志跨租户残留）</td><td>运行期与审计前</td><td>按租户标签清理、补跨境依据</td><td>缓存重建延迟、短时吞吐下降</td></tr></tbody></table>\n<h3 id=\"ap-model-data-license-sec-25\">二十五 · 上游依赖：许可条目从哪些条目取输入</h3>\n<p>《模型与数据许可》在全书里不是孤立的一节，它是一条横切条目：本身不产出性能数字，却对若干条目的产物施加约束。要判断它的上游依赖，先看它需要从别处拿什么输入。第一类输入是<strong>权重谱系</strong>——基座权重的原始许可证、是否允许商用、是否要求衍生作品继承条款。这决定了量化产物是不是“新模型”。第二类输入是<strong>校准集的来源凭证</strong>——校准数据管线条目产出的是“一批用于统计激活分布的样本”，而许可条目要追问的是这批样本的个人数据授权状态与再分发许可。第三类输入是<strong>部署拓扑</strong>——NVL72 多租户切分方式、租户边界落在哪个粒度（整机柜、单 GPU、单 MIG 实例）、KV cache 与请求日志的物理落点。第四类输入是<strong>分发形态</strong>——权重是以原始精度、FP8 还是 NVFP4 形式交付，是否附带量化配置与校准产物。</p>\n<p>这四类输入里，前三类分别由量化校准数据管线、MoE 推理框架选型与容量规划、分离式预填解码与多租户部署相关条目提供。许可条目的职责是把这些技术产物翻译成合规对象：一份 NVFP4 权重文件不只是“量化结果”，它同时是“原许可证的衍生作品”；一份校准集不只是“统计样本”，它同时是“可能含个人数据的处理记录”；一段 KV cache 不只是“显存占用”，它同时是“租户数据的驻留副本”。这个翻译动作是上游依赖的核心——没有技术条目提供的谱系与拓扑信息，许可条目无法判定边界。</p>\n<p>代价体现在工程侧：为了给许可条目提供可审计的谱系，量化管线必须额外记录校准集来源、样本授权凭证、量化配置与基座权重版本，这些元数据会随权重分发，增加分发体积与校验开销；在多租户 NVL72 上，租户边界若切在整机柜粒度，KV cache 隔离成本低但资源利用率差，切在单 GPU 粒度则需要在 KV cache 分配器里打租户标签，增加元数据管理与淘汰逻辑的复杂度。一个具体例子：同一基座权重派生出 FP8 与 NVFP4 两套量化权重，若两套都对外分发，则各自都要携带基座许可证副本与声明文件，元数据体积随分发份数线性增长，而不是共享一份。</p>\n\n<h3 id=\"ap-model-data-license-sec-26\">二十六 · 下游影响：许可判定如何改变推理系统的实现</h3>\n<p>许可条目对下游的影响不是“加一份法律声明”这么轻。它直接改写三个子系统的实现约束。其一是<strong>量化重分发链路</strong>：当判定量化权重继承原许可时，分发产物必须包含许可证副本、署名声明、以及“本权重为衍生量化作品”的标注；若原许可禁止再分发衍生权重，则量化产物只能内部使用，不能进入对外模型仓库。这会让量化流水线的输出格式从“纯权重文件”变成“权重+元数据包”，加载器需要校验元数据完整性。其二是<strong>校准数据管线的准入检查</strong>：校准集在进入量化流程前必须做来源核验，未授权个人数据不得进入校准；这条约束会改变校准管线的采样策略——从“随机采样激活”变成“先过滤再采样”，过滤环节引入额外的一次数据扫描，代价是校准准备阶段的吞吐下降与存储翻倍（原始集与过滤后集并存）。其三是<strong>多租户 KV cache 与日志的留存策略</strong>：许可条目要求按租户隔离并限期删除，跨境传输需有合法性依据。落到实现上，KV cache 分配器要支持按租户打标与按租户批量回收，请求日志要带租户标识与时间戳以便到期清理，跨区域部署时还要在路由层判断请求是否允许落到境外节点。</p>\n<div class=\"formula\">$$T_{\\text{retain}} = \\min\\bigl(T_{\\text{contract}},\\ T_{\\text{statutory}}\\bigr),\\quad \\text{evict}(kv, log)\\ \\text{when}\\ t - t_0 &gt; T_{\\text{retain}}$$</div>\n<p>这条公式表达的是留存期限取合同约定与法定要求中较短者，到期即触发 KV cache 与日志的淘汰。工程代价分三块：延迟侧，租户标签校验与跨境路由判断在请求入口增加一次查表，属于微秒级但不可忽略的固定开销；吞吐侧，按租户批量回收 KV cache 会打断连续批处理的平滑性，回收窗口内有效批大小下降；显存侧，限期删除意味着不能无限缓存历史 KV，长会话需要重新预填，抬高了首 token 延迟。一个具体例子：NVL72 上一个机柜切给两个租户，租户 A 的请求日志若因路由配置错误落到租户 B 的存储卷，审计时即构成跨租户残留；修复方式是在日志写入路径上强制携带租户 ID 并在存储层做前缀隔离，代价是写入路径多一次前缀拼接与校验。</p>\n\n<h3 id=\"ap-model-data-license-sec-27\">二十七 · 与量化条目的接口：许可继承判定发生在哪一步</h3>\n<p>许可条目与 NVFP4/FP8 权重激活、量化校准数据管线、量化后路由漂移这几个条目的接口，集中在“量化产物是不是新模型”这一判定上。判定发生在量化流水线的<strong>产物封装阶段</strong>，而不是量化计算阶段。量化计算只关心数值：缩放因子、块粒度、激活截断；产物封装才决定许可证继承。接口的具体形态是一张判定表：输入是基座许可证类型、量化是否改变模型结构（MoE 路由是否被改写）、是否附带校准产物；输出是“继承原许可并附声明”或“禁止对外分发”。</p>\n<p>这张判定表对下游的直接影响是：量化后路由漂移条目讨论的是数值层面的路由分布变化，而许可条目讨论的是“路由被改写后是否仍算同一模型”。若量化过程只改精度不改路由逻辑，通常视为衍生作品而非新模型，继承原许可；若量化伴随专家裁剪或路由重训，则可能构成新模型，需要重新评估许可。这个区分决定了分发时的声明义务强度。代价在于：为了支撑判定，量化流水线必须保留“是否改动路由”的标志位与校准集指纹，这些标志位进入权重元数据，加载器在加载 NVFP4 权重时要读取并校验，增加一次元数据解析。一个具体例子：同一 MoE 基座导出 FP8 权重时保留全部专家与路由，导出 NVFP4 权重时为压缩显存裁掉低频专家，后者在许可判定上需要单独出具“结构变更说明”，否则分发时无法证明其与原模型的关系。</p>\n\n<h3 id=\"ap-model-data-license-sec-28\">二十八 · 与部署条目的接口：多租户边界决定合规粒度</h3>\n<p>许可条目与分离式预填解码、容量规划、MoE 场景 KV 压缩、路由倾斜尾延迟这些条目的接口，落在“租户边界画在哪里”。分离式预填解码把预填与解码拆到不同节点，KV cache 在节点间传输，这使 KV cache 的物理落点跨越多台机器，租户隔离不再是单机内的显存分区，而是跨节点的数据流隔离。容量规划条目决定每个租户分到多少 GPU 与多少 KV 预算，而许可条目要求这个预算对应的存储与日志必须可限期删除。MoE 场景 KV 压缩条目降低 KV 占用，间接降低留存成本，但压缩后的 KV 仍是租户数据，删除义务不因压缩而消失。</p>\n<p>接口的机制是<strong>租户标签随 KV 与日志全程传播</strong>：预填节点写入 KV 时打标签，传输层携带标签，解码节点按标签分配与回收，日志写入按标签分卷。这条链路任何一环丢标签，就产生跨租户残留风险。代价是可观测的：标签传播增加每次 KV 传输的元数据字节，跨节点传输带宽中被元数据占用的比例随标签字段长度上升；按标签分卷的日志存储在租户数量多时产生大量小文件，存储元数据开销上升。一个具体例子：NVL72 机柜内 NVLink 5 域上做分离式预填解码，预填节点与解码节点同属一个租户时标签校验可简化，但一旦机柜被切分给多租户，跨节点 KV 传输必须逐次校验标签，校验失败即拒绝传输并记录审计事件。</p>\n<table class=\"mini\"><thead><tr><th>上游条目</th><th>提供给许可条目的输入</th><th>许可条目回压的约束</th><th>代价落点</th></tr></thead><tbody><tr><td>量化校准数据管线</td><td>校准集来源与授权凭证</td><td>未授权个人数据不得进入校准</td><td>校准准备吞吐、存储翻倍</td></tr><tr><td>NVFP4/FP8 权重激活</td><td>量化配置与结构变更标志</td><td>衍生权重继承原许可并附声明</td><td>元数据体积、加载校验</td></tr><tr><td>分离式预填解码</td><td>KV 跨节点落点</td><td>租户标签全程传播、限期删除</td><td>传输元数据开销、回收打断批处理</td></tr><tr><td>容量规划</td><td>租户资源切分粒度</td><td>留存期限与跨境路由约束</td><td>入口查表延迟、长会话重预填</td></tr></tbody></table>\n\n<h3 id=\"ap-model-data-license-sec-29\">二十九 · 在全书中的位置：横切约束而非性能条目</h3>\n<p>把许可条目放回全书结构看，它属于“约束层”而不是“优化层”。优化层条目回答“怎么更快更省”：tcgen05 与 TMEM 决定 MMA 吞吐，NVFP4 决定显存与带宽，连续批处理决定吞吐，投机解码决定尾延迟。约束层条目回答“哪些做法不能做、做了要留什么证据”。许可条目与 SLO 与容量规划同属约束层，但方向不同：SLO 约束的是性能下限，许可约束的是数据与权重的使用边界。两者的交汇点在多租户部署——SLO 要求租户间性能隔离，许可要求租户间数据隔离，隔离手段（分区、标签、限期删除）会同时消耗资源与增加路径开销，容量规划必须把这份开销计入预算。</p>\n<p>它在全书中的位置还体现在<strong>审计证据链</strong>上：性能条目产出的是吞吐、延迟、显存曲线；许可条目产出的是可审计的证据——权重谱系记录、校准集授权凭证、租户标签日志、删除时间戳。这些证据不参与推理计算，但在合规审计时是唯一能证明“没有越界”的材料。工程判断在于：证据链的采集点必须嵌在推理路径里，而不是事后补录；事后补录无法证明 KV cache 与日志在驻留期间的实际归属。代价是推理系统要常驻一份审计元数据存储，其容量随租户数与留存期限增长，属于必须提前计入的固定成本。一个具体例子：MoE 推理框架选型时，若框架不支持按租户打标的 KV 分配器与日志分卷，则许可条目的留存与隔离要求无法落地，选型阶段就应把这一项作为硬性筛选条件，而不是部署后再打补丁。</p>\n<p>最终落在具体机制上：许可条目的工程实现是一张随权重分发的元数据包加一条随 KV 与日志传播的租户标签链。元数据包决定权重能不能出门，标签链决定数据能不能留下。两者都不提升推理速度，但缺任何一环，前面所有性能优化都建立在无法审计的基础上。</p>\n<table class=\"mini\" data-fig=\"app-t-ap-model-data-license\"><caption>速查：这一条怎么用</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>范围</td><td>说明 MoE 权重与校准数据的许可边界：开源权重商用条款、校准集不得含未授权个人数据、量化重分发时的许可证继承…</td></tr><tr><td>关键点</td><td>见正文</td></tr><tr><td>用法</td><td>见正文</td></tr><tr><td>边界</td><td>见正文</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：appendix/ap-model-data-license · 共 5 个片段</p>\n"}];})();
